def _is_abstract_or_self_referential_next_dev_slice_goal(goal: str) -> bool:
    normalized_goal = _normalize_text(goal, default="").lower()
    if not normalized_goal:
        return True
    if "next-local-codex-prompt" in normalized_goal:
        return True
    if "generate next local codex implementation prompt" in normalized_goal:
        return True
    if "from next_dev_slice" in normalized_goal:
        return True
    if "prompt generation" in normalized_goal and "codex implementation prompt" in normalized_goal:
        return True
    return False


def _build_concrete_prompt298_goal_from_next_dev_slice(goal: str) -> str:
    default_goal = (
        "Implement bounded local Codex implementation execution readiness metadata from "
        "`next_codex_prompt` artifacts without invoking Codex."
    )
    normalized_goal = _normalize_text(goal, default="")
    if _is_abstract_or_self_referential_next_dev_slice_goal(normalized_goal):
        return default_goal
    lowered = normalized_goal.lower()
    if "local codex" in lowered and "execution readiness" in lowered:
        return normalized_goal
    return default_goal


def _build_project_browser_autonomous_next_dev_slice_state() -> dict[str, Any]:
    post_push_dir = Path("/tmp/codex-local-runner-decision/post_push_queue_state")
    next_dev_slice_dir = Path("/tmp/codex-local-runner-decision/next_dev_slice")

    input_state_path = post_push_dir / "post_push_queue_state.json"
    input_summary_path = post_push_dir / "post_push_queue_summary.md"
    output_json_path = next_dev_slice_dir / "next_dev_slice.json"
    output_summary_path = next_dev_slice_dir / "next_dev_slice_summary.md"

    artifact_paths = {
        "input_post_push_queue_state_json": str(input_state_path),
        "input_post_push_queue_summary_md": str(input_summary_path),
        "output_next_dev_slice_json": str(output_json_path),
        "output_next_dev_slice_summary_md": str(output_summary_path),
    }
    runtime_posture = [
        "metadata_only_prompt_generation",
        "no_codex_invocation",
        "no_next_slice_execution",
        "no_commit_tag_push_pr_merge",
    ]

    status = "next_dev_slice_blocked_missing_post_push_state"
    next_action = "manual_review_required"
    selected_slice_id = ""
    selected_slice_goal = ""
    selected_slice_scope = "metadata_only_prompt_generation"
    blocked_reason = "missing_post_push_queue_state"
    selected_count = 0
    selected_slices: list[dict[str, Any]] = []

    post_push_payload: Mapping[str, Any] | None = None
    if input_state_path.exists():
        try:
            loaded_payload = json.loads(input_state_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            blocked_reason = "invalid_post_push_queue_state_json"
        else:
            if isinstance(loaded_payload, Mapping):
                post_push_payload = loaded_payload
            else:
                blocked_reason = "post_push_queue_state_not_object"

    if isinstance(post_push_payload, Mapping):
        status_value = _normalize_text(post_push_payload.get("status"), default="")
        action_value = _normalize_text(post_push_payload.get("next_action"), default="")
        ready_value = bool(post_push_payload.get("ready_for_next_local_codex_cycle", False))

        if status_value != "post_push_queue_state_updated":
            blocked_reason = "post_push_status_not_updated"
        elif action_value != "prepare_next_development_slice":
            blocked_reason = "post_push_next_action_not_prepare_next_development_slice"
        elif not ready_value:
            blocked_reason = "post_push_not_ready_for_next_local_codex_cycle"
        else:
            selected_slice_id = "next-local-codex-prompt-from-next-dev-slice"
            selected_slice_goal = "Generate next local Codex implementation prompt from next_dev_slice."
            selected_slice_scope = "metadata_only_prompt_generation"
            selected_count = 1
            selected_slices = [
                {
                    "slice_id": selected_slice_id,
                    "goal": selected_slice_goal,
                    "scope": selected_slice_scope,
                    "execution_status": "not_started",
                    "codex_invocation_status": "not_started",
                    "review_status": "not_started",
                    "commit_tag_status": "not_started",
                    "push_status": "not_started",
                    "do_not_invoke_codex_from_runner": True,
                    "do_not_execute_generated_slice": True,
                }
            ]
            status = "next_dev_slice_generated"
            next_action = "prepare_next_local_codex_prompt"
            blocked_reason = "none"

    next_dev_slice_payload = {
        "status": status,
        "next_action": next_action,
        "blocked_reason": blocked_reason,
        "selected_slice_count": int(selected_count),
        "selected_slices": selected_slices,
        "artifact_paths": artifact_paths,
        "runtime_posture": runtime_posture,
    }
    summary_lines = [
        "# Next Development Slice",
        "",
        f"- Status: `{status}`",
        f"- Next action: `{next_action}`",
        f"- Selected slice count: `{selected_count}`",
        f"- Selected slice id: `{selected_slice_id or 'none'}`",
        f"- Selected slice goal: `{selected_slice_goal or 'none'}`",
        f"- Selected slice scope: `{selected_slice_scope}`",
        f"- Blocked reason: `{blocked_reason}`",
        "",
        "## Artifact Paths",
        f"- Input state JSON: `{artifact_paths['input_post_push_queue_state_json']}`",
        f"- Input summary MD: `{artifact_paths['input_post_push_queue_summary_md']}`",
        f"- Output next-dev-slice JSON: `{artifact_paths['output_next_dev_slice_json']}`",
        f"- Output next-dev-slice summary MD: `{artifact_paths['output_next_dev_slice_summary_md']}`",
    ]

    if blocked_reason == "none":
        summary_lines.extend(
            [
                "",
                "## Selected Slice",
                f"- `slice_id`: `{selected_slice_id}`",
                f"- `goal`: `{selected_slice_goal}`",
                "- `scope`: `metadata_only_prompt_generation`",
                "- `execution_status`: `not_started`",
                "- `codex_invocation_status`: `not_started`",
                "- `review_status`: `not_started`",
                "- `commit_tag_status`: `not_started`",
                "- `push_status`: `not_started`",
            ]
        )

    try:
        next_dev_slice_dir.mkdir(parents=True, exist_ok=True)
        output_json_path.write_text(
            json.dumps(next_dev_slice_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        output_summary_path.write_text("\n".join(summary_lines) + "\n", encoding="utf-8")
    except OSError:
        status = "next_dev_slice_blocked_write_failed"
        next_action = "manual_review_required"
        blocked_reason = "next_dev_slice_artifact_write_failed"

    return {
        "project_browser_autonomous_next_dev_slice_status": status,
        "project_browser_autonomous_next_dev_slice_next_action": next_action,
        "project_browser_autonomous_next_dev_slice_id": selected_slice_id,
        "project_browser_autonomous_next_dev_slice_goal": selected_slice_goal,
        "project_browser_autonomous_next_dev_slice_scope": selected_slice_scope,
        "project_browser_autonomous_next_dev_slice_artifact_paths": artifact_paths,
        "project_browser_autonomous_next_dev_slice_blocked_reason": blocked_reason,
        "project_browser_autonomous_next_dev_slice_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_dev_slice_selected_count": int(selected_count),
    }


def _build_project_browser_autonomous_next_local_codex_prompt_state() -> dict[str, Any]:
    next_dev_slice_dir = Path("/tmp/codex-local-runner-decision/next_dev_slice")
    next_codex_prompt_dir = Path("/tmp/codex-local-runner-decision/next_codex_prompt")

    input_next_dev_slice_json = next_dev_slice_dir / "next_dev_slice.json"
    input_next_dev_slice_summary = next_dev_slice_dir / "next_dev_slice_summary.md"
    output_prompt_path = next_codex_prompt_dir / "codex_implementation_prompt.md"
    output_request_path = next_codex_prompt_dir / "codex_implementation_request.json"
    output_summary_path = next_codex_prompt_dir / "codex_implementation_summary.md"

    runtime_posture = [
        "metadata_only_prompt_generation",
        "no_codex_invocation",
        "no_prompt_execution",
        "no_commit_tag_push_pr_merge",
        "no_daemon_loop_no_unbounded_retry",
    ]

    status = "next_local_codex_prompt_blocked_missing_next_dev_slice"
    next_action = "manual_review_required"
    blocked_reason = "next_dev_slice_missing"
    source_slice_id = ""
    execution_status = "not_started"
    codex_invocation_status = "not_started"
    review_status = "not_started"
    commit_tag_status = "not_started"
    push_status = "not_started"
    selected_slice_goal = ""
    selected_slice_scope = ""
    concrete_prompt298_goal = ""

    request_payload: dict[str, Any] = {
        "status": status,
        "next_action": next_action,
        "blocked_reason": blocked_reason,
        "source_slice_id": source_slice_id,
        "execution_status": execution_status,
        "codex_invocation_status": codex_invocation_status,
        "review_status": review_status,
        "commit_tag_status": commit_tag_status,
        "push_status": push_status,
        "input_artifacts": {
            "next_dev_slice_json": str(input_next_dev_slice_json),
            "next_dev_slice_summary_md": str(input_next_dev_slice_summary),
        },
        "output_artifacts": {
            "codex_implementation_prompt_md": str(output_prompt_path),
            "codex_implementation_request_json": str(output_request_path),
            "codex_implementation_summary_md": str(output_summary_path),
        },
        "runtime_posture": runtime_posture,
    }

    prompt_lines: list[str] = [
        "# Local Codex Implement Prompt (Bounded Metadata-Only)",
        "",
        "- Mode: `Implement`",
        "- Goal: blocked because `next_dev_slice` input is missing or invalid.",
    ]

    if not input_next_dev_slice_json.exists():
        blocked_reason = "next_dev_slice_missing"
        status = "next_local_codex_prompt_blocked_missing_next_dev_slice"
    elif not input_next_dev_slice_summary.exists():
        blocked_reason = "next_dev_slice_summary_missing"
        status = "next_local_codex_prompt_blocked_missing_next_dev_slice_summary"
    else:
        try:
            next_dev_slice_payload = json.loads(input_next_dev_slice_json.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            blocked_reason = "next_dev_slice_invalid_json"
            status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
        else:
            if not isinstance(next_dev_slice_payload, Mapping):
                blocked_reason = "next_dev_slice_not_object"
                status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
            else:
                slice_status = _normalize_text(next_dev_slice_payload.get("status"), default="")
                slice_next_action = _normalize_text(next_dev_slice_payload.get("next_action"), default="")
                selected_slice_count = _as_non_negative_int(
                    next_dev_slice_payload.get("selected_slice_count"),
                    default=0,
                )
                selected_slices = (
                    list(next_dev_slice_payload.get("selected_slices", []))
                    if isinstance(next_dev_slice_payload.get("selected_slices"), list)
                    else []
                )
                selected_slice = selected_slices[0] if selected_slices else {}
                if not isinstance(selected_slice, Mapping):
                    selected_slice = {}
                source_slice_id = _normalize_text(selected_slice.get("slice_id"), default="")
                selected_slice_goal = _normalize_text(selected_slice.get("goal"), default="")
                selected_slice_scope = _normalize_text(selected_slice.get("scope"), default="")
                concrete_prompt298_goal = _build_concrete_prompt298_goal_from_next_dev_slice(
                    selected_slice_goal
                )

                if slice_status != "next_dev_slice_generated":
                    blocked_reason = "next_dev_slice_status_not_generated"
                    status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
                elif slice_next_action != "prepare_next_local_codex_prompt":
                    blocked_reason = "next_dev_slice_next_action_not_prepare_next_local_codex_prompt"
                    status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
                elif selected_slice_count != 1:
                    blocked_reason = "next_dev_slice_selected_count_not_one"
                    status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
                elif source_slice_id != "next-local-codex-prompt-from-next-dev-slice":
                    blocked_reason = "next_dev_slice_id_mismatch"
                    status = "next_local_codex_prompt_blocked_invalid_next_dev_slice"
                else:
                    blocked_reason = "none"
                    status = "next_local_codex_prompt_generated"
                    next_action = "ready_for_bounded_local_codex_implementation"
                    prompt_lines = [
                        "# Prompt298: Implement Local Codex Execution Readiness (Metadata-Only)",
                        "",
                        "- Mode: `Implement`",
                        "",
                        "## Goal",
                        concrete_prompt298_goal,
                        "",
                        "## Allowed Files",
                        "- `automation/orchestration/planned_execution_runner.py`",
                        "- If absolutely necessary, only files required to keep this path syntactically valid.",
                        "",
                        "## Forbidden Files",
                        "- Any file outside the allowed scope unless absolutely necessary for imports or strict runtime safety.",
                        "",
                        "## Required Input",
                        f"- `{output_prompt_path}`",
                        f"- `{output_request_path}`",
                        f"- `{output_summary_path}`",
                        "",
                        "## Expected Artifacts",
                        "- `/tmp/codex-local-runner-decision/local_codex_execution_readiness/local_codex_execution_readiness.json`",
                        "- `/tmp/codex-local-runner-decision/local_codex_execution_readiness/local_codex_execution_summary.md`",
                        "- `/tmp/codex-local-runner-decision/local_codex_execution_readiness/local_codex_exec_plan.sh`",
                        "",
                        "## Required Behavior",
                        "- Read the three `next_codex_prompt` artifacts and verify:",
                        "  - request `status=next_local_codex_prompt_generated`",
                        "  - request `next_action=ready_for_bounded_local_codex_implementation`",
                        "  - request `blocked_reason=none`",
                        "- Confirm `codex_implementation_prompt.md` exists and is non-empty.",
                        "- Confirm the prompt is intended for a later local codex exec run only.",
                        "- Confirm the prompt does not request: git commit, git tag, git push, PR creation, merge, daemon, polling loop, sleep loop, queue drain, or unbounded retry.",
                        f"- Write `local_codex_exec_plan.sh` with this exact bounded command: `{_LOCAL_CODEX_EXEC_PLAN_COMMAND}`",
                        "- Do not execute `local_codex_exec_plan.sh`.",
                        "- Do not invoke Codex from inside the runner.",
                        "- Do not execute `codex_implementation_prompt.md`.",
                        "- Do not commit, tag, push, open PR, or merge.",
                        "",
                        "## Required Contract Fields",
                        "- `project_browser_autonomous_local_codex_execution_readiness_status`",
                        "- `project_browser_autonomous_local_codex_execution_readiness_next_action`",
                        "- `project_browser_autonomous_local_codex_execution_readiness_prompt_path`",
                        "- `project_browser_autonomous_local_codex_execution_readiness_exec_plan_path`",
                        "- `project_browser_autonomous_local_codex_execution_readiness_blocked_reason`",
                        "- `project_browser_autonomous_local_codex_execution_readiness_runtime_posture`",
                        "",
                        "## Next Action Mapping",
                        "- Readiness artifacts written -> `ready_for_local_codex_exec_command`",
                        "- `next_codex_prompt` missing/invalid -> `manual_review_required`",
                        "- Unsafe/self-referential prompt -> `manual_review_required`",
                        "",
                        "## Validation Commands",
                        "- `python -m py_compile automation/orchestration/planned_execution_runner.py`",
                        "- `python scripts/run_planned_execution.py --artifacts-dir /tmp/codex-local-runner-decision/artifacts --out-dir /tmp/codex-local-runner-decision/out --job-id planned-execution --transport-mode dry-run --json`",
                        "- Run one dry-run verification command only (no repeated retries).",
                        "",
                        "## Out Of Scope",
                        "- Running Codex from inside the runner.",
                        "- Executing local Codex commands inside this Prompt298 run.",
                        "- Executing `local_codex_exec_plan.sh`.",
                        "- Executing the generated implementation prompt.",
                        "- Tests beyond the requested syntax check.",
                        "- Commit/tag/push/PR/merge operations.",
                        "- Deleting existing runtime artifacts.",
                    ]

    request_payload.update(
        {
            "status": status,
            "next_action": next_action,
            "blocked_reason": blocked_reason,
            "source_slice_id": source_slice_id,
            "source_slice_goal": selected_slice_goal,
            "source_slice_scope": selected_slice_scope,
            "execution_status": execution_status,
            "codex_invocation_status": codex_invocation_status,
            "review_status": review_status,
            "commit_tag_status": commit_tag_status,
            "push_status": push_status,
            "do_not_invoke_codex_from_runner": True,
            "do_not_execute_generated_implementation_prompt": True,
            "do_not_commit_tag_push_pr_merge": True,
        }
    )

    summary_lines = [
        "# Next Local Codex Prompt Generation",
        "",
        f"- Status: `{status}`",
        f"- Next action: `{next_action}`",
        f"- Source slice id: `{source_slice_id or 'none'}`",
        f"- Blocked reason: `{blocked_reason}`",
        "- execution_status: `not_started`",
        "- codex_invocation_status: `not_started`",
        "- review_status: `not_started`",
        "- commit_tag_status: `not_started`",
        "- push_status: `not_started`",
        "",
        "## Input Artifacts",
        f"- next_dev_slice.json: `{input_next_dev_slice_json}`",
        f"- next_dev_slice_summary.md: `{input_next_dev_slice_summary}`",
        "",
        "## Output Artifacts",
        f"- codex_implementation_prompt.md: `{output_prompt_path}`",
        f"- codex_implementation_request.json: `{output_request_path}`",
        f"- codex_implementation_summary.md: `{output_summary_path}`",
    ]

    try:
        next_codex_prompt_dir.mkdir(parents=True, exist_ok=True)
        output_prompt_path.write_text("\n".join(prompt_lines).rstrip() + "\n", encoding="utf-8")
        output_request_path.write_text(
            json.dumps(request_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        output_summary_path.write_text("\n".join(summary_lines) + "\n", encoding="utf-8")
    except OSError:
        status = "next_local_codex_prompt_blocked_write_failed"
        next_action = "manual_review_required"
        blocked_reason = "next_local_codex_prompt_artifact_write_failed"

    return {
        "project_browser_autonomous_next_local_codex_prompt_status": status,
        "project_browser_autonomous_next_local_codex_prompt_next_action": next_action,
        "project_browser_autonomous_next_local_codex_prompt_source_slice_id": source_slice_id,
        "project_browser_autonomous_next_local_codex_prompt_path": str(output_prompt_path),
        "project_browser_autonomous_next_local_codex_prompt_request_path": str(output_request_path),
        "project_browser_autonomous_next_local_codex_prompt_summary_path": str(output_summary_path),
        "project_browser_autonomous_next_local_codex_prompt_blocked_reason": blocked_reason,
        "project_browser_autonomous_next_local_codex_prompt_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_local_codex_prompt_execution_status": execution_status,
        "project_browser_autonomous_next_local_codex_prompt_codex_invocation_status": (
            codex_invocation_status
        ),
        "project_browser_autonomous_next_local_codex_prompt_review_status": review_status,
        "project_browser_autonomous_next_local_codex_prompt_commit_tag_status": commit_tag_status,
        "project_browser_autonomous_next_local_codex_prompt_push_status": push_status,
    }


def _build_project_browser_autonomous_local_codex_execution_readiness_state() -> dict[str, Any]:
    next_codex_prompt_dir = Path("/tmp/codex-local-runner-decision/next_codex_prompt")
    readiness_dir = Path("/tmp/codex-local-runner-decision/local_codex_execution_readiness")

    input_prompt_path = next_codex_prompt_dir / "codex_implementation_prompt.md"
    input_request_path = next_codex_prompt_dir / "codex_implementation_request.json"
    input_summary_path = next_codex_prompt_dir / "codex_implementation_summary.md"

    output_json_path = readiness_dir / "local_codex_execution_readiness.json"
    output_summary_path = readiness_dir / "local_codex_execution_summary.md"
    output_exec_plan_path = readiness_dir / "local_codex_exec_plan.sh"

    runtime_posture = [
        "metadata_only_readiness",
        "no_codex_invocation",
        "no_prompt_execution",
        "no_exec_plan_execution",
        "no_commit_tag_push_pr_merge",
        "no_daemon_loop_no_unbounded_retry",
    ]

    status = "local_codex_execution_readiness_blocked_missing_next_codex_prompt"
    next_action = "manual_review_required"
    blocked_reason = "next_codex_prompt_missing"
    prompt_exists = False
    prompt_non_empty = False
    prompt_intended_for_later_exec_only = False
    prompt_safe = False
    prompt_self_referential = False
    banned_requests_detected: list[str] = []

    request_payload: Mapping[str, Any] | None = None
    prompt_text = ""
    summary_text = ""

    input_artifacts = {
        "codex_implementation_prompt_md": str(input_prompt_path),
        "codex_implementation_request_json": str(input_request_path),
        "codex_implementation_summary_md": str(input_summary_path),
    }
    output_artifacts = {
        "local_codex_execution_readiness_json": str(output_json_path),
        "local_codex_execution_summary_md": str(output_summary_path),
        "local_codex_exec_plan_sh": str(output_exec_plan_path),
    }

    if not input_prompt_path.exists():
        blocked_reason = "next_codex_prompt_prompt_missing"
        status = "local_codex_execution_readiness_blocked_missing_next_codex_prompt"
    elif not input_request_path.exists():
        blocked_reason = "next_codex_prompt_request_missing"
        status = "local_codex_execution_readiness_blocked_missing_next_codex_prompt"
    elif not input_summary_path.exists():
        blocked_reason = "next_codex_prompt_summary_missing"
        status = "local_codex_execution_readiness_blocked_missing_next_codex_prompt"
    else:
        try:
            loaded_request_payload = json.loads(input_request_path.read_text(encoding="utf-8"))
            prompt_text = input_prompt_path.read_text(encoding="utf-8")
            summary_text = input_summary_path.read_text(encoding="utf-8")
        except (OSError, json.JSONDecodeError):
            blocked_reason = "next_codex_prompt_invalid"
            status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
        else:
            if not isinstance(loaded_request_payload, Mapping):
                blocked_reason = "next_codex_prompt_request_not_object"
                status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
            else:
                request_payload = loaded_request_payload
                request_status = _normalize_text(request_payload.get("status"), default="")
                request_next_action = _normalize_text(request_payload.get("next_action"), default="")
                request_blocked_reason = _normalize_text(
                    request_payload.get("blocked_reason"),
                    default="",
                )
                summary_readable = bool(summary_text.strip())

                prompt_exists = input_prompt_path.is_file()
                prompt_non_empty = bool(prompt_text.strip())
                prompt_text_lower = prompt_text.lower()
                prompt_intended_for_later_exec_only = (
                    "later local codex exec run only" in prompt_text_lower
                    or (
                        "local codex execution readiness" in prompt_text_lower
                        and "do not execute `local_codex_exec_plan.sh`" in prompt_text_lower
                    )
                )
                prompt_self_referential = (
                    "generate next local codex implementation request from next_dev_slice"
                    in prompt_text_lower
                    or "bounded metadata-only local prompt generation from `next_dev_slice`"
                    in prompt_text_lower
                )
                banned_requests_detected = (
                    _collect_local_codex_execution_readiness_banned_prompt_fragments(
                        prompt_text_lower
                    )
                )
                prompt_safe = not prompt_self_referential and not banned_requests_detected

                if request_status != "next_local_codex_prompt_generated":
                    blocked_reason = "next_codex_prompt_status_not_generated"
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif request_next_action != "ready_for_bounded_local_codex_implementation":
                    blocked_reason = (
                        "next_codex_prompt_next_action_not_ready_for_bounded_local_codex_implementation"
                    )
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif request_blocked_reason != "none":
                    blocked_reason = "next_codex_prompt_blocked_reason_not_none"
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif not summary_readable:
                    blocked_reason = "next_codex_prompt_summary_empty"
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif not prompt_exists:
                    blocked_reason = "next_codex_prompt_prompt_not_file"
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif not prompt_non_empty:
                    blocked_reason = "next_codex_prompt_prompt_empty"
                    status = "local_codex_execution_readiness_blocked_invalid_next_codex_prompt"
                elif not prompt_intended_for_later_exec_only:
                    blocked_reason = "prompt_not_intended_for_later_local_codex_exec_run_only"
                    status = "local_codex_execution_readiness_blocked_prompt_unsafe_or_self_referential"
                elif prompt_self_referential:
                    blocked_reason = "prompt_self_referential"
                    status = "local_codex_execution_readiness_blocked_prompt_unsafe_or_self_referential"
                elif banned_requests_detected:
                    blocked_reason = "prompt_requests_disallowed_operations"
                    status = "local_codex_execution_readiness_blocked_prompt_unsafe_or_self_referential"
                else:
                    blocked_reason = "none"
                    status = "local_codex_execution_readiness_generated"
                    next_action = "ready_for_local_codex_exec_command"

    readiness_payload: dict[str, Any] = {
        "status": status,
        "next_action": next_action,
        "blocked_reason": blocked_reason,
        "prompt_path": str(input_prompt_path),
        "prompt_exists": prompt_exists,
        "prompt_non_empty": prompt_non_empty,
        "prompt_intended_for_later_local_codex_exec_run_only": prompt_intended_for_later_exec_only,
        "prompt_safe": prompt_safe,
        "prompt_self_referential": prompt_self_referential,
        "prompt_banned_requests_detected": banned_requests_detected,
        "exact_bounded_exec_command": _LOCAL_CODEX_EXEC_PLAN_COMMAND,
        "do_not_execute_local_codex_exec_plan": True,
        "do_not_invoke_codex_from_runner": True,
        "do_not_execute_generated_implementation_prompt": True,
        "do_not_commit_tag_push_pr_merge": True,
        "input_artifacts": input_artifacts,
        "output_artifacts": output_artifacts,
        "runtime_posture": runtime_posture,
    }

    summary_lines = [
        "# Local Codex Execution Readiness",
        "",
        f"- Status: `{status}`",
        f"- Next action: `{next_action}`",
        f"- Blocked reason: `{blocked_reason}`",
        f"- Prompt exists: `{str(prompt_exists).lower()}`",
        f"- Prompt non-empty: `{str(prompt_non_empty).lower()}`",
        (
            "- Prompt intended for later local codex exec run only: "
            f"`{str(prompt_intended_for_later_exec_only).lower()}`"
        ),
        f"- Prompt safe: `{str(prompt_safe).lower()}`",
        f"- Prompt self-referential: `{str(prompt_self_referential).lower()}`",
        f"- Banned requests detected: `{', '.join(banned_requests_detected) if banned_requests_detected else 'none'}`",
        "",
        "## Input Artifacts",
        f"- codex_implementation_prompt.md: `{input_prompt_path}`",
        f"- codex_implementation_request.json: `{input_request_path}`",
        f"- codex_implementation_summary.md: `{input_summary_path}`",
        "",
        "## Output Artifacts",
        f"- local_codex_execution_readiness.json: `{output_json_path}`",
        f"- local_codex_execution_summary.md: `{output_summary_path}`",
        f"- local_codex_exec_plan.sh: `{output_exec_plan_path}`",
        "",
        "## Bounded Exec Command",
        f"- `{_LOCAL_CODEX_EXEC_PLAN_COMMAND}`",
    ]

    try:
        readiness_dir.mkdir(parents=True, exist_ok=True)
        output_json_path.write_text(
            json.dumps(readiness_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        output_summary_path.write_text("\n".join(summary_lines) + "\n", encoding="utf-8")
        output_exec_plan_path.write_text(
            (
                "#!/usr/bin/env bash\n"
                "set -euo pipefail\n"
                "\n"
                f"{_LOCAL_CODEX_EXEC_PLAN_COMMAND}\n"
            ),
            encoding="utf-8",
        )
        try:
            current_mode = output_exec_plan_path.stat().st_mode
            output_exec_plan_path.chmod(current_mode | 0o111)
        except OSError:
            pass
    except OSError:
        status = "local_codex_execution_readiness_blocked_write_failed"
        next_action = "manual_review_required"
        blocked_reason = "local_codex_execution_readiness_artifact_write_failed"

    return {
        "project_browser_autonomous_local_codex_execution_readiness_status": status,
        "project_browser_autonomous_local_codex_execution_readiness_next_action": next_action,
        "project_browser_autonomous_local_codex_execution_readiness_prompt_path": str(
            input_prompt_path
        ),
        "project_browser_autonomous_local_codex_execution_readiness_json_path": str(
            output_json_path
        ),
        "project_browser_autonomous_local_codex_execution_readiness_summary_path": str(
            output_summary_path
        ),
        "project_browser_autonomous_local_codex_execution_readiness_exec_plan_path": str(
            output_exec_plan_path
        ),
        "project_browser_autonomous_local_codex_execution_readiness_blocked_reason": blocked_reason,
        "project_browser_autonomous_local_codex_execution_readiness_runtime_posture": runtime_posture,
    }


def _evaluate_one_cycle_controller_exec_plan_safety(*, exec_plan_path: Path) -> dict[str, Any]:
    required_fragments_present: list[str] = []
    banned_fragments_present: list[str] = []

    if not exec_plan_path.exists():
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_missing",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }
    if exec_plan_path.is_symlink():
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_symlink",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    try:
        exec_plan_text = exec_plan_path.read_text(encoding="utf-8")
    except OSError:
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_read_error",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    if not exec_plan_text:
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_empty",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    exec_plan_lines = exec_plan_text.splitlines()
    if len(exec_plan_lines) < 2 or exec_plan_lines[0] != "#!/usr/bin/env bash" or exec_plan_lines[1] != "set -euo pipefail":
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_invalid_strict_header",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    for fragment in _ONE_CYCLE_CONTROLLER_EXEC_PLAN_REQUIRED_FRAGMENTS:
        if fragment in exec_plan_text:
            required_fragments_present.append(fragment)
    approval_policy_fragment_present = ""
    for fragment in _ONE_CYCLE_CONTROLLER_EXEC_PLAN_APPROVAL_POLICY_ALLOWED_FRAGMENTS:
        if fragment in exec_plan_text:
            approval_policy_fragment_present = fragment
            break
    if approval_policy_fragment_present:
        required_fragments_present.append(approval_policy_fragment_present)
    required_fragments_ok = (
        len(required_fragments_present)
        == len(_ONE_CYCLE_CONTROLLER_EXEC_PLAN_REQUIRED_FRAGMENTS) + 1
    )
    if not required_fragments_ok:
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_required_fragment_missing",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    for fragment in _ONE_CYCLE_CONTROLLER_EXEC_PLAN_BANNED_FRAGMENTS:
        if fragment in exec_plan_text:
            banned_fragments_present.append(fragment)
    if banned_fragments_present:
        return {
            "exec_plan_safety_status": "blocked",
            "exec_plan_blocked_reason": "exec_plan_banned_fragment_present",
            "exec_plan_required_fragments_present": required_fragments_present,
            "exec_plan_banned_fragments_present": banned_fragments_present,
        }

    return {
        "exec_plan_safety_status": "safe",
        "exec_plan_blocked_reason": "none",
        "exec_plan_required_fragments_present": required_fragments_present,
        "exec_plan_banned_fragments_present": banned_fragments_present,
    }


def _read_one_cycle_completed_result_source(
    *, result_path: Path
) -> tuple[str, dict[str, Any]]:
    def _read_flag(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return False

    if not result_path.exists():
        return "missing", {}

    try:
        result_payload_raw = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return "invalid", {}

    if not isinstance(result_payload_raw, Mapping):
        return "invalid", {}

    result_payload = dict(result_payload_raw)
    result_status = _normalize_text(result_payload.get("status"), default="")
    stop_reason = _normalize_text(result_payload.get("stop_reason"), default="")
    execution_attempted = _read_flag(result_payload.get("execution_attempted", False))
    execution_exit_code = _as_int(result_payload.get("execution_exit_code"), default=-1)
    exec_plan_execution_status = _normalize_text(
        result_payload.get("exec_plan_execution_status"),
        default="",
    )
    if (
        result_status == "one_cycle_controller_completed"
        and stop_reason == "review_response_required"
        and execution_attempted
        and execution_exit_code == 0
        and exec_plan_execution_status == "completed"
    ):
        return "available", result_payload
    return "not_completed", result_payload


def _build_one_cycle_post_execution_handoff(
    *,
    execution_repo_path: str,
    status: str,
    stop_reason: str,
    next_action: str,
    execution_attempted: bool,
    execution_exit_code: int,
    exec_plan_execution_status: str,
    one_cycle_controller_dir: Path,
    completed_result_source_path: Path,
) -> dict[str, Any]:
    _ = (
        status,
        stop_reason,
        next_action,
        execution_attempted,
        execution_exit_code,
        exec_plan_execution_status,
        completed_result_source_path,
    )

    def _read_json_mapping(path: Path) -> tuple[bool, bool, dict[str, Any]]:
        if not path.exists():
            return False, False, {}
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return True, False, {}
        if not isinstance(payload, Mapping):
            return True, False, {}
        return True, True, dict(payload)

    def _read_bounded_text(path: Path, *, max_lines: int) -> tuple[bool, int, list[str], str]:
        if not path.exists():
            return False, 0, [], ""
        size_bytes = 0
        try:
            size_bytes = max(0, int(path.stat().st_size))
        except OSError:
            size_bytes = 0
        try:
            text = path.read_text(encoding="utf-8")
        except OSError:
            return True, size_bytes, [], ""
        lines = text.splitlines()
        return True, size_bytes, lines[:max_lines], text

    def _extract_stdout_blocked_reason(stdout_text: str) -> tuple[bool, str]:
        lines = stdout_text.splitlines()
        contains_blocked = any(
            _normalize_text(line, default="").strip().upper().startswith("BLOCKED")
            for line in lines
        )
        blocked_reason = ""
        marker_index = -1
        for idx, raw_line in enumerate(lines):
            normalized = _normalize_text(raw_line, default="").strip().lower()
            if normalized.startswith("specific blocked reason"):
                marker_index = idx
                suffix = _normalize_text(raw_line, default="")
                if ":" in suffix:
                    maybe_reason = suffix.split(":", 1)[1].strip()
                    if maybe_reason:
                        blocked_reason = maybe_reason
                break
        if marker_index >= 0 and not blocked_reason:
            for follow_line in lines[marker_index + 1 :]:
                maybe_reason = _normalize_text(follow_line, default="").strip()
                if maybe_reason:
                    blocked_reason = maybe_reason
                    break
        return contains_blocked, blocked_reason

    def _prompt334_safety_fields() -> dict[str, Any]:
        return {
            "commit_allowed": False,
            "tag_allowed": False,
            "push_pr_merge_enabled": False,
            "targeted_fix_execution_allowed": False,
            "rollback_allowed": False,
            "commit_performed": False,
            "tag_performed": False,
            "push_performed": False,
            "pr_created": False,
            "merge_performed": False,
            "rollback_performed": False,
            "codex_invoked": False,
            "codex_invocation_allowed": False,
        }

    one_cycle_controller_dir = Path(one_cycle_controller_dir)
    diff_stat_path = one_cycle_controller_dir / "one_cycle_controller_diff_stat.txt"
    diff_name_status_path = one_cycle_controller_dir / "one_cycle_controller_diff_name_status.txt"
    diff_patch_path = one_cycle_controller_dir / "one_cycle_controller_diff.patch"
    review_request_path = one_cycle_controller_dir / "one_cycle_controller_review_request.md"
    review_handoff_path = one_cycle_controller_dir / "one_cycle_controller_review_handoff.json"

    prompt333_result_path = one_cycle_controller_dir / "local_codex_one_shot_execution_result.json"
    prompt333_receipt_v2_path = (
        one_cycle_controller_dir / "local_codex_one_shot_execution_receipt_v2.json"
    )
    prompt333_stdout_path = one_cycle_controller_dir / "local_codex_one_shot_execution_stdout.txt"
    prompt333_stderr_path = one_cycle_controller_dir / "local_codex_one_shot_execution_stderr.txt"
    prompt334_diff_capture_path = one_cycle_controller_dir / "local_post_codex_diff_capture.json"
    prompt334_outcome_path = one_cycle_controller_dir / "local_post_codex_execution_outcome.json"
    prompt334_route_path = one_cycle_controller_dir / "local_post_codex_route_decision.json"
    prompt334_receipt_path = one_cycle_controller_dir / "local_post_codex_diff_capture_receipt.json"

    prompt333_result_exists, prompt333_result_valid, prompt333_result_payload = _read_json_mapping(
        prompt333_result_path
    )
    prompt333_receipt_v2_exists, prompt333_receipt_v2_valid, prompt333_receipt_v2_payload = (
        _read_json_mapping(prompt333_receipt_v2_path)
    )
    prompt333_validation_errors: list[str] = []
    prompt333_blocked_reason = "none"
    prompt333_ready = True

    def _invalidate(reason: str, detail: str) -> None:
        nonlocal prompt333_ready, prompt333_blocked_reason
        prompt333_ready = False
        if prompt333_blocked_reason == "none":
            prompt333_blocked_reason = reason
        prompt333_validation_errors.append(detail)

    if not prompt333_result_exists:
        _invalidate(
            "missing_prompt333_execution_result_artifact",
            "missing_prompt333_execution_result_artifact",
        )
    elif not prompt333_result_valid:
        _invalidate(
            "invalid_prompt333_execution_result_artifact",
            "invalid_prompt333_execution_result_artifact",
        )

    if not prompt333_receipt_v2_exists:
        _invalidate(
            "missing_prompt333_execution_receipt_v2_artifact",
            "missing_prompt333_execution_receipt_v2_artifact",
        )
    elif not prompt333_receipt_v2_valid:
        _invalidate(
            "invalid_prompt333_execution_receipt_v2_artifact",
            "invalid_prompt333_execution_receipt_v2_artifact",
        )

    if prompt333_result_valid:
        expected_fields: tuple[tuple[str, Any], ...] = (
            ("schema_version", _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION),
            ("execution_schema_version", _LOCAL_CODEX_ONE_SHOT_EXECUTION_SCHEMA_VERSION),
            ("status", "completed"),
            ("execution_status", "completed"),
            ("blocked_reason", "none"),
            (
                "readiness_reason",
                "local_codex_one_shot_handoff_valid_and_tracked_worktree_clean",
            ),
            ("codex_invoked", True),
            ("execution_attempted", True),
            ("execution_completed", True),
            ("max_codex_invocations", 1),
            ("codex_invocation_count", 1),
        )
        field_failure_reasons = {
            "schema_version": "prompt333_execution_result_schema_version_mismatch",
            "execution_schema_version": "prompt333_execution_result_execution_schema_version_mismatch",
            "status": "prompt333_execution_result_status_not_completed",
            "execution_status": "prompt333_execution_result_execution_status_not_completed",
            "blocked_reason": "prompt333_execution_result_blocked_reason_not_none",
            "readiness_reason": "prompt333_execution_result_readiness_reason_mismatch",
            "codex_invoked": "prompt333_execution_result_codex_not_invoked",
            "execution_attempted": "prompt333_execution_result_execution_not_attempted",
            "execution_completed": "prompt333_execution_result_execution_not_completed",
            "max_codex_invocations": "prompt333_execution_result_max_codex_invocations_not_one",
            "codex_invocation_count": "prompt333_execution_result_codex_invocation_count_not_one",
        }
        for field_name, expected_value in expected_fields:
            actual_value = prompt333_result_payload.get(field_name)
            if actual_value != expected_value:
                _invalidate(
                    field_failure_reasons[field_name],
                    f"{field_name}_mismatch",
                )
                break
        raw_execution_exit_code = prompt333_result_payload.get("execution_exit_code")
        parsed_execution_exit_code = _as_optional_int(raw_execution_exit_code)
        if parsed_execution_exit_code is None:
            _invalidate(
                "prompt333_execution_result_execution_exit_code_not_integer",
                "execution_exit_code_not_integer",
            )
        execution_result = _normalize_text(
            prompt333_result_payload.get("execution_result"),
            default="",
        )
        if execution_result not in {"codex_one_shot_completed", "codex_one_shot_failed"}:
            _invalidate(
                "prompt333_execution_result_execution_result_invalid",
                "execution_result_invalid",
            )
        result_next_action = _normalize_text(
            prompt333_result_payload.get("next_action"),
            default="",
        )
        if result_next_action not in {
            "prepare_local_git_diff_capture",
            "manual_review_local_codex_one_shot_execution_failure",
        }:
            _invalidate(
                "prompt333_execution_result_next_action_invalid",
                "next_action_invalid",
            )
        validation_errors_field = prompt333_result_payload.get("validation_errors")
        if _normalize_string_list(validation_errors_field):
            _invalidate(
                "prompt333_execution_result_validation_errors_not_empty",
                "validation_errors_not_empty",
            )
        if "command_argv_mismatch_source" in prompt333_result_payload:
            if (
                _normalize_text(
                    prompt333_result_payload.get("command_argv_mismatch_source"),
                    default="",
                )
                != "none"
            ):
                _invalidate(
                    "prompt333_execution_result_command_argv_mismatch_source_not_none",
                    "command_argv_mismatch_source_invalid",
                )
        if "authoritative_handoff_command_argv_equal_expected" in prompt333_result_payload:
            if not bool(
                prompt333_result_payload.get("authoritative_handoff_command_argv_equal_expected")
            ):
                _invalidate(
                    "prompt333_execution_result_authoritative_handoff_command_argv_not_equal_expected",
                    "authoritative_handoff_command_argv_equal_expected_invalid",
                )
        if "supporting_receipt_command_argv_equal_expected" in prompt333_result_payload:
            supporting_value = prompt333_result_payload.get(
                "supporting_receipt_command_argv_equal_expected"
            )
            if supporting_value is not None and bool(supporting_value) is not True:
                _invalidate(
                    "prompt333_execution_result_supporting_receipt_command_argv_not_equal_expected",
                    "supporting_receipt_command_argv_equal_expected_invalid",
                )

    prompt333_execution_exit_code_value = _as_optional_int(
        prompt333_result_payload.get("execution_exit_code")
    )
    prompt333_execution_exit_code = (
        int(prompt333_execution_exit_code_value)
        if prompt333_execution_exit_code_value is not None
        else -1
    )

    stdout_exists, stdout_size_bytes, stdout_head_lines, stdout_text = _read_bounded_text(
        prompt333_stdout_path,
        max_lines=40,
    )
    stderr_exists, stderr_size_bytes, stderr_head_lines, stderr_text = _read_bounded_text(
        prompt333_stderr_path,
        max_lines=40,
    )
    stdout_contains_blocked, stdout_blocked_reason = _extract_stdout_blocked_reason(stdout_text)

    git_commands: dict[str, list[str]] = {
        "status_short": ["status", "--short", "--untracked-files=no"],
        "diff_stat": ["diff", "--stat"],
        "diff_name_status": ["diff", "--name-status"],
        "diff_numstat": ["diff", "--numstat"],
        "diff_name_only": ["diff", "--name-only"],
        "cached_diff_stat": ["diff", "--cached", "--stat"],
        "cached_diff_name_status": ["diff", "--cached", "--name-status"],
        "cached_diff_name_only": ["diff", "--cached", "--name-only"],
    }
    git_command_exit_codes: dict[str, int] = {}
    git_command_stdout: dict[str, str] = {}
    git_capture_failed = False
    if prompt333_ready:
        for key, args in git_commands.items():
            try:
                cp = _run_git(execution_repo_path, args, timeout_seconds=20.0)
            except (OSError, subprocess.TimeoutExpired):
                git_command_exit_codes[key] = 124
                git_command_stdout[key] = ""
                git_capture_failed = True
                continue
            git_command_exit_codes[key] = int(cp.returncode)
            git_command_stdout[key] = _normalize_text(cp.stdout, default="")
            if cp.returncode != 0:
                git_capture_failed = True

    status_short_lines = (
        [
            _normalize_text(line, default="")
            for line in git_command_stdout.get("status_short", "").splitlines()
            if _normalize_text(line, default="").strip()
        ]
        if prompt333_ready
        else []
    )
    unstaged_tracked_files = (
        sorted(
            {
                _normalize_text(line, default="").strip()
                for line in git_command_stdout.get("diff_name_only", "").splitlines()
                if _normalize_text(line, default="").strip()
            }
        )
        if prompt333_ready
        else []
    )
    staged_tracked_files = (
        sorted(
            {
                _normalize_text(line, default="").strip()
                for line in git_command_stdout.get("cached_diff_name_only", "").splitlines()
                if _normalize_text(line, default="").strip()
            }
        )
        if prompt333_ready
        else []
    )
    changed_tracked_files = sorted(set(unstaged_tracked_files) | set(staged_tracked_files))
    changed_tracked_file_count = len(changed_tracked_files)
    staged_tracked_file_count = len(staged_tracked_files)
    unstaged_tracked_file_count = len(unstaged_tracked_files)
    worktree_clean_for_tracked_files = changed_tracked_file_count == 0 and not status_short_lines
    staged_changes_present = staged_tracked_file_count > 0
    unstaged_changes_present = unstaged_tracked_file_count > 0
    local_diff_present = changed_tracked_file_count > 0
    local_diff_stat_text = _normalize_text(git_command_stdout.get("diff_stat"), default="").strip()
    local_diff_name_status_lines = [
        _normalize_text(line, default="").strip()
        for line in git_command_stdout.get("diff_name_status", "").splitlines()
        if _normalize_text(line, default="").strip()
    ]
    local_diff_numstat_lines = [
        _normalize_text(line, default="").strip()
        for line in git_command_stdout.get("diff_numstat", "").splitlines()
        if _normalize_text(line, default="").strip()
    ]
    local_diff_name_only_lines = [
        _normalize_text(line, default="").strip()
        for line in git_command_stdout.get("diff_name_only", "").splitlines()
        if _normalize_text(line, default="").strip()
    ]

    if not prompt333_ready:
        codex_outcome_classification = "prompt333_execution_not_ready"
    elif prompt333_execution_exit_code == 0 and not stdout_contains_blocked and changed_tracked_file_count > 0:
        codex_outcome_classification = "codex_task_success_with_tracked_changes"
    elif prompt333_execution_exit_code == 0 and not stdout_contains_blocked and changed_tracked_file_count == 0:
        codex_outcome_classification = "codex_task_success_no_tracked_changes"
    elif prompt333_execution_exit_code == 0 and stdout_contains_blocked and changed_tracked_file_count == 0:
        codex_outcome_classification = "codex_task_blocked_no_tracked_changes"
    elif prompt333_execution_exit_code == 0 and stdout_contains_blocked and changed_tracked_file_count > 0:
        codex_outcome_classification = "codex_task_blocked_with_tracked_changes"
    elif prompt333_execution_exit_code != 0 and changed_tracked_file_count == 0:
        codex_outcome_classification = "codex_task_failed_no_tracked_changes"
    else:
        codex_outcome_classification = "codex_task_failed_with_tracked_changes"

    route_decision = "manual_review_prompt333_execution_artifacts"
    route_next_action = "manual_review_prompt333_execution_artifacts"
    approve_commit_tag_allowed = False
    targeted_contract_fix_recommended = False
    contract_fix_reason = ""
    if codex_outcome_classification == "codex_task_success_with_tracked_changes":
        route_decision = "prepare_review_for_tracked_changes"
        route_next_action = "prepare_local_review_handoff"
    elif codex_outcome_classification == "codex_task_success_no_tracked_changes":
        route_decision = "prepare_no_change_review"
        route_next_action = "manual_review_no_tracked_changes_after_codex_success"
    elif codex_outcome_classification == "codex_task_blocked_no_tracked_changes":
        route_decision = "prepare_contract_handoff_fix"
        route_next_action = "prepare_targeted_contract_fix_prompt"
        targeted_contract_fix_recommended = True
        contract_fix_reason = stdout_blocked_reason
    elif codex_outcome_classification == "codex_task_blocked_with_tracked_changes":
        route_decision = "prepare_blocked_with_changes_review"
        route_next_action = "manual_review_blocked_codex_with_tracked_changes"
        targeted_contract_fix_recommended = True
        contract_fix_reason = stdout_blocked_reason
    elif codex_outcome_classification == "codex_task_failed_no_tracked_changes":
        route_decision = "manual_review_codex_failure"
        route_next_action = "manual_review_local_codex_one_shot_execution_failure"
    elif codex_outcome_classification == "codex_task_failed_with_tracked_changes":
        route_decision = "manual_review_codex_failure_with_changes"
        route_next_action = "manual_review_failed_codex_with_tracked_changes"

    local_post_codex_diff_capture_status = "completed"
    local_post_codex_diff_capture_blocked_reason = "none"
    if not prompt333_ready:
        local_post_codex_diff_capture_status = "blocked"
        local_post_codex_diff_capture_blocked_reason = prompt333_blocked_reason
    elif git_capture_failed:
        local_post_codex_diff_capture_status = "blocked"
        local_post_codex_diff_capture_blocked_reason = "local_post_codex_git_diff_capture_failed"

    local_post_codex_outcome_status = "completed" if prompt333_ready else "blocked"
    local_post_codex_route_status = "completed" if prompt333_ready else "blocked"

    safety_fields = _prompt334_safety_fields()
    prompt333_validation_errors_normalized = _normalize_string_list(prompt333_validation_errors)
    diff_capture_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "diff_capture_schema_version": _LOCAL_POST_CODEX_DIFF_CAPTURE_SCHEMA_VERSION,
        "source_prompt": "prompt334",
        "status": local_post_codex_diff_capture_status,
        "blocked_reason": local_post_codex_diff_capture_blocked_reason,
        "next_action": route_next_action,
        "execution_repo_path": _normalize_text(execution_repo_path, default=""),
        "prompt333_result_path": str(prompt333_result_path),
        "prompt333_receipt_v2_path": str(prompt333_receipt_v2_path),
        "prompt333_stdout_path": str(prompt333_stdout_path),
        "prompt333_stderr_path": str(prompt333_stderr_path),
        "prompt333_result_exists": prompt333_result_exists,
        "prompt333_result_valid": prompt333_result_valid,
        "prompt333_receipt_v2_exists": prompt333_receipt_v2_exists,
        "prompt333_receipt_v2_valid": prompt333_receipt_v2_valid,
        "prompt333_validation_errors": prompt333_validation_errors_normalized,
        "changed_tracked_files": changed_tracked_files,
        "staged_tracked_files": staged_tracked_files,
        "unstaged_tracked_files": unstaged_tracked_files,
        "changed_tracked_file_count": changed_tracked_file_count,
        "staged_tracked_file_count": staged_tracked_file_count,
        "unstaged_tracked_file_count": unstaged_tracked_file_count,
        "worktree_clean_for_tracked_files": worktree_clean_for_tracked_files,
        "staged_changes_present": staged_changes_present,
        "unstaged_changes_present": unstaged_changes_present,
        "local_diff_present": local_diff_present,
        "local_diff_stat_text": local_diff_stat_text,
        "local_diff_name_status_lines": local_diff_name_status_lines,
        "local_diff_numstat_lines": local_diff_numstat_lines,
        "local_diff_name_only_lines": local_diff_name_only_lines,
        "status_short_lines": status_short_lines,
        "cached_diff_stat_text": _normalize_text(
            git_command_stdout.get("cached_diff_stat"),
            default="",
        ).strip(),
        "cached_diff_name_status_lines": [
            _normalize_text(line, default="").strip()
            for line in git_command_stdout.get("cached_diff_name_status", "").splitlines()
            if _normalize_text(line, default="").strip()
        ],
        "cached_diff_name_only_lines": staged_tracked_files,
        "git_diff_commands": {key: list(value) for key, value in git_commands.items()},
        "git_diff_command_exit_codes": dict(git_command_exit_codes),
        "stdout_exists": stdout_exists,
        "stderr_exists": stderr_exists,
        "stdout_size_bytes": stdout_size_bytes,
        "stderr_size_bytes": stderr_size_bytes,
        "stdout_head_lines": stdout_head_lines,
        "stderr_head_lines": stderr_head_lines,
        "stdout_contains_blocked": stdout_contains_blocked,
        "stdout_blocked_reason": stdout_blocked_reason,
        "local_post_codex_diff_capture_status": local_post_codex_diff_capture_status,
        "local_post_codex_diff_capture_blocked_reason": local_post_codex_diff_capture_blocked_reason,
        "local_post_codex_diff_capture_next_action": route_next_action,
        "local_post_codex_diff_capture_worktree_clean_for_tracked_files": (
            worktree_clean_for_tracked_files
        ),
        "local_post_codex_diff_capture_changed_tracked_file_count": changed_tracked_file_count,
        **safety_fields,
    }

    outcome_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "outcome_schema_version": _LOCAL_POST_CODEX_EXECUTION_OUTCOME_SCHEMA_VERSION,
        "source_prompt": "prompt334",
        "status": local_post_codex_outcome_status,
        "blocked_reason": prompt333_blocked_reason if not prompt333_ready else "none",
        "next_action": route_next_action,
        "prompt333_result_path": str(prompt333_result_path),
        "prompt333_receipt_v2_path": str(prompt333_receipt_v2_path),
        "execution_exit_code": prompt333_execution_exit_code,
        "stdout_contains_blocked": stdout_contains_blocked,
        "stdout_blocked_reason": stdout_blocked_reason,
        "changed_tracked_file_count": changed_tracked_file_count,
        "changed_tracked_files": changed_tracked_files,
        "codex_outcome_classification": codex_outcome_classification,
        "local_post_codex_outcome_status": local_post_codex_outcome_status,
        "local_post_codex_outcome_classification": codex_outcome_classification,
        "local_post_codex_stdout_contains_blocked": stdout_contains_blocked,
        "local_post_codex_stdout_blocked_reason": stdout_blocked_reason,
        **safety_fields,
    }

    route_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "route_decision_schema_version": _LOCAL_POST_CODEX_ROUTE_DECISION_SCHEMA_VERSION,
        "source_prompt": "prompt334",
        "status": local_post_codex_route_status,
        "blocked_reason": prompt333_blocked_reason if not prompt333_ready else "none",
        "codex_outcome_classification": codex_outcome_classification,
        "route_decision": route_decision,
        "next_action": route_next_action,
        "approve_commit_tag_allowed": approve_commit_tag_allowed,
        "targeted_contract_fix_recommended": targeted_contract_fix_recommended,
        "contract_fix_reason": contract_fix_reason,
        "local_post_codex_route_status": local_post_codex_route_status,
        "local_post_codex_route_decision": route_decision,
        "local_post_codex_route_next_action": route_next_action,
        "local_post_codex_route_targeted_contract_fix_recommended": (
            targeted_contract_fix_recommended
        ),
        "local_post_codex_route_approve_commit_tag_allowed": approve_commit_tag_allowed,
        **safety_fields,
    }

    artifact_write_status = {
        "local_post_codex_diff_capture_written": False,
        "local_post_codex_execution_outcome_written": False,
        "local_post_codex_route_decision_written": False,
    }
    artifact_write_errors: list[str] = []
    try:
        one_cycle_controller_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        artifact_write_errors.append("local_post_codex_artifact_directory_create_failed")
    else:
        try:
            _write_json(prompt334_diff_capture_path, diff_capture_payload)
            artifact_write_status["local_post_codex_diff_capture_written"] = True
        except OSError:
            artifact_write_errors.append("local_post_codex_diff_capture_write_failed")
        try:
            _write_json(prompt334_outcome_path, outcome_payload)
            artifact_write_status["local_post_codex_execution_outcome_written"] = True
        except OSError:
            artifact_write_errors.append("local_post_codex_execution_outcome_write_failed")
        try:
            _write_json(prompt334_route_path, route_payload)
            artifact_write_status["local_post_codex_route_decision_written"] = True
        except OSError:
            artifact_write_errors.append("local_post_codex_route_decision_write_failed")
        try:
            diff_stat_path.write_text(
                (local_diff_stat_text + "\n") if local_diff_stat_text else "",
                encoding="utf-8",
            )
            diff_name_status_path.write_text(
                ("\n".join(local_diff_name_status_lines) + "\n")
                if local_diff_name_status_lines
                else "",
                encoding="utf-8",
            )
            diff_patch_path.write_text("", encoding="utf-8")
        except OSError:
            pass

    receipt_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "diff_capture_schema_version": _LOCAL_POST_CODEX_DIFF_CAPTURE_SCHEMA_VERSION,
        "receipt_schema_version": "local_post_codex_diff_capture_receipt_v1",
        "source_prompt": "prompt334",
        "status": "completed" if not artifact_write_errors else "blocked",
        "blocked_reason": "none"
        if not artifact_write_errors
        else artifact_write_errors[0],
        "next_action": route_next_action,
        "artifact_paths": {
            "local_post_codex_diff_capture_path": str(prompt334_diff_capture_path),
            "local_post_codex_execution_outcome_path": str(prompt334_outcome_path),
            "local_post_codex_route_decision_path": str(prompt334_route_path),
            "local_post_codex_diff_capture_receipt_path": str(prompt334_receipt_path),
        },
        "artifact_write_status": artifact_write_status,
        "artifact_write_errors": artifact_write_errors,
        "codex_outcome_classification": codex_outcome_classification,
        "route_decision": route_decision,
        "route_next_action": route_next_action,
        "approve_commit_tag_allowed": approve_commit_tag_allowed,
        "targeted_contract_fix_recommended": targeted_contract_fix_recommended,
        "contract_fix_reason": contract_fix_reason,
        "local_post_codex_diff_capture_status": local_post_codex_diff_capture_status,
        "local_post_codex_diff_capture_blocked_reason": local_post_codex_diff_capture_blocked_reason,
        "local_post_codex_outcome_status": local_post_codex_outcome_status,
        "local_post_codex_outcome_classification": codex_outcome_classification,
        "local_post_codex_stdout_contains_blocked": stdout_contains_blocked,
        "local_post_codex_stdout_blocked_reason": stdout_blocked_reason,
        "local_post_codex_route_status": local_post_codex_route_status,
        "local_post_codex_route_decision": route_decision,
        "local_post_codex_route_next_action": route_next_action,
        "local_post_codex_route_targeted_contract_fix_recommended": (
            targeted_contract_fix_recommended
        ),
        "local_post_codex_route_approve_commit_tag_allowed": approve_commit_tag_allowed,
        **safety_fields,
    }
    try:
        _write_json(prompt334_receipt_path, receipt_payload)
    except OSError:
        pass

    completed_result_source_status = "available" if prompt333_ready else "not_completed"
    review_request_status = "not_started"
    review_request_blocked_reason = "prompt334_route_decision_boundary_only"

    return {
        "next_action": route_next_action,
        "diff_capture_status": local_post_codex_diff_capture_status,
        "diff_capture_blocked_reason": local_post_codex_diff_capture_blocked_reason,
        "diff_stat_path": str(diff_stat_path),
        "diff_name_status_path": str(diff_name_status_path),
        "diff_patch_path": str(diff_patch_path),
        "review_request_status": review_request_status,
        "review_request_blocked_reason": review_request_blocked_reason,
        "review_request_path": str(review_request_path),
        "review_handoff_path": str(review_handoff_path),
        "completed_result_source_path": str(completed_result_source_path),
        "completed_result_source_status": completed_result_source_status,
        "local_post_codex_diff_capture_status": local_post_codex_diff_capture_status,
        "local_post_codex_diff_capture_blocked_reason": local_post_codex_diff_capture_blocked_reason,
        "local_post_codex_diff_capture_next_action": route_next_action,
        "local_post_codex_diff_capture_worktree_clean_for_tracked_files": (
            worktree_clean_for_tracked_files
        ),
        "local_post_codex_diff_capture_changed_tracked_file_count": changed_tracked_file_count,
        "local_post_codex_outcome_status": local_post_codex_outcome_status,
        "local_post_codex_outcome_classification": codex_outcome_classification,
        "local_post_codex_stdout_contains_blocked": stdout_contains_blocked,
        "local_post_codex_stdout_blocked_reason": stdout_blocked_reason,
        "local_post_codex_route_status": local_post_codex_route_status,
        "local_post_codex_route_decision": route_decision,
        "local_post_codex_route_next_action": route_next_action,
        "local_post_codex_route_targeted_contract_fix_recommended": (
            targeted_contract_fix_recommended
        ),
        "local_post_codex_route_approve_commit_tag_allowed": approve_commit_tag_allowed,
        "local_post_codex_diff_capture_path": str(prompt334_diff_capture_path),
        "local_post_codex_execution_outcome_path": str(prompt334_outcome_path),
        "local_post_codex_route_decision_path": str(prompt334_route_path),
        "local_post_codex_diff_capture_receipt_path": str(prompt334_receipt_path),
    }


def _build_local_targeted_contract_fix_prompt_artifacts(
    *,
    one_cycle_controller_dir: Path,
) -> dict[str, Any]:
    def _prompt335_safety_fields() -> dict[str, Any]:
        return {
            "commit_allowed": False,
            "tag_allowed": False,
            "push_pr_merge_enabled": False,
            "targeted_fix_execution_allowed": False,
            "rollback_allowed": False,
            "commit_performed": False,
            "tag_performed": False,
            "push_performed": False,
            "pr_created": False,
            "merge_performed": False,
            "rollback_performed": False,
            "codex_invoked": False,
            "codex_invocation_allowed": False,
        }

    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _read_json_mapping(path: Path) -> tuple[bool, dict[str, Any]]:
        if not path.exists():
            return False, {}
        payload = _read_json_object_if_exists(path)
        if not isinstance(payload, Mapping):
            return True, {}
        return True, dict(payload)

    def _read_text(path: Path) -> tuple[bool, str]:
        if not path.exists():
            return False, ""
        try:
            return True, path.read_text(encoding="utf-8")
        except OSError:
            return True, ""

    def _extract_stdout_blocked_reason(stdout_text: str) -> tuple[bool, str]:
        lines = stdout_text.splitlines()
        contains_blocked = any(
            _normalize_text(line, default="").strip().upper().startswith("BLOCKED")
            for line in lines
        )
        blocked_reason = ""
        marker_index = -1
        for idx, raw_line in enumerate(lines):
            normalized = _normalize_text(raw_line, default="").strip().lower()
            if normalized.startswith("specific blocked reason"):
                marker_index = idx
                suffix = _normalize_text(raw_line, default="")
                if ":" in suffix:
                    maybe_reason = _normalize_text(
                        suffix.split(":", 1)[1],
                        default="",
                    ).strip()
                    if maybe_reason:
                        blocked_reason = maybe_reason
                break
        if marker_index >= 0 and not blocked_reason:
            for follow_line in lines[marker_index + 1 :]:
                maybe_reason = _normalize_text(follow_line, default="").strip()
                if maybe_reason:
                    blocked_reason = maybe_reason
                    break
        return contains_blocked, blocked_reason

    def _normalize_blocked_reason(value: Any) -> str:
        text = _normalize_text(value, default="").strip()
        for _ in range(8):
            prior = text
            text = text.strip()
            if text.startswith("**") and text.endswith("**") and len(text) >= 4:
                text = text[2:-2]
            elif text.startswith("__") and text.endswith("__") and len(text) >= 4:
                text = text[2:-2]
            elif text.startswith("`") and text.endswith("`") and len(text) >= 2:
                text = text[1:-1]
            elif text.startswith('"') and text.endswith('"') and len(text) >= 2:
                text = text[1:-1]
            elif text.startswith("'") and text.endswith("'") and len(text) >= 2:
                text = text[1:-1]
            text = text.strip().strip("`").strip().strip('"').strip("'").strip()
            if text == prior:
                break
        return text

    one_cycle_controller_dir = Path(one_cycle_controller_dir)
    prompt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt.md"
    prompt_plan_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_plan.json"
    prompt_receipt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_receipt.json"
    route_intake_path = one_cycle_controller_dir / "local_targeted_contract_fix_route_intake.json"

    prompt334_route_path = one_cycle_controller_dir / "local_post_codex_route_decision.json"
    prompt334_outcome_path = one_cycle_controller_dir / "local_post_codex_execution_outcome.json"
    prompt334_diff_receipt_path = one_cycle_controller_dir / "local_post_codex_diff_capture_receipt.json"
    prompt334_diff_capture_path = one_cycle_controller_dir / "local_post_codex_diff_capture.json"

    prompt333_stdout_path = one_cycle_controller_dir / "local_codex_one_shot_execution_stdout.txt"
    prompt333_stderr_path = one_cycle_controller_dir / "local_codex_one_shot_execution_stderr.txt"
    prompt333_result_path = one_cycle_controller_dir / "local_codex_one_shot_execution_result.json"
    prompt333_receipt_v2_path = (
        one_cycle_controller_dir / "local_codex_one_shot_execution_receipt_v2.json"
    )
    supported_blocked_reason = (
        "missing_explicit_allowed_tracked_files_and_conflicting_step_authority"
    )

    prompt334_route_exists, prompt334_route_payload = _read_json_mapping(prompt334_route_path)
    _, prompt334_outcome_payload = _read_json_mapping(prompt334_outcome_path)
    _, prompt334_diff_capture_payload = _read_json_mapping(prompt334_diff_capture_path)
    _, _ = _read_json_mapping(prompt334_diff_receipt_path)
    prompt333_result_exists, prompt333_result_payload = _read_json_mapping(prompt333_result_path)
    _, _ = _read_json_mapping(prompt333_receipt_v2_path)

    prompt333_stdout_exists, prompt333_stdout_text = _read_text(prompt333_stdout_path)
    _, _ = _read_text(prompt333_stderr_path)
    prompt333_stdout_contains_blocked, prompt333_stdout_blocked_reason_raw = (
        _extract_stdout_blocked_reason(prompt333_stdout_text)
    )

    prompt334_route_status = _normalize_text(prompt334_route_payload.get("status"), default="")
    prompt334_route_blocked_reason = _normalize_text(
        prompt334_route_payload.get("blocked_reason"),
        default="",
    )
    prompt334_route_decision = _normalize_text(prompt334_route_payload.get("route_decision"), default="")
    prompt334_route_next_action = _normalize_text(prompt334_route_payload.get("next_action"), default="")
    prompt334_codex_outcome_classification = _normalize_text(
        prompt334_route_payload.get("codex_outcome_classification"),
        default=_normalize_text(
            prompt334_outcome_payload.get("codex_outcome_classification"),
            default="",
        ),
    )
    prompt334_targeted_contract_fix_recommended = _as_boolish(
        prompt334_route_payload.get("targeted_contract_fix_recommended"),
        default=False,
    )
    prompt334_contract_fix_reason = _normalize_text(
        prompt334_route_payload.get("contract_fix_reason"),
        default="",
    )

    prompt334_stdout_contains_blocked = _as_boolish(
        prompt334_outcome_payload.get("local_post_codex_stdout_contains_blocked"),
        default=_as_boolish(
            prompt334_outcome_payload.get("stdout_contains_blocked"),
            default=_as_boolish(
                prompt334_diff_capture_payload.get("stdout_contains_blocked"),
                default=False,
            ),
        ),
    )
    prompt334_stdout_blocked_reason_raw = _normalize_text(
        prompt334_outcome_payload.get("local_post_codex_stdout_blocked_reason"),
        default=_normalize_text(
            prompt334_outcome_payload.get("stdout_blocked_reason"),
            default=_normalize_text(
                prompt334_diff_capture_payload.get("stdout_blocked_reason"),
                default="",
            ),
        ),
    )

    prompt333_result_status = _normalize_text(prompt333_result_payload.get("status"), default="")
    prompt333_execution_status = _normalize_text(
        prompt333_result_payload.get("execution_status"),
        default="",
    )
    prompt333_blocked_reason = _normalize_text(
        prompt333_result_payload.get("blocked_reason"),
        default="",
    )
    prompt333_execution_exit_code = _as_int(
        prompt333_result_payload.get("execution_exit_code"),
        default=-1,
    )
    prompt333_execution_result = _normalize_text(
        prompt333_result_payload.get("execution_result"),
        default="",
    )

    prompt334_stdout_blocked_reason = _normalize_blocked_reason(prompt334_stdout_blocked_reason_raw)
    prompt333_stdout_blocked_reason = _normalize_blocked_reason(prompt333_stdout_blocked_reason_raw)
    normalized_contract_fix_reason = _normalize_blocked_reason(prompt334_contract_fix_reason)
    if not normalized_contract_fix_reason:
        normalized_contract_fix_reason = prompt334_stdout_blocked_reason or prompt333_stdout_blocked_reason

    path_a_allowed_decisions = {
        "prepare_contract_handoff_fix",
        "prepare_blocked_with_changes_review",
    }

    path_a_ready = True
    path_a_blocked_reason = "none"
    if not prompt334_route_exists:
        path_a_ready = False
        path_a_blocked_reason = "missing_prompt334_route_decision_artifact"
    elif prompt334_route_status != "completed":
        path_a_ready = False
        path_a_blocked_reason = "prompt334_route_status_not_completed"
    elif prompt334_route_decision not in path_a_allowed_decisions:
        path_a_ready = False
        path_a_blocked_reason = "prompt334_route_decision_not_contract_fix_path"
    elif not prompt334_targeted_contract_fix_recommended:
        path_a_ready = False
        path_a_blocked_reason = "prompt334_targeted_contract_fix_not_recommended"
    elif not (normalized_contract_fix_reason or prompt334_stdout_blocked_reason):
        path_a_ready = False
        path_a_blocked_reason = "prompt334_contract_fix_reason_missing"

    path_b_candidate_reason = prompt334_stdout_blocked_reason or prompt333_stdout_blocked_reason
    path_b_ready = True
    path_b_blocked_reason = "none"
    if not prompt334_route_exists:
        path_b_ready = False
        path_b_blocked_reason = "missing_prompt334_route_decision_artifact"
    elif prompt334_route_status != "blocked":
        path_b_ready = False
        path_b_blocked_reason = "prompt334_route_status_not_blocked"
    elif "prompt333_execution_result_status_not_completed" not in prompt334_route_blocked_reason:
        path_b_ready = False
        path_b_blocked_reason = (
            "prompt334_route_blocked_reason_missing_prompt333_execution_not_completed_signal"
        )
    elif prompt334_codex_outcome_classification != "prompt333_execution_not_ready":
        path_b_ready = False
        path_b_blocked_reason = "prompt334_codex_outcome_classification_not_prompt333_execution_not_ready"
    elif not (prompt334_stdout_contains_blocked or prompt333_stdout_contains_blocked):
        path_b_ready = False
        path_b_blocked_reason = "blocked_stdout_signal_missing"
    elif path_b_candidate_reason != supported_blocked_reason:
        path_b_ready = False
        path_b_blocked_reason = "stdout_blocked_reason_not_supported_contract_fix_reason"

    route_intake_status = "blocked"
    route_intake_blocked_reason = "manual_review_contract_fix_route_intake"
    route_intake_readiness_reason = "contract_fix_signal_not_detected"
    contract_fix_signal_detected = False
    contract_fix_signal_source = "none"
    prompt333_artifact_lifecycle_issue_detected = False

    if path_a_ready:
        route_intake_status = "ready"
        route_intake_blocked_reason = "none"
        route_intake_readiness_reason = "contract_fix_signal_detected"
        contract_fix_signal_detected = True
        contract_fix_signal_source = "prompt334_route_decision"
    elif path_b_ready:
        route_intake_status = "ready"
        route_intake_blocked_reason = "none"
        route_intake_readiness_reason = "contract_fix_signal_detected"
        contract_fix_signal_detected = True
        contract_fix_signal_source = "prompt333_stdout_fallback"
        prompt333_artifact_lifecycle_issue_detected = True
        normalized_contract_fix_reason = path_b_candidate_reason
    else:
        if prompt334_route_status == "completed":
            route_intake_blocked_reason = path_a_blocked_reason
        elif prompt334_route_status == "blocked":
            route_intake_blocked_reason = path_b_blocked_reason
        else:
            route_intake_blocked_reason = (
                path_a_blocked_reason
                if path_a_blocked_reason != "none"
                else path_b_blocked_reason
            )

    route_intake_next_action = (
        "execute_targeted_contract_fix_prompt_adapter"
        if route_intake_status == "ready"
        else "manual_review_contract_fix_route_intake"
    )
    route_intake_validation_errors = (
        [] if route_intake_status == "ready" else [route_intake_blocked_reason]
    )

    safety_fields = _prompt335_safety_fields()
    route_intake_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "route_intake_schema_version": _LOCAL_TARGETED_CONTRACT_FIX_ROUTE_INTAKE_SCHEMA_VERSION,
        "status": route_intake_status,
        "route_intake_status": route_intake_status,
        "blocked_reason": route_intake_blocked_reason,
        "readiness_reason": route_intake_readiness_reason,
        "next_action": route_intake_next_action,
        "prompt334_route_status": prompt334_route_status,
        "prompt334_route_blocked_reason": prompt334_route_blocked_reason,
        "prompt334_route_decision": prompt334_route_decision,
        "prompt334_route_next_action": prompt334_route_next_action,
        "prompt334_codex_outcome_classification": prompt334_codex_outcome_classification,
        "prompt334_targeted_contract_fix_recommended": prompt334_targeted_contract_fix_recommended,
        "prompt334_contract_fix_reason": prompt334_contract_fix_reason,
        "prompt334_stdout_contains_blocked": prompt334_stdout_contains_blocked,
        "prompt334_stdout_blocked_reason": prompt334_stdout_blocked_reason,
        "prompt333_result_status": prompt333_result_status,
        "prompt333_execution_status": prompt333_execution_status,
        "prompt333_blocked_reason": prompt333_blocked_reason,
        "prompt333_execution_exit_code": prompt333_execution_exit_code,
        "prompt333_execution_result": prompt333_execution_result,
        "prompt333_stdout_exists": prompt333_stdout_exists,
        "prompt333_stdout_contains_blocked": prompt333_stdout_contains_blocked,
        "prompt333_stdout_blocked_reason": prompt333_stdout_blocked_reason,
        "prompt333_artifact_lifecycle_issue_detected": prompt333_artifact_lifecycle_issue_detected,
        "contract_fix_signal_detected": contract_fix_signal_detected,
        "contract_fix_signal_source": contract_fix_signal_source,
        "validation_errors": route_intake_validation_errors,
        **safety_fields,
    }

    prompt_text = ""
    prompt_write_errors: list[str] = []
    try:
        one_cycle_controller_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        prompt_write_errors.append("prompt335_artifact_directory_create_failed")

    if route_intake_status == "ready":
        prompt_text = "\n".join(
            [
                "# Prompt335 Local Targeted Contract-Fix Handoff",
                "",
                "Mode: Repair",
                "",
                "Goal:",
                "Implement a minimal correction for the local one-shot handoff contract so the next Prompt333/334/335 cycle no longer blocks on missing explicit tracked-file allowlist or conflicting selected-step authority.",
                "",
                "Allowed files:",
                "- automation/orchestration/planned_execution_runner.py",
                "",
                "Forbidden files:",
                "- docs/**",
                "- tests/**",
                "- scripts/**",
                "- runtime logs",
                "- generated artifacts outside normal runner artifact output behavior",
                "",
                "Expected artifact/output:",
                "- Minimal code update in automation/orchestration/planned_execution_runner.py that updates the Prompt332/333/334 contract surfaces and keeps Prompt333 command argv contract validation intact.",
                "",
                "Allowed validation commands:",
                "- none",
                "",
                "Out of scope:",
                "- running tests or py_compile",
                "- invoking Codex",
                "- executing this generated prompt",
                "- commit/tag/push/PR/merge operations",
                "- rollback",
                "- Prompt336 bounded cycle controller",
                "- Prompt337 daemon-lite wrapper",
                "- retry loops, sleep loops, polling loops, or unbounded execution",
                "",
                "Correction objective:",
                "1. Prompt332 handoff prompt must include explicit_allowed_tracked_files.",
                "2. Mutation-capable selected steps must include a deterministic non-empty explicit_allowed_tracked_files list.",
                "3. Read-only/no-mutation steps must set explicit_allowed_tracked_files=[] and mutation_allowed=false.",
                "4. For generate_next_codex_task handoff, explicit_allowed_tracked_files must be exactly ['automation/orchestration/planned_execution_runner.py'].",
                "5. Handoff prompt must not request tracked file mutation without explicit allowlist coverage.",
                "6. Selected-step authority must come from Prompt331 v2 local_autonomous_cycle_v2_decision and must not conflict with stale local_end_to_end_one_shot_step_selection when stale/blocked.",
                "7. Add and propagate fields as needed: selected_step_authority_source, selected_step_authority_artifact, selected_step_authority_status, explicit_allowed_tracked_files, mutation_allowed, stale_step_selection_conflict_detected, stale_step_selection_artifact_path, stale_step_selection_status, contract_fix_applied.",
                "8. Prompt333 validation must tolerate the added contract fields while preserving exact command argv validation.",
                "9. Prompt334 must keep classifying stdout BLOCKED; after this fix, clean rerun should no longer block for missing explicit allowed tracked files or conflicting step authority.",
                "",
                "Deterministic authority contract:",
                "- selected_step_authority_source: prompt331_v2_local_autonomous_cycle_v2_decision",
                "- selected_step_authority_artifact: /tmp/codex-local-runner-decision/one_cycle_controller/local_autonomous_cycle_v2_decision.json",
                "- explicit_allowed_tracked_files: ['automation/orchestration/planned_execution_runner.py']",
                "- mutation_allowed: true",
            ]
        ) + "\n"
    else:
        prompt_text = "\n".join(
            [
                "# Prompt335 Local Targeted Contract-Fix Handoff (Blocked)",
                "",
                "DO NOT EXECUTE.",
                "",
                f"- Route intake status: `{route_intake_status}`",
                f"- Blocked reason: `{route_intake_blocked_reason}`",
                "- Next action: `manual_review_contract_fix_route_intake`",
            ]
        ) + "\n"

    if not prompt_write_errors:
        try:
            prompt_path.write_text(prompt_text, encoding="utf-8")
        except OSError:
            prompt_write_errors.append("local_targeted_contract_fix_prompt_write_failed")

    prompt_exists = prompt_path.exists()
    prompt_non_empty = False
    prompt_size_bytes = 0
    generated_prompt_line_count = 0
    generated_prompt_sha256 = ""
    if prompt_exists:
        try:
            prompt_size_bytes = _as_non_negative_int(prompt_path.stat().st_size, default=0)
        except OSError:
            prompt_size_bytes = 0
        try:
            prompt_text_now = prompt_path.read_text(encoding="utf-8")
        except OSError:
            prompt_text_now = ""
        prompt_non_empty = bool(prompt_text_now.strip())
        generated_prompt_line_count = len(prompt_text_now.splitlines())
        generated_prompt_sha256 = (
            hashlib.sha256(prompt_text_now.encode("utf-8")).hexdigest()
            if prompt_text_now
            else ""
        )

    plan_status = "blocked"
    plan_blocked_reason = route_intake_blocked_reason
    plan_readiness_reason = "contract_fix_signal_not_ready_for_prompt_generation"
    plan_next_action = "manual_review_contract_fix_route_intake"
    if (
        route_intake_status == "ready"
        and prompt_exists
        and prompt_non_empty
        and not prompt_write_errors
    ):
        plan_status = "ready"
        plan_blocked_reason = "none"
        plan_readiness_reason = "contract_fix_signal_detected_and_prompt_generated"
        plan_next_action = "execute_targeted_contract_fix_prompt_adapter"
    elif route_intake_status == "ready" and prompt_write_errors:
        plan_blocked_reason = prompt_write_errors[0]

    stale_step_selection_conflict_detected = (
        normalized_contract_fix_reason == supported_blocked_reason
    )
    correction_objective = (
        "Fix one-shot handoff contract boundaries for explicit tracked file scope and authoritative selected-step source."
    )

    plan_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "fix_prompt_plan_schema_version": (
            _LOCAL_TARGETED_CONTRACT_FIX_PROMPT_PLAN_SCHEMA_VERSION
        ),
        "status": plan_status,
        "blocked_reason": plan_blocked_reason,
        "readiness_reason": plan_readiness_reason,
        "route_intake_status": route_intake_status,
        "contract_fix_signal_detected": contract_fix_signal_detected,
        "contract_fix_signal_source": contract_fix_signal_source,
        "normalized_contract_fix_reason": normalized_contract_fix_reason,
        "prompt_path": str(prompt_path),
        "prompt_exists": prompt_exists,
        "prompt_non_empty": prompt_non_empty,
        "correction_objective": correction_objective,
        "explicit_allowed_tracked_files": ["automation/orchestration/planned_execution_runner.py"],
        "selected_step_authority_source": "prompt331_v2_local_autonomous_cycle_v2_decision",
        "selected_step_authority_artifact": str(_LOCAL_AUTONOMOUS_CYCLE_V2_DECISION_PATH),
        "stale_step_selection_conflict_detected": stale_step_selection_conflict_detected,
        "prompt333_artifact_lifecycle_issue_detected": prompt333_artifact_lifecycle_issue_detected,
        "next_action": plan_next_action,
        "validation_errors": [] if plan_status == "ready" else [plan_blocked_reason],
        **safety_fields,
    }

    receipt_status = "ready" if plan_status == "ready" else "blocked"
    receipt_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "fix_prompt_receipt_schema_version": (
            _LOCAL_TARGETED_CONTRACT_FIX_PROMPT_RECEIPT_SCHEMA_VERSION
        ),
        "status": receipt_status,
        "blocked_reason": "none" if receipt_status == "ready" else plan_blocked_reason,
        "readiness_reason": (
            "contract_fix_signal_detected_and_prompt_generated"
            if receipt_status == "ready"
            else "contract_fix_signal_not_ready_for_prompt_generation"
        ),
        "prompt_path": str(prompt_path),
        "prompt_exists": prompt_exists,
        "prompt_non_empty": prompt_non_empty,
        "generated_prompt_sha256": generated_prompt_sha256,
        "generated_prompt_line_count": generated_prompt_line_count,
        "generated_prompt_size_bytes": prompt_size_bytes,
        "route_intake_path": str(route_intake_path),
        "fix_prompt_plan_path": str(prompt_plan_path),
        "next_action": plan_next_action,
        "validation_errors": [] if receipt_status == "ready" else [plan_blocked_reason],
        **safety_fields,
    }

    json_write_errors: list[str] = []
    try:
        _write_json(route_intake_path, route_intake_payload)
    except OSError:
        json_write_errors.append("local_targeted_contract_fix_route_intake_write_failed")
    try:
        _write_json(prompt_plan_path, plan_payload)
    except OSError:
        json_write_errors.append("local_targeted_contract_fix_prompt_plan_write_failed")
    try:
        _write_json(prompt_receipt_path, receipt_payload)
    except OSError:
        json_write_errors.append("local_targeted_contract_fix_prompt_receipt_write_failed")
    prompt_write_errors.extend(json_write_errors)

    if prompt_write_errors:
        if plan_status == "ready":
            plan_status = "blocked"
            plan_blocked_reason = prompt_write_errors[0]
            plan_next_action = "manual_review_contract_fix_route_intake"
        receipt_status = "blocked"

    return {
        "route_intake_status": route_intake_status,
        "route_intake_blocked_reason": route_intake_blocked_reason,
        "route_intake_signal_source": contract_fix_signal_source,
        "prompt_plan_status": plan_status,
        "prompt_plan_blocked_reason": plan_blocked_reason,
        "prompt_path": str(prompt_path),
        "prompt_ready": plan_status == "ready",
        "prompt_next_action": plan_next_action,
        "prompt_normalized_reason": normalized_contract_fix_reason,
        "prompt_lifecycle_issue_detected": prompt333_artifact_lifecycle_issue_detected,
        "route_intake_path": str(route_intake_path),
        "prompt_plan_path": str(prompt_plan_path),
        "prompt_receipt_path": str(prompt_receipt_path),
    }


def _build_local_contract_fix_cycle_coordination_artifacts(
    *,
    one_cycle_controller_dir: Path,
) -> dict[str, Any]:
    def _prompt336_safety_fields() -> dict[str, Any]:
        return {
            "commit_allowed": False,
            "tag_allowed": False,
            "push_pr_merge_enabled": False,
            "targeted_fix_execution_allowed": False,
            "rollback_allowed": False,
            "commit_performed": False,
            "tag_performed": False,
            "push_performed": False,
            "pr_created": False,
            "merge_performed": False,
            "rollback_performed": False,
            "codex_invoked": False,
            "codex_invocation_allowed": False,
        }

    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _read_json_mapping(path: Path) -> tuple[bool, dict[str, Any]]:
        if not path.exists():
            return False, {}
        payload = _read_json_object_if_exists(path)
        if not isinstance(payload, Mapping):
            return True, {}
        return True, dict(payload)

    one_cycle_controller_dir = Path(one_cycle_controller_dir)
    route_intake_path = one_cycle_controller_dir / "local_targeted_contract_fix_route_intake.json"
    prompt_plan_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_plan.json"
    prompt_receipt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_receipt.json"
    prompt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt.md"
    coordination_state_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_state.json"
    )
    coordination_decision_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_decision.json"
    )
    coordination_receipt_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_receipt.json"
    )
    execution_handoff_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_execution_handoff.json"
    )

    required_reason = "missing_explicit_allowed_tracked_files_and_conflicting_step_authority"
    allowed_tracked_file = "automation/orchestration/planned_execution_runner.py"

    route_intake_exists, route_intake_payload = _read_json_mapping(route_intake_path)
    prompt_plan_exists, prompt_plan_payload = _read_json_mapping(prompt_plan_path)
    prompt_receipt_exists, prompt_receipt_payload = _read_json_mapping(prompt_receipt_path)

    route_intake_status = _normalize_text(route_intake_payload.get("status"), default="missing")
    contract_fix_signal_source = _normalize_text(
        prompt_plan_payload.get("contract_fix_signal_source"),
        default=_normalize_text(
            route_intake_payload.get("contract_fix_signal_source"),
            default="none",
        ),
    )
    prompt335_plan_status = _normalize_text(prompt_plan_payload.get("status"), default="missing")
    prompt335_plan_blocked_reason = _normalize_text(
        prompt_plan_payload.get("blocked_reason"),
        default="missing_prompt335_prompt_plan_artifact",
    )
    prompt335_receipt_status = _normalize_text(
        prompt_receipt_payload.get("status"),
        default="missing",
    )
    prompt335_receipt_blocked_reason = _normalize_text(
        prompt_receipt_payload.get("blocked_reason"),
        default="missing_prompt335_prompt_receipt_artifact",
    )
    contract_fix_signal_detected = _as_boolish(
        prompt_plan_payload.get("contract_fix_signal_detected"),
        default=False,
    )
    normalized_contract_fix_reason = _normalize_text(
        prompt_plan_payload.get("normalized_contract_fix_reason"),
        default="",
    )

    plan_prompt_path = _normalize_text(
        prompt_plan_payload.get("prompt_path"),
        default=str(prompt_path),
    )
    plan_prompt_exists = _as_boolish(prompt_plan_payload.get("prompt_exists"), default=False)
    plan_prompt_non_empty = _as_boolish(
        prompt_plan_payload.get("prompt_non_empty"),
        default=False,
    )
    plan_next_action = _normalize_text(prompt_plan_payload.get("next_action"), default="")

    receipt_prompt_exists = _as_boolish(prompt_receipt_payload.get("prompt_exists"), default=False)
    receipt_prompt_non_empty = _as_boolish(
        prompt_receipt_payload.get("prompt_non_empty"),
        default=False,
    )
    generated_prompt_sha256 = _normalize_text(
        prompt_receipt_payload.get("generated_prompt_sha256"),
        default="",
    )
    generated_prompt_size_bytes = _as_non_negative_int(
        prompt_receipt_payload.get("generated_prompt_size_bytes"),
        default=0,
    )
    generated_prompt_line_count = _as_non_negative_int(
        prompt_receipt_payload.get("generated_prompt_line_count"),
        default=0,
    )

    prompt_exists = prompt_path.exists()
    prompt_text = ""
    if prompt_exists:
        try:
            prompt_text = prompt_path.read_text(encoding="utf-8")
        except OSError:
            prompt_text = ""
    prompt_non_empty = bool(prompt_text.strip())
    prompt_size_bytes = len(prompt_text.encode("utf-8"))
    prompt_line_count = len(prompt_text.splitlines())
    prompt_sha256 = hashlib.sha256(prompt_text.encode("utf-8")).hexdigest() if prompt_text else ""
    prompt_lines = prompt_text.splitlines()
    prompt_first_80_lines_text = "\n".join(prompt_lines[:80])

    blocked_reason = "none"
    prompt_content_validation_errors: list[str] = []
    prompt_content_validation_status = "not_checked"

    if not route_intake_exists:
        blocked_reason = "missing_prompt335_route_intake_artifact"
    elif not prompt_plan_exists:
        blocked_reason = "missing_prompt335_prompt_plan_artifact"
    elif prompt335_plan_status != "ready":
        blocked_reason = "prompt335_plan_status_not_ready"
    elif prompt335_plan_blocked_reason != "none":
        blocked_reason = "prompt335_plan_blocked_reason_not_none"
    elif not contract_fix_signal_detected:
        blocked_reason = "prompt335_contract_fix_signal_not_detected"
    elif not normalized_contract_fix_reason:
        blocked_reason = "prompt335_normalized_contract_fix_reason_missing"
    elif plan_prompt_path != str(prompt_path):
        blocked_reason = "prompt335_prompt_path_mismatch"
    elif not plan_prompt_exists:
        blocked_reason = "prompt335_prompt_exists_false"
    elif not plan_prompt_non_empty:
        blocked_reason = "prompt335_prompt_non_empty_false"
    elif plan_next_action != "execute_targeted_contract_fix_prompt_adapter":
        blocked_reason = "prompt335_plan_next_action_not_execute_targeted_contract_fix_prompt_adapter"
    elif not prompt_receipt_exists:
        blocked_reason = "missing_prompt335_prompt_receipt_artifact"
    elif prompt335_receipt_status != "ready":
        blocked_reason = "prompt335_receipt_status_not_ready"
    elif prompt335_receipt_blocked_reason != "none":
        blocked_reason = "prompt335_receipt_blocked_reason_not_none"
    elif not receipt_prompt_exists:
        blocked_reason = "prompt335_receipt_prompt_exists_false"
    elif not receipt_prompt_non_empty:
        blocked_reason = "prompt335_receipt_prompt_non_empty_false"
    elif not generated_prompt_sha256:
        blocked_reason = "prompt335_receipt_generated_prompt_sha256_missing"
    elif generated_prompt_size_bytes <= 0:
        blocked_reason = "prompt335_receipt_generated_prompt_size_bytes_not_positive"
    elif generated_prompt_line_count <= 0:
        blocked_reason = "prompt335_receipt_generated_prompt_line_count_not_positive"
    else:
        prompt_content_validation_status = "passed"
        if not prompt_exists:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_file_missing"]
        elif not prompt_non_empty:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_file_empty"]
        elif "DO NOT EXECUTE" in prompt_first_80_lines_text.upper():
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_contains_do_not_execute_in_first_80_lines"]
        elif "Modify only automation/orchestration/planned_execution_runner.py" not in prompt_text:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_missing_modify_only_allowed_file_instruction"]
        elif "Do not run tests" not in prompt_text:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_missing_do_not_run_tests_instruction"]
        elif "Do not invoke Codex" not in prompt_text:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_missing_do_not_invoke_codex_instruction"]
        elif required_reason not in prompt_text:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_missing_normalized_contract_fix_reason"]
        elif allowed_tracked_file not in prompt_text:
            prompt_content_validation_status = "failed"
            prompt_content_validation_errors = ["prompt_missing_explicit_allowed_tracked_file_scope"]
        if prompt_content_validation_errors:
            blocked_reason = prompt_content_validation_errors[0]

    status = "ready" if blocked_reason == "none" else "blocked"
    coordination_status = status
    contract_fix_cycle_ready = status == "ready"
    readiness_reason = (
        "targeted_contract_fix_prompt_ready_for_bounded_execution_handoff"
        if status == "ready"
        else "targeted_contract_fix_prompt_not_ready"
    )
    selected_step_id = 3 if status == "ready" else 0
    selected_step_name = "execute_targeted_contract_fix_prompt" if status == "ready" else "none"
    selected_step_operation = (
        "execute_targeted_contract_fix_prompt" if status == "ready" else "none"
    )
    selected_step_authority_source = (
        "prompt335_targeted_contract_fix_prompt_plan" if status == "ready" else "none"
    )
    selected_step_authority_artifact = str(prompt_plan_path)
    explicit_allowed_tracked_files = [allowed_tracked_file]
    mutation_allowed = status == "ready"
    execution_allowed = False
    next_action = (
        "prepare_prompt337_local_daemon_lite_wrapper"
        if status == "ready"
        else "manual_review_targeted_contract_fix_prompt"
    )
    validation_errors = [] if status == "ready" else [blocked_reason]

    handoff_status = "ready" if status == "ready" else "blocked"
    handoff_readiness_reason = (
        "bounded_contract_fix_cycle_ready_for_prompt337"
        if handoff_status == "ready"
        else "bounded_contract_fix_cycle_not_ready"
    )
    handoff_next_action = (
        "prompt337_may_execute_targeted_contract_fix_once"
        if handoff_status == "ready"
        else "manual_review_targeted_contract_fix_prompt"
    )

    safety_fields = _prompt336_safety_fields()
    coordination_payload_base: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "status": status,
        "coordination_status": coordination_status,
        "blocked_reason": blocked_reason,
        "readiness_reason": readiness_reason,
        "contract_fix_cycle_ready": contract_fix_cycle_ready,
        "prompt335_plan_status": prompt335_plan_status,
        "prompt335_plan_blocked_reason": prompt335_plan_blocked_reason,
        "prompt335_receipt_status": prompt335_receipt_status,
        "prompt335_receipt_blocked_reason": prompt335_receipt_blocked_reason,
        "route_intake_status": route_intake_status,
        "contract_fix_signal_detected": contract_fix_signal_detected,
        "contract_fix_signal_source": contract_fix_signal_source,
        "normalized_contract_fix_reason": normalized_contract_fix_reason,
        "prompt_path": str(prompt_path),
        "prompt_exists": prompt_exists,
        "prompt_non_empty": prompt_non_empty,
        "prompt_sha256": prompt_sha256,
        "prompt_size_bytes": prompt_size_bytes,
        "prompt_line_count": prompt_line_count,
        "prompt_content_validation_status": prompt_content_validation_status,
        "prompt_content_validation_errors": prompt_content_validation_errors,
        "current_cycle": _LOCAL_AUTONOMOUS_CYCLE_V2_CURRENT_CYCLE,
        "max_cycles": _LOCAL_AUTONOMOUS_CYCLE_V2_MAX_CYCLES,
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "selected_step_authority_source": selected_step_authority_source,
        "selected_step_authority_artifact": selected_step_authority_artifact,
        "explicit_allowed_tracked_files": explicit_allowed_tracked_files,
        "mutation_allowed": mutation_allowed,
        "execution_allowed": execution_allowed,
        "execution_handoff_status": handoff_status,
        "max_codex_invocations": 1,
        "codex_invocation_count": 0,
        "next_action": next_action,
        "validation_errors": validation_errors,
        **safety_fields,
    }

    coordination_state_payload = {
        **coordination_payload_base,
        "coordination_state_schema_version": (
            _LOCAL_CONTRACT_FIX_CYCLE_COORDINATION_STATE_SCHEMA_VERSION
        ),
    }
    coordination_decision_payload = {
        **coordination_payload_base,
        "coordination_decision_schema_version": (
            _LOCAL_CONTRACT_FIX_CYCLE_COORDINATION_DECISION_SCHEMA_VERSION
        ),
    }
    coordination_receipt_payload = {
        **coordination_payload_base,
        "coordination_receipt_schema_version": (
            _LOCAL_CONTRACT_FIX_CYCLE_COORDINATION_RECEIPT_SCHEMA_VERSION
        ),
    }

    execution_handoff_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "execution_handoff_schema_version": (
            _LOCAL_CONTRACT_FIX_CYCLE_EXECUTION_HANDOFF_SCHEMA_VERSION
        ),
        "status": handoff_status,
        "handoff_status": handoff_status,
        "blocked_reason": blocked_reason,
        "readiness_reason": handoff_readiness_reason,
        "execution_allowed": False,
        "codex_invocation_allowed": False,
        "prompt_path": str(prompt_path),
        "prompt_exists": prompt_exists,
        "prompt_non_empty": prompt_non_empty,
        "command_argv": [],
        "command_display": "",
        "max_codex_invocations": 1,
        "codex_invocation_count": 0,
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "explicit_allowed_tracked_files": explicit_allowed_tracked_files,
        "mutation_allowed": mutation_allowed,
        "next_action": handoff_next_action,
        "validation_errors": [] if handoff_status == "ready" else [blocked_reason],
        **safety_fields,
    }

    try:
        one_cycle_controller_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    try:
        _write_json(coordination_state_path, coordination_state_payload)
    except OSError:
        pass
    try:
        _write_json(coordination_decision_path, coordination_decision_payload)
    except OSError:
        pass
    try:
        _write_json(coordination_receipt_path, coordination_receipt_payload)
    except OSError:
        pass
    try:
        _write_json(execution_handoff_path, execution_handoff_payload)
    except OSError:
        pass

    return {
        "coordination_status": coordination_status,
        "coordination_blocked_reason": blocked_reason,
        "coordination_ready": contract_fix_cycle_ready,
        "coordination_next_action": next_action,
        "coordination_prompt_path": str(prompt_path),
        "coordination_prompt_ready": prompt_exists and prompt_non_empty and status == "ready",
        "coordination_normalized_reason": normalized_contract_fix_reason,
        "coordination_selected_step_name": selected_step_name,
        "handoff_status": handoff_status,
        "handoff_next_action": handoff_next_action,
        "coordination_state_path": str(coordination_state_path),
        "coordination_decision_path": str(coordination_decision_path),
        "coordination_receipt_path": str(coordination_receipt_path),
        "execution_handoff_path": str(execution_handoff_path),
    }


def _build_local_daemon_lite_wrapper_artifacts(
    *,
    one_cycle_controller_dir: Path,
) -> dict[str, Any]:
    def _prompt337_safety_fields() -> dict[str, Any]:
        return {
            "commit_allowed": False,
            "tag_allowed": False,
            "push_pr_merge_enabled": False,
            "targeted_fix_execution_allowed": False,
            "rollback_allowed": False,
            "commit_performed": False,
            "tag_performed": False,
            "push_performed": False,
            "pr_created": False,
            "merge_performed": False,
            "rollback_performed": False,
            "codex_invoked": False,
            "codex_invocation_allowed": False,
            "execution_allowed": False,
        }

    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _read_json_mapping(path: Path) -> tuple[bool, dict[str, Any]]:
        if not path.exists():
            return False, {}
        payload = _read_json_object_if_exists(path)
        if not isinstance(payload, Mapping):
            return True, {}
        return True, dict(payload)

    one_cycle_controller_dir = Path(one_cycle_controller_dir)
    prompt336_coordination_state_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_state.json"
    )
    prompt336_coordination_decision_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_decision.json"
    )
    prompt336_coordination_receipt_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_coordination_receipt.json"
    )
    prompt336_handoff_path = (
        one_cycle_controller_dir / "local_contract_fix_cycle_execution_handoff.json"
    )
    prompt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt.md"

    daemon_lite_state_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_state.json"
    daemon_lite_plan_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_plan.json"
    daemon_lite_decision_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_decision.json"
    daemon_lite_receipt_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_receipt.json"

    prompt336_handoff_exists, prompt336_handoff_payload = _read_json_mapping(prompt336_handoff_path)
    (
        prompt336_coordination_state_exists,
        prompt336_coordination_state_payload,
    ) = _read_json_mapping(prompt336_coordination_state_path)
    (
        prompt336_coordination_decision_exists,
        prompt336_coordination_decision_payload,
    ) = _read_json_mapping(prompt336_coordination_decision_path)
    (
        prompt336_coordination_receipt_exists,
        prompt336_coordination_receipt_payload,
    ) = _read_json_mapping(prompt336_coordination_receipt_path)

    prompt336_handoff_status = _normalize_text(
        prompt336_handoff_payload.get("status"),
        default="missing",
    )
    prompt336_handoff_handoff_status = _normalize_text(
        prompt336_handoff_payload.get("handoff_status"),
        default=prompt336_handoff_status,
    )
    prompt336_handoff_blocked_reason = _normalize_text(
        prompt336_handoff_payload.get("blocked_reason"),
        default=(
            "missing_local_contract_fix_cycle_execution_handoff"
            if not prompt336_handoff_exists
            else "prompt336_handoff_blocked_or_invalid"
        ),
    )
    prompt336_handoff_readiness_reason = _normalize_text(
        prompt336_handoff_payload.get("readiness_reason"),
        default="",
    )
    prompt336_handoff_next_action = _normalize_text(
        prompt336_handoff_payload.get("next_action"),
        default="manual_review_contract_fix_cycle_handoff",
    )
    prompt336_selected_step_id = _as_int(
        prompt336_handoff_payload.get("selected_step_id"),
        default=0,
    )
    prompt336_selected_step_name = _normalize_text(
        prompt336_handoff_payload.get("selected_step_name"),
        default="none",
    )
    prompt336_selected_step_operation = _normalize_text(
        prompt336_handoff_payload.get("selected_step_operation"),
        default="none",
    )
    prompt336_prompt_path = _normalize_text(
        prompt336_handoff_payload.get("prompt_path"),
        default=str(prompt_path),
    )
    prompt336_prompt_exists = _as_boolish(
        prompt336_handoff_payload.get("prompt_exists"),
        default=False,
    )
    prompt336_prompt_non_empty = _as_boolish(
        prompt336_handoff_payload.get("prompt_non_empty"),
        default=False,
    )
    prompt336_explicit_allowed_tracked_files = _normalize_string_list(
        prompt336_handoff_payload.get("explicit_allowed_tracked_files")
    )
    prompt336_mutation_allowed = _as_boolish(
        prompt336_handoff_payload.get("mutation_allowed"),
        default=False,
    )
    prompt336_execution_allowed = _as_boolish(
        prompt336_handoff_payload.get("execution_allowed"),
        default=False,
    )
    prompt336_codex_invocation_allowed = _as_boolish(
        prompt336_handoff_payload.get("codex_invocation_allowed"),
        default=False,
    )
    prompt336_command_argv_raw = prompt336_handoff_payload.get("command_argv")
    prompt336_command_argv: list[str] = []
    if isinstance(prompt336_command_argv_raw, list):
        prompt336_command_argv = [
            _normalize_text(item, default="") for item in prompt336_command_argv_raw
        ]
    prompt336_command_display = _normalize_text(
        prompt336_handoff_payload.get("command_display"),
        default="",
    )
    prompt336_max_codex_invocations = _as_non_negative_int(
        prompt336_handoff_payload.get("max_codex_invocations"),
        default=0,
    )
    prompt336_codex_invocation_count = _as_non_negative_int(
        prompt336_handoff_payload.get("codex_invocation_count"),
        default=0,
    )

    prompt336_coordination_status = _normalize_text(
        prompt336_coordination_state_payload.get("coordination_status"),
        default=_normalize_text(
            prompt336_coordination_decision_payload.get("coordination_status"),
            default=_normalize_text(
                prompt336_coordination_receipt_payload.get("coordination_status"),
                default="missing",
            ),
        ),
    )
    prompt336_coordination_blocked_reason = _normalize_text(
        prompt336_coordination_state_payload.get("blocked_reason"),
        default=_normalize_text(
            prompt336_coordination_decision_payload.get("blocked_reason"),
            default=_normalize_text(
                prompt336_coordination_receipt_payload.get("blocked_reason"),
                default=(
                    "missing_local_contract_fix_cycle_coordination_state"
                    if not prompt336_coordination_state_exists
                    else "none"
                ),
            ),
        ),
    )
    prompt336_contract_fix_cycle_ready = _as_boolish(
        prompt336_coordination_state_payload.get("contract_fix_cycle_ready"),
        default=_as_boolish(
            prompt336_coordination_decision_payload.get("contract_fix_cycle_ready"),
            default=_as_boolish(
                prompt336_coordination_receipt_payload.get("contract_fix_cycle_ready"),
                default=False,
            ),
        ),
    )

    blocked_reason = "none"
    expected_prompt_path = str(prompt_path)
    expected_allowed_tracked_files = ["automation/orchestration/planned_execution_runner.py"]

    if not prompt336_handoff_exists:
        blocked_reason = "missing_prompt336_execution_handoff_artifact"
    elif prompt336_handoff_status != "ready":
        blocked_reason = "prompt336_handoff_status_not_ready"
    elif prompt336_handoff_handoff_status != "ready":
        blocked_reason = "prompt336_handoff_handoff_status_not_ready"
    elif prompt336_handoff_blocked_reason != "none":
        blocked_reason = "prompt336_handoff_blocked_reason_not_none"
    elif prompt336_handoff_readiness_reason != "bounded_contract_fix_cycle_ready_for_prompt337":
        blocked_reason = "prompt336_handoff_readiness_reason_not_ready_for_prompt337"
    elif prompt336_handoff_next_action != "prompt337_may_execute_targeted_contract_fix_once":
        blocked_reason = "prompt336_handoff_next_action_not_prompt337_single_execution"
    elif prompt336_selected_step_id != 3:
        blocked_reason = "prompt336_handoff_selected_step_id_not_3"
    elif prompt336_selected_step_name != "execute_targeted_contract_fix_prompt":
        blocked_reason = "prompt336_handoff_selected_step_name_not_execute_targeted_contract_fix_prompt"
    elif prompt336_selected_step_operation != "execute_targeted_contract_fix_prompt":
        blocked_reason = (
            "prompt336_handoff_selected_step_operation_not_execute_targeted_contract_fix_prompt"
        )
    elif prompt336_prompt_path != expected_prompt_path:
        blocked_reason = "prompt336_handoff_prompt_path_mismatch"
    elif not prompt336_prompt_exists:
        blocked_reason = "prompt336_handoff_prompt_exists_false"
    elif not prompt336_prompt_non_empty:
        blocked_reason = "prompt336_handoff_prompt_non_empty_false"
    elif prompt336_explicit_allowed_tracked_files != expected_allowed_tracked_files:
        blocked_reason = "prompt336_handoff_explicit_allowed_tracked_files_mismatch"
    elif not prompt336_mutation_allowed:
        blocked_reason = "prompt336_handoff_mutation_allowed_false"
    elif prompt336_execution_allowed:
        blocked_reason = "prompt336_handoff_execution_allowed_true"
    elif prompt336_codex_invocation_allowed:
        blocked_reason = "prompt336_handoff_codex_invocation_allowed_true"
    elif prompt336_command_argv:
        blocked_reason = "prompt336_handoff_command_argv_not_empty"
    elif prompt336_command_display:
        blocked_reason = "prompt336_handoff_command_display_not_empty"
    elif prompt336_max_codex_invocations != 1:
        blocked_reason = "prompt336_handoff_max_codex_invocations_not_1"
    elif prompt336_codex_invocation_count != 0:
        blocked_reason = "prompt336_handoff_codex_invocation_count_not_0"

    supporting_expectations: tuple[tuple[str, Any, str], ...] = (
        ("status", "ready", "status_not_ready"),
        ("coordination_status", "ready", "coordination_status_not_ready"),
        ("contract_fix_cycle_ready", True, "contract_fix_cycle_ready_not_true"),
        (
            "selected_step_operation",
            "execute_targeted_contract_fix_prompt",
            "selected_step_operation_not_execute_targeted_contract_fix_prompt",
        ),
        ("prompt_exists", True, "prompt_exists_not_true"),
        ("prompt_non_empty", True, "prompt_non_empty_not_true"),
        ("execution_allowed", False, "execution_allowed_not_false"),
        ("codex_invocation_allowed", False, "codex_invocation_allowed_not_false"),
    )
    supporting_artifacts: tuple[tuple[str, bool, dict[str, Any]], ...] = (
        ("coordination_state", prompt336_coordination_state_exists, prompt336_coordination_state_payload),
        (
            "coordination_decision",
            prompt336_coordination_decision_exists,
            prompt336_coordination_decision_payload,
        ),
        (
            "coordination_receipt",
            prompt336_coordination_receipt_exists,
            prompt336_coordination_receipt_payload,
        ),
    )
    if blocked_reason == "none":
        for artifact_name, artifact_exists, artifact_payload in supporting_artifacts:
            if not artifact_exists:
                continue
            for key, expected_value, error_suffix in supporting_expectations:
                if key not in artifact_payload:
                    continue
                actual_value = artifact_payload.get(key)
                if isinstance(expected_value, bool):
                    if _as_boolish(actual_value, default=not expected_value) != expected_value:
                        blocked_reason = f"prompt336_{artifact_name}_{error_suffix}"
                        break
                else:
                    if _normalize_text(actual_value, default="") != expected_value:
                        blocked_reason = f"prompt336_{artifact_name}_{error_suffix}"
                        break
            if blocked_reason != "none":
                break

    status = "ready" if blocked_reason == "none" else "blocked"
    daemon_lite_status = status
    wrapper_plan_status = status
    daemon_lite_ready = status == "ready"
    readiness_reason = (
        "prompt336_handoff_ready_for_bounded_daemon_lite_wrapper"
        if daemon_lite_ready
        else "prompt336_handoff_not_ready_for_bounded_daemon_lite_wrapper"
    )

    selected_step_id = 3 if daemon_lite_ready else prompt336_selected_step_id
    selected_step_name = (
        "execute_targeted_contract_fix_prompt"
        if daemon_lite_ready
        else (
            prompt336_selected_step_name
            if prompt336_selected_step_name
            else "none"
        )
    )
    selected_step_operation = (
        "execute_targeted_contract_fix_prompt"
        if daemon_lite_ready
        else (
            prompt336_selected_step_operation
            if prompt336_selected_step_operation
            else "none"
        )
    )
    mutation_allowed = prompt336_mutation_allowed
    wrapper_next_action = (
        "manual_execute_bounded_targeted_contract_fix_adapter"
        if daemon_lite_ready
        else "manual_review_contract_fix_cycle_handoff"
    )
    next_action = wrapper_next_action
    decision = (
        "prepare_manual_bounded_targeted_contract_fix_execution"
        if daemon_lite_ready
        else "manual_review_contract_fix_cycle_handoff"
    )
    decision_reason = (
        "prompt336_handoff_ready_and_daemon_lite_wrapper_bounded"
        if daemon_lite_ready
        else blocked_reason
    )
    validation_errors = [] if daemon_lite_ready else [blocked_reason]

    safety_fields = _prompt337_safety_fields()
    state_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "daemon_lite_state_schema_version": _LOCAL_DAEMON_LITE_WRAPPER_STATE_SCHEMA_VERSION,
        "status": status,
        "daemon_lite_status": daemon_lite_status,
        "wrapper_plan_status": wrapper_plan_status,
        "blocked_reason": blocked_reason,
        "readiness_reason": readiness_reason,
        "daemon_lite_ready": daemon_lite_ready,
        "prompt336_handoff_status": prompt336_handoff_handoff_status,
        "prompt336_handoff_blocked_reason": prompt336_handoff_blocked_reason,
        "prompt336_handoff_next_action": prompt336_handoff_next_action,
        "prompt336_coordination_status": prompt336_coordination_status,
        "prompt336_coordination_blocked_reason": prompt336_coordination_blocked_reason,
        "prompt336_contract_fix_cycle_ready": prompt336_contract_fix_cycle_ready,
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "prompt_path": prompt336_prompt_path or expected_prompt_path,
        "prompt_exists": prompt336_prompt_exists,
        "prompt_non_empty": prompt336_prompt_non_empty,
        "explicit_allowed_tracked_files": prompt336_explicit_allowed_tracked_files,
        "mutation_allowed": mutation_allowed,
        "execution_allowed": False,
        "codex_invocation_allowed": False,
        "max_wrapper_cycles": 1,
        "current_wrapper_cycle": 0,
        "max_codex_invocations_per_cycle": 1,
        "total_codex_invocation_budget": 1,
        "bounded_execution": True,
        "unbounded_loop_allowed": False,
        "retry_allowed": False,
        "sleep_poll_allowed": False,
        "next_action": next_action,
        "validation_errors": validation_errors,
        **safety_fields,
    }

    plan_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "daemon_lite_plan_schema_version": _LOCAL_DAEMON_LITE_WRAPPER_PLAN_SCHEMA_VERSION,
        "status": status,
        "daemon_lite_status": daemon_lite_status,
        "wrapper_plan_status": wrapper_plan_status,
        "blocked_reason": blocked_reason,
        "readiness_reason": readiness_reason,
        "daemon_lite_ready": daemon_lite_ready,
        "daemon_mode": "daemon_lite",
        "daemon_is_real_background_process": False,
        "background_execution_enabled": False,
        "scheduler_enabled": False,
        "watcher_enabled": False,
        "max_wrapper_cycles": 1,
        "current_wrapper_cycle": 0,
        "max_codex_invocations_per_cycle": 1,
        "total_codex_invocation_budget": 1,
        "bounded_execution": True,
        "unbounded_loop_allowed": False,
        "retry_allowed": False,
        "sleep_poll_allowed": False,
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "selected_step_authority_source": "prompt336_contract_fix_cycle_execution_handoff",
        "selected_step_authority_artifact": str(prompt336_handoff_path),
        "prompt_path": prompt336_prompt_path or expected_prompt_path,
        "prompt_exists": prompt336_prompt_exists,
        "prompt_non_empty": prompt336_prompt_non_empty,
        "explicit_allowed_tracked_files": prompt336_explicit_allowed_tracked_files,
        "mutation_allowed": mutation_allowed,
        "execution_allowed": False,
        "codex_invocation_allowed": False,
        "command_argv": [],
        "command_display": "",
        "wrapper_next_action": wrapper_next_action,
        "next_action": next_action,
        "validation_errors": validation_errors,
        **safety_fields,
    }

    decision_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "daemon_lite_decision_schema_version": _LOCAL_DAEMON_LITE_WRAPPER_DECISION_SCHEMA_VERSION,
        "status": status,
        "daemon_lite_status": daemon_lite_status,
        "wrapper_plan_status": wrapper_plan_status,
        "blocked_reason": blocked_reason,
        "daemon_lite_ready": daemon_lite_ready,
        "decision": decision,
        "decision_reason": decision_reason,
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "wrapper_next_action": wrapper_next_action,
        "next_action": next_action,
        "execution_allowed": False,
        "codex_invocation_allowed": False,
        "max_wrapper_cycles": 1,
        "total_codex_invocation_budget": 1,
        "validation_errors": validation_errors,
        **safety_fields,
    }

    receipt_payload: dict[str, Any] = {
        "schema_version": _LOCAL_AUTONOMOUS_CYCLE_V2_SCHEMA_VERSION,
        "daemon_lite_receipt_schema_version": _LOCAL_DAEMON_LITE_WRAPPER_RECEIPT_SCHEMA_VERSION,
        "status": status,
        "daemon_lite_status": daemon_lite_status,
        "wrapper_plan_status": wrapper_plan_status,
        "blocked_reason": blocked_reason,
        "readiness_reason": readiness_reason,
        "daemon_lite_ready": daemon_lite_ready,
        "state_path": str(daemon_lite_state_path),
        "plan_path": str(daemon_lite_plan_path),
        "decision_path": str(daemon_lite_decision_path),
        "prompt336_handoff_path": str(prompt336_handoff_path),
        "selected_step_id": selected_step_id,
        "selected_step_name": selected_step_name,
        "selected_step_operation": selected_step_operation,
        "prompt_path": prompt336_prompt_path or expected_prompt_path,
        "prompt_exists": prompt336_prompt_exists,
        "prompt_non_empty": prompt336_prompt_non_empty,
        "wrapper_next_action": wrapper_next_action,
        "next_action": next_action,
        "validation_errors": validation_errors,
        **safety_fields,
    }

    try:
        one_cycle_controller_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    try:
        _write_json(daemon_lite_state_path, state_payload)
    except OSError:
        pass
    try:
        _write_json(daemon_lite_plan_path, plan_payload)
    except OSError:
        pass
    try:
        _write_json(daemon_lite_decision_path, decision_payload)
    except OSError:
        pass
    try:
        _write_json(daemon_lite_receipt_path, receipt_payload)
    except OSError:
        pass

    return {
        "local_daemon_lite_wrapper_status": status,
        "local_daemon_lite_wrapper_blocked_reason": blocked_reason,
        "local_daemon_lite_wrapper_ready": daemon_lite_ready,
        "local_daemon_lite_wrapper_decision": decision,
        "local_daemon_lite_wrapper_next_action": next_action,
        "local_daemon_lite_wrapper_selected_step_name": selected_step_name,
        "local_daemon_lite_wrapper_prompt_path": prompt336_prompt_path or expected_prompt_path,
        "local_daemon_lite_wrapper_bounded_execution": True,
        "local_daemon_lite_wrapper_total_codex_invocation_budget": 1,
        "local_daemon_lite_wrapper_state_path": str(daemon_lite_state_path),
        "local_daemon_lite_wrapper_plan_path": str(daemon_lite_plan_path),
        "local_daemon_lite_wrapper_decision_path": str(daemon_lite_decision_path),
        "local_daemon_lite_wrapper_receipt_path": str(daemon_lite_receipt_path),
    }


def _build_local_targeted_contract_fix_execution_artifacts(
    *,
    execution_repo_path: str,
    one_cycle_controller_dir: Path,
) -> dict[str, Any]:
    def _as_boolish(value: Any, *, default: bool = False) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _read_json_mapping(path: Path) -> tuple[bool, bool, dict[str, Any]]:
        if not path.exists():
            return False, False, {}
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError, json.JSONDecodeError):
            return True, False, {}
        if not isinstance(payload, Mapping):
            return True, False, {}
        return True, True, dict(payload)

    def _collect_changed_tracked_files(repo_path: str) -> tuple[bool, list[str]]:
        try:
            status_short_cmd = _run_git(
                repo_path,
                ["status", "--short", "--untracked-files=no"],
                timeout_seconds=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            return False, []
        if status_short_cmd.returncode != 0:
            return False, []
        changed = sorted(
            {
                _parse_git_status_path(line)
                for line in (status_short_cmd.stdout or "").splitlines()
                if line.strip() and _parse_git_status_path(line)
            }
        )
        return True, changed

    def _contains_blocked(text: str) -> bool:
        return "BLOCKED" in _normalize_text(text, default="").upper()

    def _get_file_size(path: Path) -> int:
        try:
            return _as_non_negative_int(path.stat().st_size, default=0)
        except OSError:
            return 0

    one_cycle_controller_dir = Path(one_cycle_controller_dir)
    prompt337_plan_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_plan.json"
    prompt337_decision_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_decision.json"
    prompt337_receipt_path = one_cycle_controller_dir / "local_daemon_lite_wrapper_receipt.json"
    prompt336_handoff_path = one_cycle_controller_dir / "local_contract_fix_cycle_execution_handoff.json"
    prompt335_prompt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt.md"
    prompt335_plan_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_plan.json"
    prompt335_receipt_path = one_cycle_controller_dir / "local_targeted_contract_fix_prompt_receipt.json"

    execution_state_path = one_cycle_controller_dir / "local_targeted_contract_fix_execution_state.json"
    execution_result_path = one_cycle_controller_dir / "local_targeted_contract_fix_execution_result.json"
    execution_receipt_path = (
        one_cycle_controller_dir / "local_targeted_contract_fix_execution_receipt.json"
    )
    stdout_path = one_cycle_controller_dir / "local_targeted_contract_fix_execution_stdout.txt"
    stderr_path = one_cycle_controller_dir / "local_targeted_contract_fix_execution_stderr.txt"

    expected_prompt_path = str(prompt335_prompt_path)
    expected_allowed_tracked_files = ["automation/orchestration/planned_execution_runner.py"]
    expected_command_argv = list(_LOCAL_TARGETED_CONTRACT_FIX_EXECUTION_COMMAND)
    command_display = " ".join(expected_command_argv)

    (
        prompt337_plan_exists,
        prompt337_plan_valid,
        prompt337_plan_payload,
    ) = _read_json_mapping(prompt337_plan_path)
    (
        prompt337_decision_exists,
        prompt337_decision_valid,
        prompt337_decision_payload,
    ) = _read_json_mapping(prompt337_decision_path)
    (
        prompt337_receipt_exists,
        prompt337_receipt_valid,
        prompt337_receipt_payload,
    ) = _read_json_mapping(prompt337_receipt_path)
    (
        prompt336_handoff_exists,
        prompt336_handoff_valid,
        prompt336_handoff_payload,
    ) = _read_json_mapping(prompt336_handoff_path)
    (
        prompt335_plan_exists,
        prompt335_plan_valid,
        prompt335_plan_payload,
    ) = _read_json_mapping(prompt335_plan_path)
    (
        prompt335_receipt_exists,
        prompt335_receipt_valid,
        prompt335_receipt_payload,
    ) = _read_json_mapping(prompt335_receipt_path)

    prompt_exists = prompt335_prompt_path.exists()
    prompt_text = ""
    if prompt_exists:
        try:
            prompt_text = prompt335_prompt_path.read_text(encoding="utf-8")
        except OSError:
            prompt_text = ""
    prompt_non_empty = bool(prompt_text.strip())
    prompt_sha256 = (
        hashlib.sha256(prompt_text.encode("utf-8")).hexdigest() if prompt_text else ""
    )
    prompt_size_bytes = len(prompt_text.encode("utf-8")) if prompt_text else 0
    prompt_line_count = len(prompt_text.splitlines()) if prompt_text else 0
    prompt_first_80_lines = "\n".join(prompt_text.splitlines()[:80])

    selected_step_id = _as_int(prompt337_plan_payload.get("selected_step_id"), default=0)
    selected_step_name = _normalize_text(
        prompt337_plan_payload.get("selected_step_name"),
        default="none",
    )
    selected_step_operation = _normalize_text(
        prompt337_plan_payload.get("selected_step_operation"),
        default="none",
    )
    selected_step_authority_source = _normalize_text(
        prompt337_plan_payload.get("selected_step_authority_source"),
        default="none",
    )
    explicit_allowed_tracked_files = _normalize_string_list(
        prompt337_plan_payload.get("explicit_allowed_tracked_files")
    )
    mutation_allowed = _as_boolish(prompt337_plan_payload.get("mutation_allowed"), default=False)

    readiness_errors: list[str] = []
    blocked_reason = "none"

    if not prompt337_plan_exists:
        readiness_errors.append("missing_prompt337_wrapper_plan_artifact")
    elif not prompt337_plan_valid:
        readiness_errors.append("invalid_prompt337_wrapper_plan_artifact")
    if not prompt337_decision_exists:
        readiness_errors.append("missing_prompt337_wrapper_decision_artifact")
    elif not prompt337_decision_valid:
        readiness_errors.append("invalid_prompt337_wrapper_decision_artifact")
    if not prompt337_receipt_exists:
        readiness_errors.append("missing_prompt337_wrapper_receipt_artifact")
    elif not prompt337_receipt_valid:
        readiness_errors.append("invalid_prompt337_wrapper_receipt_artifact")
    if not prompt336_handoff_exists:
        readiness_errors.append("missing_prompt336_execution_handoff_artifact")
    elif not prompt336_handoff_valid:
        readiness_errors.append("invalid_prompt336_execution_handoff_artifact")
    if not prompt335_plan_exists:
        readiness_errors.append("missing_prompt335_prompt_plan_artifact")
    elif not prompt335_plan_valid:
        readiness_errors.append("invalid_prompt335_prompt_plan_artifact")
    if not prompt335_receipt_exists:
        readiness_errors.append("missing_prompt335_prompt_receipt_artifact")
    elif not prompt335_receipt_valid:
        readiness_errors.append("invalid_prompt335_prompt_receipt_artifact")
    if not prompt_exists:
        readiness_errors.append("missing_prompt335_prompt_artifact")

    prompt337_plan_status = _normalize_text(prompt337_plan_payload.get("status"), default="")
    prompt337_plan_daemon_lite_status = _normalize_text(
        prompt337_plan_payload.get("daemon_lite_status"),
        default="",
    )
    prompt337_plan_blocked_reason = _normalize_text(
        prompt337_plan_payload.get("blocked_reason"),
        default="",
    )
    prompt337_plan_daemon_lite_ready = _as_boolish(
        prompt337_plan_payload.get("daemon_lite_ready"),
        default=False,
    )
    prompt337_plan_daemon_mode = _normalize_text(
        prompt337_plan_payload.get("daemon_mode"),
        default="",
    )
    prompt337_plan_daemon_is_background = _as_boolish(
        prompt337_plan_payload.get("daemon_is_real_background_process"),
        default=True,
    )
    prompt337_plan_background_execution_enabled = _as_boolish(
        prompt337_plan_payload.get("background_execution_enabled"),
        default=True,
    )
    prompt337_plan_scheduler_enabled = _as_boolish(
        prompt337_plan_payload.get("scheduler_enabled"),
        default=True,
    )
    prompt337_plan_watcher_enabled = _as_boolish(
        prompt337_plan_payload.get("watcher_enabled"),
        default=True,
    )
    prompt337_plan_max_wrapper_cycles = _as_non_negative_int(
        prompt337_plan_payload.get("max_wrapper_cycles"),
        default=0,
    )
    prompt337_plan_total_codex_invocation_budget = _as_non_negative_int(
        prompt337_plan_payload.get("total_codex_invocation_budget"),
        default=0,
    )
    prompt337_plan_bounded_execution = _as_boolish(
        prompt337_plan_payload.get("bounded_execution"),
        default=False,
    )
