def _write_approve_commit_tag_commands_if_safe(
    *,
    boundary_state: Mapping[str, Any] | None,
    command_file_path: Path,
) -> bool:
    boundary = dict(boundary_state) if isinstance(boundary_state, Mapping) else {}
    changed_paths = _normalize_string_list(boundary.get("changed_tracked_files"))
    unexpected_paths = _normalize_string_list(boundary.get("unexpected_tracked_files"))
    should_write = (
        _normalize_text(boundary.get("boundary_status"), default="blocked") == "ready"
        and bool(boundary.get("plan_ready", False))
        and bool(boundary.get("tracked_files_allowed", False))
        and changed_paths == [_APPROVE_COMMIT_TAG_EXECUTION_TRACKED_FILE]
        and not unexpected_paths
    )
    if not should_write:
        try:
            command_file_path.unlink(missing_ok=True)
        except OSError:
            pass
        return False

    commands_text = "\n".join(
        [
            "#!/usr/bin/env bash",
            "set -euo pipefail",
            "",
            "cd /home/rai/codex-local-runner",
            "",
            "git add automation/orchestration/planned_execution_runner.py",
            f'git commit -m "{_APPROVE_COMMIT_TAG_EXECUTION_COMMIT_MESSAGE}"',
            f"git tag {_APPROVE_COMMIT_TAG_EXECUTION_TAG_NAME}",
            "",
            "git status --short --untracked-files=no",
        ]
    ).rstrip() + "\n"
    try:
        command_file_path.parent.mkdir(parents=True, exist_ok=True)
        command_file_path.write_text(commands_text, encoding="utf-8")
    except OSError:
        return False
    return True


def _build_approve_commit_tag_execution_gate_state(
    *,
    execution_enabled: bool,
    execution_confirmed: bool,
    dry_run: bool,
    review_route_status: str,
    review_route_decision: str,
    review_route_should_prepare_commit: bool,
    approve_commit_tag_boundary_status: str,
    approve_commit_tag_boundary_decision: str,
    approve_commit_tag_boundary_commit_message: str,
    approve_commit_tag_boundary_tag_name: str,
    approve_commit_tag_boundary_commands_path: str,
    approve_commit_tag_boundary_metadata_path: str,
    approve_commit_tag_boundary_should_execute_commit: bool,
    approve_commit_tag_boundary_should_execute_tag: bool,
    approve_commit_tag_boundary_ready: bool,
    receipt_path: str,
) -> dict[str, Any]:
    execution_commit_message = _normalize_text(
        approve_commit_tag_boundary_commit_message,
        default="",
    )
    execution_tag_name = _normalize_text(
        approve_commit_tag_boundary_tag_name,
        default="",
    )
    state: dict[str, Any] = {
        "execution_enabled": bool(execution_enabled),
        "execution_confirmed": bool(execution_confirmed),
        "execution_gate_status": "execution_not_enabled",
        "execution_status": "not_executed",
        "execution_attempted": False,
        "execution_exit_code": 0,
        "execution_blocked_reason": "execution_not_enabled",
        "execution_commit_message": execution_commit_message,
        "execution_tag_name": execution_tag_name,
        "execution_receipt_path": _normalize_text(
            receipt_path,
            default=_APPROVE_COMMIT_TAG_EXECUTION_RECEIPT_PATH,
        ),
        "execution_should_commit": False,
        "execution_should_tag": False,
    }
    if not execution_enabled or not execution_confirmed:
        return state
    if dry_run:
        state.update(
            {
                "execution_gate_status": "dry_run_suppressed",
                "execution_status": "dry_run_suppressed",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "dry_run_execution_suppressed",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        return state
    if review_route_decision != "approve":
        state.update(
            {
                "execution_gate_status": "boundary_not_ready",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "route_not_approve",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        return state
    boundary_ready = (
        review_route_status == "route_ready"
        and bool(review_route_should_prepare_commit)
        and approve_commit_tag_boundary_status == "boundary_ready"
        and approve_commit_tag_boundary_decision == "approve"
        and bool(approve_commit_tag_boundary_ready)
    )
    if not boundary_ready:
        state.update(
            {
                "execution_gate_status": "boundary_not_ready",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_not_ready",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        return state
    deterministic_surface_valid = (
        execution_commit_message == _APPROVE_COMMIT_TAG_EXECUTION_COMMIT_MESSAGE
        and execution_tag_name == _APPROVE_COMMIT_TAG_EXECUTION_TAG_NAME
        and _normalize_text(
            approve_commit_tag_boundary_commands_path,
            default="",
        )
        == _APPROVE_COMMIT_TAG_BOUNDARY_COMMANDS_PATH
        and _normalize_text(
            approve_commit_tag_boundary_metadata_path,
            default="",
        )
        == _APPROVE_COMMIT_TAG_BOUNDARY_METADATA_PATH
        and (not bool(approve_commit_tag_boundary_should_execute_commit))
        and (not bool(approve_commit_tag_boundary_should_execute_tag))
    )
    if not deterministic_surface_valid:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_metadata_invalid",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        return state
    state.update(
        {
            "execution_gate_status": "ready_for_execution",
            "execution_status": "not_executed",
            "execution_attempted": False,
            "execution_exit_code": 0,
            "execution_blocked_reason": "none",
            "execution_commit_message": _APPROVE_COMMIT_TAG_EXECUTION_COMMIT_MESSAGE,
            "execution_tag_name": _APPROVE_COMMIT_TAG_EXECUTION_TAG_NAME,
            "execution_should_commit": False,
            "execution_should_tag": False,
        }
    )
    return state


def _run_approve_commit_tag_execution_if_enabled(
    *,
    execution_repo_path: str,
    dry_run: bool,
    review_route_status: str,
    review_route_decision: str,
    review_route_should_prepare_commit: bool,
    approve_commit_tag_boundary_status: str,
    approve_commit_tag_boundary_decision: str,
    approve_commit_tag_boundary_commit_message: str,
    approve_commit_tag_boundary_tag_name: str,
    approve_commit_tag_boundary_commands_path: str,
    approve_commit_tag_boundary_metadata_path: str,
    approve_commit_tag_boundary_should_execute_commit: bool,
    approve_commit_tag_boundary_should_execute_tag: bool,
    approve_commit_tag_boundary_ready: bool,
    execution_enabled: bool,
    execution_confirmed: bool,
    execution_receipt_path: Path,
) -> dict[str, Any]:
    state: dict[str, Any] = {
        "execution_enabled": False,
        "execution_confirmed": False,
        "execution_gate_status": "execution_not_enabled",
        "execution_status": "not_executed",
        "execution_attempted": False,
        "execution_exit_code": 0,
        "execution_blocked_reason": "execution_not_enabled",
        "execution_commit_message": _APPROVE_COMMIT_TAG_EXECUTION_COMMIT_MESSAGE,
        "execution_tag_name": _APPROVE_COMMIT_TAG_EXECUTION_TAG_NAME,
        "execution_receipt_path": _normalize_text(
            str(execution_receipt_path),
            default=_APPROVE_COMMIT_TAG_EXECUTION_RECEIPT_PATH,
        ),
        "execution_should_commit": False,
        "execution_should_tag": False,
    }
    receipt_payload = {
        "status": state["execution_status"],
        "gate_status": state["execution_gate_status"],
        "blocked_reason": state["execution_blocked_reason"],
        "attempted": state["execution_attempted"],
        "exit_code": state["execution_exit_code"],
        "execution_enabled": state["execution_enabled"],
        "execution_confirmed": state["execution_confirmed"],
        "execution_commit_message": state["execution_commit_message"],
        "execution_tag_name": state["execution_tag_name"],
        "execution_should_commit": state["execution_should_commit"],
        "execution_should_tag": state["execution_should_tag"],
        "execution_repo_path": _normalize_text(execution_repo_path, default=""),
        "boundary_commands_path": _normalize_text(
            approve_commit_tag_boundary_commands_path,
            default="",
        ),
        "boundary_metadata_path": _normalize_text(
            approve_commit_tag_boundary_metadata_path,
            default="",
        ),
        "execution_required_by": "Prompt321",
        "execution_performed": False,
    }
    try:
        execution_receipt_path.parent.mkdir(parents=True, exist_ok=True)
        execution_receipt_path.write_text(
            json.dumps(receipt_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    except OSError:
        pass
    return state

    state = _build_approve_commit_tag_execution_gate_state(
        execution_enabled=execution_enabled,
        execution_confirmed=execution_confirmed,
        dry_run=dry_run,
        review_route_status=review_route_status,
        review_route_decision=review_route_decision,
        review_route_should_prepare_commit=review_route_should_prepare_commit,
        approve_commit_tag_boundary_status=approve_commit_tag_boundary_status,
        approve_commit_tag_boundary_decision=approve_commit_tag_boundary_decision,
        approve_commit_tag_boundary_commit_message=approve_commit_tag_boundary_commit_message,
        approve_commit_tag_boundary_tag_name=approve_commit_tag_boundary_tag_name,
        approve_commit_tag_boundary_commands_path=approve_commit_tag_boundary_commands_path,
        approve_commit_tag_boundary_metadata_path=approve_commit_tag_boundary_metadata_path,
        approve_commit_tag_boundary_should_execute_commit=(
            approve_commit_tag_boundary_should_execute_commit
        ),
        approve_commit_tag_boundary_should_execute_tag=(
            approve_commit_tag_boundary_should_execute_tag
        ),
        approve_commit_tag_boundary_ready=approve_commit_tag_boundary_ready,
        receipt_path=str(execution_receipt_path),
    )

    receipt_payload: dict[str, Any] = {
        "status": state.get("execution_status"),
        "gate_status": state.get("execution_gate_status"),
        "blocked_reason": state.get("execution_blocked_reason"),
        "attempted": bool(state.get("execution_attempted", False)),
        "exit_code": _as_int(state.get("execution_exit_code"), default=0),
        "execution_enabled": bool(state.get("execution_enabled", False)),
        "execution_confirmed": bool(state.get("execution_confirmed", False)),
        "execution_commit_message": _normalize_text(
            state.get("execution_commit_message"),
            default="",
        ),
        "execution_tag_name": _normalize_text(state.get("execution_tag_name"), default=""),
        "execution_should_commit": bool(state.get("execution_should_commit", False)),
        "execution_should_tag": bool(state.get("execution_should_tag", False)),
        "execution_repo_path": _normalize_text(execution_repo_path, default=""),
        "boundary_commands_path": _normalize_text(
            approve_commit_tag_boundary_commands_path,
            default="",
        ),
        "boundary_metadata_path": _normalize_text(
            approve_commit_tag_boundary_metadata_path,
            default="",
        ),
    }

    def _write_receipt() -> dict[str, Any]:
        receipt_payload["status"] = _normalize_text(state.get("execution_status"), default="")
        receipt_payload["gate_status"] = _normalize_text(
            state.get("execution_gate_status"),
            default="",
        )
        receipt_payload["blocked_reason"] = _normalize_text(
            state.get("execution_blocked_reason"),
            default="",
        )
        receipt_payload["attempted"] = bool(state.get("execution_attempted", False))
        receipt_payload["exit_code"] = _as_int(state.get("execution_exit_code"), default=0)
        receipt_payload["execution_should_commit"] = bool(
            state.get("execution_should_commit", False)
        )
        receipt_payload["execution_should_tag"] = bool(
            state.get("execution_should_tag", False)
        )
        try:
            execution_receipt_path.parent.mkdir(parents=True, exist_ok=True)
            execution_receipt_path.write_text(
                json.dumps(receipt_payload, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
        except OSError:
            state.update(
                {
                    "execution_gate_status": "failed",
                    "execution_status": "failed",
                    "execution_attempted": bool(state.get("execution_attempted", False)),
                    "execution_exit_code": (
                        _as_int(state.get("execution_exit_code"), default=1) or 1
                    ),
                    "execution_blocked_reason": "receipt_write_failed",
                }
            )
        return state

    if _normalize_text(state.get("execution_gate_status"), default="") != "ready_for_execution":
        return _write_receipt()

    metadata_path = Path(approve_commit_tag_boundary_metadata_path)
    commands_path = Path(approve_commit_tag_boundary_commands_path)
    commit_message = _APPROVE_COMMIT_TAG_EXECUTION_COMMIT_MESSAGE
    tag_name = _APPROVE_COMMIT_TAG_EXECUTION_TAG_NAME
    expected_metadata = {
        "status": "boundary_ready",
        "decision": "approve",
        "reason": "approve_commit_tag_boundary_ready",
        "next_action": "prepare_approve_commit_tag_execution_gate",
        "blocked_reason": "none",
        "commit_message": commit_message,
        "tag_name": tag_name,
        "commands_path": _APPROVE_COMMIT_TAG_BOUNDARY_COMMANDS_PATH,
        "metadata_path": _APPROVE_COMMIT_TAG_BOUNDARY_METADATA_PATH,
        "should_execute_commit": False,
        "should_execute_tag": False,
    }

    if not metadata_path.exists():
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_metadata_missing",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["boundary_metadata_check"] = "missing"
        return _write_receipt()
    try:
        metadata_payload_raw = json.loads(metadata_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, ValueError):
        metadata_payload_raw = None
    metadata_payload = (
        dict(metadata_payload_raw) if isinstance(metadata_payload_raw, Mapping) else None
    )
    if metadata_payload is None:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_metadata_invalid",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["boundary_metadata_check"] = "invalid_json_or_shape"
        return _write_receipt()
    metadata_matches = True
    for key, expected_value in expected_metadata.items():
        if metadata_payload.get(key) != expected_value:
            metadata_matches = False
            break
    if not metadata_matches:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_metadata_invalid",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["boundary_metadata_check"] = "deterministic_mismatch"
        return _write_receipt()
    receipt_payload["boundary_metadata_check"] = "ok"

    if not commands_path.exists():
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "command_draft_missing",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["command_draft_check"] = "missing"
        return _write_receipt()
    try:
        commands_text = commands_path.read_text(encoding="utf-8")
    except OSError:
        commands_text = ""
    required_fragments = (
        f"git add {_APPROVE_COMMIT_TAG_EXECUTION_TRACKED_FILE}",
        f'git commit -m "{commit_message}"',
        f"git tag {tag_name}",
    )
    if not commands_text or any(fragment not in commands_text for fragment in required_fragments):
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "command_draft_mismatch",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["command_draft_check"] = "mismatch"
        return _write_receipt()
    receipt_payload["command_draft_check"] = "ok"

    normalized_repo_path = _normalize_text(execution_repo_path, default="")
    if (
        normalized_repo_path != _APPROVE_COMMIT_TAG_EXECUTION_REPO_PATH
        or str(Path.cwd()) != _APPROVE_COMMIT_TAG_EXECUTION_REPO_PATH
    ):
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "manual_review_required",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "cwd_mismatch"
        return _write_receipt()

    def _run_allowed_git_command(command: list[str]) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            command,
            text=True,
            capture_output=True,
            check=False,
            cwd=normalized_repo_path,
            shell=False,
        )

    status_short = _run_allowed_git_command(
        ["git", "status", "--short", "--untracked-files=no"]
    )
    if status_short.returncode != 0:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "manual_review_required",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "git_status_failed"
        receipt_payload["git_status_short_stdout"] = status_short.stdout or ""
        receipt_payload["git_status_short_stderr"] = status_short.stderr or ""
        return _write_receipt()
    receipt_payload["git_status_short_stdout"] = status_short.stdout or ""

    staged_diff = _run_allowed_git_command(["git", "diff", "--cached", "--name-only"])
    if staged_diff.returncode != 0:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "manual_review_required",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "git_diff_cached_failed"
        return _write_receipt()
    staged_paths = [
        line.strip() for line in (staged_diff.stdout or "").splitlines() if line.strip()
    ]
    receipt_payload["staged_paths"] = staged_paths
    if staged_paths:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "staged_changes_present",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "staged_changes_present"
        return _write_receipt()

    tracked_diff = _run_allowed_git_command(["git", "diff", "--name-only"])
    if tracked_diff.returncode != 0:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "manual_review_required",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "git_diff_failed"
        return _write_receipt()
    tracked_paths = [
        line.strip() for line in (tracked_diff.stdout or "").splitlines() if line.strip()
    ]
    receipt_payload["tracked_paths"] = tracked_paths
    if tracked_paths != [_APPROVE_COMMIT_TAG_EXECUTION_TRACKED_FILE]:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "unexpected_tracked_changes",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "unexpected_tracked_changes"
        return _write_receipt()

    tag_exists_check = _run_allowed_git_command(
        ["git", "rev-parse", "--verify", f"refs/tags/{tag_name}"]
    )
    if tag_exists_check.returncode == 0:
        state.update(
            {
                "execution_gate_status": "preflight_blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "tag_already_exists",
                "execution_should_commit": False,
                "execution_should_tag": False,
            }
        )
        receipt_payload["preflight_check"] = "tag_already_exists"
        return _write_receipt()

    state.update(
        {
            "execution_gate_status": "ready_for_execution",
            "execution_status": "not_executed",
            "execution_attempted": False,
            "execution_exit_code": 0,
            "execution_blocked_reason": "none",
            "execution_should_commit": True,
            "execution_should_tag": True,
        }
    )
    add_result = _run_allowed_git_command(
        ["git", "add", _APPROVE_COMMIT_TAG_EXECUTION_TRACKED_FILE]
    )
    state.update(
        {
            "execution_attempted": True,
            "execution_should_commit": True,
            "execution_should_tag": False,
        }
    )
    receipt_payload["git_add_exit_code"] = int(add_result.returncode)
    if add_result.returncode != 0:
        state.update(
            {
                "execution_gate_status": "failed",
                "execution_status": "failed",
                "execution_exit_code": int(add_result.returncode) or 1,
                "execution_blocked_reason": "commit_failed",
                "execution_should_tag": False,
            }
        )
        return _write_receipt()

    commit_result = _run_allowed_git_command(["git", "commit", "-m", commit_message])
    receipt_payload["git_commit_exit_code"] = int(commit_result.returncode)
    if commit_result.returncode != 0:
        state.update(
            {
                "execution_gate_status": "failed",
                "execution_status": "failed",
                "execution_attempted": True,
                "execution_exit_code": int(commit_result.returncode) or 1,
                "execution_blocked_reason": "commit_failed",
                "execution_should_commit": True,
                "execution_should_tag": False,
            }
        )
        return _write_receipt()

    tag_result = _run_allowed_git_command(["git", "tag", tag_name])
    receipt_payload["git_tag_exit_code"] = int(tag_result.returncode)
    if tag_result.returncode != 0:
        state.update(
            {
                "execution_gate_status": "failed",
                "execution_status": "failed",
                "execution_attempted": True,
                "execution_exit_code": int(tag_result.returncode) or 1,
                "execution_blocked_reason": "tag_failed",
                "execution_should_commit": True,
                "execution_should_tag": True,
            }
        )
        return _write_receipt()

    state.update(
        {
            "execution_gate_status": "executed",
            "execution_status": "completed",
            "execution_attempted": True,
            "execution_exit_code": 0,
            "execution_blocked_reason": "none",
            "execution_should_commit": True,
            "execution_should_tag": True,
        }
    )
    receipt_payload["preflight_check"] = "passed"
    receipt_payload["execution_result"] = "completed"
    return _write_receipt()


def _build_targeted_fix_reentry_execution_gate_state(
    *,
    execution_enabled: bool,
    execution_confirmed: bool,
    dry_run: bool,
    review_route_status: str,
    review_route_decision: str,
    review_route_should_prepare_targeted_fix: bool,
    targeted_fix_boundary_status: str,
    targeted_fix_boundary_decision: str,
    targeted_fix_boundary_prompt_ready: bool,
    targeted_fix_boundary_codex_prompt_path: str,
    receipt_path: str,
) -> dict[str, Any]:
    normalized_prompt_path = _normalize_text(
        targeted_fix_boundary_codex_prompt_path,
        default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
    )
    state: dict[str, Any] = {
        "execution_enabled": bool(execution_enabled),
        "execution_confirmed": bool(execution_confirmed),
        "execution_gate_status": "not_applicable",
        "execution_status": "not_executed",
        "execution_attempted": False,
        "execution_exit_code": 0,
        "execution_blocked_reason": "route_not_targeted_fix",
        "execution_prompt_path": normalized_prompt_path,
        "execution_receipt_path": _normalize_text(
            receipt_path,
            default=_TARGETED_FIX_REENTRY_EXECUTION_RECEIPT_PATH,
        ),
        "execution_should_execute_codex": False,
    }
    if review_route_decision != "targeted_fix":
        return state
    state.update(
        {
            "execution_gate_status": "execution_not_enabled",
            "execution_status": "not_executed",
            "execution_attempted": False,
            "execution_exit_code": 0,
            "execution_blocked_reason": "execution_not_enabled",
            "execution_should_execute_codex": False,
        }
    )
    if not execution_enabled or not execution_confirmed:
        return state
    if dry_run:
        state.update(
            {
                "execution_gate_status": "dry_run_suppressed",
                "execution_status": "dry_run_suppressed",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "dry_run_execution_suppressed",
                "execution_should_execute_codex": False,
            }
        )
        return state
    boundary_ready = (
        review_route_status == "route_ready"
        and bool(review_route_should_prepare_targeted_fix)
        and targeted_fix_boundary_status == "boundary_ready"
        and targeted_fix_boundary_decision == "targeted_fix"
        and bool(targeted_fix_boundary_prompt_ready)
        and normalized_prompt_path == _TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH
    )
    if not boundary_ready:
        state.update(
            {
                "execution_gate_status": "boundary_not_ready",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "boundary_not_ready",
                "execution_should_execute_codex": False,
            }
        )
        return state
    state.update(
        {
            "execution_gate_status": "blocked",
            "execution_status": "blocked",
            "execution_attempted": False,
            "execution_exit_code": 0,
            "execution_blocked_reason": "targeted_fix_prompt_execution_adapter_missing",
            "execution_should_execute_codex": False,
        }
    )
    return state


def _run_targeted_fix_reentry_execution_if_enabled(
    *,
    dry_run: bool,
    review_route_status: str,
    review_route_decision: str,
    review_route_should_prepare_targeted_fix: bool,
    targeted_fix_boundary_status: str,
    targeted_fix_boundary_decision: str,
    targeted_fix_boundary_prompt_ready: bool,
    targeted_fix_boundary_codex_prompt_path: str,
    execution_enabled: bool,
    execution_confirmed: bool,
    execution_receipt_path: Path,
) -> dict[str, Any]:
    state = _build_targeted_fix_reentry_execution_gate_state(
        execution_enabled=execution_enabled,
        execution_confirmed=execution_confirmed,
        dry_run=dry_run,
        review_route_status=review_route_status,
        review_route_decision=review_route_decision,
        review_route_should_prepare_targeted_fix=review_route_should_prepare_targeted_fix,
        targeted_fix_boundary_status=targeted_fix_boundary_status,
        targeted_fix_boundary_decision=targeted_fix_boundary_decision,
        targeted_fix_boundary_prompt_ready=targeted_fix_boundary_prompt_ready,
        targeted_fix_boundary_codex_prompt_path=targeted_fix_boundary_codex_prompt_path,
        receipt_path=str(execution_receipt_path),
    )
    receipt_payload: dict[str, Any] = {
        "status": state.get("execution_status"),
        "gate_status": state.get("execution_gate_status"),
        "blocked_reason": state.get("execution_blocked_reason"),
        "attempted": bool(state.get("execution_attempted", False)),
        "exit_code": _as_int(state.get("execution_exit_code"), default=0),
        "execution_enabled": bool(state.get("execution_enabled", False)),
        "execution_confirmed": bool(state.get("execution_confirmed", False)),
        "execution_prompt_path": _normalize_text(
            state.get("execution_prompt_path"),
            default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
        ),
        "execution_should_execute_codex": bool(
            state.get("execution_should_execute_codex", False)
        ),
        "codex_command": " ".join(_TARGETED_FIX_REENTRY_EXECUTION_COMMAND),
        "stdout_path": _TARGETED_FIX_REENTRY_EXECUTION_STDOUT_PATH,
        "stderr_path": _TARGETED_FIX_REENTRY_EXECUTION_STDERR_PATH,
    }

    def _run_targeted_fix_codex_prompt_file_once(
        *,
        prompt_path: str,
    ) -> dict[str, Any]:
        normalized_prompt_path = _normalize_text(
            prompt_path,
            default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
        )
        try:
            prompt_text = Path(normalized_prompt_path).read_text(encoding="utf-8")
        except OSError:
            return {
                "execution_gate_status": "blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "targeted_fix_prompt_missing",
                "execution_prompt_path": normalized_prompt_path,
                "execution_should_execute_codex": False,
            }
        if not prompt_text.strip():
            return {
                "execution_gate_status": "blocked",
                "execution_status": "blocked",
                "execution_attempted": False,
                "execution_exit_code": 0,
                "execution_blocked_reason": "targeted_fix_prompt_missing",
                "execution_prompt_path": normalized_prompt_path,
                "execution_should_execute_codex": False,
            }
        try:
            completed = subprocess.run(
                list(_TARGETED_FIX_REENTRY_EXECUTION_COMMAND),
                input=prompt_text,
                shell=False,
                cwd="/home/rai/codex-local-runner",
                capture_output=True,
                text=True,
                check=False,
            )
        except OSError:
            completed_stdout = ""
            completed_stderr = ""
            execution_exit_code = 1
            execution_gate_status = "failed"
            execution_status = "failed"
            execution_blocked_reason = "codex_execution_failed"
        else:
            completed_stdout = _normalize_text(completed.stdout, default="")
            completed_stderr = _normalize_text(completed.stderr, default="")
            execution_exit_code = int(completed.returncode)
            if execution_exit_code == 0:
                execution_gate_status = "executed"
                execution_status = "completed"
                execution_blocked_reason = "none"
            else:
                execution_gate_status = "failed"
                execution_status = "failed"
                execution_blocked_reason = "codex_execution_failed"
        stdout_path = Path(_TARGETED_FIX_REENTRY_EXECUTION_STDOUT_PATH)
        stderr_path = Path(_TARGETED_FIX_REENTRY_EXECUTION_STDERR_PATH)
        try:
            stdout_path.parent.mkdir(parents=True, exist_ok=True)
            stdout_path.write_text(completed_stdout, encoding="utf-8")
            stderr_path.parent.mkdir(parents=True, exist_ok=True)
            stderr_path.write_text(completed_stderr, encoding="utf-8")
        except OSError:
            pass
        return {
            "execution_gate_status": execution_gate_status,
            "execution_status": execution_status,
            "execution_attempted": True,
            "execution_exit_code": execution_exit_code,
            "execution_blocked_reason": execution_blocked_reason,
            "execution_prompt_path": normalized_prompt_path,
            "execution_should_execute_codex": True,
        }

    def _write_receipt() -> dict[str, Any]:
        receipt_payload["status"] = _normalize_text(state.get("execution_status"), default="")
        receipt_payload["gate_status"] = _normalize_text(
            state.get("execution_gate_status"),
            default="",
        )
        receipt_payload["blocked_reason"] = _normalize_text(
            state.get("execution_blocked_reason"),
            default="",
        )
        receipt_payload["attempted"] = bool(state.get("execution_attempted", False))
        receipt_payload["exit_code"] = _as_int(state.get("execution_exit_code"), default=0)
        receipt_payload["execution_should_execute_codex"] = bool(
            state.get("execution_should_execute_codex", False)
        )
        try:
            execution_receipt_path.parent.mkdir(parents=True, exist_ok=True)
            execution_receipt_path.write_text(
                json.dumps(receipt_payload, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
        except OSError:
            state.update(
                {
                    "execution_gate_status": "failed",
                    "execution_status": "failed",
                    "execution_attempted": bool(state.get("execution_attempted", False)),
                    "execution_exit_code": (
                        _as_int(state.get("execution_exit_code"), default=1) or 1
                    ),
                    "execution_blocked_reason": "receipt_write_failed",
                    "execution_should_execute_codex": False,
                }
            )
        return state

    if _normalize_text(state.get("execution_blocked_reason"), default="") == (
        "targeted_fix_prompt_execution_adapter_missing"
    ):
        state.update(
            _run_targeted_fix_codex_prompt_file_once(
                prompt_path=_normalize_text(
                    state.get("execution_prompt_path"),
                    default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
                )
            )
        )

    return _write_receipt()


def _run_targeted_fix_post_reentry_codex_reentry_execution_if_enabled(
    *,
    prompt_emission_path: Path,
    prompt_emission_receipt_path: Path,
    expected_emitted_prompt_path: Path,
    execution_enabled: bool,
    execution_confirmed: bool,
    execution_receipt_path: Path,
    execution_stdout_path: Path,
    execution_stderr_path: Path,
) -> dict[str, Any]:
    normalized_prompt_emission_path = _normalize_text(
        str(prompt_emission_path),
        default=_TARGETED_FIX_POST_REENTRY_PROMPT_EMISSION_PATH,
    )
    normalized_prompt_emission_receipt_path = _normalize_text(
        str(prompt_emission_receipt_path),
        default=_TARGETED_FIX_POST_REENTRY_PROMPT_EMISSION_RECEIPT_PATH,
    )
    normalized_expected_prompt_path = _normalize_text(
        str(expected_emitted_prompt_path),
        default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
    )
    normalized_execution_receipt_path = _normalize_text(
        str(execution_receipt_path),
        default=_TARGETED_FIX_POST_REENTRY_CODEX_REENTRY_EXECUTION_RECEIPT_PATH,
    )
    normalized_stdout_path = _normalize_text(
        str(execution_stdout_path),
        default=_TARGETED_FIX_POST_REENTRY_CODEX_REENTRY_EXECUTION_STDOUT_PATH,
    )
    normalized_stderr_path = _normalize_text(
        str(execution_stderr_path),
        default=_TARGETED_FIX_POST_REENTRY_CODEX_REENTRY_EXECUTION_STDERR_PATH,
    )

    prompt_emission_state_payload: dict[str, Any] = {}
    prompt_emission_receipt_payload: dict[str, Any] = {}
    try:
        loaded_prompt_emission_state = _read_json_object_if_exists(Path(normalized_prompt_emission_path))
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_prompt_emission_state = None
    if isinstance(loaded_prompt_emission_state, Mapping):
        prompt_emission_state_payload = dict(loaded_prompt_emission_state)
    try:
        loaded_prompt_emission_receipt = _read_json_object_if_exists(
            Path(normalized_prompt_emission_receipt_path)
        )
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_prompt_emission_receipt = None
    if isinstance(loaded_prompt_emission_receipt, Mapping):
        prompt_emission_receipt_payload = dict(loaded_prompt_emission_receipt)

    prompt_emission_status = _normalize_text(
        prompt_emission_receipt_payload.get("status"),
        default=_normalize_text(prompt_emission_state_payload.get("status"), default="not_applicable"),
    )
    prompt_emission_receipt_status = _normalize_text(
        prompt_emission_receipt_payload.get("receipt_status"),
        default="not_applicable",
    )
    prompt_written = bool(
        prompt_emission_receipt_payload.get(
            "prompt_written",
            prompt_emission_state_payload.get("prompt_written", False),
        )
    )
    ready_for_codex_reentry = bool(
        prompt_emission_receipt_payload.get("ready_for_codex_reentry", False)
    )
    codex_reentry_executed = bool(
        prompt_emission_receipt_payload.get("codex_reentry_executed", False)
    )
    execution_performed = bool(
        prompt_emission_receipt_payload.get("execution_performed", False)
    )
    emitted_prompt_path = _normalize_text(
        prompt_emission_receipt_payload.get("emitted_prompt_path"),
        default=_normalize_text(
            prompt_emission_state_payload.get("emitted_prompt_path"),
            default=normalized_expected_prompt_path,
        ),
    )

    state: dict[str, Any] = {
        "status": "not_applicable",
        "execution_status": "not_applicable",
        "gate_status": "not_applicable",
        "blocked_reason": "prompt_emission_not_ready",
        "attempted": False,
        "source": "targeted_fix_post_reentry_prompt_emission_receipt",
        "prompt_emission_path": normalized_prompt_emission_path,
        "prompt_emission_receipt_path": normalized_prompt_emission_receipt_path,
        "emitted_prompt_path": emitted_prompt_path,
        "stdout_path": normalized_stdout_path,
        "stderr_path": normalized_stderr_path,
        "receipt_path": normalized_execution_receipt_path,
        "prompt_written": bool(prompt_written),
        "ready_for_codex_reentry": bool(ready_for_codex_reentry),
        "codex_reentry_executed": False,
        "execution_performed": False,
        "execution_enabled": bool(execution_enabled),
        "execution_confirmed": bool(execution_confirmed),
        "exit_code": None,
        "codex_command": list(_TARGETED_FIX_REENTRY_EXECUTION_COMMAND),
        "next_action": "none",
        "summary": "Post-reentry Codex reentry execution is not applicable because prompt emission is not ready.",
    }

    stdout_text = ""
    stderr_text = ""

    receipt_ready = (
        prompt_emission_status == "ready"
        and prompt_emission_receipt_status == "ready"
        and bool(prompt_written)
        and bool(ready_for_codex_reentry)
        and (not codex_reentry_executed)
        and (not execution_performed)
    )
    if not receipt_ready:
        state.update(
            {
                "status": "not_applicable",
                "execution_status": "not_applicable",
                "gate_status": "not_applicable",
                "blocked_reason": "prompt_emission_not_ready",
                "attempted": False,
                "codex_reentry_executed": False,
                "execution_performed": False,
                "exit_code": None,
                "next_action": "none",
                "summary": (
                    "Prompt317 post-reentry prompt emission receipt is not ready for Codex reentry execution."
                ),
            }
        )
    elif not (execution_enabled and execution_confirmed):
        state.update(
            {
                "status": "blocked",
                "execution_status": "blocked",
                "gate_status": "blocked",
                "blocked_reason": "post_reentry_codex_reentry_execution_not_enabled",
                "attempted": False,
                "codex_reentry_executed": False,
                "execution_performed": False,
                "exit_code": None,
                "next_action": "enable_post_reentry_codex_reentry_execution",
                "summary": (
                    "Prompt317 post-reentry prompt is ready, but explicit execution enable/confirmation gates are not set."
                ),
            }
        )
    else:
        prompt_text = ""
        prompt_ready = False
        if emitted_prompt_path == normalized_expected_prompt_path:
            try:
                prompt_text = Path(emitted_prompt_path).read_text(encoding="utf-8")
                prompt_ready = bool(prompt_text.strip())
            except OSError:
                prompt_ready = False
        if not prompt_ready:
            state.update(
                {
                    "status": "blocked",
                    "execution_status": "blocked",
                    "gate_status": "blocked",
                    "blocked_reason": "post_reentry_codex_prompt_missing_or_empty",
                    "attempted": False,
                    "codex_reentry_executed": False,
                    "execution_performed": False,
                    "exit_code": None,
                    "next_action": "prepare_post_reentry_targeted_fix_prompt",
                    "summary": (
                        "Post-reentry targeted-fix prompt path is missing, unexpected, or empty."
                    ),
                }
            )
        else:
            try:
                completed = subprocess.run(
                    list(_TARGETED_FIX_REENTRY_EXECUTION_COMMAND),
                    input=prompt_text,
                    shell=False,
                    cwd="/home/rai/codex-local-runner",
                    capture_output=True,
                    text=True,
                    check=False,
                )
                exit_code = int(completed.returncode)
                stdout_text = _normalize_text(completed.stdout, default="")
                stderr_text = _normalize_text(completed.stderr, default="")
            except OSError as exc:
                exit_code = 1
                stderr_text = _normalize_text(str(exc), default="")
            if exit_code == 0:
                state.update(
                    {
                        "status": "completed",
                        "execution_status": "completed",
                        "gate_status": "executed",
                        "blocked_reason": "none",
                        "attempted": True,
                        "codex_reentry_executed": True,
                        "execution_performed": True,
                        "exit_code": 0,
                        "next_action": "capture_post_reentry_diff_after_codex_reentry",
                        "summary": "Post-reentry Codex reentry execution completed successfully.",
                    }
                )
            else:
                state.update(
                    {
                        "status": "failed",
                        "execution_status": "failed",
                        "gate_status": "executed",
                        "blocked_reason": "post_reentry_codex_reentry_execution_failed",
                        "attempted": True,
                        "codex_reentry_executed": True,
                        "execution_performed": True,
                        "exit_code": int(exit_code),
                        "next_action": "review_post_reentry_codex_reentry_failure",
                        "summary": "Post-reentry Codex reentry execution failed.",
                    }
                )

    state["emitted_prompt_path"] = emitted_prompt_path

    try:
        stdout_file_path = Path(normalized_stdout_path)
        stderr_file_path = Path(normalized_stderr_path)
        stdout_file_path.parent.mkdir(parents=True, exist_ok=True)
        stdout_file_path.write_text(stdout_text, encoding="utf-8")
        stderr_file_path.parent.mkdir(parents=True, exist_ok=True)
        stderr_file_path.write_text(stderr_text, encoding="utf-8")
    except OSError:
        pass

    receipt_payload: dict[str, Any] = {
        "status": _normalize_text(state.get("status"), default=""),
        "execution_status": _normalize_text(state.get("execution_status"), default=""),
        "gate_status": _normalize_text(state.get("gate_status"), default=""),
        "blocked_reason": _normalize_text(state.get("blocked_reason"), default=""),
        "attempted": bool(state.get("attempted", False)),
        "source": _normalize_text(state.get("source"), default=""),
        "prompt_emission_path": normalized_prompt_emission_path,
        "prompt_emission_receipt_path": normalized_prompt_emission_receipt_path,
        "emitted_prompt_path": _normalize_text(state.get("emitted_prompt_path"), default=""),
        "stdout_path": normalized_stdout_path,
        "stderr_path": normalized_stderr_path,
        "receipt_path": normalized_execution_receipt_path,
        "prompt_written": bool(state.get("prompt_written", False)),
        "ready_for_codex_reentry": bool(state.get("ready_for_codex_reentry", False)),
        "codex_reentry_executed": bool(state.get("codex_reentry_executed", False)),
        "execution_performed": bool(state.get("execution_performed", False)),
        "execution_enabled": bool(state.get("execution_enabled", False)),
        "execution_confirmed": bool(state.get("execution_confirmed", False)),
        "exit_code": state.get("exit_code"),
        "codex_command": list(_TARGETED_FIX_REENTRY_EXECUTION_COMMAND),
        "next_action": _normalize_text(state.get("next_action"), default="none"),
        "summary": _normalize_text(state.get("summary"), default=""),
    }
    try:
        receipt_file_path = Path(normalized_execution_receipt_path)
        receipt_file_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_file_path.write_text(
            json.dumps(receipt_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
    except OSError:
        pass
    return state


def _capture_targeted_fix_post_reentry_diff_state(
    *,
    targeted_fix_reentry_execution_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    reentry_state = (
        dict(targeted_fix_reentry_execution_state)
        if isinstance(targeted_fix_reentry_execution_state, Mapping)
        else {}
    )
    repo_path = _APPROVE_COMMIT_TAG_EXECUTION_REPO_PATH
    reentry_receipt_path = _normalize_text(
        reentry_state.get("execution_receipt_path"),
        default=_TARGETED_FIX_REENTRY_EXECUTION_RECEIPT_PATH,
    )
    diff_capture_path = _TARGETED_FIX_POST_REENTRY_DIFF_CAPTURE_PATH
    diff_patch_path = _TARGETED_FIX_POST_REENTRY_DIFF_PATCH_PATH
    diff_stat_path = _TARGETED_FIX_POST_REENTRY_DIFF_STAT_PATH
    diff_name_status_path = _TARGETED_FIX_POST_REENTRY_DIFF_NAME_STATUS_PATH
    git_commands = {
        "diff_name_status": ["git", "diff", "--name-status"],
        "diff_stat": ["git", "diff", "--stat"],
        "diff_patch": ["git", "diff"],
        "cached_diff_name_status": ["git", "diff", "--cached", "--name-status"],
        "cached_diff_stat": ["git", "diff", "--cached", "--stat"],
        "cached_diff_patch": ["git", "diff", "--cached"],
    }
    state: dict[str, Any] = {
        "status": "not_applicable",
        "capture_status": "not_applicable",
        "blocked_reason": "reentry_not_completed",
        "attempted": False,
        "source": "targeted_fix_reentry_execution_state",
        "repo_path": repo_path,
        "reentry_receipt_path": reentry_receipt_path,
        "diff_capture_path": diff_capture_path,
        "diff_patch_path": diff_patch_path,
        "diff_stat_path": diff_stat_path,
        "diff_name_status_path": diff_name_status_path,
        "changed_files": [],
        "changed_file_count": 0,
        "has_diff": False,
        "has_staged_diff": False,
        "git_commands": {
            command_key: list(command)
            for command_key, command in git_commands.items()
        },
        "command_exit_codes": {},
    }
    is_completed_reentry = (
        _normalize_text(reentry_state.get("execution_gate_status"), default="") == "executed"
        and _normalize_text(reentry_state.get("execution_status"), default="") == "completed"
        and bool(reentry_state.get("execution_attempted", False))
        and _as_int(reentry_state.get("execution_exit_code"), default=-1) == 0
        and _normalize_text(reentry_state.get("execution_blocked_reason"), default="") == "none"
    )
    if not is_completed_reentry:
        try:
            Path(diff_capture_path).parent.mkdir(parents=True, exist_ok=True)
            Path(diff_patch_path).write_text("", encoding="utf-8")
            Path(diff_stat_path).write_text("", encoding="utf-8")
            Path(diff_name_status_path).write_text("", encoding="utf-8")
            _write_json(Path(diff_capture_path), state)
        except OSError:
            pass
        return state

    command_outputs: dict[str, str] = {}
    command_exit_codes: dict[str, int] = {}
    for command_key, command in git_commands.items():
        completed = subprocess.run(
            list(command),
            shell=False,
            cwd=repo_path,
            capture_output=True,
            text=True,
            check=False,
        )
        command_exit_codes[command_key] = int(completed.returncode)
        command_outputs[command_key] = completed.stdout or ""
    state["attempted"] = True
    state["command_exit_codes"] = dict(command_exit_codes)
    state["git_commands"] = {
        command_key: list(command) for command_key, command in git_commands.items()
    }
    if any(exit_code != 0 for exit_code in command_exit_codes.values()):
        state.update(
            {
                "status": "blocked",
                "capture_status": "blocked",
                "blocked_reason": "diff_capture_failed",
            }
        )
        try:
            Path(diff_capture_path).parent.mkdir(parents=True, exist_ok=True)
            Path(diff_patch_path).write_text("", encoding="utf-8")
            Path(diff_stat_path).write_text("", encoding="utf-8")
            Path(diff_name_status_path).write_text("", encoding="utf-8")
            _write_json(Path(diff_capture_path), state)
        except OSError:
            pass
        return state

    diff_patch_text = command_outputs.get("diff_patch", "")
    cached_diff_patch_text = command_outputs.get("cached_diff_patch", "")
    diff_stat_text = (command_outputs.get("diff_stat", "") or "").strip()
    cached_diff_stat_text = (command_outputs.get("cached_diff_stat", "") or "").strip()
    diff_name_status_text = (command_outputs.get("diff_name_status", "") or "").strip()
    cached_diff_name_status_text = (
        command_outputs.get("cached_diff_name_status", "") or ""
    ).strip()

    combined_patch_sections = [
        "# git diff",
        diff_patch_text.rstrip("\n"),
        "",
        "# git diff --cached",
        cached_diff_patch_text.rstrip("\n"),
        "",
    ]
    combined_stat_sections = [
        "# git diff --stat",
        diff_stat_text or "(no unstaged tracked diff)",
        "",
        "# git diff --cached --stat",
        cached_diff_stat_text or "(no staged tracked diff)",
        "",
    ]
    combined_name_status_sections = [
        "# git diff --name-status",
        diff_name_status_text or "(no unstaged tracked diff)",
        "",
        "# git diff --cached --name-status",
        cached_diff_name_status_text or "(no staged tracked diff)",
        "",
    ]

    changed_files: set[str] = set()

    def _collect_paths(name_status_text: str) -> None:
        for raw_line in name_status_text.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            parts = [segment.strip() for segment in line.split("\t") if segment.strip()]
            if len(parts) >= 3:
                changed_files.add(parts[-1])
            elif len(parts) >= 2:
                changed_files.add(parts[1])

    _collect_paths(diff_name_status_text)
    _collect_paths(cached_diff_name_status_text)
    changed_files_list = sorted(changed_files)
    has_unstaged_diff = bool(diff_patch_text.strip())
    has_staged_diff = bool(cached_diff_patch_text.strip())
    has_diff = bool(has_unstaged_diff or has_staged_diff)
    state.update(
        {
            "status": "captured" if has_diff else "captured_no_diff",
            "capture_status": "captured" if has_diff else "captured_no_diff",
            "blocked_reason": "none",
            "changed_files": changed_files_list,
            "changed_file_count": len(changed_files_list),
            "has_diff": has_diff,
            "has_staged_diff": has_staged_diff,
        }
    )
    try:
        Path(diff_capture_path).parent.mkdir(parents=True, exist_ok=True)
        Path(diff_patch_path).write_text("\n".join(combined_patch_sections), encoding="utf-8")
        Path(diff_stat_path).write_text("\n".join(combined_stat_sections), encoding="utf-8")
        Path(diff_name_status_path).write_text(
            "\n".join(combined_name_status_sections),
            encoding="utf-8",
        )
        _write_json(Path(diff_capture_path), state)
    except OSError:
        state.update(
            {
                "status": "blocked",
                "capture_status": "blocked",
                "blocked_reason": "diff_capture_write_failed",
            }
        )
        try:
            _write_json(Path(diff_capture_path), state)
        except OSError:
            pass
    return state


def _build_targeted_fix_post_reentry_review_handoff_state(
    *,
    diff_capture_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    capture_state = dict(diff_capture_state) if isinstance(diff_capture_state, Mapping) else {}
    review_handoff_path = _TARGETED_FIX_POST_REENTRY_REVIEW_HANDOFF_PATH
    state: dict[str, Any] = {
        "status": "not_applicable",
        "handoff_status": "not_applicable",
        "blocked_reason": "reentry_not_completed",
        "review_required": False,
        "review_kind": "not_applicable",
        "source": "targeted_fix_post_reentry_diff_capture",
        "reentry_receipt_path": _normalize_text(
            capture_state.get("reentry_receipt_path"),
            default=_TARGETED_FIX_REENTRY_EXECUTION_RECEIPT_PATH,
        ),
        "diff_capture_path": _normalize_text(
            capture_state.get("diff_capture_path"),
            default=_TARGETED_FIX_POST_REENTRY_DIFF_CAPTURE_PATH,
        ),
        "diff_patch_path": _normalize_text(
            capture_state.get("diff_patch_path"),
            default=_TARGETED_FIX_POST_REENTRY_DIFF_PATCH_PATH,
        ),
        "diff_stat_path": _normalize_text(
            capture_state.get("diff_stat_path"),
            default=_TARGETED_FIX_POST_REENTRY_DIFF_STAT_PATH,
        ),
        "diff_name_status_path": _normalize_text(
            capture_state.get("diff_name_status_path"),
            default=_TARGETED_FIX_POST_REENTRY_DIFF_NAME_STATUS_PATH,
        ),
        "review_handoff_path": review_handoff_path,
        "changed_files": [],
        "changed_file_count": 0,
        "has_diff": False,
        "summary": "Post-reentry review handoff not applicable because reentry did not complete.",
    }
    capture_status = _normalize_text(capture_state.get("capture_status"), default="not_applicable")
    capture_blocked_reason = _normalize_text(
        capture_state.get("blocked_reason"),
        default="reentry_not_completed",
    )
    if capture_status == "captured":
        state.update(
            {
                "status": "ready",
                "handoff_status": "ready",
                "blocked_reason": "none",
                "review_required": True,
                "review_kind": "targeted_fix_post_reentry_review",
                "changed_files": _normalize_string_list(capture_state.get("changed_files")),
                "changed_file_count": _as_non_negative_int(
                    capture_state.get("changed_file_count"),
                    default=0,
                ),
                "has_diff": bool(capture_state.get("has_diff", False)),
                "summary": "Post-reentry diff captured; targeted fix review is required.",
            }
        )
    elif capture_status == "captured_no_diff":
        state.update(
            {
                "status": "ready_no_diff",
                "handoff_status": "ready_no_diff",
                "blocked_reason": "none",
                "review_required": False,
                "review_kind": "targeted_fix_post_reentry_no_diff_review",
                "changed_files": [],
                "changed_file_count": 0,
                "has_diff": False,
                "summary": "Post-reentry completed with no tracked/staged diff.",
            }
        )
    elif capture_status == "blocked":
        state.update(
            {
                "status": "blocked",
                "handoff_status": "blocked",
                "blocked_reason": capture_blocked_reason or "diff_capture_failed",
                "review_required": False,
                "review_kind": "targeted_fix_post_reentry_review_blocked",
                "summary": "Post-reentry diff capture was blocked.",
            }
        )

    try:
        Path(review_handoff_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(review_handoff_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_review_assimilation_state(
    *,
    review_handoff_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    handoff_state = (
        dict(review_handoff_state) if isinstance(review_handoff_state, Mapping) else {}
    )
    review_response_path = _TARGETED_FIX_POST_REENTRY_REVIEW_RESPONSE_PATH
    review_handoff_path = _TARGETED_FIX_POST_REENTRY_REVIEW_HANDOFF_PATH
    review_assimilation_path = _TARGETED_FIX_POST_REENTRY_REVIEW_ASSIMILATION_PATH
    handoff_status = _normalize_text(handoff_state.get("handoff_status"), default="not_applicable")
    review_required = bool(handoff_state.get("review_required", False))
    state: dict[str, Any] = {
        "status": "not_applicable",
        "assimilation_status": "not_applicable",
        "blocked_reason": "review_handoff_not_ready",
        "attempted": False,
        "source": "targeted_fix_post_reentry_review_handoff",
        "review_response_path": review_response_path,
        "review_handoff_path": review_handoff_path,
        "handoff_status": handoff_status,
        "review_required": review_required,
        "decision": "none",
        "normalized_decision": "none",
        "reason": "",
        "summary": "",
        "targeted_fix_prompt_present": False,
        "targeted_fix_prompt_length": 0,
    }
    if handoff_status == "ready_no_diff" and not review_required:
        state.update(
            {
                "status": "ready",
                "assimilation_status": "no_review_required",
                "blocked_reason": "none",
                "attempted": True,
                "decision": "no_action",
                "normalized_decision": "no_action",
                "reason": "no_review_required",
                "summary": _normalize_text(
                    handoff_state.get("summary"),
                    default="Post-reentry no-diff handoff does not require review response.",
                ),
                "targeted_fix_prompt_present": False,
                "targeted_fix_prompt_length": 0,
            }
        )
    elif handoff_status == "ready" and review_required:
        state["attempted"] = True
        response_path = Path(review_response_path)
        if not response_path.exists():
            state.update(
                {
                    "status": "blocked",
                    "assimilation_status": "blocked",
                    "blocked_reason": "post_reentry_review_response_missing",
                }
            )
        else:
            try:
                payload = json.loads(response_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError, ValueError):
                state.update(
                    {
                        "status": "blocked",
                        "assimilation_status": "blocked",
                        "blocked_reason": "post_reentry_review_response_invalid_json",
                    }
                )
            else:
                if not isinstance(payload, Mapping):
                    state.update(
                        {
                            "status": "blocked",
                            "assimilation_status": "blocked",
                            "blocked_reason": "post_reentry_review_response_invalid_json",
                        }
                    )
                else:
                    decision = _normalize_text(payload.get("decision"), default="")
                    normalized_decision = decision.lower()
                    reason = _normalize_text(payload.get("reason"), default="")
                    summary = _normalize_text(payload.get("summary"), default="")
                    targeted_fix_prompt = _normalize_text(
                        payload.get("targeted_fix_prompt"),
                        default="",
                    )
                    targeted_fix_prompt_present = bool(targeted_fix_prompt)
                    targeted_fix_prompt_length = len(targeted_fix_prompt)
                    state.update(
                        {
                            "decision": decision or "none",
                            "normalized_decision": normalized_decision or "none",
                            "reason": reason,
                            "summary": summary,
                            "targeted_fix_prompt_present": targeted_fix_prompt_present,
                            "targeted_fix_prompt_length": targeted_fix_prompt_length,
                        }
                    )
                    if normalized_decision not in {
                        "approve",
                        "reject",
                        "targeted_fix",
                        "no_action",
                    }:
                        state.update(
                            {
                                "status": "blocked",
                                "assimilation_status": "blocked",
                                "blocked_reason": "unsupported_post_reentry_review_decision",
                            }
                        )
                    elif normalized_decision == "targeted_fix" and not targeted_fix_prompt_present:
                        state.update(
                            {
                                "status": "blocked",
                                "assimilation_status": "blocked",
                                "blocked_reason": "post_reentry_targeted_fix_prompt_missing",
                            }
                        )
                    else:
                        state.update(
                            {
                                "status": "ready",
                                "assimilation_status": "assimilated",
                                "blocked_reason": "none",
                            }
                        )
    try:
        Path(review_assimilation_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(review_assimilation_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_route_decision_state(
    *,
    review_assimilation_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    assimilation_state = (
        dict(review_assimilation_state)
        if isinstance(review_assimilation_state, Mapping)
        else {}
    )
    review_response_path = _TARGETED_FIX_POST_REENTRY_REVIEW_RESPONSE_PATH
    review_handoff_path = _TARGETED_FIX_POST_REENTRY_REVIEW_HANDOFF_PATH
    review_assimilation_path = _TARGETED_FIX_POST_REENTRY_REVIEW_ASSIMILATION_PATH
    route_decision_path = _TARGETED_FIX_POST_REENTRY_ROUTE_DECISION_PATH
    normalized_decision = _normalize_text(
        assimilation_state.get("normalized_decision"),
        default="none",
    )
    assimilation_status = _normalize_text(
        assimilation_state.get("assimilation_status"),
        default="not_applicable",
    )
    blocked_reason = _normalize_text(
        assimilation_state.get("blocked_reason"),
        default="review_handoff_not_ready",
    )
    targeted_fix_prompt_present = bool(
        assimilation_state.get("targeted_fix_prompt_present", False)
    )
    summary = _normalize_text(assimilation_state.get("summary"), default="")
    state: dict[str, Any] = {
        "status": "blocked",
        "route_status": "blocked",
        "blocked_reason": "manual_review_required",
        "source": "targeted_fix_post_reentry_review_assimilation",
        "review_response_path": review_response_path,
        "review_assimilation_path": review_assimilation_path,
        "review_handoff_path": review_handoff_path,
        "route_decision": "manual_review_required",
        "next_action": "manual_review_required",
        "manual_review_required": True,
        "targeted_fix_required": False,
        "approve_allowed": False,
        "reject_allowed": False,
        "no_action_allowed": False,
        "targeted_fix_prompt_present": targeted_fix_prompt_present,
        "summary": summary,
    }
    if assimilation_status == "no_review_required" and normalized_decision == "no_action":
        state.update(
            {
                "status": "ready",
                "route_status": "ready",
                "blocked_reason": "none",
                "route_decision": "completed_no_diff",
                "next_action": "complete_post_reentry_no_diff",
                "manual_review_required": False,
                "targeted_fix_required": False,
                "approve_allowed": False,
                "reject_allowed": False,
                "no_action_allowed": True,
                "targeted_fix_prompt_present": False,
                "summary": summary or "No post-reentry diff; no review response required.",
            }
        )
    elif assimilation_status == "blocked":
        if blocked_reason == "post_reentry_review_response_missing":
            state.update(
                {
                    "status": "blocked",
                    "route_status": "blocked",
                    "blocked_reason": "post_reentry_review_response_missing",
                    "route_decision": "await_review_response",
                    "next_action": "provide_post_reentry_review_response",
                    "manual_review_required": False,
                    "summary": summary or "Post-reentry review response file is missing.",
                }
            )
        elif blocked_reason == "post_reentry_review_response_invalid_json":
            state.update(
                {
                    "status": "blocked",
                    "route_status": "blocked",
                    "blocked_reason": "post_reentry_review_response_invalid_json",
                    "route_decision": "await_valid_review_response",
                    "next_action": "provide_valid_post_reentry_review_response",
                    "manual_review_required": False,
                    "summary": summary or "Post-reentry review response JSON is invalid.",
                }
            )
        elif blocked_reason == "unsupported_post_reentry_review_decision":
            state.update(
                {
                    "status": "blocked",
                    "route_status": "blocked",
                    "blocked_reason": "unsupported_post_reentry_review_decision",
                    "route_decision": "manual_review_required",
                    "next_action": "manual_review_required",
                    "manual_review_required": True,
                    "summary": summary or "Post-reentry review decision is unsupported.",
                }
            )
        elif blocked_reason == "post_reentry_targeted_fix_prompt_missing":
            state.update(
                {
                    "status": "blocked",
                    "route_status": "blocked",
                    "blocked_reason": "post_reentry_targeted_fix_prompt_missing",
                    "route_decision": "targeted_fix_blocked",
                    "next_action": "provide_post_reentry_targeted_fix_prompt",
                    "manual_review_required": False,
                    "targeted_fix_required": True,
                    "summary": summary or "Targeted-fix decision requires non-empty prompt.",
                }
            )
    elif assimilation_status == "assimilated":
        if normalized_decision == "approve":
            state.update(
                {
                    "status": "ready",
                    "route_status": "ready",
                    "blocked_reason": "none",
                    "route_decision": "approve",
                    "next_action": "prepare_post_reentry_approve_boundary",
                    "manual_review_required": False,
                    "targeted_fix_required": False,
                    "approve_allowed": True,
                    "reject_allowed": False,
                    "no_action_allowed": False,
                    "targeted_fix_prompt_present": False,
                    "summary": summary or "Post-reentry review approved.",
                }
            )
        elif normalized_decision == "reject":
            state.update(
                {
                    "status": "ready",
                    "route_status": "ready",
                    "blocked_reason": "none",
                    "route_decision": "reject",
                    "next_action": "prepare_post_reentry_reject_boundary",
                    "manual_review_required": False,
                    "targeted_fix_required": False,
                    "approve_allowed": False,
                    "reject_allowed": True,
                    "no_action_allowed": False,
                    "targeted_fix_prompt_present": False,
                    "summary": summary or "Post-reentry review rejected.",
                }
            )
        elif normalized_decision == "targeted_fix":
            state.update(
                {
                    "status": "ready",
                    "route_status": "ready",
                    "blocked_reason": "none",
                    "route_decision": "targeted_fix",
                    "next_action": "prepare_post_reentry_targeted_fix_prompt",
                    "manual_review_required": False,
                    "targeted_fix_required": True,
                    "approve_allowed": False,
                    "reject_allowed": False,
                    "no_action_allowed": False,
                    "targeted_fix_prompt_present": targeted_fix_prompt_present,
                    "summary": summary or "Post-reentry follow-up targeted fix requested.",
                }
            )
        elif normalized_decision == "no_action":
            state.update(
                {
                    "status": "ready",
                    "route_status": "ready",
                    "blocked_reason": "none",
                    "route_decision": "no_action",
                    "next_action": "complete_post_reentry_no_action",
                    "manual_review_required": False,
                    "targeted_fix_required": False,
                    "approve_allowed": False,
                    "reject_allowed": False,
                    "no_action_allowed": True,
                    "targeted_fix_prompt_present": False,
                    "summary": summary or "Post-reentry review indicates no action.",
                }
            )
    try:
        Path(route_decision_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(route_decision_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_route_executor_boundary_state(
    *,
    route_decision_path: Path,
) -> dict[str, Any]:
    normalized_route_decision_path = _normalize_text(
        str(route_decision_path),
        default=_TARGETED_FIX_POST_REENTRY_ROUTE_DECISION_PATH,
    )
    boundary_path = _TARGETED_FIX_POST_REENTRY_ROUTE_EXECUTOR_BOUNDARY_PATH
    route_payload: dict[str, Any] = {}
    try:
        loaded_payload = _read_json_object_if_exists(Path(normalized_route_decision_path))
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_payload = None
    if isinstance(loaded_payload, Mapping):
        route_payload = dict(loaded_payload)
    route_decision = _normalize_text(route_payload.get("route_decision"), default="")
    route_status = _normalize_text(route_payload.get("route_status"), default="blocked")
    state: dict[str, Any] = {
        "status": "blocked",
        "boundary_status": "blocked",
        "blocked_reason": "unsupported_or_missing_post_reentry_route_decision",
        "source": "targeted_fix_post_reentry_route_decision",
        "route_decision_path": normalized_route_decision_path,
        "route_decision": route_decision,
        "route_status": route_status,
        "next_action": "manual_review_required",
        "executor_kind": "manual_review",
        "execution_allowed": False,
        "cycle_closure_allowed": False,
        "approval_boundary_allowed": False,
        "reject_boundary_allowed": False,
        "targeted_fix_prompt_emission_allowed": False,
        "codex_reentry_allowed": False,
        "commit_allowed": False,
        "rollback_allowed": False,
        "manual_review_required": True,
        "summary": "Post-reentry route decision missing or unsupported; manual review required.",
    }
    if route_decision == "completed_no_diff":
        state.update(
            {
                "status": "ready",
                "boundary_status": "ready",
                "blocked_reason": "none",
                "next_action": "complete_post_reentry_no_diff",
                "executor_kind": "cycle_closure",
                "execution_allowed": False,
                "cycle_closure_allowed": True,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": False,
                "summary": "Post-reentry route is completed_no_diff; cycle closure is ready.",
            }
        )
    elif route_decision == "no_action":
        state.update(
            {
                "status": "ready",
                "boundary_status": "ready",
                "blocked_reason": "none",
                "next_action": "complete_post_reentry_no_action",
                "executor_kind": "cycle_closure",
                "execution_allowed": False,
                "cycle_closure_allowed": True,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": False,
                "summary": "Post-reentry route is no_action; cycle closure is ready.",
            }
        )
    elif route_decision == "approve":
        state.update(
            {
                "status": "ready",
                "boundary_status": "ready",
                "blocked_reason": "none",
                "next_action": "prepare_post_reentry_approve_boundary",
                "executor_kind": "approve_boundary",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": True,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": False,
                "summary": "Post-reentry route is approve; only approval boundary preparation is ready.",
            }
        )
    elif route_decision == "reject":
        state.update(
            {
                "status": "ready",
                "boundary_status": "ready",
                "blocked_reason": "none",
                "next_action": "prepare_post_reentry_reject_boundary",
                "executor_kind": "reject_boundary",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": True,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": False,
                "summary": "Post-reentry route is reject; only reject boundary preparation is ready.",
            }
        )
    elif route_decision == "targeted_fix":
        state.update(
            {
                "status": "ready",
                "boundary_status": "ready",
                "blocked_reason": "none",
                "next_action": "prepare_post_reentry_targeted_fix_prompt",
                "executor_kind": "targeted_fix_prompt_emission",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": True,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": False,
                "summary": (
                    "Post-reentry route is targeted_fix; targeted-fix prompt emission preparation is ready."
                ),
            }
        )
    elif route_decision in {"await_review_response", "await_valid_review_response"}:
        state.update(
            {
                "status": "blocked",
                "boundary_status": "blocked",
                "blocked_reason": "post_reentry_review_response_required",
                "next_action": "provide_post_reentry_review_response",
                "executor_kind": "manual_review_input",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": True,
                "summary": "Post-reentry review response is required before any route preparation.",
            }
        )
    elif route_decision == "targeted_fix_blocked":
        state.update(
            {
                "status": "blocked",
                "boundary_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_missing",
                "next_action": "provide_post_reentry_targeted_fix_prompt",
                "executor_kind": "manual_targeted_fix_prompt_input",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": True,
                "summary": "Targeted-fix prompt is missing; manual prompt input is required.",
            }
        )
    elif route_decision in {"manual_review_required", "blocked"}:
        state.update(
            {
                "status": "blocked",
                "boundary_status": "blocked",
                "blocked_reason": "unsupported_or_missing_post_reentry_route_decision",
                "next_action": "manual_review_required",
                "executor_kind": "manual_review",
                "execution_allowed": False,
                "cycle_closure_allowed": False,
                "approval_boundary_allowed": False,
                "reject_boundary_allowed": False,
                "targeted_fix_prompt_emission_allowed": False,
                "codex_reentry_allowed": False,
                "commit_allowed": False,
                "rollback_allowed": False,
                "manual_review_required": True,
                "summary": "Post-reentry route remains blocked; manual review is required.",
            }
        )
    try:
        Path(boundary_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(boundary_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_next_step_handoff_state(
    *,
    route_executor_boundary_state: Mapping[str, Any] | None,
    route_decision_path: Path,
    route_executor_boundary_path: Path,
) -> dict[str, Any]:
    boundary_state = (
        dict(route_executor_boundary_state)
        if isinstance(route_executor_boundary_state, Mapping)
        else {}
    )
    handoff_path = _TARGETED_FIX_POST_REENTRY_NEXT_STEP_HANDOFF_PATH
    route_decision = _normalize_text(boundary_state.get("route_decision"), default="")
    boundary_status = _normalize_text(boundary_state.get("boundary_status"), default="blocked")
    blocked_reason = _normalize_text(
        boundary_state.get("blocked_reason"),
        default="unsupported_or_missing_post_reentry_route_decision",
    )
    executor_kind = _normalize_text(boundary_state.get("executor_kind"), default="manual_review")
    next_action = _normalize_text(boundary_state.get("next_action"), default="manual_review_required")
    state: dict[str, Any] = {
        "status": "blocked",
        "handoff_status": "blocked",
        "blocked_reason": blocked_reason,
        "source": "targeted_fix_post_reentry_route_executor_boundary",
        "route_decision_path": _normalize_text(
            str(route_decision_path),
            default=_TARGETED_FIX_POST_REENTRY_ROUTE_DECISION_PATH,
        ),
        "route_executor_boundary_path": _normalize_text(
            str(route_executor_boundary_path),
            default=_TARGETED_FIX_POST_REENTRY_ROUTE_EXECUTOR_BOUNDARY_PATH,
        ),
        "route_decision": route_decision,
        "handoff_kind": "manual_review",
        "next_action": next_action,
        "action_consumable": False,
        "manual_review_required": True,
        "execution_allowed": False,
        "summary": "Post-reentry route handoff is blocked pending manual review.",
    }
    if boundary_status == "ready":
        if executor_kind == "cycle_closure":
            state.update(
                {
                    "status": "ready",
                    "handoff_status": "ready",
                    "blocked_reason": "none",
                    "handoff_kind": "cycle_closure",
                    "action_consumable": True,
                    "manual_review_required": False,
                    "execution_allowed": False,
                    "summary": "Cycle closure next-step handoff is ready.",
                }
            )
        elif executor_kind == "approve_boundary":
            state.update(
                {
                    "status": "ready",
                    "handoff_status": "ready",
                    "blocked_reason": "none",
                    "handoff_kind": "approve_boundary",
                    "action_consumable": True,
                    "manual_review_required": False,
                    "execution_allowed": False,
                    "summary": "Approve boundary preparation handoff is ready.",
                }
            )
        elif executor_kind == "reject_boundary":
            state.update(
                {
                    "status": "ready",
                    "handoff_status": "ready",
                    "blocked_reason": "none",
                    "handoff_kind": "reject_boundary",
                    "action_consumable": True,
                    "manual_review_required": False,
                    "execution_allowed": False,
                    "summary": "Reject boundary preparation handoff is ready.",
                }
            )
        elif executor_kind == "targeted_fix_prompt_emission":
            state.update(
                {
                    "status": "ready",
                    "handoff_status": "ready",
                    "blocked_reason": "none",
                    "handoff_kind": "targeted_fix_prompt_emission",
                    "action_consumable": True,
                    "manual_review_required": False,
                    "execution_allowed": False,
                    "summary": "Targeted-fix prompt emission preparation handoff is ready.",
                }
            )
    try:
        Path(handoff_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(handoff_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_prompt_emission_state(
    *,
    route_decision_path: Path,
    review_assimilation_path: Path,
    review_response_path: Path,
    route_executor_boundary_path: Path,
    next_step_handoff_path: Path,
    emitted_prompt_path: Path,
) -> dict[str, Any]:
    normalized_route_decision_path = _normalize_text(
        str(route_decision_path),
        default=_TARGETED_FIX_POST_REENTRY_ROUTE_DECISION_PATH,
    )
    normalized_review_assimilation_path = _normalize_text(
        str(review_assimilation_path),
        default=_TARGETED_FIX_POST_REENTRY_REVIEW_ASSIMILATION_PATH,
    )
    normalized_review_response_path = _normalize_text(
        str(review_response_path),
        default=_TARGETED_FIX_POST_REENTRY_REVIEW_RESPONSE_PATH,
    )
    normalized_route_executor_boundary_path = _normalize_text(
        str(route_executor_boundary_path),
        default=_TARGETED_FIX_POST_REENTRY_ROUTE_EXECUTOR_BOUNDARY_PATH,
    )
    normalized_next_step_handoff_path = _normalize_text(
        str(next_step_handoff_path),
        default=_TARGETED_FIX_POST_REENTRY_NEXT_STEP_HANDOFF_PATH,
    )
    normalized_emitted_prompt_path = _normalize_text(
        str(emitted_prompt_path),
        default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
    )

    route_payload: dict[str, Any] = {}
    try:
        loaded_route_payload = _read_json_object_if_exists(Path(normalized_route_decision_path))
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_route_payload = None
    if isinstance(loaded_route_payload, Mapping):
        route_payload = dict(loaded_route_payload)

    review_assimilation_payload: dict[str, Any] = {}
    try:
        loaded_review_assimilation_payload = _read_json_object_if_exists(
            Path(normalized_review_assimilation_path)
        )
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_review_assimilation_payload = None
    if isinstance(loaded_review_assimilation_payload, Mapping):
        review_assimilation_payload = dict(loaded_review_assimilation_payload)

    review_response_payload: dict[str, Any] = {}
    try:
        loaded_review_response_payload = _read_json_object_if_exists(Path(normalized_review_response_path))
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_review_response_payload = None
    if isinstance(loaded_review_response_payload, Mapping):
        review_response_payload = dict(loaded_review_response_payload)

    route_executor_boundary_payload: dict[str, Any] = {}
    try:
        loaded_route_executor_boundary_payload = _read_json_object_if_exists(
            Path(normalized_route_executor_boundary_path)
        )
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_route_executor_boundary_payload = None
    if isinstance(loaded_route_executor_boundary_payload, Mapping):
        route_executor_boundary_payload = dict(loaded_route_executor_boundary_payload)

    route_decision = _normalize_text(route_payload.get("route_decision"), default="")
    route_status = _normalize_text(route_payload.get("route_status"), default="blocked")
    targeted_fix_required = bool(route_payload.get("targeted_fix_required", False))
    boundary_status = _normalize_text(
        route_executor_boundary_payload.get("boundary_status"),
        default="blocked",
    )
    executor_kind = _normalize_text(
        route_executor_boundary_payload.get("executor_kind"),
        default="manual_review",
    )
    targeted_fix_prompt_emission_allowed = bool(
        route_executor_boundary_payload.get("targeted_fix_prompt_emission_allowed", False)
    )
    execution_allowed = bool(route_executor_boundary_payload.get("execution_allowed", False))
    codex_reentry_allowed = bool(route_executor_boundary_payload.get("codex_reentry_allowed", False))

    state: dict[str, Any] = {
        "status": "not_applicable",
        "emission_status": "not_applicable",
        "blocked_reason": "route_not_targeted_fix",
        "attempted": False,
        "source": "targeted_fix_post_reentry_route_decision",
        "route_decision_path": normalized_route_decision_path,
        "review_assimilation_path": normalized_review_assimilation_path,
        "review_response_path": normalized_review_response_path,
        "route_executor_boundary_path": normalized_route_executor_boundary_path,
        "next_step_handoff_path": normalized_next_step_handoff_path,
        "emitted_prompt_path": normalized_emitted_prompt_path,
        "route_decision": route_decision,
        "route_status": route_status,
        "executor_kind": executor_kind,
        "targeted_fix_prompt_emission_allowed": targeted_fix_prompt_emission_allowed,
        "targeted_fix_prompt_present": False,
        "targeted_fix_prompt_length": 0,
        "prompt_written": False,
        "safety_check_passed": False,
        "safety_blocked_fragment": "none",
        "next_action": "none",
        "summary": "Post-reentry prompt emission is not applicable because route is not targeted_fix.",
    }
    if route_decision != "targeted_fix":
        return state

    activation_allowed = (
        route_status == "ready"
        and targeted_fix_required
        and boundary_status == "ready"
        and executor_kind == "targeted_fix_prompt_emission"
        and targeted_fix_prompt_emission_allowed
        and (not execution_allowed)
        and (not codex_reentry_allowed)
    )
    if not activation_allowed:
        state.update(
            {
                "status": "blocked",
                "emission_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_emission_not_allowed",
                "attempted": False,
                "source": "targeted_fix_post_reentry_route_executor_boundary",
                "next_action": "manual_review_required",
                "summary": (
                    "Post-reentry targeted-fix prompt emission is blocked because executor boundary "
                    "conditions are not satisfied."
                ),
            }
        )
        return state

    targeted_fix_prompt = _normalize_text(
        review_assimilation_payload.get("targeted_fix_prompt"),
        default="",
    )
    prompt_source = "targeted_fix_post_reentry_review_assimilation"
    if not targeted_fix_prompt:
        targeted_fix_prompt = _normalize_text(
            review_response_payload.get("targeted_fix_prompt"),
            default="",
        )
        prompt_source = "targeted_fix_post_reentry_review_response"
    targeted_fix_prompt_present = bool(targeted_fix_prompt)
    targeted_fix_prompt_length = len(targeted_fix_prompt)
    state.update(
        {
            "attempted": True,
            "source": prompt_source,
            "targeted_fix_prompt_present": targeted_fix_prompt_present,
            "targeted_fix_prompt_length": targeted_fix_prompt_length,
            "targeted_fix_prompt_text": targeted_fix_prompt,
        }
    )
    if not targeted_fix_prompt_present:
        state.update(
            {
                "status": "blocked",
                "emission_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_missing",
                "prompt_written": False,
                "safety_check_passed": False,
                "next_action": "provide_post_reentry_targeted_fix_prompt",
                "summary": "Post-reentry targeted-fix prompt is missing.",
            }
        )
        return state

    prompt_text_lower = targeted_fix_prompt.lower()
    safety_blocked_fragment = "none"
    for fragment in _TARGETED_FIX_POST_REENTRY_PROMPT_EMISSION_FORBIDDEN_FRAGMENTS:
        if fragment in prompt_text_lower:
            safety_blocked_fragment = fragment
            break
    if safety_blocked_fragment != "none":
        state.update(
            {
                "status": "blocked",
                "emission_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_failed_safety_check",
                "prompt_written": False,
                "safety_check_passed": False,
                "safety_blocked_fragment": safety_blocked_fragment,
                "next_action": "revise_post_reentry_targeted_fix_prompt",
                "summary": "Post-reentry targeted-fix prompt failed safety checks.",
            }
        )
        return state

    state.update(
        {
            "status": "ready",
            "emission_status": "ready",
            "blocked_reason": "none",
            "prompt_written": False,
            "safety_check_passed": True,
            "safety_blocked_fragment": "none",
            "next_action": "prepare_post_reentry_targeted_fix_codex_reentry",
            "summary": "Post-reentry targeted-fix prompt is ready for deterministic emission.",
        }
    )
    return state


def _write_targeted_fix_post_reentry_prompt_if_allowed(
    *,
    prompt_emission_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    state = dict(prompt_emission_state) if isinstance(prompt_emission_state, Mapping) else {}
    emission_status = _normalize_text(state.get("emission_status"), default="not_applicable")
    if emission_status != "ready":
        state.pop("targeted_fix_prompt_text", None)
        return state

    prompt_text = _normalize_text(state.get("targeted_fix_prompt_text"), default="")
    emitted_prompt_path = Path(
        _normalize_text(
            state.get("emitted_prompt_path"),
            default=_TARGETED_FIX_REENTRY_EXECUTION_PROMPT_PATH,
        )
    )
    if not prompt_text:
        state.update(
            {
                "status": "blocked",
                "emission_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_missing",
                "attempted": True,
                "prompt_written": False,
                "targeted_fix_prompt_present": False,
                "targeted_fix_prompt_length": 0,
                "safety_check_passed": False,
                "next_action": "provide_post_reentry_targeted_fix_prompt",
                "summary": "Post-reentry targeted-fix prompt is missing.",
            }
        )
        state.pop("targeted_fix_prompt_text", None)
        return state
    try:
        emitted_prompt_path.parent.mkdir(parents=True, exist_ok=True)
        emitted_prompt_path.write_text(prompt_text.rstrip() + "\n", encoding="utf-8")
    except OSError:
        state.update(
            {
                "status": "blocked",
                "emission_status": "blocked",
                "blocked_reason": "post_reentry_targeted_fix_prompt_write_failed",
                "attempted": True,
                "prompt_written": False,
                "next_action": "revise_post_reentry_targeted_fix_prompt",
                "summary": "Post-reentry targeted-fix prompt emission failed to write.",
            }
        )
        state.pop("targeted_fix_prompt_text", None)
        return state

    state.update(
        {
            "status": "ready",
            "emission_status": "ready",
            "blocked_reason": "none",
            "attempted": True,
            "prompt_written": True,
            "targeted_fix_prompt_present": True,
            "targeted_fix_prompt_length": len(prompt_text),
            "emitted_prompt_path": str(emitted_prompt_path),
            "next_action": "prepare_post_reentry_targeted_fix_codex_reentry",
            "summary": "Post-reentry targeted-fix prompt emitted for deterministic Codex reentry.",
        }
    )
    state.pop("targeted_fix_prompt_text", None)
    return state


def _build_targeted_fix_post_reentry_cycle_closure_result_state(
    *,
    next_step_handoff_path: Path,
    route_executor_boundary_path: Path,
    route_decision_path: Path,
    diff_capture_path: Path,
    review_handoff_path: Path,
) -> dict[str, Any]:
    normalized_next_step_handoff_path = _normalize_text(
        str(next_step_handoff_path),
        default=_TARGETED_FIX_POST_REENTRY_NEXT_STEP_HANDOFF_PATH,
    )
    normalized_route_executor_boundary_path = _normalize_text(
        str(route_executor_boundary_path),
        default=_TARGETED_FIX_POST_REENTRY_ROUTE_EXECUTOR_BOUNDARY_PATH,
    )
    normalized_route_decision_path = _normalize_text(
        str(route_decision_path),
        default=_TARGETED_FIX_POST_REENTRY_ROUTE_DECISION_PATH,
    )
    normalized_diff_capture_path = _normalize_text(
        str(diff_capture_path),
        default=_TARGETED_FIX_POST_REENTRY_DIFF_CAPTURE_PATH,
    )
    normalized_review_handoff_path = _normalize_text(
        str(review_handoff_path),
        default=_TARGETED_FIX_POST_REENTRY_REVIEW_HANDOFF_PATH,
    )
    cycle_closure_result_path = _TARGETED_FIX_POST_REENTRY_CYCLE_CLOSURE_RESULT_PATH
    route_decision_payload: dict[str, Any] = {}
    try:
        loaded_route_decision_payload = _read_json_object_if_exists(
            Path(normalized_route_decision_path)
        )
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_route_decision_payload = None
    if isinstance(loaded_route_decision_payload, Mapping):
        route_decision_payload = dict(loaded_route_decision_payload)
    handoff_payload: dict[str, Any] = {}
    try:
        loaded_handoff_payload = _read_json_object_if_exists(Path(normalized_next_step_handoff_path))
    except (OSError, ValueError, json.JSONDecodeError):
        loaded_handoff_payload = None
    if isinstance(loaded_handoff_payload, Mapping):
        handoff_payload = dict(loaded_handoff_payload)

    route_decision = _normalize_text(
        handoff_payload.get("route_decision"),
        default=_normalize_text(route_decision_payload.get("route_decision"), default=""),
    )
    handoff_status = _normalize_text(handoff_payload.get("handoff_status"), default="blocked")
    handoff_kind = _normalize_text(handoff_payload.get("handoff_kind"), default="")
    next_action = _normalize_text(
        handoff_payload.get("next_action"),
        default="manual_review_required",
    )
    action_consumable = bool(handoff_payload.get("action_consumable", False))
    execution_allowed = bool(handoff_payload.get("execution_allowed", False))
    manual_review_required = bool(handoff_payload.get("manual_review_required", True))
    state: dict[str, Any] = {
        "status": "blocked",
        "closure_status": "blocked",
        "blocked_reason": "post_reentry_next_step_handoff_not_ready",
        "source": "targeted_fix_post_reentry_next_step_handoff",
        "next_step_handoff_path": normalized_next_step_handoff_path,
        "route_executor_boundary_path": normalized_route_executor_boundary_path,
        "route_decision_path": normalized_route_decision_path,
        "diff_capture_path": normalized_diff_capture_path,
        "review_handoff_path": normalized_review_handoff_path,
        "cycle_closure_result_path": cycle_closure_result_path,
        "handoff_status": handoff_status,
        "handoff_kind": handoff_kind,
        "route_decision": route_decision,
        "terminal_state": "blocked",
        "cycle_closed": False,
        "no_diff_close": False,
        "no_action_close": False,
        "approval_required": False,
        "targeted_fix_required": False,
        "codex_reentry_required": False,
        "manual_review_required": True,
        "execution_performed": False,
        "next_action": "manual_review_required",
        "summary": "Post-reentry next-step handoff is not ready for deterministic cycle closure.",
    }
    if handoff_status != "ready":
        pass
    elif handoff_kind != "cycle_closure":
        state.update(
            {
                "status": "not_applicable",
                "closure_status": "not_applicable",
                "terminal_state": "not_closed",
                "blocked_reason": "handoff_not_cycle_closure",
                "cycle_closed": False,
                "manual_review_required": False,
                "next_action": next_action,
                "summary": "Next-step handoff is ready but not cycle_closure; cycle close result is not applicable.",
            }
        )
    else:
        activation_ready = (
            action_consumable
            and not execution_allowed
            and not manual_review_required
            and next_action
            in {
                "complete_post_reentry_no_diff",
                "complete_post_reentry_no_action",
            }
        )
        if activation_ready and next_action == "complete_post_reentry_no_diff":
            state.update(
                {
                    "status": "completed",
                    "closure_status": "completed",
                    "blocked_reason": "none",
                    "terminal_state": "completed_no_diff",
                    "cycle_closed": True,
                    "no_diff_close": True,
                    "no_action_close": False,
                    "approval_required": False,
                    "targeted_fix_required": False,
                    "codex_reentry_required": False,
                    "manual_review_required": False,
                    "execution_performed": False,
                    "next_action": "none",
                    "summary": "Post-reentry cycle closed with completed_no_diff and no execution.",
                }
            )
        elif activation_ready and next_action == "complete_post_reentry_no_action":
            state.update(
                {
                    "status": "completed",
                    "closure_status": "completed",
                    "blocked_reason": "none",
                    "terminal_state": "completed_no_action",
                    "cycle_closed": True,
                    "no_diff_close": False,
                    "no_action_close": True,
                    "approval_required": False,
                    "targeted_fix_required": False,
                    "codex_reentry_required": False,
                    "manual_review_required": False,
                    "execution_performed": False,
                    "next_action": "none",
                    "summary": "Post-reentry cycle closed with completed_no_action and no execution.",
                }
            )
    try:
        Path(cycle_closure_result_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(cycle_closure_result_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_terminal_summary_state(
    *,
    cycle_closure_result_state: Mapping[str, Any] | None,
    cycle_closure_result_path: Path,
) -> dict[str, Any]:
    result_state = (
        dict(cycle_closure_result_state)
        if isinstance(cycle_closure_result_state, Mapping)
        else {}
    )
    terminal_summary_path = _TARGETED_FIX_POST_REENTRY_TERMINAL_SUMMARY_PATH
    cycle_closure_status = _normalize_text(result_state.get("closure_status"), default="blocked")
    terminal_state = _normalize_text(result_state.get("terminal_state"), default="blocked")
    blocked_reason = _normalize_text(
        result_state.get("blocked_reason"),
        default="post_reentry_next_step_handoff_not_ready",
    )
    route_decision = _normalize_text(result_state.get("route_decision"), default="")
    final_next_action = _normalize_text(result_state.get("next_action"), default="manual_review_required")
    cycle_closed = bool(result_state.get("cycle_closed", False))
    requires_codex_reentry = bool(result_state.get("codex_reentry_required", False))
    requires_manual_review = bool(result_state.get("manual_review_required", True))
    state: dict[str, Any] = {
        "status": "blocked",
        "terminal_status": "blocked",
        "blocked_reason": blocked_reason,
        "source": "targeted_fix_post_reentry_cycle_closure_result",
        "cycle_closure_result_path": _normalize_text(
            str(cycle_closure_result_path),
            default=_TARGETED_FIX_POST_REENTRY_CYCLE_CLOSURE_RESULT_PATH,
        ),
        "terminal_summary_path": terminal_summary_path,
        "terminal_state": terminal_state,
        "cycle_closed": cycle_closed,
        "route_decision": route_decision,
        "final_next_action": final_next_action,
        "safe_to_stop": False,
        "safe_to_commit_prompt_changes": False,
        "requires_codex_reentry": requires_codex_reentry,
        "requires_manual_review": requires_manual_review,
        "summary": "Post-reentry terminal summary is blocked pending manual review.",
    }
    if cycle_closure_status == "completed" and terminal_state in {
        "completed_no_diff",
        "completed_no_action",
    }:
        state.update(
            {
                "status": "completed",
                "terminal_status": "completed",
                "blocked_reason": "none",
                "cycle_closed": True,
                "final_next_action": "none",
                "safe_to_stop": True,
                "safe_to_commit_prompt_changes": True,
                "requires_codex_reentry": False,
                "requires_manual_review": False,
                "summary": (
                    "Post-reentry cycle closure reached terminal completion with no further execution."
                ),
            }
        )
    elif cycle_closure_status == "not_applicable":
        state.update(
            {
                "status": "not_applicable",
                "terminal_status": "not_applicable",
                "safe_to_stop": False,
                "safe_to_commit_prompt_changes": False,
                "requires_codex_reentry": False,
                "requires_manual_review": False,
                "summary": "Post-reentry terminal summary is not applicable for non-cycle handoff.",
            }
        )
    try:
        Path(terminal_summary_path).parent.mkdir(parents=True, exist_ok=True)
        _write_json(Path(terminal_summary_path), state)
    except OSError:
        pass
    return state


def _build_targeted_fix_post_reentry_bounded_cycle_state(
    *,
    prompt_emission_path: Path,
    prompt_emission_receipt_path: Path,
    codex_reentry_execution_receipt_path: Path,
    diff_capture_path: Path,
    review_handoff_path: Path,
    review_assimilation_path: Path,
    route_decision_path: Path,
    route_executor_boundary_path: Path,
    next_step_handoff_path: Path,
    cycle_closure_result_path: Path,
    terminal_summary_path: Path,
    current_cycle_count: int,
    max_cycle_count: int,
    bounded_cycle_state_path: Path,
    bounded_cycle_decision_path: Path,
    bounded_cycle_receipt_path: Path,
) -> dict[str, Any]:
    def _load_payload(path: Path) -> dict[str, Any]:
        try:
            loaded = _read_json_object_if_exists(path)
        except (OSError, ValueError, json.JSONDecodeError):
            loaded = None
        return dict(loaded) if isinstance(loaded, Mapping) else {}

    prompt_emission_payload = _load_payload(prompt_emission_path)
    prompt_emission_receipt_payload = _load_payload(prompt_emission_receipt_path)
    codex_reentry_execution_payload = _load_payload(codex_reentry_execution_receipt_path)
    diff_capture_payload = _load_payload(diff_capture_path)
    review_handoff_payload = _load_payload(review_handoff_path)
    _ = _load_payload(review_assimilation_path)
    route_decision_payload = _load_payload(route_decision_path)
    route_executor_boundary_payload = _load_payload(route_executor_boundary_path)
    _ = _load_payload(next_step_handoff_path)
    _ = _load_payload(cycle_closure_result_path)
    terminal_summary_payload = _load_payload(terminal_summary_path)

    route_decision = _normalize_text(route_decision_payload.get("route_decision"), default="")
    route_status = _normalize_text(route_decision_payload.get("route_status"), default="blocked")
    targeted_fix_required = bool(route_decision_payload.get("targeted_fix_required", False))
    boundary_status = _normalize_text(
        route_executor_boundary_payload.get("boundary_status"),
        default="blocked",
    )
    executor_kind = _normalize_text(
        route_executor_boundary_payload.get("executor_kind"),
        default="manual_review",
    )
    targeted_fix_prompt_emission_allowed = bool(
        route_executor_boundary_payload.get("targeted_fix_prompt_emission_allowed", False)
    )

    prompt_emission_status = _normalize_text(
        prompt_emission_payload.get("emission_status"),
        default=_normalize_text(prompt_emission_payload.get("status"), default="not_applicable"),
    )
    prompt_emission_receipt_status = _normalize_text(
        prompt_emission_receipt_payload.get("receipt_status"),
        default="not_applicable",
    )
    prompt_emission_receipt_state_status = _normalize_text(
        prompt_emission_receipt_payload.get("status"),
        default="not_applicable",
    )
    prompt_written = bool(prompt_emission_receipt_payload.get("prompt_written", False))
    prompt_ready_for_codex_reentry = bool(
        prompt_emission_receipt_payload.get("ready_for_codex_reentry", False)
    )
    prompt_receipt_codex_reentry_executed = bool(
        prompt_emission_receipt_payload.get("codex_reentry_executed", False)
    )
    prompt_receipt_execution_performed = bool(
        prompt_emission_receipt_payload.get("execution_performed", False)
    )

    codex_reentry_execution_status = _normalize_text(
        codex_reentry_execution_payload.get("execution_status"),
        default="not_applicable",
    )
    codex_reentry_gate_status = _normalize_text(
        codex_reentry_execution_payload.get("gate_status"),
        default="not_applicable",
    )
    codex_reentry_executed = bool(codex_reentry_execution_payload.get("codex_reentry_executed", False))
    codex_reentry_execution_performed = bool(
        codex_reentry_execution_payload.get("execution_performed", False)
    )
    codex_reentry_exit_code = _as_optional_int(codex_reentry_execution_payload.get("exit_code"))

    diff_capture_status = _normalize_text(
        diff_capture_payload.get("capture_status"),
        default="not_applicable",
    )
    diff_has_diff = bool(diff_capture_payload.get("has_diff", False))
    review_handoff_status = _normalize_text(
        review_handoff_payload.get("handoff_status"),
        default="not_applicable",
    )
    review_required = bool(review_handoff_payload.get("review_required", False))

    terminal_status = _normalize_text(
        terminal_summary_payload.get("terminal_status"),
        default="not_applicable",
    )
    terminal_summary_state_status = _normalize_text(
        terminal_summary_payload.get("status"),
        default="not_applicable",
    )
    terminal_state = _normalize_text(
        terminal_summary_payload.get("terminal_state"),
        default="blocked",
    )
    terminal_cycle_closed = bool(terminal_summary_payload.get("cycle_closed", False))
    terminal_final_next_action = _normalize_text(
        terminal_summary_payload.get("final_next_action"),
        default="manual_review_required",
    )

    state: dict[str, Any] = {
        "status": "blocked",
        "cycle_status": "blocked",
        "blocked_reason": "post_reentry_bounded_cycle_inputs_incomplete",
        "source": "targeted_fix_post_reentry_bounded_cycle_controller",
        "current_cycle_count": int(current_cycle_count),
        "max_cycle_count": int(max_cycle_count),
        "cycle_closed": False,
        "bounded_cycle_complete": False,
        "should_continue": False,
        "should_emit_targeted_fix_prompt": False,
        "should_execute_codex_reentry": False,
        "should_capture_diff": False,
        "should_request_review": False,
        "should_block": True,
        "route_decision": route_decision,
        "route_status": route_status,
        "prompt_emission_status": prompt_emission_status,
        "prompt_emission_receipt_status": prompt_emission_receipt_status,
        "codex_reentry_execution_status": codex_reentry_execution_status,
        "codex_reentry_gate_status": codex_reentry_gate_status,
        "diff_capture_status": diff_capture_status,
        "review_handoff_status": review_handoff_status,
        "terminal_state": terminal_state,
        "safe_to_stop": False,
        "next_action": "manual_review_required",
        "summary": "Post-reentry bounded cycle inputs are incomplete; manual review required.",
        "targeted_fix_post_reentry_bounded_cycle_state_path": _normalize_text(
            str(bounded_cycle_state_path),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_STATE_PATH,
        ),
        "targeted_fix_post_reentry_bounded_cycle_decision_path": _normalize_text(
            str(bounded_cycle_decision_path),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DECISION_PATH,
        ),
        "targeted_fix_post_reentry_bounded_cycle_receipt_path": _normalize_text(
            str(bounded_cycle_receipt_path),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_RECEIPT_PATH,
        ),
    }

    terminal_completed = (
        terminal_summary_state_status == "completed"
        and terminal_status == "completed"
        and terminal_cycle_closed
        and terminal_final_next_action == "none"
    )
    diff_captured_no_diff_completed = (
        diff_capture_status == "captured_no_diff"
        and (not diff_has_diff)
        and (route_decision == "completed_no_diff" or terminal_completed)
    )
    if terminal_completed or diff_captured_no_diff_completed:
        state.update(
            {
                "status": "completed",
                "cycle_status": "completed",
                "blocked_reason": "none",
                "cycle_closed": True,
                "bounded_cycle_complete": True,
                "should_continue": False,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": False,
                "should_capture_diff": False,
                "should_request_review": False,
                "should_block": False,
                "safe_to_stop": True,
                "next_action": "none",
                "summary": "Post-reentry bounded cycle already terminal completed.",
            }
        )
        return state

    requires_targeted_fix_or_codex = (
        route_decision == "targeted_fix"
        or targeted_fix_required
        or (
            prompt_emission_receipt_state_status == "ready"
            and prompt_emission_receipt_status == "ready"
            and prompt_written
            and prompt_ready_for_codex_reentry
            and (not prompt_receipt_codex_reentry_executed)
            and (not prompt_receipt_execution_performed)
        )
        or (
            codex_reentry_execution_status == "completed"
            and codex_reentry_gate_status == "executed"
            and codex_reentry_executed
            and codex_reentry_execution_performed
            and codex_reentry_exit_code == 0
        )
    )
    if int(current_cycle_count) >= int(max_cycle_count) and requires_targeted_fix_or_codex:
        state.update(
            {
                "status": "blocked",
                "cycle_status": "max_cycle_count_reached",
                "blocked_reason": "max_post_reentry_targeted_fix_cycle_count_reached",
                "bounded_cycle_complete": False,
                "should_continue": False,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": False,
                "should_capture_diff": False,
                "should_request_review": False,
                "should_block": True,
                "safe_to_stop": False,
                "next_action": "manual_review_required_after_max_cycle_count",
                "summary": "Post-reentry targeted-fix bounded cycle reached max cycle count.",
            }
        )
        return state

    prompt_receipt_missing_or_not_ready = (
        (not prompt_emission_receipt_payload)
        or prompt_emission_receipt_status in {"not_applicable", "blocked", ""}
    )
    if (
        route_status == "ready"
        and route_decision == "targeted_fix"
        and targeted_fix_required
        and boundary_status == "ready"
        and executor_kind == "targeted_fix_prompt_emission"
        and targeted_fix_prompt_emission_allowed
        and prompt_receipt_missing_or_not_ready
    ):
        state.update(
            {
                "status": "ready",
                "cycle_status": "awaiting_prompt_emission",
                "blocked_reason": "none",
                "cycle_closed": False,
                "bounded_cycle_complete": False,
                "should_continue": True,
                "should_emit_targeted_fix_prompt": True,
                "should_execute_codex_reentry": False,
                "should_capture_diff": False,
                "should_request_review": False,
                "should_block": False,
                "safe_to_stop": False,
                "next_action": "run_prompt317_post_reentry_targeted_fix_prompt_emission",
                "summary": "Post-reentry targeted-fix route is waiting for prompt emission.",
            }
        )
        return state

    if (
        prompt_emission_receipt_state_status == "ready"
        and prompt_emission_receipt_status == "ready"
        and prompt_written
        and prompt_ready_for_codex_reentry
        and (not prompt_receipt_codex_reentry_executed)
        and (not prompt_receipt_execution_performed)
    ):
        state.update(
            {
                "status": "ready",
                "cycle_status": "awaiting_codex_reentry",
                "blocked_reason": "none",
                "cycle_closed": False,
                "bounded_cycle_complete": False,
                "should_continue": True,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": True,
                "should_capture_diff": False,
                "should_request_review": False,
                "should_block": False,
                "safe_to_stop": False,
                "next_action": "run_prompt318_post_reentry_targeted_fix_codex_reentry",
                "summary": "Post-reentry targeted-fix prompt is emitted and waiting for Codex reentry.",
            }
        )
        return state

    if codex_reentry_execution_status == "failed":
        state.update(
            {
                "status": "blocked",
                "cycle_status": "blocked",
                "blocked_reason": "post_reentry_codex_reentry_execution_failed",
                "cycle_closed": False,
                "bounded_cycle_complete": False,
                "should_continue": False,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": False,
                "should_capture_diff": False,
                "should_request_review": False,
                "should_block": True,
                "safe_to_stop": False,
                "next_action": "review_post_reentry_codex_reentry_failure",
                "summary": "Post-reentry Codex reentry execution failed and requires manual review.",
            }
        )
        return state

    if (
        codex_reentry_execution_status == "completed"
        and codex_reentry_gate_status == "executed"
        and codex_reentry_executed
        and codex_reentry_execution_performed
        and codex_reentry_exit_code == 0
    ):
        state.update(
            {
                "status": "ready",
                "cycle_status": "awaiting_post_reentry_diff_capture",
                "blocked_reason": "none",
                "cycle_closed": False,
                "bounded_cycle_complete": False,
                "should_continue": True,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": False,
                "should_capture_diff": True,
                "should_request_review": False,
                "should_block": False,
                "safe_to_stop": False,
                "next_action": "capture_post_reentry_diff_after_codex_reentry",
                "summary": "Post-reentry Codex reentry completed; waiting for diff capture.",
            }
        )
        return state

    if (
        diff_capture_status == "captured"
        and diff_has_diff
        and review_handoff_status == "ready"
        and review_required
    ):
        state.update(
            {
                "status": "ready",
                "cycle_status": "awaiting_post_reentry_review",
                "blocked_reason": "none",
                "cycle_closed": False,
                "bounded_cycle_complete": False,
                "should_continue": True,
                "should_emit_targeted_fix_prompt": False,
                "should_execute_codex_reentry": False,
                "should_capture_diff": False,
                "should_request_review": True,
                "should_block": False,
                "safe_to_stop": False,
                "next_action": "provide_post_reentry_review_response",
                "summary": "Post-reentry diff capture is ready and requires review response.",
            }
        )
        return state

    return state


def _build_targeted_fix_post_reentry_bounded_cycle_decision_state(
    *,
    bounded_cycle_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    state = dict(bounded_cycle_state) if isinstance(bounded_cycle_state, Mapping) else {}
    cycle_status = _normalize_text(state.get("cycle_status"), default="blocked")
    status = _normalize_text(state.get("status"), default="blocked")
    blocked_reason = _normalize_text(
        state.get("blocked_reason"),
        default="post_reentry_bounded_cycle_inputs_incomplete",
    )
    next_action = _normalize_text(state.get("next_action"), default="manual_review_required")
    decision = "blocked"
    if status == "completed" and cycle_status == "completed":
        decision = "stop_completed"
    elif status == "ready" and cycle_status == "awaiting_prompt_emission":
        decision = "emit_targeted_fix_prompt"
    elif status == "ready" and cycle_status == "awaiting_codex_reentry":
        decision = "execute_codex_reentry"
    elif status == "ready" and cycle_status == "awaiting_post_reentry_diff_capture":
        decision = "capture_post_reentry_diff"
    elif status == "ready" and cycle_status == "awaiting_post_reentry_review":
        decision = "request_review"
    elif status == "blocked" and cycle_status == "max_cycle_count_reached":
        decision = "max_cycle_count_reached"

    return {
        "status": status,
        "decision": decision,
        "blocked_reason": blocked_reason,
        "source": _normalize_text(
            state.get("source"),
            default="targeted_fix_post_reentry_bounded_cycle_state",
        ),
        "current_cycle_count": _as_non_negative_int(
            state.get("current_cycle_count"),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DEFAULT_CURRENT_CYCLE_COUNT,
        ),
        "max_cycle_count": _as_non_negative_int(
            state.get("max_cycle_count"),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DEFAULT_MAX_CYCLE_COUNT,
        ),
        "bounded_cycle_complete": bool(state.get("bounded_cycle_complete", False)),
        "safe_to_stop": bool(state.get("safe_to_stop", False)),
        "requires_manual_review": bool(state.get("should_block", False)),
        "requires_codex_reentry": bool(state.get("should_execute_codex_reentry", False)),
        "requires_prompt_emission": bool(state.get("should_emit_targeted_fix_prompt", False)),
        "requires_diff_capture": bool(state.get("should_capture_diff", False)),
        "requires_review_response": bool(state.get("should_request_review", False)),
        "next_action": next_action,
        "summary": _normalize_text(state.get("summary"), default=""),
    }


def _build_targeted_fix_post_reentry_bounded_cycle_receipt_state(
    *,
    bounded_cycle_state: Mapping[str, Any] | None,
    bounded_cycle_decision_state: Mapping[str, Any] | None,
) -> dict[str, Any]:
    state = dict(bounded_cycle_state) if isinstance(bounded_cycle_state, Mapping) else {}
    decision_state = (
        dict(bounded_cycle_decision_state)
        if isinstance(bounded_cycle_decision_state, Mapping)
        else {}
    )
    status = _normalize_text(state.get("status"), default="blocked")
    receipt_status = "blocked"
    if status == "completed":
        receipt_status = "completed"
    elif status == "ready":
        receipt_status = "ready"
    return {
        "status": status,
        "receipt_status": receipt_status,
        "blocked_reason": _normalize_text(
            state.get("blocked_reason"),
            default="post_reentry_bounded_cycle_inputs_incomplete",
        ),
        "source": _normalize_text(
            state.get("source"),
            default="targeted_fix_post_reentry_bounded_cycle_state",
        ),
        "bounded_cycle_complete": bool(state.get("bounded_cycle_complete", False)),
        "execution_performed": False,
        "codex_invoked": False,
        "current_cycle_count": _as_non_negative_int(
            state.get("current_cycle_count"),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DEFAULT_CURRENT_CYCLE_COUNT,
        ),
        "max_cycle_count": _as_non_negative_int(
            state.get("max_cycle_count"),
            default=_TARGETED_FIX_POST_REENTRY_BOUNDED_CYCLE_DEFAULT_MAX_CYCLE_COUNT,
        ),
        "final_decision": _normalize_text(decision_state.get("decision"), default="blocked"),
        "next_action": _normalize_text(
            decision_state.get("next_action"),
            default=_normalize_text(state.get("next_action"), default="manual_review_required"),
        ),
        "summary": _normalize_text(
            decision_state.get("summary"),
            default=_normalize_text(state.get("summary"), default=""),
        ),
    }


def _build_project_browser_autonomous_one_cycle_controller_state(
    *,
    approved_restart_payload: Mapping[str, Any] | None,
    prior_approved_restart_execution_payload: Mapping[str, Any] | None,
    execution_repo_path: str,
    dry_run: bool,
) -> dict[str, Any]:
    approved_restart = (
        dict(approved_restart_payload) if isinstance(approved_restart_payload, Mapping) else {}
    )
    prior_payload = (
        dict(prior_approved_restart_execution_payload)
        if isinstance(prior_approved_restart_execution_payload, Mapping)
        else {}
    )

    def _read_flag(key: str, *, default: bool = False) -> bool:
        value = prior_payload.get(key) if key in prior_payload else approved_restart.get(key)
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return value != 0
        text = _normalize_text(value, default="").lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return default

    def _read_non_negative_int_flag(key: str, *, default: int) -> int:
        value = prior_payload.get(key) if key in prior_payload else approved_restart.get(key)
        return _as_non_negative_int(value, default=default)

    one_cycle_controller_dir = Path("/tmp/codex-local-runner-decision/one_cycle_controller")
