def _build_project_browser_autonomous_patch_dry_run_state(
    *,
    patch_candidate_status: str,
    safe_patch_gate_status: str,
    safe_patch_gate_block_reason: str,
    expected_patch_path: str,
    touched_files: list[str] | None,
    forbidden_touched_files: list[str] | None,
    unsafe_operation_flags: list[str] | None,
    worktree_status: str,
    worktree_dirty: bool,
    human_review_required: bool,
    rollback_required: bool,
    execution_repo_path: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "ready_to_dry_run",
        "dry_run_passed",
        "dry_run_failed",
        "blocked_no_ready_gate",
        "blocked_missing_patch_path",
        "blocked_dirty_worktree",
        "blocked_forbidden_files",
        "blocked_unsafe_operations",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_command_unavailable",
        "blocked_timeout",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "wait_for_ready_patch_candidate",
        "run_bounded_dry_run_check",
        "proceed_to_safe_apply_gate_later",
        "manual_fix_patch_candidate",
        "human_review_required",
        "rollback_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "bounded_patch_dry_run_only",
        "single_command_max",
        "git_apply_check_only",
        "worktree_truth_compared_pre_post_when_available",
        "no_real_git_apply",
        "no_patch_application",
        "no_patch_file_write",
        "no_repo_file_modification_intended",
        "no_git_add_commit_push",
        "no_git_reset_clean",
        "no_github_mutation",
        "no_autonomous_loop",
    ]

    normalized_patch_candidate_status = _normalize_text(
        patch_candidate_status,
        default="insufficient_truth",
    )
    normalized_safe_patch_gate_status = _normalize_text(
        safe_patch_gate_status,
        default="insufficient_truth",
    )
    normalized_safe_patch_gate_block_reason = _normalize_text(
        safe_patch_gate_block_reason,
        default="insufficient_truth",
    )
    normalized_expected_patch_path = _normalize_text(expected_patch_path, default="")
    normalized_touched_files = _normalize_string_list(touched_files or [])
    normalized_forbidden_touched_files = _normalize_string_list(
        forbidden_touched_files or []
    )
    normalized_unsafe_operation_flags = _normalize_string_list(
        unsafe_operation_flags or []
    )
    normalized_worktree_status = _normalize_text(worktree_status, default="insufficient_truth")
    normalized_worktree_dirty = bool(worktree_dirty)
    if normalized_worktree_status in {"clean", "dirty"}:
        normalized_worktree_dirty = normalized_worktree_status == "dirty"
    elif normalized_worktree_status == "insufficient_truth":
        pass
    elif normalized_worktree_status:
        normalized_worktree_status = "insufficient_truth"

    required_inputs = [
        "patch_candidate_status",
        "safe_patch_gate_status",
        "expected_patch_path",
        "worktree_status",
        "worktree_dirty",
    ]
    available_inputs: list[str] = []
    if normalized_patch_candidate_status:
        available_inputs.append("patch_candidate_status")
    if normalized_safe_patch_gate_status:
        available_inputs.append("safe_patch_gate_status")
    if normalized_expected_patch_path:
        available_inputs.append("expected_patch_path")
    if normalized_worktree_status in {"clean", "dirty"}:
        available_inputs.extend(["worktree_status", "worktree_dirty"])
    missing_inputs = _serialize_required_signals(
        [
            input_name
            for input_name in required_inputs
            if input_name not in set(available_inputs)
        ]
    )

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    next_action = "insufficient_truth"
    dry_run_command = (
        f"git apply --check {normalized_expected_patch_path}"
        if normalized_expected_patch_path
        else "git apply --check <missing_patch_path>"
    )
    dry_run_attempted = False
    dry_run_completed = False
    dry_run_exit_code = -1
    dry_run_stdout_excerpt = ""
    dry_run_stderr_excerpt = ""
    dry_run_passed = False
    dry_run_failed = False
    dry_run_timeout_seconds = 5.0
    pre_worktree_signature = (
        f"{normalized_worktree_status}:{int(bool(normalized_worktree_dirty))}"
        if normalized_worktree_status in {"clean", "dirty"}
        else ""
    )

    def _excerpt(text: str, *, max_chars: int = 600, max_lines: int = 12) -> str:
        normalized = _normalize_text(text, default="")
        if not normalized:
            return ""
        lines = normalized.splitlines()[:max_lines]
        compact = "\n".join(lines)
        if len(compact) > max_chars:
            compact = compact[:max_chars]
        return compact

    if rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
    elif human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_required"
        block_reason = "human_review_required"
        next_action = "human_review_required"
    elif normalized_safe_patch_gate_status == "insufficient_truth":
        status = "insufficient_truth"
        source_status = "safe_patch_gate_insufficient_truth"
        block_reason = "insufficient_truth"
        next_action = "insufficient_truth"
    elif normalized_safe_patch_gate_status != "ready_for_dry_run_later":
        status = "blocked_no_ready_gate"
        source_status = "safe_patch_gate_not_ready"
        block_reason = (
            normalized_safe_patch_gate_block_reason
            or "safe_patch_gate_not_ready_for_dry_run"
        )
        next_action = "wait_for_ready_patch_candidate"
    elif not normalized_expected_patch_path:
        status = "blocked_missing_patch_path"
        source_status = "safe_patch_gate_ready"
        block_reason = "missing_expected_patch_path"
        next_action = "manual_fix_patch_candidate"
    elif normalized_worktree_status == "insufficient_truth":
        status = "insufficient_truth"
        source_status = "worktree_truth_unavailable"
        block_reason = "worktree_truth_unavailable"
        next_action = "insufficient_truth"
    elif normalized_worktree_dirty:
        status = "blocked_dirty_worktree"
        source_status = "worktree_dirty"
        block_reason = "dirty_worktree"
        next_action = "manual_fix_patch_candidate"
    elif normalized_forbidden_touched_files:
        status = "blocked_forbidden_files"
        source_status = "forbidden_files_detected"
        block_reason = "forbidden_touched_files"
        next_action = "manual_fix_patch_candidate"
    elif normalized_unsafe_operation_flags:
        status = "blocked_unsafe_operations"
        source_status = "unsafe_operations_detected"
        block_reason = "unsafe_operations_detected"
        next_action = "manual_fix_patch_candidate"
    elif not shutil.which("git"):
        status = "blocked_command_unavailable"
        source_status = "command_unavailable"
        block_reason = "git_unavailable"
        next_action = "manual_fix_patch_candidate"
    elif not execution_repo_path.strip():
        status = "insufficient_truth"
        source_status = "execution_repo_path_missing"
        block_reason = "execution_repo_path_missing"
        next_action = "insufficient_truth"
        missing_inputs = _serialize_required_signals([*missing_inputs, "execution_repo_path"])
    else:
        repo_path = execution_repo_path.strip()
        status = "ready_to_dry_run"
        source_status = "safe_patch_gate_ready"
        block_reason = "none"
        next_action = "run_bounded_dry_run_check"
        dry_run_attempted = True
        try:
            command_result = _run_git(
                repo_path,
                ["apply", "--check", normalized_expected_patch_path],
                timeout_seconds=dry_run_timeout_seconds,
            )
            dry_run_completed = True
            dry_run_exit_code = int(command_result.returncode)
            dry_run_stdout_excerpt = _excerpt(command_result.stdout)
            dry_run_stderr_excerpt = _excerpt(command_result.stderr)
            if dry_run_exit_code == 0:
                status = "dry_run_passed"
                source_status = "dry_run_execution_completed"
                block_reason = "none"
                next_action = "proceed_to_safe_apply_gate_later"
                dry_run_passed = True
                dry_run_failed = False
            else:
                status = "dry_run_failed"
                source_status = "dry_run_execution_completed"
                block_reason = "dry_run_exit_nonzero"
                next_action = "manual_fix_patch_candidate"
                dry_run_passed = False
                dry_run_failed = True
            combined_output_lower = (
                f"{dry_run_stdout_excerpt}\n{dry_run_stderr_excerpt}"
            ).lower()
            if "applied patch" in combined_output_lower or "applying patch" in combined_output_lower:
                status = "blocked_human_review_required"
                source_status = "dry_run_mutation_signal"
                block_reason = "dry_run_mutation_signal_detected"
                next_action = "human_review_required"
                dry_run_passed = False
                dry_run_failed = True
            post_worktree_signature = (
                f"{normalized_worktree_status}:{int(bool(normalized_worktree_dirty))}"
                if normalized_worktree_status in {"clean", "dirty"}
                else ""
            )
            if pre_worktree_signature and post_worktree_signature and (
                pre_worktree_signature != post_worktree_signature
            ):
                status = "blocked_human_review_required"
                source_status = "dry_run_worktree_changed"
                block_reason = "dry_run_worktree_changed"
                next_action = "human_review_required"
                dry_run_passed = False
                dry_run_failed = True
        except subprocess.TimeoutExpired as timeout_error:
            dry_run_completed = True
            dry_run_exit_code = 124
            dry_run_stdout_excerpt = _excerpt(
                timeout_error.stdout
                if isinstance(timeout_error.stdout, str)
                else ""
            )
            dry_run_stderr_excerpt = _excerpt(
                timeout_error.stderr
                if isinstance(timeout_error.stderr, str)
                else ""
            )
            status = "blocked_timeout"
            source_status = "dry_run_execution_timeout"
            block_reason = "dry_run_timeout"
            next_action = "manual_fix_patch_candidate"
            dry_run_passed = False
            dry_run_failed = True
        except OSError as command_error:
            dry_run_completed = False
            dry_run_exit_code = -1
            dry_run_stdout_excerpt = ""
            dry_run_stderr_excerpt = _excerpt(str(command_error))
            status = "blocked_command_unavailable"
            source_status = "dry_run_execution_error"
            block_reason = "git_command_unavailable"
            next_action = "manual_fix_patch_candidate"
            dry_run_passed = False
            dry_run_failed = True

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    def _group(prefix: str) -> dict[str, Any]:
        return {
            f"{prefix}_status": status,
            f"{prefix}_source_status": source_status,
            f"{prefix}_block_reason": block_reason,
            f"{prefix}_expected_patch_path": normalized_expected_patch_path,
            f"{prefix}_patch_candidate_status": normalized_patch_candidate_status,
            f"{prefix}_safe_patch_gate_status": normalized_safe_patch_gate_status,
            f"{prefix}_touched_files": normalized_touched_files,
            f"{prefix}_forbidden_touched_files": normalized_forbidden_touched_files,
            f"{prefix}_worktree_status": normalized_worktree_status,
            f"{prefix}_worktree_dirty": bool(normalized_worktree_dirty),
            f"{prefix}_dry_run_command": dry_run_command,
            f"{prefix}_dry_run_attempted": bool(dry_run_attempted),
            f"{prefix}_dry_run_completed": bool(dry_run_completed),
            f"{prefix}_dry_run_exit_code": int(dry_run_exit_code),
            f"{prefix}_dry_run_stdout_excerpt": dry_run_stdout_excerpt,
            f"{prefix}_dry_run_stderr_excerpt": dry_run_stderr_excerpt,
            f"{prefix}_dry_run_passed": bool(dry_run_passed),
            f"{prefix}_dry_run_failed": bool(dry_run_failed),
            f"{prefix}_next_action": next_action,
            f"{prefix}_runtime_posture": runtime_posture,
            f"{prefix}_missing_inputs": missing_inputs,
        }

    return {
        **_group("project_browser_autonomous_patch_dry_run_check"),
        **_group("project_browser_autonomous_patch_dry_run_execution"),
        **_group("project_browser_autonomous_patch_dry_run_result"),
    }


def _build_project_browser_autonomous_safe_patch_real_apply_state(
    *,
    patch_candidate_status: str,
    safe_patch_gate_status: str,
    expected_patch_path: str,
    dry_run_status: str,
    dry_run_passed: bool,
    dry_run_failed: bool,
    dry_run_completed: bool,
    dry_run_exit_code: int,
    touched_files: list[str] | None,
    forbidden_touched_files: list[str] | None,
    forbidden_files: list[str] | None,
    unsafe_operations: list[str] | None,
    worktree_status_before_hint: str,
    worktree_dirty_before_hint: bool,
    human_review_required: bool,
    rollback_required: bool,
    execution_repo_path: str,
) -> dict[str, Any]:
    allowed_patch_path = "/tmp/codex-local-runner-decision/chatgpt_implementation_patch.diff"
    allowed_statuses = {
        "ready_to_apply",
        "apply_passed",
        "apply_failed",
        "blocked_no_dry_run_pass",
        "blocked_missing_patch_path",
        "blocked_unexpected_patch_path",
        "blocked_patch_path_unavailable",
        "blocked_patch_path_not_file",
        "blocked_patch_path_symlink",
        "blocked_dirty_worktree",
        "blocked_forbidden_files",
        "blocked_unsafe_operations",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_command_unavailable",
        "blocked_timeout",
        "blocked_post_apply_mutation_mismatch",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "wait_for_dry_run_pass",
        "run_bounded_real_apply",
        "proceed_to_post_apply_validation_later",
        "manual_fix_patch_candidate",
        "human_review_required",
        "rollback_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "bounded_safe_real_apply",
        "single_command_max",
        "git_apply_only",
        "argv_list_execution_only",
        "no_shell_true",
        "no_git_apply_index_cached",
        "no_git_am",
        "no_git_add_commit_push",
        "no_git_reset_clean_checkout_restore",
        "no_rollback_execution",
        "no_github_mutation",
        "no_autonomous_loop",
        "post_apply_truth_required",
        "post_apply_dirty_worktree_expected_when_changes_match",
    ]

    normalized_patch_candidate_status = _normalize_text(
        patch_candidate_status,
        default="insufficient_truth",
    )
    normalized_safe_patch_gate_status = _normalize_text(
        safe_patch_gate_status,
        default="insufficient_truth",
    )
    normalized_expected_patch_path = _normalize_text(expected_patch_path, default="")
    normalized_dry_run_status = _normalize_text(dry_run_status, default="insufficient_truth")
    normalized_touched_files = _normalize_string_list(touched_files or [])
    normalized_forbidden_touched_files = _normalize_string_list(
        forbidden_touched_files or []
    )
    normalized_forbidden_files = _normalize_string_list(forbidden_files or [])
    normalized_unsafe_operations = _normalize_string_list(unsafe_operations or [])
    normalized_worktree_status_before_hint = _normalize_text(
        worktree_status_before_hint,
        default="insufficient_truth",
    )
    normalized_worktree_dirty_before_hint = bool(worktree_dirty_before_hint)

    required_inputs = [
        "patch_candidate_status",
        "safe_patch_gate_status",
        "dry_run_status",
        "expected_patch_path",
        "touched_files",
    ]
    available_inputs: list[str] = []
    if normalized_patch_candidate_status:
        available_inputs.append("patch_candidate_status")
    if normalized_safe_patch_gate_status:
        available_inputs.append("safe_patch_gate_status")
    if normalized_dry_run_status:
        available_inputs.append("dry_run_status")
    if normalized_expected_patch_path:
        available_inputs.append("expected_patch_path")
    if normalized_touched_files:
        available_inputs.append("touched_files")
    missing_inputs = _serialize_required_signals(
        [
            input_name
            for input_name in required_inputs
            if input_name not in set(available_inputs)
        ]
    )

    def _normalize_repo_path(path_text: str) -> str:
        value = _normalize_text(path_text, default="")
        if not value:
            return ""
        value = value.replace("\\", "/")
        if value.startswith("a/") or value.startswith("b/"):
            value = value[2:]
        value = value.strip().strip("`").strip("\"")
        if value == "/dev/null":
            return ""
        return value

    def _path_matches_scope(candidate: str, scope_items: list[str]) -> bool:
        normalized_candidate = _normalize_repo_path(candidate)
        if not normalized_candidate:
            return False
        for scope_item in scope_items:
            normalized_scope = _normalize_repo_path(scope_item)
            if not normalized_scope:
                continue
            if normalized_candidate == normalized_scope:
                return True
            if normalized_candidate.startswith(normalized_scope.rstrip("/") + "/"):
                return True
        return False

    def _excerpt(text: str, *, max_chars: int = 600, max_lines: int = 12) -> str:
        normalized = _normalize_text(text, default="")
        if not normalized:
            return ""
        lines = normalized.splitlines()[:max_lines]
        compact = "\n".join(lines)
        if len(compact) > max_chars:
            compact = compact[:max_chars]
        return compact

    expected_patch_path_is_exact = normalized_expected_patch_path == allowed_patch_path
    expected_patch_path_exists = False
    expected_patch_path_is_file = False
    expected_patch_path_is_symlink = False
    expected_patch_path_resolved = ""
    expected_patch_path_resolve_matches = False
    allowed_patch_path_resolved = ""
    try:
        allowed_patch_path_resolved = str(Path(allowed_patch_path).resolve())
    except OSError:
        allowed_patch_path_resolved = allowed_patch_path

    if normalized_expected_patch_path:
        candidate_path = Path(normalized_expected_patch_path)
        expected_patch_path_exists = bool(candidate_path.exists())
        expected_patch_path_is_file = bool(candidate_path.is_file())
        expected_patch_path_is_symlink = bool(candidate_path.is_symlink())
        try:
            expected_patch_path_resolved = str(candidate_path.resolve())
        except OSError:
            expected_patch_path_resolved = ""
        expected_patch_path_resolve_matches = bool(
            expected_patch_path_resolved
            and allowed_patch_path_resolved
            and expected_patch_path_resolved == allowed_patch_path_resolved
        )

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    next_action = "insufficient_truth"
    apply_command = (
        f"git apply {normalized_expected_patch_path}"
        if normalized_expected_patch_path
        else "git apply <missing_patch_path>"
    )
    apply_attempted = False
    apply_completed = False
    apply_exit_code = -1
    apply_stdout_excerpt = ""
    apply_stderr_excerpt = ""
    apply_performed = False
    apply_passed = False
    apply_failed = False
    effective_human_review_required = bool(human_review_required)
    effective_rollback_required = bool(rollback_required)
    worktree_status_before_apply = normalized_worktree_status_before_hint
    worktree_dirty_before_apply = bool(normalized_worktree_dirty_before_hint)
    worktree_status_after_apply = "insufficient_truth"
    worktree_dirty_after_apply = False
    worktree_changed_by_apply = False
    changed_files_before_apply: list[str] = []
    changed_files_after_apply: list[str] = []
    unexpected_changed_files_after_apply: list[str] = []
    forbidden_changed_files_after_apply: list[str] = []

    def _collect_worktree_truth(
        repo_path: str,
    ) -> tuple[str, bool, list[str], bool, str]:
        if not repo_path.strip():
            return ("insufficient_truth", False, [], False, "execution_repo_path_missing")
        try:
            rev_parse = _run_git(
                repo_path,
                ["rev-parse", "--is-inside-work-tree"],
                timeout_seconds=5.0,
            )
        except (subprocess.TimeoutExpired, OSError):
            return ("insufficient_truth", False, [], False, "worktree_probe_failed")
        if rev_parse.returncode != 0:
            return ("insufficient_truth", False, [], False, "not_git_worktree")
        try:
            status_result = _run_git(
                repo_path,
                ["status", "--porcelain"],
                timeout_seconds=5.0,
            )
        except (subprocess.TimeoutExpired, OSError):
            return ("insufficient_truth", False, [], False, "git_status_failed")
        if status_result.returncode != 0:
            return ("insufficient_truth", False, [], False, "git_status_failed")
        status_lines = [
            line for line in status_result.stdout.splitlines() if _normalize_text(line, default="")
        ]
        status_paths = _serialize_required_signals(
            [_parse_git_status_path(line) for line in status_lines]
        )
        dirty = bool(status_paths)
        return (
            "dirty" if dirty else "clean",
            dirty,
            status_paths,
            True,
            "none",
        )

    dry_run_pass_gate = bool(
        normalized_dry_run_status in {"dry_run_passed", "apply_passed"}
        and bool(dry_run_completed)
        and bool(dry_run_passed)
        and not bool(dry_run_failed)
        and int(_as_int(dry_run_exit_code, default=-1)) == 0
    )

    if effective_rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
    elif effective_human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_required"
        block_reason = "human_review_required"
        next_action = "human_review_required"
    elif not dry_run_pass_gate:
        if normalized_dry_run_status == "insufficient_truth":
            status = "insufficient_truth"
            source_status = "dry_run_insufficient_truth"
            block_reason = "insufficient_truth"
            next_action = "insufficient_truth"
        else:
            status = "blocked_no_dry_run_pass"
            source_status = "dry_run_not_passed"
            block_reason = "dry_run_not_passed"
            next_action = "wait_for_dry_run_pass"
    elif normalized_safe_patch_gate_status not in {
        "ready_for_dry_run_later",
        "ready_to_apply",
    }:
        status = "blocked_no_dry_run_pass"
        source_status = "safe_patch_gate_not_ready"
        block_reason = "safe_patch_gate_not_ready"
        next_action = "wait_for_dry_run_pass"
    elif not normalized_expected_patch_path:
        status = "blocked_missing_patch_path"
        source_status = "patch_path_missing"
        block_reason = "missing_expected_patch_path"
        next_action = "manual_fix_patch_candidate"
    elif not expected_patch_path_is_exact:
        status = "blocked_unexpected_patch_path"
        source_status = "patch_path_not_exact"
        block_reason = "unexpected_patch_path"
        next_action = "manual_fix_patch_candidate"
    elif not expected_patch_path_exists:
        status = "blocked_patch_path_unavailable"
        source_status = "patch_path_unavailable"
        block_reason = "patch_path_unavailable"
        next_action = "manual_fix_patch_candidate"
    elif expected_patch_path_is_symlink:
        status = "blocked_patch_path_symlink"
        source_status = "patch_path_symlink"
        block_reason = "patch_path_symlink"
        next_action = "manual_fix_patch_candidate"
    elif not expected_patch_path_is_file:
        status = "blocked_patch_path_not_file"
        source_status = "patch_path_not_file"
        block_reason = "patch_path_not_file"
        next_action = "manual_fix_patch_candidate"
    elif not expected_patch_path_resolve_matches:
        status = "blocked_unexpected_patch_path"
        source_status = "patch_path_resolve_mismatch"
        block_reason = "patch_path_resolve_mismatch"
        next_action = "manual_fix_patch_candidate"
    elif normalized_forbidden_touched_files:
        status = "blocked_forbidden_files"
        source_status = "forbidden_touched_files_present"
        block_reason = "forbidden_touched_files"
        next_action = "manual_fix_patch_candidate"
    elif normalized_unsafe_operations:
        status = "blocked_unsafe_operations"
        source_status = "unsafe_operations_present"
        block_reason = "unsafe_operations_present"
        next_action = "manual_fix_patch_candidate"
    elif not normalized_touched_files:
        status = "insufficient_truth"
        source_status = "missing_touched_files"
        block_reason = "missing_touched_files"
        next_action = "insufficient_truth"
        missing_inputs = _serialize_required_signals([*missing_inputs, "touched_files"])
    elif not shutil.which("git"):
        status = "blocked_command_unavailable"
        source_status = "git_unavailable"
        block_reason = "git_unavailable"
        next_action = "manual_fix_patch_candidate"
    elif not execution_repo_path.strip():
        status = "insufficient_truth"
        source_status = "execution_repo_path_missing"
        block_reason = "execution_repo_path_missing"
        next_action = "insufficient_truth"
        missing_inputs = _serialize_required_signals([*missing_inputs, "execution_repo_path"])
    else:
        repo_path = execution_repo_path.strip()
        (
            worktree_status_before_apply,
            worktree_dirty_before_apply,
            changed_files_before_apply,
            pre_truth_available,
            pre_truth_reason,
        ) = _collect_worktree_truth(repo_path)
        if not pre_truth_available:
            status = "insufficient_truth"
            source_status = "pre_apply_worktree_truth_unavailable"
            block_reason = pre_truth_reason or "pre_apply_worktree_truth_unavailable"
            next_action = "insufficient_truth"
        elif worktree_dirty_before_apply:
            status = "blocked_dirty_worktree"
            source_status = "pre_apply_worktree_dirty"
            block_reason = "dirty_worktree_before_apply"
            next_action = "manual_fix_patch_candidate"
        else:
            status = "ready_to_apply"
            source_status = "all_gates_passed"
            block_reason = "none"
            next_action = "run_bounded_real_apply"
            apply_attempted = True
            try:
                apply_result = _run_git(
                    repo_path,
                    ["apply", normalized_expected_patch_path],
                    timeout_seconds=5.0,
                )
                apply_completed = True
                apply_exit_code = int(apply_result.returncode)
                apply_stdout_excerpt = _excerpt(apply_result.stdout)
                apply_stderr_excerpt = _excerpt(apply_result.stderr)
                (
                    worktree_status_after_apply,
                    worktree_dirty_after_apply,
                    changed_files_after_apply,
                    post_truth_available,
                    post_truth_reason,
                ) = _collect_worktree_truth(repo_path)
                worktree_changed_by_apply = bool(
                    worktree_status_before_apply != worktree_status_after_apply
                    or changed_files_before_apply != changed_files_after_apply
                )
                unexpected_changed_files_after_apply = _serialize_required_signals(
                    [
                        path
                        for path in changed_files_after_apply
                        if path not in set(normalized_touched_files)
                    ]
                )
                forbidden_changed_files_after_apply = _serialize_required_signals(
                    [
                        path
                        for path in changed_files_after_apply
                        if (
                            path in set(normalized_forbidden_touched_files)
                            or _path_matches_scope(path, normalized_forbidden_files)
                        )
                    ]
                )
                post_truth_mismatch = bool(
                    not post_truth_available
                    or not changed_files_after_apply
                    or bool(unexpected_changed_files_after_apply)
                    or bool(forbidden_changed_files_after_apply)
                )
                if apply_exit_code == 0 and not post_truth_mismatch:
                    apply_performed = True
                    apply_passed = True
                    apply_failed = False
                    status = "apply_passed"
                    source_status = "real_apply_completed"
                    block_reason = "none"
                    next_action = "proceed_to_post_apply_validation_later"
                elif apply_exit_code == 0:
                    apply_performed = False
                    apply_passed = False
                    apply_failed = True
                    status = "blocked_post_apply_mutation_mismatch"
                    source_status = "post_apply_truth_mismatch"
                    block_reason = (
                        post_truth_reason if not post_truth_available else "post_apply_mutation_mismatch"
                    )
                    effective_human_review_required = True
                    effective_rollback_required = True
                    next_action = "human_review_required"
                else:
                    apply_performed = False
                    apply_passed = False
                    apply_failed = True
                    status = "apply_failed"
                    source_status = "real_apply_completed"
                    block_reason = "real_apply_exit_nonzero"
                    next_action = "manual_fix_patch_candidate"
            except subprocess.TimeoutExpired as timeout_error:
                apply_completed = True
                apply_exit_code = 124
                apply_stdout_excerpt = _excerpt(
                    timeout_error.stdout if isinstance(timeout_error.stdout, str) else ""
                )
                apply_stderr_excerpt = _excerpt(
                    timeout_error.stderr if isinstance(timeout_error.stderr, str) else ""
                )
                status = "blocked_timeout"
                source_status = "real_apply_timeout"
                block_reason = "real_apply_timeout"
                next_action = "manual_fix_patch_candidate"
                apply_failed = True
            except OSError as command_error:
                apply_completed = False
                apply_exit_code = -1
                apply_stdout_excerpt = ""
                apply_stderr_excerpt = _excerpt(str(command_error))
                status = "blocked_command_unavailable"
                source_status = "real_apply_command_unavailable"
                block_reason = "real_apply_command_unavailable"
                next_action = "manual_fix_patch_candidate"
                apply_failed = True

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if status.startswith("blocked_") and not apply_failed:
        apply_failed = True
    if status == "insufficient_truth" and apply_attempted:
        apply_failed = True

    def _group(prefix: str) -> dict[str, Any]:
        return {
            f"{prefix}_status": status,
            f"{prefix}_source_status": source_status,
            f"{prefix}_block_reason": block_reason,
            f"{prefix}_expected_patch_path": normalized_expected_patch_path,
            f"{prefix}_expected_patch_path_is_exact": bool(expected_patch_path_is_exact),
            f"{prefix}_expected_patch_path_exists": bool(expected_patch_path_exists),
            f"{prefix}_expected_patch_path_is_file": bool(expected_patch_path_is_file),
            f"{prefix}_expected_patch_path_is_symlink": bool(expected_patch_path_is_symlink),
            f"{prefix}_expected_patch_path_resolved": expected_patch_path_resolved,
            f"{prefix}_patch_candidate_status": normalized_patch_candidate_status,
            f"{prefix}_safe_patch_gate_status": normalized_safe_patch_gate_status,
            f"{prefix}_dry_run_status": normalized_dry_run_status,
            f"{prefix}_dry_run_passed": bool(dry_run_passed),
            f"{prefix}_dry_run_failed": bool(dry_run_failed),
            f"{prefix}_dry_run_completed": bool(dry_run_completed),
            f"{prefix}_dry_run_exit_code": int(_as_int(dry_run_exit_code, default=-1)),
            f"{prefix}_touched_files": normalized_touched_files,
            f"{prefix}_forbidden_touched_files": normalized_forbidden_touched_files,
            f"{prefix}_unsafe_operations": normalized_unsafe_operations,
            f"{prefix}_worktree_status_before_apply": worktree_status_before_apply,
            f"{prefix}_worktree_dirty_before_apply": bool(worktree_dirty_before_apply),
            f"{prefix}_worktree_status_after_apply": worktree_status_after_apply,
            f"{prefix}_worktree_dirty_after_apply": bool(worktree_dirty_after_apply),
            f"{prefix}_worktree_changed_by_apply": bool(worktree_changed_by_apply),
            f"{prefix}_changed_files_after_apply": changed_files_after_apply,
            f"{prefix}_unexpected_changed_files_after_apply": (
                unexpected_changed_files_after_apply
            ),
            f"{prefix}_forbidden_changed_files_after_apply": (
                forbidden_changed_files_after_apply
            ),
            f"{prefix}_apply_command": apply_command,
            f"{prefix}_apply_attempted": bool(apply_attempted),
            f"{prefix}_apply_completed": bool(apply_completed),
            f"{prefix}_apply_exit_code": int(apply_exit_code),
            f"{prefix}_apply_stdout_excerpt": apply_stdout_excerpt,
            f"{prefix}_apply_stderr_excerpt": apply_stderr_excerpt,
            f"{prefix}_apply_performed": bool(apply_performed),
            f"{prefix}_apply_passed": bool(apply_passed),
            f"{prefix}_apply_failed": bool(apply_failed),
            f"{prefix}_human_review_required": bool(effective_human_review_required),
            f"{prefix}_rollback_required": bool(effective_rollback_required),
            f"{prefix}_next_action": next_action,
            f"{prefix}_runtime_posture": runtime_posture,
            f"{prefix}_missing_inputs": missing_inputs,
        }

    return {
        **_group("project_browser_autonomous_safe_patch_real_apply_gate"),
        **_group("project_browser_autonomous_safe_patch_real_apply_execution"),
        **_group("project_browser_autonomous_safe_patch_real_apply_result"),
    }


def _build_project_browser_autonomous_post_apply_validation_state(
    *,
    expected_patch_path: str,
    safe_patch_gate_status: str,
    dry_run_status: str,
    dry_run_completed: bool,
    dry_run_passed: bool,
    dry_run_failed: bool,
    dry_run_exit_code: int,
    apply_status: str,
    apply_attempted: bool,
    apply_completed: bool,
    apply_performed: bool,
    apply_passed: bool,
    apply_failed: bool,
    apply_exit_code: int,
    touched_files: list[str] | None,
    changed_files_after_apply: list[str] | None,
    unexpected_changed_files_after_apply: list[str] | None,
    forbidden_changed_files_after_apply: list[str] | None,
    worktree_status_after_apply: str,
    worktree_dirty_after_apply: bool,
    human_review_required: bool,
    rollback_required: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "ready_to_validate",
        "validation_passed",
        "validation_failed",
        "blocked_no_apply_performed",
        "blocked_apply_failed",
        "blocked_missing_post_apply_truth",
        "blocked_forbidden_changes",
        "blocked_unexpected_changes",
        "blocked_changed_file_mismatch",
        "blocked_metadata_inconsistency",
        "blocked_command_unavailable",
        "blocked_timeout",
        "human_review_required",
        "rollback_required",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "wait_for_apply_success",
        "run_post_apply_validation",
        "proceed_after_validation",
        "manual_fix_patch_candidate",
        "human_review_required",
        "rollback_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "bounded_post_apply_validation",
        "single_pass_validation",
        "argv_list_execution_only",
        "no_shell_true",
        "py_compile_only_required",
        "no_broad_tests_default",
        "no_git_mutation",
        "no_rollback_execution",
        "metadata_only_rollback_posture",
    ]

    normalized_expected_patch_path = _normalize_text(expected_patch_path, default="")
    normalized_safe_patch_gate_status = _normalize_text(
        safe_patch_gate_status,
        default="insufficient_truth",
    )
    normalized_dry_run_status = _normalize_text(dry_run_status, default="insufficient_truth")
    normalized_apply_status = _normalize_text(apply_status, default="insufficient_truth")
    normalized_touched_files = _normalize_string_list(touched_files or [])
    normalized_changed_files = _normalize_string_list(changed_files_after_apply or [])
    normalized_unexpected_changed_files = _normalize_string_list(
        unexpected_changed_files_after_apply or []
    )
    normalized_forbidden_changed_files = _normalize_string_list(
        forbidden_changed_files_after_apply or []
    )
    normalized_worktree_status_after_apply = _normalize_text(
        worktree_status_after_apply,
        default="insufficient_truth",
    )
    normalized_worktree_dirty_after_apply = bool(worktree_dirty_after_apply)
    if normalized_worktree_status_after_apply in {"clean", "dirty"}:
        normalized_worktree_dirty_after_apply = (
            normalized_worktree_status_after_apply == "dirty"
        )

    validation_commands = [
        "python -m py_compile automation/orchestration/planned_execution_runner.py",
        "python -m py_compile scripts/run_planned_execution.py",
    ]
    command_args = [
        ["-m", "py_compile", "automation/orchestration/planned_execution_runner.py"],
        ["-m", "py_compile", "scripts/run_planned_execution.py"],
    ]

    required_inputs = [
        "expected_patch_path",
        "safe_patch_gate_status",
        "dry_run_status",
        "apply_status",
        "touched_files",
        "changed_files_after_apply",
        "worktree_status_after_apply",
    ]
    available_inputs: list[str] = []
    if normalized_expected_patch_path:
        available_inputs.append("expected_patch_path")
    if normalized_safe_patch_gate_status:
        available_inputs.append("safe_patch_gate_status")
    if normalized_dry_run_status:
        available_inputs.append("dry_run_status")
    if normalized_apply_status:
        available_inputs.append("apply_status")
    if normalized_touched_files:
        available_inputs.append("touched_files")
    if normalized_changed_files:
        available_inputs.append("changed_files_after_apply")
    if normalized_worktree_status_after_apply in {"clean", "dirty"}:
        available_inputs.append("worktree_status_after_apply")
    missing_inputs = _serialize_required_signals(
        [name for name in required_inputs if name not in set(available_inputs)]
    )

    changed_file_consistency_passed = bool(
        normalized_changed_files
        and set(normalized_changed_files).issubset(set(normalized_touched_files))
        and not normalized_unexpected_changed_files
        and not normalized_forbidden_changed_files
    )
    changed_file_consistency_failed = bool(
        not changed_file_consistency_passed
        and (
            normalized_forbidden_changed_files
            or normalized_unexpected_changed_files
            or not normalized_changed_files
            or (
                normalized_changed_files
                and normalized_touched_files
                and not set(normalized_changed_files).issubset(set(normalized_touched_files))
            )
        )
    )
    metadata_consistency_passed = bool(
        bool(apply_attempted)
        and bool(apply_completed)
        and bool(apply_performed)
        and bool(apply_passed)
        and not bool(apply_failed)
        and bool(dry_run_completed)
        and bool(dry_run_passed)
        and not bool(dry_run_failed)
        and int(_as_int(dry_run_exit_code, default=-1)) == 0
        and normalized_safe_patch_gate_status not in {"", "insufficient_truth"}
    )
    metadata_consistency_failed = not metadata_consistency_passed

    post_apply_truth_missing = bool(
        normalized_worktree_status_after_apply == "insufficient_truth"
    )
    diff_stat_available = bool(normalized_changed_files)
    diff_stat_excerpt = (
        ", ".join(normalized_changed_files[:8]) if normalized_changed_files else ""
    )

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    next_action = "insufficient_truth"

    validation_attempted = False
    validation_completed = False
    validation_passed = False
    validation_failed = False
    py_compile_attempted = False
    py_compile_completed = False
    py_compile_exit_code = -1
    py_compile_stdout_excerpt = ""
    py_compile_stderr_excerpt = ""
    targeted_tests_attempted = False
    targeted_tests_completed = False
    targeted_tests_exit_code = -1
    targeted_tests_stdout_excerpt = ""
    targeted_tests_stderr_excerpt = ""

    effective_human_review_required = bool(human_review_required)
    effective_rollback_required = bool(rollback_required)

    def _excerpt(text: str, *, max_chars: int = 600, max_lines: int = 12) -> str:
        normalized = _normalize_text(text, default="")
        if not normalized:
            return ""
        lines = normalized.splitlines()[:max_lines]
        compact = "\n".join(lines)
        if len(compact) > max_chars:
            compact = compact[:max_chars]
        return compact

    if rollback_required:
        status = "rollback_required"
        source_status = "preexisting_rollback_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
        validation_failed = True
    elif human_review_required:
        status = "human_review_required"
        source_status = "preexisting_human_review_required"
        block_reason = "human_review_required"
        next_action = "human_review_required"
        validation_failed = True
    elif not apply_attempted or not apply_completed or not apply_performed:
        status = "blocked_no_apply_performed"
        source_status = "apply_not_performed"
        block_reason = "apply_not_performed"
        next_action = "wait_for_apply_success"
        validation_failed = True
    elif apply_failed:
        status = "blocked_apply_failed"
        source_status = "apply_failed"
        block_reason = "apply_failed"
        next_action = "manual_fix_patch_candidate"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    elif not apply_passed:
        if normalized_apply_status == "insufficient_truth":
            status = "insufficient_truth"
            source_status = "apply_truth_unavailable"
            block_reason = "insufficient_truth"
            next_action = "insufficient_truth"
            validation_failed = False
        else:
            status = "blocked_apply_failed"
            source_status = "apply_not_passed"
            block_reason = "apply_not_passed"
            next_action = "manual_fix_patch_candidate"
            validation_failed = True
            effective_human_review_required = True
            effective_rollback_required = True
    elif post_apply_truth_missing:
        status = "blocked_missing_post_apply_truth"
        source_status = "post_apply_truth_unavailable"
        block_reason = "post_apply_truth_unavailable"
        next_action = "human_review_required"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    elif normalized_forbidden_changed_files:
        status = "blocked_forbidden_changes"
        source_status = "forbidden_changes_detected"
        block_reason = "forbidden_changes_detected"
        next_action = "human_review_required"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    elif normalized_unexpected_changed_files:
        status = "blocked_unexpected_changes"
        source_status = "unexpected_changes_detected"
        block_reason = "unexpected_changes_detected"
        next_action = "human_review_required"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    elif changed_file_consistency_failed:
        status = "blocked_changed_file_mismatch"
        source_status = "changed_file_consistency_failed"
        block_reason = "changed_file_consistency_failed"
        next_action = "human_review_required"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    elif metadata_consistency_failed:
        status = "blocked_metadata_inconsistency"
        source_status = "metadata_consistency_failed"
        block_reason = "metadata_consistency_failed"
        next_action = "human_review_required"
        validation_failed = True
        effective_human_review_required = True
        effective_rollback_required = True
    else:
        status = "ready_to_validate"
        source_status = "post_apply_validation_ready"
        block_reason = "none"
        next_action = "run_post_apply_validation"

        python_exec = _normalize_text(sys.executable, default="")
        if not python_exec:
            python_exec = _normalize_text(shutil.which("python"), default="")
        if not python_exec:
            python_exec = _normalize_text(shutil.which("python3"), default="")

        if not python_exec:
            status = "blocked_command_unavailable"
            source_status = "python_command_unavailable"
            block_reason = "python_command_unavailable"
            next_action = "manual_fix_patch_candidate"
            validation_failed = True
            effective_human_review_required = True
            effective_rollback_required = True
        else:
            validation_attempted = True
            py_compile_attempted = True
            py_stdout_parts: list[str] = []
            py_stderr_parts: list[str] = []
            for command_text, command_args_item in zip(validation_commands, command_args):
                try:
                    command_result = subprocess.run(
                        [python_exec, *command_args_item],
                        capture_output=True,
                        text=True,
                        timeout=5.0,
                        cwd=str(Path(__file__).resolve().parents[2]),
                    )
                except subprocess.TimeoutExpired as timeout_error:
                    py_compile_completed = True
                    validation_completed = True
                    py_compile_exit_code = 124
                    py_stdout_parts.append(
                        _excerpt(
                            timeout_error.stdout
                            if isinstance(timeout_error.stdout, str)
                            else ""
                        )
                    )
                    py_stderr_parts.append(
                        _excerpt(
                            timeout_error.stderr
                            if isinstance(timeout_error.stderr, str)
                            else ""
                        )
                    )
                    status = "blocked_timeout"
                    source_status = "post_apply_validation_timeout"
                    block_reason = f"timeout:{command_text}"
                    next_action = "human_review_required"
                    validation_passed = False
                    validation_failed = True
                    effective_human_review_required = True
                    effective_rollback_required = True
                    break
                except OSError as command_error:
                    py_compile_completed = False
                    validation_completed = False
                    py_compile_exit_code = -1
                    py_stdout_parts.append("")
                    py_stderr_parts.append(_excerpt(str(command_error)))
                    status = "blocked_command_unavailable"
                    source_status = "post_apply_validation_command_unavailable"
                    block_reason = f"command_unavailable:{command_text}"
                    next_action = "manual_fix_patch_candidate"
                    validation_passed = False
                    validation_failed = True
                    effective_human_review_required = True
                    effective_rollback_required = True
                    break

                py_compile_exit_code = int(command_result.returncode)
                py_stdout_parts.append(_excerpt(command_result.stdout))
                py_stderr_parts.append(_excerpt(command_result.stderr))
                if command_result.returncode != 0:
                    py_compile_completed = True
                    validation_completed = True
                    status = "validation_failed"
                    source_status = "required_py_compile_failed"
                    block_reason = f"py_compile_failed:{command_text}"
                    next_action = "human_review_required"
                    validation_passed = False
                    validation_failed = True
                    effective_human_review_required = True
                    effective_rollback_required = True
                    break
            else:
                py_compile_completed = True
                validation_completed = True
                validation_passed = True
                validation_failed = False
                status = "validation_passed"
                source_status = "required_py_compile_passed"
                block_reason = "none"
                next_action = "proceed_after_validation"

            py_compile_stdout_excerpt = _excerpt("\n".join(py_stdout_parts))
            py_compile_stderr_excerpt = _excerpt("\n".join(py_stderr_parts))

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    if (
        status.startswith("blocked_")
        or status in {"validation_failed", "human_review_required", "rollback_required"}
    ):
        validation_passed = False
        validation_failed = True
    elif status == "insufficient_truth":
        validation_passed = False
        validation_failed = False

    rollback_status = "insufficient_truth"
    rollback_source_status = source_status
    rollback_block_reason = block_reason
    rollback_reason = ""
    rollback_next_action = "insufficient_truth"
    if effective_rollback_required:
        rollback_status = "rollback_required"
        rollback_reason = block_reason or "rollback_required"
        rollback_next_action = "rollback_required"
    elif effective_human_review_required:
        rollback_status = "human_review_required"
        rollback_reason = block_reason or "human_review_required"
        rollback_next_action = "human_review_required"
    elif status == "validation_passed":
        rollback_status = "rollback_not_required"
        rollback_reason = "none"
        rollback_next_action = "proceed_after_validation"
    elif status == "insufficient_truth":
        rollback_status = "insufficient_truth"
        rollback_reason = "insufficient_truth"
        rollback_next_action = "insufficient_truth"
    else:
        rollback_status = "human_review_required"
        rollback_reason = block_reason or "human_review_required"
        rollback_next_action = "human_review_required"
        effective_human_review_required = True

    def _validation_group(prefix: str) -> dict[str, Any]:
        return {
            f"{prefix}_status": status,
            f"{prefix}_source_status": source_status,
            f"{prefix}_block_reason": block_reason,
            f"{prefix}_expected_patch_path": normalized_expected_patch_path,
            f"{prefix}_apply_status": normalized_apply_status,
            f"{prefix}_apply_attempted": bool(apply_attempted),
            f"{prefix}_apply_completed": bool(apply_completed),
            f"{prefix}_apply_performed": bool(apply_performed),
            f"{prefix}_apply_passed": bool(apply_passed),
            f"{prefix}_apply_failed": bool(apply_failed),
            f"{prefix}_apply_exit_code": int(_as_int(apply_exit_code, default=-1)),
            f"{prefix}_touched_files": normalized_touched_files,
            f"{prefix}_changed_files_after_apply": normalized_changed_files,
            f"{prefix}_unexpected_changed_files_after_apply": normalized_unexpected_changed_files,
            f"{prefix}_forbidden_changed_files_after_apply": normalized_forbidden_changed_files,
            f"{prefix}_worktree_status_after_apply": normalized_worktree_status_after_apply,
            f"{prefix}_worktree_dirty_after_apply": bool(normalized_worktree_dirty_after_apply),
            f"{prefix}_validation_commands": _normalize_string_list(validation_commands),
            f"{prefix}_validation_attempted": bool(validation_attempted),
            f"{prefix}_validation_completed": bool(validation_completed),
            f"{prefix}_validation_passed": bool(validation_passed),
            f"{prefix}_validation_failed": bool(validation_failed),
            f"{prefix}_py_compile_attempted": bool(py_compile_attempted),
            f"{prefix}_py_compile_completed": bool(py_compile_completed),
            f"{prefix}_py_compile_exit_code": int(py_compile_exit_code),
            f"{prefix}_py_compile_stdout_excerpt": py_compile_stdout_excerpt,
            f"{prefix}_py_compile_stderr_excerpt": py_compile_stderr_excerpt,
            f"{prefix}_targeted_tests_attempted": bool(targeted_tests_attempted),
            f"{prefix}_targeted_tests_completed": bool(targeted_tests_completed),
            f"{prefix}_targeted_tests_exit_code": int(targeted_tests_exit_code),
            f"{prefix}_targeted_tests_stdout_excerpt": targeted_tests_stdout_excerpt,
            f"{prefix}_targeted_tests_stderr_excerpt": targeted_tests_stderr_excerpt,
            f"{prefix}_diff_stat_available": bool(diff_stat_available),
            f"{prefix}_diff_stat_excerpt": diff_stat_excerpt,
            f"{prefix}_changed_file_consistency_passed": bool(changed_file_consistency_passed),
            f"{prefix}_changed_file_consistency_failed": bool(changed_file_consistency_failed),
            f"{prefix}_metadata_consistency_passed": bool(metadata_consistency_passed),
            f"{prefix}_metadata_consistency_failed": bool(metadata_consistency_failed),
            f"{prefix}_human_review_required": bool(effective_human_review_required),
            f"{prefix}_rollback_required": bool(effective_rollback_required),
            f"{prefix}_next_action": next_action,
            f"{prefix}_runtime_posture": runtime_posture,
            f"{prefix}_missing_inputs": missing_inputs,
        }

    return {
        **_validation_group("project_browser_autonomous_post_apply_validation_check"),
        **_validation_group("project_browser_autonomous_post_apply_validation_execution"),
        **_validation_group("project_browser_autonomous_post_apply_validation_result"),
        "project_browser_autonomous_post_apply_validation_status": status,
        "project_browser_autonomous_post_apply_validation_next_action": next_action,
        "project_browser_autonomous_rollback_posture_status": rollback_status,
        "project_browser_autonomous_rollback_posture_source_status": (
            rollback_source_status
        ),
        "project_browser_autonomous_rollback_posture_block_reason": (
            rollback_block_reason
        ),
        "project_browser_autonomous_rollback_posture_rollback_required": (
            bool(effective_rollback_required)
        ),
        "project_browser_autonomous_rollback_posture_rollback_reason": rollback_reason,
        "project_browser_autonomous_rollback_posture_rollback_execution_allowed": False,
        "project_browser_autonomous_rollback_posture_rollback_executed": False,
        "project_browser_autonomous_rollback_posture_rollback_command": "",
        "project_browser_autonomous_rollback_posture_rollback_attempted": False,
        "project_browser_autonomous_rollback_posture_rollback_completed": False,
        "project_browser_autonomous_rollback_posture_rollback_exit_code": -1,
        "project_browser_autonomous_rollback_posture_human_review_required": (
            bool(effective_human_review_required)
        ),
        "project_browser_autonomous_rollback_posture_next_action": rollback_next_action,
        "project_browser_autonomous_rollback_posture_runtime_posture": [
            "rollback_posture_metadata_only",
            "rollback_execution_disallowed",
            "no_git_reset_clean_checkout_restore",
            "human_review_gate_before_rollback",
        ],
        "project_browser_autonomous_rollback_posture_missing_inputs": missing_inputs,
    }


def _build_project_browser_autonomous_fix_prompt_readiness_state(
    *,
    expected_patch_path: str,
    dry_run_status: str,
    dry_run_passed: bool,
    dry_run_failed: bool,
    dry_run_stderr_excerpt: str,
    apply_status: str,
    apply_passed: bool,
    apply_failed: bool,
    apply_stderr_excerpt: str,
    validation_status: str,
    validation_passed: bool,
    validation_failed: bool,
    validation_missing_inputs: list[str] | None,
    py_compile_exit_code: int,
    py_compile_stderr_excerpt: str,
    touched_files: list[str] | None,
    changed_files_after_apply: list[str] | None,
    unexpected_changed_files_after_apply: list[str] | None,
    forbidden_changed_files_after_apply: list[str] | None,
    metadata_consistency_passed: bool,
    metadata_consistency_failed: bool,
    human_review_required: bool,
    rollback_required: bool,
    cycle_handoff_available: bool = False,
    cycle_handoff_prompt_kind: str = "none",
    cycle_handoff_reason: str = "",
) -> dict[str, Any]:
    allowed_statuses = {
        "ready_to_generate_fix_prompt",
        "cycle_handoff_fix_ready",
        "blocked_validation_passed",
        "blocked_insufficient_truth",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_missing_failure_truth",
        "blocked_no_actionable_failure",
        "blocked_forbidden_changes",
        "blocked_unexpected_changes",
        "blocked_metadata_inconsistency",
        "ready_for_manual_fix",
        "insufficient_truth",
    }
    allowed_failure_kinds = {
        "validation_failed",
        "py_compile_failed",
        "dry_run_failed",
        "apply_failed",
        "changed_file_mismatch",
        "forbidden_changes",
        "unexpected_changes",
        "metadata_inconsistency",
        "missing_truth",
        "human_review_required",
        "rollback_required",
        "no_actionable_failure",
        "none",
    }
    allowed_next_actions = {
        "generate_fix_prompt_later",
        "generate_fix_prompt",
        "wait_for_validation_failure",
        "wait_for_more_truth",
        "manual_review_required",
        "rollback_required",
        "manual_fix_required",
        "no_fix_needed",
        "insufficient_truth",
    }
    runtime_posture = [
        "metadata_only_fix_prompt_readiness",
        "no_fix_prompt_generation",
        "no_prompt_file_write",
        "no_model_invocation",
        "no_browser_automation",
        "no_rollback_execution",
        "no_git_mutation",
    ]

    normalized_expected_patch_path = _normalize_text(expected_patch_path, default="")
    normalized_dry_run_status = _normalize_text(dry_run_status, default="insufficient_truth")
    normalized_apply_status = _normalize_text(apply_status, default="insufficient_truth")
    normalized_validation_status = _normalize_text(
        validation_status,
        default="insufficient_truth",
    )
    normalized_validation_missing_inputs = _normalize_string_list(validation_missing_inputs or [])
    normalized_py_compile_stderr = _normalize_text(py_compile_stderr_excerpt, default="")
    normalized_dry_run_stderr = _normalize_text(dry_run_stderr_excerpt, default="")
    normalized_apply_stderr = _normalize_text(apply_stderr_excerpt, default="")
    normalized_touched_files = _normalize_string_list(touched_files or [])
    normalized_changed_files = _normalize_string_list(changed_files_after_apply or [])
    normalized_unexpected_changed_files = _normalize_string_list(
        unexpected_changed_files_after_apply or []
    )
    normalized_forbidden_changed_files = _normalize_string_list(
        forbidden_changed_files_after_apply or []
    )
    normalized_py_compile_exit_code = int(_as_int(py_compile_exit_code, default=-1))
    metadata_passed = bool(metadata_consistency_passed)
    metadata_failed = bool(metadata_consistency_failed)
    normalized_cycle_handoff_prompt_kind = _normalize_text(
        cycle_handoff_prompt_kind,
        default="none",
    )
    normalized_cycle_handoff_reason = _normalize_text(cycle_handoff_reason, default="")
    cycle_handoff_consumed = bool(cycle_handoff_available)
    cycle_handoff_acknowledged = bool(
        cycle_handoff_consumed
        and normalized_cycle_handoff_prompt_kind == "fix"
        and normalized_cycle_handoff_reason == "validation_failed"
    )
    cycle_handoff_readiness_source = (
        "cycle_failed_validation" if cycle_handoff_acknowledged else ""
    )
    cycle_handoff_block_reason = ""
    if cycle_handoff_consumed and not cycle_handoff_acknowledged:
        if normalized_cycle_handoff_prompt_kind != "fix":
            cycle_handoff_block_reason = "mismatched_cycle_handoff_prompt_kind"
        elif normalized_cycle_handoff_reason != "validation_failed":
            cycle_handoff_block_reason = "mismatched_cycle_handoff_reason"
    cycle_handoff_re_evaluation_attempted = False
    cycle_handoff_re_evaluation_allowed = False
    cycle_handoff_re_evaluation_block_reason = ""
    cycle_handoff_re_evaluated_status = ""
    cycle_handoff_re_evaluated_ready_to_generate = False
    cycle_handoff_re_evaluated_generation_allowed = False
    cycle_handoff_re_evaluation_safety_gates_passed = False
    cycle_handoff_re_evaluation_source = ""

    target_file_candidates: list[str] = []
    for file_path in [*normalized_changed_files, *normalized_touched_files]:
        if file_path and file_path not in target_file_candidates:
            target_file_candidates.append(file_path)
    fix_target_files = [
        file_path
        for file_path in target_file_candidates
        if file_path not in normalized_forbidden_changed_files
        and file_path not in normalized_unexpected_changed_files
    ]

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    failure_kind = "missing_truth"
    failure_source = "unknown"
    actionable_failure = False
    ready_to_generate = False
    generation_allowed = False
    generation_blocked = True
    next_action = "insufficient_truth"
    prompt_generation_attempted = False
    prompt_generated = False
    prompt_path = ""
    missing_inputs = list(normalized_validation_missing_inputs)

    if rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_posture_required"
        block_reason = "rollback_required"
        failure_kind = "rollback_required"
        failure_source = "prompt157_post_apply_validation"
        next_action = "rollback_required"
    elif human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_posture_required"
        block_reason = "human_review_required"
        failure_kind = "human_review_required"
        failure_source = "prompt157_post_apply_validation"
        next_action = "manual_review_required"
    elif normalized_forbidden_changed_files:
        status = "blocked_forbidden_changes"
        source_status = "forbidden_changes_detected"
        block_reason = "forbidden_changes_detected"
        failure_kind = "forbidden_changes"
        failure_source = "prompt157_changed_file_consistency"
        next_action = "manual_review_required"
    elif normalized_unexpected_changed_files:
        status = "blocked_unexpected_changes"
        source_status = "unexpected_changes_detected"
        block_reason = "unexpected_changes_detected"
        failure_kind = "unexpected_changes"
        failure_source = "prompt157_changed_file_consistency"
        next_action = "manual_review_required"
    elif metadata_failed:
        status = "blocked_metadata_inconsistency"
        source_status = "metadata_inconsistency_detected"
        block_reason = "metadata_consistency_failed"
        failure_kind = "metadata_inconsistency"
        failure_source = "prompt157_metadata_consistency"
        next_action = "wait_for_more_truth"
    elif validation_passed:
        status = "blocked_validation_passed"
        source_status = "validation_passed"
        block_reason = "validation_passed"
        failure_kind = "none"
        failure_source = "prompt157_post_apply_validation"
        next_action = "no_fix_needed"
    elif (
        normalized_validation_status == "insufficient_truth"
        or (not validation_failed and not validation_passed)
    ):
        status = "blocked_insufficient_truth"
        source_status = "validation_truth_unavailable"
        block_reason = "insufficient_truth"
        failure_kind = "missing_truth"
        failure_source = "prompt157_post_apply_validation"
        next_action = "wait_for_more_truth"
        if not missing_inputs:
            missing_inputs.append("post_apply_validation_result")
    elif validation_failed:
        source_status = "validation_failed"
        block_reason = "validation_failed"
        failure_kind = "validation_failed"
        failure_source = "prompt157_post_apply_validation"

        actionable_details_available = False
        if normalized_py_compile_exit_code not in {-1, 0}:
            failure_kind = "py_compile_failed"
            failure_source = "prompt157_py_compile"
            actionable_details_available = bool(normalized_py_compile_stderr)
        elif normalized_validation_status == "blocked_changed_file_mismatch":
            failure_kind = "changed_file_mismatch"
            failure_source = "prompt157_changed_file_consistency"
            actionable_details_available = bool(
                normalized_changed_files or normalized_touched_files
            )
        elif apply_failed or normalized_apply_status in {
            "apply_failed",
            "blocked_post_apply_mutation_mismatch",
            "blocked_no_dry_run_pass",
        }:
            failure_kind = "apply_failed"
            failure_source = "prompt156_real_apply"
            actionable_details_available = bool(normalized_apply_stderr)
        elif dry_run_failed or normalized_dry_run_status == "dry_run_failed":
            failure_kind = "dry_run_failed"
            failure_source = "prompt155_dry_run"
            actionable_details_available = bool(normalized_dry_run_stderr)

        actionable_failure = bool(
            actionable_details_available or bool(fix_target_files)
        )
        if actionable_failure and fix_target_files:
            status = "ready_to_generate_fix_prompt"
            ready_to_generate = True
            generation_allowed = True
            generation_blocked = False
            next_action = "generate_fix_prompt_later"
        elif actionable_failure and not fix_target_files:
            status = "blocked_missing_failure_truth"
            source_status = "fix_target_files_unavailable"
            block_reason = "fix_target_files_unavailable"
            failure_kind = "missing_truth"
            failure_source = "prompt157_changed_file_consistency"
            actionable_failure = False
            next_action = "wait_for_more_truth"
            missing_inputs.append("fix_target_files")
        else:
            status = "blocked_no_actionable_failure"
            source_status = "failure_not_actionable"
            block_reason = "no_actionable_failure"
            failure_kind = "no_actionable_failure"
            next_action = "manual_fix_required"
    else:
        status = "insufficient_truth"
        source_status = "readiness_unresolved"
        block_reason = "insufficient_truth"
        failure_kind = "missing_truth"
        failure_source = "unknown"
        next_action = "insufficient_truth"
        if not missing_inputs:
            missing_inputs.append("validation_failure_classification")

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if failure_kind not in allowed_failure_kinds:
        failure_kind = "missing_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    if status != "ready_to_generate_fix_prompt":
        actionable_failure = False
        ready_to_generate = False
        generation_allowed = False
        generation_blocked = True
    if cycle_handoff_acknowledged:
        cycle_handoff_re_evaluation_attempted = True
        cycle_handoff_re_evaluation_source = "cycle_failed_validation"
        cycle_handoff_re_evaluation_safety_gates_passed = bool(
            status == "ready_to_generate_fix_prompt"
            and ready_to_generate
            and generation_allowed
            and validation_failed
            and not validation_passed
            and not rollback_required
            and not human_review_required
            and not metadata_failed
            and not normalized_forbidden_changed_files
            and not normalized_unexpected_changed_files
            and bool(fix_target_files)
        )
        if cycle_handoff_re_evaluation_safety_gates_passed:
            cycle_handoff_re_evaluation_allowed = True
            status = "cycle_handoff_fix_ready"
            next_action = "generate_fix_prompt"
            ready_to_generate = True
            generation_allowed = True
            generation_blocked = False
            cycle_handoff_re_evaluated_status = status
            cycle_handoff_re_evaluated_ready_to_generate = True
            cycle_handoff_re_evaluated_generation_allowed = True
        elif human_review_required:
            cycle_handoff_re_evaluation_block_reason = "blocked_human_review_required"
        elif normalized_validation_status == "insufficient_truth" or (
            not validation_failed and not validation_passed
        ):
            cycle_handoff_re_evaluation_block_reason = "blocked_missing_truth"
        elif status in {
            "blocked_rollback_required",
            "blocked_forbidden_changes",
            "blocked_unexpected_changes",
            "blocked_metadata_inconsistency",
            "blocked_validation_passed",
            "blocked_missing_failure_truth",
            "blocked_no_actionable_failure",
            "insufficient_truth",
            "blocked_insufficient_truth",
        }:
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_existing_readiness_safety_gate"
            )
        else:
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_insufficient_re_evaluation_truth"
            )
    else:
        if cycle_handoff_consumed:
            cycle_handoff_re_evaluation_attempted = True
        if cycle_handoff_consumed and normalized_cycle_handoff_prompt_kind != "fix":
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_mismatched_cycle_handoff_prompt_kind"
            )
        elif cycle_handoff_consumed and normalized_cycle_handoff_reason != "validation_failed":
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_mismatched_cycle_handoff_reason"
            )
        elif cycle_handoff_consumed or not cycle_handoff_acknowledged:
            cycle_handoff_re_evaluation_block_reason = "blocked_handoff_not_acknowledged"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if failure_kind not in allowed_failure_kinds:
        failure_kind = "missing_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_fix_prompt_readiness_status": status,
        "project_browser_autonomous_fix_prompt_readiness_source_status": source_status,
        "project_browser_autonomous_fix_prompt_readiness_block_reason": block_reason,
        "project_browser_autonomous_fix_prompt_readiness_failure_kind": failure_kind,
        "project_browser_autonomous_fix_prompt_readiness_failure_source": failure_source,
        "project_browser_autonomous_fix_prompt_readiness_actionable_failure": bool(
            actionable_failure
        ),
        "project_browser_autonomous_fix_prompt_readiness_ready_to_generate": bool(
            ready_to_generate
        ),
        "project_browser_autonomous_fix_prompt_readiness_generation_allowed": bool(
            generation_allowed
        ),
        "project_browser_autonomous_fix_prompt_readiness_generation_blocked": bool(
            generation_blocked
        ),
        "project_browser_autonomous_fix_prompt_readiness_prompt_generation_attempted": bool(
            prompt_generation_attempted
        ),
        "project_browser_autonomous_fix_prompt_readiness_prompt_generated": bool(
            prompt_generated
        ),
        "project_browser_autonomous_fix_prompt_readiness_prompt_path": prompt_path,
        "project_browser_autonomous_fix_prompt_readiness_fix_target_files": fix_target_files,
        "project_browser_autonomous_fix_prompt_readiness_changed_files_after_apply": (
            normalized_changed_files
        ),
        "project_browser_autonomous_fix_prompt_readiness_unexpected_changed_files_after_apply": (
            normalized_unexpected_changed_files
        ),
        "project_browser_autonomous_fix_prompt_readiness_forbidden_changed_files_after_apply": (
            normalized_forbidden_changed_files
        ),
        "project_browser_autonomous_fix_prompt_readiness_validation_status": (
            normalized_validation_status
        ),
        "project_browser_autonomous_fix_prompt_readiness_validation_passed": bool(
            validation_passed
        ),
        "project_browser_autonomous_fix_prompt_readiness_validation_failed": bool(
            validation_failed
        ),
        "project_browser_autonomous_fix_prompt_readiness_validation_missing_inputs": (
            normalized_validation_missing_inputs
        ),
        "project_browser_autonomous_fix_prompt_readiness_py_compile_exit_code": int(
            normalized_py_compile_exit_code
        ),
        "project_browser_autonomous_fix_prompt_readiness_py_compile_stderr_excerpt": (
            normalized_py_compile_stderr
        ),
        "project_browser_autonomous_fix_prompt_readiness_apply_status": (
            normalized_apply_status
        ),
        "project_browser_autonomous_fix_prompt_readiness_apply_passed": bool(apply_passed),
        "project_browser_autonomous_fix_prompt_readiness_apply_failed": bool(apply_failed),
        "project_browser_autonomous_fix_prompt_readiness_dry_run_status": (
            normalized_dry_run_status
        ),
        "project_browser_autonomous_fix_prompt_readiness_dry_run_passed": bool(dry_run_passed),
        "project_browser_autonomous_fix_prompt_readiness_dry_run_failed": bool(dry_run_failed),
        "project_browser_autonomous_fix_prompt_readiness_metadata_consistency_passed": bool(
            metadata_passed
        ),
        "project_browser_autonomous_fix_prompt_readiness_metadata_consistency_failed": bool(
            metadata_failed
        ),
        "project_browser_autonomous_fix_prompt_readiness_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_fix_prompt_readiness_rollback_required": bool(
            rollback_required
        ),
        "project_browser_autonomous_fix_prompt_readiness_next_action": next_action,
        "project_browser_autonomous_fix_prompt_readiness_runtime_posture": runtime_posture,
        "project_browser_autonomous_fix_prompt_readiness_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_fix_prompt_readiness_expected_patch_path": (
            normalized_expected_patch_path
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_consumed": bool(
            cycle_handoff_consumed
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_acknowledged": bool(
            cycle_handoff_acknowledged
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_prompt_kind": (
            normalized_cycle_handoff_prompt_kind
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_reason": (
            normalized_cycle_handoff_reason
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_block_reason": (
            cycle_handoff_block_reason
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_readiness_source": (
            cycle_handoff_readiness_source
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluation_attempted": bool(
            cycle_handoff_re_evaluation_attempted
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluation_allowed": bool(
            cycle_handoff_re_evaluation_allowed
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluation_block_reason": (
            cycle_handoff_re_evaluation_block_reason
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluated_status": (
            cycle_handoff_re_evaluated_status
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluated_ready_to_generate": bool(
            cycle_handoff_re_evaluated_ready_to_generate
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluated_generation_allowed": bool(
            cycle_handoff_re_evaluated_generation_allowed
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluation_safety_gates_passed": bool(
            cycle_handoff_re_evaluation_safety_gates_passed
        ),
        "project_browser_autonomous_fix_prompt_readiness_cycle_handoff_re_evaluation_source": (
            cycle_handoff_re_evaluation_source
        ),
    }


def _build_project_browser_autonomous_fix_prompt_generation_state(
    *,
    repository_path: str,
    readiness_status: str,
    readiness_generation_allowed: bool,
    readiness_ready_to_generate: bool,
    actionable_failure: bool,
    failure_kind: str,
    failure_source: str,
    target_files: list[str] | None,
    changed_files_after_apply: list[str] | None,
    unexpected_changed_files_after_apply: list[str] | None,
    forbidden_changed_files_after_apply: list[str] | None,
    validation_status: str,
    validation_passed: bool,
    validation_failed: bool,
    validation_missing_inputs: list[str] | None,
    py_compile_stderr_excerpt: str,
    apply_stderr_excerpt: str,
    dry_run_stderr_excerpt: str,
    rollback_required: bool,
    human_review_required: bool,
    validation_commands: list[str] | None,
    cycle_handoff_generation_input_available: bool = False,
    cycle_handoff_generation_input_consumed: bool = False,
    cycle_handoff_generation_input_kind: str = "none",
    cycle_handoff_generation_input_status: str = "",
    cycle_handoff_generation_input_source: str = "",
    cycle_handoff_generation_input_block_reason: str = "",
) -> dict[str, Any]:
    allowed_statuses = {
        "prompt_generated",
        "blocked_not_ready",
        "blocked_generation_not_allowed",
        "blocked_insufficient_truth",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_missing_target_files",
        "blocked_missing_failure_detail",
        "blocked_handoff_path_invalid",
        "blocked_handoff_write_failed",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "run_codex_with_generated_fix_prompt_later",
        "generate_fix_prompt",
        "wait_for_more_truth",
        "manual_review_required",
        "rollback_required",
        "manual_fix_required",
        "no_fix_needed",
        "insufficient_truth",
    }
    handoff_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    runtime_posture = [
        "bounded_fix_prompt_generation",
        "metadata_and_prompt_text_only",
        "no_prompt_execution",
        "no_external_model_invocation",
        "no_patch_generation",
        "no_patch_apply",
        "no_git_mutation",
    ]
    non_goals = [
        "Do not invoke Codex/ChatGPT/browser automation/external models.",
        "Do not generate or apply patches.",
        "Do not execute rollback, commit, push, PR, CI, merge, or loops.",
        "Do not change unrelated Prompt154-Prompt161 semantics.",
    ]
    safety_constraints = [
        "Keep changes minimal and scoped to target files.",
        "Preserve Prompt154-Prompt161 contract fields and safety gates.",
        "Use only bounded local validation commands.",
        "Do not mutate git or remote state.",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_readiness_status = _normalize_text(
        readiness_status,
        default="insufficient_truth",
    )
    normalized_failure_kind = _normalize_text(failure_kind, default="none")
    normalized_failure_source = _normalize_text(failure_source, default="unknown")
    normalized_target_files = _normalize_string_list(target_files or [])
    normalized_changed_files = _normalize_string_list(changed_files_after_apply or [])
    normalized_unexpected_files = _normalize_string_list(
        unexpected_changed_files_after_apply or []
    )
    normalized_forbidden_files = _normalize_string_list(
        forbidden_changed_files_after_apply or []
    )
    normalized_validation_status = _normalize_text(
        validation_status,
        default="insufficient_truth",
    )
    normalized_validation_missing_inputs = _normalize_string_list(validation_missing_inputs or [])
    normalized_validation_commands = _normalize_string_list(validation_commands or [])
    normalized_cycle_handoff_generation_input_kind = _normalize_text(
        cycle_handoff_generation_input_kind,
        default="none",
    )
    normalized_cycle_handoff_generation_input_status = _normalize_text(
        cycle_handoff_generation_input_status,
        default="",
    )
    normalized_cycle_handoff_generation_input_source = _normalize_text(
        cycle_handoff_generation_input_source,
        default="",
    )
    normalized_cycle_handoff_generation_input_block_reason = _normalize_text(
        cycle_handoff_generation_input_block_reason,
        default="",
    )
    computed_cycle_handoff_generation_input_available = bool(
        cycle_handoff_generation_input_available
    )
    computed_cycle_handoff_generation_input_consumed = bool(
        cycle_handoff_generation_input_consumed
    )

    stderr_excerpt_candidates = _normalize_string_list(
        [
            _normalize_text(py_compile_stderr_excerpt, default=""),
            _normalize_text(apply_stderr_excerpt, default=""),
            _normalize_text(dry_run_stderr_excerpt, default=""),
        ]
    )
    failure_detail_excerpt = ""
    if stderr_excerpt_candidates:
        excerpt_text = stderr_excerpt_candidates[0]
        failure_detail_excerpt = excerpt_text[:600]

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    generation_allowed = False
    generation_attempted = False
    generation_completed = False
    prompt_generated = False
    prompt_kind = "none"
    prompt_body = ""
    prompt_summary = ""
    prompt_handoff_write_attempted = False
    prompt_handoff_write_completed = False
    prompt_handoff_write_failed = False
    next_action = "insufficient_truth"
    missing_inputs = list(normalized_validation_missing_inputs)

    prompt_handoff_path = handoff_path
    handoff_path_obj = Path(prompt_handoff_path)
    prompt_handoff_path_is_exact = prompt_handoff_path == handoff_path
    prompt_handoff_path_parent_exists = handoff_path_obj.parent.exists()
    prompt_handoff_path_is_symlink = handoff_path_obj.is_symlink()

    if rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_posture_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
    elif human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_required"
        block_reason = "human_review_required"
        next_action = "manual_review_required"
    elif normalized_forbidden_files or normalized_unexpected_files:
        status = "blocked_generation_not_allowed"
        source_status = "unsafe_changed_files_detected"
        block_reason = (
            "forbidden_changed_files_detected"
            if normalized_forbidden_files
            else "unexpected_changed_files_detected"
        )
        next_action = "manual_review_required"
    elif normalized_readiness_status in {"blocked_validation_passed"}:
        status = "blocked_not_ready"
        source_status = "readiness_no_fix_needed"
        block_reason = "validation_passed"
        next_action = "no_fix_needed"
    elif normalized_readiness_status in {"insufficient_truth", "blocked_insufficient_truth"}:
        status = "blocked_insufficient_truth"
        source_status = "readiness_insufficient_truth"
        block_reason = "insufficient_truth"
        next_action = "wait_for_more_truth"
        if not missing_inputs:
            missing_inputs.append("fix_prompt_readiness_truth")
    elif normalized_readiness_status not in {
        "ready_to_generate_fix_prompt",
        "cycle_handoff_fix_ready",
    }:
        status = "blocked_not_ready"
        source_status = "readiness_not_ready"
        block_reason = f"readiness_status:{normalized_readiness_status or 'unknown'}"
        next_action = "wait_for_more_truth"
    elif not readiness_generation_allowed or not readiness_ready_to_generate:
        status = "blocked_generation_not_allowed"
        source_status = "readiness_generation_not_allowed"
        block_reason = "readiness_generation_not_allowed"
        next_action = "wait_for_more_truth"
    elif not actionable_failure:
        status = "blocked_generation_not_allowed"
        source_status = "failure_not_actionable"
        block_reason = "actionable_failure_false"
        next_action = "manual_fix_required"
    elif normalized_failure_kind in {"none", "", "missing_truth"}:
        status = "blocked_missing_failure_detail"
        source_status = "failure_kind_missing"
        block_reason = "failure_kind_missing"
        next_action = "wait_for_more_truth"
        if not missing_inputs:
            missing_inputs.append("failure_kind")
    elif not normalized_target_files:
        status = "blocked_missing_target_files"
        source_status = "target_files_missing"
        block_reason = "safe_target_files_missing"
        next_action = "manual_fix_required"
        if "target_files" not in missing_inputs:
            missing_inputs.append("target_files")
    elif not validation_failed:
        status = "blocked_not_ready"
        source_status = "validation_not_failed"
        block_reason = "validation_not_failed"
        next_action = "wait_for_more_truth"
    elif not failure_detail_excerpt and normalized_failure_kind not in {
        "changed_file_mismatch",
        "metadata_inconsistency",
    }:
        status = "blocked_missing_failure_detail"
        source_status = "failure_detail_missing"
        block_reason = "missing_failure_detail_excerpt"
        next_action = "manual_fix_required"
        if "failure_detail_excerpt" not in missing_inputs:
            missing_inputs.append("failure_detail_excerpt")
    else:
        generation_allowed = True
        generation_attempted = True
        generation_completed = True
        prompt_generated = True
        prompt_kind = "bounded_fix_prompt_v1"
        prompt_summary = (
            f"Repair {normalized_failure_kind} from {normalized_failure_source} "
            f"in {len(normalized_target_files)} target file(s)."
        )

        prompt_lines = [
            "Prompt161 Generated Fix Prompt (Bounded, Execution Prohibited)",
            f"Repository: {normalized_repository_path}",
            "",
            "Goal:",
            "Apply the smallest safe code fix that resolves the observed failure state.",
            "",
            "Failure Context:",
            f"- failure_kind: {normalized_failure_kind}",
            f"- failure_source: {normalized_failure_source}",
            f"- validation_status: {normalized_validation_status}",
        ]
        if failure_detail_excerpt:
            prompt_lines.extend(
                [
                    "",
                    "Observed Failure Excerpt (bounded):",
                    failure_detail_excerpt,
                ]
            )
        prompt_lines.extend(
            [
                "",
                "Allowed Target Files (only these):",
            ]
        )
        prompt_lines.extend([f"- {file_path}" for file_path in normalized_target_files])
        prompt_lines.extend(
            [
                "",
                "Exact Repair Requirements:",
                "- Implement the minimum safe fix for the failure.",
                "- Keep Prompt154-Prompt161 semantics unchanged except the targeted fix.",
                "- Do not modify unrelated logic or broad posture precedence behavior.",
                "",
                "Strict Non-Goals:",
            ]
        )
        prompt_lines.extend([f"- {item}" for item in non_goals])
        prompt_lines.extend(
            [
                "",
                "Safety Constraints:",
            ]
        )
        prompt_lines.extend([f"- {item}" for item in safety_constraints])
        prompt_lines.extend(
            [
                "",
                "Validation Commands (run after edits):",
            ]
        )
        prompt_lines.extend([f"- {cmd}" for cmd in normalized_validation_commands])
        prompt_lines.extend(
            [
                "",
                "Expected Report Format:",
                "1. Files changed.",
                "2. Root cause.",
                "3. Exact fix applied.",
                "4. Validation commands run and results.",
                "5. Remaining risks.",
            ]
        )
        prompt_body = "\n".join(prompt_lines).strip()
        status = "prompt_generated"
        source_status = "generation_succeeded"
        block_reason = "none"
        next_action = "run_codex_with_generated_fix_prompt_later"

        if not prompt_handoff_path_is_exact:
            prompt_handoff_write_failed = True
            block_reason = "handoff_path_not_exact"
            next_action = "manual_fix_required"
        elif not prompt_handoff_path_parent_exists:
            prompt_handoff_write_failed = True
            block_reason = "handoff_parent_missing"
            next_action = "manual_fix_required"
        elif prompt_handoff_path_is_symlink:
            prompt_handoff_write_failed = True
            block_reason = "handoff_path_symlink"
            next_action = "manual_fix_required"
        else:
            prompt_handoff_write_attempted = True
            try:
                handoff_path_obj.write_text(prompt_body, encoding="utf-8")
            except OSError:
                prompt_handoff_write_failed = True
                next_action = "manual_fix_required"
                block_reason = "handoff_write_failed"
            else:
                prompt_handoff_write_completed = True

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    if human_review_required:
        normalized_cycle_handoff_generation_input_block_reason = (
            "blocked_human_review_required"
        )
    elif not readiness_generation_allowed or not readiness_ready_to_generate:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_generation_not_allowed"
        )
    elif normalized_readiness_status not in {
        "ready_to_generate_fix_prompt",
        "cycle_handoff_fix_ready",
    }:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_readiness_not_ready"
        )
    elif (
        computed_cycle_handoff_generation_input_available
        and not computed_cycle_handoff_generation_input_consumed
    ):
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_re_evaluation_not_allowed"
        )
    elif (
        computed_cycle_handoff_generation_input_available
        and normalized_cycle_handoff_generation_input_kind not in {"fix", "none"}
    ):
        normalized_cycle_handoff_generation_input_block_reason = (
            "blocked_mismatched_cycle_handoff_generation_kind"
        )
    elif not computed_cycle_handoff_generation_input_available:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_missing_generation_input_truth"
        )
    elif status != "prompt_generated":
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_existing_generation_safety_gate"
        )

    return {
        "project_browser_autonomous_fix_prompt_generation_status": status,
        "project_browser_autonomous_fix_prompt_generation_source_status": source_status,
        "project_browser_autonomous_fix_prompt_generation_block_reason": block_reason,
        "project_browser_autonomous_fix_prompt_generation_readiness_status": (
            normalized_readiness_status
        ),
        "project_browser_autonomous_fix_prompt_generation_readiness_generation_allowed": bool(
            readiness_generation_allowed
        ),
        "project_browser_autonomous_fix_prompt_generation_generation_allowed": bool(
            generation_allowed
        ),
        "project_browser_autonomous_fix_prompt_generation_generation_attempted": bool(
            generation_attempted
        ),
        "project_browser_autonomous_fix_prompt_generation_generation_completed": bool(
            generation_completed
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_generated": bool(
            prompt_generated
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_kind": prompt_kind,
        "project_browser_autonomous_fix_prompt_generation_prompt_body": prompt_body,
        "project_browser_autonomous_fix_prompt_generation_prompt_summary": prompt_summary,
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_path": (
            prompt_handoff_path
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_write_attempted": bool(
            prompt_handoff_write_attempted
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_write_completed": bool(
            prompt_handoff_write_completed
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_write_failed": bool(
            prompt_handoff_write_failed
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_path_is_exact": bool(
            prompt_handoff_path_is_exact
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_path_parent_exists": bool(
            prompt_handoff_path_parent_exists
        ),
        "project_browser_autonomous_fix_prompt_generation_prompt_handoff_path_is_symlink": bool(
            prompt_handoff_path_is_symlink
        ),
        "project_browser_autonomous_fix_prompt_generation_failure_kind": (
            normalized_failure_kind
        ),
        "project_browser_autonomous_fix_prompt_generation_failure_source": (
            normalized_failure_source
        ),
        "project_browser_autonomous_fix_prompt_generation_target_files": (
            normalized_target_files
        ),
        "project_browser_autonomous_fix_prompt_generation_changed_files_after_apply": (
            normalized_changed_files
        ),
        "project_browser_autonomous_fix_prompt_generation_unexpected_changed_files_after_apply": (
            normalized_unexpected_files
        ),
        "project_browser_autonomous_fix_prompt_generation_forbidden_changed_files_after_apply": (
            normalized_forbidden_files
        ),
        "project_browser_autonomous_fix_prompt_generation_validation_commands": (
            normalized_validation_commands
        ),
        "project_browser_autonomous_fix_prompt_generation_non_goals": non_goals,
        "project_browser_autonomous_fix_prompt_generation_safety_constraints": (
            safety_constraints
        ),
        "project_browser_autonomous_fix_prompt_generation_next_action": next_action,
        "project_browser_autonomous_fix_prompt_generation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_fix_prompt_generation_runtime_posture": runtime_posture,
        "project_browser_autonomous_fix_prompt_generation_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_available": bool(
            computed_cycle_handoff_generation_input_available
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_consumed": bool(
            computed_cycle_handoff_generation_input_consumed
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_kind": (
            normalized_cycle_handoff_generation_input_kind
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_status": (
            normalized_cycle_handoff_generation_input_status
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_source": (
            normalized_cycle_handoff_generation_input_source
        ),
        "project_browser_autonomous_fix_prompt_generation_cycle_handoff_generation_input_block_reason": (
            normalized_cycle_handoff_generation_input_block_reason
        ),
    }


def _build_project_browser_autonomous_next_prompt_readiness_state(
    *,
    validation_status: str,
    validation_passed: bool,
    validation_failed: bool,
    post_apply_validation_status: str,
    rollback_required: bool,
    human_review_required: bool,
    fix_prompt_readiness_status: str,
    fix_prompt_generation_status: str,
    prior_next_prompt_generation_attempted: bool,
    implementation_prompt_status: str,
    implementation_prompt_available: bool,
    implementation_prompt_slice_id: str,
    implementation_prompt_bounded_scope_class: str,
    implementation_prompt_preferred_files: list[str] | None,
    project_pr_queue_status: str,
    project_pr_queue_selected_slice_id: str,
    objective_completion_posture: str,
    validation_missing_inputs: list[str] | None,
    fix_readiness_missing_inputs: list[str] | None,
    fix_generation_missing_inputs: list[str] | None,
    cycle_handoff_available: bool = False,
    cycle_handoff_prompt_kind: str = "none",
    cycle_handoff_reason: str = "",
) -> dict[str, Any]:
    allowed_statuses = {
        "ready_to_generate_next_prompt",
        "cycle_handoff_next_ready",
        "blocked_validation_not_passed",
        "blocked_validation_failed",
        "blocked_fix_required",
        "blocked_insufficient_truth",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_missing_next_work",
        "blocked_no_remaining_work",
        "blocked_prompt_generation_already_attempted",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "generate_next_prompt_later",
        "generate_next_prompt",
        "wait_for_validation_pass",
        "run_fix_prompt_flow",
        "wait_for_more_truth",
        "manual_review_required",
        "rollback_required",
        "no_remaining_work",
        "insufficient_truth",
    }
    runtime_posture = [
        "metadata_only_next_prompt_readiness",
        "no_next_prompt_generation",
        "no_handoff_write",
        "no_external_model_invocation",
        "no_patch_apply",
        "no_git_mutation",
        "no_autonomous_loop",
    ]

    normalized_validation_status = _normalize_text(
        validation_status,
        default="insufficient_truth",
    )
    normalized_post_apply_validation_status = _normalize_text(
        post_apply_validation_status,
        default="insufficient_truth",
    )
    normalized_fix_readiness_status = _normalize_text(
        fix_prompt_readiness_status,
        default="insufficient_truth",
    )
    normalized_fix_generation_status = _normalize_text(
        fix_prompt_generation_status,
        default="insufficient_truth",
    )
    normalized_implementation_prompt_status = _normalize_text(
        implementation_prompt_status,
        default="insufficient_truth",
    )
    normalized_implementation_slice_id = _normalize_text(
        implementation_prompt_slice_id,
        default="",
    )
    normalized_scope_class = _normalize_text(
        implementation_prompt_bounded_scope_class,
        default="unknown",
    )
    normalized_queue_status = _normalize_text(
        project_pr_queue_status,
        default="insufficient_truth",
    )
    normalized_queue_slice_id = _normalize_text(
        project_pr_queue_selected_slice_id,
        default="",
    )
    normalized_objective_completion_posture = _normalize_text(
        objective_completion_posture,
        default="objective_insufficient_truth",
    )
    normalized_target_files = _normalize_string_list(
        implementation_prompt_preferred_files or []
    )
    normalized_cycle_handoff_prompt_kind = _normalize_text(
        cycle_handoff_prompt_kind,
        default="none",
    )
    normalized_cycle_handoff_reason = _normalize_text(cycle_handoff_reason, default="")
    cycle_handoff_consumed = bool(cycle_handoff_available)
    cycle_handoff_acknowledged = bool(
        cycle_handoff_consumed
        and normalized_cycle_handoff_prompt_kind == "next"
        and normalized_cycle_handoff_reason == "cycle_passed"
    )
    cycle_handoff_readiness_source = "cycle_passed" if cycle_handoff_acknowledged else ""
    cycle_handoff_block_reason = ""
    if cycle_handoff_consumed and not cycle_handoff_acknowledged:
        if normalized_cycle_handoff_prompt_kind != "next":
            cycle_handoff_block_reason = "mismatched_cycle_handoff_prompt_kind"
        elif normalized_cycle_handoff_reason != "cycle_passed":
            cycle_handoff_block_reason = "mismatched_cycle_handoff_reason"
    cycle_handoff_re_evaluation_attempted = False
    cycle_handoff_re_evaluation_allowed = False
    cycle_handoff_re_evaluation_block_reason = ""
    cycle_handoff_re_evaluated_status = ""
    cycle_handoff_re_evaluated_ready_to_generate = False
    cycle_handoff_re_evaluated_generation_allowed = False
    cycle_handoff_re_evaluation_safety_gates_passed = False
    cycle_handoff_re_evaluation_source = ""
    validation_missing = _normalize_string_list(validation_missing_inputs or [])
    fix_readiness_missing = _normalize_string_list(fix_readiness_missing_inputs or [])
    fix_generation_missing = _normalize_string_list(fix_generation_missing_inputs or [])
    missing_inputs = _serialize_required_signals(
        [*validation_missing, *fix_readiness_missing, *fix_generation_missing]
    )

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    next_work_available = False
    next_work_kind = "none"
    next_scope = "none"
    next_action = "insufficient_truth"
    ready_to_generate = False
    generation_allowed = False
    prompt_generation_attempted = False
    prompt_generated = False
    prompt_path = ""
    insufficient_truth = False

    fix_required_active = bool(
        normalized_fix_readiness_status
        in {
            "ready_to_generate_fix_prompt",
            "blocked_missing_failure_truth",
            "blocked_no_actionable_failure",
            "blocked_forbidden_changes",
            "blocked_unexpected_changes",
            "blocked_metadata_inconsistency",
        }
        or normalized_fix_generation_status
        in {
            "prompt_generated",
            "blocked_missing_target_files",
            "blocked_missing_failure_detail",
            "blocked_handoff_path_invalid",
            "blocked_handoff_write_failed",
        }
    )

    if rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
    elif human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_required"
        block_reason = "human_review_required"
        next_action = "manual_review_required"
    elif normalized_validation_status == "insufficient_truth" or normalized_post_apply_validation_status == "insufficient_truth":
        status = "blocked_insufficient_truth"
        source_status = "validation_truth_unavailable"
        block_reason = "insufficient_truth"
        next_action = "wait_for_more_truth"
        insufficient_truth = True
        if not missing_inputs:
            missing_inputs = ["post_apply_validation_truth"]
    elif fix_required_active:
        status = "blocked_fix_required"
        source_status = "fix_prompt_flow_required"
        block_reason = "fix_required"
        next_action = "run_fix_prompt_flow"
    elif validation_failed:
        status = "blocked_validation_failed"
        source_status = "validation_failed"
        block_reason = "validation_failed"
        next_action = "run_fix_prompt_flow"
    elif not validation_passed:
        status = "blocked_validation_not_passed"
        source_status = "validation_not_passed"
        block_reason = "validation_not_passed"
        next_action = "wait_for_validation_pass"
    elif prior_next_prompt_generation_attempted:
        status = "blocked_prompt_generation_already_attempted"
        source_status = "prior_generation_attempt_detected"
        block_reason = "prompt_generation_already_attempted"
        next_action = "wait_for_more_truth"
    else:
        if (
            normalized_objective_completion_posture == "objective_completed"
            or normalized_queue_status == "empty"
        ):
            status = "blocked_no_remaining_work"
            source_status = "no_remaining_work_detected"
            block_reason = "no_remaining_work"
            next_action = "no_remaining_work"
        elif (
            normalized_implementation_prompt_status == "available"
            and bool(implementation_prompt_available)
            and normalized_queue_status == "prepared"
        ):
            next_work_available = True
            next_work_kind = "queued_slice_next_prompt"
            next_scope = (
                normalized_scope_class
                if normalized_scope_class not in {"", "unknown", "insufficient_truth"}
                else "single_slice"
            )
        else:
            status = "blocked_missing_next_work"
            source_status = "next_work_not_determinable"
            block_reason = "next_work_missing"
            next_action = "wait_for_more_truth"
            if not missing_inputs:
                missing_inputs = ["next_work_truth"]

        scope_bounded = bool(next_scope and next_scope not in {"none", "unknown", "unbounded"})
        if next_work_available and not normalized_target_files:
            status = "blocked_missing_next_work"
            source_status = "next_target_files_missing"
            block_reason = "next_target_files_missing"
            next_action = "wait_for_more_truth"
            if "next_target_files" not in missing_inputs:
                missing_inputs = _serialize_required_signals([*missing_inputs, "next_target_files"])
        elif next_work_available and not scope_bounded:
            status = "blocked_missing_next_work"
            source_status = "next_scope_unbounded"
            block_reason = "next_scope_unbounded"
            next_action = "wait_for_more_truth"
            if "next_scope" not in missing_inputs:
                missing_inputs = _serialize_required_signals([*missing_inputs, "next_scope"])
        elif next_work_available:
            status = "ready_to_generate_next_prompt"
            source_status = "validation_and_scope_ready"
            block_reason = "none"
            next_action = "generate_next_prompt_later"
            ready_to_generate = True
            generation_allowed = True

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if cycle_handoff_acknowledged:
        cycle_handoff_re_evaluation_attempted = True
        cycle_handoff_re_evaluation_source = "cycle_passed"
        cycle_handoff_re_evaluation_safety_gates_passed = bool(
            status == "ready_to_generate_next_prompt"
            and ready_to_generate
            and generation_allowed
            and validation_passed
            and not validation_failed
            and not rollback_required
            and not human_review_required
            and not insufficient_truth
            and next_work_available
            and bool(normalized_target_files)
            and bool(next_scope and next_scope not in {"none", "unknown", "unbounded"})
        )
        if cycle_handoff_re_evaluation_safety_gates_passed:
            cycle_handoff_re_evaluation_allowed = True
            status = "cycle_handoff_next_ready"
            next_action = "generate_next_prompt"
            ready_to_generate = True
            generation_allowed = True
            cycle_handoff_re_evaluated_status = status
            cycle_handoff_re_evaluated_ready_to_generate = True
            cycle_handoff_re_evaluated_generation_allowed = True
        elif human_review_required:
            cycle_handoff_re_evaluation_block_reason = "blocked_human_review_required"
        elif normalized_validation_status == "insufficient_truth" or normalized_post_apply_validation_status == "insufficient_truth":
            cycle_handoff_re_evaluation_block_reason = "blocked_missing_truth"
        elif status in {
            "blocked_rollback_required",
            "blocked_human_review_required",
            "blocked_validation_not_passed",
            "blocked_validation_failed",
            "blocked_fix_required",
            "blocked_insufficient_truth",
            "blocked_missing_next_work",
            "blocked_no_remaining_work",
            "blocked_prompt_generation_already_attempted",
            "insufficient_truth",
        }:
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_existing_readiness_safety_gate"
            )
        else:
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_insufficient_re_evaluation_truth"
            )
    else:
        if cycle_handoff_consumed:
            cycle_handoff_re_evaluation_attempted = True
        if cycle_handoff_consumed and normalized_cycle_handoff_prompt_kind != "next":
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_mismatched_cycle_handoff_prompt_kind"
            )
        elif cycle_handoff_consumed and normalized_cycle_handoff_reason != "cycle_passed":
            cycle_handoff_re_evaluation_block_reason = (
                "blocked_mismatched_cycle_handoff_reason"
            )
        elif cycle_handoff_consumed or not cycle_handoff_acknowledged:
            cycle_handoff_re_evaluation_block_reason = "blocked_handoff_not_acknowledged"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_next_prompt_readiness_status": status,
        "project_browser_autonomous_next_prompt_readiness_source_status": source_status,
        "project_browser_autonomous_next_prompt_readiness_block_reason": block_reason,
        "project_browser_autonomous_next_prompt_readiness_validation_status": (
            normalized_validation_status
        ),
        "project_browser_autonomous_next_prompt_readiness_validation_passed": bool(
            validation_passed
        ),
        "project_browser_autonomous_next_prompt_readiness_validation_failed": bool(
            validation_failed
        ),
        "project_browser_autonomous_next_prompt_readiness_post_apply_validation_status": (
            normalized_post_apply_validation_status
        ),
        "project_browser_autonomous_next_prompt_readiness_rollback_required": bool(
            rollback_required
        ),
        "project_browser_autonomous_next_prompt_readiness_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_next_prompt_readiness_insufficient_truth": bool(
            insufficient_truth
        ),
        "project_browser_autonomous_next_prompt_readiness_fix_prompt_readiness_status": (
            normalized_fix_readiness_status
        ),
        "project_browser_autonomous_next_prompt_readiness_fix_prompt_generation_status": (
            normalized_fix_generation_status
        ),
        "project_browser_autonomous_next_prompt_readiness_next_work_available": bool(
            next_work_available
        ),
        "project_browser_autonomous_next_prompt_readiness_next_work_kind": next_work_kind,
        "project_browser_autonomous_next_prompt_readiness_next_scope": next_scope,
        "project_browser_autonomous_next_prompt_readiness_next_target_files": (
            normalized_target_files
        ),
        "project_browser_autonomous_next_prompt_readiness_ready_to_generate": bool(
            ready_to_generate
        ),
        "project_browser_autonomous_next_prompt_readiness_generation_allowed": bool(
            generation_allowed
        ),
        "project_browser_autonomous_next_prompt_readiness_generation_blocked": bool(
            not generation_allowed
        ),
        "project_browser_autonomous_next_prompt_readiness_prompt_generation_attempted": bool(
            prompt_generation_attempted
        ),
        "project_browser_autonomous_next_prompt_readiness_prompt_generated": bool(
            prompt_generated
        ),
        "project_browser_autonomous_next_prompt_readiness_prompt_path": prompt_path,
        "project_browser_autonomous_next_prompt_readiness_next_action": next_action,
        "project_browser_autonomous_next_prompt_readiness_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_prompt_readiness_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_consumed": bool(
            cycle_handoff_consumed
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_acknowledged": bool(
            cycle_handoff_acknowledged
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_prompt_kind": (
            normalized_cycle_handoff_prompt_kind
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_reason": (
            normalized_cycle_handoff_reason
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_block_reason": (
            cycle_handoff_block_reason
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_readiness_source": (
            cycle_handoff_readiness_source
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluation_attempted": bool(
            cycle_handoff_re_evaluation_attempted
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluation_allowed": bool(
            cycle_handoff_re_evaluation_allowed
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluation_block_reason": (
            cycle_handoff_re_evaluation_block_reason
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluated_status": (
            cycle_handoff_re_evaluated_status
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluated_ready_to_generate": bool(
            cycle_handoff_re_evaluated_ready_to_generate
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluated_generation_allowed": bool(
            cycle_handoff_re_evaluated_generation_allowed
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluation_safety_gates_passed": bool(
            cycle_handoff_re_evaluation_safety_gates_passed
        ),
        "project_browser_autonomous_next_prompt_readiness_cycle_handoff_re_evaluation_source": (
            cycle_handoff_re_evaluation_source
        ),
    }


def _build_project_browser_autonomous_next_prompt_generation_state(
    *,
    repository_path: str,
    current_checkpoint: str,
    readiness_status: str,
    readiness_generation_allowed: bool,
    readiness_ready_to_generate: bool,
    validation_passed: bool,
    validation_failed: bool,
    rollback_required: bool,
    human_review_required: bool,
    insufficient_truth: bool,
    next_work_available: bool,
    next_work_kind: str,
    next_scope: str,
    next_target_files: list[str] | None,
    next_validation_commands: list[str] | None,
    readiness_next_action: str,
    readiness_missing_inputs: list[str] | None,
    cycle_handoff_generation_input_available: bool = False,
    cycle_handoff_generation_input_consumed: bool = False,
    cycle_handoff_generation_input_kind: str = "none",
    cycle_handoff_generation_input_status: str = "",
    cycle_handoff_generation_input_source: str = "",
    cycle_handoff_generation_input_block_reason: str = "",
) -> dict[str, Any]:
    allowed_statuses = {
        "prompt_generated",
        "blocked_not_ready",
        "blocked_generation_not_allowed",
        "blocked_insufficient_truth",
        "blocked_human_review_required",
        "blocked_rollback_required",
        "blocked_missing_next_work",
        "blocked_missing_target_files",
        "blocked_missing_scope",
        "blocked_handoff_path_invalid",
        "blocked_handoff_write_failed",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "select_generated_next_prompt_later",
        "generate_next_prompt",
        "wait_for_more_truth",
        "run_fix_prompt_flow",
        "manual_review_required",
        "rollback_required",
        "manual_next_prompt_required",
        "no_remaining_work",
        "insufficient_truth",
    }
    runtime_posture = [
        "bounded_next_prompt_generation",
        "metadata_and_prompt_text_only",
        "no_prompt_execution",
        "no_external_model_invocation",
        "no_patch_apply",
        "no_git_mutation",
        "no_autonomous_loop",
    ]
    non_goals = [
        "Do not invoke Codex/ChatGPT/browser/external models.",
        "Do not generate or apply implementation patches.",
        "Do not execute rollback, commit, push, GitHub, CI, merge, or loops.",
        "Do not change unrelated Prompt154-Prompt163 semantics.",
    ]
    safety_constraints = [
        "Make the smallest safe additive change for the selected bounded scope.",
        "Keep changes strictly within target files unless absolutely necessary.",
        "Preserve existing Prompt154-Prompt163 safety gates and metadata contracts.",
        "Avoid unrelated refactors and side effects.",
    ]

    handoff_path = "/tmp/codex-local-runner-decision/generated_next_prompt.txt"
    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_checkpoint = _normalize_text(current_checkpoint, default="")
    normalized_readiness_status = _normalize_text(readiness_status, default="insufficient_truth")
    normalized_next_work_kind = _normalize_text(next_work_kind, default="none")
    normalized_next_scope = _normalize_text(next_scope, default="none")
    normalized_next_target_files = _normalize_string_list(next_target_files or [])
    normalized_next_validation_commands = _normalize_string_list(next_validation_commands or [])
    normalized_readiness_next_action = _normalize_text(
        readiness_next_action,
        default="insufficient_truth",
    )
    normalized_cycle_handoff_generation_input_kind = _normalize_text(
        cycle_handoff_generation_input_kind,
        default="none",
    )
    normalized_cycle_handoff_generation_input_status = _normalize_text(
        cycle_handoff_generation_input_status,
        default="",
    )
    normalized_cycle_handoff_generation_input_source = _normalize_text(
        cycle_handoff_generation_input_source,
        default="",
    )
    normalized_cycle_handoff_generation_input_block_reason = _normalize_text(
        cycle_handoff_generation_input_block_reason,
        default="",
    )
    computed_cycle_handoff_generation_input_available = bool(
        cycle_handoff_generation_input_available
    )
    computed_cycle_handoff_generation_input_consumed = bool(
        cycle_handoff_generation_input_consumed
    )
    missing_inputs = _normalize_string_list(readiness_missing_inputs or [])

    scope_bounded = normalized_next_scope not in {
        "",
        "none",
        "unknown",
        "unbounded",
        "insufficient_truth",
    }
    handoff_path_obj = Path(handoff_path)
    prompt_handoff_path_is_exact = handoff_path == "/tmp/codex-local-runner-decision/generated_next_prompt.txt"
    prompt_handoff_path_parent_exists = handoff_path_obj.parent.exists()
    prompt_handoff_path_is_symlink = handoff_path_obj.is_symlink()

    status = "insufficient_truth"
    source_status = "insufficient_truth"
    block_reason = "insufficient_truth"
    generation_allowed = False
    generation_attempted = False
    generation_completed = False
    prompt_generated = False
    prompt_kind = "none"
    prompt_body = ""
    prompt_summary = ""
    prompt_path = ""
    prompt_handoff_write_attempted = False
    prompt_handoff_write_completed = False
    prompt_handoff_write_failed = False
    next_action = "insufficient_truth"

    if rollback_required:
        status = "blocked_rollback_required"
        source_status = "rollback_required"
        block_reason = "rollback_required"
        next_action = "rollback_required"
    elif human_review_required:
        status = "blocked_human_review_required"
        source_status = "human_review_required"
        block_reason = "human_review_required"
        next_action = "manual_review_required"
    elif insufficient_truth or normalized_readiness_status in {
        "blocked_insufficient_truth",
        "insufficient_truth",
    }:
        status = "blocked_insufficient_truth"
        source_status = "insufficient_truth_active"
        block_reason = "insufficient_truth"
        next_action = "wait_for_more_truth"
        if not missing_inputs:
            missing_inputs = ["next_prompt_readiness_truth"]
    elif normalized_readiness_status in {
        "blocked_fix_required",
        "blocked_validation_failed",
    } or normalized_readiness_next_action == "run_fix_prompt_flow":
        status = "blocked_not_ready"
        source_status = "fix_flow_required"
        block_reason = "fix_required"
        next_action = "run_fix_prompt_flow"
    elif normalized_readiness_status not in {
        "ready_to_generate_next_prompt",
        "cycle_handoff_next_ready",
    }:
        status = "blocked_not_ready"
        source_status = "readiness_not_ready"
        block_reason = f"readiness_status:{normalized_readiness_status or 'unknown'}"
        next_action = (
            "no_remaining_work"
            if normalized_readiness_status == "blocked_no_remaining_work"
            else "wait_for_more_truth"
        )
    elif not readiness_generation_allowed or not readiness_ready_to_generate:
        status = "blocked_generation_not_allowed"
        source_status = "readiness_generation_not_allowed"
        block_reason = "generation_not_allowed"
        next_action = "wait_for_more_truth"
    elif not validation_passed or validation_failed:
        status = "blocked_generation_not_allowed"
        source_status = "validation_gate_not_satisfied"
        block_reason = "validation_not_passed"
        next_action = "run_fix_prompt_flow"
    elif not next_work_available:
        status = "blocked_missing_next_work"
        source_status = "next_work_unavailable"
        block_reason = "next_work_unavailable"
        next_action = "wait_for_more_truth"
        if "next_work" not in missing_inputs:
            missing_inputs = _serialize_required_signals([*missing_inputs, "next_work"])
    elif not scope_bounded:
        status = "blocked_missing_scope"
        source_status = "next_scope_unbounded"
        block_reason = "next_scope_unbounded"
        next_action = "wait_for_more_truth"
        if "next_scope" not in missing_inputs:
            missing_inputs = _serialize_required_signals([*missing_inputs, "next_scope"])
    elif not normalized_next_target_files:
        status = "blocked_missing_target_files"
        source_status = "next_target_files_missing"
        block_reason = "next_target_files_missing"
        next_action = "manual_next_prompt_required"
        if "next_target_files" not in missing_inputs:
            missing_inputs = _serialize_required_signals([*missing_inputs, "next_target_files"])
    else:
        generation_allowed = True
        generation_attempted = True
        generation_completed = True
        prompt_generated = True
        prompt_kind = "bounded_next_prompt_v1"
        prompt_path = handoff_path
        prompt_summary = (
            f"Next prompt prepared for {normalized_next_work_kind} with "
            f"{len(normalized_next_target_files)} target file(s)."
        )

        prompt_lines = [
            "Prompt163 Generated Next Prompt (Bounded, Execution Prohibited)",
            f"Repository: {normalized_repository_path}",
            f"Current checkpoint: {normalized_checkpoint}",
            "",
            "Goal:",
            "Implement the next bounded development step as the smallest safe additive change.",
            "",
            "Next Work:",
            f"- next_work_kind: {normalized_next_work_kind}",
            f"- next_scope: {normalized_next_scope}",
            "",
            "Target Files (only these):",
        ]
        prompt_lines.extend([f"- {path}" for path in normalized_next_target_files])
        prompt_lines.extend(
            [
                "",
                "Exact Implementation Requirements:",
                "- Apply only the minimum additive change required for this next step.",
                "- Preserve existing Prompt154-Prompt163 semantics unless the scoped change requires otherwise.",
                "- Avoid unrelated refactors and broad behavior changes.",
                "",
                "Strict Non-Goals:",
            ]
        )
        prompt_lines.extend([f"- {item}" for item in non_goals])
        prompt_lines.extend(
            [
                "",
                "Safety Constraints:",
            ]
        )
        prompt_lines.extend([f"- {item}" for item in safety_constraints])
        prompt_lines.extend(
            [
                "",
                "Validation Commands:",
            ]
        )
        prompt_lines.extend([f"- {cmd}" for cmd in normalized_next_validation_commands])
        prompt_lines.extend(
            [
                "",
                "Expected Report Format:",
                "1. Files changed.",
                "2. Exact behavior implemented.",
                "3. Validation commands run and results.",
                "4. Confirmation of non-goals preserved.",
                "5. Remaining risk.",
            ]
        )
        prompt_body = "\n".join(prompt_lines).strip()
        status = "prompt_generated"
        source_status = "generation_succeeded"
        block_reason = "none"
        next_action = "select_generated_next_prompt_later"

        if not prompt_handoff_path_is_exact:
            prompt_handoff_write_failed = True
            block_reason = "handoff_path_not_exact"
            next_action = "manual_next_prompt_required"
        elif not prompt_handoff_path_parent_exists:
            prompt_handoff_write_failed = True
            block_reason = "handoff_parent_missing"
            next_action = "manual_next_prompt_required"
        elif prompt_handoff_path_is_symlink:
            prompt_handoff_write_failed = True
            block_reason = "handoff_path_symlink"
            next_action = "manual_next_prompt_required"
        else:
            prompt_handoff_write_attempted = True
            try:
                handoff_path_obj.write_text(prompt_body, encoding="utf-8")
            except OSError:
                prompt_handoff_write_failed = True
                block_reason = "handoff_write_failed"
                next_action = "manual_next_prompt_required"
            else:
                prompt_handoff_write_completed = True

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    if human_review_required:
        normalized_cycle_handoff_generation_input_block_reason = (
            "blocked_human_review_required"
        )
    elif not readiness_generation_allowed or not readiness_ready_to_generate:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_generation_not_allowed"
        )
    elif normalized_readiness_status not in {
        "ready_to_generate_next_prompt",
        "cycle_handoff_next_ready",
    }:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_readiness_not_ready"
        )
    elif (
        computed_cycle_handoff_generation_input_available
        and not computed_cycle_handoff_generation_input_consumed
    ):
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_re_evaluation_not_allowed"
        )
    elif (
        computed_cycle_handoff_generation_input_available
        and normalized_cycle_handoff_generation_input_kind not in {"next", "none"}
    ):
        normalized_cycle_handoff_generation_input_block_reason = (
            "blocked_mismatched_cycle_handoff_generation_kind"
        )
    elif not computed_cycle_handoff_generation_input_available:
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_missing_generation_input_truth"
        )
    elif status != "prompt_generated":
        normalized_cycle_handoff_generation_input_block_reason = (
            normalized_cycle_handoff_generation_input_block_reason
            or "blocked_existing_generation_safety_gate"
        )

    return {
        "project_browser_autonomous_next_prompt_generation_status": status,
        "project_browser_autonomous_next_prompt_generation_source_status": source_status,
        "project_browser_autonomous_next_prompt_generation_block_reason": block_reason,
        "project_browser_autonomous_next_prompt_generation_readiness_status": (
            normalized_readiness_status
        ),
        "project_browser_autonomous_next_prompt_generation_readiness_generation_allowed": bool(
            readiness_generation_allowed
        ),
        "project_browser_autonomous_next_prompt_generation_generation_allowed": bool(
            generation_allowed
        ),
        "project_browser_autonomous_next_prompt_generation_generation_attempted": bool(
            generation_attempted
        ),
        "project_browser_autonomous_next_prompt_generation_generation_completed": bool(
            generation_completed
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_generated": bool(
            prompt_generated
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_kind": prompt_kind,
        "project_browser_autonomous_next_prompt_generation_prompt_body": prompt_body,
        "project_browser_autonomous_next_prompt_generation_prompt_summary": prompt_summary,
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_path": handoff_path,
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_write_attempted": bool(
            prompt_handoff_write_attempted
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_write_completed": bool(
            prompt_handoff_write_completed
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_write_failed": bool(
            prompt_handoff_write_failed
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_path_is_exact": bool(
            prompt_handoff_path_is_exact
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_path_parent_exists": bool(
            prompt_handoff_path_parent_exists
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_handoff_path_is_symlink": bool(
            prompt_handoff_path_is_symlink
        ),
        "project_browser_autonomous_next_prompt_generation_next_work_kind": (
            normalized_next_work_kind
        ),
        "project_browser_autonomous_next_prompt_generation_next_scope": (
            normalized_next_scope
        ),
        "project_browser_autonomous_next_prompt_generation_next_target_files": (
            normalized_next_target_files
        ),
        "project_browser_autonomous_next_prompt_generation_next_validation_commands": (
            normalized_next_validation_commands
        ),
        "project_browser_autonomous_next_prompt_generation_non_goals": non_goals,
        "project_browser_autonomous_next_prompt_generation_safety_constraints": (
            safety_constraints
        ),
        "project_browser_autonomous_next_prompt_generation_next_action": next_action,
        "project_browser_autonomous_next_prompt_generation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_next_prompt_generation_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_prompt_generation_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_next_prompt_generation_prompt_path": prompt_path,
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_available": bool(
            computed_cycle_handoff_generation_input_available
        ),
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_consumed": bool(
            computed_cycle_handoff_generation_input_consumed
        ),
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_kind": (
            normalized_cycle_handoff_generation_input_kind
        ),
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_status": (
            normalized_cycle_handoff_generation_input_status
        ),
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_source": (
            normalized_cycle_handoff_generation_input_source
        ),
        "project_browser_autonomous_next_prompt_generation_cycle_handoff_generation_input_block_reason": (
            normalized_cycle_handoff_generation_input_block_reason
        ),
    }


def _build_project_browser_autonomous_generated_prompt_reentry_readiness_state(
    *,
    fix_generation_status: str,
    fix_prompt_generated: bool,
    fix_prompt_handoff_path: str,
    fix_prompt_handoff_write_completed: bool,
    fix_prompt_handoff_write_failed: bool,
    fix_human_review_required: bool,
    fix_next_action: str,
    fix_cycle_handoff_generation_input_available: bool = False,
    fix_cycle_handoff_generation_input_consumed: bool = False,
    fix_cycle_handoff_generation_input_kind: str = "none",
    fix_cycle_handoff_generation_input_block_reason: str = "",
    next_generation_status: str = "",
    next_prompt_generated: bool = False,
    next_prompt_handoff_path: str = "",
    next_prompt_handoff_write_completed: bool = False,
    next_prompt_handoff_write_failed: bool = False,
    next_human_review_required: bool = False,
    next_next_action: str = "",
    next_cycle_handoff_generation_input_available: bool = False,
    next_cycle_handoff_generation_input_consumed: bool = False,
    next_cycle_handoff_generation_input_kind: str = "none",
    next_cycle_handoff_generation_input_block_reason: str = "",
) -> dict[str, Any]:
    allowed_statuses = {
        "reentry_fix_prompt_ready",
        "reentry_next_prompt_ready",
        "reentry_blocked_human_review_required",
        "reentry_blocked_insufficient_truth",
        "reentry_blocked_ambiguous_prompt_kind",
        "insufficient_truth",
    }
    allowed_prompt_kinds = {"fix", "next", "none"}
    allowed_targets = {
        "prompt_selection_and_codex_invocation_readiness",
        "manual_review",
        "none",
    }
    allowed_next_actions = {
        "prepare_fix_prompt_reentry",
        "prepare_next_prompt_reentry",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "metadata_only_generated_prompt_reentry_readiness",
        "no_prompt_generation",
        "no_prompt_execution",
        "no_codex_invocation",
        "no_autonomous_loop",
        "no_git_mutation",
    ]
    fix_allowed_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    next_allowed_path = "/tmp/codex-local-runner-decision/generated_next_prompt.txt"
    max_prompt_size_bytes = 20000

    normalized_fix_generation_status = _normalize_text(
        fix_generation_status,
        default="insufficient_truth",
    )
    normalized_next_generation_status = _normalize_text(
        next_generation_status,
        default="insufficient_truth",
    )
    normalized_fix_prompt_handoff_path = _normalize_text(fix_prompt_handoff_path, default="")
    normalized_next_prompt_handoff_path = _normalize_text(next_prompt_handoff_path, default="")
    normalized_fix_cycle_kind = _normalize_text(
        fix_cycle_handoff_generation_input_kind,
        default="none",
    )
    normalized_next_cycle_kind = _normalize_text(
        next_cycle_handoff_generation_input_kind,
        default="none",
    )
    normalized_fix_cycle_block_reason = _normalize_text(
        fix_cycle_handoff_generation_input_block_reason,
        default="",
    )
    normalized_next_cycle_block_reason = _normalize_text(
        next_cycle_handoff_generation_input_block_reason,
        default="",
    )

    def _safe_prompt_path(path_text: str, expected_path: str) -> tuple[bool, str]:
        normalized_path = _normalize_text(path_text, default="")
        if not normalized_path:
            return False, "blocked_insufficient_reentry_truth"
        if normalized_path != expected_path:
            return False, "blocked_unexpected_prompt_path"
        prompt_path_obj = Path(normalized_path)
        if prompt_path_obj.is_symlink():
            return False, "blocked_prompt_path_symlink"
        if not prompt_path_obj.exists():
            return False, "blocked_prompt_path_missing"
        if not prompt_path_obj.is_file():
            return False, "blocked_prompt_path_not_file"
        try:
            size_bytes = prompt_path_obj.stat().st_size
        except OSError:
            return False, "blocked_prompt_path_unreadable"
        if size_bytes <= 0:
            return False, "blocked_prompt_path_empty"
        if size_bytes > max_prompt_size_bytes:
            return False, "blocked_prompt_path_too_large"
        return True, ""

    fix_path_safe, fix_path_block_reason = _safe_prompt_path(
        normalized_fix_prompt_handoff_path,
        fix_allowed_path,
    )
    next_path_safe, next_path_block_reason = _safe_prompt_path(
        normalized_next_prompt_handoff_path,
        next_allowed_path,
    )

    fix_cycle_ok = True
    if bool(fix_cycle_handoff_generation_input_available):
        fix_cycle_ok = bool(fix_cycle_handoff_generation_input_consumed) and bool(
            normalized_fix_cycle_kind in {"fix", "none"}
        )
    next_cycle_ok = True
    if bool(next_cycle_handoff_generation_input_available):
        next_cycle_ok = bool(next_cycle_handoff_generation_input_consumed) and bool(
            normalized_next_cycle_kind in {"next", "none"}
        )

    fix_ready = bool(
        normalized_fix_generation_status == "prompt_generated"
        and bool(fix_prompt_generated)
        and bool(fix_prompt_handoff_write_completed)
        and not bool(fix_prompt_handoff_write_failed)
        and not bool(fix_human_review_required)
        and fix_path_safe
        and fix_cycle_ok
    )
    next_ready = bool(
        normalized_next_generation_status == "prompt_generated"
        and bool(next_prompt_generated)
        and bool(next_prompt_handoff_write_completed)
        and not bool(next_prompt_handoff_write_failed)
        and not bool(next_human_review_required)
        and next_path_safe
        and next_cycle_ok
    )

    status = "insufficient_truth"
    reentry_allowed = False
    reentry_block_reason = "blocked_insufficient_reentry_truth"
    reentry_prompt_kind = "none"
    reentry_prompt_path = ""
    reentry_target = "none"
    should_update_prompt_selection = False
    should_update_invocation_readiness = False
    should_invoke_codex = False
    should_start_next_cycle = False
    should_rollback = False
    human_review_required = False
    next_action = "insufficient_truth"
    missing_inputs: list[str] = []

    if bool(fix_human_review_required) or bool(next_human_review_required):
        status = "reentry_blocked_human_review_required"
        reentry_block_reason = "blocked_human_review_required"
        reentry_target = "manual_review"
        human_review_required = True
        next_action = "manual_review_required"
    elif fix_ready and next_ready:
        status = "reentry_blocked_ambiguous_prompt_kind"
        reentry_block_reason = "blocked_ambiguous_fix_and_next_reentry"
        reentry_target = "manual_review"
        human_review_required = True
        next_action = "manual_review_required"
    elif fix_ready:
        status = "reentry_fix_prompt_ready"
        reentry_allowed = True
        reentry_block_reason = ""
        reentry_prompt_kind = "fix"
        reentry_prompt_path = normalized_fix_prompt_handoff_path
        reentry_target = "prompt_selection_and_codex_invocation_readiness"
        should_update_prompt_selection = True
        should_update_invocation_readiness = True
        human_review_required = False
        next_action = "prepare_fix_prompt_reentry"
    elif next_ready:
        status = "reentry_next_prompt_ready"
        reentry_allowed = True
        reentry_block_reason = ""
        reentry_prompt_kind = "next"
        reentry_prompt_path = normalized_next_prompt_handoff_path
        reentry_target = "prompt_selection_and_codex_invocation_readiness"
        should_update_prompt_selection = True
        should_update_invocation_readiness = True
        human_review_required = False
        next_action = "prepare_next_prompt_reentry"
    else:
        status = "reentry_blocked_insufficient_truth"
        reentry_block_reason = "blocked_insufficient_reentry_truth"
        reentry_target = "manual_review"
        human_review_required = True
        next_action = "manual_review_required"
        if normalized_fix_generation_status != "prompt_generated":
            missing_inputs.append("fix_generation_prompt_not_generated")
        if normalized_next_generation_status != "prompt_generated":
            missing_inputs.append("next_generation_prompt_not_generated")
        if not fix_path_safe and fix_path_block_reason:
            missing_inputs.append(f"fix:{fix_path_block_reason}")
        if not next_path_safe and next_path_block_reason:
            missing_inputs.append(f"next:{next_path_block_reason}")
        if (
            bool(fix_cycle_handoff_generation_input_available)
            and not fix_cycle_ok
            and normalized_fix_cycle_block_reason
        ):
            missing_inputs.append(f"fix:{normalized_fix_cycle_block_reason}")
        if (
            bool(next_cycle_handoff_generation_input_available)
            and not next_cycle_ok
            and normalized_next_cycle_block_reason
        ):
            missing_inputs.append(f"next:{normalized_next_cycle_block_reason}")

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if reentry_prompt_kind not in allowed_prompt_kinds:
        reentry_prompt_kind = "none"
    if reentry_target not in allowed_targets:
        reentry_target = "none"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_generated_prompt_reentry_readiness_status": status,
        "project_browser_autonomous_generated_prompt_reentry_readiness_reentry_allowed": bool(
            reentry_allowed
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_reentry_block_reason": (
            reentry_block_reason
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_reentry_prompt_kind": (
            reentry_prompt_kind
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_reentry_prompt_path": (
            reentry_prompt_path
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_reentry_target": (
            reentry_target
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_should_update_prompt_selection": bool(
            should_update_prompt_selection
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_should_update_invocation_readiness": bool(
            should_update_invocation_readiness
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_should_start_next_cycle": bool(
            should_start_next_cycle
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_should_rollback": bool(
            should_rollback
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_fix_generation_status": (
            normalized_fix_generation_status
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_fix_prompt_generated": bool(
            fix_prompt_generated
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_fix_prompt_handoff_write_completed": bool(
            fix_prompt_handoff_write_completed
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_next_generation_status": (
            normalized_next_generation_status
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_next_prompt_generated": bool(
            next_prompt_generated
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_next_prompt_handoff_write_completed": bool(
            next_prompt_handoff_write_completed
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_next_action": (
            next_action
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_fix_next_action": (
            _normalize_text(fix_next_action, default="")
        ),
        "project_browser_autonomous_generated_prompt_reentry_readiness_source_next_next_action": (
            _normalize_text(next_next_action, default="")
        ),
    }


def _build_project_browser_autonomous_generated_prompt_reentry_routing_state(
    *,
    reentry_status: str,
    reentry_allowed: bool,
    reentry_prompt_kind: str,
    reentry_prompt_path: str,
    reentry_target: str,
    should_update_prompt_selection: bool,
    should_update_invocation_readiness: bool,
    should_invoke_codex: bool,
    should_start_next_cycle: bool,
    should_rollback: bool,
    human_review_required: bool,
    next_action: str,
    reentry_block_reason: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "reentry_routing_fix_ready",
        "reentry_routing_next_ready",
        "reentry_routing_blocked",
        "reentry_routing_blocked_ambiguous",
        "reentry_routing_blocked_unsafe_path",
        "reentry_routing_blocked_insufficient_truth",
    }
    allowed_prompt_kinds = {"fix", "next", "none"}
    allowed_next_actions = {
        "prepare_bounded_reentry_codex_invocation",
        "manual_review_required",
        "insufficient_truth",
    }
    allowed_prompt_paths = {
        "/tmp/codex-local-runner-decision/generated_fix_prompt.txt",
        "/tmp/codex-local-runner-decision/generated_next_prompt.txt",
    }
    max_prompt_size_bytes = 20000
    runtime_posture = [
        "metadata_only_generated_prompt_reentry_routing",
        "no_codex_invocation",
        "no_prompt_generation",
        "no_prompt_execution",
        "no_git_mutation",
        "no_autonomous_loop",
    ]

    source_status = _normalize_text(reentry_status, default="insufficient_truth")
    normalized_prompt_kind = _normalize_text(reentry_prompt_kind, default="none")
    normalized_prompt_path = _normalize_text(reentry_prompt_path, default="")
    normalized_reentry_target = _normalize_text(reentry_target, default="")
    normalized_source_next_action = _normalize_text(next_action, default="")
    normalized_source_block_reason = _normalize_text(reentry_block_reason, default="")

    path_is_exact = normalized_prompt_path in allowed_prompt_paths
    prompt_path_obj = Path(normalized_prompt_path) if normalized_prompt_path else None
    path_exists = bool(prompt_path_obj and prompt_path_obj.exists())
    path_is_file = bool(prompt_path_obj and prompt_path_obj.is_file())
    path_is_symlink = bool(prompt_path_obj and prompt_path_obj.is_symlink())
    size_bytes = 0
    if prompt_path_obj and path_exists and path_is_file and not path_is_symlink:
        try:
            size_bytes = _as_non_negative_int(prompt_path_obj.stat().st_size, default=0)
        except OSError:
            size_bytes = 0
    file_non_empty = size_bytes > 0
    file_too_large = size_bytes > max_prompt_size_bytes
    path_safe = bool(
        path_is_exact
        and path_exists
        and path_is_file
        and not path_is_symlink
        and file_non_empty
        and not file_too_large
    )

    status = "reentry_routing_blocked_insufficient_truth"
    reentry_routing_allowed = False
    reentry_routing_block_reason = "blocked_insufficient_reentry_truth"
    selection_refresh_allowed = False
    selection_refresh_kind = "none"
    selection_refresh_path = ""
    invocation_readiness_refresh_allowed = False
    write_invocation_reentry_prepared = False
    next_action_out = "manual_review_required"
    missing_inputs: list[str] = []

    if bool(human_review_required):
        status = "reentry_routing_blocked"
        reentry_routing_block_reason = "blocked_human_review_required"
        next_action_out = "manual_review_required"
    elif source_status == "reentry_blocked_ambiguous_prompt_kind" or (
        normalized_source_block_reason == "blocked_ambiguous_fix_and_next_reentry"
    ):
        status = "reentry_routing_blocked_ambiguous"
        reentry_routing_block_reason = "blocked_ambiguous_fix_and_next_reentry"
        next_action_out = "manual_review_required"
    elif bool(reentry_allowed) and not path_safe:
        status = "reentry_routing_blocked_unsafe_path"
        if not normalized_prompt_path:
            reentry_routing_block_reason = "blocked_prompt_path_missing"
            missing_inputs.append("reentry_prompt_path")
        elif not path_is_exact:
            reentry_routing_block_reason = "blocked_prompt_path_unexpected"
        elif path_is_symlink:
            reentry_routing_block_reason = "blocked_prompt_path_symlink"
        elif not path_exists:
            reentry_routing_block_reason = "blocked_prompt_path_missing"
        elif not path_is_file:
            reentry_routing_block_reason = "blocked_prompt_path_not_file"
        elif not file_non_empty:
            reentry_routing_block_reason = "blocked_prompt_empty"
        elif file_too_large:
            reentry_routing_block_reason = "blocked_prompt_too_large"
        else:
            reentry_routing_block_reason = "blocked_prompt_path_unexpected"
        next_action_out = "manual_review_required"
    elif (
        bool(reentry_allowed)
        and not bool(human_review_required)
        and normalized_prompt_kind == "fix"
        and path_safe
    ):
        status = "reentry_routing_fix_ready"
        reentry_routing_allowed = True
        reentry_routing_block_reason = ""
        selection_refresh_allowed = bool(should_update_prompt_selection)
        selection_refresh_kind = "fix"
        selection_refresh_path = normalized_prompt_path
        invocation_readiness_refresh_allowed = bool(
            selection_refresh_allowed and should_update_invocation_readiness
        )
        write_invocation_reentry_prepared = bool(invocation_readiness_refresh_allowed)
        next_action_out = "prepare_bounded_reentry_codex_invocation"
    elif (
        bool(reentry_allowed)
        and not bool(human_review_required)
        and normalized_prompt_kind == "next"
        and path_safe
    ):
        status = "reentry_routing_next_ready"
        reentry_routing_allowed = True
        reentry_routing_block_reason = ""
        selection_refresh_allowed = bool(should_update_prompt_selection)
        selection_refresh_kind = "next"
        selection_refresh_path = normalized_prompt_path
        invocation_readiness_refresh_allowed = bool(
            selection_refresh_allowed and should_update_invocation_readiness
        )
        write_invocation_reentry_prepared = bool(invocation_readiness_refresh_allowed)
        next_action_out = "prepare_bounded_reentry_codex_invocation"
    else:
        status = "reentry_routing_blocked_insufficient_truth"
        reentry_routing_block_reason = "blocked_insufficient_reentry_truth"
        next_action_out = "manual_review_required"
        if normalized_source_block_reason:
            missing_inputs.append(normalized_source_block_reason)
        if not normalized_prompt_kind or normalized_prompt_kind == "none":
            missing_inputs.append("reentry_prompt_kind")
        if not normalized_prompt_path:
            missing_inputs.append("reentry_prompt_path")
        if not normalized_reentry_target:
            missing_inputs.append("reentry_target")

    if status not in allowed_statuses:
        status = "reentry_routing_blocked_insufficient_truth"
    if selection_refresh_kind not in allowed_prompt_kinds:
        selection_refresh_kind = "none"
    if normalized_prompt_kind not in allowed_prompt_kinds:
        normalized_prompt_kind = "none"
    if next_action_out not in allowed_next_actions:
        next_action_out = "insufficient_truth"

    return {
        "project_browser_autonomous_generated_prompt_reentry_routing_status": status,
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_routing_allowed": bool(
            reentry_routing_allowed
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_routing_block_reason": (
            reentry_routing_block_reason
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_kind": (
            normalized_prompt_kind
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_path": (
            normalized_prompt_path
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_selection_refresh_allowed": bool(
            selection_refresh_allowed
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_selection_refresh_kind": (
            selection_refresh_kind
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_selection_refresh_path": (
            selection_refresh_path
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_invocation_readiness_refresh_allowed": bool(
            invocation_readiness_refresh_allowed
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_write_invocation_reentry_prepared": bool(
            write_invocation_reentry_prepared
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_max_reentry_invocations": 1,
        "project_browser_autonomous_generated_prompt_reentry_routing_should_invoke_codex": bool(
            False
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_should_start_next_cycle": bool(
            False
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_should_rollback": bool(
            False
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_human_review_required": bool(
            bool(human_review_required) or not bool(reentry_routing_allowed)
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_next_action": (
            next_action_out
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_runtime_posture": runtime_posture,
        "project_browser_autonomous_generated_prompt_reentry_routing_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_status": (
            source_status
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_next_action": (
            normalized_source_next_action
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_block_reason": (
            normalized_source_block_reason
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_target": (
            normalized_reentry_target
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_should_start_next_cycle": bool(
            should_start_next_cycle
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_source_should_rollback": bool(
            should_rollback
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_path_is_exact": bool(
            path_is_exact
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_path_exists": bool(
            path_exists
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_path_is_symlink": bool(
            path_is_symlink
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_file_non_empty": bool(
            file_non_empty
        ),
        "project_browser_autonomous_generated_prompt_reentry_routing_reentry_prompt_file_too_large": bool(
            file_too_large
        ),
    }


def _build_project_browser_autonomous_codex_reentry_invocation_state(
    *,
    repository_path: str,
    reentry_routing_status: str,
    reentry_routing_allowed: bool,
    reentry_prompt_kind: str,
    reentry_prompt_path: str,
    selection_refresh_allowed: bool,
    invocation_readiness_refresh_allowed: bool,
    write_invocation_reentry_prepared: bool,
    reentry_selected_prompt_kind: str,
    reentry_selected_prompt_path: str,
    reentry_selected_prompt_ready: bool,
    reentry_prompt_path_is_exact: bool,
    reentry_prompt_path_exists: bool,
    reentry_prompt_path_is_symlink: bool,
    reentry_prompt_file_non_empty: bool,
    reentry_prompt_file_too_large: bool,
    reentry_max_invocations: int,
    reentry_should_start_next_cycle: bool,
    reentry_should_rollback: bool,
    human_review_required: bool,
    reentry_routing_block_reason: str,
    prior_write_invocation_attempted: bool,
    prior_write_invocation_completed: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "reentry_invocation_completed_with_changes",
        "reentry_invocation_completed_no_changes",
        "reentry_invocation_completed_failure",
        "reentry_invocation_completed_timeout",
        "blocked_human_review_required",
        "blocked_reentry_routing_not_allowed",
        "blocked_selection_refresh_not_allowed",
        "blocked_invocation_readiness_not_allowed",
        "blocked_write_reentry_not_prepared",
        "blocked_prompt_not_ready",
        "blocked_prompt_path_unsafe",
        "blocked_ambiguous_reentry_prompt_kind",
        "blocked_max_reentry_invocations_not_one",
        "blocked_rollback_required",
        "blocked_insufficient_reentry_invocation_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_bounded_reentry_codex_invocation",
        "reentry_result_assimilation",
        "manual_review_required",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    allowed_prompt_paths = {
        "/tmp/codex-local-runner-decision/generated_fix_prompt.txt",
        "/tmp/codex-local-runner-decision/generated_next_prompt.txt",
    }
    max_prompt_size_bytes = 20000
    runtime_posture = [
        "prompt180_single_bounded_reentry_invocation",
        "reuses_prompt167_workspace_write_executor",
        "no_retry",
        "no_loop",
        "no_rollback",
        "no_git_stage_commit_push",
        "no_github_mutation",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_routing_status = _normalize_text(
        reentry_routing_status,
        default="insufficient_truth",
    )
    normalized_reentry_prompt_kind = _normalize_text(reentry_prompt_kind, default="none")
    normalized_reentry_prompt_path = _normalize_text(reentry_prompt_path, default="")
    normalized_selected_prompt_kind = _normalize_text(
        reentry_selected_prompt_kind,
        default="none",
    )
    normalized_selected_prompt_path = _normalize_text(
        reentry_selected_prompt_path,
        default="",
    )
    normalized_block_reason = _normalize_text(reentry_routing_block_reason, default="")

    effective_prompt_kind = (
        normalized_selected_prompt_kind
        if normalized_selected_prompt_kind in {"fix", "next"}
        else normalized_reentry_prompt_kind
    )
    effective_prompt_path = (
        normalized_selected_prompt_path or normalized_reentry_prompt_path
    )

    prompt_path_obj = Path(effective_prompt_path) if effective_prompt_path else None
    prompt_path_is_exact_now = effective_prompt_path in allowed_prompt_paths
    prompt_path_exists_now = bool(prompt_path_obj and prompt_path_obj.exists())
    prompt_path_is_symlink_now = bool(prompt_path_obj and prompt_path_obj.is_symlink())
    prompt_path_is_file_now = bool(prompt_path_obj and prompt_path_obj.is_file())
    prompt_size_bytes_now = 0
    if prompt_path_obj and prompt_path_exists_now and prompt_path_is_file_now and not prompt_path_is_symlink_now:
        try:
            prompt_size_bytes_now = _as_non_negative_int(
                prompt_path_obj.stat().st_size,
                default=0,
            )
        except OSError:
            prompt_size_bytes_now = 0
    prompt_file_non_empty_now = prompt_size_bytes_now > 0
    prompt_file_too_large_now = prompt_size_bytes_now > max_prompt_size_bytes
    prompt_path_safe = bool(
        prompt_path_is_exact_now
        and prompt_path_exists_now
        and prompt_path_is_file_now
        and not prompt_path_is_symlink_now
        and prompt_file_non_empty_now
        and not prompt_file_too_large_now
    )

    normalized_max_invocations = _as_non_negative_int(reentry_max_invocations, default=0)
    ambiguity_detected = bool(
        normalized_reentry_prompt_kind in {"fix", "next"}
        and normalized_selected_prompt_kind in {"fix", "next"}
        and normalized_reentry_prompt_kind != normalized_selected_prompt_kind
    )
    allowed_for_execution = False
    status = "insufficient_truth"
    block_reason = "blocked_insufficient_reentry_invocation_truth"
    next_action = "wait_for_more_truth"
    missing_inputs: list[str] = []
    local_human_review_required = bool(human_review_required)

    if local_human_review_required:
        status = "blocked_human_review_required"
        block_reason = "blocked_human_review_required"
        next_action = "manual_review_required"
    elif bool(reentry_should_rollback):
        status = "blocked_rollback_required"
        block_reason = "blocked_rollback_required"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not bool(reentry_routing_allowed):
        status = "blocked_reentry_routing_not_allowed"
        block_reason = (
            normalized_block_reason
            if normalized_block_reason
            else "blocked_reentry_routing_not_allowed"
        )
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not bool(selection_refresh_allowed):
        status = "blocked_selection_refresh_not_allowed"
        block_reason = "blocked_selection_refresh_not_allowed"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not bool(invocation_readiness_refresh_allowed):
        status = "blocked_invocation_readiness_not_allowed"
        block_reason = "blocked_invocation_readiness_not_allowed"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not bool(write_invocation_reentry_prepared):
        status = "blocked_write_reentry_not_prepared"
        block_reason = "blocked_write_reentry_not_prepared"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif bool(prior_write_invocation_attempted) or bool(prior_write_invocation_completed):
        status = "blocked_invocation_readiness_not_allowed"
        block_reason = "prior_write_invocation_already_attempted"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif ambiguity_detected or effective_prompt_kind not in {"fix", "next"}:
        status = "blocked_ambiguous_reentry_prompt_kind"
        block_reason = "blocked_ambiguous_reentry_prompt_kind"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not bool(reentry_selected_prompt_ready):
        status = "blocked_prompt_not_ready"
        block_reason = "blocked_prompt_not_ready"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif normalized_max_invocations != 1:
        status = "blocked_max_reentry_invocations_not_one"
        block_reason = "blocked_max_reentry_invocations_not_one"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not prompt_path_safe:
        status = "blocked_prompt_path_unsafe"
        if not effective_prompt_path:
            block_reason = "blocked_prompt_path_missing"
            missing_inputs.append("reentry_prompt_path")
        elif not prompt_path_is_exact_now:
            block_reason = "blocked_prompt_path_unexpected"
        elif prompt_path_is_symlink_now:
            block_reason = "blocked_prompt_path_symlink"
        elif not prompt_path_exists_now:
            block_reason = "blocked_prompt_path_missing"
        elif not prompt_path_is_file_now:
            block_reason = "blocked_prompt_path_not_file"
        elif not prompt_file_non_empty_now:
            block_reason = "blocked_prompt_empty"
        elif prompt_file_too_large_now:
            block_reason = "blocked_prompt_too_large"
        else:
            block_reason = "blocked_prompt_path_unsafe"
        next_action = "manual_review_required"
        local_human_review_required = True
    elif not normalized_repository_path:
        status = "blocked_insufficient_reentry_invocation_truth"
        block_reason = "blocked_insufficient_reentry_invocation_truth"
        next_action = "wait_for_more_truth"
        missing_inputs.append("repository_path")
        local_human_review_required = True
    elif bool(reentry_should_start_next_cycle):
        status = "blocked_insufficient_reentry_invocation_truth"
        block_reason = "blocked_insufficient_reentry_invocation_truth"
        next_action = "manual_review_required"
        local_human_review_required = True
        missing_inputs.append("reentry_should_start_next_cycle")
    else:
        allowed_for_execution = True
        status = "insufficient_truth"
        block_reason = ""
        next_action = "prepare_bounded_reentry_codex_invocation"
        local_human_review_required = False

    write_state: dict[str, Any] = {}
    reentry_invocation_attempted = False
    reentry_invocation_completed = False
    reentry_invocations_attempted = 0
    reentry_invocations_completed = 0
    result_class = "blocked"
    exit_code = -1
    timed_out = False
    changed_files_after: list[str] = []
    changed_files_count_after = 0
    command: list[str] = []
    stdout_path = "/tmp/codex-local-runner-decision/codex_write_invocation_stdout.txt"
    stderr_path = "/tmp/codex-local-runner-decision/codex_write_invocation_stderr.txt"
    result_path = "/tmp/codex-local-runner-decision/codex_write_invocation_result.json"
    git_diff_name_only_path = "/tmp/codex-local-runner-decision/codex_write_git_diff_name_only.txt"
    git_diff_numstat_path = "/tmp/codex-local-runner-decision/codex_write_git_diff_numstat.txt"
    reentry_result_ready_for_assimilation = False
    reentry_result_assimilation_source = ""
    reentry_result_next_stage = "manual_review_or_blocked_reentry"

    if allowed_for_execution:
        write_state = _build_project_browser_autonomous_codex_write_invocation_state(
            repository_path=normalized_repository_path,
            codex_invocation_readiness_status="ready_to_invoke_codex",
            codex_invocation_readiness_allowed=True,
            selected_prompt_kind=effective_prompt_kind,
            selected_prompt_path=effective_prompt_path,
            selected_prompt_source="project_browser_autonomous_generated_prompt_reentry_routing",
            selected_prompt_ready=True,
            selected_prompt_path_is_exact=True,
            selected_prompt_path_exists=True,
            selected_prompt_path_is_symlink=False,
            selected_prompt_file_non_empty=True,
            selected_prompt_file_too_large=False,
            rollback_required=False,
            human_review_required=False,
            insufficient_truth=False,
            max_invocations=1,
            prior_write_invocation_attempted=bool(prior_write_invocation_attempted),
            prior_write_invocation_completed=bool(prior_write_invocation_completed),
        )
        write_exec_status = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_status"
            ),
            default="insufficient_truth",
        )
        write_result_status = _normalize_text(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_status"),
            default="insufficient_truth",
        )
        write_exec_block_reason = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_block_reason"
            ),
            default="",
        )
        command = _normalize_string_list(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_command"
            )
        )
        stdout_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_stdout_path"
            ),
            default=stdout_path,
        )
        stderr_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_stderr_path"
            ),
            default=stderr_path,
        )
        result_path = _normalize_text(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_result_json_path"),
            default=result_path,
        )
        git_diff_name_only_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_git_diff_name_only_path"
            ),
            default=git_diff_name_only_path,
        )
        git_diff_numstat_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_git_diff_numstat_path"
            ),
            default=git_diff_numstat_path,
        )
        changed_files_after = _normalize_string_list(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_changed_files_after"
            )
        )
        changed_files_count_after = _as_non_negative_int(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_changed_files_count_after"
            ),
            default=len(changed_files_after),
        )
        exit_code = int(
            _as_int(
                write_state.get(
                    "project_browser_autonomous_codex_write_invocation_result_exit_code"
                ),
                default=-1,
            )
        )
        timed_out = bool(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_timeout", False)
        )
        reentry_invocation_attempted = bool(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_attempted",
                False,
            )
        )
        reentry_invocation_completed = bool(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_completed",
                False,
            )
        )
        reentry_invocations_attempted = 1 if reentry_invocation_attempted else 0
        reentry_invocations_completed = (
            1 if (reentry_invocation_completed and not timed_out) else 0
        )

        if write_result_status == "completed_with_changes":
            status = "reentry_invocation_completed_with_changes"
            result_class = "completed_with_changes"
            next_action = "reentry_result_assimilation"
            reentry_result_ready_for_assimilation = True
        elif write_result_status == "completed_no_changes":
            status = "reentry_invocation_completed_no_changes"
            result_class = "completed_no_changes"
            next_action = "reentry_result_assimilation"
            reentry_result_ready_for_assimilation = True
        elif write_result_status == "completed_failure":
            status = "reentry_invocation_completed_failure"
            result_class = "completed_failure"
            next_action = "reentry_result_assimilation"
            reentry_result_ready_for_assimilation = True
            local_human_review_required = True
        elif write_result_status == "completed_timeout":
            status = "reentry_invocation_completed_timeout"
            result_class = "completed_timeout"
            next_action = "reentry_result_assimilation"
            reentry_result_ready_for_assimilation = True
            local_human_review_required = True
        else:
            status = "blocked_insufficient_reentry_invocation_truth"
            result_class = "blocked"
            block_reason = (
                write_exec_block_reason
                if write_exec_block_reason
                else (
                    write_exec_status
                    if write_exec_status != "insufficient_truth"
                    else "blocked_insufficient_reentry_invocation_truth"
                )
            )
            next_action = "manual_review_required"
            local_human_review_required = True
            reentry_result_ready_for_assimilation = False

        if reentry_result_ready_for_assimilation:
            reentry_result_assimilation_source = "prompt180_reentry_invocation"
            reentry_result_next_stage = "reentry_result_assimilation"
        else:
            reentry_result_assimilation_source = ""
            reentry_result_next_stage = "manual_review_or_blocked_reentry"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_codex_reentry_invocation_status": status,
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocation_allowed": bool(
            allowed_for_execution
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocation_attempted": bool(
            reentry_invocation_attempted
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocation_completed": bool(
            reentry_invocation_completed
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocation_block_reason": (
            block_reason
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_prompt_kind": (
            effective_prompt_kind if effective_prompt_kind in {"fix", "next"} else "none"
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_prompt_path": (
            effective_prompt_path
        ),
        "project_browser_autonomous_codex_reentry_invocation_max_reentry_invocations": int(
            normalized_max_invocations
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocations_attempted": int(
            reentry_invocations_attempted
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_invocations_completed": int(
            reentry_invocations_completed
        ),
        "project_browser_autonomous_codex_reentry_invocation_reused_write_invocation_path": True,
        "project_browser_autonomous_codex_reentry_invocation_execution_sandbox": "workspace-write",
        "project_browser_autonomous_codex_reentry_invocation_command": command,
        "project_browser_autonomous_codex_reentry_invocation_stdout_path": stdout_path,
        "project_browser_autonomous_codex_reentry_invocation_stderr_path": stderr_path,
        "project_browser_autonomous_codex_reentry_invocation_result_path": result_path,
        "project_browser_autonomous_codex_reentry_invocation_git_diff_name_only_path": (
            git_diff_name_only_path
        ),
        "project_browser_autonomous_codex_reentry_invocation_git_diff_numstat_path": (
            git_diff_numstat_path
        ),
        "project_browser_autonomous_codex_reentry_invocation_changed_files_after": (
            changed_files_after
        ),
        "project_browser_autonomous_codex_reentry_invocation_changed_files_count_after": int(
            changed_files_count_after
        ),
        "project_browser_autonomous_codex_reentry_invocation_result_class": result_class,
        "project_browser_autonomous_codex_reentry_invocation_exit_code": int(exit_code),
        "project_browser_autonomous_codex_reentry_invocation_timed_out": bool(timed_out),
        "project_browser_autonomous_codex_reentry_invocation_reentry_result_ready_for_assimilation": bool(
            reentry_result_ready_for_assimilation
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_result_assimilation_source": (
            reentry_result_assimilation_source
        ),
        "project_browser_autonomous_codex_reentry_invocation_reentry_result_next_stage": (
            reentry_result_next_stage
        ),
        "project_browser_autonomous_codex_reentry_invocation_human_review_required": bool(
            local_human_review_required
        ),
        "project_browser_autonomous_codex_reentry_invocation_next_action": next_action,
        "project_browser_autonomous_codex_reentry_invocation_runtime_posture": runtime_posture,
        "project_browser_autonomous_codex_reentry_invocation_missing_inputs": (
            _serialize_required_signals(missing_inputs)
        ),
    }


def _build_project_browser_autonomous_reentry_result_assimilation_state(
    *,
    reentry_routing_status: str,
    reentry_routing_allowed: bool,
    reentry_routing_block_reason: str,
    reentry_status: str,
    reentry_invocation_allowed: bool,
    reentry_invocation_attempted: bool,
    reentry_invocation_completed: bool,
    reentry_invocation_block_reason: str,
    reentry_prompt_kind: str,
    reentry_prompt_path: str,
    reentry_result_class: str,
    reentry_changed_files: list[str] | None,
    reentry_changed_files_count: int,
    reentry_stdout_path: str,
    reentry_stderr_path: str,
    reentry_result_path: str,
    reentry_git_diff_name_only_path: str,
    reentry_git_diff_numstat_path: str,
    reentry_exit_code: int,
    reentry_timed_out: bool,
    reentry_result_ready_for_assimilation: bool,
    reentry_result_assimilation_source: str,
    reentry_result_next_stage: str,
    reentry_human_review_required: bool,
    reentry_next_action: str,
    normal_write_execution_status: str,
    normal_write_result_status: str,
    normal_write_attempted: bool,
    normal_write_completed: bool,
    normal_write_prompt_kind: str,
    normal_write_prompt_path: str,
    normal_write_changed_files: list[str] | None,
    normal_write_changed_files_count: int,
    normal_write_stdout_path: str,
    normal_write_stderr_path: str,
    normal_write_result_path: str,
    normal_write_git_diff_name_only_path: str,
    normal_write_git_diff_numstat_path: str,
    normal_write_human_review_required: bool,
    fix_target_files: list[str] | None,
    next_target_files: list[str] | None,
    smoke_override_used: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "reentry_assimilation_completed_with_changes",
        "reentry_assimilation_completed_no_changes",
        "reentry_assimilation_completed_failure",
        "reentry_assimilation_completed_timeout",
        "blocked_reentry_invocation_not_ready",
        "blocked_ambiguous_write_sources",
        "blocked_human_review_required",
        "blocked_insufficient_assimilation_truth",
        "blocked_source_paths_unsafe",
        "blocked_forbidden_changed_files",
        "blocked_unexpected_changed_files",
        "blocked_too_many_changed_files",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "route_reentry_result_to_validation",
        "manual_review_required",
        "generate_fix_prompt",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    allowed_prompt_paths = {
        "/tmp/codex-local-runner-decision/generated_fix_prompt.txt",
        "/tmp/codex-local-runner-decision/generated_next_prompt.txt",
    }
    allowed_artifact_paths = {
        "/tmp/codex-local-runner-decision/codex_write_invocation_stdout.txt",
        "/tmp/codex-local-runner-decision/codex_write_invocation_stderr.txt",
        "/tmp/codex-local-runner-decision/codex_write_invocation_result.json",
        "/tmp/codex-local-runner-decision/codex_write_git_diff_name_only.txt",
        "/tmp/codex-local-runner-decision/codex_write_git_diff_numstat.txt",
    }
    max_changed_files_threshold = 8
    runtime_posture = [
        "prompt181_reentry_result_assimilation",
        "authoritative_source_precedence",
        "no_source_merging",
        "metadata_only_routing",
        "no_codex_invocation",
        "no_validation_execution",
        "no_git_mutation",
    ]

    normalized_reentry_routing_status = _normalize_text(
        reentry_routing_status,
        default="insufficient_truth",
    )
    reentry_routing_active = bool(
        normalized_reentry_routing_status
        and normalized_reentry_routing_status != "insufficient_truth"
    )
    normalized_reentry_status = _normalize_text(reentry_status, default="insufficient_truth")
    normalized_reentry_result_class = _normalize_text(
        reentry_result_class,
        default="blocked",
    )
    normalized_reentry_prompt_kind = _normalize_text(reentry_prompt_kind, default="none")
    normalized_reentry_prompt_path = _normalize_text(reentry_prompt_path, default="")
    normalized_reentry_stdout_path = _normalize_text(reentry_stdout_path, default="")
    normalized_reentry_stderr_path = _normalize_text(reentry_stderr_path, default="")
    normalized_reentry_result_path = _normalize_text(reentry_result_path, default="")
    normalized_reentry_diff_name_only_path = _normalize_text(
        reentry_git_diff_name_only_path,
        default="",
    )
    normalized_reentry_diff_numstat_path = _normalize_text(
        reentry_git_diff_numstat_path,
        default="",
    )
    normalized_normal_write_result_status = _normalize_text(
        normal_write_result_status,
        default="insufficient_truth",
    )
    normalized_normal_write_prompt_kind = _normalize_text(
        normal_write_prompt_kind,
        default="none",
    )
    normalized_normal_write_prompt_path = _normalize_text(normal_write_prompt_path, default="")
    normalized_normal_write_stdout_path = _normalize_text(normal_write_stdout_path, default="")
    normalized_normal_write_stderr_path = _normalize_text(normal_write_stderr_path, default="")
    normalized_normal_write_result_path = _normalize_text(normal_write_result_path, default="")
    normalized_normal_write_diff_name_only_path = _normalize_text(
        normal_write_git_diff_name_only_path,
        default="",
    )
    normalized_normal_write_diff_numstat_path = _normalize_text(
        normal_write_git_diff_numstat_path,
        default="",
    )
    normalized_reentry_changed_files = _normalize_string_list(reentry_changed_files or [])
    normalized_normal_changed_files = _normalize_string_list(normal_write_changed_files or [])
    normalized_reentry_changed_files_count = _as_non_negative_int(
        reentry_changed_files_count,
        default=len(normalized_reentry_changed_files),
    )
    normalized_normal_changed_files_count = _as_non_negative_int(
        normal_write_changed_files_count,
        default=len(normalized_normal_changed_files),
    )
    normalized_reentry_routing_block_reason = _normalize_text(
        reentry_routing_block_reason,
        default="",
    )
    normalized_reentry_invocation_block_reason = _normalize_text(
        reentry_invocation_block_reason,
        default="",
    )

    def _has_parent_traversal(path_text: str) -> bool:
        path_obj = PurePosixPath(path_text.replace("\\", "/"))
        return ".." in path_obj.parts

    def _validate_prompt_path(path_text: str) -> tuple[bool, str]:
        normalized_path = _normalize_text(path_text, default="")
        if not normalized_path:
            return False, "blocked_prompt_path_missing"
        if _has_parent_traversal(normalized_path):
            return False, "blocked_prompt_path_unexpected"
        if normalized_path not in allowed_prompt_paths:
            return False, "blocked_prompt_path_unexpected"
        path_obj = Path(normalized_path)
        if path_obj.is_symlink():
            return False, "blocked_prompt_path_symlink"
        if not path_obj.exists():
            return False, "blocked_prompt_path_missing"
        if not path_obj.is_file():
            return False, "blocked_prompt_path_not_file"
        try:
            size_bytes = _as_non_negative_int(path_obj.stat().st_size, default=0)
        except OSError:
            return False, "blocked_prompt_path_unreadable"
        if size_bytes <= 0:
            return False, "blocked_prompt_empty"
        if size_bytes > 20000:
            return False, "blocked_prompt_too_large"
        return True, ""

    def _validate_artifact_path(path_text: str) -> tuple[bool, str]:
        normalized_path = _normalize_text(path_text, default="")
        if not normalized_path:
            return False, "blocked_required_path_missing"
        if _has_parent_traversal(normalized_path):
            return False, "blocked_required_path_unexpected"
        if normalized_path not in allowed_artifact_paths:
            return False, "blocked_required_path_unexpected"
        path_obj = Path(normalized_path)
        if path_obj.is_symlink():
            return False, "blocked_required_path_symlink"
        if not path_obj.exists():
            return False, "blocked_required_path_missing"
        if not path_obj.is_file():
            return False, "blocked_required_path_not_file"
        return True, ""

    def _read_changed_files_from_diff(
        diff_name_only_path: str,
        diff_numstat_path: str,
    ) -> list[str]:
        normalized_name = _normalize_text(diff_name_only_path, default="")
        normalized_numstat = _normalize_text(diff_numstat_path, default="")
        changed_from_name: list[str] = []
        changed_from_numstat: list[str] = []
        if normalized_name in allowed_artifact_paths:
            name_path = Path(normalized_name)
            if name_path.exists() and not name_path.is_symlink():
                try:
                    changed_from_name = _serialize_required_signals(
                        name_path.read_text(encoding="utf-8").splitlines()
                    )
                except OSError:
                    changed_from_name = []
        if normalized_numstat in allowed_artifact_paths:
            num_path = Path(normalized_numstat)
            if num_path.exists() and not num_path.is_symlink():
                try:
                    for line in num_path.read_text(encoding="utf-8").splitlines():
                        parts = line.split("\t")
                        if len(parts) >= 3:
                            changed_from_numstat.append(parts[-1].strip())
                except OSError:
                    changed_from_numstat = []
        return (
            changed_from_name
            if changed_from_name
            else _serialize_required_signals(changed_from_numstat)
        )

    reentry_source_available = bool(
        reentry_invocation_attempted
        or reentry_invocation_completed
        or reentry_result_ready_for_assimilation
        or normalized_reentry_status
        in {
            "reentry_invocation_completed_with_changes",
            "reentry_invocation_completed_no_changes",
            "reentry_invocation_completed_failure",
            "reentry_invocation_completed_timeout",
        }
    )
    normal_write_source_available = bool(
        normal_write_attempted
        or normal_write_completed
        or normalized_normal_write_result_status
        in {
            "completed_with_changes",
            "completed_no_changes",
            "completed_failure",
            "completed_timeout",
        }
    )
    ambiguous_write_sources = bool(
        reentry_source_available
        and normal_write_source_available
        and not bool(reentry_result_ready_for_assimilation)
    )

    authoritative_source_kind = "none"
    authoritative_source_selected = False
    authoritative_source_block_reason = "blocked_insufficient_assimilation_truth"

    if bool(reentry_result_ready_for_assimilation):
        authoritative_source_kind = "reentry"
        authoritative_source_selected = True
        authoritative_source_block_reason = ""
    elif ambiguous_write_sources:
        authoritative_source_kind = "none"
        authoritative_source_selected = False
        authoritative_source_block_reason = "blocked_ambiguous_write_sources"
    elif reentry_routing_active:
        authoritative_source_kind = "none"
        authoritative_source_selected = False
        authoritative_source_block_reason = "blocked_reentry_invocation_not_ready"
    elif normal_write_source_available:
        authoritative_source_kind = "normal_write"
        authoritative_source_selected = True
        authoritative_source_block_reason = ""

    source_status = ""
    source_result_class = "blocked"
    source_prompt_kind = "none"
    source_prompt_path = ""
    source_stdout_path = ""
    source_stderr_path = ""
    source_result_path = ""
    source_git_diff_name_only_path = ""
    source_git_diff_numstat_path = ""
    source_changed_files: list[str] = []
    source_changed_files_count = 0
    selected_source_human_review_required = False
    selected_source_timed_out = False

    if authoritative_source_kind == "reentry":
        source_status = normalized_reentry_status
        source_result_class = normalized_reentry_result_class
        source_prompt_kind = normalized_reentry_prompt_kind
        source_prompt_path = normalized_reentry_prompt_path
        source_stdout_path = normalized_reentry_stdout_path
        source_stderr_path = normalized_reentry_stderr_path
        source_result_path = normalized_reentry_result_path
        source_git_diff_name_only_path = normalized_reentry_diff_name_only_path
        source_git_diff_numstat_path = normalized_reentry_diff_numstat_path
        source_changed_files = list(normalized_reentry_changed_files)
        source_changed_files_count = normalized_reentry_changed_files_count
        selected_source_human_review_required = bool(reentry_human_review_required)
        selected_source_timed_out = bool(reentry_timed_out)
    elif authoritative_source_kind == "normal_write":
        source_status = normalized_normal_write_result_status
        if normalized_normal_write_result_status == "completed_with_changes":
            source_result_class = "completed_with_changes"
        elif normalized_normal_write_result_status == "completed_no_changes":
            source_result_class = "completed_no_changes"
        elif normalized_normal_write_result_status == "completed_failure":
            source_result_class = "completed_failure"
        elif normalized_normal_write_result_status == "completed_timeout":
            source_result_class = "completed_timeout"
        else:
            source_result_class = "blocked"
        source_prompt_kind = normalized_normal_write_prompt_kind
        source_prompt_path = normalized_normal_write_prompt_path
        source_stdout_path = normalized_normal_write_stdout_path
        source_stderr_path = normalized_normal_write_stderr_path
        source_result_path = normalized_normal_write_result_path
        source_git_diff_name_only_path = normalized_normal_write_diff_name_only_path
        source_git_diff_numstat_path = normalized_normal_write_diff_numstat_path
        source_changed_files = list(normalized_normal_changed_files)
        source_changed_files_count = normalized_normal_changed_files_count
        selected_source_human_review_required = bool(normal_write_human_review_required)
        selected_source_timed_out = bool(
            normalized_normal_write_result_status == "completed_timeout"
        )

    if not source_changed_files and authoritative_source_selected:
        source_changed_files = _read_changed_files_from_diff(
            source_git_diff_name_only_path,
            source_git_diff_numstat_path,
        )
        source_changed_files_count = max(source_changed_files_count, len(source_changed_files))

    expected_changed_files: list[str] = []
    normalized_fix_targets = _normalize_string_list(fix_target_files or [])
    normalized_next_targets = _normalize_string_list(next_target_files or [])
    if source_prompt_kind == "fix":
        expected_changed_files = list(normalized_fix_targets)
    elif source_prompt_kind == "next":
        expected_changed_files = list(normalized_next_targets)
    else:
        expected_changed_files = _serialize_required_signals(
            [*normalized_fix_targets, *normalized_next_targets]
        )
    if bool(smoke_override_used):
        expected_changed_files = _serialize_required_signals(
            [*expected_changed_files, "prompt167_workspace_write_smoke.txt"]
        )
    allowed_changed_files = list(expected_changed_files)
    allowed_changed_set = set(allowed_changed_files)

    def _is_forbidden_changed_file(path_text: str) -> bool:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            return False
        lowered = normalized_path.lower()
        if normalized_path.startswith("/") or normalized_path.startswith("../"):
            return True
        if normalized_path.startswith(".git/"):
            return True
        if normalized_path.startswith("prompts/context/") and normalized_path not in allowed_changed_set:
            return True
        if normalized_path.startswith("__pycache__/") or "/__pycache__/" in normalized_path:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered == ".env" or lowered.startswith(".env.") or "/.env" in lowered:
            return True
        if lowered.endswith(".pem") or lowered.endswith(".key"):
            return True
        if normalized_path.startswith("tmp/") or normalized_path.startswith(".cache/"):
            return True
        return False

    forbidden_changed_files = _serialize_required_signals(
        [path for path in source_changed_files if _is_forbidden_changed_file(path)]
    )
    unexpected_changed_files = _serialize_required_signals(
        [
            path
            for path in source_changed_files
            if path not in allowed_changed_set and path not in set(forbidden_changed_files)
        ]
    )
    too_many_changed_files = bool(source_changed_files_count > max_changed_files_threshold)

    safe_for_validation_routing = False
    validation_routing_candidate = False
    validation_routing_block_reason = "blocked_assimilation_not_safe"
    status = "blocked_insufficient_assimilation_truth"
    next_action = "manual_review_required"
    human_review_required = True
    reentry_assimilation_completed = False
    reentry_assimilation_failed = False
    missing_inputs: list[str] = []

    if selected_source_human_review_required:
        status = "blocked_human_review_required"
        human_review_required = True
        next_action = "manual_review_required"
        validation_routing_block_reason = "blocked_human_review_required"
    elif authoritative_source_block_reason == "blocked_ambiguous_write_sources":
        status = "blocked_ambiguous_write_sources"
        human_review_required = True
        next_action = "manual_review_required"
        validation_routing_block_reason = "blocked_not_completed"
    elif authoritative_source_block_reason == "blocked_reentry_invocation_not_ready":
        status = "blocked_reentry_invocation_not_ready"
        human_review_required = True
        next_action = "manual_review_required"
        validation_routing_block_reason = "blocked_not_completed"
    elif not authoritative_source_selected:
        status = "blocked_insufficient_assimilation_truth"
        human_review_required = True
        next_action = "manual_review_required"
        validation_routing_block_reason = "blocked_insufficient_truth"
        missing_inputs.append("authoritative_write_source")
    else:
        prompt_ok, prompt_reason = _validate_prompt_path(source_prompt_path)
        stdout_ok, stdout_reason = _validate_artifact_path(source_stdout_path)
        stderr_ok, stderr_reason = _validate_artifact_path(source_stderr_path)
        result_ok, result_reason = _validate_artifact_path(source_result_path)
        diff_name_ok, diff_name_reason = _validate_artifact_path(
            source_git_diff_name_only_path
        )
        diff_num_ok, diff_num_reason = _validate_artifact_path(
            source_git_diff_numstat_path
        )
        if not (
            prompt_ok
            and stdout_ok
            and stderr_ok
            and result_ok
            and diff_name_ok
            and diff_num_ok
        ):
            status = "blocked_source_paths_unsafe"
            human_review_required = True
            next_action = "manual_review_required"
            validation_routing_block_reason = "blocked_insufficient_truth"
            for reason in [
                prompt_reason,
                stdout_reason,
                stderr_reason,
                result_reason,
                diff_name_reason,
                diff_num_reason,
            ]:
                if reason:
                    missing_inputs.append(reason)
        elif source_result_class == "completed_timeout" or selected_source_timed_out:
            status = "reentry_assimilation_completed_timeout"
            human_review_required = True
            next_action = "manual_review_required"
            reentry_assimilation_completed = True
            reentry_assimilation_failed = True
            validation_routing_block_reason = "blocked_reentry_invocation_timeout"
        elif source_result_class == "completed_failure":
            status = "reentry_assimilation_completed_failure"
            human_review_required = False
            next_action = "generate_fix_prompt"
            reentry_assimilation_completed = True
            reentry_assimilation_failed = True
            validation_routing_block_reason = "blocked_reentry_invocation_failure"
        elif source_result_class == "completed_no_changes":
            status = "reentry_assimilation_completed_no_changes"
            human_review_required = True
            next_action = "manual_review_required"
            reentry_assimilation_completed = True
            reentry_assimilation_failed = False
            validation_routing_block_reason = "blocked_no_changed_files"
        elif source_result_class == "completed_with_changes":
            reentry_assimilation_completed = True
            if forbidden_changed_files:
                status = "blocked_forbidden_changed_files"
                human_review_required = True
                next_action = "manual_review_required"
                reentry_assimilation_failed = True
                validation_routing_block_reason = "blocked_forbidden_changed_files"
            elif unexpected_changed_files:
                status = "blocked_unexpected_changed_files"
                human_review_required = True
                next_action = "manual_review_required"
                reentry_assimilation_failed = True
                validation_routing_block_reason = "blocked_unexpected_changed_files"
            elif too_many_changed_files:
                status = "blocked_too_many_changed_files"
                human_review_required = True
                next_action = "manual_review_required"
                reentry_assimilation_failed = True
                validation_routing_block_reason = "blocked_too_many_changed_files"
            elif not source_changed_files:
                status = "reentry_assimilation_completed_no_changes"
                human_review_required = True
                next_action = "manual_review_required"
                reentry_assimilation_failed = False
                validation_routing_block_reason = "blocked_no_changed_files"
            else:
                status = "reentry_assimilation_completed_with_changes"
                human_review_required = False
                next_action = "route_reentry_result_to_validation"
                reentry_assimilation_failed = False
                safe_for_validation_routing = True
                validation_routing_candidate = True
                validation_routing_block_reason = ""
        else:
            status = "blocked_insufficient_assimilation_truth"
            human_review_required = True
            next_action = "manual_review_required"
            reentry_assimilation_failed = False
            validation_routing_block_reason = "blocked_insufficient_truth"
            missing_inputs.append("source_result_class")

    prompt170_compat_source_status = source_status if source_status else status
    prompt170_compat_result_class = "blocked"
    if safe_for_validation_routing:
        prompt170_compat_result_class = "expected_changes"
    elif status == "reentry_assimilation_completed_no_changes":
        prompt170_compat_result_class = "no_changes"
    elif status == "blocked_unexpected_changed_files":
        prompt170_compat_result_class = "unexpected_changes"
    elif status == "blocked_forbidden_changed_files":
        prompt170_compat_result_class = "forbidden_changes"
    elif status == "blocked_too_many_changed_files":
        prompt170_compat_result_class = "too_many_changes"
    elif status == "reentry_assimilation_completed_failure":
        prompt170_compat_result_class = "invocation_failure"
    elif status == "reentry_assimilation_completed_timeout":
        prompt170_compat_result_class = "invocation_timeout"
    elif status in {
        "blocked_reentry_invocation_not_ready",
        "blocked_ambiguous_write_sources",
        "blocked_human_review_required",
        "blocked_source_paths_unsafe",
    }:
        prompt170_compat_result_class = "blocked"
    elif status == "blocked_insufficient_assimilation_truth":
        prompt170_compat_result_class = "insufficient_truth"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_reentry_result_assimilation_status": status,
        "project_browser_autonomous_reentry_result_assimilation_authoritative_source_kind": (
            authoritative_source_kind
        ),
        "project_browser_autonomous_reentry_result_assimilation_authoritative_source_selected": bool(
            authoritative_source_selected
        ),
        "project_browser_autonomous_reentry_result_assimilation_authoritative_source_block_reason": (
            authoritative_source_block_reason
        ),
        "project_browser_autonomous_reentry_result_assimilation_reentry_source_available": bool(
            reentry_source_available
        ),
        "project_browser_autonomous_reentry_result_assimilation_reentry_source_selected": bool(
            authoritative_source_kind == "reentry" and authoritative_source_selected
        ),
        "project_browser_autonomous_reentry_result_assimilation_normal_write_source_available": bool(
            normal_write_source_available
        ),
        "project_browser_autonomous_reentry_result_assimilation_normal_write_source_selected": bool(
            authoritative_source_kind == "normal_write" and authoritative_source_selected
        ),
        "project_browser_autonomous_reentry_result_assimilation_ambiguous_write_sources": bool(
            ambiguous_write_sources
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_status": source_status,
        "project_browser_autonomous_reentry_result_assimilation_source_result_class": (
            source_result_class
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_prompt_kind": (
            source_prompt_kind
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_prompt_path": (
            source_prompt_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_stdout_path": (
            source_stdout_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_stderr_path": (
            source_stderr_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_result_path": (
            source_result_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_git_diff_name_only_path": (
            source_git_diff_name_only_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_git_diff_numstat_path": (
            source_git_diff_numstat_path
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_changed_files": (
            source_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_source_changed_files_count": int(
            source_changed_files_count
        ),
        "project_browser_autonomous_reentry_result_assimilation_expected_changed_files": (
            expected_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_allowed_changed_files": (
            allowed_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_unexpected_changed_files": (
            unexpected_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_forbidden_changed_files": (
            forbidden_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_too_many_changed_files": bool(
            too_many_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_safe_for_validation_routing": bool(
            safe_for_validation_routing
        ),
        "project_browser_autonomous_reentry_result_assimilation_validation_routing_candidate": bool(
            validation_routing_candidate
        ),
        "project_browser_autonomous_reentry_result_assimilation_validation_routing_block_reason": (
            validation_routing_block_reason
        ),
        "project_browser_autonomous_reentry_result_assimilation_prompt170_compat_source_status": (
            prompt170_compat_source_status
        ),
        "project_browser_autonomous_reentry_result_assimilation_prompt170_compat_result_class": (
            prompt170_compat_result_class
        ),
        "project_browser_autonomous_reentry_result_assimilation_prompt170_compat_changed_files": (
            source_changed_files
        ),
        "project_browser_autonomous_reentry_result_assimilation_prompt170_compat_safe_for_validation_routing": bool(
            safe_for_validation_routing
        ),
        "project_browser_autonomous_reentry_result_assimilation_prompt170_compat_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_reentry_result_assimilation_reentry_assimilation_completed": bool(
            reentry_assimilation_completed
        ),
        "project_browser_autonomous_reentry_result_assimilation_reentry_assimilation_failed": bool(
            reentry_assimilation_failed
        ),
        "project_browser_autonomous_reentry_result_assimilation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_reentry_result_assimilation_next_action": next_action,
        "project_browser_autonomous_reentry_result_assimilation_runtime_posture": runtime_posture,
        "project_browser_autonomous_reentry_result_assimilation_missing_inputs": (
            _serialize_required_signals(
                [
                    *missing_inputs,
                    _normalize_text(normalized_reentry_routing_block_reason, default=""),
                    _normalize_text(normalized_reentry_invocation_block_reason, default=""),
                    _normalize_text(reentry_result_assimilation_source, default=""),
                    _normalize_text(reentry_result_next_stage, default=""),
                    _normalize_text(reentry_next_action, default=""),
                    _normalize_text(normal_write_execution_status, default=""),
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_reentry_safety_refresh_state(
    *,
    repository_path: str,
    source_assimilation_status: str,
    source_authoritative_kind: str,
    source_authoritative_selected: bool,
    source_authoritative_block_reason: str,
    source_result_class: str,
    source_status: str,
    source_prompt_kind: str,
    source_prompt_path: str,
    source_changed_files: list[str] | None,
    source_changed_files_count: int,
    expected_changed_files: list[str] | None,
    allowed_changed_files: list[str] | None,
    unexpected_changed_files: list[str] | None,
    forbidden_changed_files: list[str] | None,
    too_many_changed_files: bool,
    safe_for_validation_routing: bool,
    validation_routing_candidate: bool,
    validation_routing_block_reason: str,
    prompt170_compat_source_status: str,
    prompt170_compat_result_class: str,
    prompt170_compat_changed_files: list[str] | None,
    prompt170_compat_safe_for_validation_routing: bool,
    prompt170_compat_human_review_required: bool,
    source_human_review_required: bool,
    source_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_reentry_safety_refresh_validation_passed",
        "post_reentry_safety_refresh_validation_failed",
        "post_reentry_safety_refresh_validation_timeout",
        "post_reentry_safety_refresh_invocation_failure",
        "post_reentry_safety_refresh_invocation_timeout",
        "blocked_no_post_reentry_py_compile_candidates",
        "blocked_post_reentry_validation_routing",
        "blocked_post_reentry_unsafe_changes",
        "blocked_insufficient_post_reentry_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_bounded_continuation",
        "generate_fix_prompt",
        "manual_review_required",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt182_post_reentry_safety_refresh",
        "prompt181_precedence_consumption",
        "bounded_py_compile_only",
        "no_codex_invocation",
        "no_loop_start",
        "no_rollback_execution",
        "metadata_continuation_only",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_source_assimilation_status = _normalize_text(
        source_assimilation_status,
        default="insufficient_truth",
    )
    normalized_source_authoritative_kind = _normalize_text(
        source_authoritative_kind,
        default="none",
    )
    if normalized_source_authoritative_kind not in {"reentry", "normal_write", "none"}:
        normalized_source_authoritative_kind = "none"
    normalized_source_authoritative_selected = bool(source_authoritative_selected)
    normalized_source_authoritative_block_reason = _normalize_text(
        source_authoritative_block_reason,
        default="",
    )
    normalized_source_result_class = _normalize_text(source_result_class, default="blocked")
    normalized_source_status = _normalize_text(source_status, default="insufficient_truth")
    normalized_source_prompt_kind = _normalize_text(source_prompt_kind, default="none")
    if normalized_source_prompt_kind not in {"fix", "next", "none"}:
        normalized_source_prompt_kind = "none"
    normalized_source_prompt_path = _normalize_text(source_prompt_path, default="")
    normalized_source_changed_files = _normalize_string_list(source_changed_files or [])
    normalized_source_changed_files_count = _as_non_negative_int(
        source_changed_files_count,
        default=len(normalized_source_changed_files),
    )
    normalized_expected_changed_files = _normalize_string_list(expected_changed_files or [])
    normalized_allowed_changed_files = _normalize_string_list(allowed_changed_files or [])
    normalized_unexpected_changed_files = _normalize_string_list(
        unexpected_changed_files or []
    )
    normalized_forbidden_changed_files = _normalize_string_list(
        forbidden_changed_files or []
    )
    normalized_too_many_changed_files = bool(too_many_changed_files)
    normalized_safe_for_validation_routing = bool(safe_for_validation_routing)
    normalized_validation_routing_candidate = bool(validation_routing_candidate)
    normalized_validation_routing_block_reason = _normalize_text(
        validation_routing_block_reason,
        default="",
    )
    normalized_prompt170_compat_source_status = _normalize_text(
        prompt170_compat_source_status,
        default="insufficient_truth",
    )
    normalized_prompt170_compat_result_class = _normalize_text(
        prompt170_compat_result_class,
        default="insufficient_truth",
    )
    normalized_prompt170_compat_changed_files = _normalize_string_list(
        prompt170_compat_changed_files or []
    )
    normalized_prompt170_compat_safe_for_validation_routing = bool(
        prompt170_compat_safe_for_validation_routing
    )
    normalized_prompt170_compat_human_review_required = bool(
        prompt170_compat_human_review_required
    )
    normalized_source_human_review_required = bool(source_human_review_required)
    normalized_source_next_action = _normalize_text(source_next_action, default="")

    post_reentry_validation_routing_allowed = False
    post_reentry_validation_routing_block_reason = "blocked_post_reentry_validation_routing"
    post_reentry_validation_target_files: list[str] = []
    post_reentry_py_compile_candidate_files: list[str] = []
    post_reentry_validation_executed = False
    post_reentry_validation_passed = False
    post_reentry_validation_failed = False
    post_reentry_validation_timeout = False
    post_reentry_py_compile_results: list[dict[str, Any]] = []
    post_reentry_cycle_status = "post_reentry_cycle_blocked"
    post_reentry_cycle_passed = False
    post_reentry_cycle_failed = False
    post_reentry_cycle_blocked = True
    post_reentry_cycle_block_reason = "blocked_insufficient_post_reentry_truth"
    continuation_candidate = False
    continuation_prompt_kind = "none"
    continuation_next_action = "manual_review_required"
    rollback_candidate = False
    rollback_reason = ""
    human_review_required = True
    manual_review_required = True
    status = "blocked_insufficient_post_reentry_truth"
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    unsafe_changes = bool(
        normalized_forbidden_changed_files
        or normalized_unexpected_changed_files
        or normalized_too_many_changed_files
    )
    routing_precedence_allowed = bool(
        normalized_source_authoritative_kind == "reentry"
        and normalized_source_authoritative_selected
        and normalized_validation_routing_candidate
        and normalized_safe_for_validation_routing
        and not normalized_source_human_review_required
    )

    if unsafe_changes:
        status = "blocked_post_reentry_unsafe_changes"
        post_reentry_cycle_status = "post_reentry_cycle_blocked_unsafe_changes"
        post_reentry_cycle_blocked = True
        post_reentry_cycle_block_reason = "unsafe_post_reentry_changes"
        rollback_candidate = True
        rollback_reason = "unsafe_post_reentry_changes"
        human_review_required = True
        manual_review_required = True
        next_action = "manual_review_required"
        post_reentry_validation_routing_block_reason = "blocked_post_reentry_unsafe_changes"
    elif normalized_source_result_class == "completed_timeout":
        status = "post_reentry_safety_refresh_invocation_timeout"
        post_reentry_cycle_status = "post_reentry_cycle_blocked_invocation_timeout"
        post_reentry_cycle_blocked = True
        post_reentry_cycle_block_reason = "post_reentry_invocation_timeout"
        rollback_candidate = True
        rollback_reason = "post_reentry_invocation_timeout"
        human_review_required = True
        manual_review_required = True
        next_action = "manual_review_required"
        post_reentry_validation_routing_block_reason = "blocked_reentry_invocation_timeout"
    elif normalized_source_result_class == "completed_failure":
        status = "post_reentry_safety_refresh_invocation_failure"
        post_reentry_cycle_status = "post_reentry_cycle_failed_invocation"
        post_reentry_cycle_failed = True
        post_reentry_cycle_blocked = False
        post_reentry_cycle_block_reason = "post_reentry_invocation_failure"
        continuation_candidate = True
        continuation_prompt_kind = "fix"
        continuation_next_action = "generate_fix_prompt"
        rollback_candidate = True
        rollback_reason = "post_reentry_invocation_failure"
        human_review_required = False
        manual_review_required = False
        next_action = "generate_fix_prompt"
        post_reentry_validation_routing_block_reason = "blocked_reentry_invocation_failure"
    elif not routing_precedence_allowed:
        status = "blocked_post_reentry_validation_routing"
        post_reentry_cycle_status = "post_reentry_cycle_blocked_validation_routing"
        post_reentry_cycle_blocked = True
        post_reentry_cycle_block_reason = (
            normalized_validation_routing_block_reason
            or "blocked_post_reentry_validation_routing"
        )
        human_review_required = bool(
            normalized_source_human_review_required
            or normalized_prompt170_compat_human_review_required
        )
        manual_review_required = bool(human_review_required)
        next_action = (
            "manual_review_required"
            if human_review_required
            else "wait_for_more_truth"
        )
        post_reentry_validation_routing_block_reason = (
            normalized_validation_routing_block_reason
            or "blocked_post_reentry_validation_routing"
        )
        if not normalized_source_authoritative_selected:
            missing_inputs.append("authoritative_source_selected")
        if normalized_source_authoritative_kind != "reentry":
            missing_inputs.append("authoritative_source_kind_reentry")
        if not normalized_validation_routing_candidate:
            missing_inputs.append("validation_routing_candidate")
        if not normalized_safe_for_validation_routing:
            missing_inputs.append("safe_for_validation_routing")
    else:
        post_reentry_validation_routing_allowed = True
        post_reentry_validation_routing_block_reason = ""
        allowed_set = set(normalized_allowed_changed_files)
        expected_set = set(normalized_expected_changed_files)
        post_reentry_validation_target_files = sorted(
            set(
                path
                for path in normalized_source_changed_files
                if path in allowed_set or path in expected_set
            )
        )
        post_reentry_py_compile_candidate_files = sorted(
            [path for path in post_reentry_validation_target_files if path.endswith(".py")]
        )
        if not post_reentry_py_compile_candidate_files:
            status = "blocked_no_post_reentry_py_compile_candidates"
            post_reentry_cycle_status = "post_reentry_cycle_blocked_no_py_compile_candidates"
            post_reentry_cycle_blocked = True
            post_reentry_cycle_block_reason = "blocked_no_post_reentry_py_compile_candidates"
            human_review_required = True
            manual_review_required = True
            next_action = "manual_review_required"
        else:
            validation_state = _build_project_browser_autonomous_post_write_validation_execution_state(
                repository_path=normalized_repository_path,
                source_routing_status="validation_routing_allowed",
                source_validation_allowed=True,
                source_validation_block_reason="",
                validation_target_files=post_reentry_validation_target_files,
                py_compile_candidate_files=post_reentry_py_compile_candidate_files,
                targeted_test_candidate_files=[],
                human_review_required=False,
                source_next_action="run_post_write_validation",
            )
            validation_status = _normalize_text(
                validation_state.get(
                    "project_browser_autonomous_post_write_validation_execution_status"
                ),
                default="blocked_routing_not_allowed",
            )
            post_reentry_validation_executed = bool(
                validation_state.get(
                    "project_browser_autonomous_post_write_validation_execution_validation_executed",
                    False,
                )
            )
            post_reentry_validation_passed = bool(
                validation_state.get(
                    "project_browser_autonomous_post_write_validation_execution_validation_passed",
                    False,
                )
            )
            post_reentry_validation_failed = bool(
                validation_state.get(
                    "project_browser_autonomous_post_write_validation_execution_validation_failed",
                    False,
                )
            )
            post_reentry_validation_timeout = bool(validation_status == "validation_timeout")
            post_reentry_py_compile_results = list(
                validation_state.get(
                    "project_browser_autonomous_post_write_validation_execution_py_compile_results",
                    [],
                )
                if isinstance(
                    validation_state.get(
                        "project_browser_autonomous_post_write_validation_execution_py_compile_results",
                        [],
                    ),
                    list,
                )
                else []
            )

            if post_reentry_validation_passed:
                status = "post_reentry_safety_refresh_validation_passed"
                post_reentry_cycle_status = "post_reentry_cycle_passed"
                post_reentry_cycle_passed = True
                post_reentry_cycle_failed = False
                post_reentry_cycle_blocked = False
                post_reentry_cycle_block_reason = ""
                continuation_candidate = True
                continuation_prompt_kind = "next"
                continuation_next_action = "prepare_bounded_continuation"
                rollback_candidate = False
                rollback_reason = ""
                human_review_required = False
                manual_review_required = False
                next_action = "prepare_bounded_continuation"
            elif post_reentry_validation_timeout:
                status = "post_reentry_safety_refresh_validation_timeout"
                post_reentry_cycle_status = "post_reentry_cycle_blocked_validation_timeout"
                post_reentry_cycle_blocked = True
                post_reentry_cycle_block_reason = "post_reentry_validation_timeout"
                continuation_candidate = False
                rollback_candidate = True
                rollback_reason = "post_reentry_validation_timeout"
                human_review_required = True
                manual_review_required = True
                next_action = "manual_review_required"
            elif post_reentry_validation_failed:
                status = "post_reentry_safety_refresh_validation_failed"
                post_reentry_cycle_status = "post_reentry_cycle_failed_validation"
                post_reentry_cycle_failed = True
                post_reentry_cycle_blocked = False
                post_reentry_cycle_block_reason = "post_reentry_validation_failed"
                continuation_candidate = True
                continuation_prompt_kind = "fix"
                continuation_next_action = "generate_fix_prompt"
                rollback_candidate = True
                rollback_reason = "post_reentry_validation_failed"
                human_review_required = False
                manual_review_required = False
                next_action = "generate_fix_prompt"
            else:
                status = "blocked_insufficient_post_reentry_truth"
                post_reentry_cycle_status = "post_reentry_cycle_blocked_insufficient_truth"
                post_reentry_cycle_blocked = True
                post_reentry_cycle_block_reason = "blocked_insufficient_post_reentry_truth"
                human_review_required = True
                manual_review_required = True
                next_action = "manual_review_required"
                missing_inputs.append("post_reentry_validation_outcome")

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if continuation_prompt_kind not in {"fix", "next", "none"}:
        continuation_prompt_kind = "none"
    if continuation_next_action not in {
        "prepare_bounded_continuation",
        "generate_fix_prompt",
        "manual_review_required",
    }:
        continuation_next_action = "manual_review_required"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_post_reentry_safety_refresh_status": status,
        "project_browser_autonomous_post_reentry_safety_refresh_source_assimilation_status": (
            normalized_source_assimilation_status
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_source_authoritative_kind": (
            normalized_source_authoritative_kind
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_source_result_class": (
            normalized_source_result_class
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_source_changed_files": (
            normalized_source_changed_files
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_source_changed_files_count": int(
            normalized_source_changed_files_count
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_routing_allowed": bool(
            post_reentry_validation_routing_allowed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_routing_block_reason": (
            post_reentry_validation_routing_block_reason
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_target_files": (
            post_reentry_validation_target_files
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_py_compile_candidate_files": (
            post_reentry_py_compile_candidate_files
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_executed": bool(
            post_reentry_validation_executed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_passed": bool(
            post_reentry_validation_passed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_failed": bool(
            post_reentry_validation_failed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_validation_timeout": bool(
            post_reentry_validation_timeout
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_py_compile_results": (
            post_reentry_py_compile_results
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_cycle_status": (
            post_reentry_cycle_status
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_cycle_passed": bool(
            post_reentry_cycle_passed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_cycle_failed": bool(
            post_reentry_cycle_failed
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_cycle_blocked": bool(
            post_reentry_cycle_blocked
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_post_reentry_cycle_block_reason": (
            post_reentry_cycle_block_reason
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_continuation_candidate": bool(
            continuation_candidate
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_continuation_prompt_kind": (
            continuation_prompt_kind
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_continuation_next_action": (
            continuation_next_action
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_rollback_candidate": bool(
            rollback_candidate
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_rollback_reason": rollback_reason,
        "project_browser_autonomous_post_reentry_safety_refresh_manual_review_required": bool(
            manual_review_required
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_post_reentry_safety_refresh_next_action": next_action,
        "project_browser_autonomous_post_reentry_safety_refresh_runtime_posture": runtime_posture,
        "project_browser_autonomous_post_reentry_safety_refresh_missing_inputs": (
            _serialize_required_signals(
                [
                    *missing_inputs,
                    normalized_source_authoritative_block_reason,
                    normalized_prompt170_compat_source_status,
                    normalized_prompt170_compat_result_class,
                    normalized_source_next_action,
                    "prompt170_compat_safe"
                    if normalized_prompt170_compat_safe_for_validation_routing
                    else "",
                    "prompt170_compat_human_review"
                    if normalized_prompt170_compat_human_review_required
                    else "",
                    "prompt170_compat_changed_files"
                    if normalized_prompt170_compat_changed_files
                    else "",
                    normalized_source_prompt_path,
                    normalized_source_prompt_kind,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_bounded_continuation_controller_state(
    *,
    source_status: str,
    source_post_reentry_cycle_status: str,
    source_post_reentry_cycle_passed: bool,
    source_post_reentry_cycle_failed: bool,
    source_post_reentry_cycle_blocked: bool,
    source_post_reentry_cycle_block_reason: str,
    source_continuation_candidate: bool,
    source_continuation_prompt_kind: str,
    source_continuation_next_action: str,
    source_rollback_candidate: bool,
    source_rollback_reason: str,
    source_human_review_required: bool,
    source_manual_review_required: bool,
    source_next_action: str,
    reentry_invocation_attempted: bool,
    existing_cycle_index: int,
    existing_fix_attempt_index: int,
    existing_reentry_invocations_used: int,
    existing_failure_count: int,
) -> dict[str, Any]:
    allowed_statuses = {
        "continuation_allowed_next",
        "continuation_allowed_fix",
        "continuation_blocked_rollback_required",
        "continuation_blocked_manual_review_required",
        "continuation_blocked_cycle_budget_exhausted",
        "continuation_blocked_fix_budget_exhausted",
        "continuation_blocked_failure_budget_exhausted",
        "continuation_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "generate_next_prompt",
        "generate_fix_prompt",
        "prepare_rollback",
        "manual_review_required",
        "stop_bounded_continuation",
        "insufficient_truth",
    }
    max_cycles = 2
    max_fix_attempts = 1
    max_reentry_invocations = 1
    failure_budget = 1
    runtime_posture = [
        "prompt183_bounded_continuation_controller",
        "metadata_only_controller",
        "authoritative_prompt182_source",
        "no_prompt_generation",
        "no_codex_invocation",
        "no_cycle_start",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_source_status = _normalize_text(source_status, default="insufficient_truth")
    normalized_cycle_status = _normalize_text(
        source_post_reentry_cycle_status,
        default="insufficient_truth",
    )
    normalized_cycle_block_reason = _normalize_text(
        source_post_reentry_cycle_block_reason,
        default="",
    )
    normalized_continuation_prompt_kind = _normalize_text(
        source_continuation_prompt_kind,
        default="none",
    )
    if normalized_continuation_prompt_kind not in {"next", "fix", "none"}:
        normalized_continuation_prompt_kind = "none"
    normalized_continuation_next_action = _normalize_text(
        source_continuation_next_action,
        default="",
    )
    normalized_rollback_reason = _normalize_text(source_rollback_reason, default="")
    normalized_source_next_action = _normalize_text(source_next_action, default="")

    cycle_index = _as_non_negative_int(existing_cycle_index, default=1)
    if cycle_index <= 0:
        cycle_index = 1
    remaining_cycles = max(max_cycles - cycle_index, 0)

    fix_attempt_index = _as_non_negative_int(existing_fix_attempt_index, default=0)
    remaining_fix_attempts = max(max_fix_attempts - fix_attempt_index, 0)

    reentry_invocations_used = _as_non_negative_int(
        existing_reentry_invocations_used,
        default=1 if reentry_invocation_attempted else 0,
    )

    prompt182_failed = bool(source_post_reentry_cycle_failed) or bool(
        normalized_source_status
        in {
            "post_reentry_safety_refresh_validation_failed",
            "post_reentry_safety_refresh_invocation_failure",
        }
    )
    failure_count = _as_non_negative_int(
        existing_failure_count,
        default=1 if prompt182_failed else 0,
    )

    authoritative_continuation_source = (
        "project_browser_autonomous_post_reentry_safety_refresh"
        if normalized_source_status
        else "none"
    )
    continuation_allowed = False
    continuation_block_reason = "blocked_insufficient_continuation_truth"
    continuation_prompt_kind = "none"
    continuation_next_action = "manual_review_required"
    rollback_required = False
    rollback_candidate = bool(source_rollback_candidate)
    rollback_reason = normalized_rollback_reason
    should_generate_next_prompt = False
    should_generate_fix_prompt = False
    should_invoke_codex = False
    should_start_next_cycle = False
    should_rollback = False
    should_commit = False
    human_review_required = bool(source_human_review_required)
    manual_review_required = bool(source_manual_review_required)
    stop_reason = "insufficient_truth"
    next_action = "manual_review_required"
    status = "continuation_blocked_insufficient_truth"

    unsafe_or_timeout_source = bool(
        source_rollback_candidate
        or normalized_source_status
        in {
            "blocked_post_reentry_unsafe_changes",
            "post_reentry_safety_refresh_validation_timeout",
            "post_reentry_safety_refresh_invocation_timeout",
        }
    )
    if unsafe_or_timeout_source and not rollback_reason:
        rollback_reason = "post_reentry_rollback_required"

    # Priority 1: manual review
    if bool(source_human_review_required) or bool(source_manual_review_required):
        status = "continuation_blocked_manual_review_required"
        continuation_allowed = False
        continuation_block_reason = "manual_review_required"
        rollback_required = bool(source_rollback_candidate)
        stop_reason = "manual_review_required"
        next_action = "manual_review_required"
        human_review_required = True
        manual_review_required = True
    # Priority 2: rollback / unsafe / timeout
    elif unsafe_or_timeout_source:
        status = "continuation_blocked_rollback_required"
        continuation_allowed = False
        continuation_block_reason = "rollback_required"
        rollback_required = True
        rollback_candidate = True
        stop_reason = "rollback_required"
        next_action = "prepare_rollback"
        human_review_required = bool(source_human_review_required)
        manual_review_required = bool(source_manual_review_required)
    # Priority 3: budget exhaustion
    elif (
        normalized_continuation_prompt_kind == "next"
        and remaining_cycles <= 0
        and bool(source_continuation_candidate)
    ):
        status = "continuation_blocked_cycle_budget_exhausted"
        continuation_allowed = False
        continuation_block_reason = "cycle_budget_exhausted"
        stop_reason = "cycle_budget_exhausted"
        next_action = "stop_bounded_continuation"
        human_review_required = False
        manual_review_required = False
    elif (
        normalized_continuation_prompt_kind == "fix"
        and remaining_fix_attempts <= 0
        and bool(source_continuation_candidate)
    ):
        status = "continuation_blocked_fix_budget_exhausted"
        continuation_allowed = False
        continuation_block_reason = "fix_budget_exhausted"
        rollback_candidate = True
        rollback_reason = "fix_budget_exhausted"
        stop_reason = "fix_budget_exhausted"
        next_action = "prepare_rollback"
        human_review_required = False
        manual_review_required = False
    elif failure_count > failure_budget:
        status = "continuation_blocked_failure_budget_exhausted"
        continuation_allowed = False
        continuation_block_reason = "failure_budget_exhausted"
        rollback_candidate = True
        rollback_reason = "failure_budget_exhausted"
        stop_reason = "failure_budget_exhausted"
        next_action = "prepare_rollback"
        human_review_required = False
        manual_review_required = False
    # Priority 4: next continuation allowed
    elif (
        bool(source_post_reentry_cycle_passed)
        and bool(source_continuation_candidate)
        and normalized_continuation_prompt_kind == "next"
        and not bool(source_human_review_required)
        and not bool(source_rollback_candidate)
        and remaining_cycles > 0
    ):
        status = "continuation_allowed_next"
        continuation_allowed = True
        continuation_block_reason = ""
        continuation_prompt_kind = "next"
        continuation_next_action = (
            "generate_next_prompt"
            if normalized_continuation_next_action != "generate_next_prompt"
            else normalized_continuation_next_action
        )
        should_generate_next_prompt = True
        should_generate_fix_prompt = False
        rollback_required = False
        rollback_candidate = False
        rollback_reason = ""
        human_review_required = False
        manual_review_required = False
        stop_reason = ""
        next_action = "generate_next_prompt"
    # Priority 5: fix continuation allowed
    elif (
        bool(source_post_reentry_cycle_failed)
        and bool(source_continuation_candidate)
        and normalized_continuation_prompt_kind == "fix"
        and not bool(source_human_review_required)
        and remaining_fix_attempts > 0
        and failure_count <= failure_budget
    ):
        status = "continuation_allowed_fix"
        continuation_allowed = True
        continuation_block_reason = ""
        continuation_prompt_kind = "fix"
        continuation_next_action = (
            "generate_fix_prompt"
            if normalized_continuation_next_action != "generate_fix_prompt"
            else normalized_continuation_next_action
        )
        should_generate_next_prompt = False
        should_generate_fix_prompt = True
        rollback_required = False
        human_review_required = False
        manual_review_required = False
        stop_reason = ""
        next_action = "generate_fix_prompt"
    # Priority 6: fallback insufficient truth
    else:
        status = "continuation_blocked_insufficient_truth"
        continuation_allowed = False
        continuation_block_reason = "blocked_insufficient_continuation_truth"
        continuation_prompt_kind = (
            normalized_continuation_prompt_kind
            if normalized_continuation_prompt_kind in {"fix", "next"}
            else "none"
        )
        continuation_next_action = (
            normalized_continuation_next_action
            if normalized_continuation_next_action
            else normalized_source_next_action
        )
        human_review_required = True
        manual_review_required = True
        stop_reason = "insufficient_truth"
        next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if continuation_next_action not in {
        "generate_next_prompt",
        "generate_fix_prompt",
        "prepare_rollback",
        "manual_review_required",
        "stop_bounded_continuation",
        "",
    }:
        continuation_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_bounded_continuation_controller_status": status,
        "project_browser_autonomous_bounded_continuation_controller_authoritative_continuation_source": (
            authoritative_continuation_source
        ),
        "project_browser_autonomous_bounded_continuation_controller_continuation_allowed": bool(
            continuation_allowed
        ),
        "project_browser_autonomous_bounded_continuation_controller_continuation_block_reason": (
            continuation_block_reason
        ),
        "project_browser_autonomous_bounded_continuation_controller_continuation_prompt_kind": (
            continuation_prompt_kind
        ),
        "project_browser_autonomous_bounded_continuation_controller_continuation_next_action": (
            continuation_next_action
        ),
        "project_browser_autonomous_bounded_continuation_controller_max_cycles": int(max_cycles),
        "project_browser_autonomous_bounded_continuation_controller_cycle_index": int(
            cycle_index
        ),
        "project_browser_autonomous_bounded_continuation_controller_remaining_cycles": int(
            remaining_cycles
        ),
        "project_browser_autonomous_bounded_continuation_controller_max_fix_attempts": int(
            max_fix_attempts
        ),
        "project_browser_autonomous_bounded_continuation_controller_fix_attempt_index": int(
            fix_attempt_index
        ),
        "project_browser_autonomous_bounded_continuation_controller_remaining_fix_attempts": int(
            remaining_fix_attempts
        ),
        "project_browser_autonomous_bounded_continuation_controller_max_reentry_invocations": int(
            max_reentry_invocations
        ),
        "project_browser_autonomous_bounded_continuation_controller_reentry_invocations_used": int(
            reentry_invocations_used
        ),
        "project_browser_autonomous_bounded_continuation_controller_failure_budget": int(
            failure_budget
        ),
        "project_browser_autonomous_bounded_continuation_controller_failure_count": int(
            failure_count
        ),
        "project_browser_autonomous_bounded_continuation_controller_rollback_required": bool(
            rollback_required
        ),
        "project_browser_autonomous_bounded_continuation_controller_rollback_candidate": bool(
            rollback_candidate
        ),
        "project_browser_autonomous_bounded_continuation_controller_rollback_reason": (
            rollback_reason
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_generate_next_prompt": bool(
            should_generate_next_prompt
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_generate_fix_prompt": bool(
            should_generate_fix_prompt
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_start_next_cycle": bool(
            should_start_next_cycle
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_rollback": bool(
            should_rollback
        ),
        "project_browser_autonomous_bounded_continuation_controller_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_bounded_continuation_controller_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_bounded_continuation_controller_manual_review_required": bool(
            manual_review_required
        ),
        "project_browser_autonomous_bounded_continuation_controller_stop_reason": stop_reason,
        "project_browser_autonomous_bounded_continuation_controller_next_action": next_action,
        "project_browser_autonomous_bounded_continuation_controller_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_bounded_continuation_controller_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_source_status,
                    normalized_cycle_status,
                    normalized_cycle_block_reason,
                    normalized_source_next_action,
                    "authoritative_source_missing"
                    if authoritative_continuation_source == "none"
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_rollback_readiness_state(
    *,
    repository_path: str,
    continuation_status: str,
    continuation_rollback_required: bool,
    continuation_rollback_candidate: bool,
    continuation_rollback_reason: str,
    continuation_allowed: bool,
    continuation_block_reason: str,
    continuation_stop_reason: str,
    continuation_human_review_required: bool,
    continuation_manual_review_required: bool,
    continuation_next_action: str,
    post_reentry_cycle_status: str,
    post_reentry_cycle_block_reason: str,
    post_reentry_rollback_candidate: bool,
    post_reentry_rollback_reason: str,
    source_changed_files: list[str] | None,
    source_changed_files_count: int,
    expected_changed_files: list[str] | None,
    allowed_changed_files: list[str] | None,
    unexpected_changed_files: list[str] | None,
    forbidden_changed_files: list[str] | None,
    too_many_changed_files: bool,
    reentry_assimilation_source_changed_files: list[str] | None,
    reentry_assimilation_source_changed_files_count: int,
    reentry_assimilation_authoritative_source_kind: str,
    reentry_assimilation_authoritative_source_selected: bool,
    reentry_invocation_status: str,
    reentry_invocation_attempted: bool,
    reentry_invocation_completed: bool,
    reentry_invocation_changed_files_after: list[str] | None,
    normal_write_result_status: str,
    normal_write_result_changed_files_after: list[str] | None,
) -> dict[str, Any]:
    allowed_statuses = {
        "rollback_readiness_allowed",
        "rollback_readiness_not_required",
        "rollback_readiness_blocked_manual_review",
        "rollback_readiness_blocked_no_targets",
        "rollback_readiness_blocked_forbidden_files",
        "rollback_readiness_blocked_unsafe_files",
        "rollback_readiness_blocked_symlink_files",
        "rollback_readiness_blocked_out_of_repo_files",
        "rollback_readiness_blocked_ambiguous_sources",
        "rollback_readiness_blocked_too_many_files",
        "rollback_readiness_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_strategies = {
        "restore_tracked_only",
        "restore_tracked_and_remove_safe_untracked",
        "blocked_manual_review",
    }
    runtime_posture = [
        "prompt184_rollback_readiness_controller",
        "metadata_only",
        "no_rollback_execution",
        "no_git_reset_clean_checkout_restore",
        "no_file_deletion_execution",
        "no_codex_invocation",
        "no_commit",
    ]
    max_rollback_file_count = 20

    normalized_repo = _normalize_text(repository_path, default="")
    normalized_continuation_status = _normalize_text(
        continuation_status,
        default="insufficient_truth",
    )
    normalized_continuation_next_action = _normalize_text(
        continuation_next_action,
        default="insufficient_truth",
    )
    normalized_continuation_block_reason = _normalize_text(
        continuation_block_reason,
        default="",
    )
    normalized_continuation_stop_reason = _normalize_text(
        continuation_stop_reason,
        default="",
    )
    normalized_continuation_rollback_reason = _normalize_text(
        continuation_rollback_reason,
        default="",
    )
    normalized_post_reentry_cycle_status = _normalize_text(
        post_reentry_cycle_status,
        default="insufficient_truth",
    )
    normalized_post_reentry_cycle_block_reason = _normalize_text(
        post_reentry_cycle_block_reason,
        default="",
    )
    normalized_post_reentry_rollback_reason = _normalize_text(
        post_reentry_rollback_reason,
        default="",
    )
    normalized_expected_changed_files = _normalize_string_list(expected_changed_files or [])
    normalized_allowed_changed_files = _normalize_string_list(allowed_changed_files or [])
    normalized_unexpected_changed_files = _normalize_string_list(
        unexpected_changed_files or []
    )
    normalized_forbidden_changed_files = _normalize_string_list(forbidden_changed_files or [])
    normalized_source_changed_files = _normalize_string_list(source_changed_files or [])
    normalized_source_changed_files_count = _as_non_negative_int(
        source_changed_files_count,
        default=len(normalized_source_changed_files),
    )
    normalized_assimilation_changed_files = _normalize_string_list(
        reentry_assimilation_source_changed_files or []
    )
    normalized_assimilation_changed_files_count = _as_non_negative_int(
        reentry_assimilation_source_changed_files_count,
        default=len(normalized_assimilation_changed_files),
    )
    normalized_reentry_changed_files = _normalize_string_list(
        reentry_invocation_changed_files_after or []
    )
    normalized_normal_write_changed_files = _normalize_string_list(
        normal_write_result_changed_files_after or []
    )
    normalized_reentry_authoritative_kind = _normalize_text(
        reentry_assimilation_authoritative_source_kind,
        default="none",
    )
    normalized_reentry_status = _normalize_text(
        reentry_invocation_status,
        default="insufficient_truth",
    )
    normalized_normal_write_status = _normalize_text(
        normal_write_result_status,
        default="insufficient_truth",
    )

    rollback_requested = bool(
        continuation_rollback_required
        or continuation_rollback_candidate
        or post_reentry_rollback_candidate
    )
    rollback_reason = (
        normalized_continuation_rollback_reason
        or normalized_post_reentry_rollback_reason
        or normalized_post_reentry_cycle_block_reason
        or normalized_continuation_block_reason
        or normalized_continuation_stop_reason
    )
    continuation_path_requires_rollback = bool(
        rollback_requested
        and not bool(continuation_allowed)
        and normalized_continuation_next_action in {"prepare_rollback"}
    )
    if not rollback_reason and rollback_requested:
        rollback_reason = "post_reentry_rollback_required"

    reentry_source_active = bool(
        normalized_reentry_authoritative_kind == "reentry"
        or bool(reentry_assimilation_authoritative_source_selected)
        or bool(reentry_invocation_attempted)
        or bool(reentry_invocation_completed)
        or normalized_reentry_status
        in {
            "reentry_invocation_completed_with_changes",
            "reentry_invocation_completed_no_changes",
            "reentry_invocation_completed_failure",
            "reentry_invocation_completed_timeout",
        }
    )
    source_ambiguous = bool(
        reentry_source_active
        and normalized_reentry_authoritative_kind not in {"reentry", "none"}
    )

    rollback_target_files: list[str] = []
    if normalized_source_changed_files:
        rollback_target_files = list(normalized_source_changed_files)
    elif normalized_assimilation_changed_files:
        rollback_target_files = list(normalized_assimilation_changed_files)
    elif normalized_reentry_changed_files:
        rollback_target_files = list(normalized_reentry_changed_files)
    elif not reentry_source_active and normalized_normal_write_changed_files:
        rollback_target_files = list(normalized_normal_write_changed_files)

    rollback_target_files = sorted(set(_serialize_required_signals(rollback_target_files)))
    allowed_set = set(normalized_allowed_changed_files)
    expected_set = set(normalized_expected_changed_files)
    forbidden_set_from_source = set(normalized_forbidden_changed_files)
    unexpected_set_from_source = set(normalized_unexpected_changed_files)
    too_many_from_source = bool(too_many_changed_files)

    safe_untracked_runtime_paths = {
        "prompt167_workspace_write_smoke.txt",
    }
    sensitive_file_markers = (
        ".env",
        ".pem",
        ".key",
        "secret",
        "token",
        "credential",
    )

    repo_root: Path | None = None
    if normalized_repo:
        try:
            repo_root = Path(normalized_repo).resolve()
        except OSError:
            repo_root = None

    status_by_path: dict[str, str] = {}
    rollback_worktree_dirty = bool(normalized_source_changed_files_count > 0 or rollback_target_files)
    if normalized_repo:
        try:
            status_cp = _run_git(normalized_repo, ["status", "--short"], timeout_seconds=10.0)
            status_output = _normalize_text(status_cp.stdout, default="")
            rollback_worktree_dirty = bool(status_output)
            for line in status_output.splitlines():
                parsed_path = _normalize_text(_parse_git_status_path(line), default="")
                if parsed_path:
                    status_by_path[parsed_path] = line[:2]
        except (subprocess.TimeoutExpired, OSError):
            pass

    rollback_tracked_files: list[str] = []
    rollback_untracked_files: list[str] = []
    rollback_runtime_files: list[str] = []
    rollback_forbidden_files: list[str] = []
    rollback_unexpected_files: list[str] = []
    rollback_unsafe_files: list[str] = []
    rollback_missing_files: list[str] = []
    rollback_symlink_files: list[str] = []
    rollback_out_of_repo_files: list[str] = []
    missing_inputs: list[str] = []

    def _contains_parent_traversal(path_text: str) -> bool:
        return ".." in PurePosixPath(path_text.replace("\\", "/")).parts

    def _is_forbidden(path_text: str) -> bool:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        lowered = normalized_path.lower()
        if not normalized_path:
            return False
        if normalized_path.startswith(".git/"):
            return True
        if normalized_path.startswith("prompts/context/") and normalized_path not in allowed_set:
            return True
        if normalized_path.startswith("__pycache__/") or "/__pycache__/" in normalized_path:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered.startswith(".env") or "/.env" in lowered:
            return True
        if any(marker in lowered for marker in sensitive_file_markers):
            return True
        if normalized_path.startswith(".cache/") or normalized_path.startswith("tmp/"):
            return True
        return False

    for path_text in rollback_target_files:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            continue
        if normalized_path.startswith("/") or _contains_parent_traversal(normalized_path):
            rollback_out_of_repo_files.append(normalized_path)
            continue

        candidate_path = Path(normalized_repo, normalized_path) if normalized_repo else Path(normalized_path)
        if candidate_path.exists() and candidate_path.is_symlink():
            rollback_symlink_files.append(normalized_path)
            continue
        if repo_root is not None:
            try:
                resolved_candidate = candidate_path.resolve(strict=False)
                resolved_candidate.relative_to(repo_root)
            except (OSError, ValueError):
                rollback_out_of_repo_files.append(normalized_path)
                continue

        if _is_forbidden(normalized_path) or normalized_path in forbidden_set_from_source:
            rollback_forbidden_files.append(normalized_path)
            continue
        if normalized_path in unexpected_set_from_source:
            rollback_unexpected_files.append(normalized_path)
            continue

        status_code = _normalize_text(status_by_path.get(normalized_path), default="")
        is_untracked = bool(status_code == "??")
        is_runtime = bool(normalized_path in safe_untracked_runtime_paths)
        if is_runtime:
            rollback_runtime_files.append(normalized_path)

        if is_untracked:
            rollback_untracked_files.append(normalized_path)
            if not is_runtime:
                rollback_unsafe_files.append(normalized_path)
            continue

        if candidate_path.exists() and not candidate_path.is_file():
            rollback_unsafe_files.append(normalized_path)
            continue
        if not candidate_path.exists():
            rollback_missing_files.append(normalized_path)
            # Missing tracked file can still be restored from git checkout.
        rollback_tracked_files.append(normalized_path)

        if expected_set and normalized_path not in expected_set and normalized_path not in allowed_set:
            rollback_unexpected_files.append(normalized_path)

    rollback_forbidden_files = sorted(set(_serialize_required_signals(rollback_forbidden_files)))
    rollback_unexpected_files = sorted(set(_serialize_required_signals(rollback_unexpected_files)))
    rollback_unsafe_files = sorted(set(_serialize_required_signals(rollback_unsafe_files)))
    rollback_missing_files = sorted(set(_serialize_required_signals(rollback_missing_files)))
    rollback_symlink_files = sorted(set(_serialize_required_signals(rollback_symlink_files)))
    rollback_out_of_repo_files = sorted(
        set(_serialize_required_signals(rollback_out_of_repo_files))
    )
    rollback_tracked_files = sorted(set(_serialize_required_signals(rollback_tracked_files)))
    rollback_untracked_files = sorted(
        set(_serialize_required_signals(rollback_untracked_files))
    )
    rollback_runtime_files = sorted(set(_serialize_required_signals(rollback_runtime_files)))

    rollback_file_count = len(rollback_target_files)
    rollback_safe_worktree_state = bool(
        rollback_target_files
        and not rollback_forbidden_files
        and not rollback_unexpected_files
        and not rollback_unsafe_files
        and not rollback_symlink_files
        and not rollback_out_of_repo_files
        and not too_many_from_source
        and rollback_file_count <= max_rollback_file_count
    )

    rollback_strategy = "blocked_manual_review"
    rollback_execution_plan: list[str] = []
    rollback_readiness_allowed = False
    rollback_execution_allowed_next = False
    should_execute_rollback = False
    should_invoke_codex = False
    should_commit = False
    status = "rollback_readiness_blocked_insufficient_truth"
    rollback_readiness_block_reason = "blocked_insufficient_truth"
    human_review_required = bool(
        continuation_human_review_required or continuation_manual_review_required
    )
    next_action = "manual_review_required"

    if not rollback_requested:
        status = "rollback_readiness_not_required"
        rollback_readiness_block_reason = "rollback_not_required"
        rollback_reason = ""
        human_review_required = bool(
            continuation_human_review_required or continuation_manual_review_required
        )
        next_action = "no_rollback_required"
    elif not continuation_path_requires_rollback:
        status = "rollback_readiness_blocked_insufficient_truth"
        rollback_readiness_block_reason = "rollback_precondition_not_satisfied"
        human_review_required = True
        next_action = "manual_review_required"
    elif continuation_human_review_required or continuation_manual_review_required:
        status = "rollback_readiness_blocked_manual_review"
        rollback_readiness_block_reason = "manual_review_required"
        human_review_required = True
        next_action = "manual_review_required"
    elif source_ambiguous:
        status = "rollback_readiness_blocked_ambiguous_sources"
        rollback_readiness_block_reason = "ambiguous_file_source_truth"
        human_review_required = True
        next_action = "manual_review_required"
    elif not rollback_target_files:
        status = "rollback_readiness_blocked_no_targets"
        rollback_readiness_block_reason = "rollback_target_files_missing"
        human_review_required = True
        next_action = "manual_review_required"
    elif rollback_out_of_repo_files:
        status = "rollback_readiness_blocked_out_of_repo_files"
        rollback_readiness_block_reason = "out_of_repo_files_detected"
        human_review_required = True
        next_action = "manual_review_required"
    elif rollback_symlink_files:
        status = "rollback_readiness_blocked_symlink_files"
        rollback_readiness_block_reason = "symlink_files_detected"
        human_review_required = True
        next_action = "manual_review_required"
    elif rollback_forbidden_files:
        status = "rollback_readiness_blocked_forbidden_files"
        rollback_readiness_block_reason = "forbidden_files_detected"
        human_review_required = True
        next_action = "manual_review_required"
    elif rollback_unsafe_files or rollback_unexpected_files or too_many_from_source:
        status = (
            "rollback_readiness_blocked_too_many_files"
            if too_many_from_source or rollback_file_count > max_rollback_file_count
            else "rollback_readiness_blocked_unsafe_files"
        )
        rollback_readiness_block_reason = (
            "too_many_files"
            if status == "rollback_readiness_blocked_too_many_files"
            else "unsafe_or_unexpected_files_detected"
        )
        human_review_required = True
        next_action = "manual_review_required"
    elif rollback_file_count > max_rollback_file_count:
        status = "rollback_readiness_blocked_too_many_files"
        rollback_readiness_block_reason = "too_many_files"
        human_review_required = True
        next_action = "manual_review_required"
    else:
        rollback_readiness_allowed = True
        rollback_execution_allowed_next = True
        status = "rollback_readiness_allowed"
        rollback_readiness_block_reason = ""
        human_review_required = False
        next_action = "prepare_rollback_execution"

        if rollback_untracked_files and all(
            path in safe_untracked_runtime_paths for path in rollback_untracked_files
        ):
            rollback_strategy = "restore_tracked_and_remove_safe_untracked"
        else:
            rollback_strategy = "restore_tracked_only"

        for path_text in rollback_tracked_files:
            rollback_execution_plan.append(f"git checkout -- {path_text}")
        if rollback_strategy == "restore_tracked_and_remove_safe_untracked":
            for path_text in rollback_untracked_files:
                rollback_execution_plan.append(f"rm -f -- {path_text}")

    if rollback_strategy not in allowed_strategies:
        rollback_strategy = "blocked_manual_review"
    if status not in allowed_statuses:
        status = "insufficient_truth"
    if status.startswith("rollback_readiness_blocked") and not rollback_readiness_block_reason:
        rollback_readiness_block_reason = "blocked_insufficient_truth"

    missing_inputs = _serialize_required_signals(
        [
            "repository_path_missing" if not normalized_repo else "",
            "continuation_status_missing"
            if not normalized_continuation_status
            else "",
            "post_reentry_cycle_status_missing"
            if not normalized_post_reentry_cycle_status
            else "",
            "source_changed_files_missing"
            if rollback_requested and not rollback_target_files
            else "",
            "expected_changed_files_missing"
            if rollback_requested and not normalized_expected_changed_files
            else "",
            "allowed_changed_files_missing"
            if rollback_requested and not normalized_allowed_changed_files
            else "",
        ]
    )

    return {
        "project_browser_autonomous_rollback_readiness_status": status,
        "project_browser_autonomous_rollback_readiness_rollback_readiness_allowed": bool(
            rollback_readiness_allowed
        ),
        "project_browser_autonomous_rollback_readiness_rollback_readiness_block_reason": (
            rollback_readiness_block_reason
        ),
        "project_browser_autonomous_rollback_readiness_rollback_reason": rollback_reason,
        "project_browser_autonomous_rollback_readiness_rollback_strategy": (
            rollback_strategy
        ),
        "project_browser_autonomous_rollback_readiness_rollback_target_files": (
            rollback_target_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_tracked_files": (
            rollback_tracked_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_untracked_files": (
            rollback_untracked_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_runtime_files": (
            rollback_runtime_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_forbidden_files": (
            rollback_forbidden_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_unexpected_files": (
            rollback_unexpected_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_unsafe_files": (
            rollback_unsafe_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_missing_files": (
            rollback_missing_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_symlink_files": (
            rollback_symlink_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_out_of_repo_files": (
            rollback_out_of_repo_files
        ),
        "project_browser_autonomous_rollback_readiness_rollback_file_count": int(
            rollback_file_count
        ),
        "project_browser_autonomous_rollback_readiness_rollback_worktree_dirty": bool(
            rollback_worktree_dirty
        ),
        "project_browser_autonomous_rollback_readiness_rollback_safe_worktree_state": bool(
            rollback_safe_worktree_state
        ),
        "project_browser_autonomous_rollback_readiness_rollback_execution_plan": (
            rollback_execution_plan
        ),
        "project_browser_autonomous_rollback_readiness_rollback_execution_allowed_next": bool(
            rollback_execution_allowed_next
        ),
        "project_browser_autonomous_rollback_readiness_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_rollback_readiness_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_rollback_readiness_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_rollback_readiness_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_rollback_readiness_next_action": next_action,
        "project_browser_autonomous_rollback_readiness_runtime_posture": runtime_posture,
        "project_browser_autonomous_rollback_readiness_missing_inputs": missing_inputs,
    }


def _build_project_browser_autonomous_rollback_execution_state(
    *,
    repository_path: str,
    rollback_readiness_status: str,
    rollback_readiness_allowed: bool,
    rollback_readiness_block_reason: str,
    rollback_reason: str,
    rollback_strategy: str,
    rollback_target_files: list[str] | None,
    rollback_tracked_files: list[str] | None,
    rollback_untracked_files: list[str] | None,
    rollback_runtime_files: list[str] | None,
    rollback_forbidden_files: list[str] | None,
    rollback_unexpected_files: list[str] | None,
    rollback_unsafe_files: list[str] | None,
    rollback_missing_files: list[str] | None,
    rollback_symlink_files: list[str] | None,
    rollback_out_of_repo_files: list[str] | None,
    rollback_file_count: int,
    rollback_worktree_dirty: bool,
    rollback_safe_worktree_state: bool,
    rollback_execution_plan: list[str] | None,
    rollback_execution_allowed_next: bool,
    rollback_human_review_required: bool,
    rollback_readiness_next_action: str,
    continuation_human_review_required: bool,
    post_reentry_human_review_required: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "rollback_execution_completed",
        "rollback_execution_partial_failure",
        "rollback_execution_failed",
        "rollback_execution_timeout",
        "rollback_execution_blocked_not_allowed",
        "rollback_execution_blocked_manual_review",
        "rollback_execution_blocked_unsafe_plan",
        "rollback_execution_blocked_insufficient_truth",
        "rollback_execution_not_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt185_bounded_rollback_execution",
        "no_git_reset_hard",
        "no_git_clean_fd",
        "no_recursive_delete",
        "no_shell_expansion",
        "no_codex_invocation",
        "no_commit",
    ]
    allowed_safe_untracked_paths = {
        "prompt167_workspace_write_smoke.txt",
    }
    allowed_strategy_values = {
        "restore_tracked_only",
        "restore_tracked_and_remove_safe_untracked",
    }
    command_timeout_seconds = 15.0

    normalized_repo = _normalize_text(repository_path, default="")
    normalized_readiness_status = _normalize_text(
        rollback_readiness_status,
        default="insufficient_truth",
    )
    normalized_readiness_block_reason = _normalize_text(
        rollback_readiness_block_reason,
        default="",
    )
    normalized_rollback_reason = _normalize_text(rollback_reason, default="")
    normalized_strategy = _normalize_text(rollback_strategy, default="blocked_manual_review")
    normalized_target_files = _normalize_string_list(rollback_target_files or [])
    normalized_tracked_files = _normalize_string_list(rollback_tracked_files or [])
    normalized_untracked_files = _normalize_string_list(rollback_untracked_files or [])
    normalized_runtime_files = _normalize_string_list(rollback_runtime_files or [])
    normalized_forbidden_files = _normalize_string_list(rollback_forbidden_files or [])
    normalized_unexpected_files = _normalize_string_list(rollback_unexpected_files or [])
    normalized_unsafe_files = _normalize_string_list(rollback_unsafe_files or [])
    normalized_missing_files = _normalize_string_list(rollback_missing_files or [])
    normalized_symlink_files = _normalize_string_list(rollback_symlink_files or [])
    normalized_out_of_repo_files = _normalize_string_list(rollback_out_of_repo_files or [])
    normalized_execution_plan = _normalize_string_list(rollback_execution_plan or [])
    normalized_rollback_file_count = _as_non_negative_int(
        rollback_file_count,
        default=len(normalized_target_files),
    )
    normalized_readiness_next_action = _normalize_text(
        rollback_readiness_next_action,
        default="manual_review_required",
    )

    status = "rollback_execution_blocked_insufficient_truth"
    rollback_execution_allowed = False
    rollback_execution_attempted = False
    rollback_execution_completed = False
    rollback_execution_failed = False
    rollback_execution_block_reason = "blocked_insufficient_truth"
    rollback_restored_tracked_files: list[str] = []
    rollback_removed_untracked_files: list[str] = []
    rollback_skipped_files: list[str] = []
    rollback_failed_files: list[str] = []
    rollback_command_results: list[dict[str, Any]] = []
    rollback_commands_attempted = 0
    rollback_commands_completed = 0
    rollback_exit_code = 0
    rollback_timed_out = False
    pre_rollback_git_status_short = ""
    post_rollback_git_status_short = ""
    post_rollback_dirty = bool(rollback_worktree_dirty)
    post_rollback_expected_dirty_only = False
    human_review_required = bool(
        rollback_human_review_required
        or continuation_human_review_required
        or post_reentry_human_review_required
    )
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    def _contains_parent_traversal(path_text: str) -> bool:
        return ".." in PurePosixPath(path_text.replace("\\", "/")).parts

    def _is_sensitive_or_forbidden(path_text: str) -> bool:
        lowered = path_text.lower()
        if path_text.startswith(".git/"):
            return True
        if path_text.startswith("__pycache__/") or "/__pycache__/" in path_text:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered.startswith(".env") or "/.env" in lowered:
            return True
        if any(token in lowered for token in ("secret", "token", "credential", ".pem", ".key")):
            return True
        if path_text.startswith(".cache/") or path_text.startswith("tmp/"):
            return True
        return False

    repo_root: Path | None = None
    if normalized_repo:
        try:
            repo_root = Path(normalized_repo).resolve()
        except OSError:
            repo_root = None

    def _validate_repo_file(path_text: str, *, allow_missing: bool) -> tuple[bool, str]:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            return False, "path_missing"
        if normalized_path.startswith("/") or _contains_parent_traversal(normalized_path):
            return False, "path_out_of_repo"
        if _is_sensitive_or_forbidden(normalized_path):
            return False, "path_forbidden"
        if repo_root is None:
            return False, "repo_root_missing"
        candidate = (repo_root / normalized_path)
        if candidate.exists() and candidate.is_symlink():
            return False, "path_symlink"
        if candidate.exists() and candidate.is_dir():
            return False, "path_directory"
        try:
            resolved = candidate.resolve(strict=False)
            resolved.relative_to(repo_root)
        except (OSError, ValueError):
            return False, "path_out_of_repo"
        if not allow_missing and not candidate.exists():
            return False, "path_missing"
        return True, ""

    expected_plan: list[str] = []
    for path_text in normalized_tracked_files:
        expected_plan.append(f"git checkout -- {path_text}")
    if normalized_strategy == "restore_tracked_and_remove_safe_untracked":
        for path_text in normalized_untracked_files:
            expected_plan.append(f"rm -f -- {path_text}")

    if (
        normalized_readiness_status == "rollback_readiness_not_required"
        or normalized_readiness_block_reason == "rollback_not_required"
    ):
        status = "rollback_execution_not_required"
        rollback_execution_block_reason = "rollback_not_required"
        human_review_required = bool(
            continuation_human_review_required or post_reentry_human_review_required
        )
        next_action = "no_rollback_required"
    elif human_review_required:
        status = "rollback_execution_blocked_manual_review"
        rollback_execution_block_reason = "blocked_manual_review_required"
        next_action = "manual_review_required"
    elif not bool(rollback_execution_allowed_next) or not bool(rollback_readiness_allowed):
        status = "rollback_execution_blocked_not_allowed"
        rollback_execution_block_reason = (
            normalized_readiness_block_reason or "rollback_execution_not_allowed"
        )
        next_action = "manual_review_required"
    elif normalized_strategy not in allowed_strategy_values:
        status = "rollback_execution_blocked_unsafe_plan"
        rollback_execution_block_reason = "rollback_strategy_invalid"
        human_review_required = True
        next_action = "manual_review_required"
    elif not normalized_target_files:
        status = "rollback_execution_blocked_insufficient_truth"
        rollback_execution_block_reason = "rollback_target_files_missing"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_forbidden_files or normalized_unsafe_files or normalized_symlink_files or normalized_out_of_repo_files:
        status = "rollback_execution_blocked_unsafe_plan"
        rollback_execution_block_reason = "unsafe_rollback_file_set"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_rollback_file_count > 20:
        status = "rollback_execution_blocked_unsafe_plan"
        rollback_execution_block_reason = "rollback_file_count_exceeded"
        human_review_required = True
        next_action = "manual_review_required"
    elif not normalized_execution_plan or expected_plan != normalized_execution_plan:
        status = "rollback_execution_blocked_unsafe_plan"
        rollback_execution_block_reason = "nondeterministic_rollback_plan"
        human_review_required = True
        next_action = "manual_review_required"
    elif not rollback_safe_worktree_state:
        status = "rollback_execution_blocked_unsafe_plan"
        rollback_execution_block_reason = "rollback_worktree_state_not_safe"
        human_review_required = True
        next_action = "manual_review_required"
    elif not normalized_repo or repo_root is None:
        status = "rollback_execution_blocked_insufficient_truth"
        rollback_execution_block_reason = "repository_path_missing"
        missing_inputs.append("repository_path")
        human_review_required = True
        next_action = "manual_review_required"
    else:
        rollback_execution_allowed = True
        rollback_execution_attempted = True
        human_review_required = False
        next_action = "manual_review_required"
        try:
            pre_status_cp = _run_git(normalized_repo, ["status", "--short"], timeout_seconds=10.0)
            pre_rollback_git_status_short = _normalize_text(pre_status_cp.stdout, default="")
        except (subprocess.TimeoutExpired, OSError):
            pre_rollback_git_status_short = ""

        for tracked_path in normalized_tracked_files:
            valid, reason = _validate_repo_file(tracked_path, allow_missing=True)
            if not valid:
                rollback_failed_files.append(tracked_path)
                rollback_skipped_files.append(tracked_path)
                rollback_command_results.append(
                    {
                        "command": ["git", "checkout", "--", tracked_path],
                        "exit_code": 2,
                        "timed_out": False,
                        "status": "blocked",
                        "block_reason": reason,
                    }
                )
                rollback_exit_code = 1
                continue
            command = ["git", "-C", normalized_repo, "checkout", "--", tracked_path]
            rollback_commands_attempted += 1
            try:
                cp = subprocess.run(
                    command,
                    text=True,
                    capture_output=True,
                    timeout=command_timeout_seconds,
                    check=False,
                )
                command_exit = int(cp.returncode)
                command_ok = command_exit == 0
                if command_ok:
                    rollback_restored_tracked_files.append(tracked_path)
                    rollback_commands_completed += 1
                else:
                    rollback_failed_files.append(tracked_path)
                    rollback_exit_code = 1
                rollback_command_results.append(
                    {
                        "command": command,
                        "exit_code": command_exit,
                        "timed_out": False,
                        "status": "completed" if command_ok else "failed",
                        "stdout_excerpt": _normalize_text(cp.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(cp.stderr, default="")[:400],
                    }
                )
            except subprocess.TimeoutExpired as exc:
                rollback_timed_out = True
                rollback_failed_files.append(tracked_path)
                rollback_exit_code = 1
                rollback_command_results.append(
                    {
                        "command": command,
                        "exit_code": -1,
                        "timed_out": True,
                        "status": "timeout",
                        "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                    }
                )
            except OSError as exc:
                rollback_failed_files.append(tracked_path)
                rollback_exit_code = 1
                rollback_command_results.append(
                    {
                        "command": command,
                        "exit_code": -1,
                        "timed_out": False,
                        "status": "execution_error",
                        "stderr_excerpt": f"{type(exc).__name__}",
                    }
                )

        if normalized_strategy == "restore_tracked_and_remove_safe_untracked":
            for untracked_path in normalized_untracked_files:
                valid, reason = _validate_repo_file(untracked_path, allow_missing=True)
                if not valid:
                    rollback_failed_files.append(untracked_path)
                    rollback_skipped_files.append(untracked_path)
                    rollback_exit_code = 1
                    rollback_command_results.append(
                        {
                            "command": ["unlink", untracked_path],
                            "exit_code": 2,
                            "timed_out": False,
                            "status": "blocked",
                            "block_reason": reason,
                        }
                    )
                    continue
                if untracked_path not in allowed_safe_untracked_paths or untracked_path not in normalized_runtime_files:
                    rollback_failed_files.append(untracked_path)
                    rollback_skipped_files.append(untracked_path)
                    rollback_exit_code = 1
                    rollback_command_results.append(
                        {
                            "command": ["unlink", untracked_path],
                            "exit_code": 2,
                            "timed_out": False,
                            "status": "blocked",
                            "block_reason": "untracked_path_not_safe_runtime",
                        }
                    )
                    continue
                candidate = repo_root / untracked_path
                if candidate.exists():
                    if candidate.is_symlink() or candidate.is_dir():
                        rollback_failed_files.append(untracked_path)
                        rollback_skipped_files.append(untracked_path)
                        rollback_exit_code = 1
                        rollback_command_results.append(
                            {
                                "command": ["unlink", untracked_path],
                                "exit_code": 2,
                                "timed_out": False,
                                "status": "blocked",
                                "block_reason": "unsafe_unlink_target",
                            }
                        )
                        continue
                    rollback_commands_attempted += 1
                    try:
                        candidate.unlink()
                        rollback_removed_untracked_files.append(untracked_path)
                        rollback_commands_completed += 1
                        rollback_command_results.append(
                            {
                                "command": ["unlink", untracked_path],
                                "exit_code": 0,
                                "timed_out": False,
                                "status": "completed",
                            }
                        )
                    except OSError as exc:
                        rollback_failed_files.append(untracked_path)
                        rollback_exit_code = 1
                        rollback_command_results.append(
                            {
                                "command": ["unlink", untracked_path],
                                "exit_code": -1,
                                "timed_out": False,
                                "status": "execution_error",
                                "stderr_excerpt": f"{type(exc).__name__}",
                            }
                        )
                else:
                    rollback_skipped_files.append(untracked_path)
                    rollback_command_results.append(
                        {
                            "command": ["unlink", untracked_path],
                            "exit_code": 0,
                            "timed_out": False,
                            "status": "skipped_missing",
                        }
                    )

        try:
            post_status_cp = _run_git(normalized_repo, ["status", "--short"], timeout_seconds=10.0)
            post_rollback_git_status_short = _normalize_text(post_status_cp.stdout, default="")
        except (subprocess.TimeoutExpired, OSError):
            post_rollback_git_status_short = ""
            rollback_exit_code = 1

        post_rollback_dirty = bool(post_rollback_git_status_short)
        pre_paths = {
            _normalize_text(_parse_git_status_path(line), default="")
            for line in pre_rollback_git_status_short.splitlines()
        }
        pre_paths.discard("")
        post_paths = {
            _normalize_text(_parse_git_status_path(line), default="")
            for line in post_rollback_git_status_short.splitlines()
        }
        post_paths.discard("")
        target_set = set(normalized_target_files)
        post_rollback_expected_dirty_only = bool(
            all((path in pre_paths and path not in target_set) for path in post_paths)
        )
        target_paths_remaining_dirty = bool(any(path in post_paths for path in target_set))

        if rollback_timed_out:
            status = "rollback_execution_timeout"
            rollback_execution_failed = True
            rollback_execution_completed = False
            rollback_execution_block_reason = "rollback_timeout"
            human_review_required = True
            next_action = "manual_review_required"
            rollback_exit_code = 1
        elif rollback_failed_files:
            status = (
                "rollback_execution_partial_failure"
                if rollback_restored_tracked_files or rollback_removed_untracked_files
                else "rollback_execution_failed"
            )
            rollback_execution_failed = True
            rollback_execution_completed = False
            rollback_execution_block_reason = "rollback_command_failed"
            human_review_required = True
            next_action = "manual_review_required"
            rollback_exit_code = 1
        elif target_paths_remaining_dirty or not post_rollback_expected_dirty_only:
            status = "rollback_execution_partial_failure"
            rollback_execution_failed = True
            rollback_execution_completed = False
            rollback_execution_block_reason = "post_rollback_unexpected_dirty"
            human_review_required = True
            next_action = "manual_review_required"
            rollback_exit_code = 1
        else:
            status = "rollback_execution_completed"
            rollback_execution_completed = True
            rollback_execution_failed = False
            rollback_execution_block_reason = ""
            human_review_required = False
            next_action = "rollback_completed"
            rollback_exit_code = 0

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if status.startswith("rollback_execution_blocked") and not rollback_execution_block_reason:
        rollback_execution_block_reason = "blocked_insufficient_truth"

    return {
        "project_browser_autonomous_rollback_execution_status": status,
        "project_browser_autonomous_rollback_execution_rollback_execution_allowed": bool(
            rollback_execution_allowed
        ),
        "project_browser_autonomous_rollback_execution_rollback_execution_attempted": bool(
            rollback_execution_attempted
        ),
        "project_browser_autonomous_rollback_execution_rollback_execution_completed": bool(
            rollback_execution_completed
        ),
        "project_browser_autonomous_rollback_execution_rollback_execution_failed": bool(
            rollback_execution_failed
        ),
        "project_browser_autonomous_rollback_execution_rollback_execution_block_reason": (
            rollback_execution_block_reason
        ),
        "project_browser_autonomous_rollback_execution_rollback_reason": (
            normalized_rollback_reason
        ),
        "project_browser_autonomous_rollback_execution_rollback_strategy": normalized_strategy,
        "project_browser_autonomous_rollback_execution_rollback_target_files": (
            normalized_target_files
        ),
        "project_browser_autonomous_rollback_execution_rollback_tracked_files": (
            normalized_tracked_files
        ),
        "project_browser_autonomous_rollback_execution_rollback_untracked_files": (
            normalized_untracked_files
        ),
        "project_browser_autonomous_rollback_execution_rollback_runtime_files": (
            normalized_runtime_files
        ),
        "project_browser_autonomous_rollback_execution_rollback_restored_tracked_files": (
            _serialize_required_signals(rollback_restored_tracked_files)
        ),
        "project_browser_autonomous_rollback_execution_rollback_removed_untracked_files": (
            _serialize_required_signals(rollback_removed_untracked_files)
        ),
        "project_browser_autonomous_rollback_execution_rollback_skipped_files": (
            _serialize_required_signals(rollback_skipped_files)
        ),
        "project_browser_autonomous_rollback_execution_rollback_failed_files": (
            _serialize_required_signals(rollback_failed_files)
        ),
        "project_browser_autonomous_rollback_execution_rollback_command_results": (
            rollback_command_results
        ),
        "project_browser_autonomous_rollback_execution_rollback_commands_attempted": int(
            rollback_commands_attempted
        ),
        "project_browser_autonomous_rollback_execution_rollback_commands_completed": int(
            rollback_commands_completed
        ),
        "project_browser_autonomous_rollback_execution_rollback_exit_code": int(
            rollback_exit_code
        ),
        "project_browser_autonomous_rollback_execution_rollback_timed_out": bool(
            rollback_timed_out
        ),
        "project_browser_autonomous_rollback_execution_pre_rollback_git_status_short": (
            pre_rollback_git_status_short
        ),
        "project_browser_autonomous_rollback_execution_post_rollback_git_status_short": (
            post_rollback_git_status_short
        ),
        "project_browser_autonomous_rollback_execution_post_rollback_dirty": bool(
            post_rollback_dirty
        ),
        "project_browser_autonomous_rollback_execution_post_rollback_expected_dirty_only": bool(
            post_rollback_expected_dirty_only
        ),
        "project_browser_autonomous_rollback_execution_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_rollback_execution_next_action": next_action,
        "project_browser_autonomous_rollback_execution_runtime_posture": runtime_posture,
        "project_browser_autonomous_rollback_execution_missing_inputs": (
            _serialize_required_signals(
                [
                    *missing_inputs,
                    normalized_readiness_status,
                    normalized_readiness_next_action,
                    normalized_readiness_block_reason,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_rollback_result_assimilation_state(
    *,
    rollback_execution_status: str,
    rollback_execution_allowed: bool,
    rollback_execution_attempted: bool,
    rollback_execution_completed: bool,
    rollback_execution_failed: bool,
    rollback_execution_block_reason: str,
    rollback_reason: str,
    rollback_strategy: str,
    rollback_target_files: list[str] | None,
    rollback_restored_tracked_files: list[str] | None,
    rollback_removed_untracked_files: list[str] | None,
    rollback_skipped_files: list[str] | None,
    rollback_failed_files: list[str] | None,
    rollback_command_results: list[dict[str, Any]] | None,
    rollback_commands_attempted: int,
    rollback_commands_completed: int,
    rollback_exit_code: int,
    rollback_timed_out: bool,
    pre_rollback_git_status_short: str,
    post_rollback_git_status_short: str,
    post_rollback_dirty: bool,
    post_rollback_expected_dirty_only: bool,
    rollback_execution_human_review_required: bool,
    rollback_execution_next_action: str,
    rollback_readiness_status: str,
    rollback_readiness_allowed: bool,
    rollback_readiness_block_reason: str,
    rollback_readiness_next_action: str,
    continuation_status: str,
    continuation_next_action: str,
    post_reentry_status: str,
    post_reentry_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "rollback_result_assimilation_completed_clean",
        "rollback_result_assimilation_completed_expected_dirty",
        "rollback_result_assimilation_partial_failure",
        "rollback_result_assimilation_failed",
        "rollback_result_assimilation_timeout",
        "rollback_result_assimilation_unexpected_dirty",
        "rollback_result_assimilation_not_required",
        "rollback_result_assimilation_blocked_insufficient_truth",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt186_rollback_result_assimilation",
        "metadata_only",
        "no_rollback_execution",
        "no_codex_invocation",
        "no_prompt_generation",
        "no_commit",
    ]

    normalized_rollback_execution_status = _normalize_text(
        rollback_execution_status,
        default="insufficient_truth",
    )
    normalized_rollback_execution_block_reason = _normalize_text(
        rollback_execution_block_reason,
        default="",
    )
    normalized_rollback_reason = _normalize_text(rollback_reason, default="")
    normalized_rollback_strategy = _normalize_text(
        rollback_strategy,
        default="blocked_manual_review",
    )
    normalized_pre_status_short = _normalize_text(pre_rollback_git_status_short, default="")
    normalized_post_status_short = _normalize_text(post_rollback_git_status_short, default="")
    normalized_rollback_execution_next_action = _normalize_text(
        rollback_execution_next_action,
        default="manual_review_required",
    )
    normalized_rollback_readiness_status = _normalize_text(
        rollback_readiness_status,
        default="insufficient_truth",
    )
    normalized_rollback_readiness_block_reason = _normalize_text(
        rollback_readiness_block_reason,
        default="",
    )
    normalized_rollback_readiness_next_action = _normalize_text(
        rollback_readiness_next_action,
        default="manual_review_required",
    )
    normalized_continuation_status = _normalize_text(
        continuation_status,
        default="insufficient_truth",
    )
    normalized_continuation_next_action = _normalize_text(
        continuation_next_action,
        default="insufficient_truth",
    )
    normalized_post_reentry_status = _normalize_text(
        post_reentry_status,
        default="insufficient_truth",
    )
    normalized_post_reentry_next_action = _normalize_text(
        post_reentry_next_action,
        default="insufficient_truth",
    )

    normalized_rollback_target_files = _normalize_string_list(rollback_target_files or [])
    normalized_restored_tracked_files = _normalize_string_list(
        rollback_restored_tracked_files or []
    )
    normalized_removed_untracked_files = _normalize_string_list(
        rollback_removed_untracked_files or []
    )
    normalized_skipped_files = _normalize_string_list(rollback_skipped_files or [])
    normalized_failed_files = _normalize_string_list(rollback_failed_files or [])
    normalized_command_results = (
        rollback_command_results if isinstance(rollback_command_results, list) else []
    )

    rollback_remaining_dirty_files = _serialize_required_signals(
        [
            _normalize_text(_parse_git_status_path(line), default="")
            for line in normalized_post_status_short.splitlines()
        ]
    )

    status = "rollback_result_assimilation_blocked_insufficient_truth"
    rollback_result_available = False
    rollback_result_selected = False
    rollback_result_class = "blocked"
    rollback_result_block_reason = "blocked_insufficient_rollback_result_truth"
    rollback_completed_cleanly = False
    rollback_completed_with_expected_dirty = False
    rollback_partial_failure = False
    rollback_failed = False
    rollback_timeout = False
    safe_to_continue_after_rollback = False
    safe_to_commit_after_rollback = False
    should_generate_fix_prompt = False
    should_generate_next_prompt = False
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False
    should_stop = True
    stop_reason = "insufficient_rollback_result_truth"
    human_review_required = True
    next_action = "manual_review_required"

    if normalized_rollback_execution_status == "rollback_execution_not_required":
        status = "rollback_result_assimilation_not_required"
        rollback_result_available = False
        rollback_result_selected = False
        rollback_result_class = "not_required"
        rollback_result_block_reason = "rollback_not_required"
        should_stop = False
        stop_reason = ""
        human_review_required = False
        next_action = "no_rollback_required"
    elif normalized_rollback_execution_status in {
        "rollback_execution_completed",
        "rollback_execution_partial_failure",
        "rollback_execution_failed",
        "rollback_execution_timeout",
    }:
        rollback_result_available = True
        rollback_result_selected = True
        rollback_result_block_reason = ""

        if bool(rollback_timed_out) or normalized_rollback_execution_status == "rollback_execution_timeout":
            status = "rollback_result_assimilation_timeout"
            rollback_result_class = "timeout"
            rollback_timeout = True
            rollback_failed = True
            should_stop = True
            stop_reason = "rollback_timeout"
            human_review_required = True
            next_action = "manual_review_required"
        elif normalized_rollback_execution_status == "rollback_execution_partial_failure":
            status = "rollback_result_assimilation_partial_failure"
            rollback_result_class = "partial_failure"
            rollback_partial_failure = True
            rollback_failed = True
            should_stop = True
            stop_reason = "rollback_partial_failure"
            human_review_required = True
            next_action = "manual_review_required"
        elif normalized_rollback_execution_status == "rollback_execution_failed" or bool(
            rollback_execution_failed
        ):
            status = "rollback_result_assimilation_failed"
            rollback_result_class = "failed"
            rollback_failed = True
            should_stop = True
            stop_reason = "rollback_failed"
            human_review_required = True
            next_action = "manual_review_required"
        elif bool(post_rollback_dirty) and not bool(post_rollback_expected_dirty_only):
            status = "rollback_result_assimilation_unexpected_dirty"
            rollback_result_class = "unexpected_dirty"
            rollback_failed = True
            should_stop = True
            stop_reason = "unexpected_dirty_after_rollback"
            human_review_required = True
            next_action = "manual_review_required"
        elif not bool(post_rollback_dirty):
            status = "rollback_result_assimilation_completed_clean"
            rollback_result_class = "completed_clean"
            rollback_completed_cleanly = True
            safe_to_continue_after_rollback = True
            safe_to_commit_after_rollback = False
            should_generate_fix_prompt = True
            should_stop = False
            stop_reason = ""
            human_review_required = False
            next_action = "generate_fix_prompt_after_rollback"
        else:
            status = "rollback_result_assimilation_completed_expected_dirty"
            rollback_result_class = "completed_expected_dirty"
            rollback_completed_with_expected_dirty = True
            safe_to_continue_after_rollback = True
            safe_to_commit_after_rollback = False
            should_generate_fix_prompt = True
            should_stop = False
            stop_reason = ""
            human_review_required = False
            next_action = "generate_fix_prompt_after_rollback"
    else:
        status = "rollback_result_assimilation_blocked_insufficient_truth"
        rollback_result_available = False
        rollback_result_selected = False
        rollback_result_class = "blocked"
        rollback_result_block_reason = "blocked_insufficient_rollback_result_truth"
        safe_to_continue_after_rollback = False
        safe_to_commit_after_rollback = False
        should_stop = True
        stop_reason = "insufficient_rollback_result_truth"
        human_review_required = True
        next_action = "manual_review_required"

    if rollback_execution_human_review_required and status not in {
        "rollback_result_assimilation_completed_clean",
        "rollback_result_assimilation_completed_expected_dirty",
        "rollback_result_assimilation_not_required",
    }:
        human_review_required = True

    if status not in allowed_statuses:
        status = "insufficient_truth"

    return {
        "project_browser_autonomous_rollback_result_assimilation_status": status,
        "project_browser_autonomous_rollback_result_assimilation_rollback_result_available": bool(
            rollback_result_available
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_result_selected": bool(
            rollback_result_selected
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_result_class": (
            rollback_result_class
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_result_block_reason": (
            rollback_result_block_reason
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_completed_cleanly": bool(
            rollback_completed_cleanly
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_completed_with_expected_dirty": bool(
            rollback_completed_with_expected_dirty
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_partial_failure": bool(
            rollback_partial_failure
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_failed": bool(
            rollback_failed
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_timeout": bool(
            rollback_timeout
        ),
        "project_browser_autonomous_rollback_result_assimilation_post_rollback_dirty": bool(
            post_rollback_dirty
        ),
        "project_browser_autonomous_rollback_result_assimilation_post_rollback_expected_dirty_only": bool(
            post_rollback_expected_dirty_only
        ),
        "project_browser_autonomous_rollback_result_assimilation_post_rollback_git_status_short": (
            normalized_post_status_short
        ),
        "project_browser_autonomous_rollback_result_assimilation_restored_tracked_files": (
            normalized_restored_tracked_files
        ),
        "project_browser_autonomous_rollback_result_assimilation_removed_untracked_files": (
            normalized_removed_untracked_files
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_failed_files": (
            normalized_failed_files
        ),
        "project_browser_autonomous_rollback_result_assimilation_rollback_remaining_dirty_files": (
            rollback_remaining_dirty_files
        ),
        "project_browser_autonomous_rollback_result_assimilation_safe_to_continue_after_rollback": bool(
            safe_to_continue_after_rollback
        ),
        "project_browser_autonomous_rollback_result_assimilation_safe_to_commit_after_rollback": bool(
            safe_to_commit_after_rollback
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_generate_fix_prompt": bool(
            should_generate_fix_prompt
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_generate_next_prompt": bool(
            should_generate_next_prompt
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_rollback_result_assimilation_should_stop": bool(
            should_stop
        ),
        "project_browser_autonomous_rollback_result_assimilation_stop_reason": stop_reason,
        "project_browser_autonomous_rollback_result_assimilation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_rollback_result_assimilation_next_action": next_action,
        "project_browser_autonomous_rollback_result_assimilation_runtime_posture": runtime_posture,
        "project_browser_autonomous_rollback_result_assimilation_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_rollback_execution_status,
                    normalized_rollback_execution_block_reason,
                    normalized_rollback_execution_next_action,
                    normalized_rollback_readiness_status,
                    normalized_rollback_readiness_block_reason,
                    normalized_rollback_readiness_next_action,
                    normalized_continuation_status,
                    normalized_continuation_next_action,
                    normalized_post_reentry_status,
                    normalized_post_reentry_next_action,
                    normalized_rollback_reason,
                    normalized_rollback_strategy,
                    str(_as_non_negative_int(rollback_commands_attempted, default=0)),
                    str(_as_non_negative_int(rollback_commands_completed, default=0)),
                    str(_as_int(rollback_exit_code, default=0)),
                    "rollback_target_files_missing"
                    if rollback_result_available and not normalized_rollback_target_files
                    else "",
                    "rollback_command_results_missing"
                    if rollback_result_available and not normalized_command_results
                    else "",
                    "pre_rollback_status_missing"
                    if rollback_result_available and not normalized_pre_status_short
                    else "",
                    "rollback_skipped_files_present"
                    if normalized_skipped_files
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_continuation_gate_state(
    *,
    rollback_result_status: str,
    rollback_result_available: bool,
    rollback_result_selected: bool,
    rollback_result_class: str,
    rollback_result_block_reason: str,
    rollback_completed_cleanly: bool,
    rollback_completed_with_expected_dirty: bool,
    rollback_partial_failure: bool,
    rollback_failed: bool,
    rollback_timeout: bool,
    post_rollback_dirty: bool,
    post_rollback_expected_dirty_only: bool,
    rollback_remaining_dirty_files: list[str] | None,
    safe_to_continue_after_rollback: bool,
    safe_to_commit_after_rollback: bool,
    rollback_should_generate_fix_prompt: bool,
    rollback_should_generate_next_prompt: bool,
    rollback_should_invoke_codex: bool,
    rollback_should_execute_rollback: bool,
    rollback_should_commit: bool,
    rollback_should_stop: bool,
    rollback_stop_reason: str,
    rollback_human_review_required: bool,
    rollback_next_action: str,
    remaining_fix_attempts: int,
    remaining_cycles: int,
    failure_budget: int,
    failure_count: int,
    continuation_human_review_required: bool,
    continuation_stop_reason: str,
    rollback_execution_status: str,
    post_reentry_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_continuation_allowed_fix",
        "post_rollback_continuation_blocked_manual_review",
        "post_rollback_continuation_blocked_fix_budget_exhausted",
        "post_rollback_continuation_blocked_failure_budget_exhausted",
        "post_rollback_continuation_not_required",
        "post_rollback_continuation_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "generate_fix_prompt_after_rollback",
        "manual_review_required",
        "no_rollback_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt187_post_rollback_continuation_gate",
        "metadata_only_controller",
        "authoritative_prompt186_source",
        "budget_gated_recovery",
        "no_prompt_generation",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_result_status = _normalize_text(rollback_result_status, default="insufficient_truth")
    normalized_result_class = _normalize_text(rollback_result_class, default="blocked")
    normalized_result_block_reason = _normalize_text(rollback_result_block_reason, default="")
    normalized_stop_reason = _normalize_text(rollback_stop_reason, default="")
    normalized_next_action = _normalize_text(rollback_next_action, default="manual_review_required")
    normalized_continuation_stop_reason = _normalize_text(continuation_stop_reason, default="")
    normalized_rollback_execution_status = _normalize_text(
        rollback_execution_status,
        default="insufficient_truth",
    )
    normalized_post_reentry_status = _normalize_text(
        post_reentry_status,
        default="insufficient_truth",
    )
    normalized_remaining_dirty_files = _normalize_string_list(
        rollback_remaining_dirty_files or []
    )

    normalized_remaining_fix_attempts = _as_non_negative_int(remaining_fix_attempts, default=0)
    normalized_remaining_cycles = _as_non_negative_int(remaining_cycles, default=0)
    normalized_failure_budget = _as_non_negative_int(failure_budget, default=1)
    normalized_failure_count = _as_non_negative_int(failure_count, default=0)

    fix_budget_available = normalized_remaining_fix_attempts > 0
    cycle_budget_available = normalized_remaining_cycles > 0
    failure_budget_available = normalized_failure_count <= normalized_failure_budget

    rollback_success = bool(rollback_completed_cleanly) or bool(
        rollback_completed_with_expected_dirty
    )
    unexpected_dirty_result = bool(
        normalized_result_status == "rollback_result_assimilation_unexpected_dirty"
        or (post_rollback_dirty and not post_rollback_expected_dirty_only)
    )
    hard_stop_unsafe_result = bool(
        rollback_partial_failure
        or rollback_failed
        or rollback_timeout
        or unexpected_dirty_result
        or rollback_human_review_required
        or continuation_human_review_required
    )

    status = "post_rollback_continuation_blocked_insufficient_truth"
    post_rollback_continuation_allowed = False
    post_rollback_continuation_block_reason = "blocked_insufficient_post_rollback_truth"
    post_rollback_continuation_kind = "none"
    post_rollback_next_action = "manual_review_required"
    should_generate_fix_prompt = False
    should_generate_next_prompt = False
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False
    should_stop = True
    human_review_required = True
    stop_reason = "insufficient_post_rollback_truth"
    next_action = "manual_review_required"

    # Priority 1: hard-stop unsafe rollback results
    if hard_stop_unsafe_result:
        status = "post_rollback_continuation_blocked_manual_review"
        post_rollback_continuation_allowed = False
        post_rollback_continuation_block_reason = (
            normalized_stop_reason or "rollback_result_not_safe"
        )
        post_rollback_continuation_kind = "none"
        post_rollback_next_action = "manual_review_required"
        should_stop = True
        human_review_required = True
        stop_reason = normalized_stop_reason or "rollback_result_not_safe"
        next_action = "manual_review_required"
    # Priority 2: no rollback required
    elif normalized_result_status == "rollback_result_assimilation_not_required":
        status = "post_rollback_continuation_not_required"
        post_rollback_continuation_allowed = False
        post_rollback_continuation_block_reason = "rollback_not_required"
        post_rollback_continuation_kind = "none"
        post_rollback_next_action = "no_rollback_required"
        should_stop = False
        human_review_required = False
        stop_reason = ""
        next_action = "no_rollback_required"
    # Priority 3: budget exhaustion
    elif rollback_success and not fix_budget_available:
        status = "post_rollback_continuation_blocked_fix_budget_exhausted"
        post_rollback_continuation_allowed = False
        post_rollback_continuation_block_reason = "fix_budget_exhausted_after_rollback"
        post_rollback_continuation_kind = "fix"
        post_rollback_next_action = "manual_review_required"
        should_stop = True
        human_review_required = True
        stop_reason = "fix_budget_exhausted_after_rollback"
        next_action = "manual_review_required"
    elif rollback_success and not failure_budget_available:
        status = "post_rollback_continuation_blocked_failure_budget_exhausted"
        post_rollback_continuation_allowed = False
        post_rollback_continuation_block_reason = (
            "failure_budget_exhausted_after_rollback"
        )
        post_rollback_continuation_kind = "fix"
        post_rollback_next_action = "manual_review_required"
        should_stop = True
        human_review_required = True
        stop_reason = "failure_budget_exhausted_after_rollback"
        next_action = "manual_review_required"
    # Priority 4: post-rollback fix continuation allowed
    elif (
        rollback_success
        and bool(safe_to_continue_after_rollback)
        and bool(rollback_should_generate_fix_prompt)
        and not bool(rollback_human_review_required)
        and fix_budget_available
        and failure_budget_available
    ):
        status = "post_rollback_continuation_allowed_fix"
        post_rollback_continuation_allowed = True
        post_rollback_continuation_block_reason = ""
        post_rollback_continuation_kind = "fix"
        post_rollback_next_action = "generate_fix_prompt_after_rollback"
        should_generate_fix_prompt = True
        should_generate_next_prompt = False
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        should_stop = False
        human_review_required = False
        stop_reason = ""
        next_action = "generate_fix_prompt_after_rollback"
    # Priority 5: insufficient truth
    else:
        status = "post_rollback_continuation_blocked_insufficient_truth"
        post_rollback_continuation_allowed = False
        post_rollback_continuation_block_reason = (
            "blocked_insufficient_post_rollback_truth"
        )
        post_rollback_continuation_kind = "none"
        post_rollback_next_action = "manual_review_required"
        should_generate_fix_prompt = False
        should_generate_next_prompt = False
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        should_stop = True
        human_review_required = True
        stop_reason = "insufficient_post_rollback_truth"
        next_action = "manual_review_required"

    # Prompt187 commit-safety invariant.
    should_commit = False
    safe_to_commit_after_rollback = False

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if post_rollback_next_action not in allowed_next_actions:
        post_rollback_next_action = next_action

    return {
        "project_browser_autonomous_post_rollback_continuation_gate_status": status,
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_continuation_allowed": bool(
            post_rollback_continuation_allowed
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_continuation_block_reason": (
            post_rollback_continuation_block_reason
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_continuation_kind": (
            post_rollback_continuation_kind
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_next_action": (
            post_rollback_next_action
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_source_rollback_result_status": (
            normalized_result_status
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_source_rollback_result_class": (
            normalized_result_class
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_rollback_completed_cleanly": bool(
            rollback_completed_cleanly
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_rollback_completed_with_expected_dirty": bool(
            rollback_completed_with_expected_dirty
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_rollback_failed": bool(
            rollback_failed
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_rollback_timeout": bool(
            rollback_timeout
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_dirty": bool(
            post_rollback_dirty
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_post_rollback_expected_dirty_only": bool(
            post_rollback_expected_dirty_only
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_remaining_fix_attempts": int(
            normalized_remaining_fix_attempts
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_remaining_cycles": int(
            normalized_remaining_cycles
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_failure_budget": int(
            normalized_failure_budget
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_failure_count": int(
            normalized_failure_count
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_fix_budget_available": bool(
            fix_budget_available
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_cycle_budget_available": bool(
            cycle_budget_available
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_failure_budget_available": bool(
            failure_budget_available
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_generate_fix_prompt": bool(
            should_generate_fix_prompt
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_generate_next_prompt": bool(
            should_generate_next_prompt
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_should_stop": bool(
            should_stop
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_safe_to_continue_after_rollback": bool(
            safe_to_continue_after_rollback
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_safe_to_commit_after_rollback": bool(
            safe_to_commit_after_rollback
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_stop_reason": (
            stop_reason
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_next_action": next_action,
        "project_browser_autonomous_post_rollback_continuation_gate_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_continuation_gate_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_result_status,
                    normalized_result_class,
                    normalized_result_block_reason,
                    normalized_next_action,
                    normalized_stop_reason,
                    normalized_continuation_stop_reason,
                    normalized_rollback_execution_status,
                    normalized_post_reentry_status,
                    "rollback_result_unavailable"
                    if not rollback_result_available
                    else "",
                    "rollback_result_not_selected"
                    if not rollback_result_selected
                    else "",
                    "rollback_should_stop"
                    if rollback_should_stop
                    else "",
                    "rollback_should_generate_next_prompt_true"
                    if rollback_should_generate_next_prompt
                    else "",
                    "rollback_should_invoke_codex_true"
                    if rollback_should_invoke_codex
                    else "",
                    "rollback_should_execute_true"
                    if rollback_should_execute_rollback
                    else "",
                    "rollback_should_commit_true"
                    if rollback_should_commit
                    else "",
                    "rollback_remaining_dirty_files"
                    if normalized_remaining_dirty_files
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_fix_handoff_state(
    *,
    post_rollback_status: str,
    post_rollback_continuation_allowed: bool,
    post_rollback_continuation_kind: str,
    post_rollback_next_action: str,
    rollback_completed_cleanly: bool,
    rollback_completed_with_expected_dirty: bool,
    safe_to_continue_after_rollback: bool,
    safe_to_commit_after_rollback: bool,
    remaining_fix_attempts: int,
    fix_budget_available: bool,
    cycle_budget_available: bool,
    failure_budget_available: bool,
    should_generate_fix_prompt: bool,
    should_generate_next_prompt: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_commit: bool,
    should_stop: bool,
    human_review_required: bool,
    stop_reason: str,
    next_action: str,
    source_rollback_result_class: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_fix_handoff_allowed",
        "post_rollback_fix_handoff_blocked",
        "post_rollback_fix_handoff_blocked_manual_review",
        "post_rollback_fix_handoff_blocked_budget_exhausted",
        "post_rollback_fix_handoff_blocked_not_allowed",
        "post_rollback_fix_handoff_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "generate_fix_prompt_after_rollback",
        "manual_review_required",
        "no_rollback_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt188_post_rollback_fix_handoff",
        "metadata_only_handoff",
        "connect_prompt187_to_fix_readiness_generation",
        "no_safety_bypass",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_post_rollback_status = _normalize_text(
        post_rollback_status,
        default="insufficient_truth",
    )
    normalized_post_rollback_kind = _normalize_text(
        post_rollback_continuation_kind,
        default="none",
    )
    if normalized_post_rollback_kind not in {"fix", "next", "none"}:
        normalized_post_rollback_kind = "none"
    normalized_post_rollback_next_action = _normalize_text(
        post_rollback_next_action,
        default="manual_review_required",
    )
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_next_action = _normalize_text(next_action, default="manual_review_required")
    normalized_source_rollback_result_class = _normalize_text(
        source_rollback_result_class,
        default="blocked",
    )
    normalized_remaining_fix_attempts = _as_non_negative_int(remaining_fix_attempts, default=0)

    status = "post_rollback_fix_handoff_blocked_insufficient_truth"
    post_rollback_fix_handoff_available = False
    post_rollback_fix_handoff_allowed = False
    post_rollback_fix_handoff_block_reason = "blocked_insufficient_post_rollback_truth"
    post_rollback_fix_prompt_kind = "none"
    post_rollback_fix_prompt_reason = ""
    fix_readiness_refresh_allowed = False
    fix_readiness_refresh_source = ""
    fix_generation_refresh_allowed = False
    fix_generation_refresh_source = ""
    computed_should_generate_fix_prompt = False
    computed_should_generate_next_prompt = False
    computed_should_invoke_codex = False
    computed_should_execute_rollback = False
    computed_should_commit = False
    computed_human_review_required = True
    computed_next_action = "manual_review_required"

    handoff_allow_rule = bool(
        normalized_post_rollback_status == "post_rollback_continuation_allowed_fix"
        and post_rollback_continuation_allowed
        and normalized_post_rollback_kind == "fix"
        and should_generate_fix_prompt
        and not should_generate_next_prompt
        and not should_invoke_codex
        and not should_execute_rollback
        and not should_commit
        and safe_to_continue_after_rollback
        and not safe_to_commit_after_rollback
        and fix_budget_available
        and failure_budget_available
        and not human_review_required
    )
    blocked_budget = bool(
        normalized_post_rollback_status
        in {
            "post_rollback_continuation_blocked_fix_budget_exhausted",
            "post_rollback_continuation_blocked_failure_budget_exhausted",
        }
        or (
            (rollback_completed_cleanly or rollback_completed_with_expected_dirty)
            and (not fix_budget_available or not failure_budget_available)
        )
    )
    blocked_manual_review = bool(
        human_review_required
        or normalized_post_rollback_status
        in {
            "post_rollback_continuation_blocked_manual_review",
            "post_rollback_continuation_blocked_not_allowed",
        }
    )
    blocked_not_allowed = bool(
        normalized_post_rollback_status == "post_rollback_continuation_not_required"
        or (
            not post_rollback_continuation_allowed
            and normalized_post_rollback_status not in {"insufficient_truth"}
            and not blocked_budget
            and not blocked_manual_review
        )
    )

    if handoff_allow_rule:
        status = "post_rollback_fix_handoff_allowed"
        post_rollback_fix_handoff_available = True
        post_rollback_fix_handoff_allowed = True
        post_rollback_fix_handoff_block_reason = ""
        post_rollback_fix_prompt_kind = "fix"
        post_rollback_fix_prompt_reason = "rollback_recovered_unsafe_change"
        fix_readiness_refresh_allowed = True
        fix_readiness_refresh_source = "post_rollback_continuation"
        fix_generation_refresh_allowed = True
        fix_generation_refresh_source = "post_rollback_continuation"
        computed_should_generate_fix_prompt = True
        computed_should_generate_next_prompt = False
        computed_should_invoke_codex = False
        computed_should_execute_rollback = False
        computed_should_commit = False
        computed_human_review_required = False
        computed_next_action = "generate_fix_prompt_after_rollback"
    elif blocked_manual_review:
        status = "post_rollback_fix_handoff_blocked_manual_review"
        post_rollback_fix_handoff_available = False
        post_rollback_fix_handoff_allowed = False
        post_rollback_fix_handoff_block_reason = (
            normalized_stop_reason or "manual_review_required"
        )
        computed_human_review_required = True
        computed_next_action = (
            normalized_next_action
            if normalized_next_action in allowed_next_actions
            else "manual_review_required"
        )
    elif blocked_budget:
        status = "post_rollback_fix_handoff_blocked_budget_exhausted"
        post_rollback_fix_handoff_available = False
        post_rollback_fix_handoff_allowed = False
        post_rollback_fix_handoff_block_reason = (
            "fix_or_failure_budget_exhausted_after_rollback"
        )
        computed_human_review_required = True
        computed_next_action = "manual_review_required"
    elif blocked_not_allowed:
        status = "post_rollback_fix_handoff_blocked_not_allowed"
        post_rollback_fix_handoff_available = False
        post_rollback_fix_handoff_allowed = False
        post_rollback_fix_handoff_block_reason = (
            "post_rollback_fix_continuation_not_allowed"
        )
        computed_human_review_required = bool(human_review_required)
        computed_next_action = (
            normalized_next_action
            if normalized_next_action in allowed_next_actions
            else "manual_review_required"
        )
    elif normalized_post_rollback_status in {"insufficient_truth", ""}:
        status = "post_rollback_fix_handoff_blocked_insufficient_truth"
        post_rollback_fix_handoff_available = False
        post_rollback_fix_handoff_allowed = False
        post_rollback_fix_handoff_block_reason = (
            "blocked_insufficient_post_rollback_truth"
        )
        computed_human_review_required = True
        computed_next_action = "manual_review_required"
    else:
        status = "post_rollback_fix_handoff_blocked"
        post_rollback_fix_handoff_available = False
        post_rollback_fix_handoff_allowed = False
        post_rollback_fix_handoff_block_reason = (
            normalized_stop_reason or "post_rollback_fix_handoff_blocked"
        )
        computed_human_review_required = bool(human_review_required)
        computed_next_action = (
            normalized_next_action
            if normalized_next_action in allowed_next_actions
            else "manual_review_required"
        )

    # Commit boundary invariant for rollback-derived handoff.
    computed_should_commit = False

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if computed_next_action not in allowed_next_actions:
        computed_next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_post_rollback_fix_handoff_status": status,
        "project_browser_autonomous_post_rollback_fix_handoff_post_rollback_fix_handoff_available": bool(
            post_rollback_fix_handoff_available
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_post_rollback_fix_handoff_allowed": bool(
            post_rollback_fix_handoff_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_post_rollback_fix_handoff_block_reason": (
            post_rollback_fix_handoff_block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_post_rollback_fix_prompt_kind": (
            post_rollback_fix_prompt_kind
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_post_rollback_fix_prompt_reason": (
            post_rollback_fix_prompt_reason
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_source_post_rollback_status": (
            normalized_post_rollback_status
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_source_rollback_result_class": (
            normalized_source_rollback_result_class
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_fix_readiness_refresh_allowed": bool(
            fix_readiness_refresh_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_fix_readiness_refresh_source": (
            fix_readiness_refresh_source
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_fix_generation_refresh_allowed": bool(
            fix_generation_refresh_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_fix_generation_refresh_source": (
            fix_generation_refresh_source
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_should_generate_fix_prompt": bool(
            computed_should_generate_fix_prompt
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_should_generate_next_prompt": bool(
            computed_should_generate_next_prompt
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_should_invoke_codex": bool(
            computed_should_invoke_codex
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_should_execute_rollback": bool(
            computed_should_execute_rollback
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_should_commit": bool(
            computed_should_commit
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_human_review_required": bool(
            computed_human_review_required
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_next_action": (
            computed_next_action
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_fix_handoff_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_post_rollback_status,
                    normalized_post_rollback_next_action,
                    normalized_post_rollback_kind,
                    normalized_stop_reason,
                    normalized_next_action,
                    normalized_source_rollback_result_class,
                    "remaining_fix_attempts_zero"
                    if normalized_remaining_fix_attempts <= 0
                    else "",
                    "fix_budget_unavailable" if not fix_budget_available else "",
                    "failure_budget_unavailable" if not failure_budget_available else "",
                    "cycle_budget_unavailable" if not cycle_budget_available else "",
                    "rollback_should_stop_true" if should_stop else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_fix_reentry_propagation_state(
    *,
    source_fix_generation_status: str,
    source_fix_prompt_generated: bool,
    source_fix_prompt_path: str,
    source_fix_prompt_handoff_write_completed: bool,
    source_fix_human_review_required: bool,
    source_fix_next_action: str,
    source_post_rollback_input_available: bool,
    source_post_rollback_input_consumed: bool,
    source_post_rollback_input_effective: bool,
    source_post_rollback_input_source: str,
    source_post_rollback_input_reason: str,
    source_post_rollback_refresh_applied: bool,
    post_rollback_handoff_allowed: bool,
    post_rollback_handoff_available: bool,
    post_rollback_handoff_prompt_kind: str,
    post_rollback_handoff_human_review_required: bool,
    post_rollback_handoff_should_generate_fix_prompt: bool,
    post_rollback_handoff_should_generate_next_prompt: bool,
    post_rollback_handoff_should_invoke_codex: bool,
    post_rollback_handoff_should_execute_rollback: bool,
    post_rollback_handoff_should_commit: bool,
    post_rollback_handoff_next_action: str,
    post_rollback_continuation_status: str,
    post_rollback_continuation_next_action: str,
    rollback_result_status: str,
    existing_reentry_readiness_status: str,
    existing_reentry_routing_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_fix_reentry_propagation_allowed",
        "post_rollback_fix_reentry_propagation_blocked",
        "post_rollback_fix_reentry_propagation_blocked_manual_review",
        "post_rollback_fix_reentry_propagation_blocked_unsafe_path",
        "post_rollback_fix_reentry_propagation_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_post_rollback_fix_reentry",
        "manual_review_required",
        "no_rollback_required",
        "insufficient_truth",
    }
    fix_allowed_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    max_prompt_size_bytes = 20000
    runtime_posture = [
        "prompt190_post_rollback_fix_reentry_propagation",
        "metadata_only_propagation",
        "reuse_existing_reentry_path",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_fix_generation_status = _normalize_text(
        source_fix_generation_status,
        default="insufficient_truth",
    )
    normalized_fix_prompt_path = _normalize_text(source_fix_prompt_path, default="")
    normalized_fix_next_action = _normalize_text(source_fix_next_action, default="")
    normalized_post_rollback_input_source = _normalize_text(
        source_post_rollback_input_source,
        default="",
    )
    normalized_post_rollback_input_reason = _normalize_text(
        source_post_rollback_input_reason,
        default="",
    )
    normalized_post_rollback_handoff_prompt_kind = _normalize_text(
        post_rollback_handoff_prompt_kind,
        default="none",
    )
    normalized_post_rollback_handoff_next_action = _normalize_text(
        post_rollback_handoff_next_action,
        default="manual_review_required",
    )
    normalized_post_rollback_continuation_status = _normalize_text(
        post_rollback_continuation_status,
        default="insufficient_truth",
    )
    normalized_post_rollback_continuation_next_action = _normalize_text(
        post_rollback_continuation_next_action,
        default="manual_review_required",
    )
    normalized_rollback_result_status = _normalize_text(
        rollback_result_status,
        default="insufficient_truth",
    )
    normalized_existing_reentry_readiness_status = _normalize_text(
        existing_reentry_readiness_status,
        default="insufficient_truth",
    )
    normalized_existing_reentry_routing_status = _normalize_text(
        existing_reentry_routing_status,
        default="insufficient_truth",
    )

    path_obj = Path(normalized_fix_prompt_path) if normalized_fix_prompt_path else None
    path_is_exact = normalized_fix_prompt_path == fix_allowed_path
    path_exists = bool(path_obj and path_obj.exists())
    path_is_file = bool(path_obj and path_obj.is_file())
    path_is_symlink = bool(path_obj and path_obj.is_symlink())
    file_size_bytes = 0
    if path_obj and path_exists and path_is_file and not path_is_symlink:
        try:
            file_size_bytes = _as_non_negative_int(path_obj.stat().st_size, default=0)
        except OSError:
            file_size_bytes = 0
    file_non_empty = file_size_bytes > 0
    file_too_large = file_size_bytes > max_prompt_size_bytes
    path_safe = bool(
        path_is_exact
        and path_exists
        and path_is_file
        and not path_is_symlink
        and file_non_empty
        and not file_too_large
    )

    manual_review_or_stop = bool(
        normalized_post_rollback_handoff_next_action == "manual_review_required"
        or normalized_post_rollback_continuation_next_action == "manual_review_required"
        or normalized_post_rollback_continuation_status
        in {
            "post_rollback_continuation_blocked_manual_review",
            "post_rollback_continuation_blocked_fix_budget_exhausted",
            "post_rollback_continuation_blocked_failure_budget_exhausted",
            "post_rollback_continuation_blocked_insufficient_truth",
        }
        or normalized_rollback_result_status
        in {
            "rollback_result_assimilation_partial_failure",
            "rollback_result_assimilation_failed",
            "rollback_result_assimilation_timeout",
            "rollback_result_assimilation_unexpected_dirty",
            "rollback_result_assimilation_blocked_insufficient_truth",
        }
    )

    allow_rule = bool(
        source_post_rollback_input_effective
        and source_post_rollback_refresh_applied
        and source_fix_prompt_generated
        and source_fix_prompt_handoff_write_completed
        and normalized_post_rollback_handoff_prompt_kind == "fix"
        and not source_fix_human_review_required
        and post_rollback_handoff_allowed
        and post_rollback_handoff_available
        and post_rollback_handoff_should_generate_fix_prompt
        and not post_rollback_handoff_should_generate_next_prompt
        and not post_rollback_handoff_should_invoke_codex
        and not post_rollback_handoff_should_execute_rollback
        and not post_rollback_handoff_should_commit
        and not post_rollback_handoff_human_review_required
        and path_safe
    )

    propagation_block_reason = ""
    if not source_post_rollback_input_effective:
        propagation_block_reason = "blocked_post_rollback_fix_input_not_effective"
    elif not source_post_rollback_refresh_applied:
        propagation_block_reason = "blocked_fix_generation_refresh_not_applied"
    elif not source_fix_prompt_generated or not source_fix_prompt_handoff_write_completed:
        propagation_block_reason = "blocked_fix_prompt_not_generated"
    elif not path_safe:
        propagation_block_reason = "blocked_generated_fix_prompt_path_unsafe"
    elif normalized_post_rollback_handoff_prompt_kind != "fix":
        propagation_block_reason = "blocked_mismatched_prompt_kind"
    elif source_fix_human_review_required or post_rollback_handoff_human_review_required:
        propagation_block_reason = "blocked_human_review_required"
    elif post_rollback_handoff_should_invoke_codex:
        propagation_block_reason = "blocked_codex_invocation_requested_unexpectedly"
    elif post_rollback_handoff_should_execute_rollback:
        propagation_block_reason = "blocked_rollback_requested_unexpectedly"
    elif post_rollback_handoff_should_commit:
        propagation_block_reason = "blocked_commit_requested_unexpectedly"
    elif not allow_rule:
        propagation_block_reason = "blocked_insufficient_post_rollback_reentry_truth"

    status = "post_rollback_fix_reentry_propagation_blocked"
    propagation_allowed = False
    propagation_applied = False
    generated_prompt_reentry_refresh_allowed = False
    generated_prompt_reentry_prompt_kind = "none"
    generated_prompt_reentry_prompt_path = ""
    generated_prompt_reentry_source = ""
    reentry_routing_refresh_allowed = False
    reentry_routing_refresh_source = ""
    reentry_invocation_preparation_allowed = False
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False
    human_review_required = True
    next_action = "manual_review_required"

    if manual_review_or_stop:
        status = "post_rollback_fix_reentry_propagation_blocked_manual_review"
        propagation_allowed = False
        propagation_applied = False
        human_review_required = True
        next_action = (
            normalized_post_rollback_handoff_next_action
            if normalized_post_rollback_handoff_next_action in allowed_next_actions
            else "manual_review_required"
        )
    elif allow_rule:
        status = "post_rollback_fix_reentry_propagation_allowed"
        propagation_allowed = True
        propagation_applied = True
        generated_prompt_reentry_refresh_allowed = True
        generated_prompt_reentry_prompt_kind = "fix"
        generated_prompt_reentry_prompt_path = normalized_fix_prompt_path
        generated_prompt_reentry_source = "post_rollback_fix_generation"
        reentry_routing_refresh_allowed = True
        reentry_routing_refresh_source = "post_rollback_fix_generation"
        reentry_invocation_preparation_allowed = True
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        human_review_required = False
        propagation_block_reason = ""
        next_action = "prepare_post_rollback_fix_reentry"
    elif not path_safe and normalized_fix_prompt_path:
        status = "post_rollback_fix_reentry_propagation_blocked_unsafe_path"
        propagation_allowed = False
        propagation_applied = False
        human_review_required = True
        next_action = "manual_review_required"
    elif propagation_block_reason == "blocked_insufficient_post_rollback_reentry_truth":
        status = "post_rollback_fix_reentry_propagation_blocked_insufficient_truth"
        propagation_allowed = False
        propagation_applied = False
        human_review_required = True
        next_action = "manual_review_required"
    else:
        status = "post_rollback_fix_reentry_propagation_blocked"
        propagation_allowed = False
        propagation_applied = False
        human_review_required = bool(
            source_fix_human_review_required or post_rollback_handoff_human_review_required
        )
        next_action = (
            normalized_post_rollback_handoff_next_action
            if normalized_post_rollback_handoff_next_action in allowed_next_actions
            else "manual_review_required"
        )

    # Commit/Codex/Rollback execution boundaries for Prompt190.
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_status": status,
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_propagation_allowed": bool(
            propagation_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_propagation_applied": bool(
            propagation_applied
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_propagation_block_reason": (
            propagation_block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_source_fix_generation_status": (
            normalized_fix_generation_status
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_source_fix_prompt_generated": bool(
            source_fix_prompt_generated
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_source_fix_prompt_path": (
            normalized_fix_prompt_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_source_post_rollback_input_effective": bool(
            source_post_rollback_input_effective
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_generated_prompt_reentry_refresh_allowed": bool(
            generated_prompt_reentry_refresh_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_generated_prompt_reentry_prompt_kind": (
            generated_prompt_reentry_prompt_kind
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_generated_prompt_reentry_prompt_path": (
            generated_prompt_reentry_prompt_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_generated_prompt_reentry_source": (
            generated_prompt_reentry_source
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_reentry_routing_refresh_allowed": bool(
            reentry_routing_refresh_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_reentry_routing_refresh_source": (
            reentry_routing_refresh_source
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_reentry_invocation_preparation_allowed": bool(
            reentry_invocation_preparation_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_next_action": (
            next_action
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_propagation_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_fix_generation_status,
                    normalized_fix_next_action,
                    normalized_post_rollback_input_source,
                    normalized_post_rollback_input_reason,
                    normalized_post_rollback_handoff_prompt_kind,
                    normalized_post_rollback_handoff_next_action,
                    normalized_post_rollback_continuation_status,
                    normalized_post_rollback_continuation_next_action,
                    normalized_rollback_result_status,
                    normalized_existing_reentry_readiness_status,
                    normalized_existing_reentry_routing_status,
                    "post_rollback_input_unavailable"
                    if not source_post_rollback_input_available
                    else "",
                    "post_rollback_input_not_consumed"
                    if not source_post_rollback_input_consumed
                    else "",
                    "fix_prompt_path_not_exact" if not path_is_exact else "",
                    "fix_prompt_path_missing" if not path_exists else "",
                    "fix_prompt_path_not_file" if path_exists and not path_is_file else "",
                    "fix_prompt_path_symlink" if path_is_symlink else "",
                    "fix_prompt_file_empty" if path_exists and not file_non_empty else "",
                    "fix_prompt_file_too_large" if file_too_large else "",
                    "manual_review_or_stop" if manual_review_or_stop else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_fix_reentry_checkpoint_state(
    *,
    prompt190_status: str,
    prompt190_propagation_allowed: bool,
    prompt190_propagation_applied: bool,
    prompt190_propagation_block_reason: str,
    prompt190_generated_prompt_reentry_source: str,
    prompt190_generated_prompt_reentry_prompt_kind: str,
    prompt190_generated_prompt_reentry_prompt_path: str,
    prompt190_reentry_routing_refresh_allowed: bool,
    prompt190_reentry_invocation_preparation_allowed: bool,
    prompt190_human_review_required: bool,
    prompt190_should_invoke_codex: bool,
    prompt190_should_execute_rollback: bool,
    prompt190_should_commit: bool,
    prompt190_next_action: str,
    generated_reentry_readiness_status: str,
    generated_reentry_allowed: bool,
    generated_reentry_prompt_kind: str,
    generated_reentry_prompt_path: str,
    generated_reentry_human_review_required: bool,
    generated_reentry_routing_status: str,
    generated_reentry_routing_allowed: bool,
    generated_reentry_routing_prompt_kind: str,
    generated_reentry_routing_prompt_path: str,
    generated_reentry_routing_human_review_required: bool,
    prompt_selection_reentry_refresh_allowed: bool,
    prompt_selection_reentry_refresh_kind: str,
    prompt_selection_reentry_refresh_path: str,
    codex_invocation_reentry_selected_prompt_ready: bool,
    codex_invocation_reentry_selected_prompt_kind: str,
    codex_invocation_reentry_selected_prompt_path: str,
    codex_write_reentry_prepared: bool,
    codex_write_reentry_selected_prompt_ready: bool,
    codex_write_reentry_max_invocations: int,
    codex_reentry_post_rollback_preparation_allowed: bool,
    codex_reentry_post_rollback_preparation_source: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_fix_reentry_checkpoint_ready",
        "post_rollback_fix_reentry_checkpoint_blocked",
        "post_rollback_fix_reentry_checkpoint_blocked_manual_review",
        "post_rollback_fix_reentry_checkpoint_blocked_unsafe_path",
        "post_rollback_fix_reentry_checkpoint_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_bounded_post_rollback_fix_codex_reentry",
        "manual_review_required",
        "no_rollback_required",
        "insufficient_truth",
    }
    fixed_prompt_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    max_prompt_size_bytes = 20000
    runtime_posture = [
        "prompt191_post_rollback_fix_reentry_checkpoint",
        "metadata_only_final_recompute",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_prompt190_status = _normalize_text(prompt190_status, default="insufficient_truth")
    normalized_prompt190_block_reason = _normalize_text(
        prompt190_propagation_block_reason,
        default="",
    )
    normalized_prompt190_source = _normalize_text(
        prompt190_generated_prompt_reentry_source,
        default="",
    )
    normalized_prompt190_kind = _normalize_text(
        prompt190_generated_prompt_reentry_prompt_kind,
        default="none",
    )
    normalized_prompt190_path = _normalize_text(
        prompt190_generated_prompt_reentry_prompt_path,
        default="",
    )
    normalized_prompt190_next_action = _normalize_text(prompt190_next_action, default="")

    normalized_readiness_status = _normalize_text(
        generated_reentry_readiness_status,
        default="insufficient_truth",
    )
    normalized_readiness_kind = _normalize_text(generated_reentry_prompt_kind, default="none")
    normalized_readiness_path = _normalize_text(generated_reentry_prompt_path, default="")
    normalized_routing_status = _normalize_text(
        generated_reentry_routing_status,
        default="insufficient_truth",
    )
    normalized_routing_kind = _normalize_text(
        generated_reentry_routing_prompt_kind,
        default="none",
    )
    normalized_routing_path = _normalize_text(
        generated_reentry_routing_prompt_path,
        default="",
    )
    normalized_prompt_selection_kind = _normalize_text(
        prompt_selection_reentry_refresh_kind,
        default="none",
    )
    normalized_prompt_selection_path = _normalize_text(
        prompt_selection_reentry_refresh_path,
        default="",
    )
    normalized_codex_invocation_kind = _normalize_text(
        codex_invocation_reentry_selected_prompt_kind,
        default="none",
    )
    normalized_codex_invocation_path = _normalize_text(
        codex_invocation_reentry_selected_prompt_path,
        default="",
    )
    normalized_codex_reentry_prep_source = _normalize_text(
        codex_reentry_post_rollback_preparation_source,
        default="",
    )
    normalized_max_invocations = _as_non_negative_int(
        codex_write_reentry_max_invocations,
        default=1,
    )

    final_path = normalized_prompt190_path or normalized_readiness_path or normalized_routing_path
    final_path_obj = Path(final_path) if final_path else None
    final_path_is_exact = final_path == fixed_prompt_path
    final_path_exists = bool(final_path_obj and final_path_obj.exists())
    final_path_is_file = bool(final_path_obj and final_path_obj.is_file())
    final_path_is_symlink = bool(final_path_obj and final_path_obj.is_symlink())
    final_file_size = 0
    if final_path_obj and final_path_exists and final_path_is_file and not final_path_is_symlink:
        try:
            final_file_size = _as_non_negative_int(final_path_obj.stat().st_size, default=0)
        except OSError:
            final_file_size = 0
    final_file_non_empty = final_file_size > 0
    final_file_too_large = final_file_size > max_prompt_size_bytes
    final_path_safe = bool(
        final_path_is_exact
        and final_path_exists
        and final_path_is_file
        and not final_path_is_symlink
        and final_file_non_empty
        and not final_file_too_large
    )

    manual_review_or_stop = bool(
        prompt190_human_review_required
        or generated_reentry_human_review_required
        or generated_reentry_routing_human_review_required
        or normalized_prompt190_next_action == "manual_review_required"
        or normalized_prompt190_status
        in {
            "post_rollback_fix_reentry_propagation_blocked_manual_review",
            "post_rollback_fix_reentry_propagation_blocked_insufficient_truth",
        }
    )

    generated_prompt_reentry_ready = bool(
        generated_reentry_allowed
        and normalized_readiness_kind == "fix"
        and bool(normalized_readiness_path)
    )
    generated_prompt_reentry_routed = bool(
        generated_reentry_routing_allowed
        and normalized_routing_kind == "fix"
        and bool(normalized_routing_path)
    )
    prompt_selection_refresh_ready = bool(
        prompt_selection_reentry_refresh_allowed
        and normalized_prompt_selection_kind == "fix"
        and bool(normalized_prompt_selection_path)
    )
    codex_invocation_readiness_ready = bool(
        codex_invocation_reentry_selected_prompt_ready
        and normalized_codex_invocation_kind == "fix"
        and bool(normalized_codex_invocation_path)
    )

    allow_rule = bool(
        prompt190_propagation_allowed
        and prompt190_propagation_applied
        and normalized_prompt190_source == "post_rollback_fix_generation"
        and normalized_prompt190_kind == "fix"
        and prompt190_reentry_routing_refresh_allowed
        and prompt190_reentry_invocation_preparation_allowed
        and generated_prompt_reentry_ready
        and generated_prompt_reentry_routed
        and prompt_selection_refresh_ready
        and codex_invocation_readiness_ready
        and codex_write_reentry_prepared
        and codex_write_reentry_selected_prompt_ready
        and codex_reentry_post_rollback_preparation_allowed
        and final_path_safe
        and normalized_max_invocations == 1
        and not prompt190_human_review_required
        and not prompt190_should_invoke_codex
        and not prompt190_should_execute_rollback
        and not prompt190_should_commit
    )

    block_reason = ""
    if not prompt190_propagation_allowed:
        block_reason = "blocked_prompt190_propagation_not_allowed"
    elif not prompt190_propagation_applied:
        block_reason = "blocked_prompt190_propagation_not_applied"
    elif normalized_prompt190_source != "post_rollback_fix_generation":
        block_reason = "blocked_mismatched_reentry_source"
    elif normalized_prompt190_kind != "fix":
        block_reason = "blocked_mismatched_prompt_kind"
    elif not generated_prompt_reentry_ready:
        block_reason = "blocked_reentry_readiness_not_allowed"
    elif not generated_prompt_reentry_routed:
        block_reason = "blocked_reentry_routing_not_allowed"
    elif not prompt_selection_refresh_ready:
        block_reason = "blocked_prompt_selection_refresh_not_ready"
    elif not codex_invocation_readiness_ready:
        block_reason = "blocked_codex_invocation_readiness_not_ready"
    elif not codex_write_reentry_prepared or not codex_write_reentry_selected_prompt_ready:
        block_reason = "blocked_codex_write_reentry_not_prepared"
    elif not codex_reentry_post_rollback_preparation_allowed:
        block_reason = "blocked_post_rollback_reentry_preparation_not_allowed"
    elif not final_path_safe:
        block_reason = "blocked_final_prompt_path_unsafe"
    elif normalized_max_invocations != 1:
        block_reason = "blocked_max_reentry_invocations_not_one"
    elif prompt190_human_review_required:
        block_reason = "blocked_human_review_required"
    elif prompt190_should_invoke_codex:
        block_reason = "blocked_codex_invocation_requested_unexpectedly"
    elif prompt190_should_execute_rollback:
        block_reason = "blocked_rollback_requested_unexpectedly"
    elif prompt190_should_commit:
        block_reason = "blocked_commit_requested_unexpectedly"
    elif not allow_rule:
        block_reason = "blocked_insufficient_post_rollback_reentry_truth"

    status = "post_rollback_fix_reentry_checkpoint_blocked"
    final_ready = False
    final_source = ""
    final_kind = "none"
    final_path_out = ""
    final_max_invocations = 1
    final_invocation_prepared = False
    human_review_required = True
    next_action = "manual_review_required"

    if manual_review_or_stop:
        status = "post_rollback_fix_reentry_checkpoint_blocked_manual_review"
        final_ready = False
        final_invocation_prepared = False
        human_review_required = True
        next_action = (
            normalized_prompt190_next_action
            if normalized_prompt190_next_action in allowed_next_actions
            else "manual_review_required"
        )
    elif allow_rule:
        status = "post_rollback_fix_reentry_checkpoint_ready"
        final_ready = True
        final_source = "post_rollback_fix_generation"
        final_kind = "fix"
        final_path_out = fixed_prompt_path
        final_max_invocations = 1
        final_invocation_prepared = True
        human_review_required = False
        block_reason = ""
        next_action = "prepare_bounded_post_rollback_fix_codex_reentry"
    elif not final_path_safe and final_path:
        status = "post_rollback_fix_reentry_checkpoint_blocked_unsafe_path"
        final_ready = False
        final_invocation_prepared = False
        human_review_required = True
        next_action = "manual_review_required"
    elif block_reason == "blocked_insufficient_post_rollback_reentry_truth":
        status = "post_rollback_fix_reentry_checkpoint_blocked_insufficient_truth"
        final_ready = False
        final_invocation_prepared = False
        human_review_required = True
        next_action = "manual_review_required"
    else:
        status = "post_rollback_fix_reentry_checkpoint_blocked"
        final_ready = False
        final_invocation_prepared = False
        human_review_required = bool(
            prompt190_human_review_required
            or generated_reentry_human_review_required
            or generated_reentry_routing_human_review_required
        )
        next_action = (
            normalized_prompt190_next_action
            if normalized_prompt190_next_action in allowed_next_actions
            else "manual_review_required"
        )

    # Execution boundary/commit safety invariants for Prompt191.
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_status": status,
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_post_rollback_reentry_ready": bool(
            final_ready
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_post_rollback_reentry_block_reason": (
            block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_post_rollback_reentry_source": (
            final_source
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_reentry_prompt_kind": (
            final_kind
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_reentry_prompt_path": (
            final_path_out
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_reentry_max_invocations": int(
            final_max_invocations
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_final_reentry_invocation_prepared": bool(
            final_invocation_prepared
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_prompt190_propagation_allowed": bool(
            prompt190_propagation_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_prompt190_propagation_applied": bool(
            prompt190_propagation_applied
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_generated_prompt_reentry_ready": bool(
            generated_prompt_reentry_ready
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_generated_prompt_reentry_routed": bool(
            generated_prompt_reentry_routed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_prompt_selection_refresh_ready": bool(
            prompt_selection_refresh_ready
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_codex_invocation_readiness_ready": bool(
            codex_invocation_readiness_ready
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_codex_write_invocation_reentry_prepared": bool(
            codex_write_reentry_prepared
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_post_rollback_reentry_preparation_allowed": bool(
            codex_reentry_post_rollback_preparation_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_next_action": next_action,
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_checkpoint_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_prompt190_status,
                    normalized_prompt190_block_reason,
                    normalized_prompt190_source,
                    normalized_prompt190_kind,
                    normalized_prompt190_next_action,
                    normalized_readiness_status,
                    normalized_readiness_kind,
                    normalized_routing_status,
                    normalized_routing_kind,
                    normalized_prompt_selection_kind,
                    normalized_codex_invocation_kind,
                    normalized_codex_reentry_prep_source,
                    "final_path_not_exact" if not final_path_is_exact else "",
                    "final_path_missing" if not final_path_exists else "",
                    "final_path_not_file"
                    if final_path_exists and not final_path_is_file
                    else "",
                    "final_path_symlink" if final_path_is_symlink else "",
                    "final_path_empty" if final_path_exists and not final_file_non_empty else "",
                    "final_path_too_large" if final_file_too_large else "",
                    "manual_review_or_stop" if manual_review_or_stop else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_fix_reentry_execution_state(
    *,
    repository_path: str,
    checkpoint_status: str,
    final_post_rollback_reentry_ready: bool,
    final_post_rollback_reentry_block_reason: str,
    final_post_rollback_reentry_source: str,
    final_reentry_prompt_kind: str,
    final_reentry_prompt_path: str,
    final_reentry_max_invocations: int,
    final_reentry_invocation_prepared: bool,
    prompt190_propagation_allowed: bool,
    prompt190_propagation_applied: bool,
    generated_prompt_reentry_ready: bool,
    generated_prompt_reentry_routed: bool,
    prompt_selection_refresh_ready: bool,
    codex_invocation_readiness_ready: bool,
    codex_write_invocation_reentry_prepared: bool,
    post_rollback_reentry_preparation_allowed: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_commit: bool,
    human_review_required: bool,
    checkpoint_next_action: str,
    propagation_status: str,
    codex_reentry_invocation_status: str,
    codex_reentry_invocation_attempted: bool,
    codex_reentry_invocation_completed: bool,
    codex_invocation_reentry_selected_prompt_ready: bool,
    codex_invocation_reentry_selected_prompt_kind: str,
    codex_invocation_reentry_selected_prompt_path: str,
    codex_write_reentry_selected_prompt_ready: bool,
    codex_write_reentry_selected_prompt_kind: str,
    codex_write_reentry_selected_prompt_path: str,
    codex_write_reentry_max_invocations: int,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_fix_reentry_execution_completed_with_changes",
        "post_rollback_fix_reentry_execution_completed_no_changes",
        "post_rollback_fix_reentry_execution_completed_failure",
        "post_rollback_fix_reentry_execution_completed_timeout",
        "post_rollback_fix_reentry_execution_blocked_not_ready",
        "post_rollback_fix_reentry_execution_blocked_manual_review",
        "post_rollback_fix_reentry_execution_blocked_unsafe_prompt_path",
        "post_rollback_fix_reentry_execution_blocked_max_invocations",
        "post_rollback_fix_reentry_execution_blocked_unexpected_prior_action",
        "post_rollback_fix_reentry_execution_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "post_rollback_fix_reentry_result_assimilation",
        "manual_review_required",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    fixed_prompt_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    max_prompt_size_bytes = 20000
    runtime_posture = [
        "prompt192_post_rollback_fix_reentry_execution",
        "single_bounded_invocation",
        "reuses_prompt180_prompt167_workspace_write_path",
        "no_retry",
        "no_loop",
        "no_rollback_execution",
        "no_commit",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_checkpoint_status = _normalize_text(
        checkpoint_status,
        default="insufficient_truth",
    )
    normalized_checkpoint_block_reason = _normalize_text(
        final_post_rollback_reentry_block_reason,
        default="",
    )
    normalized_checkpoint_source = _normalize_text(
        final_post_rollback_reentry_source,
        default="",
    )
    normalized_prompt_kind = _normalize_text(final_reentry_prompt_kind, default="none")
    normalized_prompt_path = _normalize_text(final_reentry_prompt_path, default="")
    normalized_checkpoint_next_action = _normalize_text(checkpoint_next_action, default="")
    normalized_propagation_status = _normalize_text(propagation_status, default="insufficient_truth")
    normalized_prior_reentry_status = _normalize_text(
        codex_reentry_invocation_status,
        default="insufficient_truth",
    )
    normalized_codex_invocation_reentry_kind = _normalize_text(
        codex_invocation_reentry_selected_prompt_kind,
        default="none",
    )
    normalized_codex_invocation_reentry_path = _normalize_text(
        codex_invocation_reentry_selected_prompt_path,
        default="",
    )
    normalized_codex_write_reentry_kind = _normalize_text(
        codex_write_reentry_selected_prompt_kind,
        default="none",
    )
    normalized_codex_write_reentry_path = _normalize_text(
        codex_write_reentry_selected_prompt_path,
        default="",
    )
    normalized_max_invocations = _as_non_negative_int(final_reentry_max_invocations, default=0)
    normalized_write_reentry_max_invocations = _as_non_negative_int(
        codex_write_reentry_max_invocations,
        default=0,
    )

    prompt_path_obj = Path(normalized_prompt_path) if normalized_prompt_path else None
    prompt_path_is_exact = normalized_prompt_path == fixed_prompt_path
    prompt_path_exists = bool(prompt_path_obj and prompt_path_obj.exists())
    prompt_path_is_file = bool(prompt_path_obj and prompt_path_obj.is_file())
    prompt_path_is_symlink = bool(prompt_path_obj and prompt_path_obj.is_symlink())
    prompt_size_bytes = 0
    if prompt_path_obj and prompt_path_exists and prompt_path_is_file and not prompt_path_is_symlink:
        try:
            prompt_size_bytes = _as_non_negative_int(prompt_path_obj.stat().st_size, default=0)
        except OSError:
            prompt_size_bytes = 0
    prompt_file_non_empty = prompt_size_bytes > 0
    prompt_file_too_large = prompt_size_bytes > max_prompt_size_bytes
    prompt_path_safe = bool(
        prompt_path_is_exact
        and prompt_path_exists
        and prompt_path_is_file
        and not prompt_path_is_symlink
        and prompt_file_non_empty
        and not prompt_file_too_large
    )

    block_reason = ""
    if not final_post_rollback_reentry_ready:
        block_reason = "blocked_checkpoint_not_ready"
    elif normalized_checkpoint_source != "post_rollback_fix_generation":
        block_reason = "blocked_mismatched_source"
    elif normalized_prompt_kind != "fix":
        block_reason = "blocked_mismatched_prompt_kind"
    elif not prompt_path_safe:
        block_reason = "blocked_unsafe_prompt_path"
    elif normalized_max_invocations != 1 or normalized_write_reentry_max_invocations != 1:
        block_reason = "blocked_max_invocations_not_one"
    elif not final_reentry_invocation_prepared:
        block_reason = "blocked_invocation_not_prepared"
    elif not (prompt190_propagation_allowed and prompt190_propagation_applied):
        block_reason = "blocked_prompt190_propagation_not_ready"
    elif not generated_prompt_reentry_ready:
        block_reason = "blocked_generated_prompt_reentry_not_ready"
    elif not generated_prompt_reentry_routed:
        block_reason = "blocked_generated_prompt_reentry_not_routed"
    elif not prompt_selection_refresh_ready:
        block_reason = "blocked_prompt_selection_not_ready"
    elif not codex_invocation_readiness_ready:
        block_reason = "blocked_codex_invocation_readiness_not_ready"
    elif not codex_write_invocation_reentry_prepared:
        block_reason = "blocked_codex_write_reentry_not_prepared"
    elif not post_rollback_reentry_preparation_allowed:
        block_reason = "blocked_post_rollback_preparation_not_allowed"
    elif human_review_required:
        block_reason = "blocked_human_review_required"
    elif should_invoke_codex:
        block_reason = "blocked_codex_invocation_requested_unexpectedly"
    elif should_execute_rollback:
        block_reason = "blocked_rollback_requested_unexpectedly"
    elif should_commit:
        block_reason = "blocked_commit_requested_unexpectedly"
    elif not normalized_repository_path:
        block_reason = "blocked_insufficient_post_rollback_fix_reentry_execution_truth"
    elif (
        normalized_codex_invocation_reentry_kind != "fix"
        or normalized_codex_invocation_reentry_path != fixed_prompt_path
        or not codex_invocation_reentry_selected_prompt_ready
    ):
        block_reason = "blocked_codex_invocation_readiness_not_ready"
    elif (
        normalized_codex_write_reentry_kind != "fix"
        or normalized_codex_write_reentry_path != fixed_prompt_path
        or not codex_write_reentry_selected_prompt_ready
    ):
        block_reason = "blocked_codex_write_reentry_not_prepared"
    elif not (
        normalized_checkpoint_status == "post_rollback_fix_reentry_checkpoint_ready"
        and normalized_propagation_status == "post_rollback_fix_reentry_propagation_allowed"
    ):
        block_reason = "blocked_insufficient_post_rollback_fix_reentry_execution_truth"
    elif not (
        normalized_prior_reentry_status in {"insufficient_truth"}
        or (
            not bool(codex_reentry_invocation_attempted)
            and not bool(codex_reentry_invocation_completed)
        )
    ):
        block_reason = "blocked_insufficient_post_rollback_fix_reentry_execution_truth"

    execution_allowed = not bool(block_reason)
    status = "post_rollback_fix_reentry_execution_blocked_insufficient_truth"
    execution_source = "prompt191_post_rollback_fix_reentry_checkpoint"
    execution_attempted = False
    execution_completed = False
    execution_failed = False
    command: list[str] = []
    stdout_path = "/tmp/codex-local-runner-decision/codex_write_invocation_stdout.txt"
    stderr_path = "/tmp/codex-local-runner-decision/codex_write_invocation_stderr.txt"
    result_path = "/tmp/codex-local-runner-decision/codex_write_invocation_result.json"
    git_diff_name_only_path = "/tmp/codex-local-runner-decision/codex_write_git_diff_name_only.txt"
    git_diff_numstat_path = "/tmp/codex-local-runner-decision/codex_write_git_diff_numstat.txt"
    changed_files_after: list[str] = []
    changed_files_count_after = 0
    result_class = "blocked"
    exit_code = -1
    timed_out = False
    invocations_attempted = 0
    invocations_completed = 0
    local_human_review_required = bool(human_review_required)
    next_action = "manual_review_required"
    assimilation_ready = False
    assimilation_source = ""
    assimilation_next_stage = "manual_review_or_blocked_post_rollback_reentry"
    missing_inputs: list[str] = []

    if execution_allowed:
        write_state = _build_project_browser_autonomous_codex_write_invocation_state(
            repository_path=normalized_repository_path,
            codex_invocation_readiness_status="ready_for_write_codex_invocation",
            codex_invocation_readiness_allowed=True,
            selected_prompt_kind="fix",
            selected_prompt_path=fixed_prompt_path,
            selected_prompt_source="project_browser_autonomous_post_rollback_fix_reentry_checkpoint",
            selected_prompt_ready=True,
            selected_prompt_path_is_exact=True,
            selected_prompt_path_exists=True,
            selected_prompt_path_is_symlink=False,
            selected_prompt_file_non_empty=True,
            selected_prompt_file_too_large=False,
            rollback_required=False,
            human_review_required=False,
            insufficient_truth=False,
            max_invocations=1,
            prior_write_invocation_attempted=False,
            prior_write_invocation_completed=False,
        )
        command = _normalize_string_list(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_command"
            )
        )
        stdout_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_stdout_path"
            ),
            default=stdout_path,
        )
        stderr_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_stderr_path"
            ),
            default=stderr_path,
        )
        result_path = _normalize_text(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_result_json_path"),
            default=result_path,
        )
        git_diff_name_only_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_git_diff_name_only_path"
            ),
            default=git_diff_name_only_path,
        )
        git_diff_numstat_path = _normalize_text(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_git_diff_numstat_path"
            ),
            default=git_diff_numstat_path,
        )
        changed_files_after = _normalize_string_list(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_changed_files_after"
            )
        )
        changed_files_count_after = _as_non_negative_int(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_result_changed_files_count_after"
            ),
            default=len(changed_files_after),
        )
        execution_attempted = bool(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_attempted",
                False,
            )
        )
        execution_completed = bool(
            write_state.get(
                "project_browser_autonomous_codex_write_invocation_execution_invocation_completed",
                False,
            )
        )
        timed_out = bool(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_timeout", False)
        )
        exit_code = int(
            _as_int(
                write_state.get("project_browser_autonomous_codex_write_invocation_result_exit_code"),
                default=-1,
            )
        )
        invocations_attempted = 1 if execution_attempted else 0
        invocations_completed = 1 if (execution_completed and not timed_out) else 0
        write_result_status = _normalize_text(
            write_state.get("project_browser_autonomous_codex_write_invocation_result_status"),
            default="insufficient_truth",
        )
        if write_result_status == "completed_with_changes":
            status = "post_rollback_fix_reentry_execution_completed_with_changes"
            result_class = "completed_with_changes"
            execution_failed = False
            local_human_review_required = False
            next_action = "post_rollback_fix_reentry_result_assimilation"
            assimilation_ready = True
        elif write_result_status == "completed_no_changes":
            status = "post_rollback_fix_reentry_execution_completed_no_changes"
            result_class = "completed_no_changes"
            execution_failed = False
            local_human_review_required = False
            next_action = "post_rollback_fix_reentry_result_assimilation"
            assimilation_ready = True
        elif write_result_status == "completed_failure":
            status = "post_rollback_fix_reentry_execution_completed_failure"
            result_class = "completed_failure"
            execution_failed = True
            local_human_review_required = False
            next_action = "post_rollback_fix_reentry_result_assimilation"
            assimilation_ready = True
        elif write_result_status == "completed_timeout":
            status = "post_rollback_fix_reentry_execution_completed_timeout"
            result_class = "completed_timeout"
            execution_failed = True
            local_human_review_required = True
            next_action = "post_rollback_fix_reentry_result_assimilation"
            assimilation_ready = True
        else:
            status = "post_rollback_fix_reentry_execution_blocked_insufficient_truth"
            result_class = "blocked"
            execution_failed = False
            local_human_review_required = True
            next_action = "manual_review_required"
            block_reason = _normalize_text(
                write_state.get(
                    "project_browser_autonomous_codex_write_invocation_execution_block_reason"
                ),
                default="blocked_insufficient_post_rollback_fix_reentry_execution_truth",
            )
            assimilation_ready = False

        if assimilation_ready:
            assimilation_source = "prompt192_post_rollback_fix_reentry_execution"
            assimilation_next_stage = "post_rollback_fix_reentry_result_assimilation"
        else:
            assimilation_source = ""
            assimilation_next_stage = "manual_review_or_blocked_post_rollback_reentry"
    else:
        if block_reason == "blocked_human_review_required":
            status = "post_rollback_fix_reentry_execution_blocked_manual_review"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif block_reason == "blocked_unsafe_prompt_path":
            status = "post_rollback_fix_reentry_execution_blocked_unsafe_prompt_path"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif block_reason == "blocked_max_invocations_not_one":
            status = "post_rollback_fix_reentry_execution_blocked_max_invocations"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif block_reason in {
            "blocked_codex_invocation_requested_unexpectedly",
            "blocked_rollback_requested_unexpectedly",
            "blocked_commit_requested_unexpectedly",
        }:
            status = "post_rollback_fix_reentry_execution_blocked_unexpected_prior_action"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif block_reason in {
            "blocked_checkpoint_not_ready",
            "blocked_mismatched_source",
            "blocked_mismatched_prompt_kind",
            "blocked_invocation_not_prepared",
            "blocked_prompt190_propagation_not_ready",
            "blocked_generated_prompt_reentry_not_ready",
            "blocked_generated_prompt_reentry_not_routed",
            "blocked_prompt_selection_not_ready",
            "blocked_codex_invocation_readiness_not_ready",
            "blocked_codex_write_reentry_not_prepared",
            "blocked_post_rollback_preparation_not_allowed",
        }:
            status = "post_rollback_fix_reentry_execution_blocked_not_ready"
            local_human_review_required = True
            next_action = (
                "manual_review_required"
                if normalized_checkpoint_next_action != "no_rollback_required"
                else "wait_for_more_truth"
            )
        else:
            status = "post_rollback_fix_reentry_execution_blocked_insufficient_truth"
            local_human_review_required = True
            next_action = "manual_review_required"
        if not normalized_repository_path:
            missing_inputs.append("repository_path")

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"

    return {
        "project_browser_autonomous_post_rollback_fix_reentry_execution_status": status,
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_allowed": bool(
            execution_allowed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_attempted": bool(
            execution_attempted
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_completed": bool(
            execution_completed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_failed": bool(
            execution_failed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_block_reason": (
            block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_source": (
            execution_source
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_prompt_kind": (
            "fix" if normalized_prompt_kind == "fix" else "none"
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_prompt_path": (
            normalized_prompt_path if normalized_prompt_kind == "fix" else ""
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_max_invocations": int(
            normalized_max_invocations
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_invocations_attempted": int(
            invocations_attempted
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_invocations_completed": int(
            invocations_completed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_reused_invocation_path": True,
        "project_browser_autonomous_post_rollback_fix_reentry_execution_execution_sandbox": (
            "workspace-write"
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_command": command,
        "project_browser_autonomous_post_rollback_fix_reentry_execution_stdout_path": (
            stdout_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_stderr_path": (
            stderr_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_result_path": (
            result_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_git_diff_name_only_path": (
            git_diff_name_only_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_git_diff_numstat_path": (
            git_diff_numstat_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_changed_files_after": (
            changed_files_after
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_changed_files_count_after": int(
            changed_files_count_after
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_result_class": (
            result_class
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_exit_code": int(
            exit_code
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_timed_out": bool(
            timed_out
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_post_rollback_fix_reentry_result_ready_for_assimilation": bool(
            assimilation_ready
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_post_rollback_fix_reentry_result_assimilation_source": (
            assimilation_source
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_post_rollback_fix_reentry_result_next_stage": (
            assimilation_next_stage
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_human_review_required": bool(
            local_human_review_required
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_next_action": (
            next_action
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_execution_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_checkpoint_status,
                    normalized_checkpoint_block_reason,
                    normalized_checkpoint_source,
                    normalized_prompt_kind,
                    normalized_prompt_path,
                    normalized_propagation_status,
                    normalized_prior_reentry_status,
                    "checkpoint_not_ready" if not final_post_rollback_reentry_ready else "",
                    "prompt_path_not_exact" if not prompt_path_is_exact else "",
                    "prompt_path_missing" if not prompt_path_exists else "",
                    "prompt_path_not_file"
                    if prompt_path_exists and not prompt_path_is_file
                    else "",
                    "prompt_path_symlink" if prompt_path_is_symlink else "",
                    "prompt_path_empty" if prompt_path_exists and not prompt_file_non_empty else "",
                    "prompt_path_too_large" if prompt_file_too_large else "",
                    *missing_inputs,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_state(
    *,
    repository_path: str,
    execution_status: str,
    execution_allowed: bool,
    execution_attempted: bool,
    execution_completed: bool,
    execution_failed: bool,
    execution_block_reason: str,
    execution_source: str,
    prompt_kind: str,
    prompt_path: str,
    max_invocations: int,
    invocations_attempted: int,
    invocations_completed: int,
    reused_invocation_path: bool,
    execution_sandbox: str,
    command: list[str] | None,
    stdout_path: str,
    stderr_path: str,
    result_path: str,
    git_diff_name_only_path: str,
    git_diff_numstat_path: str,
    changed_files_after: list[str] | None,
    changed_files_count_after: int,
    result_class: str,
    exit_code: int,
    timed_out: bool,
    result_ready_for_assimilation: bool,
    result_assimilation_source: str,
    result_next_stage: str,
    execution_human_review_required: bool,
    execution_next_action: str,
    checkpoint_status: str,
    checkpoint_next_action: str,
    propagation_status: str,
    codex_reentry_invocation_status: str,
    codex_write_execution_status: str,
    codex_write_result_status: str,
    fix_target_files: list[str] | None,
) -> dict[str, Any]:
    allowed_statuses = {
        "post_rollback_fix_reentry_result_completed_with_changes",
        "post_rollback_fix_reentry_result_completed_no_changes",
        "post_rollback_fix_reentry_result_completed_failure",
        "post_rollback_fix_reentry_result_completed_timeout",
        "post_rollback_fix_reentry_result_validation_passed",
        "post_rollback_fix_reentry_result_validation_failed",
        "post_rollback_fix_reentry_result_validation_timeout",
        "post_rollback_fix_reentry_result_blocked_execution_not_ready",
        "post_rollback_fix_reentry_result_blocked_unsafe_changes",
        "post_rollback_fix_reentry_result_blocked_validation_routing",
        "post_rollback_fix_reentry_result_blocked_no_py_compile_candidates",
        "post_rollback_fix_reentry_result_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_commit_readiness",
        "generate_fix_prompt",
        "manual_review_required",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    fixed_prompt_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    fixed_diff_name_only_path = (
        "/tmp/codex-local-runner-decision/codex_write_git_diff_name_only.txt"
    )
    fixed_diff_numstat_path = "/tmp/codex-local-runner-decision/codex_write_git_diff_numstat.txt"
    allowed_diff_paths = {fixed_diff_name_only_path, fixed_diff_numstat_path}
    max_changed_files_threshold = 8
    runtime_posture = [
        "prompt193_post_rollback_fix_reentry_result_assimilation",
        "prompt192_authoritative_source_only",
        "bounded_py_compile_only",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_commit",
        "no_loop",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_execution_status = _normalize_text(execution_status, default="insufficient_truth")
    normalized_execution_block_reason = _normalize_text(execution_block_reason, default="")
    normalized_execution_source = _normalize_text(execution_source, default="")
    normalized_prompt_kind = _normalize_text(prompt_kind, default="none")
    normalized_prompt_path = _normalize_text(prompt_path, default="")
    normalized_result_class = _normalize_text(result_class, default="blocked")
    normalized_result_assimilation_source = _normalize_text(
        result_assimilation_source,
        default="",
    )
    normalized_result_next_stage = _normalize_text(result_next_stage, default="")
    normalized_execution_next_action = _normalize_text(execution_next_action, default="")
    normalized_checkpoint_status = _normalize_text(checkpoint_status, default="insufficient_truth")
    normalized_checkpoint_next_action = _normalize_text(checkpoint_next_action, default="")
    normalized_propagation_status = _normalize_text(propagation_status, default="insufficient_truth")
    normalized_codex_reentry_invocation_status = _normalize_text(
        codex_reentry_invocation_status,
        default="insufficient_truth",
    )
    normalized_codex_write_execution_status = _normalize_text(
        codex_write_execution_status,
        default="insufficient_truth",
    )
    normalized_codex_write_result_status = _normalize_text(
        codex_write_result_status,
        default="insufficient_truth",
    )
    normalized_command = _normalize_string_list(command or [])
    normalized_stdout_path = _normalize_text(stdout_path, default="")
    normalized_stderr_path = _normalize_text(stderr_path, default="")
    normalized_result_path = _normalize_text(result_path, default="")
    normalized_diff_name_only_path = _normalize_text(git_diff_name_only_path, default="")
    normalized_diff_numstat_path = _normalize_text(git_diff_numstat_path, default="")
    normalized_changed_files = _normalize_string_list(changed_files_after or [])
    normalized_changed_files_count = _as_non_negative_int(
        changed_files_count_after,
        default=len(normalized_changed_files),
    )
    normalized_fix_target_files = _normalize_string_list(fix_target_files or [])
    normalized_max_invocations = _as_non_negative_int(max_invocations, default=0)
    normalized_invocations_attempted = _as_non_negative_int(invocations_attempted, default=0)
    normalized_invocations_completed = _as_non_negative_int(invocations_completed, default=0)

    authoritative_source_kind = "none"
    authoritative_source_selected = False
    authoritative_source_block_reason = "blocked_execution_not_ready"
    if (
        bool(result_ready_for_assimilation)
        and normalized_result_assimilation_source
        == "prompt192_post_rollback_fix_reentry_execution"
        and bool(execution_attempted)
        and normalized_prompt_kind == "fix"
        and normalized_prompt_path == fixed_prompt_path
    ):
        authoritative_source_kind = "post_rollback_fix_reentry"
        authoritative_source_selected = True
        authoritative_source_block_reason = ""

    source_status = normalized_execution_status
    source_result_class = normalized_result_class
    source_prompt_kind = normalized_prompt_kind if normalized_prompt_kind in {"fix", "next"} else "none"
    source_prompt_path = normalized_prompt_path
    source_stdout_path = normalized_stdout_path
    source_stderr_path = normalized_stderr_path
    source_result_path = normalized_result_path
    source_git_diff_name_only_path = normalized_diff_name_only_path
    source_git_diff_numstat_path = normalized_diff_numstat_path
    source_changed_files = list(normalized_changed_files)
    source_changed_files_count = normalized_changed_files_count

    def _read_changed_files_from_diff() -> list[str]:
        changed_from_name: list[str] = []
        changed_from_numstat: list[str] = []
        if source_git_diff_name_only_path in allowed_diff_paths:
            path_obj = Path(source_git_diff_name_only_path)
            if path_obj.exists() and not path_obj.is_symlink():
                try:
                    changed_from_name = _serialize_required_signals(
                        path_obj.read_text(encoding="utf-8").splitlines()
                    )
                except OSError:
                    changed_from_name = []
        if source_git_diff_numstat_path in allowed_diff_paths:
            path_obj = Path(source_git_diff_numstat_path)
            if path_obj.exists() and not path_obj.is_symlink():
                try:
                    for line in path_obj.read_text(encoding="utf-8").splitlines():
                        parts = line.split("\t")
                        if len(parts) >= 3:
                            changed_from_numstat.append(parts[-1].strip())
                except OSError:
                    changed_from_numstat = []
        return (
            changed_from_name
            if changed_from_name
            else _serialize_required_signals(changed_from_numstat)
        )

    if authoritative_source_selected and not source_changed_files:
        source_changed_files = _read_changed_files_from_diff()
        source_changed_files_count = max(source_changed_files_count, len(source_changed_files))

    expected_changed_files = _serialize_required_signals(normalized_fix_target_files)
    allowed_changed_files = list(expected_changed_files)
    allowed_set = set(allowed_changed_files)

    def _is_forbidden_changed_file(path_text: str) -> bool:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            return False
        lowered = normalized_path.lower()
        if normalized_path.startswith("/") or normalized_path.startswith("../"):
            return True
        if normalized_path.startswith(".git/"):
            return True
        if normalized_path.startswith("prompts/context/") and normalized_path not in allowed_set:
            return True
        if normalized_path.startswith("__pycache__/") or "/__pycache__/" in normalized_path:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered == ".env" or lowered.startswith(".env.") or "/.env" in lowered:
            return True
        if lowered.endswith(".pem") or lowered.endswith(".key"):
            return True
        if normalized_path.startswith("tmp/") or normalized_path.startswith(".cache/"):
            return True
        return False

    forbidden_changed_files = _serialize_required_signals(
        [path for path in source_changed_files if _is_forbidden_changed_file(path)]
    )
    forbidden_set = set(forbidden_changed_files)
    unexpected_changed_files = _serialize_required_signals(
        [path for path in source_changed_files if path not in allowed_set and path not in forbidden_set]
    )
    too_many_changed_files = bool(source_changed_files_count > max_changed_files_threshold)

    safe_for_validation_routing = False
    validation_routing_candidate = False
    validation_routing_block_reason = "blocked_validation_routing"
    validation_target_files: list[str] = []
    py_compile_candidate_files: list[str] = []
    validation_executed = False
    validation_passed = False
    validation_failed = False
    validation_timeout = False
    py_compile_results: list[dict[str, Any]] = []

    cycle_status = "post_rollback_fix_reentry_cycle_blocked"
    cycle_passed = False
    cycle_failed = False
    cycle_blocked = True
    cycle_block_reason = "blocked_insufficient_truth"
    commit_candidate = False
    fix_candidate = False
    rollback_candidate = False
    rollback_reason = ""
    local_human_review_required = True
    status = "post_rollback_fix_reentry_result_blocked_insufficient_truth"
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    if not authoritative_source_selected:
        status = "post_rollback_fix_reentry_result_blocked_execution_not_ready"
        cycle_status = "post_rollback_fix_reentry_cycle_blocked_execution_not_ready"
        cycle_blocked = True
        cycle_block_reason = "blocked_execution_not_ready"
        local_human_review_required = bool(execution_human_review_required)
        next_action = (
            "manual_review_required"
            if local_human_review_required
            else "wait_for_more_truth"
        )
        authoritative_source_block_reason = (
            normalized_execution_block_reason or authoritative_source_block_reason
        )
    elif source_result_class == "completed_timeout" or bool(timed_out):
        status = "post_rollback_fix_reentry_result_completed_timeout"
        cycle_status = "cycle_blocked_invocation_timeout"
        cycle_blocked = True
        cycle_block_reason = "post_rollback_fix_reentry_invocation_timeout"
        rollback_candidate = True
        rollback_reason = "post_rollback_fix_reentry_invocation_timeout"
        local_human_review_required = True
        validation_routing_block_reason = "blocked_post_rollback_fix_reentry_timeout"
        next_action = "manual_review_required"
    elif source_result_class == "completed_failure" or bool(execution_failed):
        status = "post_rollback_fix_reentry_result_completed_failure"
        cycle_status = "cycle_failed_invocation"
        cycle_failed = True
        cycle_blocked = False
        cycle_block_reason = "post_rollback_fix_reentry_invocation_failure"
        fix_candidate = True
        rollback_candidate = True
        rollback_reason = "post_rollback_fix_reentry_invocation_failure"
        local_human_review_required = False
        validation_routing_block_reason = "blocked_post_rollback_fix_reentry_failure"
        next_action = "generate_fix_prompt"
    elif source_result_class == "completed_no_changes":
        status = "post_rollback_fix_reentry_result_completed_no_changes"
        cycle_status = "cycle_blocked_no_changes"
        cycle_blocked = True
        cycle_block_reason = "blocked_no_changed_files"
        local_human_review_required = True
        validation_routing_block_reason = "blocked_no_changed_files"
        next_action = "manual_review_required"
    elif source_result_class == "completed_with_changes":
        status = "post_rollback_fix_reentry_result_completed_with_changes"
        if forbidden_changed_files or unexpected_changed_files or too_many_changed_files:
            status = "post_rollback_fix_reentry_result_blocked_unsafe_changes"
            cycle_status = "post_rollback_fix_reentry_cycle_blocked_unsafe_changes"
            cycle_blocked = True
            cycle_block_reason = "unsafe_post_rollback_fix_reentry_changes"
            rollback_candidate = True
            rollback_reason = "unsafe_post_rollback_fix_reentry_changes"
            local_human_review_required = True
            next_action = "manual_review_required"
            validation_routing_block_reason = "blocked_unsafe_post_rollback_fix_reentry_changes"
        elif not source_changed_files:
            status = "post_rollback_fix_reentry_result_blocked_insufficient_truth"
            cycle_status = "post_rollback_fix_reentry_cycle_blocked_missing_changes"
            cycle_blocked = True
            cycle_block_reason = "changed_files_missing"
            local_human_review_required = True
            validation_routing_block_reason = "blocked_insufficient_truth"
            next_action = "wait_for_more_truth"
            missing_inputs.append("source_changed_files")
        else:
            safe_for_validation_routing = True
            validation_routing_candidate = True
            validation_routing_block_reason = ""
            validation_target_files = sorted(
                set(path for path in source_changed_files if path in allowed_set)
            )
            py_compile_candidate_files = sorted(
                [path for path in validation_target_files if path.endswith(".py")]
            )
            if not py_compile_candidate_files:
                status = "post_rollback_fix_reentry_result_blocked_no_py_compile_candidates"
                cycle_status = "post_rollback_fix_reentry_cycle_blocked_no_py_compile_candidates"
                cycle_blocked = True
                cycle_block_reason = "blocked_no_post_reentry_py_compile_candidates"
                local_human_review_required = True
                next_action = "manual_review_required"
            else:
                validation_state = _build_project_browser_autonomous_post_write_validation_execution_state(
                    repository_path=normalized_repository_path,
                    source_routing_status="validation_routing_allowed",
                    source_validation_allowed=True,
                    source_validation_block_reason="",
                    validation_target_files=validation_target_files,
                    py_compile_candidate_files=py_compile_candidate_files,
                    targeted_test_candidate_files=[],
                    human_review_required=False,
                    source_next_action="run_post_write_validation",
                )
                validation_status = _normalize_text(
                    validation_state.get(
                        "project_browser_autonomous_post_write_validation_execution_status"
                    ),
                    default="blocked_routing_not_allowed",
                )
                validation_executed = bool(
                    validation_state.get(
                        "project_browser_autonomous_post_write_validation_execution_validation_executed",
                        False,
                    )
                )
                validation_passed = bool(
                    validation_state.get(
                        "project_browser_autonomous_post_write_validation_execution_validation_passed",
                        False,
                    )
                )
                validation_failed = bool(
                    validation_state.get(
                        "project_browser_autonomous_post_write_validation_execution_validation_failed",
                        False,
                    )
                )
                validation_timeout = bool(validation_status == "validation_timeout")
                py_compile_results = (
                    list(
                        validation_state.get(
                            "project_browser_autonomous_post_write_validation_execution_py_compile_results",
                            [],
                        )
                    )
                    if isinstance(
                        validation_state.get(
                            "project_browser_autonomous_post_write_validation_execution_py_compile_results",
                            [],
                        ),
                        list,
                    )
                    else []
                )
                if validation_passed:
                    status = "post_rollback_fix_reentry_result_validation_passed"
                    cycle_status = "post_rollback_fix_reentry_cycle_passed"
                    cycle_passed = True
                    cycle_failed = False
                    cycle_blocked = False
                    cycle_block_reason = ""
                    commit_candidate = bool(
                        not forbidden_changed_files
                        and not unexpected_changed_files
                        and not too_many_changed_files
                        and bool(source_changed_files)
                    )
                    fix_candidate = False
                    rollback_candidate = False
                    rollback_reason = ""
                    local_human_review_required = False
                    next_action = "prepare_commit_readiness"
                elif validation_timeout:
                    status = "post_rollback_fix_reentry_result_validation_timeout"
                    cycle_status = "post_rollback_fix_reentry_cycle_blocked_validation_timeout"
                    cycle_blocked = True
                    cycle_block_reason = "post_rollback_fix_reentry_validation_timeout"
                    commit_candidate = False
                    fix_candidate = False
                    rollback_candidate = True
                    rollback_reason = "post_rollback_fix_reentry_validation_timeout"
                    local_human_review_required = True
                    next_action = "manual_review_required"
                elif validation_failed:
                    status = "post_rollback_fix_reentry_result_validation_failed"
                    cycle_status = "post_rollback_fix_reentry_cycle_failed_validation"
                    cycle_passed = False
                    cycle_failed = True
                    cycle_blocked = False
                    cycle_block_reason = "post_rollback_fix_reentry_validation_failed"
                    commit_candidate = False
                    fix_candidate = True
                    rollback_candidate = True
                    rollback_reason = "post_rollback_fix_reentry_validation_failed"
                    local_human_review_required = False
                    next_action = "generate_fix_prompt"
                else:
                    status = "post_rollback_fix_reentry_result_blocked_validation_routing"
                    cycle_status = "post_rollback_fix_reentry_cycle_blocked_validation_routing"
                    cycle_blocked = True
                    cycle_block_reason = "blocked_post_rollback_fix_reentry_validation_routing"
                    local_human_review_required = True
                    next_action = "manual_review_required"
                    validation_routing_block_reason = "blocked_post_rollback_fix_reentry_validation_routing"
    else:
        status = "post_rollback_fix_reentry_result_blocked_insufficient_truth"
        cycle_status = "post_rollback_fix_reentry_cycle_blocked_insufficient_truth"
        cycle_blocked = True
        cycle_block_reason = "blocked_insufficient_truth"
        local_human_review_required = True
        next_action = "wait_for_more_truth"
        missing_inputs.append("source_result_class")

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if commit_candidate and (
        not validation_passed
        or not cycle_passed
        or rollback_candidate
        or local_human_review_required
        or forbidden_changed_files
        or unexpected_changed_files
        or too_many_changed_files
    ):
        commit_candidate = False

    return {
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_status": status,
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_authoritative_source_kind": (
            authoritative_source_kind
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_authoritative_source_selected": bool(
            authoritative_source_selected
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_authoritative_source_block_reason": (
            authoritative_source_block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_status": source_status,
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_result_class": (
            source_result_class
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_prompt_kind": (
            source_prompt_kind
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_prompt_path": (
            source_prompt_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_stdout_path": (
            source_stdout_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_stderr_path": (
            source_stderr_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_result_path": (
            source_result_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_git_diff_name_only_path": (
            source_git_diff_name_only_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_git_diff_numstat_path": (
            source_git_diff_numstat_path
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_changed_files": (
            source_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_source_changed_files_count": int(
            source_changed_files_count
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_expected_changed_files": (
            expected_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_allowed_changed_files": (
            allowed_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_unexpected_changed_files": (
            unexpected_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_forbidden_changed_files": (
            forbidden_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_too_many_changed_files": bool(
            too_many_changed_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_safe_for_validation_routing": bool(
            safe_for_validation_routing
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_routing_candidate": bool(
            validation_routing_candidate
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_routing_block_reason": (
            validation_routing_block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_target_files": (
            validation_target_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_py_compile_candidate_files": (
            py_compile_candidate_files
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_executed": bool(
            validation_executed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_passed": bool(
            validation_passed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_failed": bool(
            validation_failed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_validation_timeout": bool(
            validation_timeout
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_py_compile_results": (
            py_compile_results
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_cycle_status": (
            cycle_status
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_cycle_passed": bool(
            cycle_passed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_cycle_failed": bool(
            cycle_failed
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_cycle_blocked": bool(
            cycle_blocked
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_cycle_block_reason": (
            cycle_block_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_commit_candidate": bool(
            commit_candidate
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_fix_candidate": bool(
            fix_candidate
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_rollback_candidate": bool(
            rollback_candidate
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_rollback_reason": (
            rollback_reason
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_human_review_required": bool(
            local_human_review_required
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_next_action": (
            next_action
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_post_rollback_fix_reentry_result_assimilation_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_execution_status,
                    normalized_execution_block_reason,
                    normalized_execution_source,
                    normalized_result_assimilation_source,
                    normalized_result_next_stage,
                    normalized_execution_next_action,
                    normalized_checkpoint_status,
                    normalized_checkpoint_next_action,
                    normalized_propagation_status,
                    normalized_codex_reentry_invocation_status,
                    normalized_codex_write_execution_status,
                    normalized_codex_write_result_status,
                    _normalize_text(execution_source, default=""),
                    _normalize_text(execution_sandbox, default=""),
                    str(normalized_max_invocations),
                    str(normalized_invocations_attempted),
                    str(normalized_invocations_completed),
                    "execution_not_allowed" if not execution_allowed else "",
                    "execution_not_completed" if not execution_completed else "",
                    "execution_human_review_required" if execution_human_review_required else "",
                    "result_not_ready_for_assimilation" if not result_ready_for_assimilation else "",
                    "prompt_path_not_fixed" if normalized_prompt_path != fixed_prompt_path else "",
                    "prompt_kind_not_fix" if normalized_prompt_kind != "fix" else "",
                    "reused_invocation_path_false" if not reused_invocation_path else "",
                    "command_missing" if not normalized_command else "",
                    "exit_code_missing" if _as_int(exit_code, default=-1) == -1 else "",
                    *missing_inputs,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_commit_tag_readiness_state(
    *,
    repository_path: str,
    source_status: str,
    authoritative_source_kind: str,
    authoritative_source_selected: bool,
    source_result_class: str,
    source_prompt_kind: str,
    source_prompt_path: str,
    source_changed_files: list[str] | None,
    source_changed_files_count: int,
    expected_changed_files: list[str] | None,
    allowed_changed_files: list[str] | None,
    unexpected_changed_files: list[str] | None,
    forbidden_changed_files: list[str] | None,
    too_many_changed_files: bool,
    safe_for_validation_routing: bool,
    validation_routing_candidate: bool,
    validation_routing_block_reason: str,
    validation_executed: bool,
    validation_passed: bool,
    validation_failed: bool,
    validation_timeout: bool,
    cycle_status: str,
    cycle_passed: bool,
    cycle_failed: bool,
    cycle_blocked: bool,
    commit_candidate: bool,
    rollback_candidate: bool,
    source_human_review_required: bool,
    prompt192_execution_status: str,
    prompt191_checkpoint_status: str,
    rollback_result_assimilation_status: str,
    bounded_continuation_status: str,
    source_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "commit_tag_readiness_allowed",
        "commit_tag_readiness_blocked",
        "commit_tag_readiness_blocked_manual_review",
        "commit_tag_readiness_blocked_unsafe_changes",
        "commit_tag_readiness_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_commit_tag_execution",
        "manual_review_required",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    fixed_prompt_path = "/tmp/codex-local-runner-decision/generated_fix_prompt.txt"
    commit_message = "Prompt193 post-rollback fix reentry validation passed"
    tag_name = "prompt193-post-rollback-fix-reentry-validated"
    runtime_posture = [
        "prompt194_commit_tag_readiness",
        "metadata_only_readiness_gate",
        "no_git_stage",
        "no_git_commit",
        "no_git_tag",
        "no_push",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_loop",
    ]

    normalized_repository_path = _normalize_text(repository_path, default="")
    normalized_source_status = _normalize_text(source_status, default="insufficient_truth")
    normalized_authoritative_source_kind = _normalize_text(
        authoritative_source_kind,
        default="none",
    )
    normalized_source_result_class = _normalize_text(source_result_class, default="")
    normalized_source_prompt_kind = _normalize_text(source_prompt_kind, default="none")
    normalized_source_prompt_path = _normalize_text(source_prompt_path, default="")
    normalized_source_changed_files = _normalize_string_list(source_changed_files or [])
    normalized_source_changed_files_count = _as_non_negative_int(
        source_changed_files_count,
        default=len(normalized_source_changed_files),
    )
    normalized_expected_changed_files = _normalize_string_list(expected_changed_files or [])
    normalized_allowed_changed_files = _normalize_string_list(allowed_changed_files or [])
    normalized_unexpected_changed_files = _normalize_string_list(
        unexpected_changed_files or []
    )
    normalized_forbidden_changed_files = _normalize_string_list(forbidden_changed_files or [])
    normalized_validation_routing_block_reason = _normalize_text(
        validation_routing_block_reason,
        default="",
    )
    normalized_cycle_status = _normalize_text(cycle_status, default="insufficient_truth")
    normalized_prompt192_execution_status = _normalize_text(
        prompt192_execution_status,
        default="insufficient_truth",
    )
    normalized_prompt191_checkpoint_status = _normalize_text(
        prompt191_checkpoint_status,
        default="insufficient_truth",
    )
    normalized_rollback_result_assimilation_status = _normalize_text(
        rollback_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_bounded_continuation_status = _normalize_text(
        bounded_continuation_status,
        default="insufficient_truth",
    )
    normalized_source_next_action = _normalize_text(source_next_action, default="")

    status = "commit_tag_readiness_blocked_insufficient_truth"
    commit_readiness_allowed = False
    commit_readiness_block_reason = "blocked_insufficient_commit_readiness_truth"
    tag_readiness_allowed = False
    tag_readiness_block_reason = "blocked_insufficient_commit_readiness_truth"
    commit_source = "none"
    commit_source_status = normalized_source_status
    commit_source_cycle_status = normalized_cycle_status
    commit_source_validation_passed = bool(validation_passed)
    commit_source_cycle_passed = bool(cycle_passed)
    local_commit_candidate = False
    tag_candidate = False
    commit_files: list[str] = []
    git_add_allowed_files: list[str] = []
    git_commit_allowed_next = False
    git_tag_allowed_next = False
    should_stage = False
    should_commit = False
    should_tag = False
    should_push = False
    should_invoke_codex = False
    should_execute_rollback = False
    local_human_review_required = bool(source_human_review_required)
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    def _is_unsafe_commit_file(path_text: str) -> bool:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            return True
        if normalized_path.startswith("/") or normalized_path.startswith("../"):
            return True
        if "/../" in normalized_path:
            return True
        lowered = normalized_path.lower()
        if normalized_path.startswith(".git/"):
            return True
        if normalized_path.startswith("tmp/") or normalized_path.startswith(".cache/"):
            return True
        if normalized_path.startswith("__pycache__/") or "/__pycache__/" in normalized_path:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered == ".env" or lowered.startswith(".env.") or "/.env" in lowered:
            return True
        if lowered.endswith(".pem") or lowered.endswith(".key"):
            return True

        repository_path_obj = Path(normalized_repository_path) if normalized_repository_path else None
        if repository_path_obj is not None:
            candidate = repository_path_obj / normalized_path
            try:
                candidate_resolved = candidate.resolve()
                repository_resolved = repository_path_obj.resolve()
                candidate_resolved.relative_to(repository_resolved)
            except (OSError, ValueError):
                return True
            if candidate.exists():
                if candidate.is_symlink() or candidate.is_dir():
                    return True
        return False

    safe_allowed_changed_files = sorted(
        set(
            path
            for path in normalized_allowed_changed_files
            if path in set(normalized_source_changed_files)
        )
    )
    unsafe_commit_files = _serialize_required_signals(
        [path for path in safe_allowed_changed_files if _is_unsafe_commit_file(path)]
    )
    commit_files = [path for path in safe_allowed_changed_files if path not in unsafe_commit_files]
    commit_file_count = len(commit_files)

    authoritative_source_ready = bool(
        normalized_source_status == "post_rollback_fix_reentry_result_validation_passed"
        and bool(commit_candidate)
        and bool(cycle_passed)
        and bool(validation_passed)
        and bool(validation_executed)
        and bool(authoritative_source_selected)
        and normalized_source_prompt_kind == "fix"
        and normalized_source_prompt_path == fixed_prompt_path
        and not bool(source_human_review_required)
        and not bool(rollback_candidate)
        and not bool(cycle_blocked)
        and not bool(cycle_failed)
    )

    commit_source = (
        "prompt193_post_rollback_fix_reentry_result_assimilation"
        if authoritative_source_ready
        else "none"
    )

    block_reason_order: list[tuple[bool, str]] = [
        (not authoritative_source_ready, "blocked_commit_source_not_prompt193"),
        (not bool(commit_candidate), "blocked_commit_candidate_false"),
        (not bool(validation_passed), "blocked_validation_not_passed"),
        (not bool(validation_executed), "blocked_validation_not_executed"),
        (not bool(cycle_passed), "blocked_cycle_not_passed"),
        (bool(source_human_review_required), "blocked_human_review_required"),
        (bool(rollback_candidate), "blocked_rollback_candidate_present"),
        (bool(normalized_unexpected_changed_files), "blocked_unexpected_changed_files"),
        (bool(normalized_forbidden_changed_files), "blocked_forbidden_changed_files"),
        (bool(too_many_changed_files), "blocked_too_many_changed_files"),
        (not bool(normalized_source_changed_files), "blocked_no_changed_files"),
        (bool(unsafe_commit_files), "blocked_unsafe_commit_files"),
        (commit_file_count > 20, "blocked_file_count_exceeds_limit"),
        (normalized_source_prompt_path != fixed_prompt_path, "blocked_prompt_path_mismatch"),
        (True, "blocked_insufficient_commit_readiness_truth"),
    ]
    first_block_reason = _first_true_reason(
        block_reason_order,
        default="blocked_insufficient_commit_readiness_truth",
    )

    allow_commit_readiness = bool(
        authoritative_source_ready
        and bool(validation_passed)
        and bool(cycle_passed)
        and bool(commit_candidate)
        and bool(safe_for_validation_routing)
        and bool(validation_routing_candidate)
        and bool(normalized_source_changed_files)
        and bool(commit_files)
        and not bool(normalized_unexpected_changed_files)
        and not bool(normalized_forbidden_changed_files)
        and not bool(too_many_changed_files)
        and not bool(rollback_candidate)
        and not bool(source_human_review_required)
        and not bool(unsafe_commit_files)
        and commit_file_count <= 20
        and commit_files == safe_allowed_changed_files
    )

    if allow_commit_readiness:
        status = "commit_tag_readiness_allowed"
        commit_readiness_allowed = True
        commit_readiness_block_reason = ""
        tag_readiness_allowed = True
        tag_readiness_block_reason = ""
        local_commit_candidate = True
        tag_candidate = True
        git_add_allowed_files = list(commit_files)
        git_commit_allowed_next = True
        git_tag_allowed_next = True
        local_human_review_required = False
        next_action = "prepare_commit_tag_execution"
    else:
        local_commit_candidate = False
        tag_candidate = False
        git_add_allowed_files = []
        git_commit_allowed_next = False
        git_tag_allowed_next = False
        commit_readiness_block_reason = first_block_reason
        tag_readiness_block_reason = first_block_reason
        if bool(source_human_review_required):
            status = "commit_tag_readiness_blocked_manual_review"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif first_block_reason in {
            "blocked_unexpected_changed_files",
            "blocked_forbidden_changed_files",
            "blocked_too_many_changed_files",
            "blocked_unsafe_commit_files",
            "blocked_no_changed_files",
        }:
            status = "commit_tag_readiness_blocked_unsafe_changes"
            local_human_review_required = True
            next_action = "manual_review_required"
        elif first_block_reason in {
            "blocked_commit_source_not_prompt193",
            "blocked_validation_not_passed",
            "blocked_validation_not_executed",
            "blocked_cycle_not_passed",
            "blocked_prompt_path_mismatch",
            "blocked_insufficient_commit_readiness_truth",
        }:
            status = "commit_tag_readiness_blocked_insufficient_truth"
            local_human_review_required = True
            next_action = "wait_for_more_truth"
        else:
            status = "commit_tag_readiness_blocked"
            local_human_review_required = True
            next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if status == "insufficient_truth":
        commit_readiness_allowed = False
        tag_readiness_allowed = False
        local_commit_candidate = False
        tag_candidate = False
        git_add_allowed_files = []
        git_commit_allowed_next = False
        git_tag_allowed_next = False
        should_stage = False
        should_commit = False
        should_tag = False
        should_push = False
        should_invoke_codex = False
        should_execute_rollback = False

    return {
        "project_browser_autonomous_commit_tag_readiness_status": status,
        "project_browser_autonomous_commit_tag_readiness_commit_readiness_allowed": bool(
            commit_readiness_allowed
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_readiness_block_reason": (
            commit_readiness_block_reason
        ),
        "project_browser_autonomous_commit_tag_readiness_tag_readiness_allowed": bool(
            tag_readiness_allowed
        ),
        "project_browser_autonomous_commit_tag_readiness_tag_readiness_block_reason": (
            tag_readiness_block_reason
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_source": commit_source,
        "project_browser_autonomous_commit_tag_readiness_commit_source_status": commit_source_status,
        "project_browser_autonomous_commit_tag_readiness_commit_source_cycle_status": (
            commit_source_cycle_status
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_source_validation_passed": bool(
            commit_source_validation_passed
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_source_cycle_passed": bool(
            commit_source_cycle_passed
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_candidate": bool(
            local_commit_candidate
        ),
        "project_browser_autonomous_commit_tag_readiness_tag_candidate": bool(tag_candidate),
        "project_browser_autonomous_commit_tag_readiness_commit_files": commit_files,
        "project_browser_autonomous_commit_tag_readiness_commit_file_count": int(commit_file_count),
        "project_browser_autonomous_commit_tag_readiness_expected_changed_files": (
            normalized_expected_changed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_allowed_changed_files": (
            normalized_allowed_changed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_unexpected_changed_files": (
            normalized_unexpected_changed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_forbidden_changed_files": (
            normalized_forbidden_changed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_too_many_changed_files": bool(
            too_many_changed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_commit_message": commit_message,
        "project_browser_autonomous_commit_tag_readiness_tag_name": tag_name,
        "project_browser_autonomous_commit_tag_readiness_git_add_allowed_files": (
            git_add_allowed_files
        ),
        "project_browser_autonomous_commit_tag_readiness_git_commit_allowed_next": bool(
            git_commit_allowed_next
        ),
        "project_browser_autonomous_commit_tag_readiness_git_tag_allowed_next": bool(
            git_tag_allowed_next
        ),
        "project_browser_autonomous_commit_tag_readiness_should_stage": bool(should_stage),
        "project_browser_autonomous_commit_tag_readiness_should_commit": bool(should_commit),
        "project_browser_autonomous_commit_tag_readiness_should_tag": bool(should_tag),
        "project_browser_autonomous_commit_tag_readiness_should_push": bool(should_push),
        "project_browser_autonomous_commit_tag_readiness_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_commit_tag_readiness_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_commit_tag_readiness_human_review_required": bool(
            local_human_review_required
        ),
        "project_browser_autonomous_commit_tag_readiness_next_action": next_action,
        "project_browser_autonomous_commit_tag_readiness_runtime_posture": runtime_posture,
        "project_browser_autonomous_commit_tag_readiness_missing_inputs": _serialize_required_signals(
            [
                normalized_source_status,
                normalized_authoritative_source_kind,
                normalized_source_result_class,
                normalized_source_prompt_kind,
                normalized_source_prompt_path,
                normalized_validation_routing_block_reason,
                normalized_cycle_status,
                normalized_prompt192_execution_status,
                normalized_prompt191_checkpoint_status,
                normalized_rollback_result_assimilation_status,
                normalized_bounded_continuation_status,
                normalized_source_next_action,
                "authoritative_source_not_selected" if not authoritative_source_selected else "",
                "safe_for_validation_routing_false" if not safe_for_validation_routing else "",
                "validation_routing_candidate_false" if not validation_routing_candidate else "",
                "validation_failed_true" if validation_failed else "",
                "validation_timeout_true" if validation_timeout else "",
                "unsafe_commit_files_present" if unsafe_commit_files else "",
                *missing_inputs,
            ]
        ),
    }


def _build_project_browser_autonomous_commit_tag_execution_state(
    *,
    repository_path: str,
    readiness_status: str,
    commit_readiness_allowed: bool,
    commit_readiness_block_reason: str,
    tag_readiness_allowed: bool,
    tag_readiness_block_reason: str,
    commit_source: str,
    commit_source_status: str,
    commit_source_cycle_status: str,
    commit_source_validation_passed: bool,
    commit_source_cycle_passed: bool,
    commit_candidate: bool,
    tag_candidate: bool,
    commit_files: list[str] | None,
    commit_file_count: int,
    expected_changed_files: list[str] | None,
    allowed_changed_files: list[str] | None,
    unexpected_changed_files: list[str] | None,
    forbidden_changed_files: list[str] | None,
    too_many_changed_files: bool,
    commit_message: str,
    tag_name: str,
    git_add_allowed_files: list[str] | None,
    git_commit_allowed_next: bool,
    git_tag_allowed_next: bool,
    readiness_should_stage: bool,
    readiness_should_commit: bool,
    readiness_should_tag: bool,
    readiness_should_push: bool,
    readiness_should_invoke_codex: bool,
    readiness_should_execute_rollback: bool,
    readiness_human_review_required: bool,
    readiness_next_action: str,
    source_assimilation_status: str,
    source_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "commit_tag_execution_completed",
        "commit_tag_execution_blocked_not_allowed",
        "commit_tag_execution_blocked_manual_review",
        "commit_tag_execution_blocked_unsafe_files",
        "commit_tag_execution_blocked_diff_check_failed",
        "commit_tag_execution_blocked_tag_collision",
        "commit_tag_execution_blocked_insufficient_truth",
        "commit_tag_execution_failed_git_add",
        "commit_tag_execution_failed_git_commit",
        "commit_tag_execution_failed_git_tag",
        "commit_tag_execution_partial_commit_tag_failed",
        "commit_tag_execution_timeout",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "commit_tag_completed",
        "manual_review_required",
        "no_commit_tag_execution",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    command_timeout_seconds = 15.0
    runtime_posture = [
        "prompt195_commit_tag_execution",
        "bounded_git_mutation",
        "explicit_git_add_file_list_only",
        "no_git_add_all",
        "no_push",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_loop",
    ]

    normalized_repo = _normalize_text(repository_path, default="")
    normalized_readiness_status = _normalize_text(readiness_status, default="insufficient_truth")
    normalized_commit_readiness_block_reason = _normalize_text(
        commit_readiness_block_reason,
        default="",
    )
    normalized_tag_readiness_block_reason = _normalize_text(
        tag_readiness_block_reason,
        default="",
    )
    normalized_commit_source = _normalize_text(commit_source, default="")
    normalized_commit_source_status = _normalize_text(
        commit_source_status,
        default="insufficient_truth",
    )
    normalized_commit_source_cycle_status = _normalize_text(
        commit_source_cycle_status,
        default="insufficient_truth",
    )
    normalized_commit_files = _normalize_string_list(commit_files or [])
    normalized_expected_changed_files = _normalize_string_list(expected_changed_files or [])
    normalized_allowed_changed_files = _normalize_string_list(allowed_changed_files or [])
    normalized_unexpected_changed_files = _normalize_string_list(unexpected_changed_files or [])
    normalized_forbidden_changed_files = _normalize_string_list(forbidden_changed_files or [])
    normalized_commit_message = _normalize_text(commit_message, default="")
    normalized_tag_name = _normalize_text(tag_name, default="")
    normalized_git_add_allowed_files = _normalize_string_list(git_add_allowed_files or [])
    normalized_readiness_next_action = _normalize_text(readiness_next_action, default="")
    normalized_source_assimilation_status = _normalize_text(
        source_assimilation_status,
        default="insufficient_truth",
    )
    normalized_source_next_action = _normalize_text(source_next_action, default="")
    normalized_commit_file_count = _as_non_negative_int(
        commit_file_count,
        default=len(normalized_commit_files),
    )

    status = "commit_tag_execution_blocked_insufficient_truth"
    execution_allowed = False
    execution_attempted = False
    execution_completed = False
    execution_failed = False
    execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
    tag_collision_checked = False
    tag_collision_detected = False
    pre_commit_diff_check_attempted = False
    pre_commit_diff_check_passed = False
    pre_commit_git_status_short = ""
    post_commit_git_status_short = ""
    git_add_attempted = False
    git_add_completed = False
    git_commit_attempted = False
    git_commit_completed = False
    git_tag_attempted = False
    git_tag_completed = False
    commit_hash = ""
    command_results: list[dict[str, Any]] = []
    exit_code = 0
    timed_out = False
    should_push = False
    should_invoke_codex = False
    should_execute_rollback = False
    human_review_required = bool(readiness_human_review_required)
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    def _contains_parent_traversal(path_text: str) -> bool:
        return ".." in PurePosixPath(path_text.replace("\\", "/")).parts

    def _is_sensitive_or_forbidden(path_text: str) -> bool:
        lowered = path_text.lower()
        if path_text.startswith(".git/"):
            return True
        if path_text.startswith("__pycache__/") or "/__pycache__/" in path_text:
            return True
        if lowered.endswith(".pyc"):
            return True
        if lowered.startswith(".env") or "/.env" in lowered:
            return True
        if any(token in lowered for token in ("secret", "token", "credential", ".pem", ".key")):
            return True
        if path_text.startswith(".cache/") or path_text.startswith("tmp/"):
            return True
        return False

    repo_root: Path | None = None
    if normalized_repo:
        try:
            repo_root = Path(normalized_repo).resolve()
        except OSError:
            repo_root = None

    def _validate_commit_file(path_text: str) -> tuple[bool, str]:
        normalized_path = _normalize_text(path_text, default="").replace("\\", "/")
        if not normalized_path:
            return False, "path_missing"
        if normalized_path.startswith("/") or _contains_parent_traversal(normalized_path):
            return False, "path_out_of_repo"
        if _is_sensitive_or_forbidden(normalized_path):
            return False, "path_forbidden"
        if repo_root is None:
            return False, "repo_root_missing"
        candidate = repo_root / normalized_path
        try:
            resolved = candidate.resolve(strict=False)
            resolved.relative_to(repo_root)
        except (OSError, ValueError):
            return False, "path_out_of_repo"
        if not candidate.exists():
            return False, "path_missing"
        if candidate.is_symlink():
            return False, "path_symlink"
        if candidate.is_dir():
            return False, "path_directory"
        return True, ""

    commit_files_match = normalized_commit_files == normalized_git_add_allowed_files
    commit_files_set = set(normalized_commit_files)
    base_not_allowed_reason = _first_true_reason(
        [
            (
                normalized_readiness_status != "commit_tag_readiness_allowed"
                or not bool(commit_readiness_allowed)
                or not bool(tag_readiness_allowed)
                or not bool(git_commit_allowed_next)
                or not bool(git_tag_allowed_next),
                "blocked_readiness_not_allowed",
            ),
            (bool(readiness_human_review_required), "blocked_manual_review_required"),
            (bool(readiness_should_push), "blocked_push_requested_unexpectedly"),
            (bool(readiness_should_invoke_codex), "blocked_codex_invocation_requested_unexpectedly"),
            (bool(readiness_should_execute_rollback), "blocked_rollback_requested_unexpectedly"),
            (
                bool(readiness_should_stage) or bool(readiness_should_commit) or bool(readiness_should_tag),
                "blocked_insufficient_commit_tag_execution_truth",
            ),
            (not normalized_commit_files, "blocked_no_commit_files"),
            (normalized_commit_file_count > 20, "blocked_file_count_exceeds_limit"),
            (not commit_files_match, "blocked_commit_files_mismatch"),
            (bool(normalized_unexpected_changed_files), "blocked_unexpected_changed_files"),
            (bool(normalized_forbidden_changed_files), "blocked_forbidden_changed_files"),
            (bool(too_many_changed_files), "blocked_too_many_changed_files"),
            (not normalized_commit_message, "blocked_empty_commit_message"),
            (not normalized_tag_name, "blocked_empty_tag_name"),
            (True, "blocked_insufficient_commit_tag_execution_truth"),
        ],
        default="blocked_insufficient_commit_tag_execution_truth",
    )

    allow_base = bool(
        normalized_readiness_status == "commit_tag_readiness_allowed"
        and bool(commit_readiness_allowed)
        and bool(tag_readiness_allowed)
        and bool(git_commit_allowed_next)
        and bool(git_tag_allowed_next)
        and bool(commit_candidate)
        and bool(tag_candidate)
        and bool(normalized_commit_files)
        and commit_files_match
        and normalized_commit_file_count <= 20
        and not bool(normalized_unexpected_changed_files)
        and not bool(normalized_forbidden_changed_files)
        and not bool(too_many_changed_files)
        and not bool(readiness_human_review_required)
        and not bool(readiness_should_stage)
        and not bool(readiness_should_commit)
        and not bool(readiness_should_tag)
        and not bool(readiness_should_push)
        and not bool(readiness_should_invoke_codex)
        and not bool(readiness_should_execute_rollback)
        and bool(normalized_commit_message)
        and bool(normalized_tag_name)
    )

    if not allow_base:
        execution_allowed = False
        execution_block_reason = base_not_allowed_reason
        if base_not_allowed_reason == "blocked_manual_review_required":
            status = "commit_tag_execution_blocked_manual_review"
            human_review_required = True
            next_action = "manual_review_required"
        elif base_not_allowed_reason in {
            "blocked_commit_files_mismatch",
            "blocked_unexpected_changed_files",
            "blocked_forbidden_changed_files",
            "blocked_too_many_changed_files",
        }:
            status = "commit_tag_execution_blocked_unsafe_files"
            human_review_required = True
            next_action = "manual_review_required"
        elif base_not_allowed_reason in {
            "blocked_readiness_not_allowed",
            "blocked_insufficient_commit_tag_execution_truth",
        }:
            status = "commit_tag_execution_blocked_not_allowed"
            human_review_required = bool(readiness_human_review_required)
            next_action = "no_commit_tag_execution"
        else:
            status = "commit_tag_execution_blocked_insufficient_truth"
            human_review_required = True
            next_action = "wait_for_more_truth"
    elif not normalized_repo or repo_root is None:
        status = "commit_tag_execution_blocked_insufficient_truth"
        execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
        human_review_required = True
        next_action = "wait_for_more_truth"
        missing_inputs.append("repository_path")
    else:
        execution_allowed = True
        human_review_required = False
        next_action = "manual_review_required"

        unsafe_files: list[str] = []
        for commit_file in normalized_commit_files:
            valid, _ = _validate_commit_file(commit_file)
            if not valid:
                unsafe_files.append(commit_file)
        if unsafe_files:
            status = "commit_tag_execution_blocked_unsafe_files"
            execution_allowed = False
            execution_block_reason = "blocked_unsafe_commit_files"
            human_review_required = True
            next_action = "manual_review_required"
        else:
            try:
                status_cp = _run_git(normalized_repo, ["status", "--short"], timeout_seconds=10.0)
                pre_commit_git_status_short = _normalize_text(status_cp.stdout, default="")
            except subprocess.TimeoutExpired:
                status_cp = None
                pre_commit_git_status_short = ""
                timed_out = True
                exit_code = -1
                status = "commit_tag_execution_timeout"
                execution_allowed = False
                execution_failed = True
                execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                human_review_required = True
                next_action = "manual_review_required"
            except OSError:
                status_cp = None
                pre_commit_git_status_short = ""
                status = "commit_tag_execution_blocked_insufficient_truth"
                execution_allowed = False
                execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                human_review_required = True
                next_action = "wait_for_more_truth"

            if execution_allowed and status_cp is not None:
                if status_cp.returncode != 0:
                    status = "commit_tag_execution_blocked_insufficient_truth"
                    execution_allowed = False
                    execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                    exit_code = int(status_cp.returncode)
                    human_review_required = True
                    next_action = "wait_for_more_truth"
                else:
                    changed_paths: set[str] = set()
                    staged_paths: set[str] = set()
                    for line in pre_commit_git_status_short.splitlines():
                        path = _normalize_text(_parse_git_status_path(line), default="")
                        if not path:
                            continue
                        changed_paths.add(path)
                        status_code = line[:2] if len(line) >= 2 else ""
                        if status_code and status_code[0] not in {" ", "?"}:
                            staged_paths.add(path)
                    if not all(path in changed_paths for path in normalized_commit_files):
                        status = "commit_tag_execution_blocked_unsafe_files"
                        execution_allowed = False
                        execution_block_reason = "blocked_unsafe_commit_files"
                        human_review_required = True
                        next_action = "manual_review_required"
                    elif any(path not in commit_files_set for path in staged_paths):
                        status = "commit_tag_execution_blocked_unsafe_files"
                        execution_allowed = False
                        execution_block_reason = "blocked_unsafe_commit_files"
                        human_review_required = True
                        next_action = "manual_review_required"

        if execution_allowed:
            pre_commit_diff_check_attempted = True
            try:
                diff_cp = _run_git(normalized_repo, ["diff", "--check"], timeout_seconds=10.0)
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "diff", "--check"],
                        "exit_code": int(diff_cp.returncode),
                        "timed_out": False,
                        "status": "completed" if diff_cp.returncode == 0 else "failed",
                        "stdout_excerpt": _normalize_text(diff_cp.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(diff_cp.stderr, default="")[:400],
                    }
                )
                if diff_cp.returncode != 0:
                    status = "commit_tag_execution_blocked_diff_check_failed"
                    execution_allowed = False
                    execution_block_reason = "blocked_diff_check_failed"
                    pre_commit_diff_check_passed = False
                    exit_code = int(diff_cp.returncode)
                    human_review_required = True
                    next_action = "manual_review_required"
                else:
                    pre_commit_diff_check_passed = True
            except subprocess.TimeoutExpired as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "diff", "--check"],
                        "exit_code": -1,
                        "timed_out": True,
                        "status": "timeout",
                        "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                    }
                )
                status = "commit_tag_execution_timeout"
                execution_allowed = False
                execution_failed = True
                execution_block_reason = "blocked_diff_check_failed"
                timed_out = True
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"
            except OSError as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "diff", "--check"],
                        "exit_code": -1,
                        "timed_out": False,
                        "status": "execution_error",
                        "stderr_excerpt": f"{type(exc).__name__}",
                    }
                )
                status = "commit_tag_execution_blocked_insufficient_truth"
                execution_allowed = False
                execution_block_reason = "blocked_diff_check_failed"
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"

        if execution_allowed:
            tag_collision_checked = True
            try:
                tag_check_cp = _run_git(
                    normalized_repo,
                    ["tag", "--list", normalized_tag_name],
                    timeout_seconds=10.0,
                )
                listed_tags = _normalize_string_list(
                    (tag_check_cp.stdout or "").splitlines(),
                    sort_items=False,
                )
                tag_collision_detected = (
                    tag_check_cp.returncode == 0 and normalized_tag_name in listed_tags
                )
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "tag", "--list", normalized_tag_name],
                        "exit_code": int(tag_check_cp.returncode),
                        "timed_out": False,
                        "status": (
                            "completed"
                            if tag_check_cp.returncode == 0 and not tag_collision_detected
                            else "failed"
                        ),
                        "stdout_excerpt": _normalize_text(tag_check_cp.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(tag_check_cp.stderr, default="")[:400],
                    }
                )
                if tag_check_cp.returncode != 0:
                    status = "commit_tag_execution_blocked_insufficient_truth"
                    execution_allowed = False
                    execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                    exit_code = int(tag_check_cp.returncode)
                    human_review_required = True
                    next_action = "manual_review_required"
                elif tag_collision_detected:
                    status = "commit_tag_execution_blocked_tag_collision"
                    execution_allowed = False
                    execution_block_reason = "blocked_tag_collision"
                    human_review_required = True
                    next_action = "manual_review_required"
            except subprocess.TimeoutExpired as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "tag", "--list", normalized_tag_name],
                        "exit_code": -1,
                        "timed_out": True,
                        "status": "timeout",
                        "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                    }
                )
                status = "commit_tag_execution_timeout"
                execution_allowed = False
                execution_failed = True
                execution_block_reason = "blocked_tag_collision"
                timed_out = True
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"
            except OSError as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, "tag", "--list", normalized_tag_name],
                        "exit_code": -1,
                        "timed_out": False,
                        "status": "execution_error",
                        "stderr_excerpt": f"{type(exc).__name__}",
                    }
                )
                status = "commit_tag_execution_blocked_insufficient_truth"
                execution_allowed = False
                execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"

        if execution_allowed:
            execution_attempted = True

            add_args = ["add", "--", *normalized_commit_files]
            git_add_attempted = True
            try:
                add_cp = _run_git(normalized_repo, add_args, timeout_seconds=command_timeout_seconds)
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, *add_args],
                        "exit_code": int(add_cp.returncode),
                        "timed_out": False,
                        "status": "completed" if add_cp.returncode == 0 else "failed",
                        "stdout_excerpt": _normalize_text(add_cp.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(add_cp.stderr, default="")[:400],
                    }
                )
                if add_cp.returncode == 0:
                    git_add_completed = True
                else:
                    status = "commit_tag_execution_failed_git_add"
                    execution_failed = True
                    execution_block_reason = "git_add_failed"
                    exit_code = int(add_cp.returncode)
                    human_review_required = True
                    next_action = "manual_review_required"
            except subprocess.TimeoutExpired as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, *add_args],
                        "exit_code": -1,
                        "timed_out": True,
                        "status": "timeout",
                        "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                        "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                    }
                )
                status = "commit_tag_execution_timeout"
                execution_failed = True
                timed_out = True
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"
            except OSError as exc:
                command_results.append(
                    {
                        "command": ["git", "-C", normalized_repo, *add_args],
                        "exit_code": -1,
                        "timed_out": False,
                        "status": "execution_error",
                        "stderr_excerpt": f"{type(exc).__name__}",
                    }
                )
                status = "commit_tag_execution_failed_git_add"
                execution_failed = True
                execution_block_reason = "git_add_failed"
                exit_code = -1
                human_review_required = True
                next_action = "manual_review_required"

            if git_add_completed and not execution_failed and not timed_out:
                commit_args = [
                    "-c",
                    "user.name=Codex Local Runner",
                    "-c",
                    "user.email=codex-local-runner@example.com",
                    "commit",
                    "-m",
                    normalized_commit_message,
                ]
                git_commit_attempted = True
                try:
                    commit_cp = _run_git(
                        normalized_repo,
                        commit_args,
                        timeout_seconds=command_timeout_seconds,
                    )
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *commit_args],
                            "exit_code": int(commit_cp.returncode),
                            "timed_out": False,
                            "status": "completed" if commit_cp.returncode == 0 else "failed",
                            "stdout_excerpt": _normalize_text(commit_cp.stdout, default="")[:400],
                            "stderr_excerpt": _normalize_text(commit_cp.stderr, default="")[:400],
                        }
                    )
                    if commit_cp.returncode == 0:
                        git_commit_completed = True
                        try:
                            rev_cp = _run_git(
                                normalized_repo,
                                ["rev-parse", "HEAD"],
                                timeout_seconds=10.0,
                            )
                            command_results.append(
                                {
                                    "command": ["git", "-C", normalized_repo, "rev-parse", "HEAD"],
                                    "exit_code": int(rev_cp.returncode),
                                    "timed_out": False,
                                    "status": "completed" if rev_cp.returncode == 0 else "failed",
                                    "stdout_excerpt": _normalize_text(rev_cp.stdout, default="")[:400],
                                    "stderr_excerpt": _normalize_text(rev_cp.stderr, default="")[:400],
                                }
                            )
                            if rev_cp.returncode == 0:
                                commit_hash = _normalize_text(rev_cp.stdout, default="")
                        except (subprocess.TimeoutExpired, OSError):
                            commit_hash = ""
                    else:
                        status = "commit_tag_execution_failed_git_commit"
                        execution_failed = True
                        execution_block_reason = "git_commit_failed"
                        exit_code = int(commit_cp.returncode)
                        human_review_required = True
                        next_action = "manual_review_required"
                except subprocess.TimeoutExpired as exc:
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *commit_args],
                            "exit_code": -1,
                            "timed_out": True,
                            "status": "timeout",
                            "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                            "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                        }
                    )
                    status = "commit_tag_execution_timeout"
                    execution_failed = True
                    timed_out = True
                    exit_code = -1
                    human_review_required = True
                    next_action = "manual_review_required"
                except OSError as exc:
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *commit_args],
                            "exit_code": -1,
                            "timed_out": False,
                            "status": "execution_error",
                            "stderr_excerpt": f"{type(exc).__name__}",
                        }
                    )
                    status = "commit_tag_execution_failed_git_commit"
                    execution_failed = True
                    execution_block_reason = "git_commit_failed"
                    exit_code = -1
                    human_review_required = True
                    next_action = "manual_review_required"

            if git_commit_completed and not execution_failed and not timed_out:
                tag_args = [
                    "tag",
                    "-a",
                    normalized_tag_name,
                    "-m",
                    normalized_commit_message,
                ]
                git_tag_attempted = True
                try:
                    tag_cp = _run_git(normalized_repo, tag_args, timeout_seconds=command_timeout_seconds)
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *tag_args],
                            "exit_code": int(tag_cp.returncode),
                            "timed_out": False,
                            "status": "completed" if tag_cp.returncode == 0 else "failed",
                            "stdout_excerpt": _normalize_text(tag_cp.stdout, default="")[:400],
                            "stderr_excerpt": _normalize_text(tag_cp.stderr, default="")[:400],
                        }
                    )
                    if tag_cp.returncode == 0:
                        git_tag_completed = True
                    else:
                        status = "commit_tag_execution_partial_commit_tag_failed"
                        execution_failed = True
                        execution_block_reason = "git_tag_failed"
                        exit_code = int(tag_cp.returncode)
                        human_review_required = True
                        next_action = "manual_review_required"
                except subprocess.TimeoutExpired as exc:
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *tag_args],
                            "exit_code": -1,
                            "timed_out": True,
                            "status": "timeout",
                            "stdout_excerpt": _normalize_text(exc.stdout, default="")[:400],
                            "stderr_excerpt": _normalize_text(exc.stderr, default="")[:400],
                        }
                    )
                    status = "commit_tag_execution_timeout"
                    execution_failed = True
                    timed_out = True
                    exit_code = -1
                    human_review_required = True
                    next_action = "manual_review_required"
                except OSError as exc:
                    command_results.append(
                        {
                            "command": ["git", "-C", normalized_repo, *tag_args],
                            "exit_code": -1,
                            "timed_out": False,
                            "status": "execution_error",
                            "stderr_excerpt": f"{type(exc).__name__}",
                        }
                    )
                    status = "commit_tag_execution_failed_git_tag"
                    execution_failed = True
                    execution_block_reason = "git_tag_failed"
                    exit_code = -1
                    human_review_required = True
                    next_action = "manual_review_required"

            try:
                post_status_cp = _run_git(normalized_repo, ["status", "--short"], timeout_seconds=10.0)
                post_commit_git_status_short = _normalize_text(post_status_cp.stdout, default="")
            except (subprocess.TimeoutExpired, OSError):
                post_commit_git_status_short = ""

            if git_add_completed and git_commit_completed and git_tag_completed and not timed_out:
                status = "commit_tag_execution_completed"
                execution_completed = True
                execution_failed = False
                execution_block_reason = ""
                exit_code = 0
                human_review_required = False
                next_action = "commit_tag_completed"
            elif not execution_failed and not timed_out:
                status = "commit_tag_execution_blocked_insufficient_truth"
                execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
                execution_failed = True
                human_review_required = True
                next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if status == "insufficient_truth":
        execution_allowed = False
        execution_attempted = False
        execution_completed = False
        execution_failed = False
        execution_block_reason = "blocked_insufficient_commit_tag_execution_truth"
        should_push = False
        should_invoke_codex = False
        should_execute_rollback = False

    return {
        "project_browser_autonomous_commit_tag_execution_status": status,
        "project_browser_autonomous_commit_tag_execution_execution_allowed": bool(execution_allowed),
        "project_browser_autonomous_commit_tag_execution_execution_attempted": bool(
            execution_attempted
        ),
        "project_browser_autonomous_commit_tag_execution_execution_completed": bool(
            execution_completed
        ),
        "project_browser_autonomous_commit_tag_execution_execution_failed": bool(execution_failed),
        "project_browser_autonomous_commit_tag_execution_execution_block_reason": (
            execution_block_reason
        ),
        "project_browser_autonomous_commit_tag_execution_commit_source": normalized_commit_source,
        "project_browser_autonomous_commit_tag_execution_commit_files": normalized_commit_files,
        "project_browser_autonomous_commit_tag_execution_commit_file_count": int(
            normalized_commit_file_count
        ),
        "project_browser_autonomous_commit_tag_execution_commit_message": normalized_commit_message,
        "project_browser_autonomous_commit_tag_execution_tag_name": normalized_tag_name,
        "project_browser_autonomous_commit_tag_execution_tag_collision_checked": bool(
            tag_collision_checked
        ),
        "project_browser_autonomous_commit_tag_execution_tag_collision_detected": bool(
            tag_collision_detected
        ),
        "project_browser_autonomous_commit_tag_execution_pre_commit_diff_check_attempted": bool(
            pre_commit_diff_check_attempted
        ),
        "project_browser_autonomous_commit_tag_execution_pre_commit_diff_check_passed": bool(
            pre_commit_diff_check_passed
        ),
        "project_browser_autonomous_commit_tag_execution_pre_commit_git_status_short": (
            pre_commit_git_status_short
        ),
        "project_browser_autonomous_commit_tag_execution_post_commit_git_status_short": (
            post_commit_git_status_short
        ),
        "project_browser_autonomous_commit_tag_execution_git_add_attempted": bool(
            git_add_attempted
        ),
        "project_browser_autonomous_commit_tag_execution_git_add_completed": bool(
            git_add_completed
        ),
        "project_browser_autonomous_commit_tag_execution_git_commit_attempted": bool(
            git_commit_attempted
        ),
        "project_browser_autonomous_commit_tag_execution_git_commit_completed": bool(
            git_commit_completed
        ),
        "project_browser_autonomous_commit_tag_execution_git_tag_attempted": bool(
            git_tag_attempted
        ),
        "project_browser_autonomous_commit_tag_execution_git_tag_completed": bool(
            git_tag_completed
        ),
        "project_browser_autonomous_commit_tag_execution_commit_hash": commit_hash,
        "project_browser_autonomous_commit_tag_execution_command_results": command_results,
        "project_browser_autonomous_commit_tag_execution_exit_code": int(exit_code),
        "project_browser_autonomous_commit_tag_execution_timed_out": bool(timed_out),
        "project_browser_autonomous_commit_tag_execution_should_push": bool(should_push),
        "project_browser_autonomous_commit_tag_execution_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_commit_tag_execution_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_commit_tag_execution_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_commit_tag_execution_next_action": next_action,
        "project_browser_autonomous_commit_tag_execution_runtime_posture": runtime_posture,
        "project_browser_autonomous_commit_tag_execution_missing_inputs": _serialize_required_signals(
            [
                normalized_readiness_status,
                normalized_commit_source_status,
                normalized_commit_source_cycle_status,
                normalized_readiness_next_action,
                normalized_source_assimilation_status,
                normalized_source_next_action,
                normalized_commit_readiness_block_reason,
                normalized_tag_readiness_block_reason,
                str(int(bool(commit_source_validation_passed))),
                str(int(bool(commit_source_cycle_passed))),
                str(len(normalized_expected_changed_files)),
                str(len(normalized_allowed_changed_files)),
                "commit_files_empty" if not normalized_commit_files else "",
                "commit_files_mismatch" if not commit_files_match else "",
                "commit_candidate_false" if not commit_candidate else "",
                "tag_candidate_false" if not tag_candidate else "",
                "execution_not_allowed" if not execution_allowed and not execution_attempted else "",
                *missing_inputs,
            ]
        ),
    }


def _build_project_browser_autonomous_commit_tag_result_assimilation_state(
    *,
    execution_status: str,
    execution_attempted: bool,
    execution_completed: bool,
    execution_failed: bool,
    execution_block_reason: str,
    commit_source: str,
    commit_files: list[str] | None,
    commit_file_count: int,
    tag_name: str,
    post_commit_git_status_short: str,
    git_commit_completed: bool,
    git_tag_completed: bool,
    commit_hash: str,
    timed_out: bool,
    execution_human_review_required: bool,
    execution_next_action: str,
    readiness_status: str,
    readiness_next_action: str,
    source_assimilation_status: str,
    source_next_action: str,
    continuation_status: str,
    continuation_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "commit_tag_result_assimilation_completed",
        "commit_tag_result_assimilation_completed_with_unexpected_dirty",
        "commit_tag_result_assimilation_partial_commit_tag_failed",
        "commit_tag_result_assimilation_failed_git_add",
        "commit_tag_result_assimilation_failed_git_commit",
        "commit_tag_result_assimilation_failed_git_tag",
        "commit_tag_result_assimilation_timeout",
        "commit_tag_result_assimilation_blocked",
        "commit_tag_result_assimilation_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_next_cycle_or_github_readiness",
        "manual_review_required",
        "no_commit_tag_execution",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt196_commit_tag_result_assimilation",
        "metadata_only",
        "no_git_mutation",
        "no_push",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_loop",
    ]

    normalized_execution_status = _normalize_text(execution_status, default="insufficient_truth")
    normalized_execution_block_reason = _normalize_text(execution_block_reason, default="")
    normalized_commit_source = _normalize_text(commit_source, default="")
    normalized_commit_files = _normalize_string_list(commit_files or [])
    normalized_commit_file_count = _as_non_negative_int(
        commit_file_count,
        default=len(normalized_commit_files),
    )
    normalized_tag_name = _normalize_text(tag_name, default="")
    normalized_post_commit_git_status_short = _normalize_text(
        post_commit_git_status_short,
        default="",
    )
    normalized_commit_hash = _normalize_text(commit_hash, default="")
    normalized_execution_next_action = _normalize_text(execution_next_action, default="")
    normalized_readiness_status = _normalize_text(readiness_status, default="insufficient_truth")
    normalized_readiness_next_action = _normalize_text(readiness_next_action, default="")
    normalized_source_assimilation_status = _normalize_text(
        source_assimilation_status,
        default="insufficient_truth",
    )
    normalized_source_next_action = _normalize_text(source_next_action, default="")
    normalized_continuation_status = _normalize_text(
        continuation_status,
        default="insufficient_truth",
    )
    normalized_continuation_next_action = _normalize_text(continuation_next_action, default="")

    commit_tag_result_available = False
    commit_tag_result_selected = False
    commit_tag_result_class = "insufficient_truth"
    commit_tag_result_block_reason = "blocked_insufficient_commit_tag_result_truth"
    commit_completed = False
    tag_completed = False
    partial_commit_without_tag = False
    commit_failed = False
    tag_failed = False
    commit_tag_timeout = False
    commit_tag_blocked = False
    safe_post_commit_handoff = False
    post_commit_handoff_allowed = False
    post_commit_handoff_kind = "none"
    post_commit_handoff_source = ""
    should_prepare_next_cycle = False
    should_prepare_github_handoff = False
    should_push = False
    should_invoke_codex = False
    should_execute_rollback = False
    should_commit = False
    should_tag = False
    should_stop = True
    stop_reason = "insufficient_commit_tag_result_truth"
    human_review_required = True
    next_action = "manual_review_required"
    status = "commit_tag_result_assimilation_blocked_insufficient_truth"
    missing_inputs: list[str] = []

    post_commit_paths = _serialize_required_signals(
        [
            _normalize_text(_parse_git_status_path(line), default="")
            for line in normalized_post_commit_git_status_short.splitlines()
        ]
    )
    post_commit_dirty = bool(post_commit_paths)
    post_commit_expected_dirty_only = bool(
        post_commit_dirty
        and all(path in set(normalized_commit_files) for path in post_commit_paths)
    )

    authoritative_source_kind = "prompt195_commit_tag_execution"
    authoritative_source_valid = bool(
        normalized_execution_status
        and (
            bool(execution_attempted)
            or normalized_execution_status.startswith("commit_tag_execution_blocked")
        )
        and normalized_commit_source
    )

    if not authoritative_source_valid:
        status = "commit_tag_result_assimilation_blocked_insufficient_truth"
        commit_tag_result_available = False
        commit_tag_result_selected = False
        commit_tag_result_class = "insufficient_truth"
        commit_tag_result_block_reason = "blocked_insufficient_commit_tag_result_truth"
        human_review_required = True
        should_stop = True
        stop_reason = "insufficient_commit_tag_result_truth"
        next_action = "manual_review_required"
    elif (
        normalized_execution_status == "commit_tag_execution_completed"
        and bool(git_commit_completed)
        and bool(git_tag_completed)
        and bool(normalized_commit_hash)
        and bool(normalized_tag_name)
        and not bool(execution_human_review_required)
    ):
        status = "commit_tag_result_assimilation_completed"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "completed"
        commit_tag_result_block_reason = ""
        commit_completed = True
        tag_completed = True
        partial_commit_without_tag = False
        commit_failed = False
        tag_failed = False
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = True
        post_commit_handoff_allowed = True
        post_commit_handoff_kind = "post_commit_success"
        post_commit_handoff_source = authoritative_source_kind
        should_prepare_next_cycle = True
        should_prepare_github_handoff = False
        should_push = False
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        should_tag = False
        should_stop = False
        stop_reason = ""
        human_review_required = False
        next_action = "prepare_next_cycle_or_github_readiness"

        if post_commit_dirty and not post_commit_expected_dirty_only:
            status = "commit_tag_result_assimilation_completed_with_unexpected_dirty"
            commit_tag_result_class = "completed_unexpected_dirty"
            commit_tag_result_block_reason = "unexpected_dirty_after_commit_tag"
            safe_post_commit_handoff = False
            post_commit_handoff_allowed = False
            post_commit_handoff_kind = "none"
            post_commit_handoff_source = authoritative_source_kind
            should_prepare_next_cycle = False
            should_prepare_github_handoff = False
            should_stop = True
            stop_reason = "unexpected_dirty_after_commit_tag"
            human_review_required = True
            next_action = "manual_review_required"
    elif (
        normalized_execution_status == "commit_tag_execution_partial_commit_tag_failed"
        or (bool(git_commit_completed) and not bool(git_tag_completed))
    ):
        status = "commit_tag_result_assimilation_partial_commit_tag_failed"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "partial_commit_tag_failed"
        commit_tag_result_block_reason = "commit_completed_but_tag_failed"
        commit_completed = bool(git_commit_completed)
        tag_completed = False
        partial_commit_without_tag = True
        commit_failed = False
        tag_failed = True
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_prepare_next_cycle = False
        should_prepare_github_handoff = False
        should_push = False
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        should_tag = False
        should_stop = True
        stop_reason = "commit_completed_but_tag_failed"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_execution_status == "commit_tag_execution_failed_git_add":
        status = "commit_tag_result_assimilation_failed_git_add"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "failed_git_add"
        commit_tag_result_block_reason = "git_add_failed"
        commit_completed = False
        tag_completed = False
        partial_commit_without_tag = False
        commit_failed = True
        tag_failed = False
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_stop = True
        stop_reason = "git_add_failed"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_execution_status == "commit_tag_execution_failed_git_commit":
        status = "commit_tag_result_assimilation_failed_git_commit"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "failed_git_commit"
        commit_tag_result_block_reason = "git_commit_failed"
        commit_completed = False
        tag_completed = False
        partial_commit_without_tag = False
        commit_failed = True
        tag_failed = False
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_stop = True
        stop_reason = "git_commit_failed"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_execution_status == "commit_tag_execution_failed_git_tag":
        status = "commit_tag_result_assimilation_failed_git_tag"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "failed_git_tag"
        commit_tag_result_block_reason = "git_tag_failed"
        commit_completed = bool(git_commit_completed)
        tag_completed = False
        partial_commit_without_tag = bool(git_commit_completed)
        commit_failed = False
        tag_failed = True
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_stop = True
        stop_reason = "git_tag_failed"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_execution_status == "commit_tag_execution_timeout" or bool(timed_out):
        status = "commit_tag_result_assimilation_timeout"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "timeout"
        commit_tag_result_block_reason = "commit_tag_timeout"
        commit_completed = bool(git_commit_completed)
        tag_completed = bool(git_tag_completed)
        partial_commit_without_tag = bool(git_commit_completed and not git_tag_completed)
        commit_failed = bool(execution_failed)
        tag_failed = False
        commit_tag_timeout = True
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_stop = True
        stop_reason = "commit_tag_timeout"
        human_review_required = True
        next_action = "manual_review_required"
    elif normalized_execution_status.startswith("commit_tag_execution_blocked"):
        status = "commit_tag_result_assimilation_blocked"
        commit_tag_result_available = True
        commit_tag_result_selected = True
        commit_tag_result_class = "blocked"
        commit_tag_result_block_reason = (
            normalized_execution_block_reason or "commit_tag_execution_blocked"
        )
        commit_completed = bool(git_commit_completed)
        tag_completed = bool(git_tag_completed)
        partial_commit_without_tag = bool(git_commit_completed and not git_tag_completed)
        commit_failed = False
        tag_failed = False
        commit_tag_timeout = False
        commit_tag_blocked = True
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = authoritative_source_kind
        should_prepare_next_cycle = False
        should_prepare_github_handoff = False
        should_stop = bool(execution_human_review_required)
        stop_reason = normalized_execution_block_reason or "commit_tag_execution_blocked"
        human_review_required = bool(execution_human_review_required)
        next_action = (
            normalized_execution_next_action
            if normalized_execution_next_action
            else "manual_review_required"
        )
    else:
        status = "commit_tag_result_assimilation_blocked_insufficient_truth"
        commit_tag_result_available = False
        commit_tag_result_selected = False
        commit_tag_result_class = "insufficient_truth"
        commit_tag_result_block_reason = "blocked_insufficient_commit_tag_result_truth"
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        should_prepare_next_cycle = False
        should_prepare_github_handoff = False
        should_stop = True
        stop_reason = "insufficient_commit_tag_result_truth"
        human_review_required = True
        next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if status == "insufficient_truth":
        commit_tag_result_available = False
        commit_tag_result_selected = False
        commit_tag_result_class = "insufficient_truth"
        commit_tag_result_block_reason = "blocked_insufficient_commit_tag_result_truth"
        commit_completed = False
        tag_completed = False
        partial_commit_without_tag = False
        commit_failed = False
        tag_failed = False
        commit_tag_timeout = False
        commit_tag_blocked = False
        safe_post_commit_handoff = False
        post_commit_handoff_allowed = False
        post_commit_handoff_kind = "none"
        post_commit_handoff_source = ""
        should_prepare_next_cycle = False
        should_prepare_github_handoff = False
        should_stop = True
        stop_reason = "insufficient_commit_tag_result_truth"
        human_review_required = True
        should_push = False
        should_invoke_codex = False
        should_execute_rollback = False
        should_commit = False
        should_tag = False

    return {
        "project_browser_autonomous_commit_tag_result_assimilation_status": status,
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_result_available": bool(
            commit_tag_result_available
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_result_selected": bool(
            commit_tag_result_selected
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_result_class": (
            commit_tag_result_class
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_result_block_reason": (
            commit_tag_result_block_reason
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_completed": bool(
            commit_completed
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_tag_completed": bool(
            tag_completed
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_hash": normalized_commit_hash,
        "project_browser_autonomous_commit_tag_result_assimilation_tag_name": normalized_tag_name,
        "project_browser_autonomous_commit_tag_result_assimilation_commit_files": normalized_commit_files,
        "project_browser_autonomous_commit_tag_result_assimilation_commit_file_count": int(
            normalized_commit_file_count
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_git_status_short": (
            normalized_post_commit_git_status_short
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_dirty": bool(
            post_commit_dirty
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_expected_dirty_only": bool(
            post_commit_expected_dirty_only
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_partial_commit_without_tag": bool(
            partial_commit_without_tag
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_failed": bool(
            commit_failed
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_tag_failed": bool(
            tag_failed
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_timeout": bool(
            commit_tag_timeout
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_commit_tag_blocked": bool(
            commit_tag_blocked
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_safe_post_commit_handoff": bool(
            safe_post_commit_handoff
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_handoff_allowed": bool(
            post_commit_handoff_allowed
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_handoff_kind": (
            post_commit_handoff_kind
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_post_commit_handoff_source": (
            post_commit_handoff_source
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_prepare_next_cycle": bool(
            should_prepare_next_cycle
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_prepare_github_handoff": bool(
            should_prepare_github_handoff
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_push": bool(should_push),
        "project_browser_autonomous_commit_tag_result_assimilation_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_commit": bool(
            should_commit
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_should_tag": bool(should_tag),
        "project_browser_autonomous_commit_tag_result_assimilation_should_stop": bool(should_stop),
        "project_browser_autonomous_commit_tag_result_assimilation_stop_reason": stop_reason,
        "project_browser_autonomous_commit_tag_result_assimilation_human_review_required": bool(
            human_review_required
        ),
        "project_browser_autonomous_commit_tag_result_assimilation_next_action": next_action,
        "project_browser_autonomous_commit_tag_result_assimilation_runtime_posture": runtime_posture,
        "project_browser_autonomous_commit_tag_result_assimilation_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_execution_status,
                    normalized_execution_block_reason,
                    normalized_commit_source,
                    normalized_execution_next_action,
                    normalized_readiness_status,
                    normalized_readiness_next_action,
                    normalized_source_assimilation_status,
                    normalized_source_next_action,
                    normalized_continuation_status,
                    normalized_continuation_next_action,
                    "execution_not_attempted" if not execution_attempted else "",
                    "execution_not_completed" if not execution_completed else "",
                    "execution_failed_true" if execution_failed else "",
                    "tag_collision_detected" if False else "",
                    "commit_hash_missing_on_complete"
                    if (
                        normalized_execution_status == "commit_tag_execution_completed"
                        and not normalized_commit_hash
                    )
                    else "",
                    "tag_name_missing_on_complete"
                    if (
                        normalized_execution_status == "commit_tag_execution_completed"
                        and not normalized_tag_name
                    )
                    else "",
                    *missing_inputs,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_multi_cycle_controller_state(
    *,
    commit_tag_result_status: str,
    commit_tag_result_class: str,
    commit_tag_result_block_reason: str,
    commit_tag_result_handoff_allowed: bool,
    commit_tag_result_safe_handoff: bool,
    commit_tag_result_post_commit_dirty: bool,
    commit_tag_result_human_review_required: bool,
    commit_tag_result_stop_reason: str,
    commit_tag_result_next_action: str,
    commit_tag_result_should_prepare_next_cycle: bool,
    commit_tag_result_should_prepare_github_handoff: bool,
    commit_tag_result_commit_completed: bool,
    commit_tag_result_tag_completed: bool,
    commit_tag_result_should_stop: bool,
    commit_tag_execution_status: str,
    commit_tag_readiness_status: str,
    post_rollback_fix_reentry_result_status: str,
    post_rollback_fix_reentry_validation_passed: bool,
    post_rollback_fix_reentry_cycle_passed: bool,
    post_rollback_fix_reentry_commit_candidate: bool,
    post_rollback_fix_reentry_cycle_failed: bool,
    post_rollback_fix_reentry_cycle_blocked: bool,
    post_rollback_fix_reentry_rollback_candidate: bool,
    post_rollback_fix_reentry_human_review_required: bool,
    bounded_continuation_status: str,
    bounded_continuation_remaining_cycles: int,
    bounded_continuation_remaining_fix_attempts: int,
    bounded_continuation_human_review_required: bool,
    one_step_cycle_status: str,
    one_step_cycle_passed: bool,
    one_step_cycle_failed: bool,
    one_step_cycle_blocked: bool,
    one_step_cycle_human_review_required: bool,
    rollback_result_status: str,
    rollback_result_human_review_required: bool,
    post_rollback_continuation_status: str,
    post_rollback_continuation_human_review_required: bool,
    post_rollback_fix_reentry_execution_attempted: bool,
    codex_write_invocation_attempted: bool,
    codex_reentry_invocation_attempted: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "multi_cycle_controller_next_cycle_ready",
        "multi_cycle_controller_completed_cycle_budget_exhausted",
        "multi_cycle_controller_blocked_commit_tag_result",
        "multi_cycle_controller_prepare_commit",
        "multi_cycle_controller_fix_ready",
        "multi_cycle_controller_rollback_ready",
        "multi_cycle_controller_blocked_codex_budget_exhausted",
        "multi_cycle_controller_blocked_fix_budget_exhausted",
        "multi_cycle_controller_blocked_rollback_budget_exhausted",
        "multi_cycle_controller_blocked_manual_review",
        "multi_cycle_controller_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "generate_next_prompt",
        "generate_fix_prompt",
        "prepare_rollback_readiness",
        "prepare_commit_tag_readiness",
        "prepare_github_handoff_readiness",
        "manual_review_required",
        "stop_bounded_autonomous_loop",
        "wait_for_more_truth",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt197_multi_cycle_controller",
        "metadata_only_controller",
        "no_execution",
        "no_git_mutation",
        "no_codex_invocation",
        "no_rollback_execution",
        "no_loop_start",
    ]

    normalized_commit_tag_result_status = _normalize_text(
        commit_tag_result_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_result_class = _normalize_text(
        commit_tag_result_class,
        default="insufficient_truth",
    )
    normalized_commit_tag_result_block_reason = _normalize_text(
        commit_tag_result_block_reason,
        default="",
    )
    normalized_commit_tag_result_stop_reason = _normalize_text(
        commit_tag_result_stop_reason,
        default="",
    )
    normalized_commit_tag_result_next_action = _normalize_text(
        commit_tag_result_next_action,
        default="",
    )
    normalized_commit_tag_execution_status = _normalize_text(
        commit_tag_execution_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_readiness_status = _normalize_text(
        commit_tag_readiness_status,
        default="insufficient_truth",
    )
    normalized_post_rollback_fix_reentry_result_status = _normalize_text(
        post_rollback_fix_reentry_result_status,
        default="insufficient_truth",
    )
    normalized_bounded_continuation_status = _normalize_text(
        bounded_continuation_status,
        default="insufficient_truth",
    )
    normalized_one_step_cycle_status = _normalize_text(
        one_step_cycle_status,
        default="insufficient_truth",
    )
    normalized_rollback_result_status = _normalize_text(
        rollback_result_status,
        default="insufficient_truth",
    )
    normalized_post_rollback_continuation_status = _normalize_text(
        post_rollback_continuation_status,
        default="insufficient_truth",
    )

    # Budget defaults / derivation
    max_cycles = 2
    cycle_index = max(1, max_cycles - _as_non_negative_int(bounded_continuation_remaining_cycles, default=1))
    remaining_cycles = max(max_cycles - cycle_index, 0)

    max_fix_attempts = 1
    fix_attempt_index = max(
        0,
        max_fix_attempts - _as_non_negative_int(bounded_continuation_remaining_fix_attempts, default=1),
    )
    remaining_fix_attempts = max(max_fix_attempts - fix_attempt_index, 0)

    max_rollback_attempts = 1
    rollback_attempt_index = (
        1
        if (
            normalized_rollback_result_status
            and normalized_rollback_result_status != "insufficient_truth"
        )
        else 0
    )
    remaining_rollback_attempts = max(max_rollback_attempts - rollback_attempt_index, 0)

    max_codex_invocations = 3
    codex_invocation_count = int(bool(codex_write_invocation_attempted)) + int(
        bool(codex_reentry_invocation_attempted)
    ) + int(bool(post_rollback_fix_reentry_execution_attempted))
    remaining_codex_invocations = max(max_codex_invocations - codex_invocation_count, 0)

    max_commits = 1
    commit_count = (
        1
        if (
            normalized_commit_tag_result_class == "completed"
            and bool(commit_tag_result_commit_completed)
            and bool(commit_tag_result_tag_completed)
        )
        else 0
    )
    remaining_commits = max(max_commits - commit_count, 0)

    latest_authoritative_stage = "none"
    latest_cycle_status = "insufficient_truth"
    latest_validation_passed = False
    latest_commit_tag_status = normalized_commit_tag_result_status
    latest_rollback_status = normalized_rollback_result_status
    latest_human_review_required = False
    controller_source = "none"

    if normalized_commit_tag_result_status and normalized_commit_tag_result_status != "insufficient_truth":
        latest_authoritative_stage = "commit_tag_result_assimilation"
        latest_cycle_status = normalized_post_rollback_fix_reentry_result_status
        latest_validation_passed = bool(post_rollback_fix_reentry_validation_passed)
        latest_human_review_required = bool(commit_tag_result_human_review_required)
        controller_source = "prompt196_commit_tag_result_assimilation"
    elif (
        normalized_post_rollback_fix_reentry_result_status
        and normalized_post_rollback_fix_reentry_result_status != "insufficient_truth"
    ):
        latest_authoritative_stage = "post_rollback_fix_reentry_result_assimilation"
        latest_cycle_status = normalized_post_rollback_fix_reentry_result_status
        latest_validation_passed = bool(post_rollback_fix_reentry_validation_passed)
        latest_human_review_required = bool(post_rollback_fix_reentry_human_review_required)
        controller_source = "prompt193_post_rollback_fix_reentry_result_assimilation"
    elif (
        normalized_rollback_result_status and normalized_rollback_result_status != "insufficient_truth"
    ) or (
        normalized_post_rollback_continuation_status
        and normalized_post_rollback_continuation_status != "insufficient_truth"
    ):
        latest_authoritative_stage = "rollback_posture"
        latest_cycle_status = normalized_post_rollback_continuation_status or normalized_rollback_result_status
        latest_validation_passed = False
        latest_human_review_required = bool(
            rollback_result_human_review_required or post_rollback_continuation_human_review_required
        )
        controller_source = "prompt186_187_rollback_path"
    elif normalized_bounded_continuation_status and normalized_bounded_continuation_status != "insufficient_truth":
        latest_authoritative_stage = "bounded_continuation_controller"
        latest_cycle_status = normalized_bounded_continuation_status
        latest_validation_passed = False
        latest_human_review_required = bool(bounded_continuation_human_review_required)
        controller_source = "prompt183_bounded_continuation"
    else:
        latest_authoritative_stage = "one_step_cycle"
        latest_cycle_status = normalized_one_step_cycle_status
        latest_validation_passed = False
        latest_human_review_required = bool(one_step_cycle_human_review_required)
        controller_source = "prompt172_173_one_step_cycle"

    status = "multi_cycle_controller_blocked_insufficient_truth"
    controller_allowed = False
    controller_block_reason = "blocked_insufficient_multi_cycle_truth"
    next_prompt_kind = "none"
    next_cycle_allowed = False
    fix_continuation_allowed = False
    rollback_path_allowed = False
    github_handoff_allowed = False
    manual_review_required = False
    should_generate_next_prompt = False
    should_generate_fix_prompt = False
    should_invoke_codex = False
    should_validate = False
    should_prepare_rollback = False
    should_execute_rollback = False
    should_prepare_commit = False
    should_execute_commit = False
    should_prepare_github_handoff = False
    should_push = False
    should_stop = True
    stop_reason = "insufficient_multi_cycle_truth"
    next_action = "manual_review_required"
    missing_inputs: list[str] = []

    commit_tag_failure_or_unsafe = bool(
        normalized_commit_tag_result_status
        in {
            "commit_tag_result_assimilation_partial_commit_tag_failed",
            "commit_tag_result_assimilation_failed_git_add",
            "commit_tag_result_assimilation_failed_git_commit",
            "commit_tag_result_assimilation_failed_git_tag",
            "commit_tag_result_assimilation_timeout",
            "commit_tag_result_assimilation_blocked_insufficient_truth",
            "commit_tag_result_assimilation_completed_with_unexpected_dirty",
        }
        or normalized_commit_tag_result_class
        in {
            "partial_commit_tag_failed",
            "failed_git_add",
            "failed_git_commit",
            "failed_git_tag",
            "timeout",
            "blocked",
            "insufficient_truth",
            "completed_unexpected_dirty",
        }
    )

    validation_failed_like = bool(
        post_rollback_fix_reentry_cycle_failed
        or one_step_cycle_failed
        or normalized_post_rollback_fix_reentry_result_status
        in {
            "post_rollback_fix_reentry_result_validation_failed",
            "post_rollback_fix_reentry_result_completed_failure",
        }
    )

    rollback_needed = bool(
        post_rollback_fix_reentry_rollback_candidate
        or normalized_post_rollback_fix_reentry_result_status
        in {
            "post_rollback_fix_reentry_result_blocked_unsafe_changes",
            "post_rollback_fix_reentry_result_validation_timeout",
            "post_rollback_fix_reentry_result_completed_timeout",
        }
    )

    # deterministic priority
    if latest_human_review_required:
        status = "multi_cycle_controller_blocked_manual_review"
        controller_allowed = False
        controller_block_reason = "manual_review_required"
        manual_review_required = True
        should_stop = True
        stop_reason = "manual_review_required"
        next_action = "manual_review_required"
    elif commit_tag_failure_or_unsafe:
        status = "multi_cycle_controller_blocked_commit_tag_result"
        controller_allowed = False
        controller_block_reason = (
            normalized_commit_tag_result_stop_reason
            or normalized_commit_tag_result_block_reason
            or "commit_tag_result_not_safe"
        )
        manual_review_required = True
        should_stop = True
        stop_reason = (
            normalized_commit_tag_result_stop_reason
            or normalized_commit_tag_result_block_reason
            or "commit_tag_result_not_safe"
        )
        next_action = "manual_review_required"
    elif remaining_codex_invocations <= 0:
        status = "multi_cycle_controller_blocked_codex_budget_exhausted"
        controller_allowed = False
        controller_block_reason = "codex_invocation_budget_exhausted"
        should_stop = True
        stop_reason = "codex_invocation_budget_exhausted"
        next_action = "stop_bounded_autonomous_loop"
    elif validation_failed_like and remaining_fix_attempts <= 0:
        status = "multi_cycle_controller_blocked_fix_budget_exhausted"
        controller_allowed = False
        controller_block_reason = "fix_budget_exhausted"
        manual_review_required = True
        should_stop = True
        stop_reason = "fix_budget_exhausted"
        next_action = "manual_review_required"
    elif rollback_needed and remaining_rollback_attempts <= 0:
        status = "multi_cycle_controller_blocked_rollback_budget_exhausted"
        controller_allowed = False
        controller_block_reason = "rollback_budget_exhausted"
        manual_review_required = True
        should_stop = True
        stop_reason = "rollback_budget_exhausted"
        next_action = "manual_review_required"
    elif (
        normalized_commit_tag_result_class == "completed"
        and bool(commit_tag_result_safe_handoff)
        and bool(commit_tag_result_handoff_allowed)
        and not bool(commit_tag_result_human_review_required)
        and not bool(commit_tag_result_post_commit_dirty)
    ):
        if remaining_cycles > 0:
            status = "multi_cycle_controller_next_cycle_ready"
            controller_allowed = True
            controller_block_reason = ""
            next_cycle_allowed = True
            next_prompt_kind = "next"
            should_generate_next_prompt = True
            should_generate_fix_prompt = False
            should_invoke_codex = False
            should_validate = False
            should_prepare_rollback = False
            should_execute_rollback = False
            should_prepare_commit = False
            should_execute_commit = False
            should_prepare_github_handoff = False
            should_push = False
            should_stop = False
            stop_reason = ""
            next_action = "generate_next_prompt"
        else:
            status = "multi_cycle_controller_completed_cycle_budget_exhausted"
            controller_allowed = False
            controller_block_reason = "cycle_budget_exhausted_after_commit"
            next_cycle_allowed = False
            should_stop = True
            stop_reason = "cycle_budget_exhausted_after_commit"
            next_action = "stop_bounded_autonomous_loop"
    elif (
        bool(post_rollback_fix_reentry_validation_passed)
        and bool(post_rollback_fix_reentry_commit_candidate)
        and normalized_commit_tag_result_class != "completed"
    ):
        status = "multi_cycle_controller_prepare_commit"
        controller_allowed = True
        controller_block_reason = ""
        should_prepare_commit = True
        should_execute_commit = False
        should_stop = False
        stop_reason = ""
        next_action = "prepare_commit_tag_readiness"
    elif rollback_needed and remaining_rollback_attempts > 0 and not latest_human_review_required:
        status = "multi_cycle_controller_rollback_ready"
        controller_allowed = True
        controller_block_reason = ""
        rollback_path_allowed = True
        should_prepare_rollback = True
        should_execute_rollback = False
        should_stop = False
        stop_reason = ""
        next_action = "prepare_rollback_readiness"
    elif validation_failed_like and remaining_fix_attempts > 0 and not latest_human_review_required:
        status = "multi_cycle_controller_fix_ready"
        controller_allowed = True
        controller_block_reason = ""
        fix_continuation_allowed = True
        next_prompt_kind = "fix"
        should_generate_fix_prompt = True
        should_generate_next_prompt = False
        should_invoke_codex = False
        should_stop = False
        stop_reason = ""
        next_action = "generate_fix_prompt"
    else:
        status = "multi_cycle_controller_blocked_insufficient_truth"
        controller_allowed = False
        controller_block_reason = "blocked_insufficient_multi_cycle_truth"
        should_stop = True
        stop_reason = "insufficient_multi_cycle_truth"
        manual_review_required = True
        next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if status == "insufficient_truth":
        controller_allowed = False
        controller_block_reason = "blocked_insufficient_multi_cycle_truth"
        should_stop = True
        stop_reason = "insufficient_multi_cycle_truth"
        manual_review_required = True
        should_generate_next_prompt = False
        should_generate_fix_prompt = False
        should_invoke_codex = False
        should_validate = False
        should_prepare_rollback = False
        should_execute_rollback = False
        should_prepare_commit = False
        should_execute_commit = False
        should_prepare_github_handoff = False
        should_push = False

    return {
        "project_browser_autonomous_multi_cycle_controller_status": status,
        "project_browser_autonomous_multi_cycle_controller_controller_allowed": bool(
            controller_allowed
        ),
        "project_browser_autonomous_multi_cycle_controller_controller_block_reason": (
            controller_block_reason
        ),
        "project_browser_autonomous_multi_cycle_controller_controller_source": controller_source,
        "project_browser_autonomous_multi_cycle_controller_latest_authoritative_stage": (
            latest_authoritative_stage
        ),
        "project_browser_autonomous_multi_cycle_controller_latest_cycle_status": (
            latest_cycle_status
        ),
        "project_browser_autonomous_multi_cycle_controller_latest_validation_passed": bool(
            latest_validation_passed
        ),
        "project_browser_autonomous_multi_cycle_controller_latest_commit_tag_status": (
            latest_commit_tag_status
        ),
        "project_browser_autonomous_multi_cycle_controller_latest_rollback_status": (
            latest_rollback_status
        ),
        "project_browser_autonomous_multi_cycle_controller_latest_human_review_required": bool(
            latest_human_review_required
        ),
        "project_browser_autonomous_multi_cycle_controller_cycle_index": int(cycle_index),
        "project_browser_autonomous_multi_cycle_controller_max_cycles": int(max_cycles),
        "project_browser_autonomous_multi_cycle_controller_remaining_cycles": int(
            remaining_cycles
        ),
        "project_browser_autonomous_multi_cycle_controller_fix_attempt_index": int(
            fix_attempt_index
        ),
        "project_browser_autonomous_multi_cycle_controller_max_fix_attempts": int(
            max_fix_attempts
        ),
        "project_browser_autonomous_multi_cycle_controller_remaining_fix_attempts": int(
            remaining_fix_attempts
        ),
        "project_browser_autonomous_multi_cycle_controller_rollback_attempt_index": int(
            rollback_attempt_index
        ),
        "project_browser_autonomous_multi_cycle_controller_max_rollback_attempts": int(
            max_rollback_attempts
        ),
        "project_browser_autonomous_multi_cycle_controller_remaining_rollback_attempts": int(
            remaining_rollback_attempts
        ),
        "project_browser_autonomous_multi_cycle_controller_codex_invocation_count": int(
            codex_invocation_count
        ),
        "project_browser_autonomous_multi_cycle_controller_max_codex_invocations": int(
            max_codex_invocations
        ),
        "project_browser_autonomous_multi_cycle_controller_remaining_codex_invocations": int(
            remaining_codex_invocations
        ),
        "project_browser_autonomous_multi_cycle_controller_commit_count": int(commit_count),
        "project_browser_autonomous_multi_cycle_controller_max_commits": int(max_commits),
        "project_browser_autonomous_multi_cycle_controller_remaining_commits": int(
            remaining_commits
        ),
        "project_browser_autonomous_multi_cycle_controller_next_prompt_kind": next_prompt_kind,
        "project_browser_autonomous_multi_cycle_controller_next_cycle_allowed": bool(
            next_cycle_allowed
        ),
        "project_browser_autonomous_multi_cycle_controller_fix_continuation_allowed": bool(
            fix_continuation_allowed
        ),
        "project_browser_autonomous_multi_cycle_controller_rollback_path_allowed": bool(
            rollback_path_allowed
        ),
        "project_browser_autonomous_multi_cycle_controller_github_handoff_allowed": bool(
            github_handoff_allowed
        ),
        "project_browser_autonomous_multi_cycle_controller_manual_review_required": bool(
            manual_review_required
        ),
        "project_browser_autonomous_multi_cycle_controller_should_generate_next_prompt": bool(
            should_generate_next_prompt
        ),
        "project_browser_autonomous_multi_cycle_controller_should_generate_fix_prompt": bool(
            should_generate_fix_prompt
        ),
        "project_browser_autonomous_multi_cycle_controller_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_multi_cycle_controller_should_validate": bool(
            should_validate
        ),
        "project_browser_autonomous_multi_cycle_controller_should_prepare_rollback": bool(
            should_prepare_rollback
        ),
        "project_browser_autonomous_multi_cycle_controller_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_multi_cycle_controller_should_prepare_commit": bool(
            should_prepare_commit
        ),
        "project_browser_autonomous_multi_cycle_controller_should_execute_commit": bool(
            should_execute_commit
        ),
        "project_browser_autonomous_multi_cycle_controller_should_prepare_github_handoff": bool(
            should_prepare_github_handoff
        ),
        "project_browser_autonomous_multi_cycle_controller_should_push": bool(should_push),
        "project_browser_autonomous_multi_cycle_controller_should_stop": bool(should_stop),
        "project_browser_autonomous_multi_cycle_controller_stop_reason": stop_reason,
        "project_browser_autonomous_multi_cycle_controller_next_action": next_action,
        "project_browser_autonomous_multi_cycle_controller_runtime_posture": runtime_posture,
        "project_browser_autonomous_multi_cycle_controller_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_commit_tag_result_status,
                    normalized_commit_tag_result_class,
                    normalized_commit_tag_result_block_reason,
                    normalized_commit_tag_result_stop_reason,
                    normalized_commit_tag_result_next_action,
                    normalized_commit_tag_execution_status,
                    normalized_commit_tag_readiness_status,
                    normalized_post_rollback_fix_reentry_result_status,
                    normalized_bounded_continuation_status,
                    normalized_one_step_cycle_status,
                    normalized_rollback_result_status,
                    normalized_post_rollback_continuation_status,
                    "post_commit_dirty_true"
                    if commit_tag_result_post_commit_dirty and normalized_commit_tag_result_class == "completed"
                    else "",
                    "remaining_cycles_zero" if remaining_cycles <= 0 else "",
                    "remaining_fix_attempts_zero" if remaining_fix_attempts <= 0 else "",
                    "remaining_rollback_attempts_zero" if remaining_rollback_attempts <= 0 else "",
                    "remaining_codex_invocations_zero" if remaining_codex_invocations <= 0 else "",
                    *missing_inputs,
                ]
            )
        ),
    }


def _build_project_browser_autonomous_terminal_lane_decision_state(
    *,
    controller_status: str,
    controller_allowed: bool,
    controller_block_reason: str,
    controller_source: str,
    latest_authoritative_stage: str,
    latest_cycle_status: str,
    latest_validation_passed: bool,
    latest_commit_tag_status: str,
    latest_rollback_status: str,
    latest_human_review_required: bool,
    cycle_index: int,
    max_cycles: int,
    remaining_cycles: int,
    fix_attempt_index: int,
    max_fix_attempts: int,
    remaining_fix_attempts: int,
    rollback_attempt_index: int,
    max_rollback_attempts: int,
    remaining_rollback_attempts: int,
    codex_invocation_count: int,
    max_codex_invocations: int,
    remaining_codex_invocations: int,
    commit_count: int,
    max_commits: int,
    remaining_commits: int,
    next_prompt_kind: str,
    next_cycle_allowed: bool,
    fix_continuation_allowed: bool,
    rollback_path_allowed: bool,
    github_handoff_allowed: bool,
    manual_review_required: bool,
    should_generate_next_prompt: bool,
    should_generate_fix_prompt: bool,
    should_invoke_codex: bool,
    should_validate: bool,
    should_prepare_rollback: bool,
    should_execute_rollback: bool,
    should_prepare_commit: bool,
    should_execute_commit: bool,
    should_prepare_github_handoff: bool,
    should_push: bool,
    should_stop: bool,
    stop_reason: str,
    controller_next_action: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "terminal_lane_decision_selected_next_prompt",
        "terminal_lane_decision_selected_fix_prompt",
        "terminal_lane_decision_selected_rollback_readiness",
        "terminal_lane_decision_selected_commit_readiness",
        "terminal_lane_decision_selected_manual_stop",
        "terminal_lane_decision_blocked_conflict",
        "terminal_lane_decision_blocked_insufficient_truth",
        "terminal_lane_decision_blocked_github_not_enabled",
        "insufficient_truth",
    }
    allowed_lanes = {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
        "github_readiness_lane",
        "manual_stop_lane",
        "none",
    }
    allowed_next_actions = {
        "prepare_next_prompt_generation",
        "prepare_fix_prompt_generation",
        "prepare_rollback_readiness",
        "prepare_commit_tag_readiness",
        "github_readiness_not_enabled",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt198_terminal_lane_decision",
        "metadata_only",
        "single_lane_contract",
        "no_execution",
        "no_codex_invocation",
        "no_git_mutation",
        "no_rollback_execution",
        "no_push",
    ]

    normalized_controller_status = _normalize_text(controller_status, default="insufficient_truth")
    normalized_controller_block_reason = _normalize_text(controller_block_reason, default="")
    normalized_controller_source = _normalize_text(controller_source, default="")
    normalized_latest_authoritative_stage = _normalize_text(
        latest_authoritative_stage,
        default="none",
    )
    normalized_latest_cycle_status = _normalize_text(latest_cycle_status, default="insufficient_truth")
    normalized_latest_commit_tag_status = _normalize_text(
        latest_commit_tag_status,
        default="insufficient_truth",
    )
    normalized_latest_rollback_status = _normalize_text(
        latest_rollback_status,
        default="insufficient_truth",
    )
    normalized_next_prompt_kind = _normalize_text(next_prompt_kind, default="none")
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_controller_next_action = _normalize_text(controller_next_action, default="")

    next_prompt_lane_candidate = bool(
        controller_allowed
        and should_generate_next_prompt
        and normalized_next_prompt_kind == "next"
        and next_cycle_allowed
        and not manual_review_required
        and not should_stop
    )
    fix_prompt_lane_candidate = bool(
        controller_allowed
        and should_generate_fix_prompt
        and normalized_next_prompt_kind == "fix"
        and fix_continuation_allowed
        and not manual_review_required
        and not should_stop
    )
    rollback_readiness_lane_candidate = bool(
        controller_allowed
        and should_prepare_rollback
        and rollback_path_allowed
        and not manual_review_required
        and not should_stop
    )
    commit_readiness_lane_candidate = bool(
        controller_allowed
        and should_prepare_commit
        and not should_execute_commit
        and not manual_review_required
        and not should_stop
    )
    github_readiness_lane_candidate = bool(
        controller_allowed
        and should_prepare_github_handoff
        and github_handoff_allowed
        and not manual_review_required
        and not should_stop
    )
    manual_stop_lane_candidate = bool(
        manual_review_required
        or should_stop
        or not controller_allowed
        or "budget_exhausted" in normalized_controller_status
        or normalized_controller_status.endswith("blocked_insufficient_truth")
        or "blocked" in normalized_controller_status
    )

    candidate_map: dict[str, bool] = {
        "next_prompt_lane": next_prompt_lane_candidate,
        "fix_prompt_lane": fix_prompt_lane_candidate,
        "rollback_readiness_lane": rollback_readiness_lane_candidate,
        "commit_readiness_lane": commit_readiness_lane_candidate,
        "github_readiness_lane": github_readiness_lane_candidate,
    }
    true_non_stop_lanes = sorted([name for name, on in candidate_map.items() if on])

    status = "terminal_lane_decision_blocked_insufficient_truth"
    selected_lane = "manual_stop_lane"
    selected_lane_allowed = False
    selected_lane_block_reason = "blocked_insufficient_terminal_lane_truth"
    selected_lane_source = "multi_cycle_controller"
    selected_lane_priority = "manual_stop"
    lane_contract_ready = False
    lane_contract_kind = "manual_stop_lane"
    lane_contract_action = "manual_review_required"
    lane_contract_payload: dict[str, Any] = {}
    lane_conflict_detected = False
    conflicting_lanes: list[str] = []
    local_manual_review_required = bool(manual_review_required)
    local_should_stop = bool(should_stop)
    local_stop_reason = normalized_stop_reason or "insufficient_terminal_lane_truth"
    next_action = "manual_review_required"

    explicit_allowed_controller_statuses = {
        "multi_cycle_controller_next_cycle_ready",
        "multi_cycle_controller_fix_ready",
        "multi_cycle_controller_rollback_ready",
        "multi_cycle_controller_prepare_commit",
    }
    manual_stop_may_yield = bool(
        len(true_non_stop_lanes) == 1
        and controller_allowed
        and not manual_review_required
        and not should_stop
        and normalized_controller_status in explicit_allowed_controller_statuses
    )

    if len(true_non_stop_lanes) > 1:
        status = "terminal_lane_decision_blocked_conflict"
        selected_lane = "manual_stop_lane"
        selected_lane_allowed = False
        selected_lane_block_reason = "conflicting_terminal_lane_candidates"
        selected_lane_source = "multi_cycle_controller"
        selected_lane_priority = "conflict_block"
        lane_contract_ready = True
        lane_contract_kind = "manual_stop_lane"
        lane_contract_action = "manual_review_required"
        lane_contract_payload = {
            "lane": "manual_stop_lane",
            "source": "multi_cycle_controller",
            "stop_reason": "conflicting_terminal_lane_candidates",
            "next_action": "manual_review_required",
        }
        lane_conflict_detected = True
        conflicting_lanes = list(true_non_stop_lanes)
        local_manual_review_required = True
        local_should_stop = True
        local_stop_reason = "conflicting_terminal_lane_candidates"
        next_action = "manual_review_required"
    elif manual_stop_lane_candidate and not manual_stop_may_yield:
        status = "terminal_lane_decision_selected_manual_stop"
        selected_lane = "manual_stop_lane"
        selected_lane_allowed = False
        selected_lane_block_reason = normalized_controller_block_reason or "manual_stop_required"
        selected_lane_source = "multi_cycle_controller"
        selected_lane_priority = "manual_stop"
        lane_contract_ready = True
        lane_contract_kind = "manual_stop_lane"
        lane_contract_action = "manual_review_required"
        lane_contract_payload = {
            "lane": "manual_stop_lane",
            "source": "multi_cycle_controller",
            "stop_reason": normalized_stop_reason or "manual_review_required",
            "next_action": "manual_review_required",
        }
        lane_conflict_detected = False
        conflicting_lanes = []
        local_manual_review_required = True
        local_should_stop = True
        local_stop_reason = normalized_stop_reason or "manual_review_required"
        next_action = "manual_review_required"
    elif len(true_non_stop_lanes) == 0:
        status = "terminal_lane_decision_blocked_insufficient_truth"
        selected_lane = "manual_stop_lane"
        selected_lane_allowed = False
        selected_lane_block_reason = "blocked_insufficient_terminal_lane_truth"
        selected_lane_source = "multi_cycle_controller"
        selected_lane_priority = "insufficient_truth"
        lane_contract_ready = False
        lane_contract_kind = "manual_stop_lane"
        lane_contract_action = "manual_review_required"
        lane_contract_payload = {}
        lane_conflict_detected = False
        conflicting_lanes = []
        local_manual_review_required = True
        local_should_stop = True
        local_stop_reason = "insufficient_terminal_lane_truth"
        next_action = "manual_review_required"
    else:
        priority_order = [
            "commit_readiness_lane",
            "rollback_readiness_lane",
            "fix_prompt_lane",
            "next_prompt_lane",
            "github_readiness_lane",
        ]
        chosen_lane = "manual_stop_lane"
        for lane_name in priority_order:
            if lane_name in true_non_stop_lanes:
                chosen_lane = lane_name
                break

        if chosen_lane == "commit_readiness_lane":
            status = "terminal_lane_decision_selected_commit_readiness"
            selected_lane = chosen_lane
            selected_lane_allowed = True
            selected_lane_block_reason = ""
            selected_lane_source = "multi_cycle_controller"
            selected_lane_priority = "1"
            lane_contract_ready = True
            lane_contract_kind = chosen_lane
            lane_contract_action = "prepare_commit_tag_readiness"
            lane_contract_payload = {
                "lane": "commit_readiness_lane",
                "source": "multi_cycle_controller",
                "remaining_commits": _as_non_negative_int(remaining_commits, default=0),
                "next_action": "prepare_commit_tag_readiness",
            }
            local_manual_review_required = False
            local_should_stop = False
            local_stop_reason = ""
            next_action = "prepare_commit_tag_readiness"
        elif chosen_lane == "rollback_readiness_lane":
            status = "terminal_lane_decision_selected_rollback_readiness"
            selected_lane = chosen_lane
            selected_lane_allowed = True
            selected_lane_block_reason = ""
            selected_lane_source = "multi_cycle_controller"
            selected_lane_priority = "2"
            lane_contract_ready = True
            lane_contract_kind = chosen_lane
            lane_contract_action = "prepare_rollback_readiness"
            lane_contract_payload = {
                "lane": "rollback_readiness_lane",
                "source": "multi_cycle_controller",
                "remaining_rollback_attempts": _as_non_negative_int(
                    remaining_rollback_attempts,
                    default=0,
                ),
                "next_action": "prepare_rollback_readiness",
            }
            local_manual_review_required = False
            local_should_stop = False
            local_stop_reason = ""
            next_action = "prepare_rollback_readiness"
        elif chosen_lane == "fix_prompt_lane":
            status = "terminal_lane_decision_selected_fix_prompt"
            selected_lane = chosen_lane
            selected_lane_allowed = True
            selected_lane_block_reason = ""
            selected_lane_source = "multi_cycle_controller"
            selected_lane_priority = "3"
            lane_contract_ready = True
            lane_contract_kind = chosen_lane
            lane_contract_action = "prepare_fix_prompt_generation"
            lane_contract_payload = {
                "lane": "fix_prompt_lane",
                "prompt_kind": "fix",
                "source": "multi_cycle_controller",
                "fix_attempt_index": _as_non_negative_int(fix_attempt_index, default=0),
                "remaining_fix_attempts": _as_non_negative_int(
                    remaining_fix_attempts,
                    default=0,
                ),
                "next_action": "prepare_fix_prompt_generation",
            }
            local_manual_review_required = False
            local_should_stop = False
            local_stop_reason = ""
            next_action = "prepare_fix_prompt_generation"
        elif chosen_lane == "next_prompt_lane":
            status = "terminal_lane_decision_selected_next_prompt"
            selected_lane = chosen_lane
            selected_lane_allowed = True
            selected_lane_block_reason = ""
            selected_lane_source = "multi_cycle_controller"
            selected_lane_priority = "4"
            lane_contract_ready = True
            lane_contract_kind = chosen_lane
            lane_contract_action = "prepare_next_prompt_generation"
            lane_contract_payload = {
                "lane": "next_prompt_lane",
                "prompt_kind": "next",
                "source": "multi_cycle_controller",
                "cycle_index": _as_non_negative_int(cycle_index, default=1),
                "remaining_cycles": _as_non_negative_int(remaining_cycles, default=0),
                "max_cycles": _as_non_negative_int(max_cycles, default=2),
                "next_action": "prepare_next_prompt_generation",
            }
            local_manual_review_required = False
            local_should_stop = False
            local_stop_reason = ""
            next_action = "prepare_next_prompt_generation"
        elif chosen_lane == "github_readiness_lane":
            status = "terminal_lane_decision_blocked_github_not_enabled"
            selected_lane = "manual_stop_lane"
            selected_lane_allowed = False
            selected_lane_block_reason = "github_readiness_not_enabled"
            selected_lane_source = "multi_cycle_controller"
            selected_lane_priority = "5_blocked"
            lane_contract_ready = True
            lane_contract_kind = "manual_stop_lane"
            lane_contract_action = "manual_review_required"
            lane_contract_payload = {
                "lane": "manual_stop_lane",
                "source": "multi_cycle_controller",
                "stop_reason": "github_readiness_not_enabled",
                "next_action": "manual_review_required",
            }
            local_manual_review_required = True
            local_should_stop = True
            local_stop_reason = "github_readiness_not_enabled"
            next_action = "manual_review_required"

    if selected_lane not in allowed_lanes:
        selected_lane = "manual_stop_lane"
    if lane_contract_kind not in allowed_lanes:
        lane_contract_kind = "manual_stop_lane"
    if status not in allowed_statuses:
        status = "insufficient_truth"
    if next_action not in allowed_next_actions:
        next_action = "insufficient_truth"
    if lane_contract_action not in allowed_next_actions:
        lane_contract_action = "insufficient_truth"
    if status == "insufficient_truth":
        selected_lane = "manual_stop_lane"
        selected_lane_allowed = False
        selected_lane_block_reason = "blocked_insufficient_terminal_lane_truth"
        lane_contract_ready = False
        lane_contract_kind = "manual_stop_lane"
        lane_contract_action = "manual_review_required"
        lane_contract_payload = {}
        lane_conflict_detected = False
        conflicting_lanes = []
        local_manual_review_required = True
        local_should_stop = True
        local_stop_reason = "insufficient_terminal_lane_truth"
        next_action = "manual_review_required"

    return {
        "project_browser_autonomous_terminal_lane_decision_status": status,
        "project_browser_autonomous_terminal_lane_decision_selected_lane": selected_lane,
        "project_browser_autonomous_terminal_lane_decision_selected_lane_allowed": bool(
            selected_lane_allowed
        ),
        "project_browser_autonomous_terminal_lane_decision_selected_lane_block_reason": (
            selected_lane_block_reason
        ),
        "project_browser_autonomous_terminal_lane_decision_selected_lane_source": (
            selected_lane_source
        ),
        "project_browser_autonomous_terminal_lane_decision_selected_lane_priority": (
            selected_lane_priority
        ),
        "project_browser_autonomous_terminal_lane_decision_lane_contract_ready": bool(
            lane_contract_ready
        ),
        "project_browser_autonomous_terminal_lane_decision_lane_contract_kind": lane_contract_kind,
        "project_browser_autonomous_terminal_lane_decision_lane_contract_action": lane_contract_action,
        "project_browser_autonomous_terminal_lane_decision_lane_contract_payload": (
            lane_contract_payload
        ),
        "project_browser_autonomous_terminal_lane_decision_lane_conflict_detected": bool(
            lane_conflict_detected
        ),
        "project_browser_autonomous_terminal_lane_decision_conflicting_lanes": (
            conflicting_lanes
        ),
        "project_browser_autonomous_terminal_lane_decision_controller_status": (
            normalized_controller_status
        ),
        "project_browser_autonomous_terminal_lane_decision_controller_next_action": (
            normalized_controller_next_action
        ),
        "project_browser_autonomous_terminal_lane_decision_controller_allowed": bool(
            controller_allowed
        ),
        "project_browser_autonomous_terminal_lane_decision_manual_review_required": bool(
            local_manual_review_required
        ),
        "project_browser_autonomous_terminal_lane_decision_should_stop": bool(local_should_stop),
        "project_browser_autonomous_terminal_lane_decision_stop_reason": local_stop_reason,
        "project_browser_autonomous_terminal_lane_decision_should_generate_next_prompt": bool(
            should_generate_next_prompt
        ),
        "project_browser_autonomous_terminal_lane_decision_should_generate_fix_prompt": bool(
            should_generate_fix_prompt
        ),
        "project_browser_autonomous_terminal_lane_decision_should_prepare_rollback": bool(
            should_prepare_rollback
        ),
        "project_browser_autonomous_terminal_lane_decision_should_prepare_commit": bool(
            should_prepare_commit
        ),
        "project_browser_autonomous_terminal_lane_decision_should_prepare_github_handoff": bool(
            should_prepare_github_handoff
        ),
        "project_browser_autonomous_terminal_lane_decision_should_invoke_codex": bool(
            should_invoke_codex
        ),
        "project_browser_autonomous_terminal_lane_decision_should_execute_rollback": bool(
            should_execute_rollback
        ),
        "project_browser_autonomous_terminal_lane_decision_should_execute_commit": bool(
            should_execute_commit
        ),
        "project_browser_autonomous_terminal_lane_decision_should_push": bool(should_push),
        "project_browser_autonomous_terminal_lane_decision_next_action": next_action,
        "project_browser_autonomous_terminal_lane_decision_runtime_posture": runtime_posture,
        "project_browser_autonomous_terminal_lane_decision_missing_inputs": _serialize_required_signals(
            [
                normalized_controller_status,
                normalized_controller_block_reason,
                normalized_controller_source,
                normalized_latest_authoritative_stage,
                normalized_latest_cycle_status,
                normalized_latest_commit_tag_status,
                normalized_latest_rollback_status,
                normalized_next_prompt_kind,
                normalized_stop_reason,
                normalized_controller_next_action,
                "latest_validation_passed_true" if latest_validation_passed else "",
                "latest_human_review_required_true" if latest_human_review_required else "",
                "candidate_next_true" if next_prompt_lane_candidate else "",
                "candidate_fix_true" if fix_prompt_lane_candidate else "",
                "candidate_rollback_true" if rollback_readiness_lane_candidate else "",
                "candidate_commit_true" if commit_readiness_lane_candidate else "",
                "candidate_github_true" if github_readiness_lane_candidate else "",
                "candidate_manual_stop_true" if manual_stop_lane_candidate else "",
            ]
        ),
    }


def _build_project_browser_autonomous_lane_contract_guard_state(
    *,
    terminal_lane_status: str,
    selected_lane: str,
    selected_lane_allowed: bool,
    selected_lane_block_reason: str,
    selected_lane_source: str,
    selected_lane_priority: str,
    lane_contract_ready: bool,
    lane_contract_kind: str,
    lane_contract_action: str,
    lane_contract_payload: Any,
    lane_conflict_detected: bool,
    conflicting_lanes: Sequence[Any],
    controller_status: str,
    controller_next_action: str,
    controller_allowed: bool,
    manual_review_required: bool,
    should_stop: bool,
    stop_reason: str,
    should_generate_next_prompt: bool,
    should_generate_fix_prompt: bool,
    should_prepare_rollback: bool,
    should_prepare_commit: bool,
    should_prepare_github_handoff: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_execute_commit: bool,
    should_push: bool,
    next_action: str,
    multi_cycle_controller_status: str,
    commit_tag_result_assimilation_status: str,
    post_rollback_fix_reentry_result_assimilation_status: str,
) -> dict[str, Any]:
    allowed_lanes = {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
        "manual_stop_lane",
        "github_readiness_lane",
    }
    validated_lanes = {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
        "manual_stop_lane",
    }
    allowed_statuses = {
        "lane_contract_guard_valid_next_prompt",
        "lane_contract_guard_valid_fix_prompt",
        "lane_contract_guard_valid_rollback_readiness",
        "lane_contract_guard_valid_commit_readiness",
        "lane_contract_guard_manual_stop",
        "lane_contract_guard_blocked_malformed_contract",
        "lane_contract_guard_blocked_conflict",
        "lane_contract_guard_blocked_github_not_enabled",
        "lane_contract_guard_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "refresh_next_prompt_lane",
        "refresh_fix_prompt_lane",
        "refresh_rollback_readiness_lane",
        "refresh_commit_readiness_lane",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt199_lane_contract_guard",
        "metadata_only",
        "single_lane_validation",
        "no_execution",
        "no_codex_invocation",
        "no_git_mutation",
        "no_rollback_execution",
        "no_push",
    ]
    lane_action_allowlist: dict[str, str] = {
        "next_prompt_lane": "prepare_next_prompt_generation",
        "fix_prompt_lane": "prepare_fix_prompt_generation",
        "rollback_readiness_lane": "prepare_rollback_readiness",
        "commit_readiness_lane": "prepare_commit_tag_readiness",
        "manual_stop_lane": "manual_review_required",
    }

    normalized_terminal_lane_status = _normalize_text(terminal_lane_status, default="insufficient_truth")
    normalized_selected_lane = _normalize_text(selected_lane, default="")
    normalized_selected_lane_block_reason = _normalize_text(selected_lane_block_reason, default="")
    normalized_selected_lane_source = _normalize_text(selected_lane_source, default="")
    normalized_selected_lane_priority = _normalize_text(selected_lane_priority, default="")
    normalized_lane_contract_kind = _normalize_text(lane_contract_kind, default="")
    normalized_lane_contract_action = _normalize_text(lane_contract_action, default="")
    normalized_controller_status = _normalize_text(controller_status, default="insufficient_truth")
    normalized_controller_next_action = _normalize_text(controller_next_action, default="")
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_next_action = _normalize_text(next_action, default="")
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_result_assimilation_status = _normalize_text(
        commit_tag_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_post_rollback_fix_reentry_result_assimilation_status = _normalize_text(
        post_rollback_fix_reentry_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_conflicting_lanes = _normalize_string_list(conflicting_lanes)
    payload_mapping = dict(lane_contract_payload) if isinstance(lane_contract_payload, Mapping) else None
    payload_object = payload_mapping if payload_mapping is not None else {}
    payload_lane = _normalize_text(payload_object.get("lane"), default="")
    payload_source = _normalize_text(payload_object.get("source"), default="")
    payload_next_action = _normalize_text(payload_object.get("next_action"), default="")
    payload_prompt_kind = _normalize_text(payload_object.get("prompt_kind"), default="")

    contract_schema_valid = bool(
        isinstance(payload_mapping, Mapping)
        and bool(payload_lane)
        and bool(payload_source)
        and bool(payload_next_action)
    )
    contract_payload_lane_matches_selection = bool(
        contract_schema_valid
        and payload_lane == normalized_selected_lane
        and normalized_lane_contract_kind == normalized_selected_lane
    )
    contract_action_matches_payload = bool(
        contract_schema_valid and normalized_lane_contract_action == payload_next_action
    )

    lane_action_allowed = False
    lane_requirement_valid = False
    if normalized_selected_lane == "next_prompt_lane":
        lane_action_allowed = payload_next_action == lane_action_allowlist["next_prompt_lane"]
        lane_requirement_valid = bool(
            payload_prompt_kind == "next"
            and _as_non_negative_int(payload_object.get("remaining_cycles"), default=-1) >= 0
            and _as_non_negative_int(payload_object.get("max_cycles"), default=0) >= 1
        )
    elif normalized_selected_lane == "fix_prompt_lane":
        lane_action_allowed = payload_next_action == lane_action_allowlist["fix_prompt_lane"]
        lane_requirement_valid = bool(
            payload_prompt_kind == "fix"
            and _as_non_negative_int(payload_object.get("remaining_fix_attempts"), default=-1) >= 0
        )
    elif normalized_selected_lane == "rollback_readiness_lane":
        lane_action_allowed = payload_next_action == lane_action_allowlist["rollback_readiness_lane"]
        lane_requirement_valid = bool(
            _as_non_negative_int(payload_object.get("remaining_rollback_attempts"), default=-1) >= 0
        )
    elif normalized_selected_lane == "commit_readiness_lane":
        lane_action_allowed = payload_next_action == lane_action_allowlist["commit_readiness_lane"]
        lane_requirement_valid = bool(
            _as_non_negative_int(payload_object.get("remaining_commits"), default=-1) >= 0
        )
    elif normalized_selected_lane == "manual_stop_lane":
        lane_action_allowed = payload_next_action == lane_action_allowlist["manual_stop_lane"]
        lane_requirement_valid = bool(_normalize_text(payload_object.get("stop_reason"), default=""))
    elif normalized_selected_lane == "github_readiness_lane":
        lane_action_allowed = False
        lane_requirement_valid = False

    contract_action_allowed = bool(
        contract_schema_valid and contract_action_matches_payload and lane_action_allowed and lane_requirement_valid
    )
    github_lane_trace_detected = bool(
        normalized_selected_lane == "github_readiness_lane"
        or normalized_lane_contract_kind == "github_readiness_lane"
        or payload_lane == "github_readiness_lane"
        or payload_source == "github_readiness_lane"
        or normalized_selected_lane_block_reason in {
            "github_readiness_not_enabled",
            "github_lane_not_enabled",
        }
        or payload_next_action == "github_readiness_not_enabled"
    )
    contract_manual_stop = bool(
        normalized_selected_lane == "manual_stop_lane" or manual_review_required or should_stop
    )
    contract_conflict_detected = bool(lane_conflict_detected)

    block_reason = ""
    if normalized_terminal_lane_status in {"insufficient_truth", ""}:
        block_reason = "blocked_terminal_lane_not_ready"
    elif not normalized_selected_lane:
        block_reason = "blocked_selected_lane_missing"
    elif github_lane_trace_detected:
        block_reason = "blocked_github_lane_not_enabled"
    elif normalized_selected_lane not in validated_lanes:
        block_reason = "blocked_selected_lane_not_allowed"
    elif not selected_lane_allowed:
        block_reason = "blocked_selected_lane_not_allowed"
    elif not lane_contract_ready:
        block_reason = "blocked_lane_contract_not_ready"
    elif not isinstance(payload_mapping, Mapping):
        block_reason = "blocked_lane_contract_not_dict"
    elif not payload_lane:
        block_reason = "blocked_lane_payload_missing_lane"
    elif not payload_source:
        block_reason = "blocked_lane_payload_missing_source"
    elif not payload_next_action:
        block_reason = "blocked_lane_payload_missing_next_action"
    elif payload_lane != normalized_selected_lane:
        block_reason = "blocked_lane_payload_mismatch"
    elif normalized_lane_contract_kind != normalized_selected_lane:
        block_reason = "blocked_lane_kind_mismatch"
    elif normalized_lane_contract_action != payload_next_action:
        block_reason = "blocked_lane_action_mismatch"
    elif not lane_action_allowed or not lane_requirement_valid:
        block_reason = "blocked_lane_action_not_allowed"
    elif contract_conflict_detected:
        block_reason = "blocked_lane_conflict_detected"
    elif normalized_conflicting_lanes:
        block_reason = "blocked_conflicting_lanes_present"
    elif should_invoke_codex:
        block_reason = "blocked_unexpected_codex_invocation_flag"
    elif should_execute_rollback:
        block_reason = "blocked_unexpected_rollback_execution_flag"
    elif should_execute_commit:
        block_reason = "blocked_unexpected_commit_execution_flag"
    elif should_push:
        block_reason = "blocked_unexpected_push_flag"
    elif not contract_schema_valid or not contract_payload_lane_matches_selection:
        block_reason = "blocked_insufficient_lane_contract_truth"

    status = "lane_contract_guard_blocked_insufficient_truth"
    guarded_lane = "manual_stop_lane"
    guarded_lane_allowed = False
    guarded_lane_block_reason = block_reason or "blocked_insufficient_lane_contract_truth"
    guarded_lane_source = normalized_selected_lane_source or "terminal_lane_decision"
    guarded_contract_ready = False
    guarded_contract_kind = "manual_stop_lane"
    guarded_contract_action = "manual_review_required"
    guarded_contract_payload: dict[str, Any] = {
        "lane": "manual_stop_lane",
        "source": guarded_lane_source,
        "stop_reason": normalized_stop_reason or guarded_lane_block_reason,
        "next_action": "manual_review_required",
    }
    downstream_refresh_allowed = False
    downstream_refresh_kind = "manual_stop_lane"
    out_should_generate_next_prompt = False
    out_should_generate_fix_prompt = False
    out_should_prepare_rollback = False
    out_should_prepare_commit = False
    out_should_prepare_github_handoff = False
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_stop_reason or guarded_lane_block_reason
    out_next_action = "manual_review_required"

    status_by_lane = {
        "next_prompt_lane": "lane_contract_guard_valid_next_prompt",
        "fix_prompt_lane": "lane_contract_guard_valid_fix_prompt",
        "rollback_readiness_lane": "lane_contract_guard_valid_rollback_readiness",
        "commit_readiness_lane": "lane_contract_guard_valid_commit_readiness",
    }

    if contract_manual_stop:
        status = "lane_contract_guard_manual_stop"
        guarded_lane = "manual_stop_lane"
        guarded_lane_allowed = False
        guarded_lane_block_reason = (
            normalized_selected_lane_block_reason
            or normalized_stop_reason
            or block_reason
            or "manual_stop_lane_selected"
        )
        if github_lane_trace_detected:
            guarded_lane_block_reason = "github_lane_not_enabled"
        guarded_contract_ready = True
        guarded_contract_kind = "manual_stop_lane"
        guarded_contract_action = "manual_review_required"
        guarded_contract_payload = {
            "lane": "manual_stop_lane",
            "source": guarded_lane_source,
            "stop_reason": (
                "github_lane_not_enabled"
                if github_lane_trace_detected
                else (
                    normalized_stop_reason
                    or normalized_selected_lane_block_reason
                    or "manual_stop_lane_selected"
                )
            ),
            "next_action": "manual_review_required",
        }
        downstream_refresh_allowed = False
        downstream_refresh_kind = "manual_stop_lane"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = (
            "github_lane_not_enabled"
            if github_lane_trace_detected
            else (
                normalized_stop_reason
                or normalized_selected_lane_block_reason
                or "manual_stop_lane_selected"
            )
        )
        out_next_action = "manual_review_required"
    elif (
        not block_reason
        and normalized_selected_lane in status_by_lane
        and selected_lane_allowed
        and lane_contract_ready
        and contract_schema_valid
        and contract_payload_lane_matches_selection
        and contract_action_allowed
        and not contract_conflict_detected
        and not normalized_conflicting_lanes
        and not manual_review_required
        and not should_stop
        and not should_invoke_codex
        and not should_execute_rollback
        and not should_execute_commit
        and not should_push
    ):
        status = status_by_lane[normalized_selected_lane]
        guarded_lane = normalized_selected_lane
        guarded_lane_allowed = True
        guarded_lane_block_reason = ""
        guarded_contract_ready = True
        guarded_contract_kind = normalized_selected_lane
        guarded_contract_action = payload_next_action
        guarded_contract_payload = dict(payload_mapping or {})
        downstream_refresh_allowed = True
        downstream_refresh_kind = normalized_selected_lane
        out_should_generate_next_prompt = bool(
            normalized_selected_lane == "next_prompt_lane" and should_generate_next_prompt
        )
        out_should_generate_fix_prompt = bool(
            normalized_selected_lane == "fix_prompt_lane" and should_generate_fix_prompt
        )
        out_should_prepare_rollback = bool(
            normalized_selected_lane == "rollback_readiness_lane" and should_prepare_rollback
        )
        out_should_prepare_commit = bool(
            normalized_selected_lane == "commit_readiness_lane" and should_prepare_commit
        )
        out_should_prepare_github_handoff = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = f"refresh_{normalized_selected_lane}"
    else:
        if guarded_lane_block_reason == "blocked_github_lane_not_enabled":
            status = "lane_contract_guard_blocked_github_not_enabled"
        elif guarded_lane_block_reason in {
            "blocked_lane_contract_not_ready",
            "blocked_lane_contract_not_dict",
            "blocked_lane_payload_missing_lane",
            "blocked_lane_payload_missing_source",
            "blocked_lane_payload_missing_next_action",
            "blocked_lane_payload_mismatch",
            "blocked_lane_kind_mismatch",
            "blocked_lane_action_mismatch",
            "blocked_lane_action_not_allowed",
        }:
            status = "lane_contract_guard_blocked_malformed_contract"
        elif guarded_lane_block_reason in {
            "blocked_lane_conflict_detected",
            "blocked_conflicting_lanes_present",
        }:
            status = "lane_contract_guard_blocked_conflict"
        else:
            status = "lane_contract_guard_blocked_insufficient_truth"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if guarded_contract_action not in allowed_next_actions:
        guarded_contract_action = "insufficient_truth"
    if status == "insufficient_truth":
        guarded_lane = "manual_stop_lane"
        guarded_lane_allowed = False
        guarded_lane_block_reason = "blocked_insufficient_lane_contract_truth"
        guarded_contract_ready = False
        guarded_contract_kind = "manual_stop_lane"
        guarded_contract_action = "manual_review_required"
        guarded_contract_payload = {
            "lane": "manual_stop_lane",
            "source": guarded_lane_source,
            "stop_reason": "insufficient_lane_contract_truth",
            "next_action": "manual_review_required",
        }
        downstream_refresh_allowed = False
        downstream_refresh_kind = "manual_stop_lane"
        out_should_generate_next_prompt = False
        out_should_generate_fix_prompt = False
        out_should_prepare_rollback = False
        out_should_prepare_commit = False
        out_should_prepare_github_handoff = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_lane_contract_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_lane_contract_guard_status": status,
        "project_browser_autonomous_lane_contract_guard_guarded_lane": guarded_lane,
        "project_browser_autonomous_lane_contract_guard_guarded_lane_allowed": bool(
            guarded_lane_allowed
        ),
        "project_browser_autonomous_lane_contract_guard_guarded_lane_block_reason": (
            guarded_lane_block_reason
        ),
        "project_browser_autonomous_lane_contract_guard_guarded_lane_source": guarded_lane_source,
        "project_browser_autonomous_lane_contract_guard_guarded_contract_ready": bool(
            guarded_contract_ready
        ),
        "project_browser_autonomous_lane_contract_guard_guarded_contract_kind": (
            guarded_contract_kind
        ),
        "project_browser_autonomous_lane_contract_guard_guarded_contract_action": (
            guarded_contract_action
        ),
        "project_browser_autonomous_lane_contract_guard_guarded_contract_payload": (
            guarded_contract_payload
        ),
        "project_browser_autonomous_lane_contract_guard_contract_schema_valid": bool(
            contract_schema_valid
        ),
        "project_browser_autonomous_lane_contract_guard_contract_payload_lane_matches_selection": bool(
            contract_payload_lane_matches_selection
        ),
        "project_browser_autonomous_lane_contract_guard_contract_action_allowed": bool(
            contract_action_allowed
        ),
        "project_browser_autonomous_lane_contract_guard_contract_manual_stop": bool(
            contract_manual_stop
        ),
        "project_browser_autonomous_lane_contract_guard_contract_conflict_detected": bool(
            contract_conflict_detected
        ),
        "project_browser_autonomous_lane_contract_guard_conflicting_lanes": (
            normalized_conflicting_lanes
        ),
        "project_browser_autonomous_lane_contract_guard_downstream_refresh_allowed": bool(
            downstream_refresh_allowed
        ),
        "project_browser_autonomous_lane_contract_guard_downstream_refresh_kind": (
            downstream_refresh_kind
        ),
        "project_browser_autonomous_lane_contract_guard_should_generate_next_prompt": bool(
            out_should_generate_next_prompt
        ),
        "project_browser_autonomous_lane_contract_guard_should_generate_fix_prompt": bool(
            out_should_generate_fix_prompt
        ),
        "project_browser_autonomous_lane_contract_guard_should_prepare_rollback": bool(
            out_should_prepare_rollback
        ),
        "project_browser_autonomous_lane_contract_guard_should_prepare_commit": bool(
            out_should_prepare_commit
        ),
        "project_browser_autonomous_lane_contract_guard_should_prepare_github_handoff": bool(
            out_should_prepare_github_handoff
        ),
        "project_browser_autonomous_lane_contract_guard_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_lane_contract_guard_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_lane_contract_guard_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_lane_contract_guard_should_push": bool(out_should_push),
        "project_browser_autonomous_lane_contract_guard_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_lane_contract_guard_should_stop": bool(out_should_stop),
        "project_browser_autonomous_lane_contract_guard_stop_reason": out_stop_reason,
        "project_browser_autonomous_lane_contract_guard_next_action": out_next_action,
        "project_browser_autonomous_lane_contract_guard_runtime_posture": runtime_posture,
        "project_browser_autonomous_lane_contract_guard_missing_inputs": _serialize_required_signals(
            [
                normalized_terminal_lane_status,
                normalized_selected_lane,
                normalized_selected_lane_block_reason,
                normalized_selected_lane_source,
                normalized_selected_lane_priority,
                normalized_lane_contract_kind,
                normalized_lane_contract_action,
                normalized_controller_status,
                normalized_controller_next_action,
                normalized_next_action,
                normalized_multi_cycle_controller_status,
                normalized_commit_tag_result_assimilation_status,
                normalized_post_rollback_fix_reentry_result_assimilation_status,
                "contract_not_schema_valid" if not contract_schema_valid else "",
                "contract_payload_lane_mismatch"
                if not contract_payload_lane_matches_selection
                else "",
                "contract_action_not_allowed" if not contract_action_allowed else "",
                "lane_conflict_detected_true" if contract_conflict_detected else "",
                "manual_review_required_true" if manual_review_required else "",
                "should_stop_true" if should_stop else "",
                "should_invoke_codex_true" if should_invoke_codex else "",
                "should_execute_rollback_true" if should_execute_rollback else "",
                "should_execute_commit_true" if should_execute_commit else "",
                "should_push_true" if should_push else "",
            ]
        ),
    }


def _build_project_browser_autonomous_guarded_lane_dispatch_state(
    *,
    lane_contract_guard_status: str,
    guarded_lane: str,
    guarded_lane_allowed: bool,
    guarded_lane_block_reason: str,
    guarded_lane_source: str,
    guarded_contract_ready: bool,
    guarded_contract_kind: str,
    guarded_contract_action: str,
    guarded_contract_payload: Any,
    contract_schema_valid: bool,
    contract_payload_lane_matches_selection: bool,
    contract_action_allowed: bool,
    contract_manual_stop: bool,
    contract_conflict_detected: bool,
    conflicting_lanes: Sequence[Any],
    downstream_refresh_allowed: bool,
    downstream_refresh_kind: str,
    should_generate_next_prompt: bool,
    should_generate_fix_prompt: bool,
    should_prepare_rollback: bool,
    should_prepare_commit: bool,
    should_prepare_github_handoff: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_execute_commit: bool,
    should_push: bool,
    manual_review_required: bool,
    should_stop: bool,
    stop_reason: str,
    next_action: str,
    terminal_lane_status: str,
    multi_cycle_controller_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "guarded_lane_dispatch_next_prompt_refresh_ready",
        "guarded_lane_dispatch_fix_prompt_refresh_ready",
        "guarded_lane_dispatch_rollback_readiness_refresh_ready",
        "guarded_lane_dispatch_commit_readiness_refresh_ready",
        "guarded_lane_dispatch_manual_stop",
        "guarded_lane_dispatch_blocked",
        "guarded_lane_dispatch_blocked_refresh_conflict",
        "guarded_lane_dispatch_blocked_github_not_enabled",
        "guarded_lane_dispatch_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "execute_next_prompt_generation",
        "execute_fix_prompt_generation",
        "execute_rollback_readiness_refresh",
        "execute_commit_readiness_refresh",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt200_guarded_lane_dispatch",
        "metadata_only",
        "single_lane_refresh_dispatch",
        "no_execution",
        "no_codex_invocation",
        "no_git_mutation",
        "no_rollback_execution",
        "no_push",
    ]
    supported_dispatch_lanes = {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
    }

    normalized_guard_status = _normalize_text(lane_contract_guard_status, default="insufficient_truth")
    normalized_guarded_lane = _normalize_text(guarded_lane, default="")
    normalized_guarded_lane_block_reason = _normalize_text(guarded_lane_block_reason, default="")
    normalized_guarded_lane_source = _normalize_text(guarded_lane_source, default="terminal_lane_decision")
    normalized_guarded_contract_kind = _normalize_text(guarded_contract_kind, default="")
    normalized_guarded_contract_action = _normalize_text(guarded_contract_action, default="")
    normalized_downstream_refresh_kind = _normalize_text(downstream_refresh_kind, default="")
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_next_action = _normalize_text(next_action, default="")
    normalized_terminal_lane_status = _normalize_text(terminal_lane_status, default="insufficient_truth")
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status,
        default="insufficient_truth",
    )
    normalized_conflicting_lanes = _normalize_string_list(conflicting_lanes)
    payload_mapping = dict(guarded_contract_payload) if isinstance(guarded_contract_payload, Mapping) else {}
    payload_lane = _normalize_text(payload_mapping.get("lane"), default="")
    payload_next_action = _normalize_text(payload_mapping.get("next_action"), default="")
    github_lane_detected = bool(
        normalized_guarded_lane == "github_readiness_lane"
        or normalized_guarded_contract_kind == "github_readiness_lane"
        or payload_lane == "github_readiness_lane"
        or payload_next_action == "github_readiness_not_enabled"
    )

    dispatch_allowed = False
    dispatch_applied = False
    dispatch_block_reason = ""
    dispatch_source = normalized_guarded_lane_source or "lane_contract_guard"
    selected_lane = normalized_guarded_lane
    selected_lane_action = normalized_guarded_contract_action
    selected_lane_payload: dict[str, Any] = dict(payload_mapping)
    refreshed_downstream_kind = ""
    refreshed_downstream_source = ""
    next_prompt_refresh_allowed = False
    fix_prompt_refresh_allowed = False
    rollback_readiness_refresh_allowed = False
    commit_readiness_refresh_allowed = False
    manual_stop_refresh_applied = False
    downstream_execution_allowed_next = False
    downstream_execution_kind = ""
    downstream_execution_action = ""
    downstream_execution_payload: dict[str, Any] = {}
    out_should_generate_next_prompt = False
    out_should_generate_fix_prompt = False
    out_should_prepare_rollback = False
    out_should_prepare_commit = False
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_stop_reason or "blocked_insufficient_guarded_lane_dispatch_truth"
    out_next_action = "manual_review_required"
    status = "guarded_lane_dispatch_blocked_insufficient_truth"

    if (
        normalized_guarded_lane == "manual_stop_lane"
        or contract_manual_stop
        or manual_review_required
        or should_stop
    ):
        status = "guarded_lane_dispatch_manual_stop"
        dispatch_allowed = False
        dispatch_applied = True
        dispatch_block_reason = (
            normalized_guarded_lane_block_reason
            or normalized_stop_reason
            or "manual_stop_lane_selected"
        )
        selected_lane = "manual_stop_lane"
        selected_lane_action = "manual_review_required"
        selected_lane_payload = {
            "lane": "manual_stop_lane",
            "source": dispatch_source,
            "stop_reason": normalized_stop_reason
            or normalized_guarded_lane_block_reason
            or "manual_stop_lane_selected",
            "next_action": "manual_review_required",
        }
        manual_stop_refresh_applied = True
        downstream_execution_allowed_next = False
        downstream_execution_kind = "manual_stop_lane"
        downstream_execution_action = "manual_review_required"
        downstream_execution_payload = dict(selected_lane_payload)
        out_should_generate_next_prompt = False
        out_should_generate_fix_prompt = False
        out_should_prepare_rollback = False
        out_should_prepare_commit = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = (
            normalized_stop_reason
            or normalized_guarded_lane_block_reason
            or "manual_stop_lane_selected"
        )
        out_next_action = "manual_review_required"
    else:
        if not guarded_lane_allowed:
            dispatch_block_reason = "blocked_guarded_lane_not_allowed"
        elif not guarded_contract_ready:
            dispatch_block_reason = "blocked_guarded_contract_not_ready"
        elif not downstream_refresh_allowed:
            dispatch_block_reason = "blocked_downstream_refresh_not_allowed"
        elif not contract_schema_valid:
            dispatch_block_reason = "blocked_contract_schema_invalid"
        elif not contract_payload_lane_matches_selection:
            dispatch_block_reason = "blocked_lane_payload_mismatch"
        elif not contract_action_allowed:
            dispatch_block_reason = "blocked_lane_action_not_allowed"
        elif contract_conflict_detected:
            dispatch_block_reason = "blocked_lane_conflict_detected"
        elif manual_review_required:
            dispatch_block_reason = "blocked_manual_review_required"
        elif should_stop:
            dispatch_block_reason = "blocked_should_stop"
        elif should_invoke_codex:
            dispatch_block_reason = "blocked_unexpected_codex_invocation_flag"
        elif should_execute_rollback:
            dispatch_block_reason = "blocked_unexpected_rollback_execution_flag"
        elif should_execute_commit:
            dispatch_block_reason = "blocked_unexpected_commit_execution_flag"
        elif should_push:
            dispatch_block_reason = "blocked_unexpected_push_flag"
        elif github_lane_detected:
            dispatch_block_reason = "github_lane_not_enabled"
        elif normalized_guarded_lane not in supported_dispatch_lanes:
            dispatch_block_reason = "blocked_unknown_guarded_lane"
        elif not normalized_guarded_lane:
            dispatch_block_reason = "blocked_insufficient_guarded_lane_dispatch_truth"

        if dispatch_block_reason:
            status = (
                "guarded_lane_dispatch_blocked_github_not_enabled"
                if dispatch_block_reason == "github_lane_not_enabled"
                else "guarded_lane_dispatch_blocked"
            )
            dispatch_allowed = False
            dispatch_applied = False
            out_should_generate_next_prompt = False
            out_should_generate_fix_prompt = False
            out_should_prepare_rollback = False
            out_should_prepare_commit = False
            out_manual_review_required = True
            out_should_stop = True
            out_stop_reason = normalized_stop_reason or dispatch_block_reason
            out_next_action = "manual_review_required"
            downstream_execution_allowed_next = False
            downstream_execution_kind = ""
            downstream_execution_action = ""
            downstream_execution_payload = {}
        else:
            dispatch_allowed = True
            dispatch_applied = True
            dispatch_block_reason = ""
            refreshed_downstream_source = "prompt200_guarded_lane_dispatch"
            selected_lane = normalized_guarded_lane
            selected_lane_action = normalized_guarded_contract_action
            selected_lane_payload = dict(payload_mapping)
            downstream_execution_allowed_next = True
            downstream_execution_payload = dict(payload_mapping)
            out_should_invoke_codex = False
            out_should_execute_rollback = False
            out_should_execute_commit = False
            out_should_push = False
            out_manual_review_required = False
            out_should_stop = False
            out_stop_reason = ""

            if normalized_guarded_lane == "next_prompt_lane":
                status = "guarded_lane_dispatch_next_prompt_refresh_ready"
                next_prompt_refresh_allowed = True
                refreshed_downstream_kind = "next_prompt_generation"
                downstream_execution_kind = "next_prompt_generation"
                downstream_execution_action = "execute_next_prompt_generation"
                out_should_generate_next_prompt = True
                out_should_generate_fix_prompt = False
                out_should_prepare_rollback = False
                out_should_prepare_commit = False
                out_next_action = "execute_next_prompt_generation"
            elif normalized_guarded_lane == "fix_prompt_lane":
                status = "guarded_lane_dispatch_fix_prompt_refresh_ready"
                fix_prompt_refresh_allowed = True
                refreshed_downstream_kind = "fix_prompt_generation"
                downstream_execution_kind = "fix_prompt_generation"
                downstream_execution_action = "execute_fix_prompt_generation"
                out_should_generate_next_prompt = False
                out_should_generate_fix_prompt = True
                out_should_prepare_rollback = False
                out_should_prepare_commit = False
                out_next_action = "execute_fix_prompt_generation"
            elif normalized_guarded_lane == "rollback_readiness_lane":
                status = "guarded_lane_dispatch_rollback_readiness_refresh_ready"
                rollback_readiness_refresh_allowed = True
                refreshed_downstream_kind = "rollback_readiness"
                downstream_execution_kind = "rollback_readiness"
                downstream_execution_action = "execute_rollback_readiness_refresh"
                out_should_generate_next_prompt = False
                out_should_generate_fix_prompt = False
                out_should_prepare_rollback = True
                out_should_prepare_commit = False
                out_next_action = "execute_rollback_readiness_refresh"
            elif normalized_guarded_lane == "commit_readiness_lane":
                status = "guarded_lane_dispatch_commit_readiness_refresh_ready"
                commit_readiness_refresh_allowed = True
                refreshed_downstream_kind = "commit_tag_readiness"
                downstream_execution_kind = "commit_tag_readiness"
                downstream_execution_action = "execute_commit_readiness_refresh"
                out_should_generate_next_prompt = False
                out_should_generate_fix_prompt = False
                out_should_prepare_rollback = False
                out_should_prepare_commit = True
                out_next_action = "execute_commit_readiness_refresh"

    refresh_flags = [
        next_prompt_refresh_allowed,
        fix_prompt_refresh_allowed,
        rollback_readiness_refresh_allowed,
        commit_readiness_refresh_allowed,
        manual_stop_refresh_applied,
    ]
    if sum(1 for flag in refresh_flags if flag) > 1:
        status = "guarded_lane_dispatch_blocked_refresh_conflict"
        dispatch_allowed = False
        dispatch_applied = False
        dispatch_block_reason = "blocked_multiple_downstream_refreshes"
        next_prompt_refresh_allowed = False
        fix_prompt_refresh_allowed = False
        rollback_readiness_refresh_allowed = False
        commit_readiness_refresh_allowed = False
        manual_stop_refresh_applied = False
        downstream_execution_allowed_next = False
        downstream_execution_kind = ""
        downstream_execution_action = ""
        downstream_execution_payload = {}
        out_should_generate_next_prompt = False
        out_should_generate_fix_prompt = False
        out_should_prepare_rollback = False
        out_should_prepare_commit = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "multiple_downstream_refreshes_selected"
        out_next_action = "manual_review_required"

    if not dispatch_block_reason and not dispatch_allowed and not dispatch_applied and status in {
        "guarded_lane_dispatch_blocked",
        "guarded_lane_dispatch_blocked_insufficient_truth",
    }:
        dispatch_block_reason = "blocked_insufficient_guarded_lane_dispatch_truth"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        dispatch_allowed = False
        dispatch_applied = False
        dispatch_block_reason = "blocked_insufficient_guarded_lane_dispatch_truth"
        selected_lane = "manual_stop_lane"
        selected_lane_action = "manual_review_required"
        selected_lane_payload = {}
        refreshed_downstream_kind = ""
        refreshed_downstream_source = ""
        next_prompt_refresh_allowed = False
        fix_prompt_refresh_allowed = False
        rollback_readiness_refresh_allowed = False
        commit_readiness_refresh_allowed = False
        manual_stop_refresh_applied = False
        downstream_execution_allowed_next = False
        downstream_execution_kind = ""
        downstream_execution_action = ""
        downstream_execution_payload = {}
        out_should_generate_next_prompt = False
        out_should_generate_fix_prompt = False
        out_should_prepare_rollback = False
        out_should_prepare_commit = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_insufficient_guarded_lane_dispatch_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_guarded_lane_dispatch_status": status,
        "project_browser_autonomous_guarded_lane_dispatch_dispatch_allowed": bool(dispatch_allowed),
        "project_browser_autonomous_guarded_lane_dispatch_dispatch_applied": bool(dispatch_applied),
        "project_browser_autonomous_guarded_lane_dispatch_dispatch_block_reason": dispatch_block_reason,
        "project_browser_autonomous_guarded_lane_dispatch_dispatch_source": dispatch_source,
        "project_browser_autonomous_guarded_lane_dispatch_selected_lane": selected_lane,
        "project_browser_autonomous_guarded_lane_dispatch_selected_lane_action": selected_lane_action,
        "project_browser_autonomous_guarded_lane_dispatch_selected_lane_payload": selected_lane_payload,
        "project_browser_autonomous_guarded_lane_dispatch_refreshed_downstream_kind": (
            refreshed_downstream_kind
        ),
        "project_browser_autonomous_guarded_lane_dispatch_refreshed_downstream_source": (
            refreshed_downstream_source
        ),
        "project_browser_autonomous_guarded_lane_dispatch_next_prompt_refresh_allowed": bool(
            next_prompt_refresh_allowed
        ),
        "project_browser_autonomous_guarded_lane_dispatch_fix_prompt_refresh_allowed": bool(
            fix_prompt_refresh_allowed
        ),
        "project_browser_autonomous_guarded_lane_dispatch_rollback_readiness_refresh_allowed": bool(
            rollback_readiness_refresh_allowed
        ),
        "project_browser_autonomous_guarded_lane_dispatch_commit_readiness_refresh_allowed": bool(
            commit_readiness_refresh_allowed
        ),
        "project_browser_autonomous_guarded_lane_dispatch_manual_stop_refresh_applied": bool(
            manual_stop_refresh_applied
        ),
        "project_browser_autonomous_guarded_lane_dispatch_downstream_execution_allowed_next": bool(
            downstream_execution_allowed_next
        ),
        "project_browser_autonomous_guarded_lane_dispatch_downstream_execution_kind": (
            downstream_execution_kind
        ),
        "project_browser_autonomous_guarded_lane_dispatch_downstream_execution_action": (
            downstream_execution_action
        ),
        "project_browser_autonomous_guarded_lane_dispatch_downstream_execution_payload": (
            downstream_execution_payload
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_generate_next_prompt": bool(
            out_should_generate_next_prompt
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_generate_fix_prompt": bool(
            out_should_generate_fix_prompt
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_prepare_rollback": bool(
            out_should_prepare_rollback
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_prepare_commit": bool(
            out_should_prepare_commit
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_push": bool(out_should_push),
        "project_browser_autonomous_guarded_lane_dispatch_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_guarded_lane_dispatch_should_stop": bool(out_should_stop),
        "project_browser_autonomous_guarded_lane_dispatch_stop_reason": out_stop_reason,
        "project_browser_autonomous_guarded_lane_dispatch_next_action": out_next_action,
        "project_browser_autonomous_guarded_lane_dispatch_runtime_posture": runtime_posture,
        "project_browser_autonomous_guarded_lane_dispatch_missing_inputs": _serialize_required_signals(
            [
                normalized_guard_status,
                normalized_guarded_lane,
                normalized_guarded_lane_block_reason,
                normalized_guarded_lane_source,
                normalized_guarded_contract_kind,
                normalized_guarded_contract_action,
                normalized_downstream_refresh_kind,
                normalized_stop_reason,
                normalized_next_action,
                normalized_terminal_lane_status,
                normalized_multi_cycle_controller_status,
                "contract_schema_invalid" if not contract_schema_valid else "",
                "contract_payload_lane_mismatch"
                if not contract_payload_lane_matches_selection
                else "",
                "contract_action_not_allowed" if not contract_action_allowed else "",
                "contract_conflict_detected_true" if contract_conflict_detected else "",
                "guarded_lane_allowed_false" if not guarded_lane_allowed else "",
                "guarded_contract_ready_false" if not guarded_contract_ready else "",
                "downstream_refresh_not_allowed" if not downstream_refresh_allowed else "",
                "manual_review_required_true" if manual_review_required else "",
                "should_stop_true" if should_stop else "",
                "should_invoke_codex_true" if should_invoke_codex else "",
                "should_execute_rollback_true" if should_execute_rollback else "",
                "should_execute_commit_true" if should_execute_commit else "",
                "should_push_true" if should_push else "",
                "conflicting_lanes_present" if normalized_conflicting_lanes else "",
            ]
        ),
    }


def _build_project_browser_autonomous_selected_lane_execution_state(
    *,
    dispatch_status: str,
    dispatch_allowed: bool,
    dispatch_applied: bool,
    dispatch_block_reason: str,
    dispatch_source: str,
    selected_lane: str,
    selected_lane_action: str,
    selected_lane_payload: Any,
    refreshed_downstream_kind: str,
    refreshed_downstream_source: str,
    next_prompt_refresh_allowed: bool,
    fix_prompt_refresh_allowed: bool,
    rollback_readiness_refresh_allowed: bool,
    commit_readiness_refresh_allowed: bool,
    manual_stop_refresh_applied: bool,
    downstream_execution_allowed_next: bool,
    downstream_execution_kind: str,
    downstream_execution_action: str,
    downstream_execution_payload: Any,
    should_generate_next_prompt: bool,
    should_generate_fix_prompt: bool,
    should_prepare_rollback: bool,
    should_prepare_commit: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_execute_commit: bool,
    should_push: bool,
    manual_review_required: bool,
    should_stop: bool,
    stop_reason: str,
    dispatch_next_action: str,
    next_prompt_generation_status: str,
    next_prompt_generated: bool,
    next_prompt_handoff_path: str,
    next_prompt_handoff_write_completed: bool,
    next_prompt_handoff_write_failed: bool,
    next_prompt_human_review_required: bool,
    fix_prompt_generation_status: str,
    fix_prompt_generated: bool,
    fix_prompt_handoff_path: str,
    fix_prompt_handoff_write_completed: bool,
    fix_prompt_handoff_write_failed: bool,
    fix_prompt_human_review_required: bool,
    rollback_readiness_status: str,
    rollback_readiness_allowed: bool,
    rollback_readiness_human_review_required: bool,
    commit_readiness_status: str,
    commit_readiness_allowed: bool,
    commit_readiness_human_review_required: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "selected_lane_execution_next_prompt_completed",
        "selected_lane_execution_fix_prompt_completed",
        "selected_lane_execution_rollback_readiness_completed",
        "selected_lane_execution_commit_readiness_completed",
        "selected_lane_execution_manual_stop",
        "selected_lane_execution_blocked_not_allowed",
        "selected_lane_execution_blocked_multiple_lanes",
        "selected_lane_execution_blocked_unknown_lane",
        "selected_lane_execution_blocked_insufficient_truth",
        "selected_lane_execution_failed",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_generated_prompt_reentry_or_controller_feedback",
        "prepare_rollback_execution_or_controller_feedback",
        "prepare_commit_execution_or_controller_feedback",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt201_selected_lane_execution",
        "single_lane_execution",
        "bounded_once",
        "no_codex_invocation",
        "no_validation",
        "no_rollback_execution",
        "no_git_mutation",
        "no_push",
    ]
    executable_lanes = {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
    }
    normalized_dispatch_status = _normalize_text(dispatch_status, default="insufficient_truth")
    normalized_dispatch_block_reason = _normalize_text(dispatch_block_reason, default="")
    normalized_dispatch_source = _normalize_text(dispatch_source, default="")
    normalized_selected_lane = _normalize_text(selected_lane, default="")
    normalized_selected_lane_action = _normalize_text(selected_lane_action, default="")
    normalized_refreshed_downstream_kind = _normalize_text(refreshed_downstream_kind, default="")
    normalized_refreshed_downstream_source = _normalize_text(refreshed_downstream_source, default="")
    normalized_downstream_execution_kind = _normalize_text(downstream_execution_kind, default="")
    normalized_downstream_execution_action = _normalize_text(downstream_execution_action, default="")
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_dispatch_next_action = _normalize_text(dispatch_next_action, default="")
    normalized_next_prompt_generation_status = _normalize_text(
        next_prompt_generation_status, default="insufficient_truth"
    )
    normalized_fix_prompt_generation_status = _normalize_text(
        fix_prompt_generation_status, default="insufficient_truth"
    )
    normalized_rollback_readiness_status = _normalize_text(
        rollback_readiness_status, default="insufficient_truth"
    )
    normalized_commit_readiness_status = _normalize_text(
        commit_readiness_status, default="insufficient_truth"
    )
    normalized_next_prompt_handoff_path = _normalize_text(next_prompt_handoff_path, default="")
    normalized_fix_prompt_handoff_path = _normalize_text(fix_prompt_handoff_path, default="")
    normalized_selected_lane_payload = (
        dict(selected_lane_payload) if isinstance(selected_lane_payload, Mapping) else {}
    )
    normalized_downstream_execution_payload = (
        dict(downstream_execution_payload)
        if isinstance(downstream_execution_payload, Mapping)
        else {}
    )
    refresh_true_count = sum(
        1
        for flag in (
            bool(next_prompt_refresh_allowed),
            bool(fix_prompt_refresh_allowed),
            bool(rollback_readiness_refresh_allowed),
            bool(commit_readiness_refresh_allowed),
        )
        if flag
    )

    status = "selected_lane_execution_blocked_insufficient_truth"
    execution_allowed = False
    execution_attempted = False
    execution_completed = False
    execution_failed = False
    execution_block_reason = "blocked_insufficient_selected_lane_execution_truth"
    execution_source = normalized_dispatch_source or "prompt200_guarded_lane_dispatch"
    output_selected_lane = normalized_selected_lane
    output_selected_lane_action = normalized_selected_lane_action
    executed_downstream_kind = ""
    executed_downstream_action = ""
    non_selected_lanes_noop = True
    next_prompt_lane_executed = False
    fix_prompt_lane_executed = False
    rollback_readiness_lane_executed = False
    commit_readiness_lane_executed = False
    manual_stop_executed = False
    generated_prompt_kind = "none"
    generated_prompt_path = ""
    generated_prompt_ready_for_reentry = False
    rollback_readiness_ready = False
    commit_readiness_ready = False
    result_class = "blocked"
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_stop_reason or "blocked_insufficient_selected_lane_execution_truth"
    out_next_action = "manual_review_required"

    if (
        normalized_selected_lane == "manual_stop_lane"
        or bool(manual_stop_refresh_applied)
        or bool(manual_review_required)
        or bool(should_stop)
    ):
        status = "selected_lane_execution_manual_stop"
        execution_allowed = False
        execution_attempted = False
        execution_completed = False
        execution_failed = False
        execution_block_reason = (
            normalized_dispatch_block_reason
            or normalized_stop_reason
            or "manual_stop_lane_selected"
        )
        output_selected_lane = "manual_stop_lane"
        output_selected_lane_action = "manual_review_required"
        executed_downstream_kind = "manual_stop_lane"
        executed_downstream_action = "manual_review_required"
        non_selected_lanes_noop = True
        manual_stop_executed = True
        result_class = "manual_stop"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_stop_reason or "manual_stop_lane_selected"
        out_next_action = "manual_review_required"
    else:
        if not bool(dispatch_allowed):
            execution_block_reason = "blocked_dispatch_not_allowed"
            status = "selected_lane_execution_blocked_not_allowed"
        elif not bool(dispatch_applied):
            execution_block_reason = "blocked_dispatch_not_applied"
            status = "selected_lane_execution_blocked_not_allowed"
        elif not bool(downstream_execution_allowed_next):
            execution_block_reason = "blocked_downstream_execution_not_allowed"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(manual_review_required):
            execution_block_reason = "blocked_manual_review_required"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(should_stop):
            execution_block_reason = "blocked_should_stop"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(should_invoke_codex):
            execution_block_reason = "blocked_unexpected_codex_invocation_flag"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(should_execute_rollback):
            execution_block_reason = "blocked_unexpected_rollback_execution_flag"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(should_execute_commit):
            execution_block_reason = "blocked_unexpected_commit_execution_flag"
            status = "selected_lane_execution_blocked_not_allowed"
        elif bool(should_push):
            execution_block_reason = "blocked_unexpected_push_flag"
            status = "selected_lane_execution_blocked_not_allowed"
        elif refresh_true_count > 1:
            execution_block_reason = "blocked_multiple_lane_refreshes"
            status = "selected_lane_execution_blocked_multiple_lanes"
        elif normalized_selected_lane not in executable_lanes:
            execution_block_reason = "blocked_unknown_selected_lane"
            status = "selected_lane_execution_blocked_unknown_lane"
        elif refresh_true_count != 1:
            execution_block_reason = "blocked_insufficient_selected_lane_execution_truth"
            status = "selected_lane_execution_blocked_insufficient_truth"
        else:
            execution_allowed = True
            execution_attempted = True
            executed_downstream_kind = (
                normalized_downstream_execution_kind or normalized_refreshed_downstream_kind
            )
            executed_downstream_action = (
                normalized_downstream_execution_action or normalized_selected_lane_action
            )

            if normalized_selected_lane == "next_prompt_lane":
                next_prompt_lane_executed = True
                generated_prompt_kind = "next"
                generated_prompt_path = normalized_next_prompt_handoff_path
                generated_prompt_ready_for_reentry = bool(
                    normalized_next_prompt_generation_status == "prompt_generated"
                    and bool(next_prompt_generated)
                    and bool(next_prompt_handoff_write_completed)
                    and not bool(next_prompt_handoff_write_failed)
                    and bool(generated_prompt_path)
                    and not bool(next_prompt_human_review_required)
                )
                if generated_prompt_ready_for_reentry:
                    status = "selected_lane_execution_next_prompt_completed"
                    execution_completed = True
                    result_class = "completed_next_prompt_generation"
                    out_manual_review_required = False
                    out_should_stop = False
                    out_stop_reason = ""
                    out_next_action = "prepare_generated_prompt_reentry_or_controller_feedback"
                else:
                    status = "selected_lane_execution_failed"
                    execution_failed = True
                    execution_block_reason = "blocked_existing_downstream_safety_gate"
                    result_class = "failed_next_prompt_generation"
                    out_manual_review_required = True
                    out_should_stop = True
                    out_stop_reason = execution_block_reason
                    out_next_action = "manual_review_required"
            elif normalized_selected_lane == "fix_prompt_lane":
                fix_prompt_lane_executed = True
                generated_prompt_kind = "fix"
                generated_prompt_path = normalized_fix_prompt_handoff_path
                generated_prompt_ready_for_reentry = bool(
                    normalized_fix_prompt_generation_status == "prompt_generated"
                    and bool(fix_prompt_generated)
                    and bool(fix_prompt_handoff_write_completed)
                    and not bool(fix_prompt_handoff_write_failed)
                    and bool(generated_prompt_path)
                    and not bool(fix_prompt_human_review_required)
                )
                if generated_prompt_ready_for_reentry:
                    status = "selected_lane_execution_fix_prompt_completed"
                    execution_completed = True
                    result_class = "completed_fix_prompt_generation"
                    out_manual_review_required = False
                    out_should_stop = False
                    out_stop_reason = ""
                    out_next_action = "prepare_generated_prompt_reentry_or_controller_feedback"
                else:
                    status = "selected_lane_execution_failed"
                    execution_failed = True
                    execution_block_reason = "blocked_existing_downstream_safety_gate"
                    result_class = "failed_fix_prompt_generation"
                    out_manual_review_required = True
                    out_should_stop = True
                    out_stop_reason = execution_block_reason
                    out_next_action = "manual_review_required"
            elif normalized_selected_lane == "rollback_readiness_lane":
                rollback_readiness_lane_executed = True
                rollback_readiness_ready = bool(
                    bool(rollback_readiness_allowed)
                    and normalized_rollback_readiness_status == "rollback_readiness_allowed"
                    and not bool(rollback_readiness_human_review_required)
                )
                status = "selected_lane_execution_rollback_readiness_completed"
                execution_completed = True
                result_class = "completed_rollback_readiness"
                out_manual_review_required = bool(rollback_readiness_human_review_required)
                out_should_stop = bool(rollback_readiness_human_review_required)
                out_stop_reason = (
                    "manual_review_required"
                    if bool(rollback_readiness_human_review_required)
                    else ""
                )
                out_next_action = (
                    "manual_review_required"
                    if bool(rollback_readiness_human_review_required)
                    else "prepare_rollback_execution_or_controller_feedback"
                )
            elif normalized_selected_lane == "commit_readiness_lane":
                commit_readiness_lane_executed = True
                commit_readiness_ready = bool(
                    bool(commit_readiness_allowed)
                    and normalized_commit_readiness_status == "commit_tag_readiness_allowed"
                    and not bool(commit_readiness_human_review_required)
                )
                status = "selected_lane_execution_commit_readiness_completed"
                execution_completed = True
                result_class = "completed_commit_readiness"
                out_manual_review_required = bool(commit_readiness_human_review_required)
                out_should_stop = bool(commit_readiness_human_review_required)
                out_stop_reason = (
                    "manual_review_required"
                    if bool(commit_readiness_human_review_required)
                    else ""
                )
                out_next_action = (
                    "manual_review_required"
                    if bool(commit_readiness_human_review_required)
                    else "prepare_commit_execution_or_controller_feedback"
                )
            else:
                status = "selected_lane_execution_blocked_unknown_lane"
                execution_allowed = False
                execution_attempted = False
                execution_completed = False
                execution_failed = False
                execution_block_reason = "blocked_unknown_selected_lane"
                output_selected_lane = "manual_stop_lane"
                output_selected_lane_action = "manual_review_required"
                result_class = "blocked_unknown_lane"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = execution_block_reason
                out_next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        status = "selected_lane_execution_blocked_insufficient_truth"
        execution_allowed = False
        execution_attempted = False
        execution_completed = False
        execution_failed = False
        execution_block_reason = "blocked_insufficient_selected_lane_execution_truth"
        output_selected_lane = "manual_stop_lane"
        output_selected_lane_action = "manual_review_required"
        executed_downstream_kind = ""
        executed_downstream_action = ""
        non_selected_lanes_noop = True
        next_prompt_lane_executed = False
        fix_prompt_lane_executed = False
        rollback_readiness_lane_executed = False
        commit_readiness_lane_executed = False
        manual_stop_executed = False
        generated_prompt_kind = "none"
        generated_prompt_path = ""
        generated_prompt_ready_for_reentry = False
        rollback_readiness_ready = False
        commit_readiness_ready = False
        result_class = "blocked"
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_insufficient_selected_lane_execution_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_selected_lane_execution_status": status,
        "project_browser_autonomous_selected_lane_execution_selected_lane": (
            _normalize_text(output_selected_lane, default="manual_stop_lane")
        ),
        "project_browser_autonomous_selected_lane_execution_selected_lane_action": (
            _normalize_text(output_selected_lane_action, default="manual_review_required")
        ),
        "project_browser_autonomous_selected_lane_execution_execution_allowed": bool(
            execution_allowed
        ),
        "project_browser_autonomous_selected_lane_execution_execution_attempted": bool(
            execution_attempted
        ),
        "project_browser_autonomous_selected_lane_execution_execution_completed": bool(
            execution_completed
        ),
        "project_browser_autonomous_selected_lane_execution_execution_failed": bool(
            execution_failed
        ),
        "project_browser_autonomous_selected_lane_execution_execution_block_reason": (
            execution_block_reason
        ),
        "project_browser_autonomous_selected_lane_execution_execution_source": execution_source,
        "project_browser_autonomous_selected_lane_execution_executed_downstream_kind": (
            executed_downstream_kind
        ),
        "project_browser_autonomous_selected_lane_execution_executed_downstream_action": (
            executed_downstream_action
        ),
        "project_browser_autonomous_selected_lane_execution_non_selected_lanes_noop": bool(
            non_selected_lanes_noop
        ),
        "project_browser_autonomous_selected_lane_execution_next_prompt_lane_executed": bool(
            next_prompt_lane_executed
        ),
        "project_browser_autonomous_selected_lane_execution_fix_prompt_lane_executed": bool(
            fix_prompt_lane_executed
        ),
        "project_browser_autonomous_selected_lane_execution_rollback_readiness_lane_executed": bool(
            rollback_readiness_lane_executed
        ),
        "project_browser_autonomous_selected_lane_execution_commit_readiness_lane_executed": bool(
            commit_readiness_lane_executed
        ),
        "project_browser_autonomous_selected_lane_execution_manual_stop_executed": bool(
            manual_stop_executed
        ),
        "project_browser_autonomous_selected_lane_execution_generated_prompt_kind": (
            generated_prompt_kind
        ),
        "project_browser_autonomous_selected_lane_execution_generated_prompt_path": (
            generated_prompt_path
        ),
        "project_browser_autonomous_selected_lane_execution_generated_prompt_ready_for_reentry": bool(
            generated_prompt_ready_for_reentry
        ),
        "project_browser_autonomous_selected_lane_execution_rollback_readiness_ready": bool(
            rollback_readiness_ready
        ),
        "project_browser_autonomous_selected_lane_execution_commit_readiness_ready": bool(
            commit_readiness_ready
        ),
        "project_browser_autonomous_selected_lane_execution_result_class": result_class,
        "project_browser_autonomous_selected_lane_execution_selected_action_result_ready_for_assimilation": True,
        "project_browser_autonomous_selected_lane_execution_selected_action_result_assimilation_source": (
            "prompt201_selected_lane_execution"
        ),
        "project_browser_autonomous_selected_lane_execution_selected_action_result_next_stage": (
            "selected_lane_result_assimilation"
        ),
        "project_browser_autonomous_selected_lane_execution_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_selected_lane_execution_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_selected_lane_execution_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_selected_lane_execution_should_push": bool(out_should_push),
        "project_browser_autonomous_selected_lane_execution_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_selected_lane_execution_should_stop": bool(out_should_stop),
        "project_browser_autonomous_selected_lane_execution_stop_reason": out_stop_reason,
        "project_browser_autonomous_selected_lane_execution_next_action": out_next_action,
        "project_browser_autonomous_selected_lane_execution_runtime_posture": runtime_posture,
        "project_browser_autonomous_selected_lane_execution_missing_inputs": _serialize_required_signals(
            [
                normalized_dispatch_status,
                normalized_dispatch_block_reason,
                normalized_dispatch_source,
                normalized_selected_lane,
                normalized_selected_lane_action,
                normalized_refreshed_downstream_kind,
                normalized_refreshed_downstream_source,
                normalized_downstream_execution_kind,
                normalized_downstream_execution_action,
                normalized_stop_reason,
                normalized_dispatch_next_action,
                normalized_next_prompt_generation_status,
                normalized_fix_prompt_generation_status,
                normalized_rollback_readiness_status,
                normalized_commit_readiness_status,
                "next_prompt_generated_false"
                if normalized_selected_lane == "next_prompt_lane" and not bool(next_prompt_generated)
                else "",
                "fix_prompt_generated_false"
                if normalized_selected_lane == "fix_prompt_lane" and not bool(fix_prompt_generated)
                else "",
                "refresh_true_count_not_one" if refresh_true_count != 1 else "",
                "manual_review_required_true" if manual_review_required else "",
                "should_stop_true" if should_stop else "",
                "should_invoke_codex_true" if should_invoke_codex else "",
                "should_execute_rollback_true" if should_execute_rollback else "",
                "should_execute_commit_true" if should_execute_commit else "",
                "should_push_true" if should_push else "",
                _normalize_text(normalized_next_prompt_handoff_path, default=""),
                _normalize_text(normalized_fix_prompt_handoff_path, default=""),
            ]
        ),
    }


def _build_project_browser_autonomous_selected_lane_result_assimilation_state(
    *,
    selected_lane_execution_status: str,
    selected_lane: str,
    selected_lane_action: str,
    execution_allowed: bool,
    execution_attempted: bool,
    execution_completed: bool,
    execution_failed: bool,
    execution_block_reason: str,
    execution_source: str,
    non_selected_lanes_noop: bool,
    next_prompt_lane_executed: bool,
    fix_prompt_lane_executed: bool,
    rollback_readiness_lane_executed: bool,
    commit_readiness_lane_executed: bool,
    manual_stop_executed: bool,
    generated_prompt_kind: str,
    generated_prompt_path: str,
    generated_prompt_ready_for_reentry: bool,
    rollback_readiness_ready: bool,
    commit_readiness_ready: bool,
    execution_result_class: str,
    selected_action_result_ready_for_assimilation: bool,
    selected_action_result_assimilation_source: str,
    selected_action_result_next_stage: str,
    execution_manual_review_required: bool,
    execution_should_stop: bool,
    execution_stop_reason: str,
    execution_next_action: str,
    guarded_dispatch_status: str,
    lane_contract_guard_status: str,
    terminal_lane_status: str,
    multi_cycle_controller_status: str,
    generated_prompt_reentry_readiness_status: str,
    generated_prompt_reentry_routing_status: str,
    rollback_readiness_status: str,
    commit_readiness_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "selected_lane_result_next_prompt_completed",
        "selected_lane_result_fix_prompt_completed",
        "selected_lane_result_rollback_readiness_completed",
        "selected_lane_result_commit_readiness_completed",
        "selected_lane_result_manual_stop",
        "selected_lane_result_failed",
        "selected_lane_result_blocked",
        "selected_lane_result_blocked_non_selected_lane_activity",
        "selected_lane_result_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_result_classes = {
        "next_prompt_generation_completed",
        "fix_prompt_generation_completed",
        "rollback_readiness_completed",
        "commit_readiness_completed",
        "manual_stop",
        "blocked",
        "failed",
        "insufficient_truth",
        "blocked_non_selected_lane_activity",
    }
    allowed_next_actions = {
        "prepare_generated_prompt_reentry",
        "prepare_rollback_execution",
        "prepare_commit_execution",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt202_selected_lane_result_assimilation",
        "metadata_only",
        "controller_feedback_only",
        "no_execution",
        "no_codex_invocation",
        "no_validation_execution",
        "no_rollback_execution",
        "no_git_mutation",
        "no_push",
    ]

    normalized_selected_lane_execution_status = _normalize_text(
        selected_lane_execution_status,
        default="insufficient_truth",
    )
    normalized_selected_lane = _normalize_text(selected_lane, default="")
    normalized_selected_lane_action = _normalize_text(selected_lane_action, default="")
    normalized_execution_block_reason = _normalize_text(execution_block_reason, default="")
    normalized_execution_source = _normalize_text(execution_source, default="")
    normalized_generated_prompt_kind = _normalize_text(generated_prompt_kind, default="none")
    normalized_generated_prompt_path = _normalize_text(generated_prompt_path, default="")
    normalized_execution_result_class = _normalize_text(execution_result_class, default="blocked")
    normalized_assimilation_source = _normalize_text(
        selected_action_result_assimilation_source,
        default="",
    )
    normalized_assimilation_next_stage = _normalize_text(
        selected_action_result_next_stage,
        default="",
    )
    normalized_execution_stop_reason = _normalize_text(execution_stop_reason, default="")
    normalized_execution_next_action = _normalize_text(execution_next_action, default="")
    normalized_guarded_dispatch_status = _normalize_text(
        guarded_dispatch_status, default="insufficient_truth"
    )
    normalized_lane_contract_guard_status = _normalize_text(
        lane_contract_guard_status, default="insufficient_truth"
    )
    normalized_terminal_lane_status = _normalize_text(terminal_lane_status, default="insufficient_truth")
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status, default="insufficient_truth"
    )
    normalized_generated_prompt_reentry_readiness_status = _normalize_text(
        generated_prompt_reentry_readiness_status, default="insufficient_truth"
    )
    normalized_generated_prompt_reentry_routing_status = _normalize_text(
        generated_prompt_reentry_routing_status, default="insufficient_truth"
    )
    normalized_rollback_readiness_status = _normalize_text(
        rollback_readiness_status, default="insufficient_truth"
    )
    normalized_commit_readiness_status = _normalize_text(
        commit_readiness_status, default="insufficient_truth"
    )

    authoritative_result_selected = bool(
        bool(selected_action_result_ready_for_assimilation)
        and normalized_assimilation_source == "prompt201_selected_lane_execution"
        and normalized_assimilation_next_stage == "selected_lane_result_assimilation"
        and bool(normalized_selected_lane)
        and (
            bool(normalized_execution_result_class)
            or bool(normalized_selected_lane_execution_status)
        )
    )
    result_available = bool(
        bool(normalized_selected_lane_execution_status) and normalized_selected_lane_execution_status != "insufficient_truth"
    ) or bool(normalized_execution_result_class)
    non_stop_lane = normalized_selected_lane in {
        "next_prompt_lane",
        "fix_prompt_lane",
        "rollback_readiness_lane",
        "commit_readiness_lane",
    }

    status = "selected_lane_result_blocked_insufficient_truth"
    result_selected = False
    result_class = "insufficient_truth"
    result_block_reason = "blocked_insufficient_selected_lane_result_truth"
    source_execution_status = normalized_selected_lane_execution_status
    source_execution_completed = bool(execution_completed)
    source_execution_failed = bool(execution_failed)
    non_selected_lanes_noop_confirmed = bool(non_selected_lanes_noop)
    out_generated_prompt_kind = "none"
    out_generated_prompt_path = ""
    out_generated_prompt_ready_for_reentry = False
    out_rollback_readiness_ready = False
    out_commit_readiness_ready = False
    controller_feedback_ready = False
    controller_feedback_kind = "none"
    controller_feedback_source = ""
    controller_feedback_payload: dict[str, Any] = {}
    next_controller_input_ready = False
    next_controller_input_kind = "none"
    next_controller_input_source = ""
    next_controller_action_hint = "manual_review_required"
    should_prepare_generated_prompt_reentry = False
    should_prepare_codex_reentry = False
    should_prepare_rollback_execution = False
    should_prepare_commit_execution = False
    should_prepare_next_controller_decision = False
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_execution_stop_reason or "insufficient_selected_lane_result_truth"
    out_next_action = "manual_review_required"

    if not authoritative_result_selected:
        status = "selected_lane_result_blocked_insufficient_truth"
        result_selected = False
        result_class = "insufficient_truth"
        result_block_reason = "blocked_insufficient_selected_lane_result_truth"
    elif non_stop_lane and not bool(non_selected_lanes_noop):
        status = "selected_lane_result_blocked_non_selected_lane_activity"
        result_selected = True
        result_class = "blocked_non_selected_lane_activity"
        result_block_reason = "blocked_non_selected_lane_activity"
        source_execution_completed = bool(execution_completed)
        source_execution_failed = bool(execution_failed)
        non_selected_lanes_noop_confirmed = False
        controller_feedback_ready = True
        controller_feedback_kind = "selected_lane_blocked"
        controller_feedback_source = "prompt201_selected_lane_execution"
        next_controller_input_ready = True
        next_controller_input_kind = "stop_or_manual_review"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_non_selected_lane_activity"
        out_next_action = "manual_review_required"
    elif (
        normalized_selected_lane == "next_prompt_lane"
        and bool(next_prompt_lane_executed)
        and bool(execution_completed)
        and normalized_generated_prompt_kind == "next"
        and bool(generated_prompt_ready_for_reentry)
        and bool(normalized_generated_prompt_path)
    ):
        status = "selected_lane_result_next_prompt_completed"
        result_selected = True
        result_class = "next_prompt_generation_completed"
        result_block_reason = ""
        out_generated_prompt_kind = "next"
        out_generated_prompt_path = normalized_generated_prompt_path
        out_generated_prompt_ready_for_reentry = True
        controller_feedback_ready = True
        controller_feedback_kind = "generated_prompt_ready"
        controller_feedback_source = "prompt201_selected_lane_execution"
        controller_feedback_payload = {
            "feedback": "generated_prompt_ready",
            "prompt_kind": "next",
            "prompt_path": normalized_generated_prompt_path,
            "source": "prompt201_selected_lane_execution",
            "next_action": "prepare_generated_prompt_reentry",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "generated_next_prompt_ready_for_reentry"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "prepare_generated_prompt_reentry"
        should_prepare_generated_prompt_reentry = True
        should_prepare_codex_reentry = False
        should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_generated_prompt_reentry"
    elif (
        normalized_selected_lane == "fix_prompt_lane"
        and bool(fix_prompt_lane_executed)
        and bool(execution_completed)
        and normalized_generated_prompt_kind == "fix"
        and bool(generated_prompt_ready_for_reentry)
        and bool(normalized_generated_prompt_path)
    ):
        status = "selected_lane_result_fix_prompt_completed"
        result_selected = True
        result_class = "fix_prompt_generation_completed"
        result_block_reason = ""
        out_generated_prompt_kind = "fix"
        out_generated_prompt_path = normalized_generated_prompt_path
        out_generated_prompt_ready_for_reentry = True
        controller_feedback_ready = True
        controller_feedback_kind = "generated_prompt_ready"
        controller_feedback_source = "prompt201_selected_lane_execution"
        controller_feedback_payload = {
            "feedback": "generated_prompt_ready",
            "prompt_kind": "fix",
            "prompt_path": normalized_generated_prompt_path,
            "source": "prompt201_selected_lane_execution",
            "next_action": "prepare_generated_prompt_reentry",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "generated_fix_prompt_ready_for_reentry"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "prepare_generated_prompt_reentry"
        should_prepare_generated_prompt_reentry = True
        should_prepare_codex_reentry = False
        should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_generated_prompt_reentry"
    elif (
        normalized_selected_lane == "rollback_readiness_lane"
        and bool(rollback_readiness_lane_executed)
        and bool(execution_completed)
        and bool(rollback_readiness_ready)
    ):
        status = "selected_lane_result_rollback_readiness_completed"
        result_selected = True
        result_class = "rollback_readiness_completed"
        result_block_reason = ""
        out_rollback_readiness_ready = True
        controller_feedback_ready = True
        controller_feedback_kind = "rollback_readiness_ready"
        controller_feedback_source = "prompt201_selected_lane_execution"
        controller_feedback_payload = {
            "feedback": "rollback_readiness_ready",
            "source": "prompt201_selected_lane_execution",
            "next_action": "prepare_rollback_execution",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "rollback_execution_ready"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "prepare_rollback_execution"
        should_prepare_rollback_execution = True
        should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_rollback_execution"
    elif (
        normalized_selected_lane == "commit_readiness_lane"
        and bool(commit_readiness_lane_executed)
        and bool(execution_completed)
        and bool(commit_readiness_ready)
    ):
        status = "selected_lane_result_commit_readiness_completed"
        result_selected = True
        result_class = "commit_readiness_completed"
        result_block_reason = ""
        out_commit_readiness_ready = True
        controller_feedback_ready = True
        controller_feedback_kind = "commit_readiness_ready"
        controller_feedback_source = "prompt201_selected_lane_execution"
        controller_feedback_payload = {
            "feedback": "commit_readiness_ready",
            "source": "prompt201_selected_lane_execution",
            "next_action": "prepare_commit_execution",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "commit_execution_ready"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "prepare_commit_execution"
        should_prepare_commit_execution = True
        should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_commit_execution"
    elif normalized_selected_lane == "manual_stop_lane" or bool(manual_stop_executed):
        status = "selected_lane_result_manual_stop"
        result_selected = True
        result_class = "manual_stop"
        result_block_reason = ""
        controller_feedback_ready = True
        controller_feedback_kind = "manual_stop"
        controller_feedback_source = "prompt201_selected_lane_execution"
        out_stop_reason = normalized_execution_stop_reason or "manual_stop_lane_selected"
        controller_feedback_payload = {
            "feedback": "manual_stop",
            "source": "prompt201_selected_lane_execution",
            "stop_reason": out_stop_reason,
            "next_action": "manual_review_required",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "stop"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "manual_review_required"
        should_prepare_next_controller_decision = False
        out_manual_review_required = True
        out_should_stop = True
        out_next_action = "manual_review_required"
    elif bool(execution_failed) or normalized_selected_lane_execution_status == "selected_lane_execution_failed":
        status = "selected_lane_result_failed"
        result_selected = True
        result_class = "failed"
        result_block_reason = normalized_execution_block_reason or "selected_lane_execution_failed"
        controller_feedback_ready = True
        controller_feedback_kind = "selected_lane_failed"
        controller_feedback_source = "prompt201_selected_lane_execution"
        out_stop_reason = normalized_execution_block_reason or "selected_lane_execution_failed"
        controller_feedback_payload = {
            "feedback": "selected_lane_failed",
            "source": "prompt201_selected_lane_execution",
            "stop_reason": out_stop_reason,
            "next_action": "manual_review_required",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "stop_or_manual_review"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_next_action = "manual_review_required"
    elif "blocked" in normalized_selected_lane_execution_status:
        status = "selected_lane_result_blocked"
        result_selected = True
        result_class = "blocked"
        result_block_reason = normalized_execution_block_reason or "selected_lane_execution_blocked"
        controller_feedback_ready = True
        controller_feedback_kind = "selected_lane_blocked"
        controller_feedback_source = "prompt201_selected_lane_execution"
        out_stop_reason = normalized_execution_block_reason or "selected_lane_execution_blocked"
        controller_feedback_payload = {
            "feedback": "selected_lane_blocked",
            "source": "prompt201_selected_lane_execution",
            "stop_reason": out_stop_reason,
            "next_action": "manual_review_required",
        }
        next_controller_input_ready = True
        next_controller_input_kind = "stop_or_manual_review"
        next_controller_input_source = "prompt202_selected_lane_result_assimilation"
        next_controller_action_hint = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_next_action = "manual_review_required"
    else:
        status = "selected_lane_result_blocked_insufficient_truth"
        result_selected = True
        result_class = "insufficient_truth"
        result_block_reason = "blocked_insufficient_selected_lane_result_truth"
        controller_feedback_ready = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_selected_lane_result_truth"
        out_next_action = "manual_review_required"

    if result_selected and not controller_feedback_source:
        controller_feedback_source = "prompt201_selected_lane_execution"
    if result_selected and not controller_feedback_payload:
        controller_feedback_payload = {
            "feedback": controller_feedback_kind or "selected_lane_blocked",
            "source": "prompt201_selected_lane_execution",
            "stop_reason": out_stop_reason,
            "next_action": "manual_review_required",
        }

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if result_class not in allowed_result_classes:
        result_class = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        status = "selected_lane_result_blocked_insufficient_truth"
        result_selected = False
        result_available = False
        result_class = "insufficient_truth"
        result_block_reason = "blocked_insufficient_selected_lane_result_truth"
        source_execution_completed = False
        source_execution_failed = False
        non_selected_lanes_noop_confirmed = False
        out_generated_prompt_kind = "none"
        out_generated_prompt_path = ""
        out_generated_prompt_ready_for_reentry = False
        out_rollback_readiness_ready = False
        out_commit_readiness_ready = False
        controller_feedback_ready = False
        controller_feedback_kind = "none"
        controller_feedback_source = ""
        controller_feedback_payload = {}
        next_controller_input_ready = False
        next_controller_input_kind = "none"
        next_controller_input_source = ""
        next_controller_action_hint = "manual_review_required"
        should_prepare_generated_prompt_reentry = False
        should_prepare_codex_reentry = False
        should_prepare_rollback_execution = False
        should_prepare_commit_execution = False
        should_prepare_next_controller_decision = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_selected_lane_result_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_selected_lane_result_assimilation_status": status,
        "project_browser_autonomous_selected_lane_result_assimilation_result_selected": bool(
            result_selected
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_result_available": bool(
            result_available
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_result_class": result_class,
        "project_browser_autonomous_selected_lane_result_assimilation_result_block_reason": (
            result_block_reason
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_source_selected_lane": (
            normalized_selected_lane
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_source_selected_lane_action": (
            normalized_selected_lane_action
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_source_execution_status": (
            source_execution_status
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_source_execution_completed": bool(
            source_execution_completed
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_source_execution_failed": bool(
            source_execution_failed
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_non_selected_lanes_noop_confirmed": bool(
            non_selected_lanes_noop_confirmed
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_generated_prompt_kind": (
            out_generated_prompt_kind
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_generated_prompt_path": (
            out_generated_prompt_path
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_generated_prompt_ready_for_reentry": bool(
            out_generated_prompt_ready_for_reentry
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_rollback_readiness_ready": bool(
            out_rollback_readiness_ready
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_commit_readiness_ready": bool(
            out_commit_readiness_ready
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_controller_feedback_ready": bool(
            controller_feedback_ready
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_controller_feedback_kind": (
            controller_feedback_kind
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_controller_feedback_source": (
            controller_feedback_source
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_controller_feedback_payload": (
            controller_feedback_payload if isinstance(controller_feedback_payload, Mapping) else {}
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_next_controller_input_ready": bool(
            next_controller_input_ready
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_next_controller_input_kind": (
            next_controller_input_kind
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_next_controller_input_source": (
            next_controller_input_source
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_next_controller_action_hint": (
            next_controller_action_hint
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_prepare_generated_prompt_reentry": bool(
            should_prepare_generated_prompt_reentry
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_prepare_codex_reentry": bool(
            should_prepare_codex_reentry
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_prepare_rollback_execution": bool(
            should_prepare_rollback_execution
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_prepare_commit_execution": bool(
            should_prepare_commit_execution
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_prepare_next_controller_decision": bool(
            should_prepare_next_controller_decision
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_push": bool(
            out_should_push
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_should_stop": bool(
            out_should_stop
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_stop_reason": out_stop_reason,
        "project_browser_autonomous_selected_lane_result_assimilation_next_action": out_next_action,
        "project_browser_autonomous_selected_lane_result_assimilation_runtime_posture": (
            runtime_posture
        ),
        "project_browser_autonomous_selected_lane_result_assimilation_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_selected_lane_execution_status,
                    normalized_selected_lane,
                    normalized_selected_lane_action,
                    normalized_execution_block_reason,
                    normalized_execution_source,
                    normalized_generated_prompt_kind,
                    normalized_generated_prompt_path,
                    normalized_execution_result_class,
                    normalized_assimilation_source,
                    normalized_assimilation_next_stage,
                    normalized_execution_stop_reason,
                    normalized_execution_next_action,
                    normalized_guarded_dispatch_status,
                    normalized_lane_contract_guard_status,
                    normalized_terminal_lane_status,
                    normalized_multi_cycle_controller_status,
                    normalized_generated_prompt_reentry_readiness_status,
                    normalized_generated_prompt_reentry_routing_status,
                    normalized_rollback_readiness_status,
                    normalized_commit_readiness_status,
                    "authoritative_result_not_selected"
                    if not authoritative_result_selected
                    else "",
                    "selected_action_result_not_ready"
                    if not bool(selected_action_result_ready_for_assimilation)
                    else "",
                    "non_selected_lanes_noop_false"
                    if non_stop_lane and not bool(non_selected_lanes_noop)
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_bounded_local_loop_contract_state(
    *,
    selected_lane_result_status: str,
    result_selected: bool,
    result_available: bool,
    result_class: str,
    result_block_reason: str,
    source_selected_lane: str,
    source_selected_lane_action: str,
    source_execution_status: str,
    source_execution_completed: bool,
    source_execution_failed: bool,
    non_selected_lanes_noop_confirmed: bool,
    generated_prompt_kind: str,
    generated_prompt_path: str,
    generated_prompt_ready_for_reentry: bool,
    rollback_readiness_ready: bool,
    commit_readiness_ready: bool,
    controller_feedback_ready: bool,
    controller_feedback_kind: str,
    controller_feedback_source: str,
    controller_feedback_payload: Any,
    next_controller_input_ready: bool,
    next_controller_input_kind: str,
    next_controller_input_source: str,
    next_controller_action_hint: str,
    should_prepare_generated_prompt_reentry: bool,
    should_prepare_codex_reentry: bool,
    should_prepare_rollback_execution: bool,
    should_prepare_commit_execution: bool,
    should_prepare_next_controller_decision: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_execute_commit: bool,
    should_push: bool,
    manual_review_required: bool,
    should_stop: bool,
    stop_reason: str,
    next_action: str,
    remaining_cycles: int,
    remaining_codex_invocations: int,
    remaining_rollback_attempts: int,
    remaining_commits: int,
    multi_cycle_controller_status: str,
    selected_lane_execution_status: str,
    guarded_lane_dispatch_status: str,
    rollback_execution_status: str,
    commit_tag_execution_status: str,
    commit_tag_result_assimilation_status: str,
    post_rollback_fix_reentry_result_assimilation_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "bounded_local_loop_contract_generated_prompt_reentry_ready",
        "bounded_local_loop_contract_rollback_execution_ready",
        "bounded_local_loop_contract_commit_execution_ready",
        "bounded_local_loop_contract_manual_stop",
        "bounded_local_loop_contract_blocked",
        "bounded_local_loop_contract_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_generated_prompt_reentry",
        "prepare_rollback_execution",
        "prepare_commit_execution",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt203_bounded_local_loop_contract",
        "metadata_only",
        "controller_feedback_reconciliation",
        "no_execution",
        "no_codex_invocation",
        "no_validation_execution",
        "no_rollback_execution",
        "no_commit_execution",
        "no_push",
    ]

    normalized_selected_lane_result_status = _normalize_text(
        selected_lane_result_status, default="insufficient_truth"
    )
    normalized_result_class = _normalize_text(result_class, default="insufficient_truth")
    normalized_result_block_reason = _normalize_text(result_block_reason, default="")
    normalized_source_selected_lane = _normalize_text(source_selected_lane, default="")
    normalized_source_selected_lane_action = _normalize_text(
        source_selected_lane_action, default=""
    )
    normalized_source_execution_status = _normalize_text(
        source_execution_status, default="insufficient_truth"
    )
    normalized_generated_prompt_kind = _normalize_text(generated_prompt_kind, default="none")
    normalized_generated_prompt_path = _normalize_text(generated_prompt_path, default="")
    normalized_controller_feedback_kind = _normalize_text(controller_feedback_kind, default="none")
    normalized_controller_feedback_source = _normalize_text(
        controller_feedback_source, default=""
    )
    normalized_next_controller_input_kind = _normalize_text(
        next_controller_input_kind, default="none"
    )
    normalized_next_controller_input_source = _normalize_text(
        next_controller_input_source, default=""
    )
    normalized_next_controller_action_hint = _normalize_text(
        next_controller_action_hint, default="manual_review_required"
    )
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_next_action = _normalize_text(next_action, default="manual_review_required")
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status, default="insufficient_truth"
    )
    normalized_selected_lane_execution_status = _normalize_text(
        selected_lane_execution_status, default="insufficient_truth"
    )
    normalized_guarded_lane_dispatch_status = _normalize_text(
        guarded_lane_dispatch_status, default="insufficient_truth"
    )
    normalized_rollback_execution_status = _normalize_text(
        rollback_execution_status, default="insufficient_truth"
    )
    normalized_commit_tag_execution_status = _normalize_text(
        commit_tag_execution_status, default="insufficient_truth"
    )
    normalized_commit_tag_result_assimilation_status = _normalize_text(
        commit_tag_result_assimilation_status, default="insufficient_truth"
    )
    normalized_post_rollback_fix_reentry_result_assimilation_status = _normalize_text(
        post_rollback_fix_reentry_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_controller_feedback_payload = (
        dict(controller_feedback_payload) if isinstance(controller_feedback_payload, Mapping) else {}
    )

    cycle_budget_remaining = _as_non_negative_int(remaining_cycles, default=0)
    codex_budget_remaining = _as_non_negative_int(remaining_codex_invocations, default=0)
    rollback_budget_remaining = _as_non_negative_int(remaining_rollback_attempts, default=0)
    commit_budget_remaining = _as_non_negative_int(remaining_commits, default=0)
    budget_contract_checked = bool(
        normalized_multi_cycle_controller_status != "insufficient_truth"
    )

    authoritative_selected = bool(
        (
            bool(controller_feedback_ready)
            or normalized_selected_lane_result_status
            in {
                "selected_lane_result_manual_stop",
                "selected_lane_result_failed",
                "selected_lane_result_blocked",
                "selected_lane_result_blocked_non_selected_lane_activity",
                "selected_lane_result_blocked_insufficient_truth",
            }
        )
        and (
            not bool(controller_feedback_ready)
            or normalized_controller_feedback_source == "prompt201_selected_lane_execution"
        )
        and (
            normalized_result_class
            in {
                "manual_stop",
                "failed",
                "blocked",
                "blocked_non_selected_lane_activity",
                "insufficient_truth",
            }
            or bool(next_controller_input_ready)
        )
        and bool(normalized_result_class)
        and bool(normalized_source_selected_lane)
    )

    contract_available = False
    contract_allowed = False
    contract_block_reason = ""
    contract_source = "prompt202_selected_lane_result_assimilation"
    contract_kind = "none"
    contract_action = "manual_review_required"
    contract_payload: dict[str, Any] = {}
    feedback_selected = bool(authoritative_selected)
    feedback_kind = normalized_controller_feedback_kind
    feedback_payload_valid = bool(
        bool(normalized_controller_feedback_payload)
        and _normalize_text(normalized_controller_feedback_payload.get("source"), default="")
        == "prompt201_selected_lane_execution"
    )
    next_step_kind = "none"
    next_step_action = "manual_review_required"
    next_step_payload: dict[str, Any] = {}
    generated_prompt_reentry_contract_ready = False
    codex_reentry_contract_ready = False
    rollback_execution_contract_ready = False
    commit_execution_contract_ready = False
    next_controller_decision_contract_ready = False
    manual_stop_contract_ready = False
    unsafe_state_detected = False
    dirty_state_requires_stop = False
    conflict_requires_stop = False
    out_should_prepare_generated_prompt_reentry = False
    out_should_prepare_codex_reentry = False
    out_should_prepare_rollback_execution = False
    out_should_prepare_commit_execution = False
    out_should_prepare_next_controller_decision = False
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_stop_reason or "insufficient_bounded_local_loop_contract_truth"
    out_next_action = "manual_review_required"
    status = "bounded_local_loop_contract_blocked_insufficient_truth"

    expected_generated_paths = {
        "fix": "/tmp/codex-local-runner-decision/generated_fix_prompt.txt",
        "next": "/tmp/codex-local-runner-decision/generated_next_prompt.txt",
    }
    generated_path_truth_ok = bool(
        normalized_generated_prompt_kind in {"fix", "next"}
        and bool(normalized_generated_prompt_path)
        and normalized_generated_prompt_path
        == expected_generated_paths.get(normalized_generated_prompt_kind, "")
    )

    if (
        normalized_commit_tag_result_assimilation_status
        == "commit_tag_result_assimilation_completed_with_unexpected_dirty"
    ):
        dirty_state_requires_stop = True
    if (
        normalized_guarded_lane_dispatch_status
        == "guarded_lane_dispatch_blocked_refresh_conflict"
        or normalized_selected_lane_execution_status
        == "selected_lane_execution_blocked_multiple_lanes"
        or normalized_result_class == "blocked_non_selected_lane_activity"
    ):
        conflict_requires_stop = True
    if (
        normalized_result_class in {"failed", "blocked", "blocked_non_selected_lane_activity"}
        or normalized_selected_lane_result_status
        in {
            "selected_lane_result_failed",
            "selected_lane_result_blocked",
            "selected_lane_result_blocked_non_selected_lane_activity",
        }
    ):
        unsafe_state_detected = True

    safety_stop_required = bool(
        bool(should_invoke_codex)
        or bool(should_execute_rollback)
        or bool(should_execute_commit)
        or bool(should_push)
        or bool(manual_review_required)
        or bool(should_stop)
        or (bool(normalized_source_selected_lane) and not bool(non_selected_lanes_noop_confirmed) and normalized_result_class in {"next_prompt_generation_completed", "fix_prompt_generation_completed", "rollback_readiness_completed", "commit_readiness_completed"})
        or bool(conflict_requires_stop)
        or bool(unsafe_state_detected)
        or bool(dirty_state_requires_stop)
    )

    unknown_budget_stop = bool(
        not budget_contract_checked
        and normalized_result_class != "manual_stop"
    )

    if not authoritative_selected:
        status = "bounded_local_loop_contract_blocked_insufficient_truth"
        contract_available = False
        contract_allowed = False
        contract_block_reason = "blocked_insufficient_bounded_local_loop_contract_truth"
        out_stop_reason = "insufficient_bounded_local_loop_contract_truth"
    elif (
        normalized_result_class == "manual_stop"
        or bool(manual_review_required)
        or bool(should_stop)
    ):
        status = "bounded_local_loop_contract_manual_stop"
        contract_available = True
        contract_allowed = False
        contract_block_reason = ""
        contract_kind = "manual_stop"
        contract_action = "manual_review_required"
        contract_payload = {
            "contract": "manual_stop",
            "source": "prompt202_selected_lane_result_assimilation",
            "stop_reason": normalized_stop_reason or "manual_stop",
            "next_action": "manual_review_required",
        }
        manual_stop_contract_ready = True
        next_step_kind = "manual_stop"
        next_step_action = "manual_review_required"
        next_step_payload = dict(contract_payload)
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_stop_reason or "manual_stop"
        out_next_action = "manual_review_required"
    elif unknown_budget_stop:
        status = "bounded_local_loop_contract_blocked"
        contract_available = True
        contract_allowed = False
        contract_block_reason = "blocked_insufficient_bounded_local_loop_contract_truth"
        contract_kind = "blocked"
        contract_action = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_bounded_local_loop_contract_truth"
        out_next_action = "manual_review_required"
    elif safety_stop_required:
        status = "bounded_local_loop_contract_blocked"
        contract_available = True
        contract_allowed = False
        contract_block_reason = normalized_result_block_reason or "selected_lane_result_not_safe"
        contract_kind = "blocked"
        contract_action = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = (
            normalized_stop_reason
            or normalized_result_block_reason
            or "selected_lane_result_not_safe"
        )
        out_next_action = "manual_review_required"
    elif (
        normalized_result_class in {"next_prompt_generation_completed", "fix_prompt_generation_completed"}
        and bool(generated_prompt_ready_for_reentry)
        and generated_path_truth_ok
        and not bool(manual_review_required)
        and not bool(should_stop)
    ):
        status = "bounded_local_loop_contract_generated_prompt_reentry_ready"
        contract_available = True
        contract_allowed = True
        contract_block_reason = ""
        contract_kind = "generated_prompt_reentry"
        contract_action = "prepare_generated_prompt_reentry"
        contract_payload = {
            "contract": "generated_prompt_reentry",
            "prompt_kind": normalized_generated_prompt_kind,
            "prompt_path": normalized_generated_prompt_path,
            "source": "prompt202_selected_lane_result_assimilation",
            "next_action": "prepare_generated_prompt_reentry",
        }
        generated_prompt_reentry_contract_ready = True
        next_step_kind = "generated_prompt_reentry"
        next_step_action = "prepare_generated_prompt_reentry"
        next_step_payload = dict(contract_payload)
        out_should_prepare_generated_prompt_reentry = True
        out_should_prepare_codex_reentry = False
        out_should_prepare_rollback_execution = False
        out_should_prepare_commit_execution = False
        out_should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_generated_prompt_reentry"
    elif (
        normalized_result_class == "rollback_readiness_completed"
        and bool(rollback_readiness_ready)
        and rollback_budget_remaining > 0
        and not bool(manual_review_required)
        and not bool(should_stop)
    ):
        status = "bounded_local_loop_contract_rollback_execution_ready"
        contract_available = True
        contract_allowed = True
        contract_block_reason = ""
        contract_kind = "rollback_execution"
        contract_action = "prepare_rollback_execution"
        contract_payload = {
            "contract": "rollback_execution",
            "source": "prompt202_selected_lane_result_assimilation",
            "next_action": "prepare_rollback_execution",
        }
        rollback_execution_contract_ready = True
        next_step_kind = "rollback_execution"
        next_step_action = "prepare_rollback_execution"
        next_step_payload = dict(contract_payload)
        out_should_prepare_generated_prompt_reentry = False
        out_should_prepare_rollback_execution = True
        out_should_prepare_commit_execution = False
        out_should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_rollback_execution"
    elif (
        normalized_result_class == "commit_readiness_completed"
        and bool(commit_readiness_ready)
        and commit_budget_remaining > 0
        and not bool(manual_review_required)
        and not bool(should_stop)
    ):
        status = "bounded_local_loop_contract_commit_execution_ready"
        contract_available = True
        contract_allowed = True
        contract_block_reason = ""
        contract_kind = "commit_execution"
        contract_action = "prepare_commit_execution"
        contract_payload = {
            "contract": "commit_execution",
            "source": "prompt202_selected_lane_result_assimilation",
            "next_action": "prepare_commit_execution",
        }
        commit_execution_contract_ready = True
        next_step_kind = "commit_execution"
        next_step_action = "prepare_commit_execution"
        next_step_payload = dict(contract_payload)
        out_should_prepare_generated_prompt_reentry = False
        out_should_prepare_rollback_execution = False
        out_should_prepare_commit_execution = True
        out_should_prepare_next_controller_decision = False
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        out_next_action = "prepare_commit_execution"
    elif normalized_result_class in {
        "failed",
        "blocked",
        "blocked_non_selected_lane_activity",
        "insufficient_truth",
    }:
        status = "bounded_local_loop_contract_blocked"
        contract_available = True
        contract_allowed = False
        contract_block_reason = normalized_result_block_reason or "selected_lane_result_not_safe"
        contract_kind = "blocked"
        contract_action = "manual_review_required"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = (
            normalized_stop_reason
            or normalized_result_block_reason
            or "selected_lane_result_not_safe"
        )
        out_next_action = "manual_review_required"
    else:
        status = "bounded_local_loop_contract_blocked_insufficient_truth"
        contract_available = False
        contract_allowed = False
        contract_block_reason = "blocked_insufficient_bounded_local_loop_contract_truth"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_bounded_local_loop_contract_truth"
        out_next_action = "manual_review_required"

    if (
        status == "bounded_local_loop_contract_generated_prompt_reentry_ready"
        and not generated_path_truth_ok
    ):
        status = "bounded_local_loop_contract_blocked"
        contract_available = True
        contract_allowed = False
        contract_block_reason = "blocked_generated_prompt_path_truth_insufficient"
        contract_kind = "blocked"
        contract_action = "manual_review_required"
        contract_payload = {}
        generated_prompt_reentry_contract_ready = False
        next_step_kind = "blocked"
        next_step_action = "manual_review_required"
        next_step_payload = {}
        out_should_prepare_generated_prompt_reentry = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_generated_prompt_path_truth_insufficient"
        out_next_action = "manual_review_required"

    if contract_allowed:
        feedback_payload_valid = bool(feedback_payload_valid)
    if not contract_payload:
        contract_payload = {
            "contract": contract_kind or "blocked",
            "source": "prompt202_selected_lane_result_assimilation",
            "next_action": out_next_action,
        }
    if not next_step_payload:
        next_step_payload = dict(contract_payload)

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        status = "bounded_local_loop_contract_blocked_insufficient_truth"
        contract_available = False
        contract_allowed = False
        contract_block_reason = "blocked_insufficient_bounded_local_loop_contract_truth"
        contract_kind = "blocked"
        contract_action = "manual_review_required"
        contract_payload = {
            "contract": "blocked",
            "source": "prompt202_selected_lane_result_assimilation",
            "next_action": "manual_review_required",
        }
        feedback_selected = False
        feedback_kind = "none"
        feedback_payload_valid = False
        next_step_kind = "blocked"
        next_step_action = "manual_review_required"
        next_step_payload = dict(contract_payload)
        generated_prompt_reentry_contract_ready = False
        codex_reentry_contract_ready = False
        rollback_execution_contract_ready = False
        commit_execution_contract_ready = False
        next_controller_decision_contract_ready = False
        manual_stop_contract_ready = False
        out_should_prepare_generated_prompt_reentry = False
        out_should_prepare_codex_reentry = False
        out_should_prepare_rollback_execution = False
        out_should_prepare_commit_execution = False
        out_should_prepare_next_controller_decision = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_bounded_local_loop_contract_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_bounded_local_loop_contract_status": status,
        "project_browser_autonomous_bounded_local_loop_contract_contract_available": bool(
            contract_available
        ),
        "project_browser_autonomous_bounded_local_loop_contract_contract_allowed": bool(
            contract_allowed
        ),
        "project_browser_autonomous_bounded_local_loop_contract_contract_block_reason": (
            contract_block_reason
        ),
        "project_browser_autonomous_bounded_local_loop_contract_contract_source": contract_source,
        "project_browser_autonomous_bounded_local_loop_contract_contract_kind": contract_kind,
        "project_browser_autonomous_bounded_local_loop_contract_contract_action": contract_action,
        "project_browser_autonomous_bounded_local_loop_contract_contract_payload": (
            contract_payload
        ),
        "project_browser_autonomous_bounded_local_loop_contract_feedback_selected": bool(
            feedback_selected
        ),
        "project_browser_autonomous_bounded_local_loop_contract_feedback_kind": feedback_kind,
        "project_browser_autonomous_bounded_local_loop_contract_feedback_payload_valid": bool(
            feedback_payload_valid
        ),
        "project_browser_autonomous_bounded_local_loop_contract_next_step_kind": next_step_kind,
        "project_browser_autonomous_bounded_local_loop_contract_next_step_action": (
            next_step_action
        ),
        "project_browser_autonomous_bounded_local_loop_contract_next_step_payload": (
            next_step_payload
        ),
        "project_browser_autonomous_bounded_local_loop_contract_generated_prompt_reentry_contract_ready": bool(
            generated_prompt_reentry_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_codex_reentry_contract_ready": bool(
            codex_reentry_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_rollback_execution_contract_ready": bool(
            rollback_execution_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_commit_execution_contract_ready": bool(
            commit_execution_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_next_controller_decision_contract_ready": bool(
            next_controller_decision_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_manual_stop_contract_ready": bool(
            manual_stop_contract_ready
        ),
        "project_browser_autonomous_bounded_local_loop_contract_budget_contract_checked": bool(
            budget_contract_checked
        ),
        "project_browser_autonomous_bounded_local_loop_contract_cycle_budget_remaining": int(
            cycle_budget_remaining
        ),
        "project_browser_autonomous_bounded_local_loop_contract_codex_budget_remaining": int(
            codex_budget_remaining
        ),
        "project_browser_autonomous_bounded_local_loop_contract_rollback_budget_remaining": int(
            rollback_budget_remaining
        ),
        "project_browser_autonomous_bounded_local_loop_contract_commit_budget_remaining": int(
            commit_budget_remaining
        ),
        "project_browser_autonomous_bounded_local_loop_contract_unsafe_state_detected": bool(
            unsafe_state_detected
        ),
        "project_browser_autonomous_bounded_local_loop_contract_dirty_state_requires_stop": bool(
            dirty_state_requires_stop
        ),
        "project_browser_autonomous_bounded_local_loop_contract_conflict_requires_stop": bool(
            conflict_requires_stop
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_prepare_generated_prompt_reentry": bool(
            out_should_prepare_generated_prompt_reentry
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_prepare_codex_reentry": bool(
            out_should_prepare_codex_reentry
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_prepare_rollback_execution": bool(
            out_should_prepare_rollback_execution
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_prepare_commit_execution": bool(
            out_should_prepare_commit_execution
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_prepare_next_controller_decision": bool(
            out_should_prepare_next_controller_decision
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_push": bool(
            out_should_push
        ),
        "project_browser_autonomous_bounded_local_loop_contract_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_bounded_local_loop_contract_should_stop": bool(
            out_should_stop
        ),
        "project_browser_autonomous_bounded_local_loop_contract_stop_reason": out_stop_reason,
        "project_browser_autonomous_bounded_local_loop_contract_next_action": out_next_action,
        "project_browser_autonomous_bounded_local_loop_contract_runtime_posture": runtime_posture,
        "project_browser_autonomous_bounded_local_loop_contract_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_selected_lane_result_status,
                    normalized_result_class,
                    normalized_result_block_reason,
                    normalized_source_selected_lane,
                    normalized_source_selected_lane_action,
                    normalized_source_execution_status,
                    normalized_generated_prompt_kind,
                    normalized_generated_prompt_path,
                    normalized_controller_feedback_kind,
                    normalized_controller_feedback_source,
                    normalized_next_controller_input_kind,
                    normalized_next_controller_input_source,
                    normalized_next_controller_action_hint,
                    normalized_stop_reason,
                    normalized_next_action,
                    normalized_multi_cycle_controller_status,
                    normalized_selected_lane_execution_status,
                    normalized_guarded_lane_dispatch_status,
                    normalized_rollback_execution_status,
                    normalized_commit_tag_execution_status,
                    normalized_commit_tag_result_assimilation_status,
                    normalized_post_rollback_fix_reentry_result_assimilation_status,
                    "authoritative_selected_false" if not authoritative_selected else "",
                    "budget_contract_not_checked" if not budget_contract_checked else "",
                    "generated_prompt_path_truth_insufficient"
                    if bool(
                        normalized_result_class
                        in {"next_prompt_generation_completed", "fix_prompt_generation_completed"}
                    )
                    and not generated_path_truth_ok
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_next_step_launch_contract_state(
    *,
    bounded_local_loop_contract_status: str,
    contract_available: bool,
    contract_allowed: bool,
    contract_block_reason: str,
    contract_source: str,
    contract_kind: str,
    contract_action: str,
    contract_payload: Any,
    feedback_selected: bool,
    feedback_kind: str,
    feedback_payload_valid: bool,
    next_step_kind: str,
    next_step_action: str,
    next_step_payload: Any,
    generated_prompt_reentry_contract_ready: bool,
    codex_reentry_contract_ready: bool,
    rollback_execution_contract_ready: bool,
    commit_execution_contract_ready: bool,
    next_controller_decision_contract_ready: bool,
    manual_stop_contract_ready: bool,
    budget_contract_checked: bool,
    cycle_budget_remaining: int,
    codex_budget_remaining: int,
    rollback_budget_remaining: int,
    commit_budget_remaining: int,
    unsafe_state_detected: bool,
    dirty_state_requires_stop: bool,
    conflict_requires_stop: bool,
    should_prepare_generated_prompt_reentry: bool,
    should_prepare_codex_reentry: bool,
    should_prepare_rollback_execution: bool,
    should_prepare_commit_execution: bool,
    should_prepare_next_controller_decision: bool,
    should_invoke_codex: bool,
    should_execute_rollback: bool,
    should_execute_commit: bool,
    should_push: bool,
    manual_review_required: bool,
    should_stop: bool,
    stop_reason: str,
    next_action: str,
    selected_lane_result_assimilation_status: str,
    selected_lane_execution_status: str,
    multi_cycle_controller_status: str,
    generated_prompt_reentry_readiness_status: str,
    generated_prompt_reentry_routing_status: str,
    codex_reentry_invocation_status: str,
    rollback_readiness_status: str,
    rollback_execution_status: str,
    commit_tag_readiness_status: str,
    commit_tag_execution_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "next_step_launch_contract_generated_prompt_reentry_ready",
        "next_step_launch_contract_rollback_execution_ready",
        "next_step_launch_contract_commit_execution_ready",
        "next_step_launch_contract_manual_stop",
        "next_step_launch_contract_blocked_conflict",
        "next_step_launch_contract_blocked_insufficient_truth",
        "next_step_launch_contract_blocked_unsafe",
        "next_step_launch_contract_blocked_budget",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "launch_generated_prompt_reentry",
        "launch_rollback_execution",
        "launch_commit_execution",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt204_next_step_launch_contract",
        "metadata_only",
        "single_bounded_launch_contract",
        "no_execution",
        "no_codex_invocation",
        "no_validation_execution",
        "no_rollback_execution",
        "no_commit_execution",
        "no_push",
    ]

    normalized_loop_status = _normalize_text(
        bounded_local_loop_contract_status, default="insufficient_truth"
    )
    normalized_contract_block_reason = _normalize_text(contract_block_reason, default="")
    normalized_contract_source = _normalize_text(contract_source, default="")
    normalized_contract_kind = _normalize_text(contract_kind, default="")
    normalized_contract_action = _normalize_text(contract_action, default="")
    normalized_feedback_kind = _normalize_text(feedback_kind, default="none")
    normalized_next_step_kind = _normalize_text(next_step_kind, default="none")
    normalized_next_step_action = _normalize_text(next_step_action, default="manual_review_required")
    normalized_stop_reason = _normalize_text(stop_reason, default="")
    normalized_next_action = _normalize_text(next_action, default="manual_review_required")
    normalized_selected_lane_result_assimilation_status = _normalize_text(
        selected_lane_result_assimilation_status, default="insufficient_truth"
    )
    normalized_selected_lane_execution_status = _normalize_text(
        selected_lane_execution_status, default="insufficient_truth"
    )
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status, default="insufficient_truth"
    )
    normalized_generated_prompt_reentry_readiness_status = _normalize_text(
        generated_prompt_reentry_readiness_status, default="insufficient_truth"
    )
    normalized_generated_prompt_reentry_routing_status = _normalize_text(
        generated_prompt_reentry_routing_status, default="insufficient_truth"
    )
    normalized_codex_reentry_invocation_status = _normalize_text(
        codex_reentry_invocation_status, default="insufficient_truth"
    )
    normalized_rollback_readiness_status = _normalize_text(
        rollback_readiness_status, default="insufficient_truth"
    )
    normalized_rollback_execution_status = _normalize_text(
        rollback_execution_status, default="insufficient_truth"
    )
    normalized_commit_tag_readiness_status = _normalize_text(
        commit_tag_readiness_status, default="insufficient_truth"
    )
    normalized_commit_tag_execution_status = _normalize_text(
        commit_tag_execution_status, default="insufficient_truth"
    )

    normalized_contract_payload = (
        dict(contract_payload) if isinstance(contract_payload, Mapping) else {}
    )
    normalized_next_step_payload = (
        dict(next_step_payload) if isinstance(next_step_payload, Mapping) else {}
    )

    authoritative_source_selected = bool(
        (
            bool(contract_available)
            or normalized_loop_status
            in {
                "bounded_local_loop_contract_manual_stop",
                "bounded_local_loop_contract_blocked",
                "bounded_local_loop_contract_blocked_insufficient_truth",
            }
        )
        and bool(normalized_contract_kind)
        and bool(normalized_contract_action)
        and bool(normalized_loop_status)
        and (
            not bool(contract_allowed)
            or normalized_contract_kind == "manual_stop"
            or bool(normalized_contract_payload)
        )
    )

    codex_budget_remaining_normalized = _as_non_negative_int(codex_budget_remaining, default=0)
    rollback_budget_remaining_normalized = _as_non_negative_int(
        rollback_budget_remaining, default=0
    )
    commit_budget_remaining_normalized = _as_non_negative_int(commit_budget_remaining, default=0)
    cycle_budget_remaining_normalized = _as_non_negative_int(cycle_budget_remaining, default=0)
    launch_budget_checked = bool(budget_contract_checked)

    generated_payload_kind = _normalize_text(normalized_contract_payload.get("prompt_kind"), default="")
    generated_payload_path = _normalize_text(normalized_contract_payload.get("prompt_path"), default="")
    generated_prompt_reentry_launch_candidate = bool(
        bool(contract_allowed)
        and normalized_contract_kind == "generated_prompt_reentry"
        and bool(generated_prompt_reentry_contract_ready)
        and bool(should_prepare_generated_prompt_reentry)
        and codex_budget_remaining_normalized > 0
        and not bool(manual_review_required)
        and not bool(should_stop)
    )
    rollback_execution_launch_candidate = bool(
        bool(contract_allowed)
        and normalized_contract_kind == "rollback_execution"
        and bool(rollback_execution_contract_ready)
        and bool(should_prepare_rollback_execution)
        and rollback_budget_remaining_normalized > 0
        and not bool(manual_review_required)
        and not bool(should_stop)
    )
    commit_execution_launch_candidate = bool(
        bool(contract_allowed)
        and normalized_contract_kind == "commit_execution"
        and bool(commit_execution_contract_ready)
        and bool(should_prepare_commit_execution)
        and commit_budget_remaining_normalized > 0
        and not bool(manual_review_required)
        and not bool(should_stop)
    )
    manual_stop_launch_candidate = bool(
        normalized_contract_kind == "manual_stop"
        or bool(manual_stop_contract_ready)
        or bool(manual_review_required)
        or bool(should_stop)
        or normalized_loop_status
        in {
            "bounded_local_loop_contract_blocked",
            "bounded_local_loop_contract_blocked_insufficient_truth",
        }
    )

    non_stop_candidates: list[str] = []
    if generated_prompt_reentry_launch_candidate:
        non_stop_candidates.append("generated_prompt_reentry_launch")
    if rollback_execution_launch_candidate:
        non_stop_candidates.append("rollback_execution_launch")
    if commit_execution_launch_candidate:
        non_stop_candidates.append("commit_execution_launch")
    non_stop_candidates = sorted(non_stop_candidates)

    launch_contract_available = False
    launch_contract_allowed = False
    launch_contract_block_reason = ""
    launch_contract_source = "prompt203_bounded_local_loop_contract"
    launch_contract_kind = "manual_stop"
    launch_contract_action = "manual_review_required"
    launch_contract_payload: dict[str, Any] = {}
    launch_contract_ready_for_executor = False
    selected_launch_kind = "manual_stop"
    selected_launch_action = "manual_review_required"
    selected_launch_payload: dict[str, Any] = {}
    exactly_one_launch_contract = False
    launch_conflict_detected = False
    conflicting_launch_contracts: list[str] = []
    generated_prompt_reentry_launch_ready = False
    rollback_execution_launch_ready = False
    commit_execution_launch_ready = False
    manual_stop_launch_ready = False
    launch_safety_checked = bool(authoritative_source_selected)
    launch_requires_existing_executor = False
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_stop_reason or "insufficient_next_step_launch_contract_truth"
    out_next_action = "manual_review_required"
    status = "next_step_launch_contract_blocked_insufficient_truth"

    safety_policy_block = bool(
        not launch_budget_checked
        or bool(unsafe_state_detected)
        or bool(dirty_state_requires_stop)
        or bool(conflict_requires_stop)
        or bool(should_invoke_codex)
        or bool(should_execute_rollback)
        or bool(should_execute_commit)
        or bool(should_push)
        or bool(manual_review_required)
        or bool(should_stop)
    )
    budget_policy_block = bool(not launch_budget_checked)

    if len(non_stop_candidates) > 1:
        status = "next_step_launch_contract_blocked_conflict"
        launch_contract_available = True
        launch_contract_allowed = False
        launch_contract_ready_for_executor = False
        launch_conflict_detected = True
        conflicting_launch_contracts = list(non_stop_candidates)
        launch_contract_block_reason = "conflicting_next_step_launch_contracts"
        launch_safety_checked = True
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "conflicting_next_step_launch_contracts"
        out_next_action = "manual_review_required"
    elif manual_stop_launch_candidate and not (
        len(non_stop_candidates) == 1 and bool(contract_allowed)
    ):
        status = "next_step_launch_contract_manual_stop"
        launch_contract_available = True
        launch_contract_allowed = False
        launch_contract_kind = "manual_stop"
        launch_contract_action = "manual_review_required"
        launch_contract_payload = {
            "source": "prompt203_bounded_local_loop_contract",
            "stop_reason": normalized_stop_reason or "manual_stop",
            "next_action": "manual_review_required",
        }
        selected_launch_kind = "manual_stop"
        selected_launch_action = "manual_review_required"
        selected_launch_payload = dict(launch_contract_payload)
        exactly_one_launch_contract = True
        launch_conflict_detected = False
        conflicting_launch_contracts = []
        generated_prompt_reentry_launch_ready = False
        rollback_execution_launch_ready = False
        commit_execution_launch_ready = False
        manual_stop_launch_ready = True
        launch_contract_ready_for_executor = False
        launch_safety_checked = True
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_stop_reason or "manual_stop"
        out_next_action = "manual_review_required"
    elif not authoritative_source_selected:
        status = "next_step_launch_contract_blocked_insufficient_truth"
        launch_contract_available = False
        launch_contract_allowed = False
        launch_contract_block_reason = "insufficient_next_step_launch_contract_truth"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_next_step_launch_contract_truth"
        out_next_action = "manual_review_required"
    elif len(non_stop_candidates) == 0:
        status = "next_step_launch_contract_blocked_insufficient_truth"
        launch_contract_available = False
        launch_contract_allowed = False
        launch_contract_block_reason = "insufficient_next_step_launch_contract_truth"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_next_step_launch_contract_truth"
        out_next_action = "manual_review_required"
    elif safety_policy_block:
        status = (
            "next_step_launch_contract_blocked_budget"
            if budget_policy_block
            else "next_step_launch_contract_blocked_unsafe"
        )
        launch_contract_available = True
        launch_contract_allowed = False
        launch_contract_ready_for_executor = False
        launch_contract_block_reason = (
            "blocked_budget"
            if budget_policy_block
            else (
                "blocked_unsafe"
                if not bool(conflict_requires_stop)
                else "conflicting_next_step_launch_contracts"
            )
        )
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_stop_reason or launch_contract_block_reason
        out_next_action = "manual_review_required"
    else:
        chosen = non_stop_candidates[0]
        exactly_one_launch_contract = True
        launch_contract_available = True
        launch_contract_allowed = True
        launch_contract_source = "prompt203_bounded_local_loop_contract"
        launch_contract_ready_for_executor = True
        launch_requires_existing_executor = True
        launch_conflict_detected = False
        conflicting_launch_contracts = []
        out_manual_review_required = False
        out_should_stop = False
        out_stop_reason = ""
        if chosen == "generated_prompt_reentry_launch":
            status = "next_step_launch_contract_generated_prompt_reentry_ready"
            launch_contract_kind = "generated_prompt_reentry_launch"
            launch_contract_action = "launch_generated_prompt_reentry"
            launch_contract_payload = {
                "prompt_kind": generated_payload_kind,
                "prompt_path": generated_payload_path,
                "source": "prompt203_bounded_local_loop_contract",
                "max_invocations": 1,
                "next_action": "launch_generated_prompt_reentry",
            }
            generated_prompt_reentry_launch_ready = True
            selected_launch_kind = launch_contract_kind
            selected_launch_action = launch_contract_action
            selected_launch_payload = dict(launch_contract_payload)
            out_next_action = "launch_generated_prompt_reentry"
        elif chosen == "rollback_execution_launch":
            status = "next_step_launch_contract_rollback_execution_ready"
            launch_contract_kind = "rollback_execution_launch"
            launch_contract_action = "launch_rollback_execution"
            launch_contract_payload = {
                "source": "prompt203_bounded_local_loop_contract",
                "max_rollback_attempts": 1,
                "next_action": "launch_rollback_execution",
            }
            rollback_execution_launch_ready = True
            selected_launch_kind = launch_contract_kind
            selected_launch_action = launch_contract_action
            selected_launch_payload = dict(launch_contract_payload)
            out_next_action = "launch_rollback_execution"
        else:
            status = "next_step_launch_contract_commit_execution_ready"
            launch_contract_kind = "commit_execution_launch"
            launch_contract_action = "launch_commit_execution"
            launch_contract_payload = {
                "source": "prompt203_bounded_local_loop_contract",
                "max_commit_attempts": 1,
                "next_action": "launch_commit_execution",
            }
            commit_execution_launch_ready = True
            selected_launch_kind = launch_contract_kind
            selected_launch_action = launch_contract_action
            selected_launch_payload = dict(launch_contract_payload)
            out_next_action = "launch_commit_execution"

    if not launch_contract_payload:
        launch_contract_payload = {
            "source": "prompt203_bounded_local_loop_contract",
            "stop_reason": out_stop_reason or normalized_contract_block_reason,
            "next_action": out_next_action,
        }
    if not selected_launch_payload:
        selected_launch_payload = dict(launch_contract_payload)

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        status = "next_step_launch_contract_blocked_insufficient_truth"
        launch_contract_available = False
        launch_contract_allowed = False
        launch_contract_block_reason = "insufficient_next_step_launch_contract_truth"
        launch_contract_source = "prompt203_bounded_local_loop_contract"
        launch_contract_kind = "manual_stop"
        launch_contract_action = "manual_review_required"
        launch_contract_payload = {
            "source": "prompt203_bounded_local_loop_contract",
            "stop_reason": "insufficient_next_step_launch_contract_truth",
            "next_action": "manual_review_required",
        }
        launch_contract_ready_for_executor = False
        selected_launch_kind = "manual_stop"
        selected_launch_action = "manual_review_required"
        selected_launch_payload = dict(launch_contract_payload)
        exactly_one_launch_contract = False
        launch_conflict_detected = False
        conflicting_launch_contracts = []
        generated_prompt_reentry_launch_ready = False
        rollback_execution_launch_ready = False
        commit_execution_launch_ready = False
        manual_stop_launch_ready = False
        launch_budget_checked = bool(launch_budget_checked)
        launch_safety_checked = False
        launch_requires_existing_executor = False
        out_should_invoke_codex = False
        out_should_execute_rollback = False
        out_should_execute_commit = False
        out_should_push = False
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "insufficient_next_step_launch_contract_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_next_step_launch_contract_status": status,
        "project_browser_autonomous_next_step_launch_contract_launch_contract_available": bool(
            launch_contract_available
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_allowed": bool(
            launch_contract_allowed
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_block_reason": (
            launch_contract_block_reason
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_source": (
            launch_contract_source
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_kind": (
            launch_contract_kind
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_action": (
            launch_contract_action
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_payload": (
            launch_contract_payload
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_contract_ready_for_executor": bool(
            launch_contract_ready_for_executor
        ),
        "project_browser_autonomous_next_step_launch_contract_selected_launch_kind": (
            selected_launch_kind
        ),
        "project_browser_autonomous_next_step_launch_contract_selected_launch_action": (
            selected_launch_action
        ),
        "project_browser_autonomous_next_step_launch_contract_selected_launch_payload": (
            selected_launch_payload
        ),
        "project_browser_autonomous_next_step_launch_contract_exactly_one_launch_contract": bool(
            exactly_one_launch_contract
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_conflict_detected": bool(
            launch_conflict_detected
        ),
        "project_browser_autonomous_next_step_launch_contract_conflicting_launch_contracts": (
            conflicting_launch_contracts
        ),
        "project_browser_autonomous_next_step_launch_contract_generated_prompt_reentry_launch_ready": bool(
            generated_prompt_reentry_launch_ready
        ),
        "project_browser_autonomous_next_step_launch_contract_rollback_execution_launch_ready": bool(
            rollback_execution_launch_ready
        ),
        "project_browser_autonomous_next_step_launch_contract_commit_execution_launch_ready": bool(
            commit_execution_launch_ready
        ),
        "project_browser_autonomous_next_step_launch_contract_manual_stop_launch_ready": bool(
            manual_stop_launch_ready
        ),
        "project_browser_autonomous_next_step_launch_contract_codex_budget_remaining": int(
            codex_budget_remaining_normalized
        ),
        "project_browser_autonomous_next_step_launch_contract_rollback_budget_remaining": int(
            rollback_budget_remaining_normalized
        ),
        "project_browser_autonomous_next_step_launch_contract_commit_budget_remaining": int(
            commit_budget_remaining_normalized
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_budget_checked": bool(
            launch_budget_checked
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_safety_checked": bool(
            launch_safety_checked
        ),
        "project_browser_autonomous_next_step_launch_contract_launch_requires_existing_executor": bool(
            launch_requires_existing_executor
        ),
        "project_browser_autonomous_next_step_launch_contract_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_next_step_launch_contract_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_next_step_launch_contract_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_next_step_launch_contract_should_push": bool(out_should_push),
        "project_browser_autonomous_next_step_launch_contract_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_next_step_launch_contract_should_stop": bool(
            out_should_stop
        ),
        "project_browser_autonomous_next_step_launch_contract_stop_reason": out_stop_reason,
        "project_browser_autonomous_next_step_launch_contract_next_action": out_next_action,
        "project_browser_autonomous_next_step_launch_contract_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_step_launch_contract_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_loop_status,
                    normalized_contract_block_reason,
                    normalized_contract_source,
                    normalized_contract_kind,
                    normalized_contract_action,
                    normalized_feedback_kind,
                    normalized_next_step_kind,
                    normalized_next_step_action,
                    normalized_stop_reason,
                    normalized_next_action,
                    normalized_selected_lane_result_assimilation_status,
                    normalized_selected_lane_execution_status,
                    normalized_multi_cycle_controller_status,
                    normalized_generated_prompt_reentry_readiness_status,
                    normalized_generated_prompt_reentry_routing_status,
                    normalized_codex_reentry_invocation_status,
                    normalized_rollback_readiness_status,
                    normalized_rollback_execution_status,
                    normalized_commit_tag_readiness_status,
                    normalized_commit_tag_execution_status,
                    "authoritative_source_not_selected" if not authoritative_source_selected else "",
                    "launch_budget_not_checked" if not launch_budget_checked else "",
                    "feedback_payload_invalid"
                    if bool(feedback_selected) and not bool(feedback_payload_valid)
                    else "",
                    "non_stop_candidate_count_gt_one" if len(non_stop_candidates) > 1 else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_next_step_launch_execution_state(
    *,
    launch_contract_status: str,
    launch_contract_available: bool,
    launch_contract_allowed: bool,
    launch_contract_block_reason: str,
    launch_contract_source: str,
    launch_contract_kind: str,
    launch_contract_action: str,
    launch_contract_payload: Any,
    launch_contract_ready_for_executor: bool,
    selected_launch_kind: str,
    selected_launch_action: str,
    selected_launch_payload: Any,
    exactly_one_launch_contract: bool,
    launch_conflict_detected: bool,
    conflicting_launch_contracts: list[str] | None,
    generated_prompt_reentry_launch_ready: bool,
    rollback_execution_launch_ready: bool,
    commit_execution_launch_ready: bool,
    manual_stop_launch_ready: bool,
    codex_budget_remaining: int,
    rollback_budget_remaining: int,
    commit_budget_remaining: int,
    launch_budget_checked: bool,
    launch_safety_checked: bool,
    launch_requires_existing_executor: bool,
    launch_should_invoke_codex: bool,
    launch_should_execute_rollback: bool,
    launch_should_execute_commit: bool,
    launch_should_push: bool,
    launch_manual_review_required: bool,
    launch_should_stop: bool,
    launch_stop_reason: str,
    launch_next_action: str,
    bounded_local_loop_contract_status: str,
    selected_lane_result_assimilation_status: str,
    generated_prompt_reentry_readiness_status: str,
    generated_prompt_reentry_routing_status: str,
    codex_reentry_invocation_status: str,
    codex_reentry_invocation_next_action: str,
    codex_reentry_result_class: str,
    codex_reentry_result_ready_for_assimilation: bool,
    codex_reentry_invocation_attempted: bool,
    codex_reentry_human_review_required: bool,
    rollback_readiness_status: str,
    rollback_execution_status: str,
    rollback_execution_next_action: str,
    rollback_execution_human_review_required: bool,
    commit_tag_readiness_status: str,
    commit_tag_execution_status: str,
    commit_tag_execution_next_action: str,
    commit_tag_execution_human_review_required: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "next_step_launch_execution_generated_prompt_reentry_completed",
        "next_step_launch_execution_rollback_completed",
        "next_step_launch_execution_commit_completed",
        "next_step_launch_execution_manual_stop",
        "next_step_launch_execution_blocked_not_allowed",
        "next_step_launch_execution_blocked_multiple_launches",
        "next_step_launch_execution_blocked_unknown_launch",
        "next_step_launch_execution_blocked_existing_path",
        "next_step_launch_execution_blocked_insufficient_truth",
        "next_step_launch_execution_failed",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "assimilate_next_step_launch_result",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt205_next_step_launch_execution",
        "single_bounded_launch_only",
        "delegated_existing_paths_only",
        "no_new_executor",
        "no_retry",
        "no_loop",
        "no_push",
        "no_github_mutation",
    ]

    normalized_launch_contract_status = _normalize_text(
        launch_contract_status,
        default="insufficient_truth",
    )
    normalized_launch_contract_block_reason = _normalize_text(
        launch_contract_block_reason,
        default="",
    )
    normalized_launch_contract_source = _normalize_text(
        launch_contract_source,
        default="prompt204_next_step_launch_contract",
    )
    normalized_launch_contract_kind = _normalize_text(launch_contract_kind, default="")
    normalized_launch_contract_action = _normalize_text(
        launch_contract_action,
        default="manual_review_required",
    )
    normalized_selected_launch_kind = _normalize_text(selected_launch_kind, default="")
    normalized_selected_launch_action = _normalize_text(
        selected_launch_action,
        default="manual_review_required",
    )
    normalized_launch_stop_reason = _normalize_text(launch_stop_reason, default="")
    normalized_launch_next_action = _normalize_text(
        launch_next_action,
        default="manual_review_required",
    )
    normalized_bounded_local_loop_contract_status = _normalize_text(
        bounded_local_loop_contract_status,
        default="insufficient_truth",
    )
    normalized_selected_lane_result_assimilation_status = _normalize_text(
        selected_lane_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_generated_prompt_reentry_readiness_status = _normalize_text(
        generated_prompt_reentry_readiness_status,
        default="insufficient_truth",
    )
    normalized_generated_prompt_reentry_routing_status = _normalize_text(
        generated_prompt_reentry_routing_status,
        default="insufficient_truth",
    )
    normalized_codex_reentry_invocation_status = _normalize_text(
        codex_reentry_invocation_status,
        default="insufficient_truth",
    )
    normalized_codex_reentry_invocation_next_action = _normalize_text(
        codex_reentry_invocation_next_action,
        default="manual_review_required",
    )
    normalized_codex_reentry_result_class = _normalize_text(
        codex_reentry_result_class,
        default="blocked",
    )
    normalized_rollback_readiness_status = _normalize_text(
        rollback_readiness_status,
        default="insufficient_truth",
    )
    normalized_rollback_execution_status = _normalize_text(
        rollback_execution_status,
        default="insufficient_truth",
    )
    normalized_rollback_execution_next_action = _normalize_text(
        rollback_execution_next_action,
        default="manual_review_required",
    )
    normalized_commit_tag_readiness_status = _normalize_text(
        commit_tag_readiness_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_execution_status = _normalize_text(
        commit_tag_execution_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_execution_next_action = _normalize_text(
        commit_tag_execution_next_action,
        default="manual_review_required",
    )

    normalized_launch_contract_payload = (
        dict(launch_contract_payload) if isinstance(launch_contract_payload, Mapping) else {}
    )
    normalized_selected_launch_payload = (
        dict(selected_launch_payload) if isinstance(selected_launch_payload, Mapping) else {}
    )
    normalized_conflicting_launch_contracts = _normalize_string_list(
        conflicting_launch_contracts
    )

    normalized_codex_budget_remaining = _as_non_negative_int(codex_budget_remaining, default=0)
    normalized_rollback_budget_remaining = _as_non_negative_int(
        rollback_budget_remaining,
        default=0,
    )
    normalized_commit_budget_remaining = _as_non_negative_int(commit_budget_remaining, default=0)

    effective_selected_kind = (
        normalized_selected_launch_kind or normalized_launch_contract_kind
    )
    effective_selected_action = (
        normalized_selected_launch_action or normalized_launch_contract_action
    )
    effective_selected_payload = (
        normalized_selected_launch_payload
        if normalized_selected_launch_payload
        else normalized_launch_contract_payload
    )

    non_selected_candidates_true: list[str] = []
    if effective_selected_kind != "generated_prompt_reentry_launch" and bool(
        generated_prompt_reentry_launch_ready
    ):
        non_selected_candidates_true.append("generated_prompt_reentry_launch")
    if effective_selected_kind != "rollback_execution_launch" and bool(
        rollback_execution_launch_ready
    ):
        non_selected_candidates_true.append("rollback_execution_launch")
    if effective_selected_kind != "commit_execution_launch" and bool(
        commit_execution_launch_ready
    ):
        non_selected_candidates_true.append("commit_execution_launch")
    if effective_selected_kind != "manual_stop" and bool(manual_stop_launch_ready):
        non_selected_candidates_true.append("manual_stop")
    non_selected_candidates_true = sorted(non_selected_candidates_true)

    manual_stop_rule = bool(
        effective_selected_kind == "manual_stop"
        or bool(manual_stop_launch_ready)
        or bool(launch_manual_review_required)
        or bool(launch_should_stop)
    )

    selected_kind_is_supported = effective_selected_kind in {
        "generated_prompt_reentry_launch",
        "rollback_execution_launch",
        "commit_execution_launch",
    }
    selected_budget_ok = bool(
        (
            effective_selected_kind == "generated_prompt_reentry_launch"
            and normalized_codex_budget_remaining > 0
        )
        or (
            effective_selected_kind == "rollback_execution_launch"
            and normalized_rollback_budget_remaining > 0
        )
        or (
            effective_selected_kind == "commit_execution_launch"
            and normalized_commit_budget_remaining > 0
        )
    )
    allow_base = bool(
        bool(launch_contract_available)
        and bool(launch_contract_allowed)
        and bool(launch_contract_ready_for_executor)
        and bool(exactly_one_launch_contract)
        and not bool(launch_conflict_detected)
        and bool(launch_budget_checked)
        and bool(launch_safety_checked)
        and bool(launch_requires_existing_executor)
        and selected_kind_is_supported
        and not bool(launch_manual_review_required)
        and not bool(launch_should_stop)
        and not bool(launch_should_push)
        and not bool(non_selected_candidates_true)
        and selected_budget_ok
    )

    block_reason = _first_true_reason(
        [
            (not bool(launch_contract_allowed), "blocked_launch_contract_not_allowed"),
            (not bool(launch_contract_ready_for_executor), "blocked_launch_contract_not_ready"),
            (
                not bool(exactly_one_launch_contract),
                "blocked_not_exactly_one_launch_contract",
            ),
            (bool(launch_conflict_detected), "blocked_launch_conflict_detected"),
            (not bool(launch_budget_checked), "blocked_launch_budget_not_checked"),
            (not bool(launch_safety_checked), "blocked_launch_safety_not_checked"),
            (
                not bool(launch_requires_existing_executor),
                "blocked_existing_executor_not_required_or_missing",
            ),
            (bool(launch_manual_review_required), "blocked_manual_review_required"),
            (bool(launch_should_stop), "blocked_should_stop"),
            (bool(launch_should_push), "blocked_unexpected_push_flag"),
            (
                effective_selected_kind == "generated_prompt_reentry_launch"
                and normalized_codex_budget_remaining <= 0,
                "blocked_codex_budget_exhausted",
            ),
            (
                effective_selected_kind == "rollback_execution_launch"
                and normalized_rollback_budget_remaining <= 0,
                "blocked_rollback_budget_exhausted",
            ),
            (
                effective_selected_kind == "commit_execution_launch"
                and normalized_commit_budget_remaining <= 0,
                "blocked_commit_budget_exhausted",
            ),
            (len(non_selected_candidates_true) > 0, "blocked_multiple_launch_executions"),
            (
                not manual_stop_rule and not selected_kind_is_supported,
                "blocked_unknown_selected_launch_kind",
            ),
        ],
        default="blocked_insufficient_next_step_launch_execution_truth",
    )

    status = "next_step_launch_execution_blocked_insufficient_truth"
    launch_execution_allowed = False
    launch_execution_attempted = False
    launch_execution_completed = False
    launch_execution_failed = False
    launch_execution_block_reason = block_reason
    launch_execution_source = "prompt204_next_step_launch_contract"
    non_selected_launches_noop = True
    generated_prompt_reentry_launch_executed = False
    rollback_execution_launch_executed = False
    commit_execution_launch_executed = False
    manual_stop_launch_executed = False
    delegated_existing_path = False
    delegated_existing_path_kind = "none"
    delegated_existing_status = "insufficient_truth"
    delegated_existing_next_action = "manual_review_required"
    generated_prompt_reentry_result_status = ""
    rollback_execution_result_status = ""
    commit_execution_result_status = ""
    result_class = "blocked"
    out_should_invoke_codex = False
    out_should_execute_rollback = False
    out_should_execute_commit = False
    out_should_push = False
    out_manual_review_required = True
    out_should_stop = True
    out_stop_reason = normalized_launch_stop_reason or block_reason
    out_next_action = "manual_review_required"

    if manual_stop_rule:
        status = "next_step_launch_execution_manual_stop"
        launch_execution_allowed = False
        launch_execution_attempted = False
        launch_execution_completed = False
        launch_execution_failed = False
        launch_execution_block_reason = ""
        non_selected_launches_noop = True
        manual_stop_launch_executed = True
        result_class = "manual_stop"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_launch_stop_reason or "manual_stop"
        out_next_action = "manual_review_required"
    elif not allow_base:
        status = (
            "next_step_launch_execution_blocked_unknown_launch"
            if block_reason == "blocked_unknown_selected_launch_kind"
            else (
                "next_step_launch_execution_blocked_multiple_launches"
                if block_reason == "blocked_multiple_launch_executions"
                else "next_step_launch_execution_blocked_not_allowed"
            )
        )
        launch_execution_allowed = False
        launch_execution_attempted = False
        launch_execution_completed = False
        launch_execution_failed = False
        launch_execution_block_reason = block_reason
        non_selected_launches_noop = True
        result_class = "blocked"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = normalized_launch_stop_reason or block_reason
        out_next_action = "manual_review_required"
    else:
        launch_execution_allowed = True
        launch_execution_attempted = True
        non_selected_launches_noop = True
        delegated_existing_path = True
        launch_execution_source = "prompt204_next_step_launch_contract"

        if effective_selected_kind == "generated_prompt_reentry_launch":
            generated_prompt_reentry_launch_executed = True
            delegated_existing_path_kind = "generated_prompt_reentry"
            delegated_existing_status = normalized_codex_reentry_invocation_status
            delegated_existing_next_action = normalized_codex_reentry_invocation_next_action
            generated_prompt_reentry_result_status = normalized_codex_reentry_invocation_status
            launch_execution_attempted = bool(codex_reentry_invocation_attempted)
            if normalized_codex_reentry_invocation_status in {
                "reentry_invocation_completed_with_changes",
                "reentry_invocation_completed_no_changes",
                "reentry_invocation_completed_failure",
                "reentry_invocation_completed_timeout",
            } and bool(codex_reentry_result_ready_for_assimilation):
                status = "next_step_launch_execution_generated_prompt_reentry_completed"
                launch_execution_completed = True
                launch_execution_failed = bool(
                    normalized_codex_reentry_result_class
                    in {"completed_failure", "completed_timeout"}
                    or bool(codex_reentry_human_review_required)
                )
                launch_execution_block_reason = ""
                result_class = (
                    normalized_codex_reentry_result_class
                    if normalized_codex_reentry_result_class
                    else "generated_prompt_reentry_completed"
                )
                out_manual_review_required = bool(codex_reentry_human_review_required)
                out_should_stop = bool(codex_reentry_human_review_required)
                out_stop_reason = (
                    "generated_prompt_reentry_requires_manual_review"
                    if out_manual_review_required
                    else ""
                )
                out_next_action = "assimilate_next_step_launch_result"
            elif normalized_codex_reentry_invocation_status.startswith("blocked_"):
                status = "next_step_launch_execution_blocked_existing_path"
                launch_execution_completed = False
                launch_execution_failed = False
                launch_execution_block_reason = "blocked_existing_delegated_path"
                result_class = "blocked"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_existing_delegated_path"
                out_next_action = "manual_review_required"
            else:
                status = "next_step_launch_execution_blocked_insufficient_truth"
                launch_execution_completed = False
                launch_execution_failed = False
                launch_execution_block_reason = (
                    "blocked_insufficient_next_step_launch_execution_truth"
                )
                result_class = "insufficient_truth"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_insufficient_next_step_launch_execution_truth"
                out_next_action = "manual_review_required"
        elif effective_selected_kind == "rollback_execution_launch":
            rollback_execution_launch_executed = True
            delegated_existing_path_kind = "rollback_execution"
            delegated_existing_status = normalized_rollback_execution_status
            delegated_existing_next_action = normalized_rollback_execution_next_action
            rollback_execution_result_status = normalized_rollback_execution_status
            if normalized_rollback_execution_status in {
                "rollback_execution_completed",
                "rollback_execution_partial_failure",
                "rollback_execution_failed",
                "rollback_execution_timeout",
            }:
                status = "next_step_launch_execution_rollback_completed"
                launch_execution_completed = True
                launch_execution_failed = bool(
                    normalized_rollback_execution_status
                    in {
                        "rollback_execution_partial_failure",
                        "rollback_execution_failed",
                        "rollback_execution_timeout",
                    }
                )
                launch_execution_block_reason = ""
                result_class = normalized_rollback_execution_status
                out_manual_review_required = bool(
                    rollback_execution_human_review_required or launch_execution_failed
                )
                out_should_stop = bool(out_manual_review_required)
                out_stop_reason = (
                    "rollback_execution_requires_manual_review"
                    if out_manual_review_required
                    else ""
                )
                out_next_action = "assimilate_next_step_launch_result"
            elif normalized_rollback_execution_status.startswith("rollback_execution_blocked"):
                status = "next_step_launch_execution_blocked_existing_path"
                launch_execution_completed = False
                launch_execution_failed = False
                launch_execution_block_reason = "blocked_existing_delegated_path"
                result_class = "blocked"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_existing_delegated_path"
                out_next_action = "manual_review_required"
            else:
                status = "next_step_launch_execution_blocked_insufficient_truth"
                launch_execution_block_reason = (
                    "blocked_insufficient_next_step_launch_execution_truth"
                )
                result_class = "insufficient_truth"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_insufficient_next_step_launch_execution_truth"
                out_next_action = "manual_review_required"
        elif effective_selected_kind == "commit_execution_launch":
            commit_execution_launch_executed = True
            delegated_existing_path_kind = "commit_execution"
            delegated_existing_status = normalized_commit_tag_execution_status
            delegated_existing_next_action = normalized_commit_tag_execution_next_action
            commit_execution_result_status = normalized_commit_tag_execution_status
            if normalized_commit_tag_execution_status in {
                "commit_tag_execution_completed",
                "commit_tag_execution_failed_git_add",
                "commit_tag_execution_failed_git_commit",
                "commit_tag_execution_failed_git_tag",
                "commit_tag_execution_partial_commit_tag_failed",
                "commit_tag_execution_timeout",
            }:
                status = "next_step_launch_execution_commit_completed"
                launch_execution_completed = True
                launch_execution_failed = bool(
                    normalized_commit_tag_execution_status
                    != "commit_tag_execution_completed"
                )
                launch_execution_block_reason = ""
                result_class = normalized_commit_tag_execution_status
                out_manual_review_required = bool(
                    commit_tag_execution_human_review_required or launch_execution_failed
                )
                out_should_stop = bool(out_manual_review_required)
                out_stop_reason = (
                    "commit_execution_requires_manual_review"
                    if out_manual_review_required
                    else ""
                )
                out_next_action = "assimilate_next_step_launch_result"
            elif normalized_commit_tag_execution_status.startswith("commit_tag_execution_blocked"):
                status = "next_step_launch_execution_blocked_existing_path"
                launch_execution_completed = False
                launch_execution_failed = False
                launch_execution_block_reason = "blocked_existing_delegated_path"
                result_class = "blocked"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_existing_delegated_path"
                out_next_action = "manual_review_required"
            else:
                status = "next_step_launch_execution_blocked_insufficient_truth"
                launch_execution_block_reason = (
                    "blocked_insufficient_next_step_launch_execution_truth"
                )
                result_class = "insufficient_truth"
                out_manual_review_required = True
                out_should_stop = True
                out_stop_reason = "blocked_insufficient_next_step_launch_execution_truth"
                out_next_action = "manual_review_required"
        else:
            status = "next_step_launch_execution_blocked_unknown_launch"
            launch_execution_allowed = False
            launch_execution_attempted = False
            launch_execution_completed = False
            launch_execution_failed = False
            launch_execution_block_reason = "blocked_unknown_selected_launch_kind"
            delegated_existing_path = False
            delegated_existing_path_kind = "none"
            delegated_existing_status = "insufficient_truth"
            delegated_existing_next_action = "manual_review_required"
            result_class = "blocked"
            out_manual_review_required = True
            out_should_stop = True
            out_stop_reason = "blocked_unknown_selected_launch_kind"
            out_next_action = "manual_review_required"

    total_launch_executed = sum(
        [
            1 if generated_prompt_reentry_launch_executed else 0,
            1 if rollback_execution_launch_executed else 0,
            1 if commit_execution_launch_executed else 0,
            1 if manual_stop_launch_executed else 0,
        ]
    )
    if total_launch_executed > 1:
        status = "next_step_launch_execution_blocked_multiple_launches"
        launch_execution_allowed = False
        launch_execution_attempted = False
        launch_execution_completed = False
        launch_execution_failed = False
        launch_execution_block_reason = "blocked_multiple_launch_executions"
        non_selected_launches_noop = False
        generated_prompt_reentry_launch_executed = False
        rollback_execution_launch_executed = False
        commit_execution_launch_executed = False
        manual_stop_launch_executed = False
        delegated_existing_path = False
        delegated_existing_path_kind = "none"
        delegated_existing_status = "insufficient_truth"
        delegated_existing_next_action = "manual_review_required"
        generated_prompt_reentry_result_status = ""
        rollback_execution_result_status = ""
        commit_execution_result_status = ""
        result_class = "blocked"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_multiple_launch_executions"
        out_next_action = "manual_review_required"

    if status not in allowed_statuses:
        status = "insufficient_truth"
    if out_next_action not in allowed_next_actions:
        out_next_action = "insufficient_truth"
    if status == "insufficient_truth":
        status = "next_step_launch_execution_blocked_insufficient_truth"
        launch_execution_allowed = False
        launch_execution_attempted = False
        launch_execution_completed = False
        launch_execution_failed = False
        launch_execution_block_reason = "blocked_insufficient_next_step_launch_execution_truth"
        launch_execution_source = "prompt204_next_step_launch_contract"
        non_selected_launches_noop = True
        generated_prompt_reentry_launch_executed = False
        rollback_execution_launch_executed = False
        commit_execution_launch_executed = False
        manual_stop_launch_executed = False
        delegated_existing_path = False
        delegated_existing_path_kind = "none"
        delegated_existing_status = "insufficient_truth"
        delegated_existing_next_action = "manual_review_required"
        generated_prompt_reentry_result_status = ""
        rollback_execution_result_status = ""
        commit_execution_result_status = ""
        result_class = "insufficient_truth"
        out_manual_review_required = True
        out_should_stop = True
        out_stop_reason = "blocked_insufficient_next_step_launch_execution_truth"
        out_next_action = "manual_review_required"

    return {
        "project_browser_autonomous_next_step_launch_execution_status": status,
        "project_browser_autonomous_next_step_launch_execution_launch_execution_allowed": bool(
            launch_execution_allowed
        ),
        "project_browser_autonomous_next_step_launch_execution_launch_execution_attempted": bool(
            launch_execution_attempted
        ),
        "project_browser_autonomous_next_step_launch_execution_launch_execution_completed": bool(
            launch_execution_completed
        ),
        "project_browser_autonomous_next_step_launch_execution_launch_execution_failed": bool(
            launch_execution_failed
        ),
        "project_browser_autonomous_next_step_launch_execution_launch_execution_block_reason": (
            launch_execution_block_reason
        ),
        "project_browser_autonomous_next_step_launch_execution_launch_execution_source": (
            launch_execution_source
        ),
        "project_browser_autonomous_next_step_launch_execution_selected_launch_kind": (
            effective_selected_kind
        ),
        "project_browser_autonomous_next_step_launch_execution_selected_launch_action": (
            effective_selected_action
        ),
        "project_browser_autonomous_next_step_launch_execution_selected_launch_payload": (
            effective_selected_payload
        ),
        "project_browser_autonomous_next_step_launch_execution_non_selected_launches_noop": bool(
            non_selected_launches_noop
        ),
        "project_browser_autonomous_next_step_launch_execution_generated_prompt_reentry_launch_executed": bool(
            generated_prompt_reentry_launch_executed
        ),
        "project_browser_autonomous_next_step_launch_execution_rollback_execution_launch_executed": bool(
            rollback_execution_launch_executed
        ),
        "project_browser_autonomous_next_step_launch_execution_commit_execution_launch_executed": bool(
            commit_execution_launch_executed
        ),
        "project_browser_autonomous_next_step_launch_execution_manual_stop_launch_executed": bool(
            manual_stop_launch_executed
        ),
        "project_browser_autonomous_next_step_launch_execution_delegated_existing_path": bool(
            delegated_existing_path
        ),
        "project_browser_autonomous_next_step_launch_execution_delegated_existing_path_kind": (
            delegated_existing_path_kind
        ),
        "project_browser_autonomous_next_step_launch_execution_delegated_existing_status": (
            delegated_existing_status
        ),
        "project_browser_autonomous_next_step_launch_execution_delegated_existing_next_action": (
            delegated_existing_next_action
        ),
        "project_browser_autonomous_next_step_launch_execution_generated_prompt_reentry_result_status": (
            generated_prompt_reentry_result_status
        ),
        "project_browser_autonomous_next_step_launch_execution_rollback_execution_result_status": (
            rollback_execution_result_status
        ),
        "project_browser_autonomous_next_step_launch_execution_commit_execution_result_status": (
            commit_execution_result_status
        ),
        "project_browser_autonomous_next_step_launch_execution_result_class": result_class,
        "project_browser_autonomous_next_step_launch_execution_next_step_launch_result_ready_for_assimilation": True,
        "project_browser_autonomous_next_step_launch_execution_next_step_launch_result_assimilation_source": (
            "prompt205_next_step_launch_execution"
        ),
        "project_browser_autonomous_next_step_launch_execution_next_step_launch_result_next_stage": (
            "next_step_launch_result_assimilation"
        ),
        "project_browser_autonomous_next_step_launch_execution_should_invoke_codex": bool(
            out_should_invoke_codex
        ),
        "project_browser_autonomous_next_step_launch_execution_should_execute_rollback": bool(
            out_should_execute_rollback
        ),
        "project_browser_autonomous_next_step_launch_execution_should_execute_commit": bool(
            out_should_execute_commit
        ),
        "project_browser_autonomous_next_step_launch_execution_should_push": bool(
            out_should_push
        ),
        "project_browser_autonomous_next_step_launch_execution_manual_review_required": bool(
            out_manual_review_required
        ),
        "project_browser_autonomous_next_step_launch_execution_should_stop": bool(
            out_should_stop
        ),
        "project_browser_autonomous_next_step_launch_execution_stop_reason": out_stop_reason,
        "project_browser_autonomous_next_step_launch_execution_next_action": out_next_action,
        "project_browser_autonomous_next_step_launch_execution_runtime_posture": runtime_posture,
        "project_browser_autonomous_next_step_launch_execution_missing_inputs": (
            _serialize_required_signals(
                [
                    normalized_launch_contract_status,
                    normalized_launch_contract_block_reason,
                    normalized_launch_contract_source,
                    normalized_launch_contract_kind,
                    normalized_launch_contract_action,
                    normalized_selected_launch_kind,
                    normalized_selected_launch_action,
                    normalized_launch_stop_reason,
                    normalized_launch_next_action,
                    normalized_bounded_local_loop_contract_status,
                    normalized_selected_lane_result_assimilation_status,
                    normalized_generated_prompt_reentry_readiness_status,
                    normalized_generated_prompt_reentry_routing_status,
                    normalized_codex_reentry_invocation_status,
                    normalized_codex_reentry_invocation_next_action,
                    normalized_rollback_readiness_status,
                    normalized_rollback_execution_status,
                    normalized_rollback_execution_next_action,
                    normalized_commit_tag_readiness_status,
                    normalized_commit_tag_execution_status,
                    normalized_commit_tag_execution_next_action,
                    "launch_contract_not_available" if not bool(launch_contract_available) else "",
                    "selected_payload_missing"
                    if selected_kind_is_supported and not bool(effective_selected_payload)
                    else "",
                ]
            )
        ),
    }


def _build_project_browser_autonomous_next_step_launch_result_assimilation_state(
    *,
    next_step_launch_execution_status: str,
    launch_execution_allowed: bool,
    launch_execution_attempted: bool,
    launch_execution_completed: bool,
    launch_execution_failed: bool,
    launch_execution_block_reason: str,
    launch_execution_source: str,
    selected_launch_kind: str,
    selected_launch_action: str,
    selected_launch_payload: Any,
    non_selected_launches_noop: bool,
    generated_prompt_reentry_launch_executed: bool,
    rollback_execution_launch_executed: bool,
    commit_execution_launch_executed: bool,
    manual_stop_launch_executed: bool,
    delegated_existing_path: bool,
    delegated_existing_path_kind: str,
    delegated_existing_status: str,
    delegated_existing_next_action: str,
    generated_prompt_reentry_result_status: str,
    rollback_execution_result_status: str,
    commit_execution_result_status: str,
    launch_execution_result_class: str,
    next_step_launch_result_ready_for_assimilation: bool,
    next_step_launch_result_assimilation_source: str,
    next_step_launch_result_next_stage: str,
    launch_execution_should_invoke_codex: bool,
    launch_execution_should_execute_rollback: bool,
    launch_execution_should_execute_commit: bool,
    launch_execution_should_push: bool,
    launch_execution_manual_review_required: bool,
    launch_execution_should_stop: bool,
    launch_execution_stop_reason: str,
    launch_execution_next_action: str,
    next_step_launch_contract_status: str,
    bounded_local_loop_contract_status: str,
    multi_cycle_controller_status: str,
    reentry_result_assimilation_status: str,
    rollback_result_assimilation_status: str,
    commit_tag_result_assimilation_status: str,
) -> dict[str, Any]:
    allowed_statuses = {
        "next_step_launch_result_generated_prompt_reentry_completed",
        "next_step_launch_result_rollback_execution_completed",
        "next_step_launch_result_commit_execution_completed",
        "next_step_launch_result_manual_stop",
        "next_step_launch_result_failed",
        "next_step_launch_result_blocked",
        "next_step_launch_result_blocked_non_selected_launch_activity",
        "next_step_launch_result_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_result_classes = {
        "generated_prompt_reentry_completed",
        "rollback_execution_completed",
        "commit_execution_completed",
        "manual_stop",
        "blocked",
        "failed",
        "insufficient_truth",
        "blocked_non_selected_launch_activity",
    }
    allowed_next_actions = {
        "prepare_reentry_result_assimilation",
        "prepare_rollback_result_assimilation",
        "prepare_commit_result_assimilation",
        "manual_review_required",
        "insufficient_truth",
    }
    runtime_posture = [
        "prompt206_next_step_launch_result_assimilation",
        "metadata_only",
        "no_additional_launch_execution",
        "no_codex_invocation",
        "no_validation_execution",
        "no_rollback_execution",
        "no_commit_execution",
        "no_push",
    ]

    normalized_execution_status = _normalize_text(
        next_step_launch_execution_status,
        default="insufficient_truth",
    )
    normalized_execution_block_reason = _normalize_text(
        launch_execution_block_reason,
        default="",
    )
    normalized_execution_source = _normalize_text(
        launch_execution_source,
        default="prompt205_next_step_launch_execution",
    )
    normalized_selected_launch_kind = _normalize_text(selected_launch_kind, default="")
    normalized_selected_launch_action = _normalize_text(
        selected_launch_action,
        default="manual_review_required",
    )
    normalized_delegated_existing_path_kind = _normalize_text(
        delegated_existing_path_kind,
        default="none",
    )
    normalized_delegated_existing_status = _normalize_text(
        delegated_existing_status,
        default="insufficient_truth",
    )
    normalized_delegated_existing_next_action = _normalize_text(
        delegated_existing_next_action,
        default="manual_review_required",
    )
    normalized_generated_prompt_reentry_result_status = _normalize_text(
        generated_prompt_reentry_result_status,
        default="",
    )
    normalized_rollback_execution_result_status = _normalize_text(
        rollback_execution_result_status,
        default="",
    )
    normalized_commit_execution_result_status = _normalize_text(
        commit_execution_result_status,
        default="",
    )
    normalized_launch_execution_result_class = _normalize_text(
        launch_execution_result_class,
        default="blocked",
    )
    normalized_assimilation_source = _normalize_text(
        next_step_launch_result_assimilation_source,
        default="",
    )
    normalized_assimilation_next_stage = _normalize_text(
        next_step_launch_result_next_stage,
        default="",
    )
    normalized_stop_reason = _normalize_text(launch_execution_stop_reason, default="")
    normalized_execution_next_action = _normalize_text(
        launch_execution_next_action,
        default="manual_review_required",
    )
    normalized_next_step_launch_contract_status = _normalize_text(
        next_step_launch_contract_status,
        default="insufficient_truth",
    )
    normalized_bounded_local_loop_contract_status = _normalize_text(
        bounded_local_loop_contract_status,
        default="insufficient_truth",
    )
    normalized_multi_cycle_controller_status = _normalize_text(
        multi_cycle_controller_status,
        default="insufficient_truth",
    )
    normalized_reentry_result_assimilation_status = _normalize_text(
        reentry_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_rollback_result_assimilation_status = _normalize_text(
        rollback_result_assimilation_status,
        default="insufficient_truth",
    )
    normalized_commit_tag_result_assimilation_status = _normalize_text(
        commit_tag_result_assimilation_status,
        default="insufficient_truth",
    )

    _normalized_selected_launch_payload = (
        dict(selected_launch_payload) if isinstance(selected_launch_payload, Mapping) else {}
    )

    authoritative_selected = bool(
        bool(next_step_launch_result_ready_for_assimilation)
        and normalized_assimilation_source == "prompt205_next_step_launch_execution"
        and normalized_assimilation_next_stage == "next_step_launch_result_assimilation"
        and bool(normalized_selected_launch_kind)
        and bool(
            normalized_execution_status != "insufficient_truth"
            or normalized_launch_execution_result_class != "blocked"
        )
    )

    status = "next_step_launch_result_blocked_insufficient_truth"
    result_selected = False
    result_available = False
    result_class = "insufficient_truth"
    result_block_reason = "blocked_insufficient_next_step_launch_result_truth"
    source_execution_status = normalized_execution_status
    source_execution_completed = bool(launch_execution_completed)
    source_execution_failed = bool(launch_execution_failed)
    non_selected_launches_noop_confirmed = bool(non_selected_launches_noop)
    controller_feedback_ready = False
    controller_feedback_kind = "none"
    controller_feedback_source = ""
    controller_feedback_payload: dict[str, Any] = {}
    next_controller_input_ready = False
    next_controller_input_kind = "none"
