    if authoritative_ready:
        truth_bridge_ready = True
        prompt222_reflection_ready = True
        n2_readiness_summary_ready = True
        should_prepare_prompt242 = True
        manual_artifact_supply_next_action = (
            "prepare_prompt242_manual_artifact_supply_path_intake"
        )
        next_action = "prepare_prompt242_manual_artifact_supply_path_intake"

        if bool(validity_decision_ready):
            status = "fresh_runtime_evidence_truth_bridge_ready"
            truth_update_allowed = True
