        should_prepare_prompt242 = False
        normalized_required_artifacts = []
        normalized_supplied_artifact_paths = []
        normalized_missing_supplied_artifact_paths = []
        normalized_validity_status = ""
        normalized_validity_block_reason = "insufficient_truth"
        normalized_validity_findings = []
        forbidden_actions = []

