def _build_project_browser_autonomous_artifact_review_manual_supply_handling_phase_state(
    *,
    prompt243_status: str,
    prompt243_surface_available: bool,
    prompt243_surface_authoritative: bool,
    selected_check_kind: str,
    should_prepare_prompt244: bool,
    manual_artifact_supply_required: bool,
    required_artifacts: Any,
    supplied_artifact_paths: Any,
    missing_supplied_artifact_paths: Any,
    expected_supplied_path_fields: Any,
) -> dict[str, Any]:
    allowed_statuses = {
        "artifact_review_manual_supply_handling_phase_awaiting_explicit_paths",
        "artifact_review_manual_supply_handling_phase_ready_for_permission_recalculation",
        "artifact_review_manual_supply_handling_phase_blocked_prompt243_not_ready",
        "artifact_review_manual_supply_handling_phase_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_prompt245_read_parse_permission_and_content_consistency_contract",
        "manual_review_required",
        "insufficient_truth",
    }

    normalized_prompt243_status = _normalize_text(prompt243_status, default="")
    normalized_selected_check_kind = _normalize_text(selected_check_kind, default="")
    normalized_required_artifacts = _normalize_string_list(required_artifacts)
    normalized_supplied_artifact_paths = _normalize_string_list(supplied_artifact_paths)
    normalized_missing_supplied_artifact_paths = _normalize_string_list(
        missing_supplied_artifact_paths
    )
    normalized_expected_supplied_path_fields = _normalize_string_list(
        expected_supplied_path_fields
    )
    normalized_required_artifact_set = set(normalized_required_artifacts)
    required_artifact_set = {
        "approved_restart_execution_contract.json",
        "run_state.json",
        "manifest.json",
    }
    required_artifacts_present = required_artifact_set.issubset(
        normalized_required_artifact_set
    )

    forbidden_actions = [
        "read_files",
        "parse_json",
        "validate_file_existence",
        "filesystem_scan",
        "command_execution",
        "codex_invocation",
        "git_mutation",
        "commit",
        "tag",
        "push",
        "rollback",
        "retry",
        "github_mutation",
        "unbounded_loop",
        "prompt222_update",
        "n2_reevaluation",
    ]

    authoritative_ready = bool(
        prompt243_surface_available
        and prompt243_surface_authoritative
        and should_prepare_prompt244
        and normalized_selected_check_kind == "fresh_runtime_evidence_check"
        and manual_artifact_supply_required
        and required_artifacts_present
    )

    status = "artifact_review_manual_supply_handling_phase_blocked_prompt243_not_ready"
    next_action = "manual_review_required"
    manual_supply_handling_ready = False
    manual_supply_status = "blocked_prompt243_not_ready"
