def _build_project_browser_autonomous_read_parse_permission_content_consistency_state(
    *,
    prompt244_status: str,
    prompt244_surface_available: bool,
    prompt244_surface_authoritative: bool,
    should_prepare_prompt245: bool,
    required_artifacts: Any,
    supplied_artifact_paths: Any,
    missing_supplied_artifact_paths: Any,
    normalized_supplied_artifact_paths: Any,
    path_requirement_conformance: str,
    same_run_scope_conformance: str,
    artifact_name_conformance: str,
    review_permission_recalculation_status: str,
    review_permission_summary: Any,
    artifact_review_assimilation_ready: bool,
    validity_recheck_ready: bool,
    read_parse_gate_ready: bool,
    read_parse_gate_status: str,
    truth_update_allowed: bool,
    prompt222_reflection_allowed: bool,
    n2_readiness_allowed: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "read_parse_permission_content_consistency_ready_for_prompt246_prep",
        "read_parse_permission_content_consistency_blocked_missing_supplied_paths",
        "read_parse_permission_content_consistency_blocked_prompt244_not_ready",
        "read_parse_permission_content_consistency_blocked_metadata_preconditions",
        "read_parse_permission_content_consistency_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_prompt246_artifact_content_review_and_fresh_evidence_validity",
        "manual_review_required",
        "insufficient_truth",
    }
    required_artifact_set = {
        "approved_restart_execution_contract.json",
        "run_state.json",
        "manifest.json",
    }
    forbidden_actions = [
        "read_files",
        "parse_json",
        "validate_file_existence",
        "filesystem_scan",
        "command_execution",
        "codex_invocation",
        "git_mutation",
        "commit",
        "tag",
        "push",
        "rollback",
        "retry",
        "github_mutation",
        "unbounded_loop",
        "prompt222_update",
        "n2_reevaluation",
    ]
    content_consistency_contract = [
        "all_required_artifacts_must_have_explicit_paths",
        "same_run_scope_must_be_verified_later",
        "approved_restart_contract_artifact_required",
        "run_state_artifact_required",
        "manifest_artifact_required",
        "no_content_read_in_prompt245",
    ]
    json_schema_expectation_contract = [
        "approved_restart_execution_contract_json_expected",
        "run_state_json_expected",
        "manifest_json_expected",
        "json_parse_deferred",
        "schema_validation_deferred",
    ]
    artifact_triad_preconditions = [
        "all_required_artifact_paths_supplied",
        "normalized_paths_non_empty",
        "artifact_names_match_required_set",
        "same_out_dir_required",
        "same_job_id_required",
        "same_transport_mode_required",
        "no_glob_expansion",
        "no_filesystem_discovery",
        "existence_validation_permission_required",
        "read_permission_required",
        "parse_permission_required",
    ]
    fresh_evidence_validity_preconditions = [
        "artifact_review_readiness_required",
        "content_consistency_contract_required",
        "json_schema_expectation_contract_required",
        "all_required_artifacts_same_run_required",
        "no_prompt222_update_before_validity_true",
        "no_n2_reevaluation_before_validity_true",
    ]

    normalized_prompt244_status = _normalize_text(prompt244_status, default="")
    normalized_required_artifacts = _normalize_string_list(required_artifacts)
    normalized_supplied_artifact_paths = _normalize_string_list(supplied_artifact_paths)
    normalized_missing_supplied_artifact_paths = _normalize_string_list(
        missing_supplied_artifact_paths
    )
    normalized_normalized_supplied_artifact_paths = _normalize_string_list(
        normalized_supplied_artifact_paths
    )
    normalized_required_artifact_set = set(normalized_required_artifacts)
    required_artifacts_present = required_artifact_set.issubset(
        normalized_required_artifact_set
    )
    normalized_path_requirement_conformance = _normalize_text(
        path_requirement_conformance, default=""
    )
    normalized_same_run_scope_conformance = _normalize_text(
        same_run_scope_conformance, default=""
    )
    normalized_artifact_name_conformance = _normalize_text(
        artifact_name_conformance, default=""
    )
    normalized_review_permission_recalculation_status = _normalize_text(
        review_permission_recalculation_status, default=""
    )
    normalized_review_permission_summary = _normalize_contract_payload(
        review_permission_summary
    )
    normalized_artifact_review_assimilation_ready = bool(artifact_review_assimilation_ready)
    normalized_validity_recheck_ready = bool(validity_recheck_ready)
    normalized_truth_update_allowed = bool(truth_update_allowed)
    normalized_prompt222_reflection_allowed = bool(prompt222_reflection_allowed)
    normalized_n2_readiness_allowed = bool(n2_readiness_allowed)
    normalized_read_parse_gate_status = _normalize_text(read_parse_gate_status, default="")

    status = "read_parse_permission_content_consistency_blocked_prompt244_not_ready"
    next_action = "manual_review_required"
    read_permission = False
    parse_permission = False
    existence_validation_permission = False
    read_permission_status = "blocked_prompt244_not_ready"
    parse_permission_status = "blocked_prompt244_not_ready"
    existence_validation_permission_status = "blocked_prompt244_not_ready"
    content_consistency_contract_ready = False
    content_consistency_contract_status = "blocked_prompt244_not_ready"
    json_schema_expectation_contract_ready = False
    json_schema_expectation_contract_status = "blocked_prompt244_not_ready"
    artifact_triad_preconditions_ready = False
    artifact_review_readiness = False
    artifact_review_readiness_status = "blocked_prompt244_not_ready"
    artifact_review_block_reason = "prompt244_not_ready"
    fresh_evidence_validity_preconditions_ready = False
    prompt246_artifact_content_review_ready = False
    prompt246_artifact_content_review_block_reason = "prompt244_not_ready"
    should_prepare_prompt246 = False
    truth_update_allowed_final = False
    prompt222_reflection_allowed_final = False
    n2_readiness_allowed_final = False

    authoritative_ready = bool(
        prompt244_surface_available
        and prompt244_surface_authoritative
        and should_prepare_prompt245
        and required_artifacts_present
        and normalized_prompt244_status
    )

    if authoritative_ready:
        should_prepare_prompt246 = True
        next_action = "prepare_prompt246_artifact_content_review_and_fresh_evidence_validity"
        all_required_artifact_paths_supplied = not normalized_missing_supplied_artifact_paths
        normalized_paths_non_empty = bool(normalized_normalized_supplied_artifact_paths)
        artifact_names_match_required_set = (
            normalized_artifact_name_conformance == "conformant"
        )
        same_scope_ready = normalized_same_run_scope_conformance == "conformant"
        no_glob_expansion = normalized_path_requirement_conformance == "conformant"
        no_filesystem_discovery = normalized_path_requirement_conformance == "conformant"
        review_permissions_ready = bool(
            normalized_review_permission_summary.get("existence_review_permission", False)
            and normalized_review_permission_summary.get("content_review_permission", False)
            and normalized_review_permission_summary.get("json_review_permission", False)
            and normalized_review_permission_recalculation_status
            == "ready_for_review_permissions"
        )
        prompt244_validity_ready = bool(
            normalized_artifact_review_assimilation_ready
            and normalized_validity_recheck_ready
        )
        blocked_truth_posture = not (
            normalized_truth_update_allowed
            or normalized_prompt222_reflection_allowed
            or normalized_n2_readiness_allowed
        )
        read_parse_gate_open = bool(
            read_parse_gate_ready
            and normalized_read_parse_gate_status == "ready_for_read_parse_permissions"
        )
        permission_metadata_ready = bool(
            all_required_artifact_paths_supplied
            and normalized_paths_non_empty
            and artifact_names_match_required_set
            and same_scope_ready
            and no_glob_expansion
            and no_filesystem_discovery
            and review_permissions_ready
            and prompt244_validity_ready
            and blocked_truth_posture
            and read_parse_gate_open
        )

        if permission_metadata_ready:
            status = "read_parse_permission_content_consistency_ready_for_prompt246_prep"
            read_permission = True
            parse_permission = True
            existence_validation_permission = True
            read_permission_status = "ready_metadata_only_read_permission"
            parse_permission_status = "ready_metadata_only_parse_permission"
            existence_validation_permission_status = (
                "ready_metadata_only_existence_validation_permission"
            )
            content_consistency_contract_ready = True
            content_consistency_contract_status = "ready_metadata_only_contract"
            json_schema_expectation_contract_ready = True
            json_schema_expectation_contract_status = "ready_metadata_only_contract"
            artifact_triad_preconditions_ready = True
