def _build_project_browser_autonomous_artifact_content_review_fresh_evidence_validity_state(
    *,
    prompt245_status: str,
    prompt245_surface_available: bool,
    prompt245_surface_authoritative: bool,
    should_prepare_prompt246: bool,
    required_artifacts: Any,
    supplied_artifact_paths: Any,
    normalized_supplied_artifact_paths: Any,
    missing_supplied_artifact_paths: Any,
    read_permission: bool,
    parse_permission: bool,
    existence_validation_permission: bool,
    content_consistency_contract_ready: bool,
    content_consistency_contract: Any,
    json_schema_expectation_contract_ready: bool,
    json_schema_expectation_contract: Any,
    artifact_triad_preconditions: Any,
    artifact_triad_preconditions_ready: bool,
    artifact_review_readiness: bool,
    artifact_review_block_reason: str,
    fresh_evidence_validity_preconditions: Any,
    fresh_evidence_validity_preconditions_ready: bool,
) -> dict[str, Any]:
    allowed_statuses = {
        "artifact_content_review_fresh_evidence_validity_ready_for_prompt247_bridge",
        "artifact_content_review_fresh_evidence_validity_blocked_missing_supplied_paths",
        "artifact_content_review_fresh_evidence_validity_blocked_prompt245_not_ready",
        "artifact_content_review_fresh_evidence_validity_blocked_metadata_preconditions",
        "artifact_content_review_fresh_evidence_validity_blocked_insufficient_truth",
        "insufficient_truth",
    }
    allowed_next_actions = {
        "prepare_prompt247_prompt222_n2_bridge_readiness_phase",
        "manual_review_required",
        "insufficient_truth",
    }
    required_artifact_set = {
        "approved_restart_execution_contract.json",
        "run_state.json",
        "manifest.json",
    }
    forbidden_actions = [
        "read_files",
        "parse_json",
        "validate_file_existence",
        "filesystem_scan",
        "command_execution",
        "codex_invocation",
        "git_mutation",
        "commit",
        "tag",
        "push",
        "rollback",
        "retry",
        "github_mutation",
        "unbounded_loop",
        "prompt222_update",
        "n2_reevaluation",
    ]

    normalized_prompt245_status = _normalize_text(prompt245_status, default="")
    normalized_required_artifacts = _normalize_string_list(required_artifacts)
    normalized_supplied_artifact_paths = _normalize_string_list(supplied_artifact_paths)
    normalized_normalized_supplied_artifact_paths = _normalize_string_list(
        normalized_supplied_artifact_paths
    )
    normalized_missing_supplied_artifact_paths = _normalize_string_list(
        missing_supplied_artifact_paths
    )
    normalized_required_artifact_set = set(normalized_required_artifacts)
    required_artifacts_present = required_artifact_set.issubset(
        normalized_required_artifact_set
    )
    normalized_content_consistency_contract_ready = bool(content_consistency_contract_ready)
    normalized_content_consistency_contract = _normalize_string_list(
        content_consistency_contract
    )
    normalized_json_schema_expectation_contract_ready = bool(
        json_schema_expectation_contract_ready
    )
    normalized_json_schema_expectation_contract = _normalize_string_list(
        json_schema_expectation_contract
    )
    normalized_artifact_triad_preconditions = _normalize_string_list(
        artifact_triad_preconditions
    )
    normalized_artifact_triad_preconditions_ready = bool(artifact_triad_preconditions_ready)
    normalized_artifact_review_readiness = bool(artifact_review_readiness)
    normalized_artifact_review_block_reason = _normalize_text(
        artifact_review_block_reason, default=""
    )
    normalized_fresh_evidence_validity_preconditions = _normalize_string_list(
        fresh_evidence_validity_preconditions
    )
    normalized_fresh_evidence_validity_preconditions_ready = bool(
        fresh_evidence_validity_preconditions_ready
    )

    status = "artifact_content_review_fresh_evidence_validity_blocked_prompt245_not_ready"
    next_action = "manual_review_required"
    content_review_ready = False
    content_review_status = "blocked_prompt245_not_ready"
    json_review_ready = False
    json_review_status = "blocked_prompt245_not_ready"
    artifact_triad_review_ready = False
    artifact_triad_review_status = "blocked_prompt245_not_ready"
    artifact_content_review_decision = "not_reviewable_prompt245_not_ready"
    artifact_content_review_block_reason = "prompt245_not_ready"
    fresh_evidence_validity_decision_ready = False
    fresh_evidence_validity_status = "blocked_prompt245_not_ready"
    fresh_evidence_validity_block_reason = "prompt245_not_ready"
    fresh_evidence_validity_findings: list[str] = []
