    truth_update_allowed = False
    prompt222_reflection_readiness = False
    prompt222_reflection_allowed = False
    n2_readiness_summary_ready = False
    n2_readiness_allowed = False
    prompt247_bridge_ready = False
    prompt247_bridge_block_reason = "prompt245_not_ready"
