        json_review_status = "blocked_insufficient_truth"
        artifact_triad_review_ready = False
        artifact_triad_review_status = "blocked_insufficient_truth"
        artifact_content_review_decision = "not_reviewable_insufficient_truth"
        artifact_content_review_block_reason = "insufficient_truth"
        fresh_evidence_validity_decision_ready = False
        fresh_evidence_validity_status = "blocked_insufficient_truth"
        fresh_evidence_validity_block_reason = "insufficient_truth"
